// Change phone number and "Export Telegram data" (R-Y212): the routes of
// the POSTS table in routes-telegram.js, each validated strictly before the
// account is asked. The export only reads from Telegram (through a takeout
// session); its files are written on this computer, in a folder the server
// chooses under the store directory's `exports`.
//
// Its routes:
//   POST /api/telegram/phone-change-send {phone} -> { ok, phoneCodeHash,
//                       length, timeout } the code goes to the new number;
//                       or { ok: false, code } (occupied, phone-invalid,
//                       banned, flood, send-failed, fresh)
//   POST /api/telegram/phone-change-confirm {phone, phoneCodeHash, code}
//                       -> { ok, phone }; or { ok: false, code }
//                       (code-invalid, code-expired, occupied, flood, …)
//   POST /api/telegram/data-export-start {info?, contacts?, kinds:
//                       {personal, bots, privateGroups, privateChannels,
//                       publicChats: boolean}, media?, sizeLimitMb (1..4000,
//                       default 8), from?, to? (YYYY-MM-DD), formats:
//                       ['html'|'json']} -> { ok, job }; or { ok: false,
//                       code: 'takeout-delay', seconds } when Telegram will
//                       allow the export later (TAKEOUT_INIT_DELAY_X),
//                       bad-request, busy
//   POST /api/telegram/data-export-status -> { ok, job } phase, chats done
//                       / total, messages, files, state
//   POST /api/telegram/data-export-cancel -> { ok, job } stops it; what was
//                       written stays
//   POST /api/telegram/data-export-reveal -> { ok } opens the finished
//                       export's folder in the file manager

import { CODE, PHONE } from '../sources/telegram-phone-change.js';
import { parseDataExport } from '../sources/telegram-account-data.js';

import { bad, plain } from './routes-telegram-export.js';

export const ACCOUNT_DATA_POSTS = {
  'phone-change-send': async (account, body) =>
    PHONE.test(String(body.phone ?? '')) &&
    typeof account.phoneChangeSend === 'function'
      ? [200, await account.phoneChangeSend({ phone: String(body.phone) })]
      : bad('phone required'),
  'phone-change-confirm': async (account, body) =>
    PHONE.test(String(body.phone ?? '')) &&
    CODE.test(String(body.code ?? '')) &&
    /^[\w-]{1,128}$/.test(String(body.phoneCodeHash ?? '')) &&
    typeof account.phoneChangeConfirm === 'function'
      ? [
          200,
          await account.phoneChangeConfirm({
            phone: String(body.phone),
            code: String(body.code),
            phoneCodeHash: String(body.phoneCodeHash),
          }),
        ]
      : bad('phone, code and hash required'),
  'data-export-start': async (account, body) =>
    parseDataExport(body).ok && typeof account.dataExportStart === 'function'
      ? [200, await account.dataExportStart(body)]
      : bad('kinds and formats required'),
  'data-export-status': plain('dataExportStatus'),
  'data-export-cancel': plain('dataExportCancel'),
  'data-export-reveal': plain('dataExportReveal'),
};

// Archive settings, logged-in websites and pinned Saved Messages chats
// (R-Y174): the routes of the POSTS table in routes-telegram.js, each
// validated strictly before the account is asked.
//
// Its routes:
//   POST /api/telegram/archive-settings -> { ok, settings: { archiveAndMute,
//                       keepUnmuted, keepFolders, hideReadMarks,
//                       requirePremium } }
//   POST /api/telegram/archive-settings-set {archiveAndMute, keepUnmuted,
//                       keepFolders, hideReadMarks, requirePremium} (all
//                       booleans) -> { ok, settings } the other fields of
//                       Telegram's settings are kept
//   POST /api/telegram/web-sessions     -> { ok, sessions: [{ hash, domain,
//                       bot, browser, platform, ip, region, created,
//                       active }] } websites logged in with Telegram
//   POST /api/telegram/web-session-reset {hash} -> { ok } one disconnected
//   POST /api/telegram/web-sessions-reset-all -> { ok } all disconnected
//   POST /api/telegram/saved-pin {peer, pinned} -> { ok, pinned } a chat of
//                       Saved Messages pinned or unpinned
//   POST /api/telegram/saved-reorder {peers: [id, …]} -> { ok } the pinned
//                       chats of Saved Messages in this order, the first on
//                       top (R-Y197); each id once, up to 100

import {
  ARCHIVE_FIELDS,
  MAX_PINNED,
} from '../sources/telegram-account-extras.js';

const bad = (error) => [400, { error, code: 'bad-request' }];
const NOT_SUPPORTED = [400, { error: 'not supported', code: 'bad-request' }];

const run = async (account, method, arg) =>
  typeof account[method] === 'function'
    ? [200, await account[method](arg)]
    : NOT_SUPPORTED;

const validSettings = (b) =>
  Object.keys(ARCHIVE_FIELDS).every((key) => typeof b[key] === 'boolean');

export const ACCOUNT_EXTRAS_POSTS = {
  'archive-settings': (account) => run(account, 'archiveSettings'),
  'archive-settings-set': async (account, body) =>
    validSettings(body)
      ? run(
          account,
          'setArchiveSettings',
          Object.fromEntries(
            Object.keys(ARCHIVE_FIELDS).map((key) => [key, body[key]])
          )
        )
      : bad('five booleans required'),
  'web-sessions': (account) => run(account, 'webSessions'),
  'web-session-reset': async (account, body) =>
    /^-?\d{1,20}$/.test(String(body.hash ?? ''))
      ? run(account, 'webSessionReset', { hash: String(body.hash) })
      : bad('hash required'),
  'web-sessions-reset-all': (account) => run(account, 'webSessionsResetAll'),
  'saved-pin': async (account, body) =>
    /^-?\d{1,20}$/.test(String(body.peer ?? '')) &&
    typeof body.pinned === 'boolean'
      ? run(account, 'savedPin', {
          peer: String(body.peer),
          pinned: body.pinned,
        })
      : bad('peer and pinned required'),
  'saved-reorder': async (account, body) =>
    Array.isArray(body.peers) &&
    body.peers.length > 0 &&
    body.peers.length <= MAX_PINNED &&
    body.peers.every((p) => typeof p === 'string' && /^-?\d{1,20}$/.test(p)) &&
    new Set(body.peers).size === body.peers.length
      ? run(account, 'savedReorder', { peers: body.peers })
      : bad('a list of peers required'),
};

// More than one Telegram account (R-Y198; learned, never copied): the
// routes of the POSTS table in routes-telegram.js, plus the one place
// that picks the account a request is for. A request without `account`
// (every request the page sends today) is account 1, the existing single
// account, exactly as before. An extra account (2..5) answers only the
// routes in EXTRA_ROUTES; any other route asked for it is refused with
// `unsupported-account`, never run against account 1 by mistake.
//
// Its routes:
//   POST /api/telegram/accounts {} -> { ok, accounts: [{ account, name,
//                       username?, id?, current? }], limit, premium, canAdd,
//                       next } the signed-in accounts (1 first), how many
//                       are allowed (3, 5 with Premium), and the slot the
//                       next "Add account" signs in to (null: at the limit)
//   POST /api/telegram/accounts-unread {all?} -> { ok, unread: [{ account,
//                       unread }] } the other accounts' unread counts: from
//                       the account's own store while it runs (R-Y202), else
//                       read live (nothing stored); `all: true` adds
//                       account 1's count, for a page that uses another
//   GET  /api/telegram/accounts-events -> Server-Sent Events: `event:
//                       message` for each new incoming message of any
//                       account (R-Y202), { account, id, chat, chatName,
//                       sender, body, at, muted }, so the page can notify
//                       for the accounts it is not showing
//   POST /api/telegram/accounts-dialogs {account} -> { ok, dialogs: [{
//                       chat, name, text, date, unread }], unread } an
//                       extra account's chat list (from its store while it
//                       runs, else read live)
//   POST /api/telegram/accounts-logout {account} -> { ok, removed } an
//                       extra account (2..5) logged out: its service stops,
//                       the session ends on Telegram's side, only its own
//                       namespaced keys and its own store directory
//                       (accounts/telegram-N) are removed; account 1 is
//                       refused
//
// R-Y202: an extra account is also fully usable. Every other route of
// /api/telegram/*, and the link, chat, events, send and message routes,
// answer for it when the request names it (`telegramAccount=N`, see
// ./account-scope.js); this file's routes are account-global.
//
// The sign-in of an extra account is the existing login flow with
// `account` in its bodies (routes-auto-import.js).

import { classifyOrigin } from './cors.js';
import { json } from './util.js';
import { unreadOfStore } from './telegram-extras.js';
import {
  accountSlot,
  extraSlots,
  limitFor,
  nextFreeSlot,
  profileId,
  removeExtraAccount,
} from '../sources/telegram-accounts.js';

/** Routes of this file: they read `body.account` themselves. */
const OWN = new Set(['accounts', 'accounts-unread', 'accounts-logout']);
/** The only routes an extra account answers. */
const EXTRA_ROUTES = new Set(['accounts-dialogs']);

const MAX_BUFFERED = 1024 * 1024;
const BAD = [400, { error: 'bad account', code: 'bad-request' }];
const NO_ACCOUNT = [404, { error: 'no such account', code: 'no-account' }];
const UNSUPPORTED = [
  400,
  { error: 'not available for this account', code: 'unsupported-account' },
];

/**
 * Which account a POST is for: `{ account }` to run it on, or `{ error }`
 * as the route's `[status, body]`. `account` is the existing single one.
 */
export const resolveAccount = async (ctx, account, name, body = {}) => {
  if (OWN.has(name)) {
    return { account };
  }
  const slot = accountSlot(body.account);
  if (slot === null) {
    return { error: BAD };
  }
  if (slot === 1) {
    return name === 'accounts-dialogs' ? { error: UNSUPPORTED } : { account };
  }
  if (!EXTRA_ROUTES.has(name)) {
    return { error: UNSUPPORTED };
  }
  // A running account answers from its own store (a second connection
  // with the same session would be refused by Telegram).
  const running = ctx?.telegramExtras?.get(slot);
  if (running) {
    return { account: { dialogs: () => storeDialogs(running) } };
  }
  const extra = await ctx?.telegramAccounts?.resolve(slot);
  return extra ? { account: extra } : { error: NO_ACCOUNT };
};

// A running account's chat list as the preview shows it, from its store.
const storeDialogs = async (entry) => {
  const heads = await entry.chatIndex.heads();
  const rows = [];
  for (const link of heads) {
    const read = await entry.own.get(`read:telegram:${link.chat}`);
    rows.push({
      chat: String(link.chat),
      name: link.chatName ?? link.senderName ?? null,
      text: String(link.body ?? ''),
      date: Date.parse(link.timestamp ?? '') || null,
      unread: Number(read?.unreadCount ?? 0),
      muted: Number(read?.muteUntil ?? 0) * 1000 > Date.now(),
    });
  }
  rows.sort((a, b) => (b.date ?? 0) - (a.date ?? 0));
  return {
    ok: true,
    at: Date.now(),
    dialogs: rows,
    unread: await unreadOfStore(entry.own),
  };
};

const firstAccount = async (account) => {
  const me =
    typeof account.accountMe === 'function'
      ? await account.accountMe().catch(() => null)
      : null;
  return {
    account: 1,
    current: true,
    id: me?.ok ? (me.id ?? null) : null,
    name: me?.ok ? (me.name ?? null) : null,
    username: me?.ok ? (me.username ?? null) : null,
    premium: Boolean(me?.ok && me.premium),
  };
};

const listAccounts = async (account, body, ctx) => {
  const store = ctx.telegramStore;
  if (!store) {
    return [501, { error: 'accounts not available', code: 'unsupported' }];
  }
  const first = await firstAccount(account);
  const extras = [];
  for (const slot of await extraSlots(store)) {
    const profile = await store.get(profileId(slot));
    extras.push({
      account: slot,
      name: profile?.name ?? null,
      username: profile?.username ?? null,
      ...(profile?.accountId ? { id: profile.accountId } : {}),
    });
  }
  const limit = limitFor(first.premium);
  const { premium, ...head } = first;
  const next = await nextFreeSlot(store, limit);
  return [
    200,
    {
      ok: true,
      accounts: [head, ...extras],
      limit,
      premium,
      canAdd: next !== null,
      next,
    },
  ];
};

const unreadOfOthers = async (account, body, ctx) => {
  const store = ctx.telegramStore;
  const unread = [];
  if (body?.all === true && ctx.telegramExtras) {
    unread.push({ account: 1, unread: await ctx.telegramExtras.homeUnread() });
  }
  for (const slot of store ? await extraSlots(store) : []) {
    // A running account's count is its own store's; only one that is not
    // running is asked from Telegram.
    const own = await ctx.telegramExtras?.unread(slot);
    if (own !== null && own !== undefined) {
      unread.push({ account: slot, unread: own });
      continue;
    }
    const answer = await ctx.telegramAccounts?.dialogs(slot);
    unread.push({ account: slot, unread: answer?.ok ? answer.unread : null });
  }
  return [200, { ok: true, unread }];
};

const logout = async (account, body, ctx) => {
  const slot = accountSlot(body.account);
  const store = ctx.telegramStore;
  if (slot === null || slot < 2 || !store) {
    return BAD;
  }
  // Its service stops first (one connection per session), then the
  // session ends on Telegram's side, then its keys and its own store
  // directory go: nothing of account 1 or another account is touched.
  await ctx.telegramExtras?.stopSlot(slot);
  await ctx.telegramAccounts?.revoke(slot);
  const removed = await removeExtraAccount(store, slot);
  await ctx.telegramExtras?.remove(slot);
  return [200, { ok: true, removed }];
};

// The notification stream (R-Y202): a new incoming message of any
// account, so the page can notify for the accounts it is not showing.
const FRAME = (data) => `event: message\ndata: ${JSON.stringify(data)}\n\n`;
const accountEvents = (account, req, res, ctx) => {
  if (classifyOrigin(req, ctx.allowOrigins ?? []) === 'denied') {
    return json(res, 403, { error: 'origin not allowed' }) ?? true;
  }
  if (!ctx.telegramExtras || ctx.passcode?.locked()) {
    return json(res, 501, { error: 'accounts not available' }) ?? true;
  }
  res.writeHead(200, {
    'content-type': 'text/event-stream; charset=utf-8',
    'cache-control': 'no-cache, no-transform',
    ...(req.httpVersionMajor === 2 ? {} : { connection: 'keep-alive' }),
    'x-accel-buffering': 'no',
  });
  res.write('retry: 5000\n\n: open\n\n');
  const stop = ctx.telegramExtras.watch((event) => {
    if (res.writableLength < MAX_BUFFERED) {
      res.write(FRAME(event));
    }
  });
  const ping = globalThis.setInterval(() => res.write(': ping\n\n'), 25_000);
  ping.unref?.();
  const close = () => {
    globalThis.clearInterval(ping);
    stop();
  };
  req.on('close', close);
  res.on('error', close);
  return true;
};

export const ACCOUNTS_GETS = { 'accounts-events': accountEvents };

export const ACCOUNTS_POSTS = {
  accounts: listAccounts,
  'accounts-unread': unreadOfOthers,
  'accounts-logout': logout,
  'accounts-dialogs': async (account) => [200, await account.dialogs()],
};

// Moderation, ownership and left channels (R-Y200): the routes of the POSTS
// table in routes-telegram.js, each validated strictly before the account
// is asked. The sources validate again; this keeps junk off the account.
//
// Its routes:
//   POST /api/telegram/moderate-user {chat, user, ids?, reportSpam?, ban?,
//                       deleteAll?} -> { ok, deleted } a supergroup's
//                       member reported (needs ids), banned and/or all
//                       their messages deleted (R-Y200)
//   POST /api/telegram/not-spam {chat, msgId} -> { ok } an anti-spam
//                       deletion reported as a false positive (R-Y200)
//   POST /api/telegram/convert-gigagroup {chat, confirm: true} -> { ok } a
//                       supergroup made a broadcast group, no undo (R-Y200)
//   POST /api/telegram/transfer-ownership {chat, user, password} -> { ok }
//                       the chat handed over; the 2-Step Verification
//                       password is checked by SRP, never kept (R-Y200)
//   POST /api/telegram/left-channels {offset?} -> { ok, channels, next } the
//                       channels the user left, read only (R-Y200)

import { moderationBody } from '../sources/telegram-moderation.js';
import { PASSWORD_MAX } from '../sources/telegram-ownership.js';

const CHANNEL = /^-100\d{1,20}$/;
const CHAT = /^-\d{1,20}$/;
const USER = /^\d{1,20}$/;
const MSG = /^\d{1,12}$/;
const OFFSET = /^\d{1,6}$/;

export const invalid = (what) => [400, { error: what, code: 'bad-request' }];

// Calls `method` of the account with `pick(body)` (the body itself unless
// told) when `ok` says it is valid.
export const route =
  (method, what, ok, pick = (body) => body) =>
  async (account, body) =>
    ok(body) && typeof account[method] === 'function'
      ? [200, await account[method](pick(body))]
      : invalid(what);

export const ADMIN_EXTRAS_POSTS = {
  'moderate-user': route(
    'moderateUser',
    'chat, user and what to do required',
    moderationBody
  ),
  'not-spam': route(
    'notSpam',
    'chat and message required',
    (b) => CHANNEL.test(String(b.chat ?? '')) && MSG.test(String(b.msgId ?? ''))
  ),
  'convert-gigagroup': route(
    'convertToGigagroup',
    'chat and confirmation required',
    (b) => CHANNEL.test(String(b.chat ?? '')) && b.confirm === true
  ),
  'transfer-ownership': route(
    'transferOwnership',
    'chat, user and password required',
    (b) =>
      CHAT.test(String(b.chat ?? '')) &&
      USER.test(String(b.user ?? '')) &&
      typeof b.password === 'string' &&
      b.password !== '' &&
      b.password.length <= PASSWORD_MAX
  ),
  'left-channels': route(
    'leftChannels',
    'offset must be a number',
    (b) => b.offset === undefined || OFFSET.test(String(b.offset))
  ),
};

// A group's permissions, slow mode and recent actions (R-Y133): the
// routes of the POSTS table in routes-telegram.js, each validated
// strictly before the account is asked.
//
// Its routes:
//   POST /api/telegram/chat-permissions {chat} -> { ok, rights, slowMode,
//                       canEdit } what members may do (true: allowed)
//   POST /api/telegram/chat-permissions-set {chat, rights} -> { ok } only
//                       the known boolean rights, changed (R-Y133)
//   POST /api/telegram/slow-mode {chat, seconds} -> { ok } seconds 0, 10,
//                       30, 60, 300, 900 or 3600
//   POST /api/telegram/admin-log {chat, maxId?} -> { ok, events, next }

import { RIGHT_KEYS, SLOW_MODES } from '../sources/telegram-admin.js';

const GROUP_CHAT = /^-\d{1,20}$/;

// Rights: only the known keys, each a boolean.
const validRightsBody = (rights) =>
  Boolean(rights) &&
  typeof rights === 'object' &&
  !Array.isArray(rights) &&
  Object.keys(rights).length > 0 &&
  Object.entries(rights).every(
    ([k, v]) => RIGHT_KEYS.includes(k) && typeof v === 'boolean'
  );

export const ADMIN_POSTS = {
  'chat-permissions': async (account, body) =>
    GROUP_CHAT.test(String(body.chat ?? '')) &&
    typeof account.chatPermissions === 'function'
      ? [200, await account.chatPermissions({ chat: body.chat })]
      : [400, { error: 'chat required', code: 'bad-request' }],
  'chat-permissions-set': async (account, body) =>
    GROUP_CHAT.test(String(body.chat ?? '')) &&
    validRightsBody(body.rights) &&
    typeof account.setPermissions === 'function'
      ? [
          200,
          await account.setPermissions({
            chat: body.chat,
            rights: body.rights,
          }),
        ]
      : [400, { error: 'chat and rights required', code: 'bad-request' }],
  'slow-mode': async (account, body) =>
    GROUP_CHAT.test(String(body.chat ?? '')) &&
    SLOW_MODES.includes(body.seconds) &&
    typeof account.setSlowMode === 'function'
      ? [
          200,
          await account.setSlowMode({
            chat: body.chat,
            seconds: body.seconds,
          }),
        ]
      : [400, { error: 'chat and seconds required', code: 'bad-request' }],
  'admin-log': async (account, body) =>
    GROUP_CHAT.test(String(body.chat ?? '')) &&
    (body.maxId === undefined || /^\d{1,20}$/.test(String(body.maxId))) &&
    typeof account.adminLog === 'function'
      ? [
          200,
          await account.adminLog({
            chat: body.chat,
            ...(body.maxId === undefined ? {} : { maxId: String(body.maxId) }),
          }),
        ]
      : [400, { error: 'chat required', code: 'bad-request' }],
};

// The bot and mini-app extras (R-Y194): the routes of the POSTS table in
// routes-telegram.js, each validated strictly before the account is asked.
// All reads; a prepared message is sent by the existing inline-send route.
//
// Its routes:
//   POST /api/telegram/apps-popular {offset?, limit?} -> { ok, apps: [{
//                       chat, name, username, users, mainApp }], next } the
//                       popular mini apps, a page at a time (limit 1..50)
//   POST /api/telegram/bot-similar {chat} -> { ok, bots: [...] } the bots
//                       Telegram recommends beside a bot
//   POST /api/telegram/prepared-message {bot, id} -> { ok, queryId, id,
//                       preview: { type, title, description }, peerTypes,
//                       bot } a message a mini app prepared; it is sent with
//                       inline-send to one chat, on a click
//   POST /api/telegram/collectible-info {kind, value} -> { ok, date, price:
//                       { amount, currency }, crypto: { amount, currency },
//                       url } kind is username | phone

import {
  ID,
  KINDS,
  MAX_PAGE,
  PREPARED_ID,
  collectibleOk,
} from '../sources/telegram-apps.js';

const bad = (error) => [400, { error, code: 'bad-request' }];
const OFFSET = /^[\x21-\x7e]{0,256}$/;

const popularOk = (body) =>
  (body.offset === undefined ||
    (typeof body.offset === 'string' && OFFSET.test(body.offset))) &&
  (body.limit === undefined ||
    (Number.isInteger(body.limit) &&
      body.limit >= 1 &&
      body.limit <= MAX_PAGE));

export const APPS_POSTS = {
  'apps-popular': async (account, body) =>
    popularOk(body) && typeof account.appsPopular === 'function'
      ? [
          200,
          await account.appsPopular({
            ...(body.offset ? { offset: body.offset } : {}),
            ...(body.limit ? { limit: body.limit } : {}),
          }),
        ]
      : bad('a valid page required'),
  'bot-similar': async (account, body) =>
    ID.test(String(body.chat ?? '')) && typeof account.botSimilar === 'function'
      ? [200, await account.botSimilar({ chat: String(body.chat) })]
      : bad('chat required'),
  'prepared-message': async (account, body) =>
    ID.test(String(body.bot ?? '')) &&
    typeof body.id === 'string' &&
    PREPARED_ID.test(body.id) &&
    typeof account.preparedMessage === 'function'
      ? [
          200,
          await account.preparedMessage({ bot: String(body.bot), id: body.id }),
        ]
      : bad('bot and message id required'),
  'collectible-info': async (account, body) =>
    KINDS.includes(body.kind) &&
    collectibleOk(body.kind, body.value) &&
    typeof account.collectibleInfo === 'function'
      ? [
          200,
          await account.collectibleInfo({ kind: body.kind, value: body.value }),
        ]
      : bad('kind and value required'),
};

// Channel boosts (R-Y173): the routes of the POSTS table in
// routes-telegram.js, each validated strictly before the account is asked.
//
// Its routes:
//   POST /api/telegram/boosts-status {chat} -> { ok, level, boosts,
//                       giftBoosts, currentLevelBoosts, nextLevelBoosts,
//                       url, mine } a channel's or supergroup's boost level
//   POST /api/telegram/my-boosts {chat} -> { ok, premium, slots: [{ slot,
//                       chat, title, expires, cooldownUntil }] } the user's
//                       boost slots
//   POST /api/telegram/boost-apply {chat, slot} -> { ok, slots } gives the
//                       chat that slot's boost (a write, on a click only)
//   POST /api/telegram/boosters {chat, offset?} -> { ok, count, boosters,
//                       next } who boosts it (admins), a page at a time

