};

// Inline bots in the message box (R-Y138): the routes of the POSTS table
// in routes-telegram.js, each validated strictly before the account is
// asked.
//
// Its routes:
//   POST /api/telegram/inline-bot {username} -> { ok, bot: { id, username,
//                       name, placeholder } } a bot with inline mode, or
//                       code not-inline / no-bot (R-Y138)
//   POST /api/telegram/inline-results {chat, username, query, offset?}
//                       -> { ok, bot, queryId, gallery, results, next,
//                       switchPm, switchWebview } a bot's answers, a page
//   POST /api/telegram/inline-send {chat, queryId, id, replyTo?, clientId?,
//                       sendAs?} -> { ok } one of those answers sent (as
//                       the picked identity; location and contact sends
//                       take `sendAs` too) (R-Y147)
//   POST /api/telegram/inline-start-bot {username, startParam}
//                       -> { ok, chat } "switch to PM": /start with the
//                       parameter that bot's answer offered (R-Y147)

import {
  MAX_OFFSET,
  MAX_QUERY,
  MAX_RESULT_ID,
  NAME,
} from '../sources/telegram-inline-bots.js';
import { paidField, validSendAs } from '../sources/telegram-send-as-client.js';

const START_PARAM = /^[A-Za-z0-9_-]{0,64}$/;
const NUMBER = /^-?\d{1,20}$/;
const bad = (error) => [400, { error, code: 'bad-request' }];

const validChat = (chat) => typeof chat === 'string' && NUMBER.test(chat);
const validName = (name) => typeof name === 'string' && NAME.test(name);
// Words and an offset: text, no control characters, within the limits.
const plain = (value, max) =>
  typeof value === 'string' &&
  value.length <= max &&
  // eslint-disable-next-line no-control-regex
  !/[\u0000-\u001f\u007f]/.test(value);

const validSend = (body, replyTo) =>
  validChat(body.chat) &&
  validSendAs(body.sendAs) &&
  typeof body.queryId === 'string' &&
  NUMBER.test(body.queryId) &&
  typeof body.id === 'string' &&
  body.id.length > 0 &&
  plain(body.id, MAX_RESULT_ID) &&
  (replyTo === null || (Number.isInteger(replyTo) && replyTo > 0));

export const INLINE_POSTS = {
  'inline-bot': async (account, body) =>
    validName(body.username) && typeof account.inlineBot === 'function'
      ? [200, await account.inlineBot({ username: body.username })]
      : bad('username required'),
  'inline-results': async (account, body) =>
    validChat(body.chat) &&
    validName(body.username) &&
    plain(body.query ?? '', MAX_QUERY) &&
    plain(body.offset ?? '', MAX_OFFSET) &&
    typeof account.inlineResults === 'function'
      ? [
          200,
          await account.inlineResults({
            chat: body.chat,
            username: body.username,
            query: body.query ?? '',
            offset: body.offset ?? '',
          }),
        ]
      : bad('chat, username and query required'),
  'inline-send': async (account, body) => {
    const replyTo = body.replyTo === undefined ? null : Number(body.replyTo);
    if (!validSend(body, replyTo) || typeof account.inlineSend !== 'function') {
      return bad('chat, queryId and id required');
    }
    return [
      200,
      await account.inlineSend({
        chat: body.chat,
        queryId: body.queryId,
        id: body.id,
        replyTo,
        clientId: typeof body.clientId === 'string' ? body.clientId : null,
        ...(body.sendAs ? { sendAs: body.sendAs } : {}),
        ...paidField(body),
      }),
    ];
  },
  // "Switch to PM": /start with the bot's own start parameter (R-Y147).
  'inline-start-bot': async (account, body) =>
    validName(body.username) &&
    typeof body.startParam === 'string' &&
    START_PARAM.test(body.startParam) &&
    typeof account.inlineStartBot === 'function'
      ? [
          200,
          await account.inlineStartBot({
            username: body.username,
            startParam: body.startParam,
          }),
        ]
      : bad('username and startParam required'),
};

// Instant View (R-Y205): the routes of the POSTS and GETS tables in
// routes-telegram.js, validated strictly before the account is asked.
//
// Its routes:
//   POST /api/telegram/instant-view {url, hash?} -> { ok, available,
//        siteName?, title?, page? } the cached page of a link as a safe
//        tree (R-Y205); a t.me/iv?url=… link names the page it wraps;
//        errors come as codes (not-found, unreachable, bad-url, flood)
//   GET  /api/telegram/instant-view-media?kind=photo|document&id= -> a
//        picture of the page, downloaded through Telegram; `full=1` (a
//        document): the whole file by byte range for a video or audio,
//        `download=1` saved under its name (R-Y224; 400 for `full` on a
//        photo, 413 when over 64 MB)

import { json } from './util.js';
import { fromApp, answerFile } from './routes-telegram-files.js';
import { KINDS, targetOf } from '../sources/telegram-instant-view.js';

const ID = /^\d{1,20}$/;

const validHash = (hash) =>
  hash === undefined ||
  (Number.isInteger(hash) && hash >= 0 && hash <= 2 ** 31 - 1);

// The picture asked for, or null when the query is malformed.
const pictureQuery = (query) => {
  const kind = query.get('kind') ?? '';
  const id = query.get('id') ?? '';
  const full = query.get('full') === '1';
  return KINDS.includes(kind) && ID.test(id) && (!full || kind === 'document')
    ? { kind, id, full }
    : null;
};

// GET /api/telegram/instant-view-media?kind=&id= -> the picture, only for
// the app's own pages.
const handleMedia = async (account, req, res, ctx) => {
  if (!fromApp(req, ctx?.allowOrigins)) {
    return json(res, 403, { error: 'pictures load only in the app' }) ?? true;
  }
  if (typeof account.instantViewFile !== 'function') {
    return json(res, 501, { error: 'instant view not available' }) ?? true;
  }
  const query = new URL(req.url, 'http://local').searchParams;
  const asked = pictureQuery(query);
  if (!asked) {
    return json(res, 400, { error: 'bad picture' }) ?? true;
  }
  const result = await account.instantViewFile(asked);
  if (asked.full) {
    return answerFile(req, res, result, query, true);
  }
  if (!result?.buffer) {
    return json(res, 404, { error: 'no picture' }) ?? true;
  }
  res.writeHead(200, {
    'content-type': result.mimeType || 'image/jpeg',
    'content-length': result.buffer.length,
    'cache-control': 'private, max-age=3600',
    'x-content-type-options': 'nosniff',
  });
  res.end(result.buffer);
  return true;
};

export const INSTANT_VIEW_GETS = { 'instant-view-media': handleMedia };

export const INSTANT_VIEW_POSTS = {
  'instant-view': async (account, body) =>
    typeof body.url === 'string' &&
    targetOf(body.url) &&
    validHash(body.hash) &&
    typeof account.instantView === 'function'
      ? [
          200,
          await account.instantView({
            url: body.url,
            ...(body.hash === undefined ? {} : { hash: body.hash }),
          }),
        ]
      : [400, { error: 'url required', code: 'bad-request' }],
};

// A group's or channel's invite links and join requests (R-Y152): the
// routes of the POSTS table in routes-telegram.js, each validated
// strictly before the account is asked.
//
// Its routes:
//   POST /api/telegram/invite-links {chat, revoked?, offsetLink?,
//                  offsetDate?} -> { ok, primary, links, count, next }
//                                         the user's invite links (R-Y152)
//   POST /api/telegram/invite-create {chat, title?, expireDate?, usageLimit?,
//                  requestNeeded?} -> { ok, invite } (expireDate: unix s)
//   POST /api/telegram/invite-edit {chat, link, revoked?, title?, expireDate?,
//                  usageLimit?, requestNeeded?} -> { ok, invite }
//   POST /api/telegram/invite-delete {chat, link} -> { ok } a revoked link
//   POST /api/telegram/invite-delete-revoked {chat} -> { ok } all of them
//   POST /api/telegram/invite-importers {chat, link? | requested: true,
//                  offset?} -> { ok, importers, count, next } who joined
//                                         through a link, or who asks to join
//   POST /api/telegram/join-request-hide {chat, user, accessHash?, approved}
//                                      -> { ok } one request decided
//   POST /api/telegram/join-requests-hide-all {chat, approved, link?}
//                                      -> { ok } every request decided

import {
  validLink,
  validOffset,
  validSettings,
} from '../sources/telegram-invite-links.js';

const GROUP_CHAT = /^-\d{1,20}$/;
const USER = /^\d{1,20}$/;
const BAD = [400, { error: 'bad request', code: 'bad-request' }];

const chatOk = (body) => GROUP_CHAT.test(String(body.chat ?? ''));
const optional = (value, test) => value === undefined || test(value);
const isBool = (value) => typeof value === 'boolean';

// Runs `method` of the account on `args` when `ok`, else answers 400.
const route = (method, ok, args) => async (account, body) =>
  ok(body) && typeof account[method] === 'function'
    ? [200, await account[method](args(body))]
    : BAD;

// The link settings a body carries, as given.
const settings = (body) =>
  Object.fromEntries(
    ['title', 'expireDate', 'usageLimit', 'requestNeeded']
      .filter((key) => body[key] !== undefined)
      .map((key) => [key, body[key]])
  );

export const INVITE_LINKS_POSTS = {
  'invite-links': route(
    'inviteLinks',
    (b) =>
      chatOk(b) &&
      optional(b.revoked, isBool) &&
      optional(b.offsetLink, validLink) &&
      optional(b.offsetDate, Number.isInteger),
    (b) => ({
      chat: b.chat,
      ...(b.revoked ? { revoked: true } : {}),
      ...(b.offsetLink === undefined
        ? {}
        : { offsetLink: b.offsetLink, offsetDate: b.offsetDate ?? 0 }),
    })
  ),
  'invite-create': route(
    'inviteCreate',
    (b) => chatOk(b) && validSettings(b),
    (b) => ({ chat: b.chat, ...settings(b) })
  ),
  'invite-edit': route(
    'inviteEdit',
    (b) =>
      chatOk(b) &&
      validLink(b.link) &&
