// Sharing a place and a contact (R-Y142): the routes of the POSTS table in
// routes-telegram.js, each validated strictly before the account is asked.
//
// Its routes:
//   POST /api/telegram/send-location {chat, lat, lon, accuracy?, live?,
//                       replyTo?, silent?, scheduleDate?, clientId?} -> { ok }
//                       a place (latitude -90..90, longitude -180..180,
//                       accuracy 0..1500 m) or, with live 900, 3600 or
//                       28800 seconds, a live location (R-Y142)
//   POST /api/telegram/stop-live-location {chat, id} -> { ok } our live
//                       location message stops
//   POST /api/telegram/send-contact {chat, contact | firstName, lastName?,
//                       phone, replyTo?, silent?, scheduleDate?, clientId?}
//                       -> { ok } one of our contacts by id (its phone read
//                       server-side) or a typed name and phone
//   POST /api/telegram/update-live-location {chat, id, lat, lon, accuracy?,
//                       heading?, proximity?} -> { ok } our live location moved
//                       (R-Y147); `proximity` (metres, 1..100000) asks to be
//                       told when the other person comes this near (R-Y197)

import { paidField, validSendAs } from '../sources/telegram-send-as-client.js';
import { validSchedule } from '../sources/telegram-scheduled.js';
import {
  LIVE_PERIODS,
  MAX_ACCURACY,
  MAX_PROXIMITY,
  cleanPhone,
  validPoint,
} from '../sources/telegram-share-media.js';

const CHAT = /^-?\d{1,20}$/;
const USER = /^\d{1,20}$/;
const NAME_MAX = 64;

const optionalOk = (body) =>
  (body.silent === undefined || typeof body.silent === 'boolean') &&
  (body.scheduleDate === undefined || validSchedule(body.scheduleDate)) &&
  (body.clientId === undefined || typeof body.clientId === 'string') &&
  validSendAs(body.sendAs) &&
  (body.replyTo === undefined ||
    (Number.isInteger(body.replyTo) && body.replyTo > 0));

// Without sound, at a time, an answer to, a draft's id.
const extrasOf = (body) => ({
  ...(body.silent === true ? { silent: true } : {}),
  ...(body.scheduleDate !== undefined
    ? { scheduleDate: body.scheduleDate }
    : {}),
  ...(body.replyTo ? { replyTo: body.replyTo } : {}),
  ...(body.clientId ? { clientId: body.clientId } : {}),
  ...(body.sendAs ? { sendAs: body.sendAs } : {}),
  ...paidField(body),
});

const validPlace = (b) =>
  CHAT.test(String(b.chat ?? '')) &&
  typeof b.lat === 'number' &&
  typeof b.lon === 'number' &&
  validPoint(b.lat, b.lon) !== null &&
  (b.accuracy === undefined ||
    (Number.isInteger(b.accuracy) &&
      b.accuracy >= 0 &&
      b.accuracy <= MAX_ACCURACY)) &&
  (b.live === undefined || LIVE_PERIODS.includes(b.live)) &&
  optionalOk(b);

const nameOk = (value, required) =>
  typeof value === 'string' &&
  value.length <= NAME_MAX &&
  (!required || value.trim() !== '');

// A picked contact (its id) or a typed one (names and a phone).
const validContact = (b) =>
  CHAT.test(String(b.chat ?? '')) &&
  optionalOk(b) &&
  (b.contact !== undefined
    ? USER.test(String(b.contact)) &&
      b.phone === undefined &&
      b.firstName === undefined
    : nameOk(b.firstName, true) &&
      (b.lastName === undefined || nameOk(b.lastName, false)) &&
      cleanPhone(b.phone) !== null);

// The moving point of a live place: a place with the message's id.
const validMove = (b) =>
  validPlace({ ...b, live: undefined }) &&
  Number.isInteger(b.id) &&
  b.id > 0 &&
  (b.proximity === undefined ||
    (Number.isInteger(b.proximity) &&
      b.proximity > 0 &&
      b.proximity <= MAX_PROXIMITY)) &&
  (b.heading === undefined ||
    (typeof b.heading === 'number' && Number.isFinite(b.heading)));

const refuse = (what) => [400, { error: what, code: 'bad-request' }];

export const SHARE_POSTS = {
  'send-location': async (account, body) =>
    validPlace(body) && typeof account.sendLocation === 'function'
      ? [
          200,
          await account.sendLocation({
            chat: String(body.chat),
            lat: body.lat,
            lon: body.lon,
            ...(body.accuracy ? { accuracy: body.accuracy } : {}),
            ...(body.live ? { live: body.live } : {}),
            ...extrasOf(body),
          }),
        ]
      : refuse('a valid place required'),
  'stop-live-location': async (account, body) =>
    CHAT.test(String(body.chat ?? '')) &&
    Number.isInteger(body.id) &&
    body.id > 0 &&
    typeof account.stopLiveLocation === 'function'
      ? [
          200,
          await account.stopLiveLocation({
            chat: String(body.chat),
            id: body.id,
          }),
        ]
      : refuse('chat and id required'),
  // The moving point of our live location (R-Y147).
  'update-live-location': async (account, body) =>
    validMove(body) && typeof account.updateLiveLocation === 'function'
      ? [
          200,
          await account.updateLiveLocation({
            chat: String(body.chat),
            id: body.id,
            lat: body.lat,
            lon: body.lon,
            ...(body.accuracy ? { accuracy: body.accuracy } : {}),
            ...(body.heading === undefined ? {} : { heading: body.heading }),
            ...(body.proximity ? { proximity: body.proximity } : {}),
          }),
        ]
      : refuse('chat, id and a valid place required'),
  'send-contact': async (account, body) =>
    validContact(body) && typeof account.sendContact === 'function'
      ? [
          200,
          await account.sendContact({
            chat: String(body.chat),
            ...(body.contact === undefined
              ? {
                  firstName: body.firstName.trim(),
                  lastName: (body.lastName ?? '').trim(),
                  phone: body.phone,
                }
              : { contact: String(body.contact) }),
            ...extrasOf(body),
          }),
        ]
      : refuse('a contact required'),
};

// Telegram Stars (R-Y176): the routes of the POSTS table in
// routes-telegram.js, each validated strictly before the account is asked.
//
// Its routes:
//   POST /api/telegram/stars-status {} -> { ok, balance } the user's Stars
//   POST /api/telegram/stars-history {filter?, offset?} -> { ok, balance,
//                       transactions, next } the history (filter all, in
//                       or out), a page at a time
//   POST /api/telegram/star-gifts {chat, offset?} -> { ok, count, mine,
//                       gifts, next } a person's gifts on their profile
//   POST /api/telegram/star-gift-save {chat, msgId, unsave} -> { ok,
//                       hidden } hides a gift from the profile or shows it
//                       (a write, on a click only)
//   POST /api/telegram/paid-reaction {chat, id, count} -> { ok, sent }
//                       sends Stars as a paid reaction (a write, on Send)
//   POST /api/telegram/paid-media-unlock {chat, id, stars} -> { ok, paid }
//                       pays for a message's paid media (a write, on the
//                       confirmation only; refused if the price changed)

const CHAT = /^-?\d{1,20}$/;
const USER = /^\d{1,20}$/;
const bad = (error) => [400, { error, code: 'bad-request' }];
const whole = (n, min, max = Infinity) =>
  Number.isInteger(n) && n >= min && n <= max;
const paged = (body) =>
  body.offset === undefined ||
  (typeof body.offset === 'string' && body.offset.length <= 200);

const route = (method, valid, error) => async (account, body) =>
  valid(body) && typeof account[method] === 'function'
    ? [200, await account[method](body)]
    : bad(error);

export const STARS_POSTS = {
  'stars-status': route('starsStatus', () => true, 'bad request'),
  'stars-history': route(
    'starsHistory',
    (b) =>
      (b.filter === undefined || ['all', 'in', 'out'].includes(b.filter)) &&
      paged(b),
    'a filter (all, in, out) and an offset required'
  ),
  'star-gifts': route(
    'starGifts',
    (b) => USER.test(String(b.chat ?? '')) && paged(b),
    'a person required'
  ),
  'star-gift-save': route(
    'starGiftSave',
    (b) =>
      USER.test(String(b.chat ?? '')) &&
      whole(b.msgId, 1) &&
      typeof b.unsave === 'boolean',
    'a person, a gift message and unsave required'
  ),
  'paid-reaction': route(
    'paidReaction',
    (b) =>
      CHAT.test(String(b.chat ?? '')) &&
      whole(b.id, 1) &&
      whole(b.count, 1, 2500),
    'a chat, a message and 1 to 2500 Stars required'
  ),
  'paid-media-unlock': route(
    'paidMediaUnlock',
    (b) =>
      CHAT.test(String(b.chat ?? '')) && whole(b.id, 1) && whole(b.stars, 1),
    'a chat, a message and its price required'
  ),
};

