// Story interactions (R-Y148): the routes of the POSTS table in
// routes-telegram.js, each validated strictly before the account is asked.
//
// Its routes:
//   POST /api/telegram/story-reply {chat, id, text} -> { ok } a private
//                       reply to a story (R-Y148)
//   POST /api/telegram/story-react {chat, id, reaction} -> { ok, reaction }
//                       an emoji reaction; '' takes it back
//   POST /api/telegram/story-views {chat, id, offset?} -> { ok, count,
//                       viewsCount, reactionsCount, views, next } the
//                       viewers of one's own story, 50 a page
//                       Also q?, justContacts?, reactionsFirst?,
//                       forwardsFirst? (search and order, R-Y199); each
//                       entry has a kind: view, forward or repost
//   POST /api/telegram/story-delete {chat, id} -> { ok } one's own story
//   POST /api/telegram/stories-hide {chat, hidden} -> { ok, hidden } a
//                       peer's stories to or from the hidden list

const CHAT = /^-?\d{1,20}$/;
// The viewers list's switches (R-Y199).
const VIEW_FLAGS = ['justContacts', 'reactionsFirst', 'forwardsFirst'];
const OFFSET = /^[A-Za-z0-9+/=_.-]{0,256}$/;

const bad = (error) => [400, { error, code: 'bad-request' }];

const storyOf = (body) =>
  CHAT.test(String(body.chat ?? '')) && Number.isInteger(body.id) && body.id > 0
    ? { chat: String(body.chat), id: body.id }
    : null;

// A route that asks `account[method]` with the story and `extra(body)`
// (null when the body is wrong).
const storyRoute =
  (method, what, extra = () => ({})) =>
  async (account, body) => {
    const story = storyOf(body);
    const more = story && extra(body);
    return story && more && typeof account[method] === 'function'
      ? [200, await account[method]({ ...story, ...more })]
      : bad(what);
  };

export const STORY_ACTION_POSTS = {
  'story-reply': storyRoute(
    'storyReply',
    'chat, id and text required',
    (body) =>
      typeof body.text === 'string' &&
      body.text.trim() &&
      body.text.length <= 4096
        ? { text: body.text }
        : null
  ),
  'story-react': storyRoute(
    'storyReact',
    'chat, id and reaction required',
    (body) =>
      typeof body.reaction === 'string' && body.reaction.length <= 24
        ? { reaction: body.reaction }
        : null
  ),
  'story-views': storyRoute('storyViews', 'chat and id required', (body) =>
    (body.offset === undefined ||
      (typeof body.offset === 'string' && OFFSET.test(body.offset))) &&
    (body.q === undefined ||
      (typeof body.q === 'string' && body.q.length <= 128)) &&
    VIEW_FLAGS.every(
      (flag) => body[flag] === undefined || typeof body[flag] === 'boolean'
    )
      ? {
          offset: body.offset ?? '',
          ...(body.q ? { q: body.q } : {}),
          ...Object.fromEntries(
            VIEW_FLAGS.filter((flag) => body[flag] === true).map((flag) => [
              flag,
              true,
            ])
          ),
        }
      : null
  ),
  'story-delete': storyRoute('storyDelete', 'chat and id required'),
  'stories-hide': async (account, body) =>
    CHAT.test(String(body.chat ?? '')) &&
    typeof body.hidden === 'boolean' &&
    typeof account.storiesHide === 'function'
      ? [
          200,
          await account.storiesHide({
            chat: String(body.chat),
            hidden: body.hidden,
          }),
        ]
      : bad('chat and hidden required'),
};

// The rest of the story features (R-Y199): the routes of the POSTS table
// in routes-telegram.js, each validated strictly before the account is
// asked.
//
// Its routes:
//   POST /api/telegram/story-stealth {past, future} -> { ok, stealth:
//                       { activeUntil, cooldownUntil } | null } stealth
//                       mode (Premium); at least one flag is true
//   POST /api/telegram/story-reactions {chat, id, offset?, reaction?,
//                       forwardsFirst?} -> { ok, count, views, next } the
//                       "Reactions" view of one's own story's viewers
//   POST /api/telegram/story-report {chat, id, option?, message?} -> { ok,
//                       result: choose (title, options) | comment
//                       (optional, option) | reported } as peer-report
//   POST /api/telegram/stories-views {chat, ids} -> { ok, stories: [{ id,
//                       views, reactions, forwards }] } fresh counters of
//                       one's own stories (1 to 100 ids)

const CHAT = /^-?\d{1,20}$/;
const OFFSET = /^[A-Za-z0-9+/=_.-]{0,256}$/;
const BASE64 = /^[A-Za-z0-9+/]*={0,2}$/;

const bad = (error) => [400, { error, code: 'bad-request' }];

const storyId = (body) =>
  CHAT.test(String(body.chat ?? '')) &&
  Number.isInteger(body.id) &&
  body.id > 0;

const optional = (value, ok) => value === undefined || ok(value);

// A route that asks the account's `method` when `ok(body)` holds.
const route = (method, what, ok, build) => async (account, body) =>
  ok(body) && typeof account[method] === 'function'
    ? [200, await account[method](build(body))]
    : bad(what);

const pick = (body, keys) =>
  Object.fromEntries(
    keys.filter((k) => body[k] !== undefined).map((k) => [k, body[k]])
  );

export const STORY_EXTRAS_POSTS = {
  'story-stealth': route(
    'storyStealth',
    'past and future required',
    (b) =>
      typeof b.past === 'boolean' &&
      typeof b.future === 'boolean' &&
      (b.past || b.future),
    (b) => ({ past: b.past, future: b.future })
  ),
  'story-reactions': route(
    'storyReactions',
    'chat and id required',
    (b) =>
      storyId(b) &&
      optional(b.offset, (v) => typeof v === 'string' && OFFSET.test(v)) &&
      optional(
        b.reaction,
        (v) => typeof v === 'string' && v.length > 0 && v.length <= 24
      ) &&
      optional(b.forwardsFirst, (v) => typeof v === 'boolean'),
    (b) => ({
      chat: String(b.chat),
      id: b.id,
      ...pick(b, ['offset', 'reaction', 'forwardsFirst']),
    })
  ),
  'story-report': route(
    'storyReport',
    'chat and id required',
    (b) =>
      storyId(b) &&
      optional(
        b.option,
        (v) => typeof v === 'string' && v.length <= 2048 && BASE64.test(v)
      ) &&
      optional(b.message, (v) => typeof v === 'string' && v.length <= 512),
    (b) => ({
      chat: String(b.chat),
      id: b.id,
      ...pick(b, ['option', 'message']),
    })
  ),
  'stories-views': route(
    'storiesViews',
    'chat and ids required',
    (b) =>
      CHAT.test(String(b.chat ?? '')) &&
      Array.isArray(b.ids) &&
      b.ids.length > 0 &&
      b.ids.length <= 100 &&
      b.ids.every((id) => Number.isInteger(id) && id > 0),
    (b) => ({ chat: String(b.chat), ids: b.ids })
  ),
};

