// Voice chats, video chats and live streams (R-Y188): the routes of the
// POSTS table in routes-telegram.js, each validated strictly before the
// account is asked. Joining, leaving, notifying and unmuting are writes
// and only ever follow a click in the page.
//
// Its routes:
//   POST /api/telegram/call-info {chat} -> { ok, call } the chat's active
//                       call or null (a group or channel id)
//   POST /api/telegram/call-open {id, accessHash} -> { ok, call,
//                       participants, next, count }
//   POST /api/telegram/call-participants {id, accessHash, offset?} ->
//                       { ok, participants, next, count } a further page
//   POST /api/telegram/call-notify {id, accessHash, subscribed} -> { ok }
//                       "Notify me" for a scheduled call
//   POST /api/telegram/call-join-as {chat} -> { ok, peers } who may join
//   POST /api/telegram/call-join {id, accessHash, params, joinAs?} ->
//                       { ok, connection, source } joins muted; `params`
//                       is the join params JSON as a string
//   POST /api/telegram/call-leave {id, accessHash, source} -> { ok }
//   POST /api/telegram/call-self {id, accessHash, muted, raiseHand?,
//                       joinAs?} -> { ok } our own mute / raised hand

import {
  validCall,
  validChat,
  validJoinAs,
  validParams,
} from '../sources/telegram-voice-chat.js';

const BAD = [400, { error: 'bad request', code: 'bad-request' }];

const through = (name, valid) => async (account, body) =>
  valid(body) && typeof account[name] === 'function'
    ? [200, await account[name](body)]
    : BAD;

const offsetOk = (body) =>
  body.offset === undefined || /^[\w-]{0,200}$/.test(String(body.offset));

export const VOICE_CHAT_POSTS = {
  'call-info': through('callInfo', validChat),
  'call-open': through('callOpen', validCall),
  'call-participants': through(
    'callParticipants',
    (body) => validCall(body) && offsetOk(body)
  ),
  'call-notify': through(
    'callNotify',
    (body) => validCall(body) && typeof body.subscribed === 'boolean'
  ),
  'call-join-as': through('callJoinAs', validChat),
  'call-join': through(
    'callJoin',
    (body) =>
      validCall(body) && validParams(body.params) && validJoinAs(body.joinAs)
  ),
  'call-leave': through(
    'callLeave',
    (body) => validCall(body) && Number.isInteger(body.source)
  ),
  'call-self': through(
    'callSelf',
    (body) =>
      validCall(body) &&
      typeof body.muted === 'boolean' &&
      validJoinAs(body.joinAs) &&
      (body.raiseHand === undefined || typeof body.raiseHand === 'boolean')
  ),
};

// Chat backgrounds (R-Y155): the routes of the POSTS and GETS tables in
// routes-telegram.js, each validated strictly before the account is asked.
//
// Its routes:
//   POST /api/telegram/wallpapers {fresh?} -> { ok, wallpapers } the
//                       backgrounds Telegram offers (R-Y155): id, slug,
//                       kind image|pattern|colors, colours, intensity
//   POST /api/telegram/chat-wallpaper-set {chat, id} -> { ok } a listed
//                       wallpaper set for one chat, for the user only
//   GET  /api/telegram/wallpaper?id=&slug=&size=thumb|full -> the picture
//                       (a pattern as sanitized image/svg+xml)

import { json } from './util.js';
import { fromApp } from './routes-telegram-files.js';
import { ID, SLUG } from '../sources/telegram-wallpapers.js';

const SIZES = ['thumb', 'full'];

const validFile = (id, slug, size) =>
  ID.test(id) && (slug === '' || SLUG.test(slug)) && SIZES.includes(size);

// GET /api/telegram/wallpaper?id=&slug=&size= -> the wallpaper's picture
// (a pattern as sanitized SVG), only for the app's own pages.
const handleWallpaper = async (account, req, res, ctx) => {
  if (!fromApp(req, ctx?.allowOrigins)) {
    return json(res, 403, { error: 'wallpapers load only in the app' }) ?? true;
  }
  if (typeof account.wallpaperFile !== 'function') {
    return json(res, 501, { error: 'wallpapers not available' }) ?? true;
  }
  const query = new URL(req.url, 'http://local').searchParams;
  const id = query.get('id') ?? '';
  const slug = query.get('slug') ?? '';
  const size = query.get('size') || 'full';
  if (!validFile(id, slug, size)) {
    return json(res, 400, { error: 'bad wallpaper' }) ?? true;
  }
  const result = await account.wallpaperFile({ id, slug, size });
  if (!result?.buffer) {
    return json(res, 404, { error: 'no wallpaper' }) ?? true;
  }
  res.writeHead(200, {
    'content-type': result.mimeType,
    'content-length': result.buffer.length,
    'cache-control': 'private, max-age=31536000, immutable',
    'x-content-type-options': 'nosniff',
    'content-security-policy': "default-src 'none'; style-src 'unsafe-inline'",
  });
  res.end(result.buffer);
  return true;
};

export const WALLPAPER_GETS = { wallpaper: handleWallpaper };

export const WALLPAPER_POSTS = {
  wallpapers: async (account, body) =>
    typeof account.wallpapers === 'function' &&
    (body.fresh === undefined || typeof body.fresh === 'boolean')
      ? [200, await account.wallpapers({ fresh: body.fresh === true })]
      : [400, { error: 'bad request', code: 'bad-request' }],
  'chat-wallpaper-set': async (account, body) =>
    ID.test(String(body.chat ?? '')) &&
    ID.test(String(body.id ?? '')) &&
    typeof account.setChatWallpaper === 'function'
      ? [
          200,
          await account.setChatWallpaper({
            chat: String(body.chat),
            id: String(body.id),
          }),
        ]
      : [400, { error: 'chat and wallpaper required', code: 'bad-request' }],
};

// A bot's mini apps (R-Y168): the routes of the POSTS table in
// routes-telegram.js, each validated strictly before the account is asked.
//
// Its routes:
//   POST /api/telegram/web-app-open {kind, chat?, bot?, url?, username?,
//                       shortName?, startParam?, theme?}
//                       -> { ok, url, queryId, fullsize, bot? } where kind is
//                       menu | inline | simple | app | main; an address must
//                       be https; theme is `key: #rrggbb` pairs (R-Y168)
//   POST /api/telegram/web-app-prolong {chat, bot, queryId} -> { ok } keeps
//                       an open app's query alive (silent)
//   POST /api/telegram/web-app-data {bot, text, data} -> { ok } a reply
//                       keyboard app's data (at most 4096 bytes) sent

import {
  KINDS,
  MAX_DATA,
  MAX_TEXT,
  httpsUrl,
  startParamOk,
  themeOf,
} from '../sources/telegram-web-apps.js';

const ID = /^\d{1,20}$/;
const CHAT = /^-?\d{1,20}$/;
const NAME = /^[A-Za-z][A-Za-z0-9_]{3,31}$/;
const SHORT = /^[A-Za-z][A-Za-z0-9_]{2,31}$/;

const bad = (error) => [400, { error, code: 'bad-request' }];
const optional = (value, ok) => value === undefined || ok(value);

// The fields every kind may carry.
const generalOk = (body) =>
  KINDS.includes(body.kind) &&
  startParamOk(body.startParam) &&
  optional(body.theme, (t) => themeOf(t) !== null) &&
  optional(body.url, (u) => typeof u === 'string' && httpsUrl(u) !== null) &&
  optional(body.chat, (c) => CHAT.test(String(c)));

const linkOk = (body) =>
  NAME.test(String(body.username ?? '')) &&
  (body.kind === 'main' || SHORT.test(String(body.shortName ?? '')));

const buttonOk = (body) =>
  ID.test(String(body.bot ?? '')) &&
  (body.kind === 'simple' || body.chat !== undefined) &&
  (['menu', 'attach'].includes(body.kind) || body.url !== undefined);

const openOk = (body) =>
  generalOk(body) &&
  (body.kind === 'app' || body.kind === 'main' ? linkOk(body) : buttonOk(body));

const pick = (body, keys) =>
  Object.fromEntries(
    keys.filter((k) => body[k] !== undefined).map((k) => [k, body[k]])
  );

export const WEB_APPS_POSTS = {
  'web-app-open': async (account, body) =>
    openOk(body) && typeof account.webAppOpen === 'function'
      ? [
          200,
          await account.webAppOpen(
            pick(body, [
              'kind',
              'chat',
              'bot',
              'url',
              'username',
              'shortName',
              'startParam',
              'theme',
            ])
          ),
        ]
      : bad('a valid app request required'),
  'web-app-prolong': async (account, body) =>
    CHAT.test(String(body.chat ?? '')) &&
    ID.test(String(body.bot ?? '')) &&
    ID.test(String(body.queryId ?? '')) &&
    typeof account.webAppProlong === 'function'
      ? [
          200,
          await account.webAppProlong({
            chat: String(body.chat),
            bot: String(body.bot),
            queryId: String(body.queryId),
          }),
        ]
      : bad('chat, bot and queryId required'),
  'web-app-data': async (account, body) =>
    ID.test(String(body.bot ?? '')) &&
    typeof body.text === 'string' &&
    body.text.trim().length > 0 &&
    body.text.length <= MAX_TEXT &&
    typeof body.data === 'string' &&
    body.data.length > 0 &&
    Buffer.byteLength(body.data) <= MAX_DATA &&
    typeof account.webAppSendData === 'function'
      ? [
          200,
          await account.webAppSendData({
            bot: String(body.bot),
            text: body.text,
            data: body.data,
          }),
        ]
      : bad('bot, button text and data (up to 4096 bytes) required'),
};

