const validSlot = (slot) =>
  Number.isInteger(slot) && slot >= 2 && slot <= MAX_ACCOUNTS_PREMIUM;

/** The directory of an extra account's own store, inside the store dir. */
export const accountDir = (storeDir, slot) => {
  if (!validSlot(slot) || !storeDir) {
    throw new Error('no directory for this account');
  }
  return path.join(storeDir, 'accounts', `telegram-${slot}`);
};

const secretValue = (link) =>
  link?.value ?? link?.token ?? link?.body ?? link?.text ?? null;

/**
 * `own` (the account's store) as the account service sees it: the
 * `secret:telegram:*` credentials are read from `home`'s
 * `secret:telegram@<slot>:*`. Everything else is `own`'s.
 */
export const borrowSecrets = (own, home, slot) => {
  const borrowed = async (id) => {
    const name = /^secret:telegram:(.+)$/.exec(id)?.[1];
    if (!name) {
      return undefined;
    }
    if (SECRET_NAMES.includes(name)) {
      const value = secretValue(await home.get(secretId(slot, name)));
      return value === null ? null : { id, value };
    }
    // The connection proxy is shared; a bot token or anything else is not.
    return id === PROXY_ID ? ((await home.get(PROXY_ID)) ?? null) : null;
  };
  return new Proxy(own, {
    get(target, prop) {
      if (prop === 'get') {
        return async (id) => (await borrowed(id)) ?? target.get(id);
      }
      const value = Reflect.get(target, prop, target);
      return typeof value === 'function' ? value.bind(target) : value;
    },
  });
};

/** A store's unread count as the badge counts it: chats not muted. */
export const unreadOfStore = async (store, now = Date.now()) => {
  const reads = await store.query((link) =>
    String(link?.id ?? '').startsWith('read:telegram:')
  );
  return reads.reduce(
    (sum, read) =>
      sum +
      (Number(read.muteUntil ?? 0) * 1000 > now
        ? 0
        : Math.max(0, Number(read.unreadCount) || 0)),
    0
  );
};

/** The Telegram chats with their newest message, from a chat index. */
export const telegramChats = async (chatIndex) =>
  (await chatIndex.heads())
    .filter((link) => link.source === 'telegram')
    .map((link) => ({
      chat: String(link.chat),
      chatType: link.chatType ?? null,
      at: link.timestamp ?? null,
    }));

const sourcesFor = (account) => (name) => {
  const adapter = getSource(name);
  return name === 'telegram' && account && adapter
    ? { ...adapter, live: { ...adapter.live, ...account.live } }
    : adapter;
};

// An extra account sends through Telegram only: never through a browser
// that is signed in as someone else.
const NO_BROWSER = {
  send: async () => {
    throw Object.assign(new Error('this account sends through Telegram'), {
      code: 'no-browser',
      fallback: false,
    });
  },
  close: async () => {},
};

const senderOf = (store, account, log) => {
  const optionsFor = (source) =>
    liveOptionsFrom(store, source).catch(() => ({}));
  const getSourceFor = sourcesFor(account);
  return {
    send: createDefaultSender({
      getSource: getSourceFor,
      optionsFor,
      browser: NO_BROWSER,
      log,
    }),
    setTyping: async ({ source, chat, cancel }) =>
      setTypingFor(getSourceFor, {
        source,
        chat,
        cancel,
        options: await optionsFor(source),
      }).catch((error) => ({ supported: false, source, error: error.message })),
  };
};

const defaultBuild = ({ store, log, chats, mediaDir }) => {
  const account = createTelegramAccount({ store, log, chats, mediaDir });
  account.start();
  return { account };
};

const incoming = (link, now) =>
  typeof link?.id === 'string' &&
  link.id.startsWith('msg:telegram:') &&
  link.sender !== 'me' &&
  !link.deleted &&
  now - (Date.parse(link.timestamp ?? '') || 0) < FRESH_MS;

// The notification stream's source: a new incoming message of any account
// (account 1's store is only subscribed to, never written). It listens to
// the stores only while someone watches.
const createMessageWatch = ({ home, now, entries }) => {
  const watchers = new Set();
  const unwatch = new Map(); // slot -> unsubscribe

  const announce = async (slot, store, link) => {
    const read = await store.get(`read:telegram:${link.chat}`);
    const body = String(link.body ?? '');
    const event = {
      account: slot,
      id: link.id,
      chat: String(link.chat),
      chatName: link.chatName ?? link.senderName ?? null,
      sender: link.senderName ?? null,
      body: body.length > 200 ? `${body.slice(0, 200)}...` : body,
      at: link.timestamp ?? null,
      muted: Number(read?.muteUntil ?? 0) * 1000 > now(),
    };
    for (const watcher of watchers) {
      watcher(event);
    }
  };
  const attachNow = (slot, store) => {
    if (unwatch.has(slot) || typeof store.subscribe !== 'function') {
      return;
    }
    unwatch.set(
      slot,
      store.subscribe((event) => {
        if (event?.type !== 'delete' && incoming(event?.link, now())) {
          announce(slot, store, event.link).catch(() => {});
        }
      })
    );
  };
  const detach = (slot) => {
    unwatch.get(slot)?.();
    unwatch.delete(slot);
  };
  return {
    attach: (slot, store) => watchers.size > 0 && attachNow(slot, store),
    detach,
    watch: (listener) => {
      watchers.add(listener);
      attachNow(1, home);
      for (const [slot, entry] of entries) {
        attachNow(slot, entry.store);
      }
      return () => {
        watchers.delete(listener);
        if (watchers.size === 0) {
          [...unwatch.keys()].forEach(detach);
        }
      };
    },
  };
};

/**
 * The running extra accounts of `home` (account 1's store).
 * `openStore(slot)` -> `{ store, dir }` and `build({ store, slot, ... })`
 * -> `{ account, send?, setTyping? }` are replaceable (tests).
 */
export const createExtraRuntime = ({
  home,
  storeDir = null,
  openStore = null,
  build = defaultBuild,
  log = () => {},
  now = () => Date.now(),
} = {}) => {
  const entries = new Map(); // slot -> entry
  const starting = new Map(); // slot -> promise
  const messages = createMessageWatch({ home, now, entries });

  const open =
    openStore ??
    (async (slot) => {
      if (!storeDir) {
        return { store: createMemoryStore(), dir: null };
      }
      const dir = accountDir(storeDir, slot);
      return { store: await openDualStore(dir), dir };
    });

  const create = async (slot) => {
    if (!(await readSlotCredentials(home, slot))) {
      return null;
    }
    const { store: opened, dir } = await open(slot);
    const own = withMessageVersions(opened);
    const store = borrowSecrets(own, home, slot);
    const chatIndex = createChatIndex(store);
    const built = await build({
      store,
      slot,
      log,
      chats: () => telegramChats(chatIndex),
      mediaDir: dir ? path.join(dir, 'media', 'telegram') : null,
    });
    const made = senderOf(store, built.account, log);
    const entry = {
      slot,
      store,
      own,
      dir,
      chatIndex,
      account: built.account,
      send: built.send ?? made.send,
      setTyping: built.setTyping ?? made.setTyping,
    };
    entries.set(slot, entry);
    messages.attach(slot, store);
    return entry;
  };

  /** The running entry of a slot, or null. */
  const get = (slot) => entries.get(slot) ?? null;

  /** Start a signed-in slot (once), or null when it is not signed in. */
  const start = async (slot) => {
    if (!validSlot(slot)) {
      return null;
    }
    if (entries.has(slot)) {
      return entries.get(slot);
    }
    if (!starting.has(slot)) {
      starting.set(
        slot,
        create(slot).finally(() => starting.delete(slot))
      );
    }
    return starting.get(slot);
  };

  const stopSlot = async (slot, { handoff = false } = {}) => {
    const entry = entries.get(slot);
    entries.delete(slot);
    messages.detach(slot);
    if (entry) {
      await entry.account?.stop?.().catch(() => {});
      entry.chatIndex.close();
      await (handoff ? entry.own.flushLog?.() : entry.own.flush?.())?.catch(
        () => {}
      );
    }
  };

  return {
    get,
    start,
    /** Every signed-in extra account starts with the server. */
    startAll: async () => {
      for (const slot of await extraSlots(home)) {
        await start(slot).catch((error) =>
          log({
            level: 'error',
            event: 'telegram_extra_start_failed',
            slot,
            error: error.message,
          })
        );
      }
    },
    stopSlot,
    /**
     * Stop an account and delete its own directory (only that one:
     * `<store dir>/accounts/telegram-N`). True when a directory went.
     */
    remove: async (slot) => {
      await stopSlot(slot);
      if (!storeDir || !validSlot(slot)) {
        return false;
      }
      const dir = accountDir(storeDir, slot);
      const existed = await fs.stat(dir).then(
        () => true,
        () => false
      );
      await fs.rm(dir, { recursive: true, force: true });
      return existed;
    },
    /** Account `slot`'s unread count, from its own store; null if not running. */
    unread: async (slot) => {
      const entry = entries.get(slot);
      return entry ? unreadOfStore(entry.own, now()) : null;
    },
    /** Account 1's unread count (reads only). */
    homeUnread: () => unreadOfStore(home, now()),
    /** `listener(event)` for each new incoming message of any account. */
    watch: messages.watch,
    /** Stop every running extra account (the server is closing). */
    stop: async (options) => {
      await Promise.all(
        [...entries.keys()].map((slot) => stopSlot(slot, options))
      );
    },
  };
};

/**
 * The server context a request for a running extra account runs with: the
 * server's own, read through, with this account's service, store, chat
 * index and sender in place of account 1's. Kept per account, so what a
 * route remembers on it (a send's client id, a confirmation) survives
 * between requests.
 */
export const scopedContext = (ctx, entry) => {
  if (entry.scoped?.base !== ctx) {
    entry.scoped = {
      base: ctx,
      ctx: Object.assign(Object.create(ctx), {
        telegramAccount: entry.account,
        telegramStore: entry.store,
        telegramAccounts: null,
        telegramExtras: null,
        chatIndex: entry.chatIndex,
        storeDir: entry.dir,
        send: entry.send,
        setTyping: entry.setTyping,
        // Its own record of sends in flight (a client id is per account).
        sends: new Map(),
      }),
    };
  }
  return entry.scoped.ctx;
};

import { floodSeconds } from '../sources/telegram-history.js';
import { json } from './util.js';

// A Telegram rate limit is a recoverable wait, with a usable retry time.
export const telegramRouteError = (res, path, error, log) => {
  const wait =
    floodSeconds(error) ||
    (error.code === 'flood-wait' ? Number(error.retryAfter) : 0);
  const code = wait ? 'flood-wait' : error.code;
  log?.({
    level: wait ? 'warn' : 'error',
    event: wait ? 'telegram_route_waits' : 'telegram_route_failed',
    path,
    error: error.message,
    code: code ?? null,
    ...(wait ? { retryAfter: wait } : {}),
  });
  if (wait) {
    res.setHeader('retry-after', String(Math.ceil(wait)));
  }
  json(res, wait ? 429 : 502, {
    error: error.message,
    code,
    ...(wait || error.retryAfter
      ? { retryAfter: wait || error.retryAfter }
      : {}),
  });
  return true;
};

/**
 * Find the Telegram sign-ins the user already has on this computer.
 *
 * People who experiment with Telegram scatter their own credentials across
 * repositories: the same bot token in a dozen project `.env` files, a GramJS
 * user "string session" saved beside another (konard/telegram-bot writes it
 * to `.telegram_session`), an `api_id`/`api_hash`/phone trio in a third.
 * This module walks folders the user chooses and distils them down to the
 * few real accounts behind them, so the account can be connected here
 * without hunting for them again.
 *
 *   scan({ roots })  read-only walk of the chosen folders. The same token or
 *                    session found in many files collapses to ONE entry
 *                    (every location kept for display). Each distinct
 *                    credential is checked LIVE — bot tokens via the Bot API
 *                    `getMe`, user sessions via MTProto — so only accounts
 *                    that still work are listed, and a user session resolves
 *                    to its real phone number. Entries are grouped by the
 *                    account they belong to and typed: a bot token, a login
 *                    by session, or a login by phone & password.
 *   use(id, {store}) connect the chosen credential — store it under the
 *                    `secret:telegram:*` keys the app already reads. A
 *                    phone & password credential has no stored session yet,
 *                    so `use` reports `needsLogin` and the caller starts the
 *                    interactive sign-in with `loginContext(id)`.
 *
 * Everything stays on this computer: raw values live in an owner-only file
 * (0600) until the user connects one, and are never logged or returned to
 * the browser — callers see types, locations and masked hints only.
 */

import { promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { renameDurable } from '../../storage/durable.js';
import crypto from 'node:crypto';
import { timedRequest } from '../http.js';

const statusError = (message, status) =>
  Object.assign(new Error(message), { status });

// Folders worth scanning by default: the common roots where repositories
// live, plus the current working directory, filtered to those that exist.
export const defaultRoots = async ({
  homeDir = os.homedir(),
  cwd = process.cwd(),
} = {}) => {
  const candidates = [
    cwd,
    ...[
      'Code',
      'code',
      'projects',
      'dev',
      'src',
      'work',
      'repos',
      'github',
    ].map((name) => path.join(homeDir, name)),
  ];
  const existing = [];
  const seen = new Set();
  for (const dir of candidates) {
    try {
      if (!(await fs.stat(dir)).isDirectory()) {
        continue;
      }
      // Dedupe by real path: on a case-insensitive macOS filesystem
      // `~/Code` and `~/code` are the same directory, so scanning both
      // would walk the whole tree twice.
      const real = await fs.realpath(dir);
      if (!seen.has(real)) {
        seen.add(real);
        existing.push(dir);
      }
    } catch {
      // not there — skip.
    }
  }
  return existing;
};

const SKIP_DIRS = new Set([
  'node_modules',
  '.git',
  '.Trash',
  'Library',
  'vendor',
  'dist',
  'build',
  '.cache',
  // Heavy build / dependency / virtualenv trees that never hold a
  // hand-written .env, skipped so the walk stays fast.
  'target',
  'venv',
  '.venv',
  '__pycache__',
  '.next',
  '.nuxt',
  'coverage',
  '.pytest_cache',
  '.gradle',
  'Pods',
  'DerivedData',
]);

// `.env.example`, `.env.template`, `.env.sample`, `.env.dist` hold
// placeholders, never real secrets — ignore them.
const isTemplateEnv = (name) => /\.(example|sample|template|dist)$/i.test(name);

const isEnvFile = (name) =>
  !isTemplateEnv(name) &&
  (name === '.env' ||
    name === '.lenv' ||
    name.endsWith('.env') ||
    name.endsWith('.lenv') ||
    /^\.env\./i.test(name));

// Files that hold a saved user session string (konard/telegram-bot writes
// `.telegram_session`; Telethon writes a `*.session` SQLite file).
const isSessionFile = (name) =>
  name === '.telegram_session' ||
  name.endsWith('.telegram_session') ||
  name.endsWith('.tgsession') ||
  /string[_-]?session/i.test(name);

const isTelethonSession = (name) => /\.session$/i.test(name);

// A directory not worth descending into: a known heavy tree, or any
// dot-directory (.git, .github, .vscode, .venv, …) — project `.env` files
// live in ordinary folders, so skipping these keeps the walk fast.
const skipDir = (name) => SKIP_DIRS.has(name) || name.startsWith('.');

/** Walk `root`, breadth-capped, for env and session files. No reads yet. */
const walkFiles = async (root, { maxDepth = 5, limit = 4000 } = {}) => {
  const found = [];
  const queue = [{ dir: root, depth: 0 }];
  while (queue.length && found.length < limit) {
    const { dir, depth } = queue.shift();
    let entries;
    try {
      entries = await fs.readdir(dir, { withFileTypes: true });
    } catch {
      continue;
    }
    for (const entry of entries) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        if (depth < maxDepth && !skipDir(entry.name)) {
          queue.push({ dir: full, depth: depth + 1 });
        }
      } else if (
        isEnvFile(entry.name) ||
        isSessionFile(entry.name) ||
        isTelethonSession(entry.name)
      ) {
        found.push(full);
      }
    }
  }
  return found;
};

const BOT_TOKEN = /^\d{5,}:[A-Za-z0-9_-]{30,}$/;
// A GramJS StringSession: one long line of base64url-ish characters.
const USER_SESSION = /^[A-Za-z0-9+/=_-]{40,}$/;

/** Last four characters, everything else hidden. Never more than that. */
export const maskHint = (value) => {
  const text = String(value ?? '');
  const tail = text.slice(-4);
  return tail ? `••••${tail}` : '••••';
};

// A token/session hint that shows a little of both ends: the first three and
// last three characters, the middle hidden (`123•••••xyz`). Only when the
// value is long enough that doing so still hides most of it; shorter values
// fall back to the tail-only mask so nothing short is over-exposed.
export const maskEnds = (value) => {
  const text = String(value ?? '');
  if (text.length < 10) {
    return maskHint(text);
  }
  return `${text.slice(0, 3)}•••••${text.slice(-3)}`;
};

// Paths sorted shortest first, so the most concise location leads the list.
const byLength = (paths) =>
  [...paths].sort((a, b) => a.length - b.length || a.localeCompare(b));

// The digits of a phone number, as a stable grouping key (`+1 555…` and
// `15 55…` for the same line collapse). Never shown — only maskHint is.
const phoneKey = (phone) => String(phone ?? '').replace(/\D/g, '');

/** Parse `KEY=VALUE` lines from a `.env` / `.lenv` file. */
export const parseEnv = (text) => {
  const out = [];
  for (const raw of String(text).split(/\r?\n/)) {
    const line = raw.trim();
    if (!line || line.startsWith('#')) {
      continue;
    }
    const match = /^(?:export\s+)?([A-Za-z0-9_.]+)\s*=\s*(.*)$/.exec(line);
    if (!match) {
      continue;
    }
    let value = match[2].trim();
    const quote = value[0];
    if ((quote === '"' || quote === "'") && value.endsWith(quote)) {
      value = value.slice(1, -1);
    }
    out.push({ key: match[1], value });
  }
  return out;
};

const KEY_SESSION = /session/i;
const KEY_API_ID = /api[_-]?id$/i;
const KEY_API_HASH = /api[_-]?hash$/i;
const KEY_PHONE = /phone/i;

// A shell reference or an obvious fill-me-in, not a real value:
// `${X}`, `$X`, `<...>`, or words like your/example/changeme/placeholder.
const isPlaceholder = (value) =>
  /\$\{|\$[A-Za-z]|[<>]|\b(your|example|changeme|placeholder|xxxx+|here|todo)\b/i.test(
    value
  );

// Classify one env field into a Telegram credential kind, or null. Bot
// tokens and sessions are accepted only when the VALUE has the real shape,
// so `.env` placeholders never look like credentials.
const classifyField = ({ key, value }) => {
  if (!value || isPlaceholder(value)) {
    return null;
  }
  if (BOT_TOKEN.test(value)) {
    return 'bot-token';
  }
  if (KEY_SESSION.test(key) && USER_SESSION.test(value)) {
    return 'user-session';
  }
  if (KEY_API_ID.test(key)) {
    return 'api-id';
  }
  if (KEY_API_HASH.test(key)) {
    return 'api-hash';
  }
  if (KEY_PHONE.test(key)) {
    return 'phone';
  }
  return null;
};

// The api_id / api_hash / phone that sit alongside a user session.
const apiContext = (fields) => {
  const pick = (kind) => fields.find((f) => f.kind === kind)?.value ?? null;
  return {
    apiId: pick('api-id'),
    apiHash: pick('api-hash'),
    phone: pick('phone'),
  };
};

const idForValue = (kind, value) =>
  crypto
    .createHash('sha1')
    .update(`${kind}\u0000${value}`)
    .digest('hex')
    .slice(0, 16);

const relativeTo = (roots, file) => {
  const root = roots.find((r) => file.startsWith(r));
  return root ? path.relative(path.dirname(root), file) : file;
};

// A field classifier bound to each field, then only the connectable kinds.
const envRecords = (file, roots, fields) => {
  const ctx = apiContext(fields);
  const records = [];
  for (const field of fields) {
    if (field.kind !== 'bot-token' && field.kind !== 'user-session') {
      continue;
    }
    records.push({
      kind: field.kind,
      source: file,
      where: relativeTo(roots, file),
      key: field.key,
      value: field.value,
      ...(field.kind === 'user-session' ? ctx : {}),
    });
  }
  // A bare api_id/api_hash/phone trio (no session beside it) is a
  // "sign in by phone & password" credential in its own right.
  if (ctx.apiId && ctx.apiHash && ctx.phone) {
    records.push({
      kind: 'user-password',
      source: file,
      where: relativeTo(roots, file),
      key: 'phone',
      value: null,
      ...ctx,
    });
  }
  return records;
};

// One env file -> zero or more credential records (with raw values).
const recordsFromEnv = async (file, roots) => {
  const fields = parseEnv(await fs.readFile(file, 'utf8'))
    .map((f) => ({ ...f, kind: classifyField(f) }))
    .filter((f) => f.kind);
  return envRecords(file, roots, fields);
};

// The api_id/api_hash/phone from the `.env` sitting next to a session file.
const siblingApiContext = async (file) => {
  try {
    const sibling = path.join(path.dirname(file), '.env');
    const fields = parseEnv(await fs.readFile(sibling, 'utf8')).map((f) => ({
      ...f,
      kind: classifyField(f),
    }));
    return apiContext(fields);
  } catch {
    return { apiId: null, apiHash: null, phone: null };
  }
};

// A saved session file (`.telegram_session`) -> one user-session record,
// paired with api_id/api_hash from a sibling `.env` when present.
const recordFromSession = async (file, roots) => {
  if (isTelethonSession(file)) {
    return {
      kind: 'telethon-session',
      source: file,
      where: relativeTo(roots, file),
      key: path.basename(file),
      value: null,
    };
  }
  const value = (await fs.readFile(file, 'utf8')).trim();
  if (!USER_SESSION.test(value)) {
    return null;
  }
  return {
    kind: 'user-session',
    source: file,
    where: relativeTo(roots, file),
    key: path.basename(file),
    value,
    ...(await siblingApiContext(file)),
  };
};

// Collapse records that are the same credential found in different files
// into ONE, keeping every location. A session or token repeated across a
// dozen repos becomes a single connectable entry. Distinct kinds keep
// distinct keys; connectables key on their value, phone-logins on the line.
const dedupeKey = (record) => {
  if (record.kind === 'user-password') {
    return `user-password\u0000${phoneKey(record.phone)}`;
  }
  if (record.kind === 'telethon-session') {
    return `telethon\u0000${record.source}`;
  }
  return `${record.kind}\u0000${record.value}`;
};

// Prefer the copy that carries the most context (api_id/api_hash/phone):
// any repo's `.env` may hold the token, but only some sit beside the trio
// needed to verify a session or to sign in by phone.
const richer = (a, b) => {
  const score = (r) =>
    (r.apiId ? 1 : 0) + (r.apiHash ? 1 : 0) + (r.phone ? 1 : 0);
  return score(b) > score(a) ? b : a;
};

const dedupeRecords = (records) => {
  const byKey = new Map();
  for (const record of records) {
    const key = dedupeKey(record);
    const existing = byKey.get(key);
    if (!existing) {
      byKey.set(key, { ...record, wheres: [record.where] });
      continue;
    }
    const merged = richer(existing, record);
    byKey.set(key, {
      ...merged,
      wheres: [...new Set([...existing.wheres, record.where])],
    });
  }
  // A phone-login is redundant when a working session for the same line is
  // present (the session is the stronger credential) — drop it so each
  // account shows "by session" OR "by phone & password", not a stray dup.
  const sessionPhones = new Set(
    [...byKey.values()]
      .filter((r) => r.kind === 'user-session' && r.phone)
      .map((r) => phoneKey(r.phone))
  );
  const kept = [...byKey.values()].filter(
    (r) => r.kind !== 'user-password' || !sessionPhones.has(phoneKey(r.phone))
  );
  for (const record of kept) {
    record.id = idForValue(record.kind, record.value ?? dedupeKey(record));
  }
  return kept;
};

// The credential type the UI groups by: a bot token, a login by session,
// or a login by phone & password.
const typeOf = (record) =>
  record.kind === 'bot-token'
    ? 'bot'
    : record.kind === 'user-password'
      ? 'user-password'
      : 'session';

// A record as the caller sees it: never the value, only a masked hint, the
// type, whether it is live, and every place it was found.
const publicEntry = (record) => {
  const wheres = byLength(record.wheres ?? [record.where]);
  return {
    id: record.id,
    kind: record.kind,
    type: typeOf(record),
    where: wheres[0],
    wheres,
    key: record.key,
    hint: record.value ? maskEnds(record.value) : null,
    phone: record.phone ? maskHint(record.phone) : null,
    active: record.active ?? null,
    account: record.account ?? null,
  };
};

// Walk the chosen folders and read every credential they hold.
const collectRecords = async (scanRoots) => {
  const files = (await Promise.all(scanRoots.map((r) => walkFiles(r)))).flat();
  const records = [];
  for (const file of files) {
    try {
      const base = path.basename(file);
      if (isSessionFile(base) || isTelethonSession(base)) {
        const record = await recordFromSession(file, scanRoots);
        if (record) {
          records.push(record);
        }
      } else {
        records.push(...(await recordsFromEnv(file, scanRoots)));
      }
    } catch {
      // unreadable file — skip it.
    }
  }
  return records;
};

// Give a slow or hung network check a hard deadline so one bad credential
// can never freeze the whole scan.
const withTimeout = (promise, ms) => {
  if (!ms) {
    return promise;
  }
  let timer;
  const guard = new Promise((_resolve, reject) => {
    timer = globalThis.setTimeout(() => reject(new Error('timeout')), ms);
  });
  // Clear the timer whichever way the race ends, so a resolved check never
  // leaves a 12s timeout holding the event loop open.
  return Promise.race([promise, guard]).finally(() =>
    globalThis.clearTimeout(timer)
  );
};

// An error that means the credential is genuinely dead — Telegram answered
// and rejected it — as opposed to a network/timeout error that proves
// nothing. Only the former drops a credential from the list.
const deadError = (message) =>
  Object.assign(new Error(message), { dead: true });

const DEAD_SESSION =
  /AUTH_KEY_UNREGISTERED|SESSION_REVOKED|SESSION_EXPIRED|USER_DEACTIVATED|AUTH_KEY_DUPLICATED|UNAUTHORIZED/i;

const isDeadError = (error) =>
  error?.dead === true ||
  DEAD_SESSION.test(
    error?.errorMessage ?? error?.className ?? error?.message ?? ''
  );

// Resolve a bot token to its account with the Bot API (no dependency). A
// reachable API that rejects the token is a dead credential; a network error
// is not (it rethrows untagged and the token is kept, unverified).
const identifyBot = async (value, fetchImpl) => {
  const me = await timedRequest(
    fetchImpl,
    `https://api.telegram.org/bot${value}/getMe`,
    undefined,
    { write: false },
    async (res) => (await res.json())?.result
  );
  if (!me) {
    throw deadError('bot token rejected by Telegram');
  }
  return {
    kind: 'bot',
    key: `bot:${me.id}`,
    id: me.id,
    username: me.username ?? null,
    label: me.username ? `@${me.username}` : (me.first_name ?? `bot ${me.id}`),
    verified: true,
  };
};

// Resolve a user session via MTProto: connect with the paired
// api_id/api_hash and read the account, including its phone number.
const identifyUser = async (record, mtproto) => {
  const me = await mtproto({
    apiId: Number(record.apiId),
    apiHash: record.apiHash,
    session: record.value,
  }).then((client) => client.getMe());
  const name = [me.firstName, me.lastName].filter(Boolean).join(' ');
  const phone = me.phone ?? (phoneKey(record.phone) || null);
  // GramJS ids are BigInt; keep them as strings so the result stays
  // JSON-serializable (a raw BigInt throws on JSON.stringify).
  const id = me.id === null || me.id === undefined ? null : String(me.id);
  return {
    kind: 'user',
    key: `user:${id}`,
    id,
    username: me.username ?? null,
    phone,
    label: me.username ? `@${me.username}` : name || `user ${maskHint(phone)}`,
    verified: true,
  };
};

// The account a phone-login (api_id/api_hash/phone) belongs to, before any
// sign-in: known only by its phone number, so unverified.
const phoneAccount = (record) => ({
  kind: 'user',
  key: `phone:${phoneKey(record.phone)}`,
  id: null,
  username: null,
  phone: phoneKey(record.phone),
  label: `user ${maskHint(record.phone)}`,
  verified: false,
});

// A fallback account label from the file alone, when no live check ran.
const localAccount = (record) => {
  if (record.kind === 'bot-token') {
    return {
      kind: 'bot',
      key: `bot:${maskHint(record.value)}`,
      label: `bot token ${maskHint(record.value)}`,
      verified: false,
    };
  }
  const phone = record.phone ? maskHint(record.phone) : null;
  return {
    kind: 'user',
    key: phone ? `phone:${phoneKey(record.phone)}` : `session:${record.id}`,
    phone: phoneKey(record.phone),
    label: phone ? `user ${phone}` : 'user session',
    verified: false,
  };
};

// Check one credential live and attach its account + whether it works.
// A proven-dead credential (a token Telegram rejects, a revoked session)
// gets active=false; one we cannot check (a session with no api_id, or no
// MTProto client) stays active=null and is kept — we never hide a
// credential just because we could not reach the network.
const verifyRecord = async (record, { fetchImpl, mtproto, timeout }) => {
  try {
    if (record.kind === 'bot-token' && fetchImpl) {
      record.account = await withTimeout(
        identifyBot(record.value, fetchImpl),
        timeout
      );
      record.active = true;
    } else if (
      record.kind === 'user-session' &&
      mtproto &&
      record.apiId &&
      record.apiHash
    ) {
      record.account = await withTimeout(
        identifyUser(record, mtproto),
        timeout
      );
      record.phone = record.account.phone ?? record.phone;
      record.active = true;
    } else if (record.kind === 'user-password') {
      record.account = phoneAccount(record);
      record.active = null; // ready to sign in, not yet proven
    } else {
      record.account = localAccount(record);
      record.active = null; // could not check
    }
  } catch (error) {
    record.account = localAccount(record);
    // Only a credential Telegram actually rejected is dropped. A network or
    // timeout error proves nothing, so the credential is kept, unverified.
    record.active = isDeadError(error) ? false : null;
  }
  return record;
};

// After the live checks, fold every credential for one phone line into the
// same account: a verified session tells us the real @username and id for a
// phone, so a phone-login on that same number joins its group instead of
// sitting alone.
const mergeByPhone = (records) => {
  const verifiedByPhone = new Map();
  for (const record of records) {
    const phone = record.account?.verified && record.account.phone;
    if (phone) {
      verifiedByPhone.set(phoneKey(phone), record.account);
    }
  }
  for (const record of records) {
    const mine = phoneKey(record.phone);
    if (!record.account?.verified && mine && verifiedByPhone.has(mine)) {
      record.account = verifiedByPhone.get(mine);
    }
  }
  return records;
};

const accountView = (account) => ({
  kind: account.kind,
  label: account.label,
  verified: Boolean(account.verified),
  phone: account.phone ? maskHint(account.phone) : null,
});

// How good a credential is to keep when several of the same type belong to
// one account: a live one beats an unchecked one, a verified account beats a
// phone guess, and one with a session value and api context beats a bare one.
const rankRecord = (r) =>
  (r.active === true ? 8 : 0) +
  (r.account?.verified ? 4 : 0) +
  (r.value ? 2 : 0) +
  (r.apiId ? 1 : 0) +
  (r.apiHash ? 1 : 0);

// Merge two credentials of the same account and type into one: keep the
// stronger, but remember every place either was found.
const mergeRecords = (keep, extra) => {
  const best =
    rankRecord(extra) > rankRecord(keep) ? { ...extra } : { ...keep };
  best.wheres = [
    ...new Set([
      ...(keep.wheres ?? [keep.where]),
      ...(extra.wheres ?? [extra.where]),
    ]),
  ];
  return best;
};

// Group by account and collapse to ONE entry per type, so an account shows a
// single "login by session" (whichever session still works), a single bot
// token, and/or a single "login by phone & password" — never one row per
// file. Every location stays, listed on the entry it was merged into.
const groupRecords = (records) => {
  const groups = new Map();
  for (const record of records) {
    const account = record.account ?? localAccount(record);
    if (!groups.has(account.key)) {
      groups.set(account.key, { account, byType: new Map() });
    }
    const byType = groups.get(account.key).byType;
    const type = typeOf(record);
    byType.set(
      type,
      byType.has(type) ? mergeRecords(byType.get(type), record) : record
    );
  }
  // User accounts first, bot accounts after; otherwise keep discovery order
  // (a stable sort on the kind rank preserves it within each group).
  const kindRank = (account) => (account.kind === 'bot' ? 1 : 0);
  return [...groups.values()]
    .sort((a, b) => kindRank(a.account) - kindRank(b.account))
    .map(({ account, byType }) => ({
      account: accountView(account),
      entries: [...byType.values()].map(publicEntry),
    }));
};

// The `secret:telegram:*` links to write for a connected credential.
const secretLinks = (record, stamp) => {
  const link = (id, tokens, value) => ({ id, tokens, value, updated: stamp });
  if (record.kind === 'bot-token') {
    return [
      link(
        'secret:telegram:bot-token',
        ['secret', 'telegram', 'bot-token'],
        record.value
      ),
    ];
  }
  const links = [
    link(
      'secret:telegram:user-session',
      ['secret', 'telegram', 'user-session'],
      record.value
    ),
  ];
  if (record.apiId) {
    links.push(
      link(
        'secret:telegram:api-id',
        ['secret', 'telegram', 'api-id'],
        String(record.apiId)
      )
    );
  }
  if (record.apiHash) {
    links.push(
      link(
        'secret:telegram:api-hash',
        ['secret', 'telegram', 'api-hash'],
        record.apiHash
      )
    );
  }
  return links;
};

export const createTelegramCreds = ({
  dataDir,
  fetchImpl = globalThis.fetch,
  // Optional MTProto client factory ({apiId,apiHash,session}) -> getMe(),
  // injected where GramJS is available; absent keeps the module dep-free
  // and user sessions are listed unverified (grouped by phone).
  mtproto = null,
  // Per-credential network deadline; 0 disables it (handy in tests).
  verifyTimeout = 12000,
  homeDir = os.homedir(),
  cwd = process.cwd(),
  now = () => Date.now(),
} = {}) => {
  const dir = path.join(dataDir, 'auto-import', 'telegram');
  const cacheFile = path.join(dir, 'found.json');

  const readCache = async () => {
    try {
      return JSON.parse(await fs.readFile(cacheFile, 'utf8'));
    } catch (error) {
      if (error.code === 'ENOENT') {
        return {};
      }
      throw error;
    }
  };

  const writeCache = async (cache) => {
    await fs.mkdir(dir, { recursive: true, mode: 0o700 });
    const temp = `${cacheFile}.${process.pid}.tmp`;
    // A BigInt account id (from GramJS) would otherwise throw here.
    const text = JSON.stringify(cache, (_k, v) =>
      typeof v === 'bigint' ? v.toString() : v
    );
    await fs.writeFile(temp, text, { mode: 0o600 });
    await renameDurable(temp, cacheFile); // (R-Z19)
  };

  const verifyAll = (records) =>
    Promise.all(
      records.map((record) =>
        verifyRecord(record, { fetchImpl, mtproto, timeout: verifyTimeout })
      )
    );

  const scan = async ({ roots } = {}) => {
    const scanRoots = roots?.length
      ? roots
      : await defaultRoots({ homeDir, cwd });
    // Collapse duplicates first, so each distinct credential is checked
    // once however many repos hold it, then verify them all at once.
    const records = dedupeRecords(await collectRecords(scanRoots));
    await verifyAll(records);
    mergeByPhone(records);
    // "Only active": a credential Telegram proved dead is dropped; one we
    // could not check is kept (active=null).
    const live = records.filter((record) => record.active !== false);
    await writeCache({
      roots: scanRoots,
      scannedAt: new Date(now()).toISOString(),
      records: Object.fromEntries(live.map((r) => [r.id, r])),
    });
    // The groups are collapsed to one entry per account and type; the flat
    // entry list is just those same entries, so both agree.
    const groups = groupRecords(live);
    return {
      roots: scanRoots,
      entries: groups.flatMap((group) => group.entries),
      groups,
    };
  };

  // Re-group whatever the last scan cached (used by the HTTP route); the
  // live checks already ran during scan, so this is cheap.
  const identify = async (ids = null) => {
    const cache = await readCache();
    const records = Object.values(cache.records ?? {}).filter(
      (r) => !ids || ids.includes(r.id)
    );
    return { groups: groupRecords(records) };
  };

  // The api_id/api_hash/phone behind a phone-login entry, so the caller can
  // start the interactive sign-in. Server-side only — never sent to a browser.
  const loginContext = async (id) => {
    const cache = await readCache();
    const record = cache.records?.[id];
    if (!record || record.kind !== 'user-password') {
      return null;
    }
    return {
      apiId: record.apiId,
      apiHash: record.apiHash,
      phone: record.phone,
    };
  };

  // Connect the chosen credential: write the secrets the app reads. A
  // phone-login has no session yet, so it reports `needsLogin` and the
  // caller drives the sign-in flow (see loginContext).
  const use = async (id, { store } = {}) => {
    const cache = await readCache();
    const record = cache.records?.[id];
    if (!record) {
      throw statusError('unknown or unreadable credential', 404);
    }
    if (record.kind === 'user-password') {
      return { needsLogin: true, id, account: record.account ?? null };
    }
    if (!record.value) {
      throw statusError('unknown or unreadable credential', 404);
    }
    if (!store) {
      throw statusError('a store is required to connect', 500);
    }
    for (const link of secretLinks(record, new Date(now()).toISOString())) {
      await store.put(link);
    }
    return {
      kind: record.kind,
      hint: maskEnds(record.value),
      account: record.account ?? null,
    };
  };

  return {
    defaultRoots: () => defaultRoots({ homeDir, cwd }),
    scan,
    identify,
    loginContext,
    use,
  };
};

/**
 * Where "Export Telegram data" writes (R-Y212): a folder the server
 * chooses, `<base>/<name>`, or `<base>/<name> (1)`, `(2)`, … when it is
 * already there, so an earlier export is never mixed with a new one.
 */

import { promises as fs } from 'node:fs';
import path from 'node:path';

const exists = async (file) => {
  try {
    await fs.access(file);
    return true;
  } catch {
    return false;
  }
};

export const freeFolder = async (base, name) => {
  const first = path.join(base, name);
  let candidate = first;
  for (let n = 1; (await exists(candidate)) && n < 1000; n += 1) {
    candidate = `${first} (${n})`;
  }
  return candidate;
};

/**
 * The work of "Export Telegram data" (R-Y212; learned, never copied),
 * done inside a takeout session: the account's information, the contacts,
 * the chat list chosen by kind, and each chat's history written by the
 * per-chat export (R-Y186, ./telegram-export-run.js) into its own folder
 * `chats/chat_NN`. Every request goes out wrapped in invokeWithTakeout.
 * `r` is the run: `{ env, c, job, value, now, sleep, takeoutId }`; Cancel is
 * the job's `cancelling` state, looked at between steps.
 */

import { promises as fs } from 'node:fs';
import path from 'node:path';
import { asked, execute, newRun, stopping } from './telegram-export-run.js';
import { chatMeta } from './telegram-export-output.js';
import { EXPORT_CSS, esc, pageHtml } from './telegram-export-html.js';

const PAGE = 100;
const MAX_PAGES = 500;

/** The chat kinds the user picks from. */
export const KINDS = Object.freeze([
  'personal',
  'bots',
  'privateGroups',
  'privateChannels',
  'publicChats',
]);

const KIND_OF_TYPE = {
  personal_chat: 'personal',
  saved_messages: 'personal',
  bot_chat: 'bots',
  private_group: 'privateGroups',
  private_supergroup: 'privateGroups',
  private_channel: 'privateChannels',
  public_supergroup: 'publicChats',
  public_channel: 'publicChats',
};

/** `{ contacts, messageUsers, … }` for account.initTakeoutSession. */
export const takeoutFlags = (value) => {
  const k = value.kinds;
  const flags = {
    contacts: value.contacts || undefined,
    messageUsers: k.personal || k.bots || undefined,
    messageChats: k.privateGroups || undefined,
    messageMegagroups: k.privateGroups || k.publicChats || undefined,
    messageChannels: k.privateChannels || k.publicChats || undefined,
  };
  return Object.fromEntries(
    Object.entries(flags).filter(([, v]) => v !== undefined)
  );
};

/** Seconds Telegram asks to wait (TAKEOUT_INIT_DELAY_X), or 0. */
export const delayOf = (error) => {
  const text = `${error?.errorMessage ?? ''} ${error?.message ?? ''}`;
  if (!text.includes('TAKEOUT_INIT_DELAY')) {
    return 0;
  }
  const match = /TAKEOUT_INIT_DELAY_(\d+)/.exec(text);
  return match ? Number(match[1]) : Number(error?.seconds) || 1;
};

/** The client with every request wrapped in invokeWithTakeout. */
export const takeoutClient = (c, takeoutId) =>
  new Proxy(c.client, {
    get: (target, prop) => {
      if (prop === 'invoke') {
        return (request, ...rest) =>
          target.invoke(
            new c.Api.InvokeWithTakeout({ takeoutId, query: request }),
            ...rest
          );
      }
      const value = Reflect.get(target, prop);
      return typeof value === 'function' ? value.bind(target) : value;
    },
  });

const pad = (n) => String(n).padStart(2, '0');

const peerId = (peer) => {
  if (peer?.userId !== undefined) {
    return String(peer.userId);
  }
  if (peer?.chatId !== undefined) {
    return `-${peer.chatId}`;
  }
  return peer?.channelId !== undefined ? `-100${peer.channelId}` : null;
};

const userName = (u) =>
  [u.firstName, u.lastName].filter(Boolean).join(' ') ||
  u.username ||
  `user${u.id}`;

// What a dialog's peer is: `{ id, name, type }`, or null for a chat that
// cannot be read (forbidden, deleted).
const entryOf = (dialog, page) => {
  const id = peerId(dialog.peer);
  if (!id) {
    return null;
  }
  const key = id.startsWith('-100')
    ? `channel${id.slice(4)}`
    : id.startsWith('-')
      ? `chat${id.slice(1)}`
      : `user${id}`;
  let known;
  if (key.startsWith('user')) {
    const u = (page.users ?? []).find((x) => String(x.id) === id);
    known = u && {
      title: userName(u),
      bot: Boolean(u.bot),
      self: Boolean(u.self),
      username: u.username,
    };
  } else {
    const num = key.replace(/^\D+/, '');
    const c = (page.chats ?? []).find((x) => String(x.id) === num);
    known = c &&
      !String(c.className).endsWith('Forbidden') && {
        title: c.title,
        username: c.username,
        megagroup: Boolean(c.megagroup),
      };
  }
  if (!known) {
    return null;
  }
  const meta = chatMeta({
    chat: id,
    chatName: known.title,
    entities: new Map([[key, known]]),
  });
  return { id, name: meta.name, type: meta.type };
};

const topMessage = (dialog, page) =>
  (page.messages ?? []).find(
    (m) =>
      Number(m.id) === Number(dialog.topMessage) &&
      peerId(m.peerId) === peerId(dialog.peer)
  );

const unixOf = (value) =>
  typeof value === 'string'
    ? Math.floor(Date.parse(value) / 1000) || 0
    : Number(value) || 0;

const offsetPeerOf = async (r, dialog) => {
  try {
    return await r.c.client.getInputEntity(peerId(dialog.peer));
  } catch {
    return new r.c.Api.InputPeerEmpty();
  }
};

// One folder's dialogs, page by page; `into` is the id → entry map.
const readFolder = async (r, folderId, into) => {
  let cursor = { offsetDate: 0, offsetId: 0 };
  let offsetPeer = new r.c.Api.InputPeerEmpty();
  for (let n = 1; n <= MAX_PAGES && !stopping(r); n += 1) {
    const page = await asked(r, `dialogs:takeout:${folderId ?? 0}:${n}`, () =>
      r.client.invoke(
        new r.c.Api.messages.GetDialogs({
          ...(folderId === undefined ? {} : { folderId }),
          ...cursor,
          offsetPeer,
          limit: PAGE,
          hash: r.c.zero,
        })
      )
    );
    const dialogs = page.dialogs ?? [];
    for (const dialog of dialogs) {
      const entry = entryOf(dialog, page);
      if (entry && !into.has(entry.id)) {
        into.set(entry.id, entry);
      }
    }
    const last = dialogs.at(-1);
    const top = last && topMessage(last, page);
    if (
      dialogs.length < PAGE ||
      page.className === 'messages.Dialogs' ||
      !top
    ) {
      return;
    }
    cursor = { offsetDate: unixOf(top.date), offsetId: Number(top.id) };
    offsetPeer = await offsetPeerOf(r, last);
  }
};

/** The chats of the chosen kinds: main list, then the archive. */
export const listChats = async (r) => {
  const all = new Map();
  await readFolder(r, undefined, all);
  await readFolder(r, 1, all);
  return [...all.values()].filter(
    (e) => r.value.kinds[KIND_OF_TYPE[e.type]] === true
  );
};

const personalInfo = async (r) => {
  const { Api } = r.c;
  const full = await asked(r, 'users:takeout:self', () =>
    r.client.invoke(new Api.users.GetFullUser({ id: new Api.InputUserSelf() }))
  );
  const u = (full.users ?? []).find((x) => x.self) ?? full.users?.[0] ?? {};
  return {
    user_id: Number(u.id) || null,
    first_name: u.firstName ?? '',
    last_name: u.lastName ?? '',
    phone_number: u.phone ? `+${u.phone}` : '',
    username: u.username ? `@${u.username}` : '',
    bio: full.fullUser?.about ?? '',
  };
};

const contactList = async (r) => {
  const res = await asked(r, 'contacts:takeout', () =>
    r.client.invoke(new r.c.Api.contacts.GetContacts({ hash: r.c.zero }))
  );
  const ids = new Set((res.contacts ?? []).map((x) => String(x.userId)));
  return (res.users ?? [])
    .filter((u) => ids.has(String(u.id)))
    .map((u) => ({
      first_name: u.firstName ?? '',
      last_name: u.lastName ?? '',
      phone_number: u.phone ? `+${u.phone}` : '',
    }));
};

// A job for one chat: its state follows the whole export's Cancel, the
// state the per-chat run ends in is kept in `ended`.
const chatJob = (parent, entry, folder, options) => {
  const sub = {
    chat: entry.id,
    chatName: entry.name,
    options,
    folder,
    formats: parent.formats,
    messages: 0,
    total: null,
    files: 0,
    skipped: 0,
    failed: 0,
    bytes: 0,
    current: null,
    ended: null,
  };
  let end = null;
  Object.defineProperty(sub, 'state', {
    get: () => (parent.state === 'cancelling' ? 'cancelling' : 'running'),
    set: (state) => {
      end = state;
      sub.ended = state;
    },
  });
  return { sub, ended: () => end };
};

const SUMS = ['messages', 'files', 'skipped', 'failed', 'bytes'];

const exportChat = async (r, entry, index) => {
  const { job } = r;
  const folder = path.join(job.folder, 'chats', `chat_${pad(index + 1)}`);
  const base = Object.fromEntries(SUMS.map((k) => [k, job[k]]));
  const { sub, ended } = chatJob(job, entry, folder, r.value.chatOptions);
  const sync = () => {
    for (const k of SUMS) {
      job[k] = base[k] + sub[k];
    }
    job.current = sub.current;
  };
  job.chatName = entry.name;
  await execute(
    newRun({
      env: r.env,
      c: r.tc,
      job: sub,
      now: r.now,
      sleep: r.sleep,
      publish: async () => sync(),
    })
  );
  sync();
  job.current = null;
  return { ...entry, folder: `chats/chat_${pad(index + 1)}`, state: ended() };
};

const indexHtml = (title, rows) =>
  pageHtml({
    title,
    body: `<ul>\n${rows
      .map(
        (row) =>
          `<li>${row.href ? `<a href="${esc(row.href)}">${esc(row.text)}</a>` : esc(row.text)}</li>`
      )
      .join('\n')}\n</ul>\n`,
  });

const writeIndex = async (r, data) => {
  const { job } = r;
  const result = {
    about: 'Here is the data you requested. Handle with care.',
    ...(data.info ? { personal_information: data.info } : {}),
    ...(data.contacts
      ? { contacts: { about: 'Your contacts.', list: data.contacts } }
      : {}),
    chats: {
      about: 'Chats exported to the folders below.',
      list: data.chats.map((c) => ({
        name: c.name,
        type: c.type,
        id: Number(c.id.replace(/^-100|^-/, '')),
        folder: c.folder,
        exported: c.state === 'done',
      })),
    },
  };
  if (job.formats.includes('json')) {
    await fs.writeFile(
      path.join(job.folder, 'result.json'),
      `${JSON.stringify(result, null, 1)}\n`
    );
  }
  if (job.formats.includes('html')) {
    await fs.mkdir(path.join(job.folder, 'css'), { recursive: true });
    await fs.writeFile(path.join(job.folder, 'css', 'style.css'), EXPORT_CSS);
    const rows = [
      ...(data.info
        ? [
            {
              text: `${data.info.first_name} ${data.info.last_name} ${data.info.phone_number}`.trim(),
            },
          ]
        : []),
      ...(data.contacts ?? []).map((c) => ({
        text: `${c.first_name} ${c.last_name} ${c.phone_number}`.trim(),
      })),
      ...data.chats.map((c) => ({
        text: c.name,
        href: `${c.folder}/messages.html`,
      })),
    ];
    await fs.writeFile(
      path.join(job.folder, 'export_results.html'),
      indexHtml('Exported Data', rows)
    );
  }
};

const gather = async (r) => {
  const { job, value } = r;
  const data = { info: null, contacts: null, chats: [] };
  await fs.mkdir(job.folder, { recursive: true });
  job.phase = 'info';
  if (value.info && !stopping(r)) {
    data.info = await personalInfo(r);
  }
  job.phase = 'contacts';
  if (value.contacts && !stopping(r)) {
    data.contacts = await contactList(r);
  }
  job.phase = 'chats';
  const chats = stopping(r) ? [] : await listChats(r);
  job.chatsTotal = chats.length;
  for (const [i, entry] of chats.entries()) {
    if (stopping(r)) {
      break;
    }
    const done = await exportChat(r, entry, i);
    data.chats.push(done);
    job.chatsDone = i + 1;
    if (done.state === 'failed') {
      job.chatsFailed += 1;
    }
  }
  return data;
};

/** Runs the whole export; resolves to the state it ends in. */
export const runDataExport = async (r) => {
  const { job } = r;
  r.tc = { ...r.c, client: r.client };
  try {
    const data = await gather(r);
    job.phase = 'writing';
    await writeIndex(r, data);
    return stopping(r) ? 'cancelled' : 'done';
  } catch (error) {
    job.error = error;
    return stopping(r) ? 'cancelled' : 'failed';
  }
};

/**
 * "Export Telegram data", as Telegram Desktop has it in Settings → Advanced
 * (R-Y212; learned, never copied): the account's information, contacts and
 * the chats of the kinds the user picks (personal chats, bot chats, private
 * groups, private channels, public groups and channels) with a date range
 * and "include media up to N MB", read through a takeout session
 * (account.initTakeoutSession, requests wrapped in invokeWithTakeout,
 * account.finishTakeoutSession). Each chat is written by the per-chat export
 * (R-Y186, HTML and/or JSON) into a folder the server chooses under the
 * store directory's `exports` (never one the page names):
 * - `dataExportDefaults()` — `{ ok, job }`, the running or last export;
 * - `dataExportStart({ info, contacts, kinds, media, sizeLimitMb, from?,
 *   to?, formats })` — opens the takeout session first; Telegram may refuse
 *   with `{ ok: false, code: 'takeout-delay', seconds }`
 *   (TAKEOUT_INIT_DELAY_X), then starts it in the background → `{ ok, job }`;
 * - `dataExportStatus()` / `dataExportCancel()` / `dataExportReveal()`.
 * Only reads go to Telegram; no message text is ever logged.
 */

import os from 'node:os';
import path from 'node:path';
import { connected } from './telegram-stickers.js';
import {
  validFormats,
  validLimit,
  validRange,
  DEFAULT_LIMIT_MB,
  FORMATS,
  MEDIA_KEYS,
  active,
  exportRuntime,
  opener,
  revealOf,
} from './telegram-export.js';
import { dayOf } from './telegram-export-paths.js';
import { failure } from './telegram-export-run.js';
import { freeFolder } from './telegram-account-data-paths.js';
import {
  KINDS,
  delayOf,
  runDataExport,
  takeoutClient,
  takeoutFlags,
} from './telegram-account-data-run.js';

const bad = (code) => ({ ok: false, error: code, code });
const flag = (v, fallback) => (typeof v === 'boolean' ? v : fallback);

const plainObject = (v) =>
  Boolean(v) && typeof v === 'object' && !Array.isArray(v);

// Whether the fields have the right shapes (not yet whether they say
// enough to export anything).
const shapeOk = (r, kindsIn) =>
  plainObject(kindsIn) &&
  Object.entries(kindsIn).every(
    ([k, v]) => KINDS.includes(k) && typeof v === 'boolean'
  ) &&
  [r.media, r.info, r.contacts].every(
    (v) => v === undefined || typeof v === 'boolean'
  ) &&
  validLimit(r.sizeLimitMb ?? DEFAULT_LIMIT_MB) &&
  validRange(r.from ?? null, r.to ?? null) &&
  validFormats(r.formats);

/**
 * The request as `{ ok: true, value }`, or `{ ok: false, code:
 * 'bad-request' }`: `info`/`contacts` booleans, `kinds` (known keys,
 * booleans, at least one thing chosen), `media` boolean with a size limit of
 * 1 to 4000 MB, `from`/`to` as `YYYY-MM-DD` or none, one or both formats.
 */
export const parseDataExport = (request) => {
  const r = request ?? {};
  const kindsIn = r.kinds ?? {};
  const from = r.from ?? null;
  const to = r.to ?? null;
  const sizeLimitMb = r.sizeLimitMb ?? DEFAULT_LIMIT_MB;
  const kinds = Object.fromEntries(KINDS.map((k) => [k, kindsIn[k] === true]));
  const info = flag(r.info, true);
  const contacts = flag(r.contacts, true);
  const anything = info || contacts || Object.values(kinds).includes(true);
  if (!shapeOk(r, kindsIn) || !anything) {
    return bad('bad-request');
  }
  const media = r.media === true;
  return {
    ok: true,
    value: {
      info,
      contacts,
      kinds,
      media,
      sizeLimitMb,
      from,
      to,
      formats: FORMATS.filter((f) => r.formats.includes(f)),
      chatOptions: {
        media: Object.fromEntries(
          MEDIA_KEYS.map((k) => [k, media && k !== 'stickers' && k !== 'gifs'])
        ),
        sizeLimitMb,
        from,
        to,
      },
    },
  };
};

const snapshot = (job) =>
  job && {
    state: job.state,
    phase: job.phase,
    folder: job.folder,
    formats: job.formats,
    chatsTotal: job.chatsTotal,
    chatsDone: job.chatsDone,
    chatsFailed: job.chatsFailed,
    chatName: job.chatName,
    messages: job.messages,
    files: job.files,
    skipped: job.skipped,
    failed: job.failed,
    bytes: job.bytes,
    current: job.current,
    code: job.code ?? null,
    startedAt: job.startedAt,
    finishedAt: job.finishedAt ?? null,
  };

const newJob = (value, folder, at) => ({
  state: 'running',
  phase: 'starting',
  folder,
  formats: value.formats,
  chatsTotal: null,
  chatsDone: 0,
  chatsFailed: 0,
  chatName: null,
  messages: 0,
  files: 0,
  skipped: 0,
  failed: 0,
  bytes: 0,
  current: null,
  startedAt: new Date(at).toISOString(),
});

// Opens the session: `{ ok: true, id }`, or the failure to answer with
// (TAKEOUT_INIT_DELAY_X is `takeout-delay` with its seconds).
const openTakeout = async (c, value) => {
  const flags = takeoutFlags(value);
  try {
    const takeout = await c.client.invoke(
      new c.Api.account.InitTakeoutSession({
        ...flags,
        ...(value.media
          ? {
              files: true,
              fileMaxSize: c.helpers.returnBigInt(
                value.sizeLimitMb * 1024 * 1024
              ),
            }
          : {}),
      })
    );
    return { ok: true, id: takeout.id };
  } catch (error) {
    const seconds = delayOf(error);
    return seconds > 0
      ? { ok: false, error: 'takeout-delay', code: 'takeout-delay', seconds }
      : failure(error);
  }
};

export const createAccountData = (
  env,
  {
    userClient,
    mediaDir = null,
    home = os.homedir(),
    now = () => Date.now(),
    reveal = opener,
  }
) => {
  const { storeDir, sleep } = exportRuntime(env, mediaDir);
  let job = null;
  let starting = false;

  const finish = async (c, takeoutId, state) => {
    job.state = state;
    job.phase = 'finished';
    job.current = null;
    job.finishedAt = new Date(now()).toISOString();
    if (state === 'failed') {
      job.code = failure(job.error).code;
    }
    delete job.error;
    env.log?.({
      level: 'info',
      event: 'telegram_data_export_end',
      state,
      code: job.code ?? null,
      chats: job.chatsDone,
      messages: job.messages,
    });
    try {
      await c.client.invoke(
        new c.Api.InvokeWithTakeout({
          takeoutId,
          query: new c.Api.account.FinishTakeoutSession({
            success: state === 'done',
          }),
        })
      );
    } catch {
      // the session ends by itself; the export stands
    }
  };

  const launch = async (c, value, takeoutId) => {
    const base = storeDir ? path.join(storeDir, 'exports') : null;
    const folder = await freeFolder(
      base ?? path.join(home, 'Downloads', 'Telegram Desktop'),
      `DataExport_${dayOf(now())}`
    );
    job = newJob(value, folder, now());
    env.log?.({
      level: 'info',
      event: 'telegram_data_export_start',
      formats: value.formats,
    });
    const run = {
      env,
      c,
      client: takeoutClient(c, takeoutId),
      job,
      value,
      now,
      sleep,
    };
    // In the background: the page follows it by asking for the status.
    runDataExport(run)
      .then((state) => finish(c, takeoutId, state))
      .catch(() => {});
    return { ok: true, job: snapshot(job) };
  };

  const start = async (request) => {
    const parsed = parseDataExport(request);
    if (!parsed.ok) {
      return parsed;
    }
    if (starting || active(job)) {
      return bad('busy');
    }
    starting = true;
    try {
      return await connected(env, userClient, failure, async (c) => {
        const opened = await openTakeout(c, parsed.value);
        return opened.ok ? launch(c, parsed.value, opened.id) : opened;
      });
    } finally {
      starting = false;
    }
  };

  return {
    dataExportDefaults: async () => ({ ok: true, job: snapshot(job) }),
    dataExportStatus: async () => ({ ok: true, job: snapshot(job) }),
    dataExportStart: start,
    dataExportCancel: async () => {
      if (job?.state === 'running') {
        job.state = 'cancelling';
      }
      return { ok: true, job: snapshot(job) };
    },
    dataExportReveal: revealOf(() => job, reveal),
  };
};

/**
 * Four small account features, as Telegram Desktop has them (R-Y174;
 * learned, never copied):
 * - `archiveSettings()` — account.getGlobalPrivacySettings → `{ ok,
 *   settings: { archiveAndMute, keepUnmuted, keepFolders, hideReadMarks,
 *   requirePremium } }`;
 * - `setArchiveSettings({ ...those five booleans })` —
 *   account.setGlobalPrivacySettings with the settings read again and
 *   only these five changed, so the fields the page does not show (gifts
 *   button, paid messages price, disallowed gifts) are kept;
 * - `webSessions()` — account.getWebAuthorizations → `{ ok, sessions:
 *   [{ hash, domain, bot, browser, platform, ip, region, created,
 *   active }] }`; `webSessionReset({ hash })` —
 *   account.resetWebAuthorization; `webSessionsResetAll()` —
 *   account.resetWebAuthorizations;
 * - `savedPin({ peer, pinned })` — messages.toggleSavedDialogPin, a
 *   chat of Saved Messages pinned or unpinned;
 * - `savedReorder({ peers })` — messages.reorderPinnedSavedDialogs, the
 *   pinned chats of Saved Messages in a new order, the first on top
 *   (R-Y197; chats not named keep their pin: no `force`).
 * Telegram's errors become codes the page shows as text
 * (PREMIUM_ACCOUNT_REQUIRED → `premium-required`).
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';

export const ARCHIVE_FIELDS = {
  archiveAndMute: 'archiveAndMuteNewNoncontactPeers',
  keepUnmuted: 'keepArchivedUnmuted',
  keepFolders: 'keepArchivedFolders',
  hideReadMarks: 'hideReadMarks',
  requirePremium: 'newNoncontactPeersRequirePremium',
};
// The fields of GlobalPrivacySettings this page does not show.
const KEPT_FIELDS = [
  'displayGiftsButton',
  'noncontactPeersPaidStars',
  'disallowedGifts',
];

const CODES = {
  PREMIUM_ACCOUNT_REQUIRED: 'premium-required',
  HASH_INVALID: 'hash-invalid',
  PEER_ID_INVALID: 'no-access',
  FLOOD_WAIT: 'flood',
};
const failure = failureOf(CODES);
const bad = { ok: false, error: 'bad request', code: 'bad-request' };
const CHAT = /^-?\d{1,20}$/;
export const MAX_PINNED = 100;
// Chat ids, each once: the pinned chats in their new order.
const validPeers = (peers) =>
  Array.isArray(peers) &&
  peers.length > 0 &&
  peers.length <= MAX_PINNED &&
  peers.every((p) => typeof p === 'string' && CHAT.test(p)) &&
  new Set(peers).size === peers.length;
const HASH = /^-?\d{1,20}$/;
const text = (value) => String(value?.value ?? value ?? '');

/** The page's five switches from Telegram's GlobalPrivacySettings. */
export const settingsOf = (answer) =>
  Object.fromEntries(
    Object.entries(ARCHIVE_FIELDS).map(([key, field]) => [
      key,
      Boolean(answer?.[field]),
    ])
  );

const validSettings = (request) =>
  Object.keys(ARCHIVE_FIELDS).every(
    (key) => typeof request?.[key] === 'boolean'
  );

const iso = (seconds) =>
  Number(seconds) > 0 ? new Date(Number(seconds) * 1000).toISOString() : null;

const botName = (user) =>
  user?.firstName || user?.username || (user ? text(user.id) : '');

/** A WebAuthorization as the page lists it. */
export const webSessionOf = (a, users) => {
  const bot = users.get(text(a.botId));
  return {
    hash: text(a.hash),
    domain: a.domain ?? '',
    bot: botName(bot),
    botUsername: bot?.username ?? '',
    browser: a.browser ?? '',
    platform: a.platform ?? '',
    ip: a.ip ?? '',
    region: a.region ?? '',
    created: iso(a.dateCreated),
    active: iso(a.dateActive),
  };
};

export const createAccountExtras = (env, { userClient }) => {
  const doing = (key, use) =>
    connected(env, userClient, failure, (c) => runIn(env, key, () => use(c)));

  const archiveSettings = async () =>
    doing('archive-settings', async (c) => {
      const answer = await c.client.invoke(
        new c.Api.account.GetGlobalPrivacySettings()
      );
      return { ok: true, settings: settingsOf(answer) };
    });

  const setArchiveSettings = async (request = {}) => {
    if (!validSettings(request)) {
      return bad;
    }
    return doing('archive-settings', async (c) => {
      const now = await c.client.invoke(
        new c.Api.account.GetGlobalPrivacySettings()
      );
      const fields = {};
      for (const name of KEPT_FIELDS) {
        if (now?.[name] !== undefined) {
          fields[name] = now[name];
        }
      }
      for (const [key, field] of Object.entries(ARCHIVE_FIELDS)) {
        fields[field] = request[key];
      }
      const next = await c.client.invoke(
        new c.Api.account.SetGlobalPrivacySettings({
          settings: new c.Api.GlobalPrivacySettings(fields),
        })
      );
      return { ok: true, settings: settingsOf(next ?? fields) };
    });
  };

  const webSessions = async () =>
    doing('web-sessions', async (c) => {
      const answer = await c.client.invoke(
        new c.Api.account.GetWebAuthorizations()
      );
      const users = new Map((answer?.users ?? []).map((u) => [text(u.id), u]));
      return {
        ok: true,
        sessions: (answer?.authorizations ?? []).map((a) =>
          webSessionOf(a, users)
        ),
      };
    });

  const webSessionReset = async ({ hash } = {}) =>
    !HASH.test(String(hash ?? ''))
      ? bad
      : doing('web-sessions', async (c) => {
          await c.client.invoke(
            new c.Api.account.ResetWebAuthorization({
              hash: c.helpers.returnBigInt(String(hash)),
            })
          );
          return { ok: true };
        });

  const webSessionsResetAll = async () =>
    doing('web-sessions', async (c) => {
      await c.client.invoke(new c.Api.account.ResetWebAuthorizations());
      return { ok: true };
    });

  const savedPin = async ({ peer, pinned } = {}) =>
    !CHAT.test(String(peer ?? '')) || typeof pinned !== 'boolean'
      ? bad
      : doing('saved-pin', (c) =>
          env.connection.withPeer(c.client, String(peer), async (input) => {
            await c.client.invoke(
              new c.Api.messages.ToggleSavedDialogPin({
                ...(pinned ? { pinned: true } : {}),
                peer: new c.Api.InputDialogPeer({ peer: input }),
              })
            );
            return { ok: true, pinned };
          })
        );

  const savedReorder = async ({ peers } = {}) =>
    !validPeers(peers)
      ? bad
      : doing('saved-pin', async (c) => {
          const order = [];
          for (const peer of peers) {
            await env.connection.withPeer(c.client, peer, (input) => {
              order.push(new c.Api.InputDialogPeer({ peer: input }));
            });
          }
          await c.client.invoke(
            new c.Api.messages.ReorderPinnedSavedDialogs({ order })
          );
          return { ok: true };
        });

  return {
    archiveSettings,
    setArchiveSettings,
    webSessions,
    webSessionReset,
    webSessionsResetAll,
    savedPin,
    savedReorder,
  };
};

/**
 * Real-time Telegram for a connected user session.
 *
 * While the GramJS client is connected, Telegram pushes updates over the
 * same MTProto connection: new and edited messages, deletions, "read"
 * receipts and typing. `createTelegramLive` registers one raw handler on
 * each client the account opens and writes what the update means to the
 * store, as the same links a sync would write — so a message that arrives
 * live and the next sync agree, and nothing shows twice:
 *
 *   msg:telegram:<chat>:<id>   new / edited (`edited`) / deleted (`deleted`)
 *   read:telegram:<chat>       the chat's read and draft state:
 *                              `outboxMaxId`  the other side read our
 *                                             messages up to this id
 *                              `inboxMaxId`   we read theirs up to it
 *                              `unreadCount`  unread at `unreadTopId`
 *                                             (Telegram's count; newer
 *                                             ones are counted from links)
 *                              `unreadMentions`, `unreadReactions`
 *                                             (@ and ♥ not seen yet)
 *                              `draft`, `draftAt`  the cloud draft
 *   typing:telegram:<chat>:<user>
 *   requests:telegram:<chat>   the people waiting to join a group or
 *                              channel: `pending` and `recent` ({ id,
 *                              name }); the page's join requests bar
 *                              follows it (R-Y161)
 *   eph:telegram:<chat>:<id>   an ephemeral message, shown to this user only
 *                              (never part of the history, R-Y223)
 *   groupcall:telegram:<chat>  the chat's voice chat or live stream: `call`
 *                              (null once over) and `rev`, which grows
 *                              when its participants change (R-Y188)
 *
 * Updates missed while the connection was down come through the same
 * handler from the catch-up (./telegram-catchup.js); the background poll
 * stays as the last safety net.
 */

import { typingLink } from './live-links.js';
import { stampSourceLink } from './index.js';
import { messageSenderId, updateEffect } from './telegram-updates.js';
import { pollWriter } from './telegram-polls.js';
import { transcriptWriter } from './telegram-transcribe.js';
import { groupCallWriter } from './telegram-voice-chat-live.js';
import { ephemeralLive } from './telegram-ephemeral.js';
import { markDeleted as tombstone } from '../storage/soft-delete.js';

const SOURCE = 'telegram';

export const readLinkId = (chat) => `read:${SOURCE}:${chat}`;

const READ_FIELDS = [
  'outboxMaxId',
  'inboxMaxId',
  'unreadCount',
  'unreadTopId',
  'unreadMentions',
  'unreadReactions',
  // How Telegram lists the chat: muted until (Unix seconds, 0 not), its
  // place among the pinned (1 first, 0 not pinned), its folder (1 the
  // archive, 0 the main list).
  'muteUntil',
  'pinnedRank',
  'folder',
  // Marked unread by the user (R-Y97).
  'unreadMark',
  // A forum group: its messages are in topics (R-Y122).
  'forum',
];

/** One chat's read (and draft) state; only the given fields are set. */
export const readLink = (chat, fields = {}) => ({
  id: readLinkId(chat),
  tokens: ['read', SOURCE, String(chat)],
  kind: 'read',
  source: SOURCE,
  chat: String(chat),
  ...Object.fromEntries(
    READ_FIELDS.filter(
      (f) => fields[f] !== undefined && fields[f] !== null
    ).map((f) => [f, Number(fields[f]) || 0])
  ),
  ...(fields.draft !== undefined
    ? { draft: String(fields.draft ?? ''), draftAt: fields.draftAt ?? null }
    : {}),
});

const isoOf = (date) =>
  date ? new Date(Number(date) * 1000).toISOString() : null;

// What `telegramDialogLinks` needs to know about a chat, from a GramJS
// entity (a User, Chat or Channel).
export const dialogInfo = (chat, entity) => {
  const kind = entity?.className;
  const name = [entity?.firstName, entity?.lastName].filter(Boolean).join(' ');
  return {
    id: chat,
    entity,
    title: name || entity?.title || entity?.username || null,
    isUser: kind ? kind === 'User' : !String(chat).startsWith('-'),
    isGroup: kind === 'Chat' || Boolean(entity?.megagroup),
    isChannel: kind === 'Channel',
  };
};

/**
 * Our own messages being sent right now, by chat, with their text: the
 * copy Telegram echoes (another device's view, a catch-up) is matched to
 * the composer's bubble (`clientId`) instead of showing twice. This plays
 * the role of Telegram Web K's pendingByRandomId: GramJS does not expose
 * the random_id on the message it hands us.
 */
const createOwnMessages = () => {
  const own = new Map(); // chat -> [{ clientId, texts }]
  const expect = ({ chat, clientId, texts }) => {
    if (!clientId) {
      return () => {};
    }
    const entry = { clientId, texts: new Set(texts) };
    own.set(chat, [...(own.get(chat) ?? []), entry]);
    return () => {
      const rest = (own.get(chat) ?? []).filter((e) => e !== entry);
      if (rest.length > 0) {
        own.set(chat, rest);
      } else {
        own.delete(chat);
      }
    };
  };
  const clientIdOf = (chat, link) =>
    link.sender === 'me'
      ? ((own.get(chat) ?? []).find((e) => e.texts.has(link.body))?.clientId ??
        null)
      : null;
  return { expect, clientIdOf };
};

// The read markers, the cloud draft and typing of a chat, as links.
const chatStateWriters = ({ store, now }) => {
  // Read markers only move forward (Element never rewinds a receipt).
  const onRead = async ({ chat, maxId }) => {
    const before = await store.get(readLinkId(chat));
    if ((before?.outboxMaxId ?? 0) >= maxId) {
      return false;
    }
    await store.put({
      ...(before ?? {}),
      ...readLink(chat, { outboxMaxId: maxId }),
    });
    return false; // a marker, not a message: no refresh needed for it
  };

  // Each chat's newest message seen live: what Telegram counts as unread
  // after a read reaches up to it.
  const tops = new Map();
  const noteTop = (chat, id) => {
    if (chat && Number(id) > (tops.get(chat) ?? 0)) {
      tops.set(chat, Number(id));
    }
  };

  // We read the chat up to maxId (here or on another device). Telegram
  // says how many are still unread then (`stillUnread`, up to the chat's
  // newest message); without it what is still unread is newer than
  // maxId, so it is counted from the links.
  const onReadInbox = async ({ chat, maxId, stillUnread }) => {
    const before = await store.get(readLinkId(chat));
    const was = before?.inboxMaxId ?? 0;
    const counted = Number.isFinite(stillUnread);
    if (was > maxId || (was === maxId && !counted)) {
      return false;
    }
    const top = counted
      ? Math.max(maxId, before?.unreadTopId ?? 0, tops.get(chat) ?? 0)
      : maxId;
    await store.put({
      ...(before ?? {}),
      ...readLink(chat, {
        inboxMaxId: maxId,
        unreadCount: counted ? Math.max(0, stillUnread) : 0,
        unreadTopId: top,
      }),
    });
    return false;
  };

  // How Telegram lists the chat (R-Y68): a chat pinned goes first, the
  // others pinned in its folder one down; an order given is kept as is;
  // a chat archived or brought back is no longer pinned.
  const putListing = async (chat, fields) => {
    const before = await store.get(readLinkId(chat));
    await store.put({ ...(before ?? {}), ...readLink(chat, fields) });
  };
  const pinnedIn = (folder) =>
    store.query(
      (l) =>
        l?.kind === 'read' &&
        l.source === SOURCE &&
        Number(l.pinnedRank ?? 0) > 0 &&
        Number(l.folder ?? 0) === folder
    );
  const onListing = async ({
    chat,
    muteUntil,
    pinned,
    folder = 0,
    unreadMark,
  }) => {
    if (muteUntil !== undefined) {
      await putListing(chat, { muteUntil });
    }
    if (unreadMark !== undefined) {
      await putListing(chat, { unreadMark });
    }
    if (pinned === true) {
      for (const other of await pinnedIn(folder)) {
        if (other.chat !== chat) {
          await putListing(other.chat, { pinnedRank: other.pinnedRank + 1 });
        }
      }
    }
    if (pinned !== undefined) {
      await putListing(chat, { pinnedRank: pinned ? 1 : 0, folder });
    }
    return false;
  };
  const onPinnedOrder = async ({ folder, chats: order }) => {
    for (const other of await pinnedIn(folder)) {
      if (!order.includes(other.chat)) {
        await putListing(other.chat, { pinnedRank: 0 });
      }
    }
    for (const [at, chat] of order.entries()) {
      await putListing(chat, { pinnedRank: at + 1, folder });
    }
    return false;
  };
  const onFolders = async ({ peers }) => {
    for (const { chat, folder } of peers) {
      await putListing(chat, { folder, pinnedRank: 0 });
    }
    return false;
  };

  const onDraft = async ({ chat, text: draft, date }) => {
    const before = await store.get(readLinkId(chat));
    await store.put({
      ...(before ?? {}),
      ...readLink(chat, { draft, draftAt: isoOf(date) }),
    });
    return false;
  };

  // The typing status names who types, when the address book knows
  // them, so a group shows "Oleg is typing", not their id.
  const onTyping = async ({ chat, user, typing }) => {
    const person = await store.get(`person:${SOURCE}:${user}`);
    await store.put({
      ...typingLink({
        source: SOURCE,
        chat,
        user,
        state: typing ? 'typing' : 'idle',
        at: new Date(now()).toISOString(),
      }),
      ...(person?.name ? { name: person.name } : {}),
    });
    return false;
  };

  return {
    onRead,
    onReadInbox,
    noteTop,
    onListing,
    onPinnedOrder,
    onFolders,
    onDraft,
    onTyping,
  };
};

// The people waiting to join (R-Y161; learned, never copied): one link
// per chat, with the latest requesters named from the update's own
// entities or the address book.
export const requestsLinkId = (chat) => `requests:${SOURCE}:${chat}`;

const entityName = (entity) =>
  [entity?.firstName, entity?.lastName].filter(Boolean).join(' ') ||
  entity?.username ||
  null;

const requestsWriter = async (store, now, effect) => {
  const recent = [];
  for (const id of effect.recent.slice(0, 3)) {
    const person = await store.get(`person:${SOURCE}:${id}`);
    const entity = effect.entities?.get?.(String(id));
    recent.push({ id, name: person?.name || entityName(entity) || id });
  }
  await store.put({
    id: requestsLinkId(effect.chat),
    tokens: ['requests', SOURCE, String(effect.chat)],
    kind: 'requests',
    source: SOURCE,
    chat: String(effect.chat),
    pending: effect.pending,
    recent,
    at: new Date(now()).toISOString(),
  });
  return false;
};

// The folders changed elsewhere (R-Y172): one link whose `rev` grows with
// each change, so the page knows to ask for the folders again.
export const FOLDERS_LIVE_ID = `folders-live:${SOURCE}`;

const foldersLiveWriter = async (store, now, effect) => {
  const before = await store.get(FOLDERS_LIVE_ID);
  await store.put({
    id: FOLDERS_LIVE_ID,
    tokens: ['folders-live', SOURCE],
    kind: 'folders-live',
    source: SOURCE,
    rev: (Number(before?.rev) || 0) + 1,
    change: effect.change,
    folder: effect.id,
    at: new Date(now()).toISOString(),
  });
  return false;
};

// A deletion: those messages are marked `deleted` (kept, for the record);
// the one tombstone shape `{ at, by, reason }` (R-Z7).
const deletedLink = (link) =>
  tombstone(link, { by: 'telegram', reason: 'deleted-on-network' });

const deleteWriter = async (store, { chat, ids }) => {
  const wanted = new Set(ids.map(String));
  if (chat) {
    // A channel's ids are its own: each link is read by its id.
    const links = await Promise.all(
      [...wanted].map((id) => store.get(`msg:${SOURCE}:${chat}:${id}`))
    );
    const found = links.filter((l) => l && !l.deleted);
    for (const link of found) {
      await store.put(deletedLink(link));
    }
    return found.length > 0;
  }
  // Without a chat, the ids are the account-wide ones of private chats
  // and basic groups (never channels).
  const matches = await store.query(
    (l) =>
      l.id?.startsWith(`msg:${SOURCE}:`) &&
      !l.deleted &&
      !String(l.chat).startsWith('-100') &&
      wanted.has(l.id.split(':').pop())
  );
  for (const link of matches) {
    await store.put(deletedLink(link));
  }
  return matches.length > 0;
};

// Pinned or unpinned: the stored message carries Telegram's own
// `pinned` flag in `raw`, which the chat's pinned bar reads.
const pinWriter = async (store, { chat, ids, pinned }) => {
  let changed = false;
  for (const id of ids) {
    const link = await store.get(`msg:${SOURCE}:${chat}:${id}`);
    if (link && Boolean(link.raw?.pinned) !== pinned) {
      await store.put({ ...link, raw: { ...(link.raw ?? {}), pinned } });
      changed = true;
    }
  }
  return changed;
};

// Effects that name no one chat.
const MANY_CHATS = new Set([
  'delete',
  'pinned-order',
  'folders',
  'folders-live',
  'poll',
  'group-call',
  'group-call-people',
  'phone-call',
]);

// The log line for an update that could not be stored (R-Z14).
const reportFailure = (log, effect, error) =>
  log({
    level: 'error',
    event: 'telegram_update_failed',
    kind: effect.kind,
    code: error.code ?? null,
    error: error.message,
  });

/**
 * Apply live updates to the store.
 *   toLinks(dialog, messages)  the sync's message mapping
 *   chats                      Map chat -> dialog info, filled by syncs
 *   touch()                    marks the store changed (for pollers)
 */
export const createTelegramLive = ({
  store,
  toLinks,
  chats = new Map(),
  touch = async () => {},
  log = () => {},
  now = () => Date.now(),
  // A private call's update goes to the call machine (R-Y196).
  onPhoneCall = async () => {},
  // A live update whose store write failed: the update counters step
  // back so the next catch-up fetches it again (R-Z14).
  onFailed = () => {},
  track = (_update, done) => done,
}) => {
  const entityOf = (entities, id) =>
    id === null || id === undefined
      ? null
      : (entities?.get?.(String(id)) ?? null);

  const dialogFor = async (client, chat, entities) => {
    const known = chats.get(chat);
    if (known) {
      return known;
    }
    let entity = entityOf(entities, chat);
    if (!entity) {
      try {
        entity = await client?.getEntity?.(chat);
      } catch {
        entity = null; // a name is nice to have, not required
      }
    }
    const dialog = dialogInfo(chat, entity);
    if (entity) {
      chats.set(chat, dialog);
    }
    return dialog;
  };

  const own = createOwnMessages();

  const merge = async (link) => {
    const before = await store.get(link.id);
    const next = stampSourceLink({ ...(before ?? {}), ...link }, SOURCE);
    await store.put(next);
    return next;
  };

  const onMessage = async (client, { kind, chat, message, entities }) => {
    const dialog = await dialogFor(client, chat, entities);
    const sender = entityOf(entities, messageSenderId(message));
    const [link] = toLinks(dialog, [
      { ...message, sender: message.sender ?? sender },
    ]);
    if (!link) {
      return false;
    }
    const edited = kind === 'edit' ? isoOf(message.editDate) : null;
    const clientId = own.clientIdOf(chat, link);
    await merge({
      ...link,
      ...(edited ? { edited } : {}),
      ...(clientId ? { clientId } : {}),
    });
    if (kind === 'message' && link.sender !== 'me') {
      await stopTyping(chat, link.sender);
    }
    return true;
  };

  // Their message is here, so they are no longer typing it (as Telegram
  // apps show it, without waiting for the typing status to time out).
  const stopTyping = async (chat, user) => {
    const id = `typing:${SOURCE}:${chat}:${user}`;
    const before = await store.get(id);
    if (before?.state === 'typing') {
      await store.put({ ...before, state: 'idle' });
    }
  };

  const onDelete = (effect) => deleteWriter(store, effect);
  const onPin = (effect) => pinWriter(store, effect);

  const {
    onRead,
    onReadInbox,
    noteTop,
    onListing,
    onPinnedOrder,
    onFolders,
    onDraft,
    onTyping,
  } = chatStateWriters({ store, now });

  // What each kind of effect writes; true when the chat needs a refresh.
  const writers = {
    message: (client, effect) => {
      noteTop(effect.chat, effect.message?.id);
      return onMessage(client, effect);
    },
    edit: onMessage,
    // Ephemeral messages, shown to this user only (R-Y223).
    ...ephemeralLive({ store, merge, toLinks, dialogFor, entityOf }),
    delete: (_client, effect) => onDelete(effect),
    pin: (_client, effect) => onPin(effect),
    read: (_client, effect) => onRead(effect),
    'read-inbox': (_client, effect) => onReadInbox(effect),
    listing: (_client, effect) => onListing(effect),
    'pinned-order': (_client, effect) => onPinnedOrder(effect),
    folders: (_client, effect) => onFolders(effect),
    draft: (_client, effect) => onDraft(effect),
    typing: (_client, effect) => onTyping(effect),
    requests: (_client, effect) => requestsWriter(store, now, effect),
    'folders-live': (_client, effect) => foldersLiveWriter(store, now, effect),
    poll: (_client, effect) => pollWriter(store, effect),
    transcript: (_client, effect) => transcriptWriter(store, effect, now),
    'group-call': (_c, effect) => groupCallWriter(store, now, effect),
    'group-call-people': (_c, effect) => groupCallWriter(store, now, effect),
    'phone-call': async (client, effect) => {
      await onPhoneCall(client, effect);
      return false;
    },
  };

  const apply = async (client, effect) => {
    if (!effect?.chat && !MANY_CHATS.has(effect?.kind)) {
      return false;
    }
    const write = writers[effect.kind];
    return write ? write(client, effect) : false;
  };

  /**
   * One raw GramJS update. A failure is logged and swallowed, unless
   * `strict` (a catch-up replaying a difference): then it is thrown, so
   * the counter never moves past an update that was not stored (R-Z14).
   */
  const handle = async (client, update, { strict = false } = {}) => {
    const effect = updateEffect(update);
    if (!effect) {
      return;
    }
    try {
      if (await apply(client, effect)) {
        await touch();
      }
    } catch (error) {
      reportFailure(log, effect, error);
      if (strict) {
        throw error;
      }
      try {
        onFailed(update);
      } catch {
        // the hook must not turn a logged failure into a crash
      }
    }
  };

  /** Listen on a freshly connected client. */
  const attach = (client) => {
    if (typeof client?.addEventHandler !== 'function') {
      return;
    }
    // The saved update number waits for the write (`track`, R-Z7).
    client.addEventHandler((update) => track(update, handle(client, update)));
  };

  return {
    attach,
    handle,
    chats,
    expectOwn: own.expect,
    readInbox: onReadInbox,
    draft: onDraft,
  };
};

/**
 * The connected Telegram account — what makes "Connect" actually work.
 *
 * Connecting (the credential finder, the phone login or pasted keys) only
 * stores `secret:telegram:*` links. This service reads them and does the
 * work behind Chat and Contacts:
 *   - sync(): a user session (MTProto, GramJS) lists the dialogs, their
 *     recent messages and the address-book contacts; a bot token pulls
 *     `getUpdates`. Everything lands as ordinary `msg:telegram:*` and
 *     `person:telegram:*` links, so Chat and Contacts show it unchanged.
 *   - history(chat): more of one chat's messages, when it is opened.
 *   - post() / setTyping(): the chat composer sends through the same
 *     account — a user session as the user, a bot token as the bot.
 *   - markRead() / saveDraft(): reading a chat here marks it read on
 *     Telegram, and the composer's draft is the chat's cloud draft, as in
 *     Telegram's own apps (a user session only).
 *   - live updates (./telegram-account-live.js) and the catch-up after a
 *     gap or a reconnect (./telegram-catchup.js) keep a user session
 *     current; start() adds a light poll as the last safety net (only
 *     dialogs whose newest message changed are re-read).
 *
 * A user session wins over a bot token when both are stored: a bot only
 * sees messages sent to it, a user account sees their real chats. Bots
 * are never polled in the background — `getUpdates` would take updates
 * away from the bot's own process — and sync only when the user asks.
 *
 * Secret values never leave this module: results and logs carry counts,
 * chat ids and the account's public name only.
 */

import { createDialogState } from './telegram-dialog-state.js';
import { buildMessageLink } from './link.js';
import { personLink } from './live-links.js';
import { accountOf, gramjsClientFactory } from './telegram-mtproto.js';
import { readProxy } from './telegram-proxy.js';
import { createTelegramBotLive } from './telegram.js';
import { stampSourceLink } from './index.js';
import { putAll } from '../storage/universal.js';
import {
  createTelegramLive,
  dialogInfo,
  readLink,
} from './telegram-account-live.js';
import { BACKFILL_EVERY_MS, createBackfill } from './telegram-backfill.js';
import { createTelegramCatchUp, rewindPts } from './telegram-catchup.js';
import { createChannelSync } from './telegram-channels.js';
import {
  createFetchQueue,
  floodSeconds,
  rawMessage,
} from './telegram-history.js';
import { createPeers } from './telegram-peers.js';
import { createActions } from './telegram-actions.js';
import { createPageReader, dialogsCursor } from './telegram-pages.js';
import { messageSenderId } from './telegram-updates.js';
import { statusFields } from './telegram-emoji-status.js';
import {
  nameForwards,
  repairSenders,
  rereadUnsupported,
} from './telegram-repair.js';
import {
  MAX_MESSAGE_LENGTH,
  sendError,
  sendText,
  formattedParts,
} from './telegram-send.js';
import { rawEntities } from './telegram-format.js';
import {
  paidField,
  validSendAs,
  withSendAs,
} from './telegram-send-as-client.js';
import { previewFields } from './telegram-link-preview.js';
import { EFFECT_ID } from './telegram-effects.js';
import { GENERAL_TOPIC, inTopicOnly } from '../web/forum-topics.js';
import {
  importTelegram,
  installTelegramLayer,
  LAYER,
  SCHEMA_REV,
} from './telegram-layer.js';

import { richPlainText } from './telegram-instant-view-shape.js';

const SOURCE = 'telegram';
export const TELEGRAM_SYNC_ID = 'sync:telegram';
// The address book changes seldom; Telegram turns down asking for it
// often (R-Y34).
const CONTACTS_EVERY_MS = 6 * 60 * 60_000;
// Listing the dialogs so GramJS knows a chat: at most this often.
const PEER_LOOKUP_EVERY_MS = 10 * 60_000;
// The chat list is re-read this often by the poll; live updates and the
// catch-up bring new messages in between (R-Y24).
const DIALOGS_EVERY_MS = 5 * 60_000;
// A channel's gap re-reads the dialogs; no more often than this.
const RESYNC_EVERY_MS = 15_000;
const CONNECTION = { 1: 'connected', 0: 'broken', '-1': 'disconnected' };

const secretValue = (link) =>
  link?.value ?? link?.token ?? link?.body ?? link?.text ?? null;

/** The stored credential to use: a user session first, else a bot token. */
export const readTelegramCredentials = async (store) => {
  const read = async (name) =>
    secretValue(await store.get(`secret:telegram:${name}`));
  const [session, apiId, apiHash, token] = await Promise.all([
    read('user-session'),
    read('api-id'),
    read('api-hash'),
    read('bot-token'),
  ]);
  if (session) {
    return { kind: 'user', session, apiId, apiHash };
  }
  if (token) {
    return { kind: 'bot', token };
  }
  return null;
};

// GramJS ids are big-integer objects (or BigInt); chats are addressed by
// their plain decimal string, which GramJS also accepts as a peer.
const idText = (value) =>
  value === null || value === undefined ? null : String(value.value ?? value);

const fullName = (entity) => {
  if (!entity) {
    return null;
  }
  const name = [entity.firstName, entity.lastName].filter(Boolean).join(' ');
  return name || entity.title || entity.username || null;
};

const chatTypeOf = (dialog) => {
  if (dialog.isUser) {
    return 'personal_chat';
  }
  return dialog.isChannel && !dialog.isGroup ? 'channel' : 'group';
};

const isoOf = (date) => {
  if (!date) {
    return undefined;
  }
  const ms = date instanceof Date ? date.getTime() : Number(date) * 1000;
  return new Date(ms).toISOString();
};

// A media message without a caption still shows up in the chat.
// A rich message (layer 232, R-Y220) has no text of its own: its blocks'
// words stand in for it (the chat list, search), and it is never dropped.
const richWords = (message) => {
  if (!message.richMessage) {
    return '';
  }
  try {
    return richPlainText(message.richMessage) || '…';
  } catch {
    return '…';
  }
};

const bodyOf = (message) =>
  message.message || richWords(message) || (message.media ? '📎' : '');

// A service message (a join, a pin, a call) has no text: what happened
// is its action's name, and the chat shows it as a line of its own.
const serviceOf = (message) => message.action?.className ?? null;

/** One dialog's GramJS messages as `msg:telegram:<chat>:<id>` links. */
// Who a forwarded message came from, by name, while GramJS knows the
// chat or person (the app names the rest from its chat list).
const forwardedFromOf = (message) => {
  if (!message.fwdFrom) {
    return undefined;
  }
  try {
    const forward = message.forward;
    const name =
      message.fwdFrom.fromName ??
      forward?.chat?.title ??
      fullName(forward?.sender);
    return name ? { name } : undefined;
  } catch {
    return undefined;
  }
};

/**
 * What the dialog's entity says about writing to it (R-Z7): a bot, a deleted
 * account, a chat we left. Only true flags are returned; the autopilot's
 * planner skips such chats (../automation/safety.js). Telegram does not say
 * in a dialog whether the other side blocked us: that is not stored.
 */
export const reachabilityOf = (entity) => ({
  ...(entity?.bot ? { bot: true } : {}),
  ...(entity?.deleted ? { deletedAccount: true } : {}),
  ...(entity?.left ? { left: true } : {}),
});

export const telegramDialogLinks = (dialog, messages = []) => {
  const chat = idText(dialog.id);
  const chatType = chatTypeOf(dialog);
  const reach = reachabilityOf(dialog.entity);
  const chatName = dialog.title ?? dialog.name ?? fullName(dialog.entity);
  return messages
    .filter((m) => m && m.id !== undefined && (bodyOf(m) || serviceOf(m)))
    .map((m) => {
      const service = serviceOf(m);
      const mine = Boolean(m.out);
      // In a forum topic, naming only the topic's first message is being
      // in the topic, not answering it (R-Y122).
      const replyId = inTopicOnly(m.replyTo) ? null : m.replyTo?.replyToMsgId;
      const link = buildMessageLink({
        source: SOURCE,
        externalId: `${chat}:${m.id}`,
        sender: mine ? 'me' : (messageSenderId(m) ?? chat),
        chat,
        body: bodyOf(m),
        timestamp: isoOf(m.date),
        replyTo: replyId ? `${chat}:${replyId}` : null,
        chatType,
        chatName,
        ...reach,
        senderName: mine
          ? null
          : (fullName(m.sender) ?? (dialog.isUser ? chatName : null)),
        forwardedFrom: forwardedFromOf(m),
      });
      // Everything Telegram said about it, for offline analysis (R-Y28);
      // the author's emoji status, shown by their name (R-Y162).
      return {
        ...link,
        ...(service ? { service } : {}),
        ...(mine ? {} : statusFields(m.sender, 'senderEmoji')),
        raw: rawMessage(m),
      };
    });
};

/** Address-book users (and private-chat partners) as `person:` links. */
export const telegramPersonLinks = (users = [], { contact = true } = {}) =>
  users
    .filter((u) => u && !u.self && !u.deleted && u.id !== undefined)
    .map((u) => ({
      ...personLink({
        source: SOURCE,
        user: idText(u.id),
        name: fullName(u),
        handle: u.username ?? null,
      }),
      ...(contact ? { contact: true } : {}),
      ...(u.bot ? { bot: true } : {}),
      ...statusFields(u, 'emoji'),
    }));

// A GramJS entity as the dialog shape `telegramDialogLinks` reads.
const dialogOfEntity = (chat, entity) => {
  const kind = entity?.className;
  const megagroup = Boolean(entity?.megagroup);
  return {
    id: chat,
    entity,
    title: fullName(entity),
    isUser: kind === 'User',
    isGroup: kind === 'Chat' || megagroup,
    isChannel: kind === 'Channel',
  };
};

// Re-put a link only when what it shows changed, so a re-sync does not
// re-announce every old message to the store's subscribers. Links with
// the same id merge in order (a chat partner, then the address book).
const SHOWN_FIELDS = [
  'body',
  'name',
  'handle',
  'chatName',
  'senderName',
  'senderEmojiStatus',
  'senderEmojiUntil',
  'emojiStatus',
  'emojiUntil',
  'outboxMaxId',
  'inboxMaxId',
  'unreadCount',
  'unreadTopId',
  'unreadMentions',
  'unreadReactions',
  'muteUntil',
  'pinnedRank',
  'folder',
  'unreadMark',
  'draft',
  'bot',
  'left',
  'deletedAccount',
];
// A forward's source named now, where it was not before.
const namesForward = (before, link) =>
  Boolean(link.forwardedFrom?.name) &&
  before.forwardedFrom?.name !== link.forwardedFrom.name;

const writeChanged = async (store, links) => {
  const byId = new Map();
  for (const link of links) {
    byId.set(link.id, { ...(byId.get(link.id) ?? {}), ...link });
  }
  const fresh = [];
  for (const link of byId.values()) {
    const before = await store.get(link.id);
    const changed =
      !before ||
      SHOWN_FIELDS.some((f) => (before[f] ?? null) !== (link[f] ?? null)) ||
      (link.contact && !before.contact) ||
      namesForward(before, link) ||
      (link.raw !== undefined &&
        JSON.stringify(before.raw ?? null) !== JSON.stringify(link.raw));
    if (changed) {
      fresh.push(stampSourceLink({ ...(before ?? {}), ...link }, SOURCE));
    }
  }
  await putAll(store, fresh);
  return fresh.length;
};

// Every Telegram chat in the store with its type and newest message —
// for the background download when the server has no chat index.
const storedChats = async (store) => {
  const chats = new Map();
  for (const link of await store.query(
    (l) => l?.source === SOURCE && l.id?.startsWith('msg:')
  )) {
    const chat = String(link.chat);
    const known = chats.get(chat);
    if (!known || String(link.timestamp) > String(known.at)) {
      chats.set(chat, { chat, chatType: link.chatType, at: link.timestamp });
    }
  }
  return [...chats.values()];
};

const codeError = (code, message) =>
  Object.assign(new Error(message), { code });

const PUBLIC_FIELDS = [
  'kind',
  'account',
  'at',
  'changedAt',
  'chats',
  'written',
  'contacts',
  'error',
  'code',
  'connection',
  'dialogsComplete',
  'unreachableSince',
];

// Telegram unreachable this long shows as Offline in the header (R-Y96);
// meanwhile everything keeps being retried, as Telegram's apps do.
export const OFFLINE_AFTER_MS = 60_000;
// Telegram answered but asked to wait: not a lost connection.
const askedToWait = (error) =>
  error?.code === 'flood-wait' || floodSeconds(error) > 0;
// What only signing in again fixes.
const NEEDS_LOGIN =
  /AUTH_KEY_UNREGISTERED|AUTH_KEY_INVALID|SESSION_REVOKED|SESSION_EXPIRED|USER_DEACTIVATED/;

/** Whether Telegram has been out of reach for long, and whether only a new sign-in helps. */
export const reachability = (link, at) => {
  const since = Date.parse(link?.unreachableSince ?? '');
  return {
    offline: Number.isFinite(since) && at - since >= OFFLINE_AFTER_MS,
    needsLogin: NEEDS_LOGIN.test(`${link?.code ?? ''} ${link?.error ?? ''}`),
  };
};

const publicStatus = (link = {}) =>
  Object.fromEntries(PUBLIC_FIELDS.map((f) => [f, link?.[f] ?? null]));

// One connected GramJS client per stored session, reused across requests.
// `onOpen(client, me)` runs once per new client (live updates attach
// there). Chats are addressed by their stored input peer (`peers`).
// GramJS drops an answer holding a type its schema does not know, and
// says so only at "info": the request then waits until it is given up
// as stuck. Which constructor, in the log (never the data).
const UNDECODABLE =
  /^(?:Type (-?\d+) not found|Received response without parent request)/;
export const watchUndecodable = (client, log) => {
  const logger = client?._log;
  if (!logger?.info || !log) {
    return;
  }
  const info = logger.info.bind(logger);
  logger.info = (message) => {
    const found = UNDECODABLE.exec(String(message));
    if (found) {
      log({
        level: 'warn',
        event: 'telegram_type_unknown',
        constructor: found[1]
          ? (Number(found[1]) >>> 0).toString(16).padStart(8, '0')
          : null,
      });
    }
    info(message);
  };
};

// Every dialog, the archived ones too, each one's peer stored: a chat
// beyond the recent ones (an old conversation an automation writes to)
// is then found by its stored peer (R-Y85).
const lookupAllDialogs = (env, client) =>
  env.queue.run('dialogs:lookup', 'list', async () => {
    let listed = 0;
    for (const params of [{}, { folder: 1 }]) {
      const dialogs = [...((await client.getDialogs(params)) ?? [])];
      await env.pages?.remember(dialogs);
      listed += dialogs.length;
    }
    env.log?.({ level: 'info', event: 'telegram_dialogs_lookup', listed });
    return listed;
  });

export const createUserConnection = ({
  clientFactory,
  dialogLimit,
  log,
  onOpen,
  peers,
  request,
  now,
  lookup = (client) =>
    request('dialogs:lookup', () => client.getDialogs({ limit: dialogLimit })),
}) => {
  let lookedUpAt = -Infinity;
  let connection = null; // { key, client, me }
  let opening = null; // { key, promise }: the open in flight, shared
  let generation = 0; // a disconnect during an open makes it stale
  // GramJS's disconnect() leaves the client's update loop running: its
  // next ping fails and reconnects it, handlers and all. destroy() ends
  // the loop, so a dropped client is really gone.
  const end = async (client) => {
    try {
      await (client?.destroy ?? client?.disconnect)?.call(client);
    } catch {
      // Already gone.
    }
  };
  const disconnect = async () => {
    generation += 1;
    const current = connection;
    connection = null;
    await end(current?.client);
  };
  const connect = async (creds, key) => {
    await disconnect();
    const mine = generation;
    const client = await clientFactory({
      apiId: creds.apiId,
      apiHash: creds.apiHash,
      session: creds.session,
    });
    client.setLogLevel?.('error');
    watchUndecodable(client, log);
    try {
      await client.connect();
      const me = accountOf(await client.getMe());
      if (mine !== generation) {
        throw codeError('telegram-reconnect', 'the connection was dropped');
      }
      connection = { key, client, me };
      onOpen?.(client, me);
      return connection;
    } catch (error) {
      await end(client);
      throw error;
    }
  };
  // One client at a time: callers arriving while it opens share it.
  const open = async (creds) => {
    if (!creds.apiId || !creds.apiHash) {
      throw codeError(
        'needs-api-credentials',
        'this Telegram session has no api_id/api_hash stored; sign in with your phone once (Connections → Telegram) to add them'
      );
    }
    const key = `${creds.apiId}:${creds.session}`;
    if (connection?.key === key) {
      return connection;
    }
    if (opening?.key !== key) {
      const promise = connect(creds, key).finally(() => {
        if (opening?.promise === promise) {
          opening = null;
        }
      });
      opening = { key, promise };
    }
    return opening.promise;
  };
  // The stored input peer when there is one. Otherwise GramJS resolves
  // a bare chat id only for peers it has seen: the dialogs are listed
  // (`lookup`: all of them, each one's peer stored, so an old chat is
  // found and never looked up again) — at most every ten minutes, so an
  // unknown chat never costs a request each time.
  const withPeer = async (client, chat, use) => {
    const stored = await peers?.input(chat).catch(() => null);
    try {
      return await use(stored ?? chat);
    } catch (error) {
      const unknown = /input entity|PEER_ID_INVALID/i.test(error.message ?? '');
      if (!unknown || now() - lookedUpAt < PEER_LOOKUP_EVERY_MS) {
        throw error;
      }
      lookedUpAt = now();
      await lookup(client);
      const found = await peers?.input(chat).catch(() => null);
      return use(found ?? chat);
    }
  };
  return { open, disconnect, withPeer };
};

const readContacts = async (client, { importer, log, queue }) => {
  try {
    if (typeof client.getContacts === 'function') {
      return await queue.run('contacts', 'background', () =>
        client.getContacts()
      );
    }
    const { Api, helpers } = await importer();
    const result = await queue.run('contacts', 'background', () =>
      client.invoke(
        new Api.contacts.GetContacts({ hash: helpers.returnBigInt(0) })
      )
    );
    return result?.users ?? [];
  } catch (error) {
    log({
      level: 'warn',
      event: 'telegram_contacts_failed',
      code: error.code ?? null,
      error: error.message,
    });
    return null;
  }
};

// How Telegram lists a chat: muted, pinned (its place, from `rank`),
// archived.
const listing = (dialog, rank) => {
  const state = dialog.dialog ?? {};
  const pinned = Boolean(dialog.pinned ?? state.pinned);
  return {
    muteUntil: Number(state.notifySettings?.muteUntil ?? 0) || 0,
    ...(rank === undefined ? {} : { pinnedRank: pinned ? rank : 0 }),
    folder: Number(dialog.folderId ?? state.folderId ?? 0) === 1 ? 1 : 0,
    unreadMark: Boolean(dialog.unreadMark ?? state.unreadMark),
    // A forum group (R-Y122).
    forum: Boolean(dialog.entity?.forum),
  };
};

/**
 * Each listed dialog's place among the pinned of its folder, 1 first
 * (Telegram lists the pinned first, in their order).
 */
export const pinnedRanks = (listed) => {
  const ranks = new Map();
  const next = new Map();
  for (const dialog of listed) {
    const pinned = Boolean(dialog?.pinned ?? dialog?.dialog?.pinned);
    const folder = Number(dialog?.folderId ?? dialog?.dialog?.folderId ?? 0);
    const rank = pinned ? (next.get(folder) ?? 0) + 1 : 0;
    if (pinned) {
      next.set(folder, rank);
    }
    ranks.set(dialog, rank);
  }
  return ranks;
};

const dialogReadLink = (chat, dialog, rank) => {
  const state = dialog.dialog ?? {};
  const draft = state.draft;
  return readLink(chat, {
    ...listing(dialog, rank),
    outboxMaxId: state.readOutboxMaxId,
    inboxMaxId: state.readInboxMaxId,
    unreadCount: dialog.unreadCount ?? state.unreadCount,
    unreadTopId: dialog.message?.id ?? state.topMessage,
    unreadMentions: state.unreadMentionsCount,
    unreadReactions: state.unreadReactionsCount,
    draft: draft?.message ?? '',
    draftAt: draft?.date ? isoOf(draft.date) : null,
  });
};

// The recent dialogs; only those whose newest message changed since the
// last sync (`tops`, updated in place) are read again, and then only what
// came after the stored messages (`env.pages.readNew`).
const readDialogs = async (
  env,
  client,
  { dialogs, messages, tops, chats: known }
) => {
  const links = [];
  const covers = [];
  const partners = [];
  let chats = 0;
  const listed = [
    ...((await env.queue.run('dialogs:first', 'list', () =>
      client.getDialogs({ limit: dialogs })
    )) ?? []),
  ];
  await env.pages.remember(listed);
  const ranks = pinnedRanks(listed);
  for (const dialog of listed) {
    const chat = idText(dialog.id);
    if (!chat) {
      continue;
    }
    chats += 1;
    known?.set(chat, dialogInfo(chat, dialog.entity));
    links.push(dialogReadLink(chat, dialog, ranks.get(dialog)));
    if (dialog.isUser && dialog.entity) {
      partners.push(dialog.entity);
    }
    const top = idText(dialog.message?.id);
    if (top && tops[chat] === top) {
      continue;
    }
    const read = await env.pages.readNew(client, dialog, chat, {
      limit: messages,
      since: tops[chat],
      priority: 'list',
    });
    links.push(...read.links);
    covers.push(read.cover);
    if (top) {
      tops[chat] = top;
    }
  }
  links.push(...telegramPersonLinks(partners, { contact: false }));
  return { links, covers, chats, listed };
};

// The address book is read for a new account and every
// CONTACTS_EVERY_MS otherwise — counted from the last try, so a refusal
// is not asked again on every sync.
const contactsDue = (state, { sameAccount, now }) =>
  !sameAccount ||
  now() -
    Math.max(
      Date.parse(state.contactsAt ?? '') || 0,
      Date.parse(state.contactsTriedAt ?? '') || 0
    ) >=
    CONTACTS_EVERY_MS;

const syncUser = async (env, creds, state, { dialogs, messages }) => {
  const { client, me } = await env.connection.open(creds);
  // Another account than last time: forget what was seen. The same one
  // keeps it even on a full sync: what is stored is not read again.
  const sameAccount = Boolean(state.account?.id) && state.account.id === me.id;
  const tops = sameAccount ? { ...(state.tops ?? {}) } : {};
  const { links, covers, chats, listed } = await readDialogs(env, client, {
    dialogs,
    messages,
    tops,
    chats: env.live?.chats,
  });
  let contacts = state.contacts ?? 0;
  let contactsAt = state.contactsAt ?? null;
  let contactsTriedAt = state.contactsTriedAt ?? null;
  if (contactsDue(state, { sameAccount, now: env.now })) {
    contactsTriedAt = new Date(env.now()).toISOString();
    const users = await readContacts(client, env);
    if (users) {
      links.push(...telegramPersonLinks(users));
      contacts = users.filter((u) => u && !u.self).length;
      contactsAt = new Date(env.now()).toISOString();
    }
  }
  await putAll(env.store, covers);
  // The chat list's next page starts after the furthest one read.
  const keepCursor = sameAccount && state.dialogsCursor;
  return {
    kind: 'user',
    account: me,
    chats,
    contacts,
    contactsAt,
    contactsTriedAt,
    tops,
    dialogsAt: new Date(env.now()).toISOString(),
    dialogsCursor: keepCursor ? state.dialogsCursor : dialogsCursor(listed),
    dialogsComplete: keepCursor
      ? Boolean(state.dialogsComplete)
      : listed.length < dialogs,
    written: await writeChanged(env.store, links),
  };
};

const syncBot = async (env, creds, state) => {
  const pulled = await env.botLive.pullMessages({
    token: creds.token,
    offset: state.offset ?? undefined,
    limit: 100,
  });
  const links = pulled.links ?? [];
  return {
    kind: 'bot',
    account: state.account ?? null,
    chats: new Set(links.map((l) => l.chat)).size,
    contacts: 0,
    offset: pulled.nextOffset ?? state.offset ?? null,
    written: await writeChanged(env.store, links),
  };
};

const recordSync = async (store, patch) => {
  const before = (await store.get(TELEGRAM_SYNC_ID)) ?? {};
  const link = {
    ...before,
    ...patch,
    id: TELEGRAM_SYNC_ID,
    tokens: ['sync', SOURCE],
    kind: patch.kind ?? before.kind ?? null,
    source: SOURCE,
  };
  await store.put(link);
  return link;
};

const runSync = async (env, { full, reason, dialogs, messages }) => {
  const { store, now, log } = env;
  const started = now();
  const creds = await readTelegramCredentials(store);
  if (!creds) {
    return { ...publicStatus(), connected: false };
  }
  const state = (await store.get(TELEGRAM_SYNC_ID)) ?? {};
  const at = new Date(started).toISOString();
  try {
    const result =
      creds.kind === 'user'
        ? await syncUser(env, creds, state, { full, dialogs, messages })
        : await syncBot(env, creds, state);
    const changedAt =
      result.written > 0 ? new Date(now()).toISOString() : state.changedAt;
    const link = await recordSync(store, {
      ...result,
      at,
      changedAt: changedAt ?? null,
      error: null,
      code: null,
      unreachableSince: null,
    });
    log({
      event: 'telegram_sync',
      kind: creds.kind,
      reason,
      chats: result.chats,
      written: result.written,
      contacts: result.contacts,
      duration_ms: now() - started,
    });
    return { ...publicStatus(link), connected: true };
  } catch (error) {
    // Asked to wait: the next tick asks again; nothing to show or drop.
    if (askedToWait(error)) {
      log({
        level: 'warn',
        event: 'telegram_sync_waits',
        kind: creds.kind,
        reason,
        seconds: floodSeconds(error) || error.retryAfter || null,
      });
      return { ...publicStatus(state), connected: true };
    }
    await env.connection.disconnect();
    const link = await recordSync(store, {
      kind: creds.kind,
      at,
      error: error.message,
      code: error.code ?? error.errorMessage ?? 'sync-failed',
      unreachableSince: state.unreachableSince ?? at,
    });
    log({
      level: 'error',
      event: 'telegram_sync_failed',
      kind: creds.kind,
      reason,
      error: error.message,
    });
    return { ...publicStatus(link), connected: true };
  }
};

// The reply header of a message we just sent; in a forum topic it says
// so, as Telegram's echo will (R-Y122).
const sentReply = (replyTo, quote, topic) => {
  const inTopic = topic && topic !== GENERAL_TOPIC;
  return replyTo || inTopic
    ? {
        replyToMsgId: replyTo ?? topic,
        ...(inTopic ? { forumTopic: true, replyToTopId: topic } : {}),
        ...(quote ? { quote: true, quoteText: quote } : {}),
      }
    : undefined;
};

// The same link the next sync gives a message we just sent, so it is
// never shown twice. Its full data comes with Telegram's echo of it.
const sentLink = (
  chat,
  messageId,
  text,
  at,
  { replyTo = null, quote = null, topic = null, entities = [] } = {}
) => {
  if (!messageId) {
    return null;
  }
  const reply = sentReply(replyTo, quote, topic);
  // GramJS gives users positive ids, groups and channels negative ones.
  const [link] = telegramDialogLinks(
    { id: chat, isUser: !chat.startsWith('-') },
    [{ id: messageId, out: true, message: text, date: at, replyTo: reply }]
  );
  const { raw: _raw, ...known } = link;
  // The quote and the formatting show at once; the rest of `raw` comes
  // with the echo.
  const raw = {
    ...(reply ? { replyTo: reply } : {}),
    ...(entities.length > 0 ? { entities: rawEntities(entities) } : {}),
  };
  return Object.keys(raw).length > 0 ? { ...known, raw } : known;
};

// Telegram's message length limit (help.getConfig), once per client.
const lengthLimits = new WeakMap();
const messageLengthMax = async (client, Api) => {
  if (!lengthLimits.has(client)) {
    const ask =
      Api?.help?.GetConfig && typeof client.invoke === 'function'
        ? client
            .invoke(new Api.help.GetConfig())
            .then((config) => Number(config?.messageLengthMax) || null)
            .catch(() => null)
        : Promise.resolve(null);
    lengthLimits.set(client, ask);
  }
  return (await lengthLimits.get(client)) ?? MAX_MESSAGE_LENGTH;
};

// Send as the user: exactly once (random_id), formatted, long text in
// parts; returns the network's links for what was sent.
const postAsUser = async (
  env,
  creds,
  {
    chat,
    text,
    clientId,
    replyTo,
    replyQuote = null,
    topic = null,
    silent,
    scheduleDate,
    sendAs,
    allowPaidStars,
    preview = null,
    effect,
  }
) => {
  const { client: own } = await env.connection.open(creds);
  // Sent as another identity (R-Y141).
  const client = await withSendAs(env, own, sendAs, allowPaidStars).catch(
    (error) => {
      throw sendError(error);
    }
  );
  const { Api, helpers } = await env.importer().catch(() => ({}));
  const maxLength = await messageLengthMax(client, Api);
  const release = env.live.expectOwn({
    chat,
    clientId,
    texts: formattedParts(text, maxLength).map((part) => part.text),
  });
  let sent;
  try {
    sent = await env.connection.withPeer(client, chat, (peer) =>
      sendText({
        client,
        Api,
        helpers,
        peer,
        text,
        clientId,
        maxLength,
        log: env.log,
        replyTo,
        replyQuote,
        topic,
        silent,
        scheduleDate,
        effect,
        preview,
        onResult: (result) => env.catchUp?.observeResult(result),
      })
    );
  } catch (error) {
    throw sendError(error);
  } finally {
    release();
  }
  // The send cleared the chat's cloud draft (`clear_draft`); so does its
  // read link, or the composer would take the sent text back as a draft.
  await Promise.resolve(
    env.live.draft?.({ chat, text: '', date: Math.floor(env.now() / 1000) })
  ).catch(() => {});
  if (scheduleDate) {
    // Held by Telegram, not in the chat: its scheduled ones (R-Y102).
    env.actions?.scheduledChanged?.(chat);
    return { ok: true, scheduled: true, chat, parts: sent.length, links: [] };
  }
  if (sent.some((part) => part.duplicate)) {
    // An earlier try got through but its answer was lost: the catch-up
    // brings that message in.
    env.catchUp?.run('duplicate').catch(() => {});
  }
  const at = new Date(env.now());
  const links = sent
    .map((part, index) =>
      sentLink(chat, idText(part.id), part.text, part.date ?? at, {
        replyTo: index === 0 ? replyTo : null,
        quote: index === 0 ? replyQuote : null,
        topic,
        entities: part.entities ?? [],
      })
    )
    .filter(Boolean);
  return {
    ok: true,
    messageId: idText(sent.at(-1)?.id),
    chat,
    parts: sent.length,
    ...(sent.some((part) => part.duplicate) ? { duplicate: true } : {}),
    ...(links.length > 0 ? { link: links.at(-1), links } : {}),
  };
};

// A draft's reply, quote, sound and time, as postAsUser takes them.
const draftOptions = (draft) => {
  const replyTo = Number(draft.replyTo);
  const topic = Number(draft.topic);
  return {
    replyTo: Number.isInteger(replyTo) && replyTo > 0 ? replyTo : null,
    // A forum topic it goes to (R-Y122).
    topic: Number.isInteger(topic) && topic > 0 ? topic : null,
    replyQuote: typeof draft.replyQuote === 'string' ? draft.replyQuote : null,
    silent: draft.silent === true,
    scheduleDate: Number.isInteger(draft.scheduleDate)
      ? draft.scheduleDate
      : null,
    // The identity it is sent as (R-Y141).
    sendAs: validSendAs(draft.sendAs) ? draft.sendAs : undefined,
    // The Stars the user confirmed for a paid chat (R-Y184).
    ...paidField(draft),
    // The link preview's choice (R-Y145), validated when it came in.
    preview: previewFields(draft),
    // A message effect (R-Y149), a decimal string.
    effect: EFFECT_ID.test(String(draft.effect ?? ''))
      ? draft.effect
      : undefined,
  };
};

// Pollers (no event stream) look at `changedAt` to know to refresh.
const touchChanged = (store, now) =>
  recordSync(store, { changedAt: new Date(now()).toISOString() });

// A live update whose store write failed: the counters step back and the
// difference is fetched again, so it is not lost (R-Z14).
const failedLive = (env, update) => {
  if (rewindPts(env.catchUp?.state(), update)) {
    env.catchUp.run('store-failed').catch(() => {});
  }
  env.channels?.failed(update);
};

/** history / post / setTyping through the connected account. */
const createMessaging = (env) => {
  const { store, connection, botLive, importer, now } = env;

  /** Send through the connected account (the chat composer, automations). */
  const post = async (draft = {}, options = {}) => {
    const creds = await readTelegramCredentials(store);
    if (creds?.kind !== 'user') {
      // A stored bot token, else the environment's one (as before).
      const token = creds?.token ?? options.token;
      return botLive.post(draft, token ? { ...options, token } : options);
    }
    const text = draft.text ?? draft.body;
    const target = draft.chat ?? draft.chatId ?? draft.to;
    if (!target) {
      throw new Error('telegram post requires a chat/chatId target');
    }
    return postAsUser(env, creds, {
      chat: String(target),
      text,
      clientId: draft.clientId,
      ...draftOptions(draft),
    });
  };

  // `cancel`: the user sent the message or cleared the box, so the
  // other side stops showing "typing…" at once (Telegram Desktop, Web A).
  const setTyping = async (
    { chat, chatId, cancel = false } = {},
    options = {}
  ) => {
    const creds = await readTelegramCredentials(store);
    const target = chat ?? chatId;
    if (creds?.kind !== 'user') {
      if (cancel) {
        return { ok: true, supported: false }; // bots have no cancel
      }
      const token = creds?.token ?? options.token;
      return botLive.setTyping({ chat: target }, token ? { token } : options);
    }
    const { client } = await connection.open(creds);
    const { Api } = await importer();
    return connection.withPeer(client, String(target), (peer) =>
      client.invoke(
        new Api.messages.SetTyping({
          peer,
          action: cancel
            ? new Api.SendMessageCancelAction()
            : new Api.SendMessageTypingAction(),
        })
      )
    );
  };

  // A user session and the chat to act on, else null (a bot, no chat).
  const userChat = async (chat) => {
    const creds = await readTelegramCredentials(store);
    if (creds?.kind !== 'user' || chat === undefined || chat === null) {
      return null;
    }
    const { client } = await connection.open(creds);
    return { client, chat: String(chat), Api: (await importer()).Api };
  };

  /**
   * Mark the chat read up to `maxId` on Telegram (the user saw those
   * messages here). Only forward: an older id than already read is a
   * no-op, as in TDLib and Element.
   */
  const markRead = async ({ chat, maxId, topic = null } = {}) => {
    const max = Number(maxId);
    const target =
      Number.isInteger(max) && max > 0 ? await userChat(chat) : null;
    if (!target) {
      return { ok: false, supported: false };
    }
    if (topic) {
      // A forum topic is read on its own, as Telegram's apps read it
      // (messages.readDiscussion, R-Y122); the chat's marker stays.
      const { client, Api } = target;
      await connection.withPeer(client, target.chat, (peer) =>
        client.invoke(
          new Api.messages.ReadDiscussion({
            peer,
            msgId: Number(topic),
            readMaxId: max,
          })
        )
      );
      return { ok: true };
    }
    const before = await store.get(`read:${SOURCE}:${target.chat}`);
    if ((before?.inboxMaxId ?? 0) >= max) {
      return { ok: true, already: true };
    }
    const { client, Api } = target;
    const result = await connection.withPeer(client, target.chat, (peer) =>
      client.invoke(
        target.chat.startsWith('-100')
          ? new Api.channels.ReadHistory({ channel: peer, maxId: max })
          : new Api.messages.ReadHistory({ peer, maxId: max })
      )
    );
    env.catchUp?.observeResult(result);
    await env.live.readInbox({ chat: target.chat, maxId: max });
    return { ok: true };
  };

  /** The chat's cloud draft (empty text clears it). */
  const saveDraft = async ({ chat, text = '' } = {}) => {
    const target = await userChat(chat);
    if (!target) {
      return { ok: false, supported: false };
    }
    const draft = String(text ?? '');
    const { client, Api } = target;
    await connection.withPeer(client, target.chat, (peer) =>
      client.invoke(new Api.messages.SaveDraft({ peer, message: draft }))
    );
    const before = await store.get(`read:${SOURCE}:${target.chat}`);
    await store.put({
      ...(before ?? {}),
      ...readLink(target.chat, {
        draft,
        draftAt: new Date(now()).toISOString(),
      }),
    });
    return { ok: true };
  };

  return {
    post,
    setTyping,
    markRead,
    saveDraft,
    dialogState: createDialogState(env, userChat),
  };
};

const reopenerOf = (store, connection) => async () => {
  const creds = await readTelegramCredentials(store);
  if (creds?.kind === 'user') {
    await connection.open(creds);
  }
};

// The account's request queue, stored peers, channel catch-up, page
// reader and message actions (on `env`).
const addReaders = (env, { pace, mediaDir }) => {
  const { store, now, log } = env;
  env.reopen = reopenerOf(store, env.connection);
  // Every Telegram request goes through one queue, the most urgent first,
  // paced; Telegram's "wait" is kept across restarts (R-Y34).
  env.queue = createFetchQueue({
    now,
    log,
    ...(pace ? { pace } : {}),
    onHold: (holds) => recordSync(store, { holds }).catch(() => {}),
    // No answer: the connection is likely gone. A new one is opened at
    // once, so the catch-up and the live updates follow it (not only
    // the next request).
    onStuck: () =>
      env.connection
        ?.disconnect()
        .then(() => env.reopen?.())
        .catch(() => {}),
  });
  env.peers = createPeers({ store, importer: env.importer });
  env.channels = createChannelSync({
    store,
    peers: env.peers,
    request: env.queue.run,
    handle: env.live.handle,
    client: async () => {
      const creds = await readTelegramCredentials(store);
      return creds?.kind === 'user'
        ? (await env.connection.open(creds)).client
        : null;
    },
    importer: env.importer,
    log,
    now,
  });
  env.pages = createPageReader(env, {
    credentials: () => readTelegramCredentials(store),
    toLinks: telegramDialogLinks,
    dialogOfEntity,
    dialogInfo,
    dialogReadLink,
    pinnedRanks,
    partnersOf: (listed) =>
      telegramPersonLinks(
        listed.filter((d) => d?.isUser && d.entity).map((d) => d.entity),
        { contact: false }
      ),
    writeChanged,
    recordSync,
    syncId: TELEGRAM_SYNC_ID,
  });
  env.actions = createActions(
    env,
    {
      credentials: () => readTelegramCredentials(store),
      toLinks: telegramDialogLinks,
      dialogOfEntity,
      writeChanged,
    },
    { mediaDir }
  );
};

// Telegram's "wait" for any request of the client — a send, a read
// marker, GramJS's own lookups — holds the queue too (R-Y34).
const watchFloods = (client, queue) => {
  if (typeof client?.invoke !== 'function' || client.invoke.watched) {
    return;
  }
  const invoke = client.invoke.bind(client);
  client.invoke = Object.assign(
    async (request, ...rest) => {
      try {
        return await invoke(request, ...rest);
      } catch (error) {
        queue.note(error, { method: request?.className ?? null });
        throw error;
      }
    },
    { watched: true }
  );
};

// Telegram's "wait" from before a restart still holds.
const restoreHolds = ({ store, queue }) =>
  store
    .get(TELEGRAM_SYNC_ID)
    .then((state) => queue.hold(state?.holds ?? {}))
    .catch(() => {});

// What the account reads on request: a chat's pages, more of the chat
// list, and a chat's whole history before others' (someone is being
// learned about, R-Y50).
const readersOf = (env, backfill) => ({
  history: async (options = {}) => {
    if (options.priority === 'view') {
      backfill.focus(options.chat);
    }
    const result = await env.pages.history(options);
    return {
      ...result,
      background: backfill.active(options.chat) && !result.complete,
    };
  },
  historyAt: env.pages.historyAt,
  historyAround: env.pages.historyAround,
  newer: env.pages.newer,
  moreDialogs: env.pages.moreDialogs,
  readFirst: backfill.prefer,
});

// The slow download of whole histories, through the account's readers.
const backfillOf = (env, { chats, everyMs }) =>
  createBackfill({
    store: env.store,
    queue: env.queue,
    pages: env.pages,
    chats: chats ?? (() => storedChats(env.store)),
    credentials: () => readTelegramCredentials(env.store),
    syncId: TELEGRAM_SYNC_ID,
    log: env.log,
    now: env.now,
    everyMs,
  });

// The minimal adapter object the sender and typing helper look up on the
// account; actions that act on existing messages live here too (R-Y36).
const buildLiveAdapter = (messaging, actions) => ({
  post: messaging.post,
  setTyping: messaging.setTyping,
  editMessage: actions.editMessage,
  react: actions.react,
  deleteMessages: actions.deleteMessages,
  forwardMessages: actions.forwardMessages,
  markRead: messaging.markRead,
});

// Mend what older versions stored wrong, once each, in the background.
const runRepairs = (store, log, refresh) =>
  repairSenders(store, { log })
    // Only worth it when GramJS really speaks the current layer.
    .then(() =>
      installTelegramLayer().layer === LAYER
        ? rereadUnsupported(store, {
            refresh,
            layer: LAYER,
            rev: SCHEMA_REV,
            log,
          })
        : 0
    )
    .then(() => nameForwards(store, { refresh, log }))
    .catch((error) =>
      log({
        level: 'warn',
        event: 'telegram_repair_failed',
        error: error.message,
      })
    );

// The connection's state, shown in Chat ("Telegram: reconnecting…");
// written on change only.
const connectionRecorder = (store) => {
  let current = null;
  return (state) => {
    const next = CONNECTION[state] ?? null;
    if (next !== current) {
      current = next;
      // Reached again, or out of reach since now (kept while it lasts).
      const mark = async () => {
        const before = (await store.get(TELEGRAM_SYNC_ID)) ?? {};
        const since = before.unreachableSince ?? null;
        const unreachableSince =
          next === 'connected'
            ? null
            : next
              ? (since ?? new Date().toISOString())
              : since;
        await recordSync(store, { connection: next, unreachableSince });
      };
      mark().catch(() => {});
    }
  };
};

export const createTelegramAccount = ({
  store,
  // The saved connection proxy is read whenever a client is built (R-Y192).
  clientFactory = gramjsClientFactory(importTelegram, {
    proxy: () => readProxy(store),
  }),
  importer = importTelegram,
  botLive = createTelegramBotLive(),
  log = () => {},
  now = () => Date.now(),
  dialogLimit = 40,
  messageLimit = 30,
  pollMs = 30_000,
  // The slow download of whole histories (./telegram-backfill.js): one
  // request this often; 0 turns it off. `chats()` lists the chats.
  backfillMs = BACKFILL_EVERY_MS,
  chats = null,
  // The queue's pace (./telegram-history.js PACE); tests pass NO_PACE.
  pace = null,
  // Where downloaded pictures are kept (null: none are downloaded).
  mediaDir = null,
} = {}) => {
  const live = createTelegramLive({
    store,
    toLinks: telegramDialogLinks,
    log,
    now,
    onPhoneCall: (client, effect) => env.phoneCalls?.handle(client, effect),
    // A live update that could not be stored is fetched again (R-Z14).
    onFailed: (update) => failedLive(env, update),
    track: (update, done) => env.catchUp?.track(update, done) ?? done,
    touch: () => touchChanged(store, now),
  });
  let resync = async () => {}; // set once `sync` exists
  const env = { store, botLive, importer, log, now, live };
  const catchUp = createTelegramCatchUp({
    store,
    handle: live.handle,
    resync: (reason) => resync(reason),
    // A channel's gap: that channel's own catch-up, not the chat list.
    channelTooLong: (update) => env.channels.observe(update),
    request: (key, task) => env.queue.run(key, 'list', task),
    importer,
    log,
    onConnection: connectionRecorder(store),
  });
  const connection = createUserConnection({
    clientFactory,
    dialogLimit,
    log,
    peers: { input: (chat) => env.peers.input(chat) },
    request: (key, task) => env.queue.run(key, 'list', task),
    lookup: (client) => lookupAllDialogs(env, client),
    now,
    onOpen: (client, me) => {
      watchFloods(client, env.queue);
      live.attach(client);
      client.addEventHandler?.((update) => env.channels.observe(update));
      catchUp.attach(client, me).catch(() => {});
    },
  });
  Object.assign(env, { connection, catchUp });
  addReaders(env, { pace, mediaDir });
  const messaging = createMessaging(env);
  const backfill = backfillOf(env, { chats, everyMs: backfillMs });
  let running = null; // the sync in flight
  let timer = null;
  let resyncedAt = 0;

  /** Pull chats, messages and contacts into the store (one at a time). */
  const sync = ({
    full = false,
    reason = 'manual',
    dialogs = dialogLimit,
    messages = messageLimit,
  } = {}) => {
    running ??= runSync(env, { full, reason, dialogs, messages }).finally(
      () => {
        running = null;
      }
    );
    return running;
  };
  resync = async (reason) => {
    if (now() - resyncedAt < RESYNC_EVERY_MS) {
      return;
    }
    resyncedAt = now();
    await sync({ reason });
  };

  /** Whether an account is connected, and how the last sync went. */
  const status = async () => {
    const creds = await readTelegramCredentials(store);
    const link = await store.get(TELEGRAM_SYNC_ID);
    return {
      ...publicStatus(link ?? {}),
      ...reachability(creds ? link : null, now()),
      connected: Boolean(creds),
      kind: creds?.kind ?? null,
      syncing: Boolean(running),
      // Only a user session is kept up to date in the background.
      auto: creds?.kind === 'user',
      backfill: backfill.progress(),
      // How fast Telegram is asked now, and any wait it asked for.
      requests: env.queue.state(),
    };
  };

  /** The stored credential changed: drop the old connection, sync anew. */
  const connected = async () => {
    await connection.disconnect();
    const creds = await readTelegramCredentials(store);
    // A bot syncs only on request (see the module comment).
    return creds?.kind === 'user'
      ? sync({ full: true, reason: 'connect' })
      : status();
  };

  const start = () => {
    if (timer || !pollMs) {
      return;
    }
    restoreHolds(env);
    runRepairs(store, log, env.actions?.refreshMessages);
    const tick = async () => {
      const creds = await readTelegramCredentials(store);
      if (creds?.kind === 'user') {
        // Reopen a dropped connection, ask what we missed (cheap: Web A
        // asks on every ping); the chat list only now and then.
        await env.reopen().catch(() => {});
        await catchUp.run('poll');
        const state = (await store.get(TELEGRAM_SYNC_ID)) ?? {};
        if (
          now() - (Date.parse(state.dialogsAt ?? '') || 0) >=
          DIALOGS_EVERY_MS
        ) {
          await sync({ reason: 'poll' });
        }
      }
    };
    timer = globalThis.setInterval(() => {
      tick().catch(() => {});
    }, pollMs);
    timer.unref?.();
    tick().catch(() => {});
    backfill.start();
  };

  const stop = async () => {
    globalThis.clearInterval(timer);
    timer = null;
    backfill.stop();
    await env.channels.flush().catch(() => {});
    await catchUp.stop();
    await connection.disconnect();
  };

  return {
    sync,
    status,
    ...messaging,
    ...env.actions,
    ...readersOf(env, backfill),
    connected,
    start,
    stop,
    catchUp: () => catchUp.run('manual'),
    live: buildLiveAdapter(messaging, env.actions),
  };
};

/**
 * More than one Telegram account, as Telegram Desktop allows: up to 3,
 * up to 5 with Premium (R-Y198; learned, never copied).
 *
 * Additions only. Account 1 is today's single account and keeps its keys
 * (`secret:telegram:*`, `msg:telegram:*`, ...) and its whole service
 * untouched: this module never writes under them. An extra account lives
 * in its own namespace:
 *   secret:telegram@2:user-session | api-id | api-hash   its session
 *   account:telegram@2                                   public name only
 * Nothing exists for a slot until the user adds the account.
 *
 * What an extra account can do today (honest scope): be signed in (the
 * existing login flow, parameterized by `account`), be listed with its
 * name, show its chat list and unread count read live from Telegram
 * (nothing is written to the message store, so no `telegram@2` messages
 * mix with account 1's), and be logged out (auth.logOut, then only its `@2` keys go).
 * R-Y202 makes an extra account fully usable: each runs on its own store
 * (src/server/telegram-extras.js), so `msg:telegram:*` and the page's
 * `source: 'telegram'` stay as they are. The dialogs here remain the
 * preview of an account whose service is not running.
 *
 * Session contents are never logged or returned.
 */

import { accountOf, gramjsClientFactory } from './telegram-mtproto.js';
import { readProxy } from './telegram-proxy.js';
import { importTelegram } from './telegram-layer.js';
import { connected, failureOf } from './telegram-stickers.js';

export const MAX_ACCOUNTS = 3;
export const MAX_ACCOUNTS_PREMIUM = 5;
/** The secrets one account's sign-in keeps (all of its secrets). */
export const SECRET_NAMES = ['user-session', 'api-id', 'api-hash'];

/** The slot a request names: 1 when absent, 2..5 as asked, else null. */
export const accountSlot = (value) => {
  if (value === undefined || value === null || value === '') {
    return 1;
  }
  const slot = Number(value);
  return Number.isInteger(slot) && slot >= 1 && slot <= MAX_ACCOUNTS_PREMIUM
    ? slot
    : null;
};

/** The namespace of a slot: `telegram` for account 1, else `telegram@2`. */
export const namespaceOf = (slot) =>
  slot === 1 ? 'telegram' : `telegram@${slot}`;

/** The store id of one of a slot's secrets. */
export const secretId = (slot, name) => `secret:${namespaceOf(slot)}:${name}`;

/** The id of an extra account's public profile link. */
export const profileId = (slot) => `account:${namespaceOf(slot)}`;

const secretValue = (link) =>
  link?.value ?? link?.token ?? link?.body ?? link?.text ?? null;

/** A slot's stored user session, or null (reads only). */
export const readSlotCredentials = async (store, slot) => {
  const read = async (name) =>
    secretValue(await store.get(secretId(slot, name)));
  const [session, apiId, apiHash] = await Promise.all(SECRET_NAMES.map(read));
  return session ? { kind: 'user', session, apiId, apiHash } : null;
};

/** The extra slots (2..5) that hold a signed-in account. Reads only. */
export const extraSlots = async (store) => {
  const slots = [];
  for (let slot = 2; slot <= MAX_ACCOUNTS_PREMIUM; slot += 1) {
    if (await store.get(secretId(slot, 'user-session'))) {
      slots.push(slot);
    }
  }
  return slots;
};

/** The first free extra slot within `limit` accounts in all, or null. */
export const nextFreeSlot = async (store, limit) => {
  const taken = new Set(await extraSlots(store));
  for (let slot = 2; slot <= limit; slot += 1) {
    if (!taken.has(slot)) {
      return slot;
    }
  }
  return null;
};

/** How many accounts the user may have: 3, or 5 with Premium. */
export const limitFor = (premium) =>
  premium ? MAX_ACCOUNTS_PREMIUM : MAX_ACCOUNTS;

const stamp = () => new Date().toISOString();

/** Keep a freshly signed-in extra account (slot 2 or more only). */
export const saveExtraAccount = async (
  store,
  slot,
  { apiId, apiHash, session, account }
) => {
  if (!Number.isInteger(slot) || slot < 2) {
    throw new Error('only an extra account is saved here');
  }
  const put = (name, value) =>
    store.put({
      id: secretId(slot, name),
      tokens: ['secret', namespaceOf(slot), name],
      value,
      updated: stamp(),
    });
  await put('user-session', session);
  await put('api-id', String(apiId));
  await put('api-hash', apiHash);
  await store.put({
    id: profileId(slot),
    tokens: ['account', namespaceOf(slot)],
    source: 'telegram',
    slot,
    name:
      [account?.firstName, account?.lastName].filter(Boolean).join(' ') ||
      account?.username ||
      null,
    username: account?.username ?? null,
    // Its own id (R-Y202): the avatar of the account it is shown with.
    accountId: account?.id ? String(account.id) : null,
    updated: stamp(),
  });
};

/**
 * Log an extra account out: only that slot's own keys are removed.
 * Account 1 is never removed here. Returns how many keys went.
 */
export const removeExtraAccount = async (store, slot) => {
  if (!Number.isInteger(slot) || slot < 2 || slot > MAX_ACCOUNTS_PREMIUM) {
    throw new Error('only an extra account can be removed here');
  }
  let removed = 0;
  for (const id of [
    ...SECRET_NAMES.map((name) => secretId(slot, name)),
    profileId(slot),
  ]) {
    if (await store.get(id)) {
      await store.delete(id);
      removed += 1;
    }
  }
  return removed;
};

const CODES = { AUTH_KEY_UNREGISTERED: 'signed-out', FLOOD_WAIT: 'flood' };
const meFailure = failureOf(CODES);
const text = (value) => String(value?.value ?? value);

const meOf = (me) => ({
  ...accountOf(me),
  name:
    [me?.firstName, me?.lastName].filter(Boolean).join(' ') ||
    me?.username ||
    null,
  premium: Boolean(me?.premium),
});

/** Account 1's own name and Premium flag, from its connection. */
export const createAccountsActions = (env, context) => ({
  accountMe: async () =>
    connected(env, context.userClient, meFailure, async (c) => ({
      ok: true,
      ...meOf(await c.client.getMe()),
    })),
});

// One dialog as the preview list shows it: a name, the newest message's
// text, when, and the unread count. Nothing of it is stored.
export const dialogRow = (dialog) => ({
  chat: text(dialog.id),
  name: dialog.title ?? dialog.name ?? null,
  text: dialog.message?.message ?? '',
  date: dialog.date ? Number(dialog.date) * 1000 : null,
  unread: Number(dialog.unreadCount ?? 0),
  muted: Boolean(dialog.dialog?.notifySettings?.muteUntil),
});

/**
 * The extra accounts' live side: `resolve(slot)` answers a small account
 * service (status, dialogs) for a signed-in slot, or null. Clients are
 * opened on demand and dropped after `idleMs`; nothing is written.
 */
export const createExtraAccounts = ({
  store,
  clientFactory = gramjsClientFactory(importTelegram, {
    proxy: () => readProxy(store),
  }),
  log = () => {},
  now = () => Date.now(),
  idleMs = 60_000,
  dialogLimit = 40,
  loadApi = async () => (await importTelegram()).Api,
} = {}) => {
  const open = new Map(); // slot -> { client, timer }

  const drop = async (slot) => {
    const entry = open.get(slot);
    open.delete(slot);
    if (entry) {
      globalThis.clearTimeout(entry.timer);
      await Promise.resolve(entry.client.disconnect?.()).catch(() => {});
    }
  };

  const clientOf = async (slot) => {
    const creds = await readSlotCredentials(store, slot);
    if (!creds) {
      return null;
    }
    let entry = open.get(slot);
    if (!entry) {
      const client = await clientFactory({
        apiId: creds.apiId,
        apiHash: creds.apiHash,
        session: creds.session,
      });
      await client.connect();
      entry = { client, timer: null };
      open.set(slot, entry);
    }
    globalThis.clearTimeout(entry.timer);
    entry.timer = globalThis.setTimeout(() => drop(slot), idleMs);
    entry.timer.unref?.();
    return entry.client;
  };

  const dialogs = async (slot) => {
    const client = await clientOf(slot);
    if (!client) {
      return { ok: false, error: 'no-account', code: 'no-account' };
    }
    try {
      const listed = (await client.getDialogs({ limit: dialogLimit })) ?? [];
      const rows = [...listed]
        .map(dialogRow)
        .sort((a, b) => (b.date ?? 0) - (a.date ?? 0));
      const unread = rows.reduce((n, r) => n + (r.muted ? 0 : r.unread), 0);
      return { ok: true, at: now(), dialogs: rows, unread };
    } catch (error) {
      log({ level: 'warn', event: 'telegram_extra_failed', slot });
      await drop(slot);
      return { ok: false, ...meFailure(error) };
    }
  };

  // "Log out" ends the session on Telegram's side too (auth.logOut), as
  // Telegram Desktop does; when that fails the session is still forgotten
  // here.
  const revoke = async (slot) => {
    try {
      const client = await clientOf(slot);
      if (client) {
        const Api = await loadApi();
        await client.invoke(new Api.auth.LogOut());
      }
    } catch {
      log({ level: 'warn', event: 'telegram_extra_logout_failed', slot });
    }
    await drop(slot);
  };

  const resolve = async (slot) =>
    slot >= 2 && (await store.get(secretId(slot, 'user-session')))
      ? {
          slot,
          status: async () => ({ connected: true, slot, kind: 'user' }),
          dialogs: () => dialogs(slot),
        }
      : null;

  return {
    resolve,
    dialogs,
    drop,
    revoke,
    stop: async () => {
      await Promise.all([...open.keys()].map(drop));
    },
  };
};

/**
 * What the user does to messages in Chat, as Telegram's apps do it
 * (R-Y36): read some messages again, forward them, delete them, show
 * their pictures.
 *
 * - `refreshMessages({ chat, ids })` reads the messages by id (one
 *   request, by the stored peer, through the queue): an edit since is
 *   stored, and a message Telegram no longer has is marked `deleted` —
 *   so a deletion made in another app shows here even when no update
 *   about it arrived.
 * - `forwardMessages({ fromChat, ids, toChat })` and `deleteMessages({
 *   chat, ids, revoke })` change Telegram only on the user's press in
 *   Chat; Telegram's answer goes through the live handler at once (the
 *   forwarded messages appear, the deleted ones go) and moves the update
 *   counters, so the catch-up does not ask for them again.
 * - `pinMessage({ chat, id, unpin, oneSide, silent })` pins or unpins
 *   one message (R-Y67); Telegram's answer moves the pinned bar.
 * - `media({ chat, id, size })` is ./telegram-media.js.
 * - polls and checklists (vote, stop, results, voters, tick) are
 *   ./telegram-polls.js (R-Y74).
 * - the chat list's menu (pin, mute, archive, mark read or unread) is
 *   ./telegram-dialogs.js (R-Y97); search in a chat is
 *   ./telegram-search.js (R-Y98); files and photos are sent by
 *   ./telegram-upload.js (R-Y99); clearing, deleting and leaving a chat
 *   is ./telegram-chat-removal.js (R-Y100); scheduled messages are
 *   ./telegram-scheduled.js (R-Y102), chat folders ./telegram-folders.js
 *   (R-Y103); translating messages is ./telegram-translate.js (R-Y132);
 *   message effects are ./telegram-effects.js (R-Y149); emoji statuses
 *   ./telegram-emoji-status.js (R-Y162); the translate bar and summaries
 *   ./telegram-translate-chat.js (R-Y213).
 */

