/**
 * Adding members to a group or channel, as Telegram Desktop does
 * (R-Y204; learned, never copied):
 * - `addCandidates({ chat })` — the people to pick from: contacts and the
 *   people written to most (contacts.getContacts, contacts.getTopPeers)
 *   → `{ ok, people: [{ id, name, username, contact }] }`;
 * - `addMembers({ chat, users })` — channels.inviteToChannel (a supergroup
 *   or channel) or messages.addChatUser (a basic group, one by one, fwd
 *   limit 100) → `{ ok, added: [id], missing: [{ id, name }], failed:
 *   [{ id, code }] }`; `missing` are those their privacy keeps from being
 *   added (layer 225's missing_invitees), to whom the page may offer the
 *   chat's invite link;
 * - `sendInviteLink({ chat, users })` — the chat's primary link sent as a
 *   message to each of them (messages.exportChatInvite, sendMessage), only
 *   when the user asked for it → `{ ok, sent: [id], failed: [id] }`.
 * Telegram's errors become codes the page shows as text.
 */

import { randomIdOf } from './telegram-send.js';
import { connected, failureOf, runIn } from './telegram-stickers.js';

export const CODES = {
  USER_PRIVACY_RESTRICTED: 'privacy',
  USER_NOT_MUTUAL_CONTACT: 'not-mutual',
  USERS_TOO_MUCH: 'users-too-much',
  USER_CHANNELS_TOO_MUCH: 'user-channels-too-much',
  CHANNELS_TOO_MUCH: 'too-many-chats',
  CHAT_ADMIN_REQUIRED: 'not-admin',
  CHAT_ADMIN_INVITE_REQUIRED: 'not-admin',
  CHAT_WRITE_FORBIDDEN: 'not-admin',
  RIGHT_FORBIDDEN: 'right-forbidden',
  USER_KICKED: 'kicked',
  USER_BANNED_IN_CHANNEL: 'kicked',
  BOT_GROUPS_BLOCKED: 'bot-blocked',
  BOTS_TOO_MUCH: 'bots-too-much',
  ADMINS_TOO_MUCH: 'admins-too-much',
  ADMIN_RANK_INVALID: 'rank-invalid',
  ADMIN_RANK_EMOJI_NOT_ALLOWED: 'rank-invalid',
  USER_CREATOR: 'user-creator',
  USER_ID_INVALID: 'no-user',
  USER_NOT_PARTICIPANT: 'not-member',
  USER_ALREADY_PARTICIPANT: 'already',
  CHAT_NOT_MODIFIED: 'not-modified',
  CHAT_ID_INVALID: 'no-access',
  CHANNEL_PRIVATE: 'no-access',
  CHANNEL_INVALID: 'no-access',
  PEER_ID_INVALID: 'no-access',
  PEER_FLOOD: 'flood',
  USER_RESTRICTED: 'restricted',
};

const asFailure = failureOf(CODES);
/** Telegram's error as `{ ok: false, code }`; "not modified" is no failure. */
export const failure = (error) => {
  const out = asFailure(error);
  return out.code === 'not-modified' ? { ok: true } : out;
};
export const bad = (code) => ({ ok: false, error: code, code });
export const codeOf = (error) => asFailure(error).code;

export const CHAT = /^-\d{1,20}$/;
const USER = /^\d{1,20}$/;
const MAX_USERS = 200;
const FWD_LIMIT = 100;
const PRIVACY = new Set(['privacy', 'not-mutual']);

export const isChannel = (chat) => chat.startsWith('-100');
export const textOf = (value) => String(value?.value ?? value);
export const nameOf = (user) =>
  [user?.firstName, user?.lastName].filter(Boolean).join(' ') ||
  user?.username ||
  '';

/** Whether `users` is a short list of distinct user ids. */
export const validUsers = (users) =>
  Array.isArray(users) &&
  users.length > 0 &&
  users.length <= MAX_USERS &&
  users.every((u) => USER.test(String(u))) &&
  new Set(users.map(String)).size === users.length;

/** Remembers the users an answer carried (their access hashes). */
export const remember = (known, users = []) => {
  for (const user of users) {
    if (user?.id !== undefined && !user.bot) {
      known.set(textOf(user.id), user);
    }
  }
};

/** The input user for an id: a known one, else what GramJS has, else bare. */
export const inputUserOf = async (c, known, id) => {
  const user = known.get(id);
  if (user) {
    return new c.Api.InputUser({
      userId: user.id,
      accessHash: user.accessHash ?? c.zero,
    });
  }
  const entity = await Promise.resolve()
    .then(() => c.client.getInputEntity?.(c.helpers.returnBigInt(id)))
    .catch(() => null);
  return new c.Api.InputUser({
    userId: entity?.userId ?? c.helpers.returnBigInt(id),
    accessHash: entity?.accessHash ?? c.zero,
  });
};

const createCandidates =
  (env, userClient, known) =>
  async (req = {}) => {
    if (!CHAT.test(String(req.chat ?? ''))) {
      return bad('bad-request');
    }
    return connected(env, userClient, failure, async (c) => {
      const people = new Map();
      const take = (users, contact) => {
        remember(known, users);
        for (const u of users ?? []) {
          const id = u ? textOf(u.id) : '';
          if (u && !u.self && !u.bot && !u.deleted && !people.has(id)) {
            people.set(id, {
              id,
              name: nameOf(u) || id,
              username: u.username ?? null,
              contact,
            });
          }
        }
      };
      const contacts = await runIn(env, 'contacts:list', () =>
        c.client.invoke(new c.Api.contacts.GetContacts({ hash: c.zero }))
      );
      take(contacts?.users, true);
      // The people written to most (without them the contacts still show).
      const top = await c.client
        .invoke(
          new c.Api.contacts.GetTopPeers({
            correspondents: true,
            offset: 0,
            limit: 30,
            hash: c.zero,
          })
        )
        .catch(() => null);
      take(top?.users, false);
      return {
        ok: true,
        people: [...people.values()].sort((a, b) =>
          a.name.localeCompare(b.name)
        ),
      };
    });
  };

const missingIds = (answer) =>
  (answer?.missingInvitees ?? []).map((m) => textOf(m.userId));

// A basic group takes one person a request.
const addToGroup = async (c, env, known, chat, ids) => {
  const out = { added: [], missing: [], failed: [], updates: [] };
  for (const id of ids) {
    try {
      const answer = await runIn(env, `member-add:${chat}:${id}`, async () =>
        c.client.invoke(
          new c.Api.messages.AddChatUser({
            chatId: c.helpers.returnBigInt(chat.slice(1)),
            userId: await inputUserOf(c, known, id),
            fwdLimit: FWD_LIMIT,
          })
        )
      );
      (missingIds(answer).length > 0 ? out.missing : out.added).push(id);
      out.updates.push(answer?.updates);
    } catch (error) {
      const code = codeOf(error);
      if (PRIVACY.has(code)) {
        out.missing.push(id);
      } else {
        out.failed.push({ id, code });
      }
    }
  }
  return out;
};

const addToChannel = async (c, env, known, chat, ids) => {
  const users = await Promise.all(ids.map((id) => inputUserOf(c, known, id)));
  const answer = await runIn(env, `member-add:${chat}`, () =>
    env.connection.withPeer(c.client, chat, (peer) =>
      c.client.invoke(
        new c.Api.channels.InviteToChannel({ channel: peer, users })
      )
    )
  );
  const missing = missingIds(answer);
  return {
    added: ids.filter((id) => !missing.includes(id)),
    missing,
    failed: [],
    updates: [answer?.updates],
  };
};

const createAddMembers =
  (env, { userClient, apply }, known) =>
  async (req = {}) => {
    const chat = String(req.chat ?? '');
    if (!CHAT.test(chat) || !validUsers(req.users)) {
      return bad('bad-request');
    }
    const ids = req.users.map(String);
    return connected(env, userClient, failure, async (c) => {
      const ask = isChannel(chat) ? addToChannel : addToGroup;
      const found = await ask(c, env, known, chat, ids);
      for (const updates of found.updates) {
        if (updates && typeof updates === 'object') {
          await apply(c.client, updates);
        }
      }
      const [first] = found.failed;
      if (first && found.added.length + found.missing.length === 0) {
        return bad(first.code);
      }
      return {
        ok: true,
        added: found.added,
        missing: found.missing.map((id) => ({
          id,
          name: nameOf(known.get(id)) || id,
        })),
        failed: found.failed,
      };
    });
  };

// The chat's primary link, sent to each of the people as a message.
const createSendLink =
  (env, { userClient, apply }, known) =>
  async (req = {}) => {
    const chat = String(req.chat ?? '');
    if (!CHAT.test(chat) || !validUsers(req.users)) {
      return bad('bad-request');
    }
    const ids = req.users.map(String);
    return connected(env, userClient, failure, async (c) => {
      const invite = await runIn(env, `invite-primary:${chat}`, () =>
        env.connection.withPeer(c.client, chat, (peer) =>
          c.client.invoke(new c.Api.messages.ExportChatInvite({ peer }))
        )
      );
      if (typeof invite?.link !== 'string') {
        return bad('failed');
      }
      const out = { sent: [], failed: [] };
      for (const [index, id] of ids.entries()) {
        try {
          const user = await inputUserOf(c, known, id);
          const sent = await c.client.invoke(
            new c.Api.messages.SendMessage({
              peer: new c.Api.InputPeerUser({
                userId: user.userId,
                accessHash: user.accessHash,
              }),
              message: invite.link,
              randomId: randomIdOf(null, index, c.helpers),
            })
          );
          await apply(c.client, sent);
          out.sent.push(id);
        } catch {
          out.failed.push(id);
        }
      }
      return out.sent.length === 0 ? bad('failed') : { ok: true, ...out };
    });
  };

export const createAddMembersActions = (env, context, known) => ({
  addCandidates: createCandidates(env, context.userClient, known),
  addMembers: createAddMembers(env, context, known),
  sendInviteLink: createSendLink(env, context, known),
});

/**
 * A chat's administrators, the history new members see, and upgrading a
 * group, as Telegram Desktop does (R-Y204; learned, never copied):
 * - `chatAdmins({ chat })` — the administrators (channels.getParticipants
 *   with the admins filter, or a basic group's full chat) → `{ ok, admins:
 *   [{ id, name, username, role, rank, rights, promotedBy, promotedByName,
 *   canEdit, self }] }`; `rights` holds every ChatAdminRights flag;
 * - `setAdmin({ chat, user, rights?, rank?, dismiss?, broadcast? })` —
 *   channels.editAdmin with the rights of the chat's kind (no rights at all
 *   dismisses), or in a basic group messages.editChatAdmin (a basic group
 *   has no custom rights or titles: those need an upgrade) → `{ ok }`;
 * - `setHistoryHidden({ chat, hidden })` — what new members see
 *   (channels.togglePreHistoryHidden; a basic group must upgrade first);
 * - `upgradeGroup({ chat })` — messages.migrateChat → `{ ok, chat, title }`
 *   with the supergroup's id; the answer's updates go through the live
 *   handler, which carries the migration service messages.
 * Telegram's errors become codes the page shows as text.
 */

import { markedId } from './telegram-invite.js';
import { connected, runIn } from './telegram-stickers.js';
import {
  ALL_ADMIN_RIGHTS,
  anyRight,
  kindOfChat,
  shapeRights,
  validRank,
  validRights,
} from './telegram-admin-rights.js';
import {
  CHAT,
  bad,
  failure,
  inputUserOf,
  isChannel,
  nameOf,
  remember,
  textOf,
  validUsers,
} from './telegram-add-members.js';

const ROLES = {
  ChannelParticipantCreator: 'creator',
  ChatParticipantCreator: 'creator',
  ChannelParticipantAdmin: 'admin',
  ChatParticipantAdmin: 'admin',
};

const idOf = (value) => (value === undefined ? '' : textOf(value));

const adminOf = (participant, users) => {
  const id = idOf(participant.userId);
  const user = users.get(id);
  const by = idOf(participant.promotedBy ?? participant.inviterId);
  return {
    id,
    name: nameOf(user) || id,
    username: user?.username ?? null,
    role: ROLES[participant.className],
    rank: participant.rank ?? null,
    rights: Object.fromEntries(
      ALL_ADMIN_RIGHTS.map((key) => [
        key,
        ROLES[participant.className] === 'creator' ||
          Boolean(participant.adminRights?.[key]),
      ])
    ),
    promotedBy: by || null,
    promotedByName: by ? nameOf(users.get(by)) || by : null,
    canEdit: Boolean(participant.canEdit),
    self: Boolean(user?.self),
  };
};

const shapeAdmins = (participants, answer, known) => {
  remember(known, answer?.users);
  const users = new Map((answer?.users ?? []).map((u) => [textOf(u.id), u]));
  return participants
    .filter((p) => ROLES[p.className])
    .map((p) => adminOf(p, users))
    .filter((a) => a.id !== '');
};

const createAdmins =
  (env, userClient, known) =>
  async (req = {}) => {
    const chat = String(req.chat ?? '');
    if (!CHAT.test(chat)) {
      return bad('bad-request');
    }
    return connected(env, userClient, failure, async (c) => {
      if (!isChannel(chat)) {
        const answer = await runIn(env, `admins:${chat}`, () =>
          c.client.invoke(
            new c.Api.messages.GetFullChat({
              chatId: c.helpers.returnBigInt(chat.slice(1)),
            })
          )
        );
        const all = answer?.fullChat?.participants?.participants ?? [];
        return { ok: true, admins: shapeAdmins(all, answer, known) };
      }
      const answer = await runIn(env, `admins:${chat}`, () =>
        env.connection.withPeer(c.client, chat, (peer) =>
          c.client.invoke(
            new c.Api.channels.GetParticipants({
              channel: peer,
              filter: new c.Api.ChannelParticipantsAdmins(),
              offset: 0,
              limit: 200,
              hash: c.zero,
            })
          )
        )
      );
      const list = answer?.participants ?? [];
      return { ok: true, admins: shapeAdmins(list, answer, known) };
    });
  };

/**
 * What a `setAdmin` request is asked with, or the code that refuses it:
 * `{ ok: true, dismiss, rights, rank }`; rights are shaped to the chat's
 * kind, and a request with none at all dismisses.
 */
const wellFormed = (req, rank) =>
  CHAT.test(String(req.chat ?? '')) &&
  validUsers([req.user]) &&
  (req.rights === undefined || validRights(req.rights)) &&
  validRank(rank) &&
  (req.dismiss === undefined || typeof req.dismiss === 'boolean') &&
  (req.broadcast === undefined || typeof req.broadcast === 'boolean');

export const adminRequest = (req = {}) => {
  const chat = String(req.chat ?? '');
  const rank = req.rank === undefined ? '' : req.rank;
  if (!wellFormed(req, rank)) {
    return bad('bad-request');
  }
  const kind = kindOfChat(chat, req.broadcast === true);
  if (kind === 'group' && (req.rights !== undefined || rank !== '')) {
    return bad('needs-upgrade');
  }
  const rights = shapeRights(req.rights ?? {}, kind);
  const dismiss = req.dismiss === true;
  if (kind !== 'group' && !dismiss && !anyRight(rights)) {
    return bad('no-rights');
  }
  return { ok: true, chat, kind, dismiss, rights, rank };
};

const createSetAdmin =
  (env, { userClient, apply }, known) =>
  async (req = {}) => {
    const asked = adminRequest(req);
    if (!asked.ok) {
      return asked;
    }
    const { chat, kind, dismiss, rights, rank } = asked;
    return connected(env, userClient, failure, async (c) => {
      const user = await inputUserOf(c, known, String(req.user));
      const answer = await runIn(env, `admin-set:${chat}:${req.user}`, () =>
        kind === 'group'
          ? c.client.invoke(
              new c.Api.messages.EditChatAdmin({
                chatId: c.helpers.returnBigInt(chat.slice(1)),
                userId: user,
                isAdmin: !dismiss,
              })
            )
          : env.connection.withPeer(c.client, chat, (peer) =>
              c.client.invoke(
                new c.Api.channels.EditAdmin({
                  channel: peer,
                  userId: user,
                  adminRights: new c.Api.ChatAdminRights(dismiss ? {} : rights),
                  rank: dismiss ? '' : rank,
                })
              )
            )
      );
      if (answer && typeof answer === 'object') {
        await apply(c.client, answer);
      }
      return { ok: true };
    });
  };

const createHistory =
  (env, { userClient, apply }) =>
  async (req = {}) => {
    const chat = String(req.chat ?? '');
    if (!CHAT.test(chat) || typeof req.hidden !== 'boolean') {
      return bad('bad-request');
    }
    if (!isChannel(chat)) {
      return bad('needs-upgrade');
    }
    return connected(env, userClient, failure, async (c) => {
      const answer = await runIn(env, `history-hidden:${chat}`, () =>
        env.connection.withPeer(c.client, chat, (peer) =>
          c.client.invoke(
            new c.Api.channels.TogglePreHistoryHidden({
              channel: peer,
              enabled: req.hidden,
            })
          )
        )
      );
      if (answer && typeof answer === 'object') {
        await apply(c.client, answer);
      }
      return { ok: true, hidden: req.hidden };
    });
  };

const createUpgrade =
  (env, { userClient, apply }) =>
  async (req = {}) => {
    const chat = String(req.chat ?? '');
    if (!CHAT.test(chat) || isChannel(chat)) {
      return bad('bad-request');
    }
    return connected(env, userClient, failure, async (c) => {
      const answer = await runIn(env, `migrate:${chat}`, () =>
        c.client.invoke(
          new c.Api.messages.MigrateChat({
            chatId: c.helpers.returnBigInt(chat.slice(1)),
          })
        )
      );
      const channel = (answer?.chats ?? []).find(
        (x) => x?.className === 'Channel'
      );
      if (answer && typeof answer === 'object') {
        await apply(c.client, answer);
      }
      if (!channel) {
        return bad('failed');
      }
      const id = markedId(channel);
      await Promise.resolve(
        env.peers?.remember?.(id, channel, {
          title: channel.title,
          isGroup: true,
          isChannel: true,
        })
      ).catch(() => {});
      return { ok: true, chat: id, title: channel.title ?? null };
    });
  };

export const createAdminManage = (env, context, known) => ({
  chatAdmins: createAdmins(env, context.userClient, known),
  setAdmin: createSetAdmin(env, context, known),
  setHistoryHidden: createHistory(env, context),
  upgradeGroup: createUpgrade(env, context),
});

// An administrator's rights, as Telegram Desktop's "Admin rights" dialog
// offers them for each kind of chat (R-Y204; learned, never copied). Pure:
// the server shapes and checks with it, the page draws the checkboxes
// from it. Names are ChatAdminRights fields of layer 225.

export const RANK_MAX = 16;

/** Each kind of chat's rights, in the order the dialog lists them. */
export const ADMIN_RIGHTS = Object.freeze({
  channel: [
    'changeInfo',
    'postMessages',
    'editMessages',
    'deleteMessages',
    'inviteUsers',
    'postStories',
    'editStories',
    'deleteStories',
    'manageCall',
    'addAdmins',
  ],
  supergroup: [
    'changeInfo',
    'deleteMessages',
    'banUsers',
    'inviteUsers',
    'pinMessages',
    'manageTopics',
    'postStories',
    'editStories',
    'deleteStories',
    'manageCall',
    'addAdmins',
    'anonymous',
  ],
});

export const ALL_ADMIN_RIGHTS = Object.freeze(
  [...new Set([...ADMIN_RIGHTS.channel, ...ADMIN_RIGHTS.supergroup])].sort()
);

/** The kind of chat an id and its info make: channel, supergroup, group. */
export const kindOfChat = (chat, broadcast = false) => {
  if (!String(chat).startsWith('-100')) {
    return 'group';
  }
  return broadcast ? 'channel' : 'supergroup';
};

/** The rights the dialog lists for a kind (a basic group has none). */
export const rightsFor = (kind) => ADMIN_RIGHTS[kind] ?? [];

/** Rights as booleans for the keys of a kind, from a ChatAdminRights. */
export const shapeRights = (rights = {}, kind = 'supergroup') =>
  Object.fromEntries(
    rightsFor(kind).map((key) => [key, Boolean(rights?.[key])])
  );

/**
 * What of `wanted` the user may grant: only the rights the user has
 * (the creator has all), and only those of the kind of chat.
 */
export const grantable = (wanted, mine, kind, creator = false) =>
  Object.fromEntries(
    rightsFor(kind).map((key) => [
      key,
      Boolean(wanted?.[key]) && (creator || Boolean(mine?.[key])),
    ])
  );

/** Whether a body's rights are only known keys with boolean values. */
export const validRights = (rights) =>
  Boolean(rights) &&
  typeof rights === 'object' &&
  !Array.isArray(rights) &&
  Object.entries(rights).every(
    ([key, value]) =>
      ALL_ADMIN_RIGHTS.includes(key) && typeof value === 'boolean'
  );

/** A custom title: at most 16 characters, no line breaks. */
export const validRank = (rank) =>
  typeof rank === 'string' &&
  Array.from(rank).length <= RANK_MAX &&
  !/[\r\n]/.test(rank);

/** Whether any right is on. */
export const anyRight = (rights = {}) => Object.values(rights).some(Boolean);

/**
 * A group's permissions, slow mode and recent actions, as Telegram
 * Desktop's admin screens (R-Y133; learned, never copied):
 * - `chatPermissions({ chat })` — what members may do, the slow mode and
 *   whether the user may change them → `{ ok, rights, slowMode, canEdit }`;
 *   `rights` are positive: `true` is allowed (Telegram's flags say what is
 *   forbidden);
 * - `setPermissions({ chat, rights })` — the rights changed
 *   (messages.editChatDefaultBannedRights); rights not named stay as they
 *   are;
 * - `setSlowMode({ chat, seconds })` — a supergroup's slow mode
 *   (channels.toggleSlowMode);
 * - `adminLog({ chat, maxId? })` — a supergroup's or channel's recent
 *   actions, newest first, a page at a time (channels.getAdminLog) →
 *   `{ ok, events: [{ id, date, user, userName, kind, text?, msgId? }],
 *   next }`; `msgId` is a deleted message's id (R-Y200).
 * Telegram's errors become codes the page shows as text.
 */

import { canBanIn } from './telegram-chat-info.js';
import { connected, failureOf, runIn } from './telegram-stickers.js';

const CODES = {
  CHAT_ADMIN_REQUIRED: 'not-admin',
  CHAT_NOT_MODIFIED: 'not-modified',
  SECONDS_INVALID: 'seconds-invalid',
  CHANNEL_PRIVATE: 'no-access',
  CHANNEL_INVALID: 'no-access',
  PEER_ID_INVALID: 'no-access',
};

const asFailure = failureOf(CODES);
// Nothing to change is no failure.
const failure = (error) => {
  const out = asFailure(error);
  return out.code === 'not-modified' ? { ok: true } : out;
};
const bad = (code) => ({ ok: false, error: code, code });

const CHAT = /^-\d{1,20}$/;
const isChannel = (chat) => chat.startsWith('-100');
export const SLOW_MODES = Object.freeze([0, 10, 30, 60, 300, 900, 3600]);
const PAGE = 50;

// Each right the page shows, and the flags that forbid it.
const RIGHTS = {
  sendMessages: ['sendMessages'],
  sendMedia: [
    'sendMedia',
    'sendPhotos',
    'sendVideos',
    'sendDocs',
    'sendAudios',
    'sendVoices',
    'sendRoundvideos',
    'sendStickers',
    'sendGifs',
    'sendPolls',
  ],
  embedLinks: ['embedLinks'],
  inviteUsers: ['inviteUsers'],
  pinMessages: ['pinMessages'],
  changeInfo: ['changeInfo'],
  manageTopics: ['manageTopics'],
};
export const RIGHT_KEYS = Object.freeze(Object.keys(RIGHTS));

const textOf = (value) => String(value?.value ?? value);

/** Positive rights from a chat's default banned rights (none: all allowed). */
export const rightsOf = (banned = {}) =>
  Object.fromEntries(
    RIGHT_KEYS.map((key) => [key, !RIGHTS[key].some((flag) => banned?.[flag])])
  );

// Flags to ban for the rights that are not allowed.
const flagsOf = (rights) =>
  Object.fromEntries(
    RIGHT_KEYS.filter((key) => key in rights).flatMap((key) =>
      RIGHTS[key].map((flag) => [flag, !rights[key]])
    )
  );

// The full chat: a channel's or a basic group's, as telegram-chat-info.
const readChat = async (env, c, chat) => {
  if (isChannel(chat)) {
    const answer = await env.connection.withPeer(c.client, chat, (peer) =>
      c.client.invoke(new c.Api.channels.GetFullChannel({ channel: peer }))
    );
    const entity = (answer?.chats ?? []).find(Boolean) ?? {};
    return {
      ok: true,
      rights: rightsOf(entity.defaultBannedRights),
      slowMode: Number(answer?.fullChat?.slowmodeSeconds ?? 0),
      canEdit: canBanIn(entity) && !entity.broadcast,
    };
  }
  const answer = await c.client.invoke(
    new c.Api.messages.GetFullChat({
      chatId: c.helpers.returnBigInt(chat.slice(1)),
    })
  );
  const entity = (answer?.chats ?? []).find(Boolean) ?? {};
  return {
    ok: true,
    rights: rightsOf(entity.defaultBannedRights),
    slowMode: 0,
    canEdit: canBanIn(entity),
  };
};

const createPermissions =
  (env, userClient) =>
  async (body = {}) => {
    const chat = String(body.chat ?? '');
    if (!CHAT.test(chat)) {
      return bad('bad-request');
    }
    return connected(env, userClient, failure, (c) =>
      runIn(env, `admin:perms:${chat}`, () => readChat(env, c, chat))
    );
  };

const validRights = (rights) =>
  Boolean(rights) &&
  typeof rights === 'object' &&
  !Array.isArray(rights) &&
  Object.keys(rights).length > 0 &&
  Object.entries(rights).every(
    ([key, value]) => RIGHT_KEYS.includes(key) && typeof value === 'boolean'
  );

const createSetPermissions =
  (env, userClient, read) =>
  async (body = {}) => {
    const chat = String(body.chat ?? '');
    if (!CHAT.test(chat) || !validRights(body.rights)) {
      return bad('bad-request');
    }
    return connected(env, userClient, failure, async (c) => {
      // The call replaces every flag: those not named are kept as they are.
      let rights = body.rights;
      if (RIGHT_KEYS.some((key) => !(key in rights))) {
        const was = await read({ chat });
        if (!was.ok) {
          return was;
        }
        rights = { ...was.rights, ...rights };
      }
      await runIn(env, `admin:set:${chat}`, () =>
        env.connection.withPeer(c.client, chat, (peer) =>
          c.client.invoke(
            new c.Api.messages.EditChatDefaultBannedRights({
              peer,
              bannedRights: new c.Api.ChatBannedRights({
                ...flagsOf(rights),
                untilDate: 0,
              }),
            })
          )
        )
      );
      return { ok: true };
    });
  };

const createSlowMode =
  (env, userClient) =>
  async (body = {}) => {
    const chat = String(body.chat ?? '');
    const { seconds } = body;
    if (!CHAT.test(chat) || !isChannel(chat) || !SLOW_MODES.includes(seconds)) {
      return bad('bad-request');
    }
    return connected(env, userClient, failure, async (c) => {
      await runIn(env, `admin:slow:${chat}`, () =>
        env.connection.withPeer(c.client, chat, (peer) =>
          c.client.invoke(
            new c.Api.channels.ToggleSlowMode({ channel: peer, seconds })
          )
        )
      );
      return { ok: true };
    });
  };

const nameOf = (user) =>
  [user?.firstName, user?.lastName].filter(Boolean).join(' ') ||
  user?.username ||
  '';

// The person a participant record is about.
const partUser = (part) => textOf(part?.userId ?? part?.peer?.userId ?? '');

const messageText = (message) => message?.message || undefined;

// Each action: its kind and the text it carries.
const KINDS = {
  ChangeTitle: (a) => ['title', a.newValue],
  ChangeAbout: (a) => ['about', a.newValue],
  ChangePhoto: () => ['photo'],
  EditMessage: (a) => ['edit', messageText(a.newMessage)],
  DeleteMessage: (a) => ['delete', messageText(a.message)],
  UpdatePinned: (a) => ['pin', messageText(a.message)],
  ParticipantJoin: () => ['join'],
  ParticipantJoinByInvite: () => ['join'],
  ParticipantJoinByRequest: () => ['join'],
  ParticipantLeave: () => ['leave'],
  ParticipantInvite: (a, who) => ['invite', who(a.participant)],
  ParticipantToggleBan: (a, who) => ['ban', who(a.newParticipant)],
  ParticipantToggleAdmin: (a, who) => ['promote', who(a.newParticipant)],
  DefaultBannedRights: () => ['rights'],
  ToggleSlowMode: (a) => ['slowmode', String(a.newValue ?? 0)],
};

const eventOf = (event, names) => {
  const user = textOf(event.userId);
  const action = event.action ?? { className: '' };
  const who = (part) => names.get(partUser(part)) || partUser(part);
  const make =
    KINDS[action.className.replace('ChannelAdminLogEventAction', '')];
  const [kind, text] = make ? make(action, who) : ['other', action.className];
  // A deleted message's id, for "Not spam" (R-Y200).
  const msgId = kind === 'delete' ? action.message?.id : undefined;
  return {
    id: textOf(event.id),
    date: Number(event.date) * 1000,
    user,
    userName: names.get(user) || user,
    kind,
    ...(text ? { text } : {}),
    ...(msgId ? { msgId: Number(msgId) } : {}),
  };
};

const createAdminLog =
  (env, userClient) =>
  async (body = {}) => {
    const chat = String(body.chat ?? '');
    const maxId = String(body.maxId ?? '0');
    if (!CHAT.test(chat) || !isChannel(chat) || !/^\d{1,20}$/.test(maxId)) {
      return bad('bad-request');
    }
    return connected(env, userClient, failure, async (c) => {
      const answer = await runIn(env, `admin:log:${chat}:${maxId}`, () =>
        env.connection.withPeer(c.client, chat, (peer) =>
          c.client.invoke(
            new c.Api.channels.GetAdminLog({
              channel: peer,
              q: '',
              maxId: c.helpers.returnBigInt(maxId),
              minId: c.helpers.returnBigInt(0),
              limit: PAGE,
            })
          )
        )
      );
      const names = new Map(
        (answer?.users ?? []).map((u) => [textOf(u.id), nameOf(u)])
      );
      const events = (answer?.events ?? []).map((e) => eventOf(e, names));
      return {
        ok: true,
        events,
        next: events.length >= PAGE ? events.at(-1).id : null,
      };
    });
  };

export const createAdminActions = (env, context) => {
  const chatPermissions = createPermissions(env, context.userClient);
  return {
    chatPermissions,
    setPermissions: createSetPermissions(
      env,
      context.userClient,
      chatPermissions
    ),
    setSlowMode: createSlowMode(env, context.userClient),
    adminLog: createAdminLog(env, context.userClient),
  };
};

/**
 * The bot and mini-app extras of Telegram Desktop (R-Y194; learned,
 * never copied). All reads; the only send is the existing inline-result
 * send, asked for by the page on a click:
 * - `appsPopular({ offset?, limit? })` — the popular mini apps
 *   (bots.getPopularAppBots), a page at a time → `{ ok, apps: [{ chat,
 *   name, username, users, mainApp }], next }` (`users` the bot's monthly
 *   users when Telegram says, `next` the offset of the next page);
 * - `botSimilar({ chat })` — the bots Telegram recommends beside a bot
 *   (bots.getBotRecommendations; Telegram limits the list for accounts
 *   without Premium) → `{ ok, bots: [same shape] }`;
 * - `preparedMessage({ bot, id })` — the message a mini app prepared
 *   (messages.getPreparedInlineMessage) → `{ ok, queryId, id, preview:
 *   { type, title, description }, peerTypes, bot }`; it is then offered
 *   to the inline send, which sends it to one chat chosen by the click;
 * - `collectibleInfo({ kind, value })` — what Fragment knows of a
 *   collectible username or phone number (fragment.getCollectibleInfo) →
 *   `{ ok, date, price: { amount, currency }, crypto: { amount, currency },
 *   url }` (amounts in the currency's smallest units).
 * Answers are kept five minutes. Errors become codes.
 */

import { connected, runIn, failureOf } from './telegram-stickers.js';
import { inputUserOf } from './telegram-peer-actions.js';

const CODES = {
  BOT_INVALID: 'no-bot',
  USER_ID_INVALID: 'no-bot',
  PEER_ID_INVALID: 'no-bot',
  USERNAME_INVALID: 'not-collectible',
  PHONE_NUMBER_INVALID: 'not-collectible',
  MESSAGE_EXPIRED: 'expired',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);
const BAD = { ok: false, error: 'bad request', code: 'bad-request' };
const KEEP_MS = 5 * 60_000;

export const MAX_PAGE = 50;
export const DEFAULT_PAGE = 20;
export const ID = /^\d{1,20}$/;
export const PREPARED_ID = /^[A-Za-z0-9_-]{1,128}$/;
export const USERNAME = /^[A-Za-z][A-Za-z0-9_]{3,31}$/;
export const PHONE = /^\+?\d{5,20}$/;
export const KINDS = ['username', 'phone'];

const textOf = (value) => String(value?.value ?? value);
const numberOf = (value) => Number(textOf(value ?? 0)) || 0;

/** A bot as the page lists it; null for anything but a user. */
export const botOf = (user) =>
  user?.className === 'User'
    ? {
        chat: textOf(user.id),
        name:
          [user.firstName, user.lastName].filter(Boolean).join(' ') ||
          String(user.username ?? ''),
        username: user.username ?? null,
        users:
          user.botActiveUsers === undefined || user.botActiveUsers === null
            ? null
            : numberOf(user.botActiveUsers),
        mainApp: Boolean(user.botHasMainApp),
      }
    : null;

/** The kinds of chat a prepared message may go to, as words. */
export const PEER_TYPES = {
  InlineQueryPeerTypeSameBotPM: 'same-bot',
  InlineQueryPeerTypePM: 'users',
  InlineQueryPeerTypeBotPM: 'bots',
  InlineQueryPeerTypeChat: 'groups',
  InlineQueryPeerTypeMegagroup: 'groups',
  InlineQueryPeerTypeBroadcast: 'channels',
};

/** The words for Telegram's peer types, each once. */
export const peerTypesOf = (list) => [
  ...new Set(
    (Array.isArray(list) ? list : [])
      .map((type) => PEER_TYPES[type?.className])
      .filter(Boolean)
  ),
];

/** The prepared result as a preview (the page never loads its media). */
export const previewOf = (result) => ({
  type: String(result?.type ?? ''),
  title: String(result?.title ?? ''),
  description: String(result?.description ?? ''),
});

/** Whether a collectible request is well formed. */
export const collectibleOk = (kind, value) =>
  (kind === 'username' && USERNAME.test(String(value ?? ''))) ||
  (kind === 'phone' && PHONE.test(String(value ?? '')));

const keeper = () => {
  const map = new Map();
  return {
    get: (key, now) => {
      const hit = map.get(key);
      return hit && now - hit.at < KEEP_MS ? hit.value : undefined;
    },
    set: (key, value, now) => {
      map.set(key, { at: now, value });
      while (map.size > 60) {
        map.delete(map.keys().next().value);
      }
      return value;
    },
  };
};

export const createApps = (env, { userClient, tools, offer }) => {
  const now = () => (env.now ?? Date.now)();
  const memory = keeper();

  // A listed bot is remembered, so opening it reads it at once.
  const remember = async (users) => {
    for (const user of users) {
      const bot = botOf(user);
      if (!bot) {
        continue;
      }
      try {
        await env.peers?.remember(
          bot.chat,
          user,
          tools?.dialogOfEntity?.(bot.chat, user)
        );
      } catch {
        // the list is shown all the same
      }
    }
  };

  const inputOf = (c, chat) =>
    env.connection.withPeer(c.client, chat, (peer) => inputUserOf(c, peer));

  const appsPopular = async (body = {}) => {
    const offset = String(body.offset ?? '');
    const limit = Number(body.limit ?? DEFAULT_PAGE);
    if (
      offset.length > 256 ||
      !Number.isInteger(limit) ||
      limit < 1 ||
      limit > MAX_PAGE
    ) {
      return BAD;
    }
    const key = `popular:${offset}:${limit}`;
    const have = memory.get(key, now());
    if (have) {
      return have;
    }
    return connected(env, userClient, failure, async (c) => {
      const answer = await runIn(env, `apps:popular:${offset}`, () =>
        c.client.invoke(new c.Api.bots.GetPopularAppBots({ offset, limit }))
      );
      const users = answer?.users ?? [];
      await remember(users);
      return memory.set(
        key,
        {
          ok: true,
          apps: users.map(botOf).filter(Boolean),
          next: answer?.nextOffset || null,
        },
        now()
      );
    });
  };

  const botSimilar = async (body = {}) => {
    const chat = String(body.chat ?? '');
    if (!ID.test(chat)) {
      return BAD;
    }
    const have = memory.get(`similar:${chat}`, now());
    if (have) {
      return have;
    }
    return connected(env, userClient, failure, async (c) => {
      const answer = await runIn(env, `apps:similar:${chat}`, async () =>
        c.client.invoke(
          new c.Api.bots.GetBotRecommendations({ bot: await inputOf(c, chat) })
        )
      );
      const users = answer?.users ?? [];
      await remember(users);
      return memory.set(
        `similar:${chat}`,
        { ok: true, bots: users.map(botOf).filter(Boolean) },
        now()
      );
    });
  };

  const preparedMessage = async (body = {}) => {
    const bot = String(body.bot ?? '');
    const id = String(body.id ?? '');
    if (!ID.test(bot) || !PREPARED_ID.test(id)) {
      return BAD;
    }
    return connected(env, userClient, failure, async (c) => {
      const answer = await runIn(env, `apps:prepared:${id}`, async () =>
        c.client.invoke(
          new c.Api.messages.GetPreparedInlineMessage({
            bot: await inputOf(c, bot),
            id,
          })
        )
      );
      const result = answer?.result;
      if (!result?.id || answer.queryId === undefined) {
        return { ok: false, error: 'no message', code: 'expired' };
      }
      const queryId = textOf(answer.queryId);
      offer?.({ queryId, id: String(result.id) });
      return {
        ok: true,
        queryId,
        id: String(result.id),
        preview: previewOf(result),
        peerTypes: peerTypesOf(answer.peerTypes),
        bot,
      };
    });
  };

  const collectibleInfo = async (body = {}) => {
    const { kind, value } = body;
    if (!collectibleOk(kind, value)) {
      return BAD;
    }
    const key = `collectible:${kind}:${value}`;
    const have = memory.get(key, now());
    if (have) {
      return have;
    }
    return connected(env, userClient, failure, async (c) => {
      const collectible =
        kind === 'username'
          ? new c.Api.InputCollectibleUsername({ username: value })
          : new c.Api.InputCollectiblePhone({ phone: value });
      const info = await runIn(env, `apps:${key}`, () =>
        c.client.invoke(new c.Api.fragment.GetCollectibleInfo({ collectible }))
      );
      return memory.set(
        key,
        {
          ok: true,
          date: numberOf(info?.purchaseDate),
          price: {
            amount: textOf(info?.amount ?? 0),
            currency: String(info?.currency ?? ''),
          },
          crypto: {
            amount: textOf(info?.cryptoAmount ?? 0),
            currency: String(info?.cryptoCurrency ?? ''),
          },
          url: String(info?.url ?? ''),
        },
        now()
      );
    });
  };

  return { appsPopular, botSimilar, preparedMessage, collectibleInfo };
};

/**
 * Profile photos of Telegram peers (users, groups, channels), cached on
 * disk and served from there: GET /api/telegram/avatar?peer=&size=s|b.
 *
 * Each avatar is downloaded once and kept at
 * `<dir>/avatars/<peer>-<size>` with a `.type` file. A "no photo" result
 * is remembered for 24 h (a `.none` file), a failed download is tried
 * again after 5 minutes; a cached avatar older than
 * 24 h is re-downloaded in the background while the cached one is served.
 *
 * Downloads go through the account's queue at `list` priority with key
 * `avatar:<peer>:<size>` — after what the user scrolls to, never blocking
 * it (R-Y34). Secrets are never logged.
 */

import { promises as fs } from 'node:fs';
import path from 'node:path';
import { importTelegram } from './telegram-layer.js';

const MS_PER_DAY = 24 * 60 * 60_000;
const PEER = /^-?\d{1,20}$/;
// A download that failed is tried again after this long.
const RETRY_MS = 5 * 60_000;

const peerKind = (peer) => {
  if (peer.startsWith('-100')) {
    return 'channel';
  }
  if (peer.startsWith('-')) {
    return 'group';
  }
  return 'user';
};

const readCache = async (file) => {
  try {
    const buffer = await fs.readFile(file);
    return buffer.length > 0 ? buffer : null;
  } catch {
    return null;
  }
};

const fileAge = async (file) => {
  try {
    const s = await fs.stat(file);
    return Date.now() - s.mtimeMs;
  } catch {
    return Infinity;
  }
};

// A chat the account holds is asked for by its stored peer; someone
// seen only as a group's member, by the message they wrote there
// (Telegram's InputUserFromMessage: no access hash of theirs is
// needed); else by id, which GramJS finds in what it has seen.
const inputOf = async ({ peers, importer }, peer, { chat, msg } = {}) => {
  const stored = await peers.input(peer);
  if (stored) {
    return { entity: stored };
  }
  const where =
    chat && msg && !peer.startsWith('-') ? await peers.input(chat) : null;
  if (!where) {
    return { entity: peer };
  }
  const { Api, helpers } = await importer();
  return {
    byMessage: new Api.InputUserFromMessage({
      peer: where,
      msgId: Number(msg),
      userId: helpers.returnBigInt(peer),
    }),
    Api,
  };
};

// GramJS cannot look up a user by message itself (it casts the input
// to an id and fails), so the user is asked for first; their photo is
// then read from the answer, and their peer kept for next time.
const entityOf = async (client, deps, peer, context) => {
  const { entity, byMessage, Api } = await inputOf(deps, peer, context);
  if (!byMessage) {
    return entity;
  }
  const [user] = await client.invoke(
    new Api.users.GetUsers({ id: [byMessage] })
  );
  if (!user || user.className === 'UserEmpty') {
    return null;
  }
  const name = [user.firstName, user.lastName].filter(Boolean).join(' ');
  await Promise.resolve(
    deps.peers.remember?.(peer, user, { isUser: true, name: name || null })
  ).catch(() => {});
  return user;
};

/**
 * `read({ peer, size })` → `{ buffer, mimeType }` or null when the peer
 * has no photo. `size` is `'s'` (small, default) or `'b'` (big). `dir`
 * is the telegram media folder; `queue`, `client`, `peers` are the
 * account's shared instances.
 */
export const createAvatarReader = ({
  dir,
  queue,
  client: clientOf,
  peers,
  importer = importTelegram,
  log = () => {},
  retryMs = RETRY_MS,
}) => {
  const avatarDir = path.join(dir, 'avatars');

  const fetchAvatar = async (peer, isBig, context) => {
    const client = await clientOf();
    if (!client) {
      return undefined;
    }
    const entity = await entityOf(client, { peers, importer }, peer, context);
    if (!entity) {
      return null;
    }
    const buf = await client.downloadProfilePhoto(entity, { isBig });
    return buf?.length ? Buffer.from(buf) : null;
  };

  const refresh = (peer, sz, context) => {
    const base = path.join(avatarDir, `${peer}-${sz}`);
    const noneFile = `${base}.none`;
    queue
      .run(`avatar:${peer}:${sz}:refresh`, 'list', async () => {
        const buf = await fetchAvatar(peer, sz === 'b', context);
        if (buf === undefined) {
          return;
        }
        await fs.mkdir(avatarDir, { recursive: true });
        if (buf?.length) {
          await fs.writeFile(base, buf);
          await fs.writeFile(`${base}.type`, 'image/jpeg');
          // Clear an old .none if present.
          await fs.unlink(noneFile).catch(() => {});
        } else {
          await fs.writeFile(noneFile, '');
        }
      })
      .catch(() => {});
  };

  // Where a group member wrote, for Telegram to find them by.
  const contextOf = (chat, msg) =>
    PEER.test(String(chat ?? '')) &&
    Number.isInteger(Number(msg)) &&
    Number(msg) > 0
      ? { chat: String(chat), msg: Number(msg) }
      : {};

  // Kept on disk: the photo (re-read in the background once a day old).
  const fromDisk = async (base, peer, sz, context) => {
    const cached = await readCache(base);
    if (!cached) {
      return null;
    }
    const typeBuf = await readCache(`${base}.type`);
    if ((await fileAge(base)) >= MS_PER_DAY) {
      refresh(peer, sz, context);
    }
    return { buffer: cached, mimeType: typeBuf?.toString() || 'image/jpeg' };
  };

  // Read from Telegram and kept; "none" is kept too, unless Telegram
  // only asked to wait.
  const download = async (base, peer, sz, context) => {
    const started = Date.now();
    const done = (bytes, extra = {}) =>
      log({
        event: 'telegram_avatar',
        peer_kind: peerKind(peer),
        size: sz,
        bytes,
        by_message: Boolean(context.msg),
        duration_ms: Date.now() - started,
        ...extra,
      });
    let buffer;
    try {
      buffer = await queue.run(`avatar:${peer}:${sz}`, 'list', () =>
        fetchAvatar(peer, sz === 'b', context)
      );
    } catch (error) {
      // A failure is not "no photo": it is asked again a while later.
      const code = String(error.errorMessage ?? error.message ?? '');
      done(0, { level: 'warn', failed: code.slice(0, 60) });
      failedAt.set(base, Date.now());
      return null;
    }
    if (buffer === undefined) {
      return null;
    }
    await fs.mkdir(avatarDir, { recursive: true });
    if (!buffer?.length) {
      await fs.writeFile(`${base}.none`, '');
      done(0);
      return null;
    }
    await fs.writeFile(base, buffer);
    await fs.writeFile(`${base}.type`, 'image/jpeg');
    done(buffer.length);
    return { buffer, mimeType: 'image/jpeg' };
  };

  // One download per photo, however many rows ask for it at once.
  const inFlight = new Map();
  // When a download last failed, to wait a little before the next.
  const failedAt = new Map();

  const read = async ({ peer, size = 's', chat, msg } = {}) => {
    const p = String(peer ?? '');
    const sz = size === 'b' ? 'b' : 's';
    if (!PEER.test(p)) {
      return null;
    }
    const base = path.join(avatarDir, `${p}-${sz}`);
    // "No photo" is remembered for 24 h: skip the download.
    if ((await fileAge(`${base}.none`)) < MS_PER_DAY) {
      return null;
    }
    const context = contextOf(chat, msg);
    const kept = await fromDisk(base, p, sz, context);
    if (kept) {
      return kept;
    }
    if (Date.now() - (failedAt.get(base) ?? -Infinity) < retryMs) {
      return null;
    }
    if (!inFlight.has(base)) {
      inFlight.set(
        base,
        download(base, p, sz, context).finally(() => inFlight.delete(base))
      );
    }
    return inFlight.get(base);
  };

  return { read };
};

/**
 * The slow download of every chat's whole history (R-Y30), so the store
 * holds it for offline reading, analysis and learning replies — and
 * Telegram is never asked for it again.
 *
 *   1. the whole chat list first (its pages after the first one);
 *   2. then private chats, a page at a time, taking turns (the chat read
 *      longest ago goes next), so short chats are done early and a long
 *      one does not hold the others back;
 *   3. then groups the same way;
 *   4. channels never: they are read on demand only (opened or shown).
 *
 * One request every few seconds, at `background` priority, and none at
 * all while the user waits for something (anything queued at `prefetch`
 * or above) or Telegram asked to wait. Progress lives in the store: each
 * chat's `history:` link (./telegram-history.js) says how far back it is
 * stored, so a restart goes on where it stopped. It also waits while the
 * server's memory is nearly full (the store is held in memory): more
 * history then waits for room instead of stopping the server. A chat
 * Telegram cannot address (no access hash for its user, a channel now
 * private) is passed over for the rest of the run instead of holding
 * every other chat back.
 */

import { getHeapStatistics } from 'node:v8';
import { historyLinkId, floodSeconds } from './telegram-history.js';

export const BACKFILL_EVERY_MS = 5000;
export const BACKFILL_PAGE = 100;
const DIALOGS_PAGE = 100;
const CHATS_FRESH_MS = 60_000;
const MAX_BACKOFF_MS = 5 * 60_000;
// Past this share of the heap limit, nothing more is downloaded.
export const BACKFILL_HEAP_SHARE = 0.7;

/** Whether the heap is too full to take more history. */
export const heapNearlyFull = (stats = getHeapStatistics()) =>
  stats.used_heap_size > BACKFILL_HEAP_SHARE * stats.heap_size_limit;

// What the background download covers, in order.
export const BACKFILL_ORDER = Object.freeze(['private', 'group']);

// Errors that are about the chat itself, not the connection.
const UNREACHABLE =
  /input entity|PEER_ID_INVALID|CHANNEL_PRIVATE|CHANNEL_INVALID|USER_ID_INVALID|CHAT_ID_INVALID/;

/** Whether reading a chat failed because Telegram cannot reach it. */
export const unreachableChat = (error) =>
  UNREACHABLE.test(`${error?.errorMessage ?? ''} ${error?.message ?? ''}`);

/** `private`, `group` or `channel`, from a message's `chatType`. */
export const backfillKind = (chatType) => {
  if (chatType === 'personal_chat') {
    return 'private';
  }
  return chatType === 'channel' ? 'channel' : 'group';
};

/**
 * The next chat to read further back, or null when every private chat
 * and group is stored to its first message. `chats`: `{ chat, chatType,
 * at }` (`at`: its newest message); `records`: chat → `history:` link;
 * `first`: chats to read before any other, whatever their kind.
 */
export const nextBackfill = (
  chats = [],
  records = new Map(),
  skip = [],
  first = []
) => {
  const skipped = new Set(skip);
  const due = (c) => !records.get(c.chat)?.complete && !skipped.has(c.chat);
  // A chat asked for (someone is being learned about) comes first.
  const wanted = first
    .map((chat) => chats.find((c) => c.chat === String(chat)))
    .find((c) => c && due(c));
  if (wanted) {
    return {
      chat: wanted.chat,
      kind: backfillKind(wanted.chatType),
      before: records.get(wanted.chat)?.oldest ?? null,
      wanted: true,
    };
  }
  for (const kind of BACKFILL_ORDER) {
    const todo = chats.filter(
      (c) =>
        backfillKind(c.chatType) === kind &&
        !records.get(c.chat)?.complete &&
        !skipped.has(c.chat)
    );
    if (todo.length > 0) {
      const turn = (c) => String(records.get(c.chat)?.at ?? '');
      todo.sort(
        (a, b) =>
          turn(a).localeCompare(turn(b)) ||
          String(b.at ?? '').localeCompare(String(a.at ?? ''))
      );
      const record = records.get(todo[0].chat);
      return {
        chat: todo[0].chat,
        kind,
        before: record?.oldest ?? null,
      };
    }
  }
  return null;
};

/** How far the download is: `{ phase, chats, complete }`. */
export const backfillProgress = (phase, chats = [], records = new Map()) => {
  const covered = chats.filter((c) =>
    BACKFILL_ORDER.includes(backfillKind(c.chatType))
  );
  return {
    phase,
    chats: covered.length,
    complete: covered.filter((c) => records.get(c.chat)?.complete).length,
  };
};

// How long to wait after a step: long when nothing is left, short for
// a chat someone waits for.
const paceAfter = (did, everyMs) => {
  if (did === 'done' || did === 'memory') {
    return everyMs * 12;
  }
  return did === 'wanted' ? Math.ceil(everyMs / 2) : everyMs;
};

/**
 * `start()` / `stop()` the download; `step()` does one request (tests
 * call it directly). `chats()` lists the account's chats; `pages` is the
 * account's page reader, `queue` its request queue.
 */
const recordsOf = async (store, list) =>
  new Map(
    await Promise.all(
      list.map(async (c) => [c.chat, await store.get(historyLinkId(c.chat))])
    )
  );

const backfillDelay = (failures, base, heldFor) =>
  Math.max(
    failures === 0 ? base : Math.min(MAX_BACKOFF_MS, base * 2 ** failures),
    heldFor
  );

const cachedChatList = async (listed, chats, at) =>
  at - listed.at >= CHATS_FRESH_MS
    ? { at, chats: (await chats()) ?? [] }
    : listed;

export const createBackfill = ({
  store,
  queue,
  pages,
  chats,
  credentials,
  syncId,
  log = () => {},
  now = () => Date.now(),
  everyMs = BACKFILL_EVERY_MS,
  memoryFull = heapNearlyFull,
}) => {
  let timer = null;
  let failures = 0;
  let listed = { at: -Infinity, chats: [] };
  const skip = new Set(); // chats Telegram gave nothing older for
  const wanted = new Set(); // chats asked for first, until whole
  let focus = null;
  const focused = () => (focus && focus.until > now() ? focus.chat : null);
  let progress = { phase: 'idle', chats: 0, complete: 0 };
  let waitedForMemory = false;

  const histories = async () => {
    listed = await cachedChatList(listed, chats, now());
    const list = listed.chats;
    const records = await recordsOf(store, list);
    for (const chat of wanted) {
      if (records.get(chat)?.complete || skip.has(chat)) {
        wanted.delete(chat);
      }
    }
    const active = focused();
    const next = nextBackfill(
      list,
      records,
      [...skip],
      [active, ...wanted].filter(Boolean)
    );
    progress = backfillProgress(next?.kind ?? 'done', list, records);
    if (!next) {
      return 'done';
    }
    let answer;
    try {
      answer = await pages.history({
        chat: next.chat,
        before: next.before,
        limit: BACKFILL_PAGE,
        priority: next.chat === active ? 'view' : 'background',
      });
    } catch (error) {
      if (!unreachableChat(error)) {
        throw error;
      }
      skip.add(next.chat);
      log({
        level: 'warn',
        event: 'telegram_backfill_chat_skipped',
        kind: next.kind,
        error: error?.message,
      });
      return 'skipped';
    }
    if (answer?.cached) {
      skip.add(next.chat);
    }
    return next.wanted ? 'wanted' : next.kind;
  };

  /** One request, if one is due; what it did. */
  const step = async () => {
    if ((await credentials())?.kind !== 'user') {
      return 'idle';
    }
    const active =
      focused() && !(await store.get(historyLinkId(focused())))?.complete;
    if (
      queue.pending(active ? 'view' : 'prefetch') > 0 ||
      queue.heldFor() > 0
    ) {
      return 'yield';
    }
    if (memoryFull()) {
      if (!waitedForMemory) {
        log({ level: 'warn', event: 'telegram_backfill_memory_full' });
      }
      waitedForMemory = true;
      progress = { ...progress, phase: 'memory' };
      return 'memory';
    }
    waitedForMemory = false;
    const state = (await store.get(syncId)) ?? {};
    // The open conversation does not wait for every dialog to be listed.
    if (active) {
      return histories();
    }
    if (!state.dialogsComplete) {
      await pages.moreDialogs({ limit: DIALOGS_PAGE, priority: 'background' });
      listed = { at: -Infinity, chats: [] };
      progress = { ...progress, phase: 'dialogs' };
      return 'dialogs';
    }
    return histories();
  };

  // Longer after each failure in a row; never before Telegram's "wait".

  const schedule = (ms) => {
    timer = globalThis.setTimeout(tick, ms);
    timer.unref?.();
  };

  async function tick() {
    let base = everyMs;
    try {
      const did = await step();
      failures = 0;
      // Nothing to read now; new chats may come with the list.
      base = paceAfter(did, everyMs);
    } catch (error) {
      const wait = floodSeconds(error);
      failures = wait ? 0 : failures + 1;
      log({
        level: wait ? 'info' : 'warn',
        event: wait ? 'telegram_backfill_waits' : 'telegram_backfill_failed',
        code: error?.code ?? null,
        error: error?.message,
      });
    }
    if (timer !== null) {
      schedule(backfillDelay(failures, base, queue.heldFor()));
    }
  }

  return {
    step,
    /** Read this chat's history before any other's. */
    prefer: (chat) => {
      wanted.add(String(chat));
    },
    focus: (chat) => {
      focus = { chat: String(chat), until: now() + 60_000 };
      listed.at = -Infinity;
      skip.delete(String(chat));
    },
    active: (chat) =>
      everyMs > 0 && focused() === String(chat) && progress.phase !== 'memory',
    wanted: (chat) => wanted.has(String(chat)),
    start: () => {
      if (timer === null && everyMs > 0) {
        schedule(everyMs);
      }
    },
    stop: () => {
      globalThis.clearTimeout(timer);
      timer = null;
    },
    progress: () => progress,
  };
};

/**
 * Channel boosts, as Telegram Desktop has them (R-Y173; learned, never
 * copied): a channel or supergroup has a boost level that Premium users
 * raise by giving it one of their boost slots.
 * - `boostsStatus({ chat })` — premium.getBoostsStatus → `{ ok, level,
 *   boosts, giftBoosts, currentLevelBoosts, nextLevelBoosts (null at the
 *   top), url, mine }` (`mine`: the user already boosts it);
 * - `myBoosts({ chat })` — premium.getMyBoosts → `{ ok, premium, slots:
 *   [{ slot, chat (marked id or null), title, expires, cooldownUntil }] }`
 *   (dates are unix seconds, 0 when none); an account without Premium has
 *   no slots;
 * - `boostApply({ chat, slot })` — premium.applyBoost with that one slot,
 *   a WRITE made only on the user's click → `{ ok, slots }`;
 * - `boostersList({ chat, offset? })` — premium.getBoostsList, for admins,
 *   a page of 50 → `{ ok, count, boosters: [{ user, name, date, expires,
 *   multiplier, gift, giveaway }], next }`.
 * Telegram's errors become codes the page shows as text.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';

export const BOOSTERS_PAGE = 50;

const CODES = {
  PREMIUM_ACCOUNT_REQUIRED: 'premium',
  BOOST_NOT_MODIFIED: 'already',
  PEER_ID_INVALID: 'no-chat',
  CHANNEL_INVALID: 'no-chat',
  BOOSTS_EMPTY: 'premium',
  CHAT_ADMIN_REQUIRED: 'admin',
  FLOOD_WAIT: 'flood',
};
const failure = failureOf(CODES);
const BAD = { ok: false, error: 'bad request', code: 'failed' };
const CHANNEL = /^-100\d{1,20}$/;
const text = (value) => String(value?.value ?? value ?? '');
const whole = (n) => Number(n ?? 0) || 0;

const nameOf = (user) =>
  [user?.firstName, user?.lastName].filter(Boolean).join(' ') ||
  (user?.username ? `@${user.username}` : '');

/** Telegram's boosts status as the page's. */
export const statusOf = (s) => ({
  level: whole(s?.level),
  boosts: whole(s?.boosts),
  giftBoosts: whole(s?.giftBoosts),
  currentLevelBoosts: whole(s?.currentLevelBoosts),
  nextLevelBoosts:
    s?.nextLevelBoosts === undefined ? null : whole(s.nextLevelBoosts),
  url: String(s?.boostUrl ?? ''),
  mine: Boolean(s?.myBoost),
});

// A peer as the page's marked chat id.
const markedOf = (peer) => {
  if (peer?.className === 'PeerChannel') {
    return `-100${text(peer.channelId)}`;
  }
  return peer?.className === 'PeerChat' ? `-${text(peer.chatId)}` : null;
};

/** The user's boost slots from premium.myBoosts. */
export const slotsOf = (answer) => {
  const titles = new Map(
    (answer?.chats ?? []).map((chat) => [
      text(chat.id),
      String(chat.title ?? ''),
    ])
  );
  return (answer?.myBoosts ?? []).map((boost) => {
    const chat = markedOf(boost.peer);
    const id = text(boost.peer?.channelId ?? boost.peer?.chatId);
    return {
      slot: whole(boost.slot),
      chat,
      title: chat ? (titles.get(id) ?? '') : '',
      expires: whole(boost.expires),
      cooldownUntil: whole(boost.cooldownUntilDate),
    };
  });
};

/** Telegram's boosters list as the page's. */
export const boostersOf = (answer) => {
  const users = new Map((answer?.users ?? []).map((u) => [text(u.id), u]));
  return (answer?.boosts ?? []).map((b) => ({
    user: b.userId === undefined ? null : text(b.userId),
    name: nameOf(users.get(text(b.userId))),
    date: whole(b.date),
    expires: whole(b.expires),
    multiplier: Math.max(1, whole(b.multiplier)),
    gift: Boolean(b.gift),
    giveaway: Boolean(b.giveaway),
  }));
};

export const createBoosts = (env, { userClient }) => {
  const doing = (key, use) =>
    connected(env, userClient, failure, (c) => runIn(env, key, () => use(c)));
  const withChat = (c, chat, use) =>
    env.connection.withPeer(c.client, chat, use);

  const boostsStatus = async ({ chat } = {}) =>
    !CHANNEL.test(String(chat ?? ''))
      ? BAD
      : doing(`boosts:${chat}`, (c) =>
          withChat(c, String(chat), async (peer) => ({
            ok: true,
            ...statusOf(
              await c.client.invoke(new c.Api.premium.GetBoostsStatus({ peer }))
            ),
          }))
        );

  const myBoosts = async ({ chat } = {}) =>
    !CHANNEL.test(String(chat ?? ''))
      ? BAD
      : doing('my-boosts', async (c) => {
          const answer = await c.client.invoke(new c.Api.premium.GetMyBoosts());
          const me = await c.client.getMe?.().catch(() => null);
          return {
            ok: true,
            premium: Boolean(me?.premium),
            slots: slotsOf(answer),
          };
        });

  const boostApply = async ({ chat, slot } = {}) =>
    !CHANNEL.test(String(chat ?? '')) || !Number.isInteger(slot) || slot < 1
      ? BAD
      : doing(`boost-apply:${chat}`, (c) =>
          withChat(c, String(chat), async (peer) => ({
            ok: true,
            slots: slotsOf(
              await c.client.invoke(
                new c.Api.premium.ApplyBoost({ slots: [slot], peer })
              )
            ),
          }))
        );

  const boostersList = async ({ chat, offset = '' } = {}) =>
    !CHANNEL.test(String(chat ?? '')) ||
    typeof offset !== 'string' ||
    offset.length > 200
      ? BAD
      : doing(`boosters:${chat}`, (c) =>
          withChat(c, String(chat), async (peer) => {
            const answer = await c.client.invoke(
              new c.Api.premium.GetBoostsList({
                peer,
                offset,
                limit: BOOSTERS_PAGE,
              })
            );
            return {
              ok: true,
              count: whole(answer?.count),
              boosters: boostersOf(answer),
              next: answer?.nextOffset ? String(answer.nextOffset) : null,
            };
          })
        );

  return { boostsStatus, myBoosts, boostApply, boostersList };
};

/**
 * A bot's commands, as Telegram Desktop lists them (R-Y135; learned,
 * never copied): `botCommands({ chat })` for a bot chat
 * (users.getFullUser → botInfo) or a group (messages.getFullChat /
 * channels.getFullChannel → botInfo[], one per bot) →
 * `{ ok, commands: [{ command, description, bot, botName, username }],
 * menu: { kind: 'commands'|'webapp'|'default', text?, url? } }`.
 * `menu` is the bot's menu button of a bot chat. Answers are kept for
 * ten minutes, per chat.
 */

import { runIn, connected, failureOf } from './telegram-stickers.js';

const CODES = {
  CHANNEL_PRIVATE: 'no-access',
  CHAT_ID_INVALID: 'no-access',
  PEER_ID_INVALID: 'no-access',
  USER_ID_INVALID: 'no-access',
};

const failure = failureOf(CODES);

const CHAT = /^-?\d{1,20}$/;
const KEEP_MS = 10 * 60_000;
const textOf = (value) => String(value?.value ?? value);

const nameOf = (user) =>
  [user?.firstName, user?.lastName].filter(Boolean).join(' ') ||
  user?.username ||
  '';

const menuOf = (button) => {
  if (button?.className === 'BotMenuButton' && button.url) {
    return { kind: 'webapp', text: button.text || '', url: button.url };
  }
  return {
    kind:
      button?.className === 'BotMenuButtonCommands' ? 'commands' : 'default',
  };
};

// One bot's commands, named by the users Telegram sent along.
const commandsOf = (info, users) => {
  const bot = textOf(info?.userId ?? '');
  const user = users.get(bot);
  return (info?.commands ?? []).map((one) => ({
    command: String(one.command),
    description: String(one.description ?? ''),
    bot,
    botName: nameOf(user),
    username: user?.username ?? null,
  }));
};

const shape = (answer, infos) => {
  const users = new Map((answer?.users ?? []).map((u) => [textOf(u.id), u]));
  return infos.filter(Boolean).flatMap((info) => commandsOf(info, users));
};

// A group's bots: one botInfo each.
const askGroup = async (c, env, chat) => {
  const channel = chat.startsWith('-100');
  const answer = await runIn(env, `bot-commands:${chat}`, () =>
    env.connection.withPeer(c.client, chat, (peer) =>
      c.client.invoke(
        channel
          ? new c.Api.channels.GetFullChannel({ channel: peer })
          : new c.Api.messages.GetFullChat({
              chatId: c.helpers.returnBigInt(chat.slice(1)),
            })
      )
    )
  );
  return {
    ok: true,
    commands: shape(answer, answer?.fullChat?.botInfo ?? []),
    menu: { kind: 'default' },
  };
};

// A bot chat: the bot's own botInfo and menu button.
const askBot = async (c, env, chat) => {
  const answer = await runIn(env, `bot-commands:${chat}`, () =>
    env.connection.withPeer(c.client, chat, (id) =>
      c.client.invoke(new c.Api.users.GetFullUser({ id }))
    )
  );
  const info = answer?.fullUser?.botInfo;
  return {
    ok: true,
    commands: shape(answer, info ? [{ ...info, userId: chat }] : []),
    menu: menuOf(info?.menuButton),
  };
};

export const createBotCommands = (env, context) => {
  const kept = new Map();
  return {
    botCommands: async ({ chat } = {}) => {
      const target = String(chat ?? '');
      if (!CHAT.test(target)) {
        return { ok: false, error: 'bad chat', code: 'failed' };
      }
      const hit = kept.get(target);
      if (hit && Date.now() - hit.at < KEEP_MS) {
        return hit.answer;
      }
      const answer = await connected(env, context.userClient, failure, (c) =>
        target.startsWith('-')
          ? askGroup(c, env, target)
          : askBot(c, env, target)
      );
      if (answer.ok) {
        kept.set(target, { at: Date.now(), answer });
      }
      return answer;
    },
  };
};

/**
 * A bot's login links and the attachment menu (R-Y201; learned from how
 * Telegram Desktop behaves, never copied):
 * - `botUrlAuth({ chat, id, buttonId })` or `botUrlAuth({ url })`
 *   (messages.requestUrlAuth: a login button under a message, or a plain
 *   link whose domain is a login domain) → `{ ok, status, url }` where
 *   status is 'default' or 'accepted' (open `url`; the link itself for
 *   'default'), or `{ ok, status: 'request', domain, bot,
 *   requestWriteAccess }` when the person must be asked first;
 * - `botUrlAccept({ chat, id, buttonId } | { url }, writeAllowed)`
 *   (messages.acceptUrlAuth) → `{ ok, url }`, called only after the
 *   person ticked "Log in" and pressed Open;
 * - `urlAuthDomains()` (help.getAppConfig, `url_auth_domains`) → `{ ok,
 *   domains }`: the hosts whose links ask for a login. (Not done: the
 *   `autologin_domains` token appending, which only adds a query token.)
 * - `attachMenuBots()` (messages.getAttachMenuBots), `attachMenuBot({ bot |
 *   username })` (messages.getAttachMenuBot) and `attachMenuToggle({ bot,
 *   enabled, writeAllowed })` (messages.toggleBotInAttachMenu).
 * Nothing here runs unless the page asks on a person's press.
 */

import { runIn, connected, failureOf } from './telegram-stickers.js';
import { inputUserOf } from './telegram-peer-actions.js';
import { inputBot, resolveBotUser } from './telegram-inline-bots.js';

const CODES = {
  BOT_INVALID: 'no-bot',
  USERNAME_NOT_OCCUPIED: 'no-bot',
  USERNAME_INVALID: 'no-bot',
  URL_EXPIRED: 'expired',
  MESSAGE_ID_INVALID: 'bad-request',
  BUTTON_ID_INVALID: 'bad-request',
  PEER_ID_INVALID: 'no-access',
  CHANNEL_PRIVATE: 'no-access',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);

export const MAX_URL = 2048;
const ID = /^\d{1,20}$/;
const CHAT = /^-?\d{1,20}$/;
const NAME = /^[A-Za-z][A-Za-z0-9_]{3,31}$/;
const DOMAIN_KEY = 'url_auth_domains';
const BAD = { ok: false, error: 'bad request', code: 'bad-request' };
const NO_BOT = { ok: false, error: 'not a bot', code: 'no-bot' };

const text = (value) =>
  value === null || value === undefined ? '' : String(value.value ?? value);

/** An http(s) address without credentials, within bounds; else null. */
export const webUrl = (value) => {
  const raw = String(value ?? '').trim();
  if (!raw || raw.length > MAX_URL) {
    return null;
  }
  try {
    const url = new URL(raw);
    return ['http:', 'https:'].includes(url.protocol) &&
      !url.username &&
      !url.password
      ? url.href
      : null;
  } catch {
    return null;
  }
};

const botOut = (user) => ({
  id: text(user?.id),
  name:
    [user?.firstName, user?.lastName].filter(Boolean).join(' ') ||
    String(user?.username ?? ''),
  username: String(user?.username ?? ''),
});

/** What Telegram's urlAuthResult says, as the page's answer. */
export const authOut = (answer, original) => {
  const name = answer?.className;
  if (name === 'UrlAuthResultRequest') {
    return {
      ok: true,
      status: 'request',
      domain: String(answer.domain ?? ''),
      bot: botOut(answer.bot),
      requestWriteAccess: Boolean(answer.requestWriteAccess),
    };
  }
  const accepted = name === 'UrlAuthResultAccepted';
  const url = webUrl(accepted ? answer.url : original);
  return url
    ? { ok: true, status: accepted ? 'accepted' : 'default', url }
    : { ok: false, error: 'bad address', code: 'bad-url' };
};

/** The domains of an app config's `url_auth_domains` (lower case). */
export const domainsOf = (config) => {
  const entry = (config?.config?.value ?? config?.value ?? []).find(
    (e) => e?.key === DOMAIN_KEY
  );
  return (entry?.value?.value ?? [])
    .map((one) => String(one?.value ?? '').toLowerCase())
    .filter((d) => /^[a-z0-9.-]{1,253}$/.test(d));
};

// The peer types of an attachment-menu bot as words.
const TYPES = {
  AttachMenuPeerTypeSameBotPM: 'sameBotPm',
  AttachMenuPeerTypeBotPM: 'botPm',
  AttachMenuPeerTypePM: 'pm',
  AttachMenuPeerTypeChat: 'chat',
  AttachMenuPeerTypeBroadcast: 'broadcast',
};

/** One attachment-menu bot as the page lists it. */
export const attachBotOut = (bot) => ({
  id: text(bot.botId),
  shortName: String(bot.shortName ?? ''),
  peerTypes: (bot.peerTypes ?? [])
    .map((t) => TYPES[t?.className])
    .filter(Boolean),
  inactive: Boolean(bot.inactive),
  requestWriteAccess: Boolean(bot.requestWriteAccess),
});

// The form of a request naming a button or a plain link, else null.
const targetOf = (o) => {
  if (o.url !== undefined) {
    const url = webUrl(o.url);
    return url ? { url } : null;
  }
  return CHAT.test(String(o.chat ?? '')) &&
    /^\d{1,10}$/.test(String(o.id ?? '')) &&
    /^-?\d{1,10}$/.test(String(o.buttonId ?? ''))
    ? { chat: String(o.chat), id: Number(o.id), buttonId: Number(o.buttonId) }
    : null;
};

// The request fields of a target (the peer resolved for a button).
const fieldsOf = async (c, env, target) =>
  target.url
    ? { url: target.url }
    : {
        peer: await env.connection.withPeer(c.client, target.chat, (p) => p),
        msgId: target.id,
        buttonId: target.buttonId,
      };

const userNamed = (answer, id) =>
  (answer?.users ?? []).find((u) => text(u.id) === text(id));

const botFound = async (c, env, o) => {
  if (o.username) {
    const user = await resolveBotUser(c, o.username);
    return user ? inputBot(c, user) : null;
  }
  return env.connection.withPeer(c.client, String(o.bot), (peer) =>
    inputUserOf(c, peer)
  );
};

const nameFor = (answer, bot) =>
  botOut(userNamed(answer, bot.botId)).name || String(bot.shortName ?? '');

export const createBotLogin = (env, { userClient }) => ({
  botUrlAuth: async (options = {}) => {
    const target = targetOf(options);
    if (!target) {
      return BAD;
    }
    return connected(env, userClient, failure, (c) =>
      runIn(env, 'bot-login', async () => {
        const answer = await c.client.invoke(
          new c.Api.messages.RequestUrlAuth(await fieldsOf(c, env, target))
        );
        return authOut(answer, target.url ?? webUrl(options.original));
      })
    );
  },
  botUrlAccept: async (options = {}) => {
    const target = targetOf(options);
    if (!target || typeof options.writeAllowed !== 'boolean') {
      return BAD;
    }
    return connected(env, userClient, failure, (c) =>
      runIn(env, 'bot-login', async () => {
        const answer = await c.client.invoke(
          new c.Api.messages.AcceptUrlAuth({
            ...(options.writeAllowed ? { writeAllowed: true } : {}),
            ...(await fieldsOf(c, env, target)),
          })
        );
        const out = authOut(answer, target.url ?? webUrl(options.original));
        return out.ok && out.status !== 'request'
          ? out
          : { ...BAD, code: 'bad-url' };
      })
    );
  },
  urlAuthDomains: async () =>
    connected(env, userClient, failure, async (c) => {
      const config = await runIn(env, 'app-config', () =>
        c.client.invoke(new c.Api.help.GetAppConfig({ hash: 0 }))
      );
      return { ok: true, domains: domainsOf(config) };
    }),
  attachMenuBots: async () =>
    connected(env, userClient, failure, async (c) => {
      const answer = await runIn(env, 'attach-menu', () =>
        c.client.invoke(new c.Api.messages.GetAttachMenuBots({ hash: c.zero }))
      );
      return {
        ok: true,
        bots: (answer?.bots ?? []).map((bot) => ({
          ...attachBotOut(bot),
          name: nameFor(answer, bot),
        })),
      };
    }),
  attachMenuBot: async ({ bot, username } = {}) => {
    if (username ? !NAME.test(String(username)) : !ID.test(String(bot ?? ''))) {
      return BAD;
    }
    return connected(env, userClient, failure, async (c) => {
      const user = await botFound(c, env, { bot, username });
      if (!user) {
        return NO_BOT;
      }
      const answer = await runIn(env, 'attach-menu', () =>
        c.client.invoke(new c.Api.messages.GetAttachMenuBot({ bot: user }))
      );
      const found = answer?.bot;
      if (!found) {
        return NO_BOT;
      }
      return {
        ok: true,
        bot: {
          ...attachBotOut(found),
          name: nameFor(answer, found),
          username: String(userNamed(answer, found.botId)?.username ?? ''),
        },
      };
    });
  },
  attachMenuToggle: async ({ bot, enabled, writeAllowed } = {}) => {
    if (
      !ID.test(String(bot ?? '')) ||
      typeof enabled !== 'boolean' ||
      (writeAllowed !== undefined && typeof writeAllowed !== 'boolean')
    ) {
      return BAD;
    }
    return connected(env, userClient, failure, async (c) => {
      const user = await botFound(c, env, { bot });
      await runIn(env, 'attach-menu', () =>
        c.client.invoke(
          new c.Api.messages.ToggleBotInAttachMenu({
            ...(enabled && writeAllowed ? { writeAllowed: true } : {}),
            bot: user,
            enabled,
          })
        )
      );
      return { ok: true };
    });
  },
});

/**
 * A bot's buttons under its message, as Telegram's apps press them
 * (R-Y110): a callback button asks the bot through
 * messages.getBotCallbackAnswer, and the bot answers with words to show
 * (a toast, or a box when it is an alert), a link to open, or nothing —
 * what it changes in the chat (most often the message itself, edited)
 * comes as an update like any other.
 *
 * A button's data is bytes; the app and the store name it in base64
 * (R-Y28).
 */

// A bot that did not answer in time still got the press.
const QUIET = new Set(['BOT_RESPONSE_TIMEOUT']);

// Telegram's refusals the app can name.
const REFUSED = {
  DATA_INVALID: 'data-invalid',
  MESSAGE_ID_INVALID: 'message-gone',
  PEER_ID_INVALID: 'chat-gone',
};

const reasonOf = (error) => String(error?.errorMessage ?? error?.message ?? '');

/** The answer as the app shows it. */
export const answerOf = (answer) => ({
  ok: true,
  message: answer?.message ? String(answer.message) : null,
  alert: Boolean(answer?.alert),
  url: answer?.url ? String(answer.url) : null,
});

/**
 * A game's answer (R-Y190): the page opens only a web link, so any other
 * kind of address (tg://, javascript:, file:) is dropped here already.
 */
export const gameAnswerOf = (answer) => {
  const shown = answerOf(answer);
  return /^https?:\/\//i.test(shown.url ?? '')
    ? shown
    : { ...shown, url: null };
};

/** The bot actions over the user's client. */
export const createBotActions = (env, { userClient }) => {
  const botCallback = async ({ chat, id, data = null, game = false }) => {
    const msgId = Number(id);
    const client = chat && msgId > 0 ? await userClient() : null;
    if (!client) {
      return { ok: false, supported: false };
    }
    const { Api } = await env.importer();
    try {
      const answer = await env.connection.withPeer(
        client,
        String(chat),
        (peer) =>
          env.queue.run(`bot:${chat}:${msgId}:${data ?? ''}`, 'view', () =>
            client.invoke(
              new Api.messages.GetBotCallbackAnswer({
                peer,
                msgId,
                ...(data ? { data: Buffer.from(data, 'base64') } : {}),
                ...(game ? { game: true } : {}),
              })
            )
          )
      );
      return game ? gameAnswerOf(answer) : answerOf(answer);
    } catch (error) {
      const reason = reasonOf(error);
      if (QUIET.has(reason)) {
        return { ok: true, message: null, alert: false, url: null };
      }
      if (REFUSED[reason]) {
        return { ok: false, code: REFUSED[reason] };
      }
      throw error;
    }
  };
  return { botCallback };
};

/**
 * Chatbots of Telegram Business (R-Y180; learned from Telegram Desktop's
 * Settings → Telegram Business → Chatbots, never copied).
 *
 * - `businessBot()` → `{ ok, bot: { id, username, name, canReply, rights,
 *   recipients } | null }` — the connected bot (account.getConnectedBots);
 * - `businessBotSet({ username, recipients, canReply })` — connect a bot by
 *   its username (contacts.resolveUsername), who it serves
 *   (`existingChats`, `newChats`, `contacts`, `nonContacts`) and whether it
 *   may reply; other rights and chosen users of the same bot are kept
 *   (account.updateConnectedBot), on Save only;
 * - `businessBotRemove()` — disconnect it (updateConnectedBot, deleted);
 * - `businessBotChat({ chat })` → `{ ok, bar }` — whether a bot manages
 *   this chat, its name, paused or not (messages.getPeerSettings);
 * - `businessBotPause({ chat, paused })` (account.toggleConnectedBotPaused)
 *   and `businessBotDisable({ chat })` (account.disablePeerConnectedBot).
 */

import { connected, failureOf } from './telegram-stickers.js';
import { ask, bad, text } from './telegram-business.js';

const CODES = {
  PREMIUM_ACCOUNT_REQUIRED: 'premium',
  USERNAME_INVALID: 'no-bot',
  USERNAME_NOT_OCCUPIED: 'no-bot',
  BOT_INVALID: 'no-bot',
  BOT_BUSINESS_MISSING: 'not-business-bot',
  BUSINESS_RECIPIENTS_EMPTY: 'recipients-empty',
  BUSINESS_BOT_ALREADY_CONNECTED: 'failed',
  PEER_ID_INVALID: 'no-user',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);

const USER = /^\d{1,20}$/;
const NAME = /^@?[A-Za-z][A-Za-z0-9_]{3,31}$/;
export const KINDS = ['existingChats', 'newChats', 'contacts', 'nonContacts'];
const RIGHTS = [
  'reply',
  'readMessages',
  'deleteSentMessages',
  'deleteReceivedMessages',
  'editName',
  'editBio',
  'editProfilePhoto',
  'editUsername',
  'viewGifts',
  'sellGifts',
  'changeGiftSettings',
  'transferAndUpgradeGifts',
  'transferStars',
  'manageStories',
];

const flagsOf = (source, keys) =>
  Object.fromEntries(keys.filter((k) => source?.[k]).map((k) => [k, true]));

/** Whether the page's recipients name at least one kind of chat. */
export const validRecipients = (recipients) =>
  Boolean(recipients) &&
  typeof recipients === 'object' &&
  KINDS.every((k) => typeof recipients[k] === 'boolean') &&
  KINDS.some((k) => recipients[k]);

const ids = (list) => (list ?? []).map(String);

const botOf = (connectedBot, users) => {
  if (!connectedBot) {
    return null;
  }
  const user = (users ?? []).find(
    (u) => String(u?.id) === String(connectedBot.botId)
  );
  const r = connectedBot.recipients ?? {};
  return {
    id: String(connectedBot.botId),
    username: text(user?.username),
    name: text(user?.firstName) || text(user?.username),
    canReply: Boolean(connectedBot.rights?.reply),
    rights: flagsOf(connectedBot.rights, RIGHTS),
    recipients: {
      ...Object.fromEntries(KINDS.map((k) => [k, Boolean(r[k])])),
      excludeSelected: Boolean(r.excludeSelected),
      users: ids(r.users),
      excludeUsers: ids(r.excludeUsers),
    },
  };
};

// Telegram's PeerSettings, as the bar over a managed chat reads them.
export const barOf = (settings, users) => {
  if (!/^[1-9]\d*$/.test(String(settings?.businessBotId ?? ''))) {
    return null;
  }
  const user = (users ?? []).find(
    (u) => String(u?.id) === String(settings.businessBotId)
  );
  return {
    id: String(settings.businessBotId),
    name: text(user?.firstName) || text(user?.username),
    paused: Boolean(settings.businessBotPaused),
    canReply: Boolean(settings.businessBotCanReply),
    manageUrl: text(settings.businessBotManageUrl),
  };
};

/** The connected bot: read, connect, disconnect. */
const createBotsConnection = (env, { userClient }) => {
  const read = async (c) => {
    const answer = await ask(
      env,
      c,
      'business:bot',
      new c.Api.account.GetConnectedBots()
    );
    const first = (answer?.connectedBots ?? [])[0] ?? null;
    return { bot: botOf(first, answer?.users), users: answer?.users ?? [] };
  };

  const inputUser = async (c, id) => {
    const entity = await c.client.getInputEntity(c.helpers.returnBigInt(id));
    return new c.Api.InputUser({
      userId: entity.userId,
      accessHash: entity.accessHash ?? c.zero,
    });
  };

  const businessBot = async () =>
    connected(env, userClient, failure, async (c) => ({
      ok: true,
      bot: (await read(c)).bot,
    }));

  const resolveBot = async (c, username, known) => {
    if (known && known.username.toLowerCase() === username.toLowerCase()) {
      return inputUser(c, known.id);
    }
    const answer = await ask(
      env,
      c,
      'business:bot-resolve',
      new c.Api.contacts.ResolveUsername({ username })
    );
    const user = (answer?.users ?? []).find(
      (u) => String(u?.id) === String(answer?.peer?.userId)
    );
    if (!user?.bot) {
      return null;
    }
    return new c.Api.InputUser({
      userId: user.id,
      accessHash: user.accessHash ?? c.zero,
    });
  };

  // The same bot keeps its other rights and chosen users.
  const recipientsOf = async (c, request, known) => {
    const kept = known ?? { recipients: {} };
    const same = Boolean(known);
    const toUsers = async (list) => {
      const out = [];
      for (const id of same ? list : []) {
        try {
          out.push(await inputUser(c, id));
        } catch {
          // a person that cannot be found any more is let go
        }
      }
      return out;
    };
    const users = await toUsers(kept.recipients.users ?? []);
    const excluded = await toUsers(kept.recipients.excludeUsers ?? []);
    return new c.Api.InputBusinessBotRecipients({
      ...flagsOf(request.recipients, KINDS),
      ...(same && kept.recipients.excludeSelected && users.length
        ? { excludeSelected: true }
        : {}),
      ...(users.length ? { users } : {}),
      ...(excluded.length ? { excludeUsers: excluded } : {}),
    });
  };

  const businessBotSet = async (request = {}) => {
    const username = text(request.username).trim();
    if (
      !NAME.test(username) ||
      !validRecipients(request.recipients) ||
      typeof request.canReply !== 'boolean'
    ) {
      return bad('no-bot');
    }
    const name = username.replace(/^@/, '');
    return connected(env, userClient, failure, async (c) => {
      const { bot: known } = await read(c);
      const same =
        known && known.username.toLowerCase() === name.toLowerCase()
          ? known
          : null;
      const bot = await resolveBot(c, name, same);
      if (!bot) {
        return bad('no-bot');
      }
      const rights = {
        ...(same?.rights ?? {}),
        ...(request.canReply ? { reply: true } : {}),
      };
      if (!request.canReply) {
        delete rights.reply;
      }
      await ask(
        env,
        c,
        'business:bot-set',
        new c.Api.account.UpdateConnectedBot({
          rights: new c.Api.BusinessBotRights(rights),
          bot,
          recipients: await recipientsOf(c, request, same),
        })
      );
      return { ok: true, bot: (await read(c)).bot };
    });
  };

  const businessBotRemove = async () =>
    connected(env, userClient, failure, async (c) => {
      const { bot: known } = await read(c);
      if (!known) {
        return { ok: true, bot: null };
      }
      await ask(
        env,
        c,
        'business:bot-remove',
        new c.Api.account.UpdateConnectedBot({
          deleted: true,
          bot: await inputUser(c, known.id),
          recipients: new c.Api.InputBusinessBotRecipients({}),
        })
      );
      return { ok: true, bot: null };
    });

  return { businessBot, businessBotSet, businessBotRemove };
};

/** The bar over a chat a bot manages: what it says, pause, remove. */
const createBotChats = (env, { userClient }) => {
  // Checks the chat is a person, connects, runs `use` on the peer.
  const inChat = (use) => async (request) => {
    const chat = text(request?.chat);
    if (!USER.test(chat)) {
      return bad('no-user');
    }
    return connected(env, userClient, failure, (c) =>
      env.connection.withPeer(c.client, chat, (peer) =>
        use(c, peer, request, chat)
      )
    );
  };

  const businessBotChat = inChat(async (c, peer, _request, chat) => {
    const answer = await ask(
      env,
      c,
      `business:bar:${chat}`,
      new c.Api.messages.GetPeerSettings({ peer })
    );
    return { ok: true, bar: barOf(answer?.settings, answer?.users) };
  });

  const businessBotPause = inChat(async (c, peer, request, chat) => {
    if (typeof request.paused !== 'boolean') {
      return bad();
    }
    await ask(
      env,
      c,
      `business:pause:${chat}`,
      new c.Api.account.ToggleConnectedBotPaused({
        peer,
        paused: request.paused,
      })
    );
    return { ok: true, paused: request.paused };
  });

  const businessBotDisable = inChat(async (c, peer, _r, chat) => {
    await ask(
      env,
      c,
      `business:disable:${chat}`,
      new c.Api.account.DisablePeerConnectedBot({ peer })
    );
    return { ok: true };
  });

  return { businessBotChat, businessBotPause, businessBotDisable };
};

export const createBusinessBots = (env, context) => ({
  ...createBotsConnection(env, context),
  ...createBotChats(env, context),
});

/**
 * Business chat links (R-Y180; learned from Telegram Desktop's Settings →
 * Telegram Business → Chat links, never copied): a link t.me/m/<slug> that
 * opens a chat with the user and puts a ready text in the box.
 *
 * - `businessLinks()` → `{ ok, links: [{ slug, link, message, title,
 *   views }] }` (account.getBusinessChatLinks);
 * - `businessLinkCreate({ message, title? })` → `{ ok, link }`
 *   (account.createBusinessChatLink), on Save only;
 * - `businessLinkEdit({ slug, message, title? })` → `{ ok, link }`
 *   (account.editBusinessChatLink);
 * - `businessLinkDelete({ slug })` (account.deleteBusinessChatLink);
 * - `businessLinkResolve({ slug })` → `{ ok, chat, name, text }` — whose
 *   link it is and the text for the box (account.resolveBusinessChatLink).
 *   Nothing is sent: the page only puts the text in the box.
 */

import { connected, failureOf } from './telegram-stickers.js';
import { ask, bad, text } from './telegram-business.js';

const CODES = {
  PREMIUM_ACCOUNT_REQUIRED: 'premium',
  CHATLINKS_TOO_MUCH: 'too-many-links',
  CHATLINK_SLUG_EMPTY: 'link-gone',
  CHATLINK_SLUG_EXPIRED: 'link-gone',
  CHATLINK_INVALID: 'link-gone',
  CHATLINK_EXPIRED: 'link-gone',
  MESSAGE_EMPTY: 'text-empty',
  MESSAGE_TOO_LONG: 'text-long',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);

export const SLUG = /^[A-Za-z0-9_-]{1,64}$/;
export const TEXT_MAX = 4096;
export const TITLE_MAX = 32;

const length = (value) => Array.from(text(value)).length;

/** A business chat link as the page reads it. */
export const linkOf = (link) => {
  const address = text(link?.link);
  return {
    slug: address.split('/').filter(Boolean).pop() ?? '',
    link: address,
    message: text(link?.message),
    title: text(link?.title),
    views: Number(link?.views) || 0,
  };
};

/** Whether a link's words are valid: some text, a short title. */
export const validLinkBody = (body = {}) =>
  typeof body.message === 'string' &&
  body.message.trim() !== '' &&
  length(body.message) <= TEXT_MAX &&
  (body.title === undefined ||
    (typeof body.title === 'string' && length(body.title) <= TITLE_MAX));

const inputOf = (c, body) =>
  new c.Api.InputBusinessChatLink({
    message: body.message,
    ...(body.title?.trim() ? { title: body.title.trim() } : {}),
  });

export const createBusinessLinks = (env, { userClient }) => {
  const businessLinks = async () =>
    connected(env, userClient, failure, async (c) => {
      const answer = await ask(
        env,
        c,
        'business:links',
        new c.Api.account.GetBusinessChatLinks()
      );
      return { ok: true, links: (answer?.links ?? []).map(linkOf) };
    });

  const businessLinkCreate = async (body = {}) =>
    !validLinkBody(body)
      ? bad('text-empty')
      : connected(env, userClient, failure, async (c) => {
          const link = await ask(
            env,
            c,
            'business:link-create',
            new c.Api.account.CreateBusinessChatLink({
              link: inputOf(c, body),
            })
          );
          return { ok: true, link: linkOf(link) };
        });

  const businessLinkEdit = async (body = {}) =>
    !validLinkBody(body) || !SLUG.test(text(body.slug))
      ? bad('text-empty')
      : connected(env, userClient, failure, async (c) => {
          const link = await ask(
            env,
            c,
            'business:link-edit',
            new c.Api.account.EditBusinessChatLink({
              slug: body.slug,
              link: inputOf(c, body),
            })
          );
          return { ok: true, link: linkOf(link) };
        });

  const businessLinkDelete = async (body = {}) =>
    !SLUG.test(text(body.slug))
      ? bad('link-gone')
      : connected(env, userClient, failure, async (c) => {
          await ask(
            env,
            c,
            'business:link-delete',
            new c.Api.account.DeleteBusinessChatLink({ slug: body.slug })
          );
          return { ok: true };
        });

  const businessLinkResolve = async (body = {}) =>
    !SLUG.test(text(body.slug))
      ? bad('link-gone')
      : connected(env, userClient, failure, async (c) => {
          const answer = await ask(
            env,
            c,
            'business:link-resolve',
            new c.Api.account.ResolveBusinessChatLink({ slug: body.slug })
          );
          const id = answer?.peer?.userId;
          if (id === undefined) {
            return bad('link-gone');
          }
          const user = (answer.users ?? []).find(
            (u) => String(u?.id) === String(id)
          );
          const name =
            [user?.firstName, user?.lastName].filter(Boolean).join(' ') ||
            user?.username ||
            null;
          return {
            ok: true,
            chat: String(id),
            name,
            text: text(answer.message),
          };
        });

  return {
    businessLinks,
    businessLinkCreate,
    businessLinkEdit,
    businessLinkDelete,
    businessLinkResolve,
  };
};

/**
 * The greeting and the away message of Telegram Business, as Telegram
 * Desktop's Settings → Telegram Business has them (R-Y179; learned, never
 * copied). Each one sends a quick reply shortcut to chats automatically:
 * - `businessMessages()` — users.getFullUser of the user (UserFull.
 *   businessGreetingMessage / businessAwayMessage) and messages.
 *   getQuickReplies → `{ ok, greeting, away, shortcuts: [{ id, name }],
 *   people: [{ id, name }] }`; `greeting` is `null` (off) or `{ shortcutId,
 *   recipients, noActivityDays }`, `away` `null` or `{ shortcutId,
 *   recipients, offlineOnly, schedule: { kind: 'always' | 'outside' |
 *   'custom', start?, end? } }` (times in seconds); `recipients` is
 *   `{ existingChats, newChats, contacts, nonContacts, excludeSelected,
 *   users: [id] }`;
 * - `businessGreetingSave({ enabled, shortcutId, recipients,
 *   noActivityDays })` — account.updateBusinessGreetingMessage (off: no
 *   message);
 * - `businessAwaySave({ enabled, shortcutId, recipients, offlineOnly,
 *   schedule })` — account.updateBusinessAwayMessage.
 * Writes come only from the page's Save. Telegram's refusals (Premium
 * needed…) become codes.
 */

import { connected, runIn } from './telegram-stickers.js';
import { quickFailure } from './telegram-quick-replies.js';

const ID = /^\d{1,10}$/;
const USER = /^\d{1,20}$/;
export const DAYS = [7, 14, 21, 28];
export const SCHEDULES = ['always', 'outside', 'custom'];
const FLAGS = [
  'existingChats',
  'newChats',
  'contacts',
  'nonContacts',
  'excludeSelected',
];

const bad = (code) => ({ ok: false, error: code, code });
const textOf = (value) => String(value?.value ?? value);

const recipientsOf = (r) => ({
  ...Object.fromEntries(FLAGS.map((k) => [k, Boolean(r?.[k])])),
  users: (r?.users ?? []).map(textOf),
});

const scheduleOf = (s) => {
  switch (s?.className) {
    case 'BusinessAwayMessageScheduleCustom':
      return {
        kind: 'custom',
        start: Number(s.startDate),
        end: Number(s.endDate),
      };
    case 'BusinessAwayMessageScheduleOutsideWorkHours':
      return { kind: 'outside' };
    default:
      return { kind: 'always' };
  }
};

const greetingOf = (g) =>
  g
    ? {
        shortcutId: Number(g.shortcutId),
        recipients: recipientsOf(g.recipients),
        noActivityDays: Number(g.noActivityDays),
      }
    : null;

const awayOf = (a) =>
  a
    ? {
        shortcutId: Number(a.shortcutId),
        recipients: recipientsOf(a.recipients),
        offlineOnly: Boolean(a.offlineOnly),
        schedule: scheduleOf(a.schedule),
      }
    : null;

const nameOf = (u) =>
  [u?.firstName, u?.lastName].filter(Boolean).join(' ') ||
  u?.username ||
  textOf(u?.id ?? '');

/** Whether `recipients` from the page is shaped as above. */
export const validRecipients = (r) =>
  Boolean(r) &&
  typeof r === 'object' &&
  FLAGS.every((k) => typeof r[k] === 'boolean') &&
  Array.isArray(r.users) &&
  r.users.length <= 100 &&
  r.users.every((u) => USER.test(String(u)));

/** Whether `schedule` from the page is shaped as above. */
export const validSchedule = (s) =>
  Boolean(s) &&
  SCHEDULES.includes(s.kind) &&
  (s.kind !== 'custom' ||
    (Number.isInteger(s.start) && Number.isInteger(s.end) && s.end > s.start));

const inputRecipients = async (c, r) => {
  const users = [];
  for (const id of r.users) {
    const peer = await c.client.getInputEntity(c.helpers.returnBigInt(id));
    users.push(
      new c.Api.InputUser({
        userId: peer.userId ?? c.helpers.returnBigInt(id),
        accessHash: peer.accessHash ?? c.zero,
      })
    );
  }
  return new c.Api.InputBusinessRecipients({
    ...Object.fromEntries(FLAGS.map((k) => [k, r[k] || undefined])),
    ...(users.length > 0 ? { users } : {}),
  });
};

const inputSchedule = (c, s) => {
  if (s.kind === 'custom') {
    return new c.Api.BusinessAwayMessageScheduleCustom({
      startDate: s.start,
      endDate: s.end,
    });
  }
  return s.kind === 'outside'
    ? new c.Api.BusinessAwayMessageScheduleOutsideWorkHours()
    : new c.Api.BusinessAwayMessageScheduleAlways();
};

export const createBusinessMessages = (env, { userClient }) => {
  const act = (key, use) =>
    connected(env, userClient, quickFailure, (c) =>
      runIn(env, `business-messages:${key}`, () => use(c))
    );

  const read = (c) =>
    c.client
      .invoke(new c.Api.users.GetFullUser({ id: new c.Api.InputUserSelf() }))
      .then(async (answer) => {
        const full = answer?.fullUser ?? {};
        const quick = await c.client.invoke(
          new c.Api.messages.GetQuickReplies({ hash: c.zero })
        );
        return { answer, full, quick };
      });

  const people = (answer, ...lists) => {
    const wanted = new Set(lists.flat());
    return (answer?.users ?? [])
      .filter((u) => wanted.has(textOf(u.id)))
      .map((u) => ({ id: textOf(u.id), name: nameOf(u) }));
  };

  const save = (key, enabled, build) =>
    act(key, async (c) => {
      await c.client.invoke(
        key === 'greeting'
          ? new c.Api.account.UpdateBusinessGreetingMessage(
              enabled ? { message: await build(c) } : {}
            )
          : new c.Api.account.UpdateBusinessAwayMessage(
              enabled ? { message: await build(c) } : {}
            )
      );
      return { ok: true };
    });

  return {
    businessMessages: () =>
      act('read', async (c) => {
        const { answer, full, quick } = await read(c);
        const greeting = greetingOf(full.businessGreetingMessage);
        const away = awayOf(full.businessAwayMessage);
        return {
          ok: true,
          greeting,
          away,
          shortcuts: (quick?.quickReplies ?? []).map((q) => ({
            id: Number(q.shortcutId),
            name: String(q.shortcut),
          })),
          people: people(
            answer,
            greeting?.recipients.users ?? [],
            away?.recipients.users ?? []
          ),
        };
      }),
    businessGreetingSave: async (body = {}) => {
      if (body.enabled !== true) {
        return body.enabled === false
          ? save('greeting', false)
          : bad('bad-request');
      }
      if (
        !ID.test(String(body.shortcutId)) ||
        !validRecipients(body.recipients) ||
        !DAYS.includes(body.noActivityDays)
      ) {
        return bad('bad-request');
      }
      return save(
        'greeting',
        true,
        async (c) =>
          new c.Api.InputBusinessGreetingMessage({
            shortcutId: Number(body.shortcutId),
            recipients: await inputRecipients(c, body.recipients),
            noActivityDays: body.noActivityDays,
          })
      );
    },
    businessAwaySave: async (body = {}) => {
      if (body.enabled !== true) {
        return body.enabled === false
          ? save('away', false)
          : bad('bad-request');
      }
      if (
        !ID.test(String(body.shortcutId)) ||
        !validRecipients(body.recipients) ||
        !validSchedule(body.schedule) ||
        typeof body.offlineOnly !== 'boolean'
      ) {
        return bad('bad-request');
      }
      return save(
        'away',
        true,
        async (c) =>
          new c.Api.InputBusinessAwayMessage({
            offlineOnly: body.offlineOnly || undefined,
            shortcutId: Number(body.shortcutId),
            schedule: inputSchedule(c, body.schedule),
            recipients: await inputRecipients(c, body.recipients),
          })
      );
    },
  };
};

/**
 * Telegram Business, the parts of a profile (R-Y180; learned from Telegram
 * Desktop's Settings → Telegram Business, never copied). Reads are free;
 * every write happens on an explicit Save in the page.
 *
 * - `businessHours()` → `{ ok, hours: { timezone, weekly: [{ start, end }],
 *   openNow } | null, timezones: [{ id, name, offset }] }` — the user's
 *   opening hours (users.getFullUser) and Telegram's time zones
 *   (help.getTimezonesList); minutes count from Monday 00:00 in the zone;
 * - `businessHoursSet({ timezone, weekly })` — account.updateBusinessWorkHours
 *   (no weekly hours: cleared);
 * - `businessLocation()` / `businessLocationSet({ address, lat?, lon? })` —
 *   account.updateBusinessLocation (nothing given: cleared);
 * - `businessIntro()` / `businessIntroSet({ title, description, sticker? })`
 *   — account.updateBusinessIntro; `sticker` an id from
 *   `businessIntroStickers()` (messages.getStickers) or the intro's own,
 *   null removes it;
 * - `businessProfile({ chat })` → `{ ok, hours, location, intro }` of a
 *   person, as their profile and an empty chat with them show it;
 * - `foldersTagsSet({ enabled })` — messages.toggleDialogFilterTags (Premium).
 * Telegram's refusals become codes (Telegram Business needs Premium).
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';
import { inputUserOf } from './telegram-peer-actions.js';

export const CODES = {
  PREMIUM_ACCOUNT_REQUIRED: 'premium',
  BUSINESS_WORK_HOURS_PERIOD_INVALID: 'hours-invalid',
  BUSINESS_WORK_HOURS_EMPTY: 'hours-invalid',
  TIMEZONE_INVALID: 'hours-invalid',
  BUSINESS_ADDRESS_TOO_LONG: 'address-long',
  BUSINESS_INTRO_TITLE_LENGTH: 'intro-long',
  BUSINESS_INTRO_DESCRIPTION_LENGTH: 'intro-long',
  USER_ID_INVALID: 'no-user',
  PEER_ID_INVALID: 'no-user',
  FLOOD_WAIT: 'flood',
};

export const failure = failureOf(CODES);

export const WEEK = 7 * 24 * 60;
const MAX_END = 8 * 24 * 60;
const USER = /^\d{1,20}$/;
const ZONE = /^[A-Za-z0-9_/+-]{1,64}$/;
const INTRO_STICKER_EMOJI = '\u{1F44B}';

export const bad = (code = 'failed') => ({
  ok: false,
  error: 'bad request',
  code,
});
export const text = (value) => String(value ?? '');
const length = (value) => Array.from(text(value)).length;

/** Whether `weekly` is Telegram's list: sorted, apart, inside a week and a day. */
export const validWeekly = (weekly) =>
  Array.isArray(weekly) &&
  weekly.length <= 28 &&
  weekly.every(
    (w, i) =>
      Number.isInteger(w?.start) &&
      Number.isInteger(w?.end) &&
      w.start >= 0 &&
      w.start < WEEK &&
      w.end > w.start &&
      w.end <= MAX_END &&
      (i === 0 || weekly[i - 1].end <= w.start)
  ) &&
  // A last interval running into Monday must not meet Monday's own.
  (weekly.length === 0 || weekly.at(-1).end - WEEK <= weekly[0].start);

export const validZone = (zone) => typeof zone === 'string' && ZONE.test(zone);

export const hoursOf = (work) =>
  work
    ? {
        timezone: text(work.timezoneId),
        weekly: (work.weeklyOpen ?? []).map((w) => ({
          start: Number(w.startMinute),
          end: Number(w.endMinute),
        })),
        openNow: Boolean(work.openNow),
      }
    : null;

const geoOf = (geo) =>
  geo && geo.className !== 'GeoPointEmpty' && geo.lat !== undefined
    ? { lat: Number(geo.lat), lon: Number(geo.long) }
    : null;

export const locationOf = (place) =>
  place ? { address: text(place.address), point: geoOf(place.geoPoint) } : null;

export const ask = (env, c, key, request) =>
  runIn(env, key, () => c.client.invoke(request));

const fullOf = async (env, c, id, key) => {
  const answer = await ask(env, c, key, new c.Api.users.GetFullUser({ id }));
  return answer?.fullUser ?? {};
};

const selfFull = (env, c) =>
  fullOf(env, c, new c.Api.InputUserSelf(), 'business:me');

const validPoint = (r) =>
  (r.lat === undefined && r.lon === undefined) ||
  (typeof r.lat === 'number' &&
    typeof r.lon === 'number' &&
    Math.abs(r.lat) <= 90 &&
    Math.abs(r.lon) <= 180);

const zonesOf = async (env, c) => {
  try {
    const list = await ask(
      env,
      c,
      'business:zones',
      new c.Api.help.GetTimezonesList({ hash: 0 })
    );
    return (list?.timezones ?? []).map((z) => ({
      id: text(z.id),
      name: text(z.name),
      offset: Number(z.utcOffset) || 0,
    }));
  } catch {
    // the zones are a convenience: the editor falls back to the browser's
    return [];
  }
};

const hoursRequest = (c, timezone, weekly) =>
  new c.Api.account.UpdateBusinessWorkHours(
    weekly.length === 0
      ? {}
      : {
          businessWorkHours: new c.Api.BusinessWorkHours({
            timezoneId: timezone,
            weeklyOpen: weekly.map(
              (w) =>
                new c.Api.BusinessWeeklyOpen({
                  startMinute: w.start,
                  endMinute: w.end,
                })
            ),
          }),
        }
  );

const locationRequest = (c, address, point) =>
  new c.Api.account.UpdateBusinessLocation({
    ...(address === '' ? {} : { address }),
    ...(point
      ? {
          geoPoint: new c.Api.InputGeoPoint({
            lat: point.lat,
            long: point.lon,
          }),
        }
      : {}),
  });

const validIntro = ({ title, description, sticker }) =>
  typeof title === 'string' &&
  typeof description === 'string' &&
  length(title) <= 32 &&
  length(description) <= 70 &&
  (sticker === undefined || sticker === null || USER.test(text(sticker)));

/** Opening hours, location and folder tags. */
const createBusinessHours = (env, { userClient }) => {
  const businessHours = async () =>
    connected(env, userClient, failure, async (c) => {
      const full = await selfFull(env, c);
      return {
        ok: true,
        hours: hoursOf(full.businessWorkHours),
        timezones: await zonesOf(env, c),
      };
    });

  const businessHoursSet = async (request = {}) => {
    const { timezone, weekly } = request;
    if (!validZone(timezone) || !validWeekly(weekly)) {
      return bad('hours-invalid');
    }
    return connected(env, userClient, failure, async (c) => {
      await ask(
        env,
        c,
        'business:hours-set',
        hoursRequest(c, timezone, weekly)
      );
      return { ok: true };
    });
  };

  const businessLocation = async () =>
    connected(env, userClient, failure, async (c) => {
      const full = await selfFull(env, c);
      return { ok: true, location: locationOf(full.businessLocation) };
    });

  const businessLocationSet = async (request = {}) => {
    const address = text(request.address).trim();
    if (
      typeof request.address !== 'string' ||
      length(address) > 96 ||
      !validPoint(request)
    ) {
      return bad('address-long');
    }
    const point = request.lat === undefined ? null : request;
    if (address === '' && point) {
      return bad('address-empty');
    }
    return connected(env, userClient, failure, async (c) => {
      await ask(
        env,
        c,
        'business:location-set',
        locationRequest(c, address, point)
      );
      return { ok: true };
    });
  };

  const foldersTagsSet = async (request = {}) =>
    typeof request.enabled !== 'boolean'
      ? bad()
      : connected(env, userClient, failure, async (c) => {
          await ask(
            env,
            c,
            'business:tags',
            new c.Api.messages.ToggleDialogFilterTags({
              enabled: request.enabled,
            })
          );
          return { ok: true, enabled: request.enabled };
        });

  return {
    businessHours,
    businessHoursSet,
    businessLocation,
    businessLocationSet,
    foldersTagsSet,
  };
};

/** The intro, its stickers and a person's business profile. */
const createBusinessIntro = (env, { userClient, stickers }) => {
  // The documents of the stickers shown for the intro, by id.
  const held = new Map();

  const picture = (doc, from) => {
    if (doc?.className !== 'Document') {
      return null;
    }
    held.set(String(doc.id), doc);
    return (
      stickers?.remember?.([doc], from, 'sticker')?.[0] ?? {
        id: String(doc.id),
      }
    );
  };

  const introOf = (intro, from) =>
    intro
      ? {
          title: text(intro.title),
          description: text(intro.description),
          sticker: intro.sticker ? picture(intro.sticker, from) : null,
        }
      : null;

  const businessIntro = async () =>
    connected(env, userClient, failure, async (c) => {
      const full = await selfFull(env, c);
      return { ok: true, intro: introOf(full.businessIntro, 'business:me') };
    });

  const businessIntroStickers = async () =>
    connected(env, userClient, failure, async (c) => {
      const answer = await ask(
        env,
        c,
        'business:stickers',
        new c.Api.messages.GetStickers({
          emoticon: INTRO_STICKER_EMOJI,
          hash: c.zero,
        })
      );
      const items = (answer?.stickers ?? [])
        .slice(0, 60)
        .map((doc) => picture(doc, 'business:pick'))
        .filter(Boolean);
      return { ok: true, stickers: items };
    });

  const inputSticker = (c, id) => {
    const doc = held.get(text(id));
    return doc
      ? new c.Api.InputDocument({
          id: doc.id,
          accessHash: doc.accessHash,
          fileReference: doc.fileReference,
        })
      : null;
  };

  const businessIntroSet = async (request = {}) => {
    if (!validIntro(request)) {
      return bad('intro-long');
    }
    const { title, description, sticker } = request;
    const empty = title.trim() === '' && description.trim() === '' && !sticker;
    return connected(env, userClient, failure, async (c) => {
      const doc = sticker ? inputSticker(c, sticker) : null;
      if (sticker && !doc) {
        return bad('unknown-sticker');
      }
      await ask(
        env,
        c,
        'business:intro-set',
        new c.Api.account.UpdateBusinessIntro(
          empty
            ? {}
            : {
                intro: new c.Api.InputBusinessIntro({
                  title: title.trim(),
                  description: description.trim(),
                  ...(doc ? { sticker: doc } : {}),
                }),
              }
        )
      );
      return { ok: true };
    });
  };

  const businessProfile = async (request = {}) => {
    const chat = text(request.chat);
    if (!USER.test(chat)) {
      return bad('no-user');
    }
    return connected(env, userClient, failure, (c) =>
      env.connection.withPeer(c.client, chat, async (peer) => {
        const full = await fullOf(
          env,
          c,
          await inputUserOf(c, peer),
          `business:${chat}`
        );
        return {
          ok: true,
          hours: hoursOf(full.businessWorkHours),
          location: locationOf(full.businessLocation),
          intro: introOf(full.businessIntro, `business:${chat}`),
        };
      })
    );
  };

  // A sticker's file reference expired: the person's profile, again.
  stickers?.onAgain?.('business:', (which) => {
    if (which === 'me') {
      return businessIntro();
    }
    return which === 'pick'
      ? businessIntroStickers()
      : businessProfile({ chat: which });
  });

  return {
    businessIntro,
    businessIntroStickers,
    businessIntroSet,
    businessProfile,
  };
};

export const createBusiness = (env, context) => ({
  ...createBusinessHours(env, context),
  ...createBusinessIntro(env, context),
});

/**
 * Which days of a chat hold messages, and how many, for the jump-to-date
 * calendar (R-Y207; learned, never copied): messages.getSearchResultsCalendar
 * answers the days (newest first) before `before`, so a month further back
 * is another request with an earlier `before` — offset paging.
 *
 * `calendar({ chat, filter?, before? })` → `{ ok, days: [{ date, count,
 * minId, maxId }], first, total, inexact }`: `date` is unix seconds, `first`
 * the time (unix seconds) of the chat's first matching message, `before` a
 * unix time (0: now). `filter` is one of FILTERS (default `empty`: every
 * message; `photoVideo` for the shared media tab).
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';

const failure = failureOf({ FLOOD_WAIT: 'flood' });

export const FILTERS = Object.freeze([
  'empty',
  'photos',
  'video',
  'photoVideo',
  'document',
  'url',
  'music',
  'voice',
]);

// The request's filter object of a name.
const filterOf = (Api, name) => {
  switch (name) {
    case 'photos':
      return new Api.InputMessagesFilterPhotos();
    case 'video':
      return new Api.InputMessagesFilterVideo();
    case 'photoVideo':
      return new Api.InputMessagesFilterPhotoVideo();
    case 'document':
      return new Api.InputMessagesFilterDocument();
    case 'url':
      return new Api.InputMessagesFilterUrl();
    case 'music':
      return new Api.InputMessagesFilterMusic();
    case 'voice':
      return new Api.InputMessagesFilterVoice();
    default:
      return new Api.InputMessagesFilterEmpty();
  }
};

/** The days of an answer, shaped for the page. */
export const daysOf = (answer) =>
  (answer?.periods ?? []).map((p) => ({
    date: Number(p.date),
    count: Number(p.count),
    minId: Number(p.minMsgId),
    maxId: Number(p.maxMsgId),
  }));

export const createCalendar = (env, { userClient }) => ({
  calendar: async ({ chat, filter = 'empty', before = 0 } = {}) => {
    if (!FILTERS.includes(filter) || !(Number(before) >= 0) || !chat) {
      return { ok: false, error: 'bad-request', code: 'bad-request' };
    }
    return connected(env, userClient, failure, async (c) => {
      const key = `calendar:${chat}:${filter}:${before}`;
      const answer = await runIn(env, key, () =>
        env.connection.withPeer(c.client, String(chat), (peer) =>
          c.client.invoke(
            new c.Api.messages.GetSearchResultsCalendar({
              peer,
              filter: filterOf(c.Api, filter),
              offsetId: 0,
              offsetDate: Number(before),
            })
          )
        )
      );
      return {
        ok: true,
        days: daysOf(answer),
        first: answer?.minDate ? Number(answer.minDate) : null,
        total: Number(answer?.count) || 0,
        inexact: Boolean(answer?.inexact),
      };
    });
  },
});

/**
 * The recent calls list, as Telegram Desktop's main menu → Calls shows it
 * (R-Y163; learned, never copied). The app places no calls; this is the
 * history only:
 * - `callsList({ missed?, offsetId? })` — the account's phone-call service
 *   messages across every chat (messages.search with no peer, no query
 *   and InputMessagesFilterPhoneCalls, `missed` for the Missed tab), newest
 *   first, a page at a time → `{ ok, calls, next }`; each call is `{ chat
 *   (the other person's user id), name, id, date (ms), out, video, missed
 *   (incoming and ended missed or busy), duration (seconds) }`; `next` is
 *   the id to ask again with, or null at the end. Group calls are not in
 *   this list.
 * Telegram's errors become codes the page shows as text.
 */

import { connected, runIn, failureOf } from './telegram-stickers.js';

const CODES = {
  FLOOD_WAIT: 'flood',
  AUTH_KEY_UNREGISTERED: 'no-access',
};

const failure = failureOf(CODES);

export const CALLS_PAGE = 50;
const OFFSET = /^\d{1,12}$/;

/** Whether a request body is one the list answers. */
export const validCallsRequest = (body = {}) =>
  (body.missed === undefined || typeof body.missed === 'boolean') &&
  (body.offsetId === undefined ||
    (typeof body.offsetId === 'number' || typeof body.offsetId === 'string'
      ? OFFSET.test(String(body.offsetId))
      : false));

const idOf = (peer) => String(peer?.userId ?? '');

const nameOf = (user) =>
  [user?.firstName, user?.lastName].filter(Boolean).join(' ') ||
  user?.username ||
  '';

const missedOf = (message) => {
  const reason = message.action?.reason?.className ?? '';
  return (
    !message.out &&
    (reason === 'PhoneCallDiscardReasonMissed' ||
      reason === 'PhoneCallDiscardReasonBusy')
  );
};

/** One call for the page, from a message and the users of the answer. */
export const callOf = (message, users) => {
  const chat = idOf(message.peerId);
  const user = users.get(chat);
  return {
    chat,
    name: nameOf(user),
    id: Number(message.id),
    date: Number(message.date) * 1000,
    out: Boolean(message.out),
    video: Boolean(message.action?.video),
    missed: missedOf(message),
    duration: Number(message.action?.duration ?? 0),
  };
};

export const createCalls = (env, { userClient }) => {
  const callsList = async (body = {}) => {
    if (!validCallsRequest(body)) {
      return { ok: false, error: 'bad request', code: 'failed' };
    }
    const offsetId = Number(body.offsetId ?? 0);
    return connected(env, userClient, failure, async (c) => {
      const answer = await runIn(
        env,
        `calls:${body.missed ? 1 : 0}:${offsetId}`,
        () =>
          c.client.invoke(
            new c.Api.messages.Search({
              peer: new c.Api.InputPeerEmpty(),
              q: '',
              filter: new c.Api.InputMessagesFilterPhoneCalls({
                ...(body.missed ? { missed: true } : {}),
              }),
              minDate: 0,
              maxDate: 0,
              offsetId,
              addOffset: 0,
              limit: CALLS_PAGE,
              maxId: 0,
              minId: 0,
              hash: c.zero,
            })
          )
      );
      const users = new Map(
        (answer?.users ?? []).map((user) => [String(user.id), user])
      );
      const messages = (answer?.messages ?? []).filter(
        (m) => m?.action?.className === 'MessageActionPhoneCall'
      );
      const calls = messages.map((m) => callOf(m, users));
      const raw = answer?.messages ?? [];
      return {
        ok: true,
        calls,
        next:
          raw.length >= CALLS_PAGE && raw.length > 0
            ? Number(raw.at(-1).id)
            : null,
      };
    });
  };
  return { callsList };
};

/**
 * Catching up on Telegram updates that never arrived.
 *
 * Telegram numbers the updates of an account (`pts`): each one says the
 * number after it and how many it adds (`ptsCount`). Telegram's own apps
 * (TDLib, Telegram Web A and K) keep the last number and ask
 * `updates.getDifference` for everything after it whenever
 *   - the connection comes back (after sleep, a network change),
 *   - an update skips numbers and the missing one does not show up
 *     within 0.7 s (TDLib's MAX_UNFILLED_GAP_TIME),
 *   - Telegram says there were too many (`updatesTooLong`),
 *   - the app starts again (the number is saved).
 * GramJS has the hook for this (`catchUp()`) but it is an empty TODO, so
 * without this module a message sent while the connection was down only
 * appeared on the next poll, and an edit or deletion not at all.
 *
 * What the difference returns goes through the same handler as live
 * updates (`handle`), so it lands as the same links. Channels and
 * supergroups have their own numbers; a gap there (`updateChannelTooLong`)
 * goes to that channel's own catch-up (`channelTooLong`,
 * ./telegram-channels.js), and a difference too long to fetch falls back
 * to re-reading the dialogs (`resync`). Applying an update twice is
 * harmless (links merge by id). Every request goes through `request`
 * (the account's paced queue).
 *
 * See docs/CHAT-REFERENCES.md, "Live updates and catching up after a gap".
 */

import { connectionStateOf } from './telegram-updates.js';
import { floodSeconds } from './telegram-history.js';

export const TELEGRAM_STATE_ID = 'state:telegram';

export const GAP_MS = 700;
const SAVE_MS = 1000;
const FIRST_RETRY_MS = 1000;
const MAX_RETRY_MS = 60_000;
const MAX_SLICES = 50;

// Channels count their own updates; only the account's common numbers
// are tracked here.
const ownPts = (update) =>
  update?.pts !== undefined &&
  update.ptsCount !== undefined &&
  !/Channel/.test(update.className ?? '');

/** The numbers an update moves the counter to, or null. */
export const ptsStep = (update) =>
  ownPts(update)
    ? { pts: Number(update.pts), count: Number(update.ptsCount) }
    : null;

/**
 * An update was seen but its store write failed: put the counter's `state`
 * back to just before it, so the difference that follows brings it again
 * (R-Z14). True when the counter moved.
 */
export const rewindPts = (state, update) => {
  const step = ptsStep(update);
  if (!step || !state || state.pts <= step.pts - step.count) {
    return false;
  }
  state.pts = step.pts - step.count;
  return true;
};

/** A user or chat as GramJS's marked peer id (what `_entities` uses). */
export const markedId = (entity) => {
  const id = String(entity?.id?.value ?? entity?.id ?? '');
  const kind = entity?.className ?? '';
  if (kind.startsWith('Channel')) {
    return `-100${id}`;
  }
  return kind.startsWith('Chat') ? `-${id}` : id;
};

/** The users and chats of an answer, by marked id (as `_entities`). */
export const entitiesOf = (result) =>
  new Map(
    [...(result.users ?? []), ...(result.chats ?? [])].map((e) => [
      markedId(e),
      e,
    ])
  );

const later = (timers, fn, ms) => {
  const id = timers.setTimeout(fn, ms);
  id?.unref?.();
  return id;
};

const stateOf = (next) => ({
  pts: Number(next.pts),
  qts: Number(next.qts ?? 0),
  date: Number(next.date ?? 0),
  seq: Number(next.seq ?? 0),
});

/**
 * The account's update counter. `step(update)` follows it; an update
 * past a gap waits in `pending`, and when the gap is still open after
 * `gapMs` (TDLib: 0.7 s) `onGap()` asks for the difference.
 */
export const createPtsCounter = ({
  gapMs = GAP_MS,
  timers = globalThis,
  onGap = () => {},
  onMove = () => {},
} = {}) => {
  let state = null; // { pts, qts, date, seq }
  let pending = []; // steps past a gap: [{ pts, count }]
  let gapTimer = null;
  // The numbers live updates started from while their store write runs.
  const writing = new Set();

  const closeGap = () => {
    timers.clearTimeout(gapTimer);
    gapTimer = null;
  };

  // Steps waiting behind a gap that now follow on.
  const drain = () => {
    pending = pending
      .filter((p) => p.pts > state.pts)
      .sort((a, b) => a.pts - b.pts);
    while (
      pending.length > 0 &&
      pending[0].pts - pending[0].count === state.pts
    ) {
      state.pts = pending.shift().pts;
    }
    if (pending.length === 0) {
      closeGap();
    }
  };

  const step = (update) => {
    const next = ptsStep(update);
    if (!next || !state) {
      return;
    }
    if (state.pts + next.count > next.pts) {
      return; // already applied
    }
    if (state.pts + next.count === next.pts) {
      state.pts = next.pts;
      drain();
      onMove();
      return;
    }
    pending.push(next);
    gapTimer ??= later(
      timers,
      () => {
        gapTimer = null;
        if (pending.length > 0) {
          onGap();
        }
      },
      gapMs
    );
  };

  return {
    step,
    get: () => state,
    set: (next) => {
      state = next ? stateOf(next) : null;
      if (state) {
        drain();
      }
    },
    patch: (fields) => {
      state = { ...state, ...fields };
      drain();
    },
    /**
     * A live update's store write began; `done` settles when it ended,
     * stored or failed. The saved number (`floor`) waits for it (R-Z14,
     * R-Z7): a write that fails after a save is fetched again after a crash.
     */
    track: (update, done) => {
      const step = ptsStep(update);
      if (step) {
        const from = step.pts - step.count;
        writing.add(from);
        Promise.resolve(done)
          .catch(() => {})
          .finally(() => {
            writing.delete(from);
            onMove();
          });
      }
      return done;
    },
    floor: () => Math.min(state?.pts ?? Infinity, ...writing),
    pending: () => pending.length,
    reset: () => {
      pending = [];
      closeGap();
    },
  };
};

// After a failure: again in 1 s, doubling up to 60 s (TDLib's backoff).
const createBackoff = (timers) => {
  let ms = 0;
  let timer = null;
  const stop = () => {
    timers.clearTimeout(timer);
    timer = null;
  };
  return {
    reset: () => {
      ms = 0;
      stop();
    },
    later: (fn, minimumMs = 0) => {
      ms = Math.min(ms ? ms * 2 : FIRST_RETRY_MS, MAX_RETRY_MS);
      stop();
      timer = later(
        timers,
        () => {
          timer = null;
          fn();
        },
        Math.max(ms, minimumMs)
      );
    },
    stop,
  };
};

const RESULT_UPDATES = new Set(['Updates', 'UpdatesCombined']);

/** The updates inside Telegram's answer to one of our requests. */
export const updatesOfResult = (result) => {
  if (RESULT_UPDATES.has(result?.className)) {
    return result.updates ?? [];
  }
  return [result?.className === 'UpdateShort' ? result.update : result];
};

// A difference's messages and updates, through the live handler.
const replay = async ({ client, handle, channelTooLong }, result) => {
  const entities = entitiesOf(result);
  const updates = [
    ...(result.newMessages ?? []).map((message) => ({
      className: 'UpdateNewMessage',
      message,
    })),
    ...(result.otherUpdates ?? []),
  ];
  for (const update of updates) {
    if (update?.className === 'UpdateChannelTooLong') {
      await channelTooLong(update);
      continue;
    }
    update._entities = entities;
    // Strict: a store write that fails stops the replay before the
    // counter moves, so the next try fetches the same updates (R-Z14).
    await handle(client, update, { strict: true });
  }
  return updates.length;
};

// updates.getDifference until Telegram says we are up to date; returns
// how many updates it replayed.
const fetchDifference = async ({
  client,
  Api,
  counter,
  feed,
  resync,
  request,
}) => {
  let fed = 0;
  for (let slice = 0; slice < MAX_SLICES; slice += 1) {
    const { pts, qts, date } = counter.get();
    const result = await request(`difference:${pts}:${qts}`, () =>
      client.invoke(new Api.updates.GetDifference({ pts, qts, date }))
    );
    const kind = result?.className;
    if (kind === 'updates.DifferenceEmpty') {
      counter.patch({ date: Number(result.date), seq: Number(result.seq) });
      break;
    }
    if (kind === 'updates.DifferenceTooLong') {
      // Too much to replay: take the new number and re-read the chats.
      counter.patch({ pts: Number(result.pts) });
      await resync('difference-too-long');
      break;
    }
    fed += await feed(result);
    if (kind !== 'updates.DifferenceSlice') {
      counter.set(result.state);
      break;
    }
    counter.set(result.intermediateState);
  }
  return fed;
};

// The counter written to the store; its number never passes a live write
// still running (`counter.floor`, R-Z7).
const saveCounter = async (store, account, counter) => {
  const state = counter.get();
  if (state && account) {
    await store.put({
      id: TELEGRAM_STATE_ID,
      tokens: ['state', 'telegram'],
      kind: 'state',
      source: 'telegram',
      account,
      ...state,
      pts: counter.floor(),
    });
  }
};

/**
 * One account's catch-up.
 *   handle(client, update)  the live handler (telegram-account-live.js)
 *   resync(reason)          re-read the dialogs (a difference too long)
 *   channelTooLong(update)  a channel's own gap (its own catch-up)
 *   request(key, task)      runs one request (the account's queue)
 *   importer()              resolves { Api } (the `telegram` package)
 *   onConnection(state)     GramJS's connection: 1, 0 or -1
 */
const logCatchUpFailure = (log, error, reason) => {
  const wait =
    floodSeconds(error) ||
    (error.code === 'flood-wait' ? Number(error.retryAfter) : 0);
  log({
    level: wait ? 'warn' : 'error',
    event: wait ? 'telegram_catch_up_waits' : 'telegram_catch_up_failed',
    reason,
    error: error.message,
    ...(wait ? { retryAfter: wait } : {}),
  });
  return wait;
};

export const createTelegramCatchUp = ({
  store,
  handle,
  resync = async () => {},
  channelTooLong = () => resync('channel-too-long'),
  request = (_key, task) => task(),
  importer,
  log = () => {},
  onConnection = () => {},
  gapMs = GAP_MS,
  timers = globalThis,
  now = Date.now,
}) => {
  let client = null;
  let account = null;
  let saveTimer = null;
  const backoff = createBackoff(timers);
  let running = null;
  let again = false;
  let connection = null;
  let retryAt = 0;

  const save = () => {
    timers.clearTimeout(saveTimer);
    saveTimer = null;
    return saveCounter(store, account, counter);
  };

  const counter = createPtsCounter({
    gapMs,
    timers,
    onGap: () => run('gap').catch(() => {}),
    onMove: () => {
      saveTimer ??= later(timers, () => save().catch(() => {}), SAVE_MS);
    },
  });

  const feed = (result) => replay({ client, handle, channelTooLong }, result);

  const difference = async (reason) => {
    const { Api } = await importer();
    if (!counter.get()) {
      // A new account: start from now (the dialog sync reads the past).
      counter.set(
        await request('difference:state', () =>
          client.invoke(new Api.updates.GetState())
        )
      );
      await save();
      return;
    }
    const fed = await fetchDifference({
      client,
      Api,
      counter,
      feed,
      resync,
      request,
    });
    await save();
    log({ event: 'telegram_catch_up', reason, updates: fed });
  };

  const once = async (reason) => {
    try {
      await difference(reason);
      backoff.reset();
      return true;
    } catch (error) {
      const wait = logCatchUpFailure(log, error, reason);
      retryAt = wait ? now() + wait * 1000 : 0;
      backoff.later(() => run(reason).catch(() => {}), wait * 1000);
      return false;
    }
  };

  /** Catch up now (one at a time; a call during a run runs once more). */
  const run = (reason = 'manual') => {
    if (!client || now() < retryAt) {
      return Promise.resolve();
    }
    if (running) {
      again = true;
      return running;
    }
    running = (async () => {
      do {
        again = false;
      } while ((await once(reason)) && again);
    })().finally(() => {
      running = null;
    });
    return running;
  };

  /** Every update the client receives (registered by `attach`). */
  const observe = (update) => {
    const linked = connectionStateOf(update);
    if (linked !== null) {
      const was = connection;
      connection = linked;
      onConnection(linked);
      if (linked === 1 && was !== null && was !== 1) {
        run('reconnect').catch(() => {});
      }
      return;
    }
    const kind = update?.className;
    if (kind === 'UpdatesTooLong') {
      run('too-long').catch(() => {});
    } else if (kind === 'UpdateChannelTooLong') {
      Promise.resolve(channelTooLong(update)).catch(() => {});
    } else {
      counter.step(update);
    }
  };

  /** Telegram's answer to one of our requests (a send, a read). */
  const observeResult = (result) => {
    for (const update of updatesOfResult(result)) {
      counter.step(update);
    }
  };

  /**
   * A freshly connected client of account `me`: listen, then catch up
   * from the saved number (or take the current one for a new account).
   */
  const attach = async (next, me) => {
    client = next;
    account = me?.id ? String(me.id) : null;
    // Connected before this handler was added, so GramJS's own
    // "connected" went by unseen.
    connection = 1;
    onConnection(1);
    counter.reset();
    if (typeof next?.addEventHandler === 'function') {
      next.addEventHandler(observe);
    }
    const saved = await store.get(TELEGRAM_STATE_ID);
    counter.set(
      saved && saved.account === account && Number.isFinite(saved.pts)
        ? saved
        : null
    );
    return run('start');
  };

  const stop = async () => {
    backoff.stop();
    counter.reset();
    const flush = saveTimer ? save() : Promise.resolve();
    client = null;
    await flush;
  };

  return {
    attach,
    observe,
    observeResult,
    track: counter.track,
    run,
    stop,
    state: counter.get,
  };
};

/**
 * Channel direct messages and suggested posts, shaped for the page
 * (R-Y191; learned from Telegram Desktop and the official apps, never
 * copied). Pure helpers, no network:
 * - `monoforumInfo(entity, chats)` — what a channel's info carries about
 *   its linked monoforum (the chat where subscribers write to the admins);
 * - `priceOf(amount)` — a StarsAmount / StarsTonAmount as `{ currency,
 *   amount }`;
 * - `suggestedOf(post)` — a SuggestedPost as `{ status, price, at }`;
 * - `actionOf(action)` — the suggested-post service messages;
 * - `dmMessageOf(message, names)` — one message of a thread;
 * - `threadOf(dialog, byId, names)` — one subscriber's thread.
 */

const text = (value) =>
  value === null || value === undefined ? '' : String(value.value ?? value);

const iso = (date) =>
  Number(date) > 0 ? new Date(Number(date) * 1000).toISOString() : null;

const NANO = 1_000_000_000;

/** A price: Stars (with nanos) or TON (the amount in nanoTON). */
export const priceOf = (amount) => {
  if (!amount) {
    return null;
  }
  if (amount.className === 'StarsTonAmount') {
    return { currency: 'ton', amount: Number(amount.amount) / NANO };
  }
  const stars = Number(amount.amount) + (Number(amount.nanos) || 0) / NANO;
  return { currency: 'stars', amount: stars };
};

/** A suggested post: pending until it is accepted or rejected. */
export const suggestedOf = (post) => {
  if (!post || post.className !== 'SuggestedPost') {
    return null;
  }
  let status = 'pending';
  if (post.accepted) {
    status = 'accepted';
  } else if (post.rejected) {
    status = 'rejected';
  }
  return {
    status,
    price: priceOf(post.price),
    at: iso(post.scheduleDate),
  };
};

/** The suggested-post service messages, as fields the page words. */
export const actionOf = (action) => {
  switch (action?.className) {
    case 'MessageActionSuggestedPostApproval':
      return {
        type: 'approval',
        rejected: Boolean(action.rejected),
        balanceTooLow: Boolean(action.balanceTooLow),
        comment: action.rejectComment ? String(action.rejectComment) : null,
        price: priceOf(action.price),
        at: iso(action.scheduleDate),
      };
    case 'MessageActionSuggestedPostSuccess':
      return { type: 'success', price: priceOf(action.price) };
    case 'MessageActionSuggestedPostRefund':
      return { type: 'refund', payerInitiated: Boolean(action.payerInitiated) };
    case 'MessageActionPaidMessagesPrice':
      return {
        type: 'price',
        stars: Number(action.stars) || 0,
        allowed: Boolean(action.broadcastMessagesAllowed),
      };
    default:
      return null;
  }
};

/** A person's name for a row. */
export const nameOfUser = (user) =>
  [user?.firstName, user?.lastName].filter(Boolean).join(' ') ||
  user?.username ||
  (user?.id === undefined ? '' : text(user.id));

/** `Map(userId -> name)` of an answer's users. */
export const namesOf = (users = []) =>
  new Map(users.filter(Boolean).map((u) => [text(u.id), nameOfUser(u)]));

const senderOf = (message) =>
  text(message.fromId?.userId ?? message.fromId?.channelId ?? '');

/** One message of a thread, as the page shows it. */
export const dmMessageOf = (message, names = new Map()) => {
  const action = actionOf(message.action);
  const from = senderOf(message);
  return {
    id: Number(message.id),
    out: Boolean(message.out),
    from,
    name: names.get(from) ?? '',
    text: String(message.message ?? ''),
    at: iso(message.date),
    thread: message.savedPeerId ? text(message.savedPeerId.userId) : null,
    paid: Number(message.paidMessageStars) || 0,
    suggested: suggestedOf(message.suggestedPost),
    ...(action ? { service: action } : {}),
  };
};

/** One subscriber's thread of a monoforum, for the list. */
export const threadOf = (dialog, byId, names) => {
  if (dialog?.className !== 'MonoForumDialog') {
    return null;
  }
  const id = text(dialog.peer?.userId ?? dialog.peer?.channelId);
  if (!id) {
    return null;
  }
  const last = byId.get(Number(dialog.topMessage));
  const shaped = last ? dmMessageOf(last, names) : null;
  return {
    peer: id,
    name: names.get(id) || id,
    unread: Number(dialog.unreadCount) || 0,
    top: Number(dialog.topMessage) || 0,
    at: shaped?.at ?? null,
    last: shaped ? { id: shaped.id, text: shaped.text, out: shaped.out } : null,
    free: Boolean(dialog.nopaidMessagesException),
  };
};

/**
 * What a channel's info says about its monoforum, from the channel
 * entity and the chats of the same answer: `{ id, title, price, admin,
 * allowed }`, or null without one. `price` is Stars per message (0 for
 * none); `admin` is whether the user answers the subscribers (the
 * creator, or an admin allowed to manage direct messages).
 */
export const monoforumInfo = (entity = {}, chats = []) => {
  const linked = text(entity.linkedMonoforumId);
  if (!linked || linked === '0') {
    return null;
  }
  const mono = chats.find((c) => c && text(c.id) === linked) ?? {};
  return {
    id: `-100${linked}`,
    title: String(mono.title ?? entity.title ?? ''),
    price:
      Number(mono.sendPaidMessagesStars ?? entity.sendPaidMessagesStars) || 0,
    allowed: Boolean(entity.broadcastMessagesAllowed),
    admin: Boolean(entity.creator || entity.adminRights?.manageDirectMessages),
  };
};

/**
 * Channel direct messages and suggested posts, as Telegram Desktop and the
 * official apps have them (R-Y191; learned, never copied). A channel may
 * link a monoforum: a chat where each subscriber has a thread with the
 * channel's admins. Everything here is asked by the page, a write only on
 * its own click.
 *
 * - `channelDmThreads({ chat })` — the admin's list of threads
 *   (messages.getSavedDialogs with `parent_peer` = the monoforum) →
 *   `{ ok, threads: [{ peer, name, unread, top, at, last, free }] }`;
 * - `channelDmHistory({ chat, peer?, before?, limit? })` — a thread's
 *   messages, oldest first: with `peer` (an admin) messages.getSavedHistory
 *   with `parent_peer` and `peer` = the subscriber; without (a subscriber)
 *   messages.getHistory of the monoforum → `{ ok, messages, complete }`;
 * - `channelDmSend({ chat, text, peer?, stars?, suggestedPost?, clientId? })`
 *   — messages.sendMessage into the monoforum: an admin's reply names the
 *   thread with `InputReplyToMonoForum`; `stars` is the price the sender
 *   accepts for one message (`allow_paid_stars`); `suggestedPost` = `{
 *   stars, scheduleDate? }` is a subscriber's suggestion of a post;
 * - `channelDmDecide({ chat, id, approve, scheduleDate?, comment? })` —
 *   messages.toggleSuggestedPostApproval: an admin accepts a suggested
 *   post, or rejects it with an optional comment.
 * Telegram's errors become codes the page shows as words.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';
import { randomIdOf } from './telegram-send.js';
import { dmMessageOf, namesOf, threadOf } from './telegram-channel-dm-shape.js';

const CODES = {
  ALLOW_PAYMENT_REQUIRED: 'payment-required',
  BALANCE_TOO_LOW: 'balance',
  CHAT_ADMIN_REQUIRED: 'admin-required',
  CHAT_WRITE_FORBIDDEN: 'write-forbidden',
  USER_BANNED_IN_CHANNEL: 'write-forbidden',
  MESSAGE_ID_INVALID: 'gone',
  SCHEDULE_DATE_INVALID: 'bad-date',
  SUGGESTED_POST_PEER_INVALID: 'not-allowed',
  PEER_ID_INVALID: 'no-access',
  CHANNEL_PRIVATE: 'no-access',
  CHANNEL_INVALID: 'no-access',
  CHAT_ID_INVALID: 'no-access',
  MESSAGE_TOO_LONG: 'too-long',
  MESSAGE_EMPTY: 'empty',
  FLOOD_WAIT: 'flood',
};
const failure = failureOf(CODES);

const CHANNEL = /^-100\d{1,15}$/;
const USER = /^\d{1,20}$/;
const bad = { ok: false, error: 'bad request', code: 'bad-request' };
const PAGE = 50;

const positive = (value) => {
  const n = Number(value);
  return Number.isInteger(n) && n > 0 ? n : null;
};

const byId = (messages) =>
  new Map(messages.map((m) => [Number(m.id), m]).filter(([id]) => id > 0));

const shown = (messages) =>
  [...(messages ?? [])].filter(
    (m) => m && m.id !== undefined && m.className !== 'MessageEmpty'
  );

// The request that sends a message into the monoforum: an admin's reply
// names the thread (`reply`, the subscriber's input peer), a price paid
// goes as `allow_paid_stars`, a suggestion as `suggested_post`.
const sendRequest = (c, { parent, text, reply, stars, post, clientId }) =>
  new c.Api.messages.SendMessage({
    peer: parent,
    message: text,
    randomId: randomIdOf(clientId, 0, c.helpers),
    ...(reply
      ? {
          replyTo: new c.Api.InputReplyToMonoForum({
            monoforumPeerId: reply,
          }),
        }
      : {}),
    ...(positive(stars)
      ? { allowPaidStars: c.helpers.returnBigInt(stars) }
      : {}),
    ...(post
      ? {
          suggestedPost: new c.Api.SuggestedPost({
            price: new c.Api.StarsAmount({
              amount: c.helpers.returnBigInt(positive(post.stars) ?? 0),
              nanos: 0,
            }),
            ...(positive(post.scheduleDate)
              ? { scheduleDate: post.scheduleDate }
              : {}),
          }),
        }
      : {}),
  });

// The thread's messages: an admin's (saved history of the subscriber under
// the monoforum), else the subscriber's own (the monoforum's history).
const historyRequest = (c, { parent, subscriber, before }) => {
  const page = {
    offsetId: positive(before) ?? 0,
    offsetDate: 0,
    addOffset: 0,
    limit: PAGE,
    maxId: 0,
    minId: 0,
    hash: c.zero,
  };
  return subscriber
    ? new c.Api.messages.GetSavedHistory({
        parentPeer: parent,
        peer: subscriber,
        ...page,
      })
    : new c.Api.messages.GetHistory({ peer: parent, ...page });
};

const decideRequest = (c, { parent, id, approve, scheduleDate, comment }) =>
  new c.Api.messages.ToggleSuggestedPostApproval({
    peer: parent,
    msgId: positive(id),
    ...(approve ? {} : { reject: true }),
    ...(approve && positive(scheduleDate) ? { scheduleDate } : {}),
    ...(!approve && String(comment ?? '').trim()
      ? { rejectComment: String(comment).trim() }
      : {}),
  });

const validChat = (chat) => CHANNEL.test(String(chat ?? ''));
const validPeer = (peer) => peer === null || USER.test(String(peer));

export const createChannelDm = (env, { userClient }) => {
  // Subscribers' input peers, as the last list or history gave them.
  const known = new Map();

  const rememberUsers = (c, chat, users) => {
    for (const user of users ?? []) {
      if (user?.id !== undefined && user.accessHash !== undefined) {
        known.set(
          `${chat}:${user.id}`,
          new c.Api.InputPeerUser({
            userId: user.id,
            accessHash: user.accessHash,
          })
        );
      }
    }
  };

  const subscriberOf = async (c, chat, peer) =>
    peer === null
      ? null
      : (known.get(`${chat}:${peer}`) ??
        (await env.connection.withPeer(c.client, String(peer), (p) => p)));

  // `use(c, parent)` on the monoforum's peer, through the queue.
  const inMonoforum = (c, chat, name, use) =>
    runIn(env, `${name}:${chat}`, () =>
      env.connection.withPeer(c.client, String(chat), (parent) => use(parent))
    );

  const threads = async ({ chat } = {}) =>
    !validChat(chat)
      ? bad
      : connected(env, userClient, failure, async (c) => {
          const answer = await inMonoforum(c, chat, 'channel-dm', (parent) =>
            c.client.invoke(
              new c.Api.messages.GetSavedDialogs({
                parentPeer: parent,
                offsetDate: 0,
                offsetId: 0,
                offsetPeer: new c.Api.InputPeerEmpty(),
                limit: 100,
                hash: c.zero,
              })
            )
          );
          rememberUsers(c, String(chat), answer?.users);
          const names = namesOf(answer?.users);
          const messages = byId(shown(answer?.messages));
          return {
            ok: true,
            threads: (answer?.dialogs ?? [])
              .map((d) => threadOf(d, messages, names))
              .filter(Boolean),
          };
        });

  const history = async ({ chat, peer = null, before = null } = {}) =>
    !validChat(chat) || !validPeer(peer)
      ? bad
      : connected(env, userClient, failure, async (c) => {
          const answer = await inMonoforum(
            c,
            chat,
            'channel-dm-history',
            async (parent) =>
              c.client.invoke(
                historyRequest(c, {
                  parent,
                  subscriber: await subscriberOf(c, String(chat), peer),
                  before,
                })
              )
          );
          const names = namesOf(answer?.users);
          const list = shown(answer?.messages);
          return {
            ok: true,
            messages: list
              .map((m) => dmMessageOf(m, names))
              .sort((a, b) => a.id - b.id),
            complete: list.length < PAGE,
          };
        });

  const send = async ({
    chat,
    text,
    peer = null,
    stars = null,
    suggestedPost = null,
    clientId,
  } = {}) =>
    !validChat(chat) ||
    typeof text !== 'string' ||
    text.trim() === '' ||
    !validPeer(peer)
      ? bad
      : connected(env, userClient, failure, async (c) => {
          const sent = await inMonoforum(
            c,
            chat,
            'channel-dm-send',
            async (parent) =>
              c.client.invoke(
                sendRequest(c, {
                  parent,
                  text,
                  reply: await subscriberOf(c, String(chat), peer),
                  stars,
                  post: suggestedPost,
                  clientId,
                })
              )
          );
          env.catchUp?.observeResult?.(sent);
          return { ok: true };
        });

  const decide = async ({ chat, id, approve, ...rest } = {}) =>
    !validChat(chat) || !positive(id) || typeof approve !== 'boolean'
      ? bad
      : connected(env, userClient, failure, async (c) => {
          await inMonoforum(c, chat, 'channel-dm-decide', (parent) =>
            c.client.invoke(decideRequest(c, { parent, id, approve, ...rest }))
          );
          return { ok: true, approved: approve };
        });

  return {
    channelDmThreads: threads,
    channelDmHistory: history,
    channelDmSend: send,
    channelDmDecide: decide,
  };
};

/**
 * Managing a channel or group, as Telegram Desktop's Edit has it (R-Y216;
 * learned, never copied):
 * - `channelUsernameCheck({ chat, username })` — channels.checkUsername
 *   → `{ ok, status: 'available' }`; USERNAME_INVALID, USERNAME_OCCUPIED
 *   and CHANNELS_ADMIN_PUBLIC_TOO_MUCH come back as codes;
 * - `channelUsernameSave({ chat, username })` — channels.updateUsername
 *   (an empty name makes the chat private);
 * - `publicChannels()` — channels.getAdminedPublicChannels → `{ ok,
 *   channels: [{ chat, title, username }] }`, for the limit's "Revoke link";
 * - `publicLinkRevoke({ chat })` — one of those channels made private;
 * - `usernamesDeactivate({ chat })` — channels.deactivateAllUsernames;
 * - `channelColorSave({ chat, forProfile, color?, emoji? })` —
 *   channels.updateColor (name colour or profile colour, with a background
 *   emoji); BOOSTS_REQUIRED comes back as `boosts`;
 * - `channelEmojiStatusSet({ chat, documentId|null, until? })` —
 *   channels.updateEmojiStatus;
 * - `inactiveChannels()` — channels.getInactiveChannels → `{ ok, channels:
 *   [{ chat, title, date, broadcast }] }`, for the "too many channels" case;
 * - `leaveChannels({ chats })` — channels.leaveChannel on the chosen ones,
 *   only those Telegram lists as inactive.
 * Deleting a chat is `removeChat` with the `destroy` action.
 * Telegram's errors become codes the page shows as text.
 */

import { connected, runIn } from './telegram-stickers.js';
import { quietFailureOf } from './telegram-chat-settings.js';

const CODES = {
  USERNAME_INVALID: 'invalid',
  USERNAME_PURCHASE_AVAILABLE: 'taken',
  USERNAME_OCCUPIED: 'taken',
  USERNAME_NOT_MODIFIED: 'not-modified',
  CHANNELS_ADMIN_PUBLIC_TOO_MUCH: 'too-many-public',
  CHAT_ADMIN_REQUIRED: 'not-admin',
  CHAT_NOT_MODIFIED: 'not-modified',
  CHANNEL_PRIVATE: 'no-access',
  CHANNEL_INVALID: 'no-access',
  BOOSTS_REQUIRED: 'boosts',
  COLOR_INVALID: 'invalid',
  DOCUMENT_INVALID: 'invalid',
  EMOJI_STATUS_INVALID: 'invalid',
  FLOOD_WAIT: 'flood',
};

const failure = quietFailureOf(CODES);
const bad = (code = 'bad-request') => ({ ok: false, error: code, code });

const CHANNEL = /^-100\d{1,20}$/;
const NAME = /^[A-Za-z][A-Za-z0-9_]{3,30}[A-Za-z0-9]$/;
const EMOJI = /^\d{1,20}$/;
const MAX_COLOR = 20;
const MAX_LEAVE = 100;
const MAX_UNTIL_SECONDS = 366 * 24 * 3600;

const text = (value) => String(value?.value ?? value);
const idOf = (raw) => `-100${text(raw.id)}`;

const nameOk = (username) =>
  typeof username === 'string' && (username === '' || NAME.test(username));

const colorOk = ({ forProfile, color, emoji }) =>
  typeof forProfile === 'boolean' &&
  (color === undefined ||
    (Number.isInteger(color) && color >= 0 && color <= MAX_COLOR)) &&
  (emoji === undefined || EMOJI.test(String(emoji)));

const statusOk = (r, seconds) =>
  (r.documentId === null || EMOJI.test(String(r.documentId))) &&
  (r.until === undefined ||
    (Number.isInteger(r.until) &&
      r.until > seconds &&
      r.until <= seconds + MAX_UNTIL_SECONDS));

const publicOf = (raw) =>
  raw?.className === 'Channel'
    ? { chat: idOf(raw), title: raw.title ?? '', username: raw.username ?? '' }
    : null;

const inactiveOf = (answer) =>
  (answer?.chats ?? [])
    .map((raw, i) => ({ raw, date: Number(answer.dates?.[i]) || 0 }))
    .filter(({ raw }) => raw?.className === 'Channel');

// The shared helpers of the actions below.
const kitOf = (env, userClient) => {
  const ask = (c, key, request) =>
    runIn(env, `channel-manage:${key}`, () => c.client.invoke(request));
  const withChannel = (c, chat, use) =>
    runIn(env, `channel-manage:${chat}`, () =>
      env.connection.withPeer(c.client, chat, use)
    );
  // An action that runs `use(request)(c)` for a request that passed `valid`.
  const guarded = (valid, use) => async (request) =>
    valid(request ?? {})
      ? connected(env, userClient, failure, use(request ?? {}))
      : bad();
  // An action of one request on the chat's channel.
  const onChannel = (valid, make) =>
    guarded(
      (r) => CHANNEL.test(String(r.chat ?? '')) && valid(r),
      (r) => async (c) => {
        await withChannel(c, String(r.chat), (peer) =>
          c.client.invoke(make(c, peer, r))
        );
        return { ok: true };
      }
    );
  const plain = (use) => async () =>
    connected(env, userClient, failure, async (c) => ({
      ok: true,
      ...(await use(c)),
    }));
  const admined = async (c) =>
    (
      (await ask(c, 'admined', new c.Api.channels.GetAdminedPublicChannels({})))
        ?.chats ?? []
    ).filter((x) => x?.className === 'Channel');
  // The inactive channels Telegram lists, with their dates.
  const inactive = async (c) =>
    inactiveOf(
      await ask(c, 'inactive', new c.Api.channels.GetInactiveChannels())
    );
  return { ask, withChannel, guarded, onChannel, plain, admined, inactive };
};

const createPublicLink = ({
  ask,
  withChannel,
  guarded,
  onChannel,
  admined,
  plain,
}) => ({
  channelUsernameCheck: guarded(
    (r) => CHANNEL.test(String(r.chat ?? '')) && NAME.test(r.username ?? ''),
    (r) => async (c) => {
      const free = await withChannel(c, String(r.chat), (peer) =>
        c.client.invoke(
          new c.Api.channels.CheckUsername({
            channel: peer,
            username: r.username,
          })
        )
      );
      return free === false ? bad('taken') : { ok: true, status: 'available' };
    }
  ),
  channelUsernameSave: onChannel(
    (r) => nameOk(r.username),
    (c, peer, r) =>
      new c.Api.channels.UpdateUsername({
        channel: peer,
        username: r.username,
      })
  ),
  publicChannels: plain(async (c) => ({
    channels: (await admined(c)).map(publicOf).filter(Boolean),
  })),
  publicLinkRevoke: guarded(
    (r) => CHANNEL.test(String(r.chat ?? '')),
    (r) => async (c) => {
      const found = (await admined(c)).find((x) => idOf(x) === r.chat);
      if (!found) {
        return bad('no-access');
      }
      await ask(
        c,
        'revoke',
        new c.Api.channels.UpdateUsername({
          channel: new c.Api.InputChannel({
            channelId: found.id,
            accessHash: found.accessHash,
          }),
          username: '',
        })
      );
      return { ok: true };
    }
  ),
  usernamesDeactivate: onChannel(
    () => true,
    (c, peer) => new c.Api.channels.DeactivateAllUsernames({ channel: peer })
  ),
});

const createLook = (env, { onChannel }) => ({
  channelColorSave: onChannel(colorOk, (c, peer, r) => {
    const { forProfile, color, emoji } = r;
    return new c.Api.channels.UpdateColor({
      channel: peer,
      ...(forProfile ? { forProfile: true } : {}),
      ...(color === undefined ? {} : { color }),
      ...(emoji === undefined
        ? {}
        : { backgroundEmojiId: c.helpers.returnBigInt(String(emoji)) }),
    });
  }),
  channelEmojiStatusSet: onChannel(
    (r) => statusOk(r, (env.now ?? Date.now)() / 1000),
    (c, peer, r) =>
      new c.Api.channels.UpdateEmojiStatus({
        channel: peer,
        emojiStatus:
          r.documentId === null
            ? new c.Api.EmojiStatusEmpty()
            : new c.Api.EmojiStatus({
                documentId: c.helpers.returnBigInt(String(r.documentId)),
                ...(r.until === undefined ? {} : { until: r.until }),
              }),
      })
  ),
});

const createInactive = ({ ask, guarded, plain, inactive }) => ({
  inactiveChannels: plain(async (c) => ({
    channels: (await inactive(c)).map(({ raw, date }) => ({
      chat: idOf(raw),
      title: raw.title ?? '',
      date,
      broadcast: Boolean(raw.broadcast),
    })),
  })),
  leaveChannels: guarded(
    (r) =>
      Array.isArray(r.chats) &&
      r.chats.length > 0 &&
      r.chats.length <= MAX_LEAVE &&
      r.chats.every((x) => CHANNEL.test(String(x))),
    (r) => async (c) => {
      const listed = new Map(
        (await inactive(c)).map((x) => [idOf(x.raw), x.raw])
      );
      const left = [];
      for (const chat of new Set(r.chats.map(String))) {
        const raw = listed.get(chat);
        if (raw) {
          await ask(
            c,
            'leave',
            new c.Api.channels.LeaveChannel({
              channel: new c.Api.InputChannel({
                channelId: raw.id,
                accessHash: raw.accessHash,
              }),
            })
          );
          left.push(chat);
        }
      }
      return { ok: true, left };
    }
  ),
});

export const createChannelManage = (env, { userClient }) => {
  const kit = kitOf(env, userClient);
  return {
    ...createPublicLink(kit),
    ...createLook(env, kit),
    ...createInactive(kit),
  };
};

/**
 * Each channel's and supergroup's own catch-up (R-Y35).
 *
 * Telegram numbers a channel's updates on their own (`pts`), apart from
 * the account's. When it has too many to push for one channel it sends
 * `updateChannelTooLong` instead, and an update that skips numbers means
 * some never came — in both cases a new message, an edit or a deletion
 * is missing. Telegram's apps then ask `updates.getChannelDifference`
 * for that channel from its last number (TDLib's get_channel_difference,
 * Telegram Web K's getChannelDifference); so does this module, instead
 * of re-reading the whole chat list, which brings neither edits nor
 * deletions and costs far more requests.
 *
 * A channel's number lives in the store (`pts:telegram:<chat>`), from
 * the chat list (each dialog carries it) and then from every update, so
 * a restart goes on where it stopped. One channel is caught up at most
 * once a minute unless the user has it open, through the account's
 * queue; broadcast channels (not groups) only while the user reads them,
 * as their history is read on demand only (R-Y30).
 */

import {
  coverSlice,
  historyLink,
  historyLinkId,
  floodSeconds,
} from './telegram-history.js';
import { peerChatId } from './telegram-updates.js';
import { entitiesOf } from './telegram-catchup.js';
import { importTelegram } from './telegram-layer.js';

const SOURCE = 'telegram';
export const channelStateId = (chat) => `pts:${SOURCE}:${chat}`;

const SAVE_MS = 10_000;
export const CHANNEL_EVERY_MS = 60_000;
// A channel read this recently is open in the app.
const OPEN_MS = 10 * 60_000;
const SLICES = 10;
const SLICE = 100;

const text = (value) =>
  value === null || value === undefined ? null : String(value.value ?? value);

const channelOf = (update) => `-100${text(update.channelId)}`;

const CHANNEL_UPDATES = {
  UpdateNewChannelMessage: (u) => peerChatId(u.message?.peerId),
  UpdateEditChannelMessage: (u) => peerChatId(u.message?.peerId),
  UpdateDeleteChannelMessages: channelOf,
  UpdatePinnedChannelMessages: channelOf,
  UpdateChannelWebPage: channelOf,
};

/**
 * Where a channel's update moves its number: `{ chat, pts, count }`, or
 * `{ chat, tooLong: true }`; null for other updates.
 */
export const channelStep = (update) => {
  const name = update?.className;
  if (name === 'UpdateChannelTooLong') {
    return { chat: channelOf(update), tooLong: true };
  }
  const chatOf = CHANNEL_UPDATES[name];
  if (!chatOf || update.pts === undefined) {
    return null;
  }
  const chat = chatOf(update);
  return chat?.startsWith('-100')
    ? { chat, pts: Number(update.pts), count: Number(update.ptsCount ?? 0) }
    : null;
};

const stateLink = (chat, pts, at) => ({
  id: channelStateId(chat),
  tokens: ['pts', SOURCE, String(chat)],
  kind: 'pts',
  source: SOURCE,
  chat: String(chat),
  pts,
  at,
});

// The difference's messages extend the chat's stored stretch; after
// `tooLong` what lay between is unknown, so the stretch starts again.
const cover = async ({ store, now }, chat, ids, gap) => {
  if (ids.length === 0) {
    return;
  }
  const record = await store.get(historyLinkId(chat));
  const next = coverSlice(record, {
    ids,
    limit: gap ? ids.length : Infinity,
    mode: gap ? 'newest' : 'since',
    at: record?.at ?? new Date(now()).toISOString(),
  });
  await store.put(historyLink(chat, next));
};

const channelWarn = (log) => (error) => {
  const waiting = error?.code === 'flood-wait' || floodSeconds(error) > 0;
  log({
    level: waiting ? 'info' : 'warn',
    event: waiting
      ? 'telegram_channel_catch_up_waits'
      : 'telegram_channel_catch_up_failed',
    code: error?.code ?? null,
    error: error?.message,
  });
};

// A live update was not stored: the channel's number goes back to just
// before it (R-Z14). Returns the chat to catch up, or null.
const rewindChannel = (states, dirty, update) => {
  const step = channelStep(update);
  const state = step && !step.tooLong ? states.get(step.chat) : null;
  if (!state || !(state.pts > step.pts - step.count)) {
    return null;
  }
  states.set(step.chat, { ...state, pts: step.pts - step.count, at: 0 });
  dirty.add(step.chat);
  return step.chat;
};

const replay = async (ctx, client, chat, result, gap) => {
  const entities = entitiesOf(result);
  const messages = result.newMessages ?? result.messages ?? [];
  const updates = [
    ...messages.map((message) => ({
      className: 'UpdateNewChannelMessage',
      message,
    })),
    ...(result.otherUpdates ?? []),
  ];
  for (const update of updates) {
    update._entities = entities;
    // Strict: the channel's number must not pass an update that was not
    // stored (R-Z14).
    await ctx.handle(client, update, { strict: true });
  }
  await cover(
    ctx,
    chat,
    messages.map((m) => Number(m?.id)).filter(Number.isFinite),
    gap
  );
  return updates.length;
};

/**
 * `observe(update)` follows every update; `seed(chat, pts)` takes a
 * listed dialog's number for a channel not followed yet; `difference(
 * chat, priority)` catches one channel up now; `opened(chat)` says the
 * user reads it. `handle(client, update)` is the live handler, `request(
 * key, priority, task)` the queue, `peers` the stored input peers.
 */
export const createChannelSync = ({
  store,
  peers,
  request,
  handle,
  client: clientOf,
  importer = importTelegram,
  log = () => {},
  now = () => Date.now(),
  timers = globalThis,
}) => {
  const ctx = { store, handle, now };
  const warnFailed = channelWarn(log);
  const states = new Map(); // chat -> { pts, at } (at: last caught up)
  const dirty = new Set();
  const opened = new Map(); // chat -> when the user last read it
  let saveTimer = null;

  const stateOf = async (chat) => {
    if (!states.has(chat)) {
      const saved = await store.get(channelStateId(chat));
      states.set(chat, saved ? { pts: saved.pts, at: 0 } : null);
    }
    return states.get(chat);
  };

  const save = async () => {
    timers.clearTimeout(saveTimer);
    saveTimer = null;
    const at = new Date(now()).toISOString();
    const chats = [...dirty];
    dirty.clear();
    for (const chat of chats) {
      const state = states.get(chat);
      if (state) {
        await store.put(stateLink(chat, state.pts, at));
      }
    }
  };

  const move = (chat, pts) => {
    const state = states.get(chat) ?? { pts: 0, at: 0 };
    if (pts <= state.pts) {
      return;
    }
    states.set(chat, { ...state, pts });
    dirty.add(chat);
    saveTimer ??= timers.setTimeout(() => save().catch(() => {}), SAVE_MS);
    saveTimer?.unref?.();
  };

  // One answer of getChannelDifference: the next number, and whether
  // there is more.
  const apply = async (client, chat, result) => {
    const kind = result?.className;
    if (kind === 'updates.ChannelDifferenceTooLong') {
      const fed = await replay(ctx, client, chat, result, true);
      return { pts: Number(result.dialog?.pts), final: true, fed };
    }
    const fed =
      kind === 'updates.ChannelDifference'
        ? await replay(ctx, client, chat, result, false)
        : 0;
    return { pts: Number(result?.pts), final: result?.final !== false, fed };
  };

  /** Catch one channel up now; how many updates it brought. */
  const difference = async (chat, priority = 'prefetch') => {
    const state = await stateOf(chat);
    const channel = state?.pts ? await peers.input(chat) : null;
    const client = channel ? await clientOf() : null;
    if (!client) {
      return null;
    }
    states.set(chat, { ...state, at: now() });
    const { Api } = await importer();
    let fed = 0;
    for (let slice = 0; slice < SLICES; slice += 1) {
      const pts = states.get(chat).pts;
      const result = await request(`channel:${chat}:${pts}`, priority, () =>
        client.invoke(
          new Api.updates.GetChannelDifference({
            channel,
            filter: new Api.ChannelMessagesFilterEmpty(),
            pts,
            limit: SLICE,
          })
        )
      );
      const step = await apply(client, chat, result);
      fed += step.fed;
      if (Number.isFinite(step.pts)) {
        move(chat, step.pts);
      }
      if (step.final) {
        break;
      }
    }
    log({ event: 'telegram_channel_catch_up', priority, updates: fed });
    return fed;
  };

  const isOpen = (chat) => now() - (opened.get(chat) ?? -Infinity) < OPEN_MS;

  // A gap: caught up soon, unless it was a moment ago (it is then caught
  // up the next time one is due, or when the user opens the chat).
  const due = async (chat) => {
    const state = await stateOf(chat);
    if (!state?.pts || now() - state.at < CHANNEL_EVERY_MS) {
      return;
    }
    const dialog = await peers.dialog(chat);
    if (!isOpen(chat) && !dialog?.isGroup) {
      return; // a broadcast channel nobody reads now
    }
    await difference(chat, isOpen(chat) ? 'list' : 'prefetch');
  };

  const observe = async (update) => {
    const step = channelStep(update);
    if (!step) {
      return;
    }
    const state = await stateOf(step.chat);
    if (step.tooLong) {
      await due(step.chat);
      return;
    }
    if (state?.pts && step.pts - step.count > state.pts) {
      await due(step.chat); // numbers skipped: something never came
      return;
    }
    move(step.chat, step.pts);
  };

  const seed = async (chat, pts) => {
    if (String(chat).startsWith('-100') && Number(pts) > 0) {
      const state = await stateOf(String(chat));
      if (!state?.pts) {
        move(String(chat), Number(pts));
      }
    }
  };

  // A live channel update that could not be stored: the channel is caught
  // up again from just before it, so it is fetched, not lost (R-Z14).
  const failed = (update) => {
    const chat = rewindChannel(states, dirty, update);
    if (chat) {
      difference(chat).catch(warnFailed);
    }
  };

  return {
    failed,
    observe: (update) => observe(update).catch(warnFailed),
    seed,
    difference,
    /** Whether a channel's number is known (it can be caught up). */
    follows: async (chat) => Boolean((await stateOf(String(chat)))?.pts),
    opened: (chat) => opened.set(String(chat), now()),
    flush: save,
  };
};

/**
 * Adding members and managing administrators (R-Y204; learned, never
 * copied): the actions of telegram-add-members.js (`addCandidates`,
 * `addMembers`, `sendInviteLink`) and telegram-admin-manage.js
 * (`chatAdmins`, `setAdmin`, `setHistoryHidden`, `upgradeGroup`), sharing
 * the users they have seen (their access hashes).
 */

import { createAddMembersActions } from './telegram-add-members.js';
import { createAdminManage } from './telegram-admin-manage.js';

export const createChatAdmins = (env, context) => {
  const known = new Map();
  return {
    ...createAddMembersActions(env, context, known),
    ...createAdminManage(env, context, known),
  };
};

/**
 * New groups and channels, and a chat's info edited, as Telegram Desktop
 * does (R-Y129; learned, never copied):
 * - `chatContacts()` — the user's contacts to pick members from
 *   (contacts.getContacts) → `{ ok, contacts: [{ id, name, username, phone, online,
 *   lastSeen? }] }` (R-Y189: `lastSeen` an ISO time, or recently/week/month);
 * - `createGroup({ title, users })` — a basic group of those contacts
 *   (messages.createChat) → `{ ok, chat, title }`;
 * - `createChannel({ title, about })` — a broadcast channel
 *   (channels.createChannel) → `{ ok, chat, title }`;
 * - `editChatInfo({ chat, title?, about?, photo? })` — the title, the
 *   description, and the photo: an upload's `token` (the page's upload,
 *   sent as the chat's photo) or `'remove'` → `{ ok }`.
 * The new peer is remembered and Telegram's answer goes through the live
 * handler. Telegram's errors become codes the page shows as text.
 */

import { markedId } from './telegram-invite.js';
import { statusOf } from './telegram-chat-info.js';
import { connect, runIn, connected } from './telegram-stickers.js';

export const MAX_TITLE = 128;
export const MAX_ABOUT = 255;
export const MAX_MEMBERS = 200;

const CODES = {
  CHAT_TITLE_EMPTY: 'title-empty',
  CHAT_ABOUT_TOO_LONG: 'about-too-long',
  CHAT_ADMIN_REQUIRED: 'not-admin',
  USERS_TOO_FEW: 'users-too-few',
  USERS_TOO_MUCH: 'users-too-much',
  CHANNELS_TOO_MUCH: 'too-many-chats',
  CHANNELS_ADMIN_PUBLIC_TOO_MUCH: 'too-many-chats',
  USER_RESTRICTED: 'restricted',
  USER_PRIVACY_RESTRICTED: 'privacy',
  PHOTO_INVALID: 'photo-invalid',
  PHOTO_EXT_INVALID: 'photo-invalid',
  IMAGE_PROCESS_FAILED: 'photo-invalid',
};

const failure = (error) => {
  const text = String(error?.errorMessage ?? error?.message ?? '');
  const [, code = 'failed'] =
    Object.entries(CODES).find(([name]) => text.includes(name)) ?? [];
  return { ok: false, error: code, code };
};

const bad = (code) => ({ ok: false, error: code, code });

const CHAT = /^-\d{1,20}$/;
const textOf = (value) => String(value?.value ?? value);
const nameOf = (user) =>
  [user.firstName, user.lastName].filter(Boolean).join(' ') ||
  user.username ||
  textOf(user.id);

// A title as Telegram takes it: trimmed, one to 128 characters.
const titleOf = (value) => Array.from(String(value ?? '').trim());

const chatOf = (answer) => (answer?.chats ?? []).find(Boolean) ?? null;

// The chat a creation made: remembered, and its address.
const created = async (env, answer, { title, isChannel }) => {
  const chat = chatOf(answer);
  if (!chat) {
    return bad('failed');
  }
  const id = markedId(chat);
  await Promise.resolve(
    env.peers?.remember?.(id, chat, { title, isGroup: !isChannel, isChannel })
  ).catch(() => {});
  return { ok: true, chat: id, title };
};

const createContacts = (env, userClient, known) => async () =>
  connected(env, userClient, failure, async (c) => {
    const answer = await runIn(env, 'contacts:list', () =>
      c.client.invoke(new c.Api.contacts.GetContacts({ hash: c.zero }))
    );
    const users = (answer?.users ?? []).filter(
      (u) => u && !u.self && !u.bot && !u.deleted
    );
    for (const user of users) {
      known.set(textOf(user.id), user);
    }
    return {
      ok: true,
      contacts: users
        .map((u) => ({
          id: textOf(u.id),
          name: nameOf(u),
          username: u.username ?? null,
          // The Contacts window (R-Y189): number and last seen.
          phone: u.phone ? String(u.phone) : null,
          ...statusOf(u.status),
        }))
        .sort((a, b) => a.name.localeCompare(b.name)),
    };
  });

// What a group's creation is asked with, or the code that refuses it.
const groupRequest = (request) => {
  const title = titleOf(request.title);
  const ids = [...new Set((request.users ?? []).map(String))];
  if (title.length === 0 || title.length > MAX_TITLE) {
    return bad(title.length === 0 ? 'title-empty' : 'title-too-long');
  }
  if (ids.length === 0 || ids.length > MAX_MEMBERS) {
    return bad(ids.length === 0 ? 'users-too-few' : 'users-too-much');
  }
  return { ok: true, title: title.join(''), ids };
};

const createGroupMaker =
  (env, { userClient, apply }, known) =>
  async (request = {}) => {
    const asked = groupRequest(request);
    if (!asked.ok) {
      return asked;
    }
    return connected(env, userClient, failure, async (c) => {
      if (asked.ids.some((id) => !known.has(id))) {
        await createContacts(env, userClient, known)();
      }
      if (asked.ids.some((id) => !known.has(id))) {
        return bad('users-unknown');
      }
      const answer = await runIn(env, 'chat:create', () =>
        c.client.invoke(
          new c.Api.messages.CreateChat({
            title: asked.title,
            users: asked.ids.map(
              (id) =>
                new c.Api.InputUser({
                  userId: known.get(id).id,
                  accessHash: known.get(id).accessHash ?? c.zero,
                })
            ),
          })
        )
      );
      const updates = answer?.updates ?? answer;
      if (updates && typeof updates === 'object') {
        await apply(c.client, updates);
      }
      return await created(env, updates, {
        title: asked.title,
        isChannel: false,
      });
    });
  };

const createChannelMaker =
  (env, { userClient, apply }) =>
  async (request = {}) => {
    const title = titleOf(request.title);
    const about = String(request.about ?? '');
    if (title.length === 0 || title.length > MAX_TITLE) {
      return bad(title.length === 0 ? 'title-empty' : 'title-too-long');
    }
    if (Array.from(about).length > MAX_ABOUT) {
      return bad('about-too-long');
    }
    return connected(env, userClient, failure, async (c) => {
      const answer = await runIn(env, 'chat:create', () =>
        c.client.invoke(
          new c.Api.channels.CreateChannel({
            broadcast: true,
            title: title.join(''),
            about,
          })
        )
      );
      if (answer && typeof answer === 'object') {
        await apply(c.client, answer);
      }
      return await created(env, answer, {
        title: title.join(''),
        isChannel: true,
      });
    });
  };

// One step of an edit: Telegram saying nothing changed is no failure.
const step = async (use) => {
  try {
    return await use();
  } catch (error) {
    if (!String(error?.errorMessage ?? '').includes('CHAT_NOT_MODIFIED')) {
      throw error;
    }
    return null;
  }
};

// The page's upload sent to Telegram: its InputFile, or null (R-Y136
// sends a profile photo the same way).
export const uploadedFile = async (c, uploads, token) => {
  const entry = uploads?.uploadOf?.(token);
  if (!entry?.path) {
    return null;
  }
  const telegram = await c.env.importer();
  const CustomFile =
    telegram.client?.uploads?.CustomFile ?? telegram.CustomFile;
  return c.client.uploadFile({
    file: new CustomFile(entry.name, entry.size, entry.path),
    workers: 1,
  });
};

// The photo to set: the page's upload sent to Telegram, or none.
const photoOf = async (c, uploads, wanted) => {
  if (wanted === 'remove') {
    return new c.Api.InputChatPhotoEmpty();
  }
  const file = await uploadedFile(c, uploads, wanted);
  return file ? new c.Api.InputChatUploadedPhoto({ file }) : null;
};

const editRequests = (c, { chat, peer, title, about, photo }) => {
  const channel = chat.startsWith('-100');
  const chatId = c.helpers.returnBigInt(chat.slice(1));
  const requests = [];
  if (title !== undefined) {
    requests.push(
      channel
        ? new c.Api.channels.EditTitle({ channel: peer, title })
        : new c.Api.messages.EditChatTitle({ chatId, title })
    );
  }
  if (about !== undefined) {
    requests.push(new c.Api.messages.EditChatAbout({ peer, about }));
  }
  if (photo) {
    requests.push(
      channel
        ? new c.Api.channels.EditPhoto({ channel: peer, photo })
        : new c.Api.messages.EditChatPhoto({ chatId, photo })
    );
  }
  return requests;
};

// The edit asked for, or the code that refuses it.
const editRequest = (request) => {
  const chat = String(request.chat ?? '');
  const title =
    request.title === undefined ? undefined : titleOf(request.title);
  const about = request.about === undefined ? undefined : String(request.about);
  if (!CHAT.test(chat)) {
    return bad('failed');
  }
  if (title && (title.length === 0 || title.length > MAX_TITLE)) {
    return bad(title.length === 0 ? 'title-empty' : 'title-too-long');
  }
  if (about !== undefined && Array.from(about).length > MAX_ABOUT) {
    return bad('about-too-long');
  }
  return {
    ok: true,
    chat,
    title: title?.join(''),
    about,
    wanted: request.photo === undefined ? null : String(request.photo),
  };
};

const createEditor =
  (env, { userClient, apply, uploads }) =>
  async (request = {}) => {
    const asked = editRequest(request);
    if (!asked.ok) {
      return asked;
    }
    const { chat, wanted } = asked;
    const c = await connect(env, userClient);
    if (!c) {
      return { ok: false, supported: false };
    }
    try {
      return await runIn(env, `chat:edit:${chat}`, () =>
        env.connection.withPeer(c.client, chat, async (peer) => {
          const photo = wanted
            ? await photoOf({ ...c, env }, uploads, wanted)
            : null;
          if (wanted && !photo) {
            return bad('photo-invalid');
          }
          for (const next of editRequests(c, { ...asked, peer, photo })) {
            const answer = await step(() => c.client.invoke(next));
            if (answer && typeof answer === 'object') {
              await apply(c.client, answer);
            }
          }
          return { ok: true };
        })
      );
    } catch (error) {
      return failure(error);
    } finally {
      if (wanted && wanted !== 'remove') {
        await uploads?.dropUpload?.(wanted);
      }
    }
  };

/** `uploads` has the page's uploads (`uploadOf`, `dropUpload`). */
export const createChatEdit = (env, context) => {
  const known = new Map();
  return {
    chatContacts: createContacts(env, context.userClient, known),
    createGroup: createGroupMaker(env, context, known),
    createChannel: createChannelMaker(env, context),
    editChatInfo: createEditor(env, context),
  };
};

/**
 * Chat metadata for the sidebar and header (R-Y36): member count, online
 * count, about text, username and whether the peer has a profile photo.
 *   GET /api/telegram/chat-info?chat=<id>
 *   → { chat, kind, title, members, online, username, about, photo,
 *       pinned (the newest pinned message's id), broadcast?, bot?,
 *       lastSeen?, commonChats? (a person: groups in common) }
 *
 * Fetched through the account's queue at `view` priority and cached in
 * memory for 60 s (online counts change, so longer is wrong). The three
 * chat kinds each need their own Telegram call:
 *   - channel/supergroup (-100N): channels.GetFullChannel + GetOnlines
 *   - basic group (-N):           messages.GetFullChat  + GetOnlines
 *   - user (positive id):         users.GetFullUser
 * Secrets are never logged; only the error code on failure.
 */

import { importTelegram } from './telegram-layer.js';
import { wallpaperPage } from './telegram-wallpapers.js';
import { themeOf } from './telegram-chat-themes.js';
import { collectibleOf, usernamesOf } from './telegram-usernames.js';
import { canReactIn, reactionsOf } from './telegram-chat-reactions.js';
import { settingsInfo } from './telegram-chat-settings.js';
import { birthdayOf, colorOf } from './telegram-profile-extras.js';
import { monoforumInfo } from './telegram-channel-dm-shape.js';
import { groupStickersInfo } from './telegram-group-extras.js';
import { statusOf as emojiStatusOf } from './telegram-emoji-status.js';
import { noteOf } from './telegram-contact-extras.js';
import { ALL_ADMIN_RIGHTS } from './telegram-admin-rights.js';

const CHAT = /^-?\d{1,20}$/;
const CACHE_TTL_MS = 60_000;

const isChannel = (chat) => chat.startsWith('-100');
const isGroup = (chat) => !isChannel(chat) && chat.startsWith('-');

// Parse UserStatus into { online, lastSeen? }.
export const statusOf = (status) => {
  const cn = status?.className;
  if (cn === 'UserStatusOnline') {
    return { online: true };
  }
  if (cn === 'UserStatusOffline') {
    return {
      online: false,
      lastSeen: new Date(Number(status.wasOnline) * 1000).toISOString(),
    };
  }
  if (cn === 'UserStatusRecently') {
    return { online: false, lastSeen: 'recently' };
  }
  if (cn === 'UserStatusLastWeek') {
    return { online: false, lastSeen: 'week' };
  }
  if (cn === 'UserStatusLastMonth') {
    return { online: false, lastSeen: 'month' };
  }
  return { online: false };
};

const hasPhoto = (photo) =>
  Boolean(
    photo &&
    photo.className !== 'ChatPhotoEmpty' &&
    photo.className !== 'UserProfilePhotoEmpty'
  );

// "Do not translate this chat" is on (R-Y209).
const translationsOf = (full) =>
  full?.translationsDisabled ? { translationsDisabled: true } : {};

// Online count for a peer — 0 on any failure (not critical).
const getOnlines = async (client, Api, inputPeer) => {
  try {
    const r = await client.invoke(
      new Api.messages.GetOnlines({ peer: inputPeer })
    );
    return r?.onlines ?? 0;
  } catch {
    return 0;
  }
};

/**
 * Whether the user may pin messages in a group or channel, from its
 * entity, as Telegram's apps decide: its creator always; in a channel an
 * admin who may edit messages; in a group an admin who may pin, or
 * anyone when neither the group nor the user's own restrictions forbid it.
 */
export const canPinIn = (entity = {}) => {
  if (entity.creator) {
    return true;
  }
  if (entity.broadcast) {
    return Boolean(entity.adminRights?.editMessages);
  }
  if (entity.adminRights?.pinMessages) {
    return true;
  }
  return !(
    entity.bannedRights?.pinMessages || entity.defaultBannedRights?.pinMessages
  );
};

// Whether the user may see and replace the chat's invite link: its
// creator, or an admin with the right to invite (R-Y123).
export const canInviteIn = (entity = {}) =>
  Boolean(entity.creator || entity.adminRights?.inviteUsers);

// Whether the user may change the chat's name, description and photo: its
// creator, an admin with the right to change info, or, in a group, a member
// whom neither the group's rights nor their own restrict (R-Y129).
export const canEditIn = (entity = {}) =>
  Boolean(entity.creator || entity.adminRights?.changeInfo) ||
  (!entity.broadcast &&
    !entity.left &&
    !entity.deactivated &&
    Boolean(entity.defaultBannedRights) &&
    !entity.defaultBannedRights.changeInfo &&
    !entity.bannedRights?.changeInfo);

// Whether the user may ban people and so set the group's permissions: its
// creator, or an admin with the right to ban users (R-Y133).
export const canBanIn = (entity = {}) =>
  Boolean(entity.creator || entity.adminRights?.banUsers);

// What the user may do about other people's messages and about who owns
// the chat (R-Y200): delete them (creator, or an admin who may delete
// messages), own the chat (the creator: transfer it, and convert a
// supergroup to a broadcast group).
export const moderationOf = (entity = {}) => ({
  canDeleteMessages: Boolean(
    entity.creator || entity.adminRights?.deleteMessages
  ),
  owner: Boolean(entity.creator),
  canConvertGiga: Boolean(
    entity.creator && entity.megagroup && !entity.gigagroup
  ),
  gigagroup: Boolean(entity.gigagroup),
});

// Whether the user may set the chat's auto-delete timer (R-Y143): its
// creator, or an admin with the right to delete messages.
export const canSetTtlIn = (entity = {}) =>
  Boolean(entity.creator || entity.adminRights?.deleteMessages);

// The auto-delete period a full chat carries, in seconds, or 0 (off).
const ttlOf = (full) => Number(full?.ttlPeriod) || 0;

// Which reactions a group or channel allows, and whether the user may
// change that (R-Y160).
const reactionsInfo = (entity, full) => ({
  reactions: reactionsOf(full),
  canSetReactions: canReactIn(entity),
});

// The chat's own wallpaper, when it has one (R-Y155).
const wallpaperOf = (full) => {
  const wallpaper = wallpaperPage(full?.wallpaper);
  return wallpaper ? { wallpaper } : {};
};

// A channel's several usernames, for the user who owns it (R-Y170).
const usernamesInfo = (entity) => {
  const usernames = usernamesOf(entity.usernames);
  return entity.creator && usernames.length > 0
    ? { usernames, canEditUsernames: true }
    : {};
};

// A channel's name colour, profile colour and emoji status, for those who
// may change them (R-Y216): the creator, or an admin with the change-info right.
const lookInfo = (entity) =>
  entity.creator || entity.adminRights?.changeInfo
    ? {
        canAppearance: true,
        look: {
          color: colorOf(entity.color),
          profileColor: colorOf(entity.profileColor),
          status: emojiStatusOf(entity.emojiStatus),
        },
      }
    : {};

// What the user may do with administrators and the history new members see
// (R-Y204): their own rights (the creator has all), who may add admins, and
// whether the history is hidden from new members.
const adminInfo = (entity, full, kind) => ({
  creator: Boolean(entity.creator),
  myRights: Object.fromEntries(
    ALL_ADMIN_RIGHTS.map((key) => [key, Boolean(entity.adminRights?.[key])])
  ),
  canAddAdmins: Boolean(entity.creator || entity.adminRights?.addAdmins),
  canToggleHistory:
    kind === 'channel' &&
    Boolean(entity.creator || entity.adminRights?.changeInfo),
  historyHidden: Boolean(full?.hiddenPrehistory),
});

// The primary invite link the full chat carries, for those who may see it.
const inviteOf = (entity, full) =>
  canInviteIn(entity) && typeof full.exportedInvite?.link === 'string'
    ? { canInvite: true, inviteLink: full.exportedInvite.link }
    : { canInvite: canInviteIn(entity) };

/**
 * What the user may do with a forum's topics (R-Y153), as Desktop
 * decides: manage them (creator, or an admin who may manage topics),
 * create one (that, or anyone neither the group's nor their own
 * restrictions forbid), delete them (creator, or an admin who may delete
 * messages).
 */
export const topicRightsIn = (entity = {}) => {
  const manage = Boolean(entity.creator || entity.adminRights?.manageTopics);
  return {
    manage,
    create:
      manage ||
      (!entity.left &&
        !entity.bannedRights?.manageTopics &&
        !entity.defaultBannedRights?.manageTopics),
    delete: Boolean(entity.creator || entity.adminRights?.deleteMessages),
  };
};

// People waiting to be let in, for those who may invite (R-Y152): how
// many, and the latest few as { id, name }.
const requestsOf = (entity, full, users = []) => {
  const pending = Number(full?.requestsPending ?? 0);
  if (!canInviteIn(entity) || pending <= 0) {
    return {};
  }
  const byId = new Map(users.map((u) => [String(u.id?.value ?? u.id), u]));
  const recentRequesters = (full.recentRequesters ?? []).map((raw) => {
    const id = String(raw?.value ?? raw);
    return { id, name: nameOf(byId.get(id) ?? {}) || id };
  });
  return { requestsPending: pending, recentRequesters };
};

// The channel's direct messages (R-Y191): its linked monoforum, whose peer
// is kept so the chat can be opened and written to.
const monoforumOf = async (entity, chats, peers) => {
  const monoforum = monoforumInfo(entity, chats);
  if (!monoforum) {
    return {};
  }
  const chat = chats.find(
    (c) => String(c?.id?.value ?? c?.id) === monoforum.id.slice(4)
  );
  await Promise.resolve(
    chat
      ? peers?.remember?.(monoforum.id, chat, {
          title: monoforum.title,
          isChannel: true,
        })
      : null
  ).catch(() => {});
  return { monoforum };
};

const fetchChannel = async (client, Api, inputPeer, peers) => {
  const result = await client.invoke(
    new Api.channels.GetFullChannel({ channel: inputPeer })
  );
  const full = result.fullChat;
  // The channel itself: with a monoforum the answer lists two chats.
  const entity =
    (result.chats ?? []).find(
      (c) => c && full?.id !== undefined && String(c.id) === String(full.id)
    ) ??
    (result.chats ?? []).find(Boolean) ??
    {};
  const online = await getOnlines(client, Api, inputPeer);
  return {
    kind: 'channel',
    title: entity.title ?? null,
    members: full.participantsCount ?? null,
    online,
    username: entity.username ?? null,
    about: full.about ?? null,
    photo: hasPhoto(entity.photo),
    pinned: full.pinnedMsgId ?? null,
    canPin: canPinIn(entity),
    broadcast: Boolean(entity.broadcast),
    forum: Boolean(entity.forum),
    ...translationsOf(full),
    // "View as messages" is on for this forum (R-Y171).
    forumAsMessages: Boolean(full.viewForumAsMessages),
    topics: topicRightsIn(entity),
    canToggleForum: Boolean(entity.creator) && !entity.broadcast,
    // Statistics for admins of channels and big supergroups (R-Y167).
    canViewStats: Boolean(full.canViewStats),
    // The Stars revenue section of the statistics (R-Y195).
    canViewStarsRevenue: Boolean(full.canViewStarsRevenue),
    canEdit: canEditIn(entity),
    canBan: canBanIn(entity),
    ...moderationOf(entity),
    ttlPeriod: ttlOf(full),
    canSetTtl: canSetTtlIn(entity),
    ...reactionsInfo(entity, full),
    // Sign messages, Discussion, Join to send… (R-Y165).
    settings: settingsInfo(entity, full, result.chats ?? []),
    ...wallpaperOf(full),
    ...usernamesInfo(entity),
    ...collectibleOf(entity),
    ...lookInfo(entity),
    ...inviteOf(entity, full),
    // The group's sticker set and emoji pack (R-Y211).
    ...groupStickersInfo(entity, full),
    ...adminInfo(entity, full, 'channel'),
    ...requestsOf(entity, full, result.users),
    ...(await monoforumOf(entity, result.chats ?? [], peers)),
  };
};

const fetchGroup = async (client, Api, helpers, inputPeer, chat) => {
  // A basic group's id is its marked id without the minus.
  const chatId = helpers.returnBigInt(chat.slice(1));
  const result = await client.invoke(new Api.messages.GetFullChat({ chatId }));
  const full = result.fullChat;
  const entity = (result.chats ?? []).find(Boolean) ?? {};
  const parts = full.participants?.participants ?? [];
  const online = await getOnlines(client, Api, inputPeer);
  return {
    kind: 'group',
    title: entity.title ?? null,
    members: parts.length,
    online,
    username: null,
    about: full.about ?? null,
    photo: hasPhoto(entity.photo),
    pinned: full.pinnedMsgId ?? null,
    canPin: canPinIn(entity),
    canEdit: canEditIn(entity),
    canBan: canBanIn(entity),
    ...moderationOf(entity),
    ttlPeriod: ttlOf(full),
    canSetTtl: canSetTtlIn(entity),
    ...reactionsInfo(entity, full),
    settings: settingsInfo(entity, full, result.chats ?? []),
    ...inviteOf(entity, full),
    ...adminInfo(entity, full, 'group'),
    ...translationsOf(full),
    ...requestsOf(entity, full, result.users),
  };
};

// A person's InputUser: from their stored peer, else by id alone.
const inputUserOf = (Api, helpers, storedPeer, chat) =>
  storedPeer?.userId !== undefined
    ? new Api.InputUser({
        userId: storedPeer.userId,
        accessHash: storedPeer.accessHash,
      })
    : new Api.InputUser({
        userId: helpers.returnBigInt(String(chat)),
        accessHash: helpers.returnBigInt('0'),
      });

const nameOf = (user) =>
  [user.firstName, user.lastName].filter(Boolean).join(' ') ||
  user.username ||
  null;

// A person's birthday, profile colour and whether they show a personal
// channel (R-Y178); the channel's card is read when the profile opens.
const extrasOf = (user, full) => ({
  ...(birthdayOf(full.birthday) ? { birthday: birthdayOf(full.birthday) } : {}),
  ...(colorOf(user.profileColor)
    ? { profileColor: colorOf(user.profileColor) }
    : {}),
  ...(full.personalChannelId ? { personalChannel: true } : {}),
});

// A bot the user owns: its Stars revenue (R-Y195).
const botRevenueOf = (user, full) =>
  user.bot && full.canViewRevenue ? { canViewStarsRevenue: true } : {};

const contactReach = (user) => ({
  username: user.username ?? null,
  phone: user.phone ?? null,
});

const fetchUser = async (client, Api, helpers, inputPeer, peers, chat) => {
  const storedPeer = inputPeer ?? (await peers.input(chat));
  const id = inputUserOf(Api, helpers, storedPeer, chat);
  const result = await client.invoke(new Api.users.GetFullUser({ id }));
  const full = result.fullUser ?? result;
  const user = (result.users ?? []).find(Boolean) ?? {};
  const { online = false, lastSeen } = statusOf(user.status);
  return {
    kind: 'user',
    title: nameOf(user),
    members: 1,
    online,
    ...contactReach(user),
    about: full.about ?? null,
    photo: hasPhoto(user.photo),
    pinned: full.pinnedMsgId ?? null,
    // Blocked by us, and in our contacts (R-Y128).
    blocked: Boolean(full.blocked),
    contact: Boolean(user.contact),
    // The auto-delete timer; anyone may set it in a chat with a person
    // (not in Saved Messages, the chat with oneself) (R-Y143).
    ttlPeriod: ttlOf(full),
    canSetTtl: !user.self,
    // Groups both belong to (R-Y158); the list is a separate call.
    commonChats: user.self ? 0 : Number(full.commonChatsCount) || 0,
    ...wallpaperOf(full),
    ...extrasOf(user, full),
    // Collectible usernames and number, opened in Fragment's card (R-Y194).
    ...collectibleOf(user),
    // The theme of this chat, by its emoticon (R-Y170).
    ...(themeOf(full) ? { theme: themeOf(full) } : {}),
    ...translationsOf(full),
    // The private note and a personal photo of a contact (R-Y217).
    ...noteOf(full),
    ...(user.self ? { self: true } : {}),
    ...(user.bot ? { bot: true } : {}),
    ...botRevenueOf(user, full),
    ...(lastSeen !== undefined ? { lastSeen } : {}),
  };
};

/**
 * `read({ chat })` → the chat's metadata, or null on failure.
 * Results are cached in memory for 60 s. `client()` is the connected
 * GramJS client (or null), `peers` the account's peer store.
 */
export const createChatInfoReader = ({
  queue,
  client: clientOf,
  peers,
  importer = importTelegram,
  log = () => {},
}) => {
  const cache = new Map(); // chat → { data, at }

  const fetch = async (chat, client, Api, helpers, inputPeer) => {
    if (isChannel(chat)) {
      return fetchChannel(client, Api, inputPeer, peers);
    }
    if (isGroup(chat)) {
      return fetchGroup(client, Api, helpers, inputPeer, chat);
    }
    return fetchUser(client, Api, helpers, inputPeer, peers, chat);
  };

  // Kept for a minute: read again only after.
  const fresh = (target) => {
    const hit = cache.get(target);
    if (!hit || Date.now() - hit.at >= CACHE_TTL_MS) {
      return null;
    }
    log({
      event: 'telegram_chat_info',
      kind: hit.data.kind,
      cached: true,
      duration_ms: 0,
    });
    return hit.data;
  };

  // A chat the account holds has its stored peer; else GramJS may
  // know it from what it has seen.
  const inputOf = async (target, client, helpers) =>
    (await peers.input(target)) ??
    (await Promise.resolve()
      .then(() => client.getInputEntity?.(helpers.returnBigInt(target)))
      .catch(() => null)) ??
    null;

  const read = async ({ chat } = {}) => {
    const target = String(chat ?? '');
    if (!CHAT.test(target)) {
      return null;
    }

    const hit = fresh(target);
    if (hit) {
      return hit;
    }
    const client = await clientOf();
    if (!client) {
      return null;
    }
    const { Api, helpers } = await importer();
    const inputPeer = await inputOf(target, client, helpers);
    const started = Date.now();
    try {
      const data = await queue.run(`chat-info:${target}`, 'view', () =>
        fetch(target, client, Api, helpers, inputPeer)
      );
      cache.set(target, { data: { chat: target, ...data }, at: Date.now() });
      log({
        event: 'telegram_chat_info',
        kind: data.kind,
        cached: false,
        duration_ms: Date.now() - started,
      });
      return cache.get(target).data;
    } catch (error) {
      log({
        level: 'warn',
        event: 'telegram_chat_info_failed',
        code: error.errorMessage ?? error.code ?? null,
        duration_ms: Date.now() - started,
      });
      return null;
    }
  };

  return { read };
};

/**
 * Which reactions a group or channel allows, as Telegram Desktop's
 * "Reactions" in Manage group / channel (R-Y160; learned, never copied):
 * - `availableReactions()` — the emoji reactions Telegram offers
 *   (messages.getAvailableReactions, the inactive ones left out), kept in
 *   memory for ten minutes → `{ ok, reactions: [{ emoji, title, premium }] }`;
 * - `chatReactionsSet({ chat, mode, reactions? })` — the chat's setting
 *   (messages.setChatAvailableReactions): `mode` is 'all', 'some' (with
 *   1 to 100 emoji of at most 16 characters) or 'none' → `{ ok }`.
 * `reactionsOf(full)` reads the setting off a ChatFull / ChannelFull
 * (for the chat info) and `canReactIn(entity)` says who may change it:
 * the chat's creator, or an admin with the right to change info.
 * Telegram's errors become codes the page shows as text.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';

const CODES = {
  CHAT_ADMIN_REQUIRED: 'not-admin',
  CHAT_NOT_MODIFIED: 'not-modified',
  REACTION_INVALID: 'reaction-invalid',
  REACTIONS_TOO_MANY: 'reaction-invalid',
  PEER_ID_INVALID: 'no-access',
  CHAT_ID_INVALID: 'no-access',
  CHANNEL_PRIVATE: 'no-access',
  CHANNEL_INVALID: 'no-access',
};

const asFailure = failureOf(CODES);
// Nothing to change is no failure.
const failure = (error) => {
  const out = asFailure(error);
  return out.code === 'not-modified' ? { ok: true } : out;
};
const bad = { ok: false, error: 'bad request', code: 'bad-request' };

export const MODES = Object.freeze(['all', 'some', 'none']);
export const MAX_REACTIONS = 100;
export const MAX_EMOJI_LENGTH = 16;
const CHAT = /^-\d{1,20}$/;
const KEEP_MS = 10 * 60_000;

/** Whether the user may change the chat's reactions (not a person's chat). */
export const canReactIn = (entity = {}) =>
  Boolean(entity.creator || entity.adminRights?.changeInfo);

/**
 * The setting a full chat carries: `{ mode: 'all' }`, `{ mode: 'none' }` or
 * `{ mode: 'some', emojis }`; a chat that says nothing allows all.
 */
export const reactionsOf = (full) => {
  const set = full?.availableReactions;
  if (set?.className === 'ChatReactionsNone') {
    return { mode: 'none' };
  }
  if (set?.className === 'ChatReactionsSome') {
    const emojis = (set.reactions ?? [])
      .filter((r) => typeof r?.emoticon === 'string')
      .map((r) => r.emoticon);
    return { mode: 'some', emojis };
  }
  return { mode: 'all' };
};

/** Whether `emojis` is 1 to 100 distinct short strings. */
export const validEmojis = (emojis) =>
  Array.isArray(emojis) &&
  emojis.length >= 1 &&
  emojis.length <= MAX_REACTIONS &&
  new Set(emojis).size === emojis.length &&
  emojis.every(
    (e) => typeof e === 'string' && e && e.length <= MAX_EMOJI_LENGTH
  );

/** Whether a body is a valid `{ chat, mode, reactions? }`. */
export const validSetting = (body = {}) =>
  CHAT.test(String(body.chat ?? '')) &&
  MODES.includes(body.mode) &&
  (body.mode === 'some'
    ? validEmojis(body.reactions)
    : body.reactions === undefined);

const listOf = (answer) =>
  (answer?.reactions ?? [])
    .filter((r) => !r.inactive && typeof r.reaction === 'string')
    .map((r) => ({
      emoji: r.reaction,
      title: String(r.title ?? ''),
      premium: Boolean(r.premium),
    }));

const createAvailable = (env, userClient, now) => {
  let kept = null; // { at, reactions }
  return async () => {
    if (kept && now() - kept.at < KEEP_MS) {
      return { ok: true, reactions: kept.reactions };
    }
    return connected(env, userClient, failure, async (c) => {
      const answer = await runIn(env, 'chat-reactions:available', () =>
        c.client.invoke(new c.Api.messages.GetAvailableReactions({ hash: 0 }))
      );
      const reactions = listOf(answer);
      kept = { at: now(), reactions };
      return { ok: true, reactions };
    });
  };
};

const chatReactionsOf = (c, { mode, reactions }) => {
  if (mode === 'none') {
    return new c.Api.ChatReactionsNone();
  }
  if (mode === 'all') {
    return new c.Api.ChatReactionsAll({ allowCustom: false });
  }
  return new c.Api.ChatReactionsSome({
    reactions: reactions.map(
      (emoticon) => new c.Api.ReactionEmoji({ emoticon })
    ),
  });
};

const createSet = (env, userClient) => async (body) => {
  if (!validSetting(body)) {
    return bad;
  }
  return connected(env, userClient, failure, async (c) => {
    await runIn(env, `chat-reactions:set:${body.chat}`, () =>
      env.connection.withPeer(c.client, body.chat, (peer) =>
        c.client.invoke(
          new c.Api.messages.SetChatAvailableReactions({
            peer,
            availableReactions: chatReactionsOf(c, body),
          })
        )
      )
    );
    return { ok: true };
  });
};

export const createChatReactions = (env, context) => ({
  availableReactions: createAvailable(
    env,
    context.userClient,
    env.now ?? Date.now
  ),
  chatReactionsSet: createSet(env, context.userClient),
});

/**
 * Clearing, deleting and leaving a chat, as Telegram's apps do it
 * (R-Y100; Telegram Desktop's "Clear history", "Delete chat" and
 * "Leave", learned, never copied):
 *
 * - `clear` — every message of the chat deleted, the chat kept:
 *   messages.deleteHistory with just_clear (a person or a basic group;
 *   `revoke` deletes them for the other side too), channels.deleteHistory
 *   for a supergroup (for the user only).
 * - `delete` — a personal chat's every message deleted and the chat
 *   gone from the list (`revoke`: for the other person too).
 * - `leave` — a basic group: the user leaves it (messages.deleteChatUser)
 *   and its history goes; a supergroup or channel:
 *   channels.leaveChannel.
 * - `destroy` — the owner deletes a group or channel for everyone
 *   (channels.deleteChannel, messages.deleteChat; R-Y216), no undo; the
 *   chat leaves the list like a left one.
 *
 * Telegram deletes history a part at a time (`offset` says there is
 * more); it is asked again until done. The chat's stored messages are
 * then marked deleted, so the messages leave the screens at once; the
 * chat goes with them after `delete` and `leave`, but a cleared chat
 * stays in the list, empty, as Telegram keeps it: its read link holds
 * when it was cleared and its name and type, as the list is built from
 * messages. The update counters move with Telegram's answers.
 */

import { markDeleted as tombstone } from '../storage/soft-delete.js';

const SOURCE = 'telegram';
export const REMOVAL_ACTIONS = Object.freeze([
  'clear',
  'delete',
  'leave',
  'destroy',
]);
const MAX_ROUNDS = 100;

const kindOf = (chat) => {
  const id = String(chat);
  if (id.startsWith('-100')) {
    return 'channel';
  }
  return id.startsWith('-') ? 'group' : 'personal';
};

/** Whether `action` is one Telegram has for chat `chat`. */
export const removalAllowed = (chat, action) => {
  const kind = kindOf(chat);
  if (action === 'delete') {
    return kind === 'personal';
  }
  if (action === 'leave' || action === 'destroy') {
    return kind !== 'personal';
  }
  return action === 'clear';
};

/**
 * `env` is the account's; `userClient()` the connected user client or
 * null; `apply(client, result)` takes Telegram's answer through the
 * live handler.
 */
export const createChatRemoval = (env, { userClient, apply }) => {
  // messages.deleteHistory until Telegram says nothing is left.
  const deleteHistory = async (client, Api, peer, { justClear, revoke }) => {
    for (let round = 0; round < MAX_ROUNDS; round += 1) {
      const affected = await client.invoke(
        new Api.messages.DeleteHistory({
          peer,
          maxId: 0,
          justClear,
          revoke,
        })
      );
      env.catchUp?.observeResult(affected);
      if (!(Number(affected?.offset) > 0)) {
        return;
      }
    }
  };

  // The newest message the chat is known to have.
  const newestId = async (chat) => {
    const read = (await env.store.get(`read:${SOURCE}:${chat}`)) ?? {};
    const prefix = `msg:${SOURCE}:${chat}:`;
    const stored = await env.store.query((link) => link.id.startsWith(prefix));
    return Math.max(
      Number(read.unreadTopId ?? 0) || 0,
      ...stored.map((link) => Number(link.id.slice(prefix.length)) || 0)
    );
  };

  const askChannel = async (client, Api, peer, { action, chat }) => {
    if (action === 'destroy') {
      return client.invoke(new Api.channels.DeleteChannel({ channel: peer }));
    }
    if (action === 'leave') {
      return client.invoke(new Api.channels.LeaveChannel({ channel: peer }));
    }
    return client.invoke(
      new Api.channels.DeleteHistory({
        channel: peer,
        maxId: await newestId(chat),
        forEveryone: false,
      })
    );
  };

  const ask = async (client, Api, peer, { action, chat, revoke }) => {
    const kind = kindOf(chat);
    if (kind === 'channel') {
      return askChannel(client, Api, peer, { action, chat });
    }
    if (kind === 'group' && action === 'destroy') {
      const { helpers } = await env.importer();
      return client.invoke(
        new Api.messages.DeleteChat({
          chatId: helpers.returnBigInt(String(chat).slice(1)),
        })
      );
    }
    if (kind === 'group' && action === 'leave') {
      const { helpers } = await env.importer();
      const left = await client.invoke(
        new Api.messages.DeleteChatUser({
          chatId: helpers.returnBigInt(String(chat).slice(1)),
          userId: new Api.InputUserSelf(),
          revokeHistory: false,
        })
      );
      await apply(client, left);
    }
    await deleteHistory(client, Api, peer, {
      justClear: action === 'clear',
      revoke: kind === 'personal' && Boolean(revoke),
    });
    return null;
  };

  // The chat's stored messages, marked deleted: off the screens at once.
  const forget = async (chat) => {
    const prefix = `msg:${SOURCE}:${chat}:`;
    const stored = await env.store.query(
      (link) => link.id.startsWith(prefix) && !link.deleted
    );
    for (const link of stored) {
      await env.store.put(
        tombstone(link, { by: 'user', reason: 'chat-removed' })
      );
    }
    return stored;
  };

  // A cleared chat is kept in the list by its read link; delete and
  // leave take that mark away, and the chat with it.
  const markCleared = async (chat, action, stored) => {
    const id = `read:${SOURCE}:${chat}`;
    const before = (await env.store.get(id)) ?? {
      id,
      tokens: ['read', SOURCE, chat],
      kind: 'read',
      source: SOURCE,
      chat,
    };
    const link = { ...before };
    for (const field of ['clearedAt', 'chatName', 'chatType']) {
      delete link[field];
    }
    if (action === 'clear') {
      const known = stored.find((m) => m.chatName || m.chatType) ?? before;
      Object.assign(link, {
        clearedAt: new Date().toISOString(),
        chatName: known.chatName,
        chatType: known.chatType,
      });
    }
    await env.store.put(link);
  };

  /** `{ chat, action, revoke? }` → `{ ok, deleted }`. */
  const removeChat = async ({ chat, action, revoke = false } = {}) => {
    const client =
      chat && REMOVAL_ACTIONS.includes(action) && removalAllowed(chat, action)
        ? await userClient()
        : null;
    if (!client) {
      return { ok: false, supported: false };
    }
    const { Api } = await env.importer();
    const target = String(chat);
    const answer = await env.connection.withPeer(client, target, (peer) =>
      ask(client, Api, peer, { action, chat: target, revoke })
    );
    if (answer && typeof answer === 'object') {
      await apply(client, answer);
    }
    const stored = await forget(target);
    await markCleared(target, action, stored);
    return { ok: true, chat: target, action, deleted: stored.length };
  };

  return { removeChat };
};

/**
 * A group's and a channel's settings in Manage group / channel (R-Y165;
 * learned, never copied), as Telegram Desktop has them:
 * - `chatSettingSet({ chat, setting, value })` — one switch, from a strict
 *   allow-list: `signatures` and `signatureProfiles`
 *   (channels.toggleSignatures), `joinToSend` (channels.toggleJoinToSend),
 *   `joinRequest` (channels.toggleJoinRequest), `hideMembers`
 *   (channels.toggleParticipantsHidden), `antiSpam` (channels.toggleAntiSpam)
 *   `autotranslation` (channels.toggleAutotranslation, the channel's owner,
 *   R-Y184) and `noForwards` (messages.toggleNoForwards; a group or a
 *   channel);
 * - `discussionGroups({ chat })` — the supergroups a channel may be linked
 *   to (channels.getGroupsForDiscussion) → `{ ok, groups: [{ id, title }] }`;
 * - `discussionSet({ chat, group })` — links the channel to a group, or
 *   unlinks it with `group: null` (channels.setDiscussionGroup).
 * `settingsInfo(entity, full, chats)` is what the chat's info carries so the
 * page knows the current values and which switches the user may use.
 * Telegram's errors become codes the page shows as words.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';

const CODES = {
  CHAT_ADMIN_REQUIRED: 'not-admin',
  CHAT_NOT_MODIFIED: 'not-modified',
  LINK_NOT_MODIFIED: 'not-modified',
  PARTICIPANTS_TOO_FEW: 'too-few',
  ANTISPAM: 'antispam-unavailable',
  BROADCAST_FORBIDDEN: 'wrong-kind',
  MEGAGROUP_PREHISTORY_HIDDEN: 'prehistory-hidden',
  BROADCAST_ID_INVALID: 'no-access',
  MEGAGROUP_ID_INVALID: 'no-access',
  CHANNEL_PRIVATE: 'no-access',
  CHANNEL_INVALID: 'no-access',
  PEER_ID_INVALID: 'no-access',
  FLOOD_WAIT: 'flood',
};

// Telegram's errors as codes, where nothing to change is no failure.
export const quietFailureOf = (codes) => {
  const asFailure = failureOf(codes);
  return (error) => {
    const out = asFailure(error);
    return out.code === 'not-modified' ? { ok: true } : out;
  };
};
const failure = quietFailureOf(CODES);
const bad = { ok: false, error: 'bad-request', code: 'bad-request' };

const CHANNEL = /^-100\d{1,20}$/;
const CHAT = /^-\d{1,20}$/;
const textOf = (value) => String(value?.value ?? value);

// Each switch the page may set: whether it needs a channel (not a basic
// group) and the request that sets it.
const SETTINGS = {
  signatures: {
    channel: true,
    ask: (c, peer, enabled) =>
      new c.Api.channels.ToggleSignatures({
        channel: peer,
        signaturesEnabled: enabled,
        profilesEnabled: false,
      }),
  },
  signatureProfiles: {
    channel: true,
    ask: (c, peer, enabled) =>
      new c.Api.channels.ToggleSignatures({
        channel: peer,
        signaturesEnabled: true,
        profilesEnabled: enabled,
      }),
  },
  joinToSend: {
    channel: true,
    ask: (c, peer, enabled) =>
      new c.Api.channels.ToggleJoinToSend({ channel: peer, enabled }),
  },
  joinRequest: {
    channel: true,
    ask: (c, peer, enabled) =>
      new c.Api.channels.ToggleJoinRequest({ channel: peer, enabled }),
  },
  hideMembers: {
    channel: true,
    ask: (c, peer, enabled) =>
      new c.Api.channels.ToggleParticipantsHidden({ channel: peer, enabled }),
  },
  antiSpam: {
    channel: true,
    ask: (c, peer, enabled) =>
      new c.Api.channels.ToggleAntiSpam({ channel: peer, enabled }),
  },
  // Translate the channel's posts for its readers (R-Y184).
  autotranslation: {
    channel: true,
    ask: (c, peer, enabled) =>
      new c.Api.channels.ToggleAutotranslation({ channel: peer, enabled }),
  },
  noForwards: {
    channel: false,
    ask: (c, peer, enabled) =>
      new c.Api.messages.ToggleNoForwards({ peer, enabled }),
  },
};
export const SETTING_KEYS = Object.freeze(Object.keys(SETTINGS));

/** Whether `body` is a valid `{ chat, setting, value }`. */
export const validSetting = (body = {}) => {
  const chat = String(body.chat ?? '');
  const spec = Object.hasOwn(SETTINGS, body.setting)
    ? SETTINGS[body.setting]
    : null;
  return Boolean(
    spec &&
    typeof body.value === 'boolean' &&
    (spec.channel ? CHANNEL.test(chat) : CHAT.test(chat))
  );
};

// The group a channel is linked to, as { id, title }, or null.
const linkedOf = (full, chats) => {
  if (full.linkedChatId === undefined || full.linkedChatId === null) {
    return null;
  }
  const id = textOf(full.linkedChatId);
  const found = chats.find((one) => one && textOf(one.id) === id);
  return { id: `-100${id}`, title: found?.title ?? '' };
};

// The switches this user may use in this chat.
const shownIn = (entity, linked, full = {}) => {
  const owner = Boolean(entity.creator);
  const admin = owner || Boolean(entity.adminRights?.changeInfo);
  const shown = [];
  if (admin && entity.broadcast) {
    shown.push('signatures', 'discussion');
  }
  if (admin && entity.megagroup) {
    if (entity.username || linked) {
      shown.push('joinToSend', 'joinRequest');
    }
    shown.push('hideMembers', 'antiSpam');
    // What a message costs: only where Telegram offers it (R-Y184).
    if (full.paidMessagesAvailable) {
      shown.push('paidMessages');
    }
  }
  if (owner) {
    shown.push('noForwards');
    if (entity.broadcast) {
      shown.push('autotranslation');
    }
  }
  return shown;
};

/**
 * What a chat's info carries about these settings: `shown`, the switches
 * this user may use (the creator or an admin who may change info; Restrict
 * saving is the creator's; Join to send and Approve new members only where
 * the group is public or linked to a channel, as Desktop shows them),
 * their current `values` and the linked discussion group.
 */
export const settingsInfo = (entity = {}, full = {}, chats = []) => {
  const linked = linkedOf(full, chats);
  return {
    shown: shownIn(entity, linked, full),
    values: {
      signatures: Boolean(entity.signatures),
      signatureProfiles: Boolean(entity.signatureProfiles),
      joinToSend: Boolean(entity.joinToSend),
      joinRequest: Boolean(entity.joinRequest),
      hideMembers: Boolean(full.participantsHidden),
      antiSpam: Boolean(full.antispam),
      noForwards: Boolean(entity.noforwards),
      autotranslation: Boolean(entity.autotranslation),
    },
    // Stars one message to the group costs its members (R-Y184).
    paidStars:
      Number(
        full.sendPaidMessagesStars?.value ?? full.sendPaidMessagesStars ?? 0
      ) || 0,
    linked,
  };
};

const createSet = (env, userClient) => async (body) => {
  if (!validSetting(body)) {
    return bad;
  }
  return connected(env, userClient, failure, async (c) => {
    await runIn(env, `chat-settings:${body.chat}`, () =>
      env.connection.withPeer(c.client, body.chat, (peer) =>
        c.client.invoke(SETTINGS[body.setting].ask(c, peer, body.value))
      )
    );
    return { ok: true };
  });
};

const createGroups =
  (env, userClient) =>
  async (body = {}) => {
    if (!CHANNEL.test(String(body.chat ?? ''))) {
      return bad;
    }
    return connected(env, userClient, failure, async (c) => {
      const answer = await runIn(env, `chat-settings:groups:${body.chat}`, () =>
        c.client.invoke(new c.Api.channels.GetGroupsForDiscussion())
      );
      const groups = (answer?.chats ?? [])
        .filter((one) => one?.id !== undefined)
        .map((one) => ({
          id: `-100${textOf(one.id)}`,
          title: one.title ?? '',
        }));
      return { ok: true, groups };
    });
  };

const createDiscussion =
  (env, userClient) =>
  async (body = {}) => {
    const chat = String(body.chat ?? '');
    const group = body.group ?? null;
    if (
      !CHANNEL.test(chat) ||
      (group !== null && !CHANNEL.test(String(group)))
    ) {
      return bad;
    }
    return connected(env, userClient, failure, async (c) => {
      await runIn(env, `chat-settings:discussion:${chat}`, () =>
        env.connection.withPeer(c.client, chat, async (broadcast) => {
          const target =
            group === null
              ? new c.Api.InputChannelEmpty()
              : await env.connection.withPeer(
                  c.client,
                  String(group),
                  async (peer) => peer
                );
          return c.client.invoke(
            new c.Api.channels.SetDiscussionGroup({ broadcast, group: target })
          );
        })
      );
      return { ok: true };
    });
  };

export const createChatSettings = (env, context) => ({
  chatSettingSet: createSet(env, context.userClient),
  discussionGroups: createGroups(env, context.userClient),
  discussionSet: createDiscussion(env, context.userClient),
});

/**
 * Chat themes, as Telegram Desktop's "Change colours" has them (R-Y170;
 * learned, never copied):
 * - `chatThemes({ fresh })` — the themes Telegram offers for chats
 *   (account.getChatThemes, asked again with the hash it gave so an
 *   unchanged list costs nothing) as `{ ok, themes: [{ emoticon, title,
 *   light, dark }] }`. `light` and `dark` are the colours of the theme's
 *   ThemeSettings for that mode (`{ base, accent, outgoing, messages }`,
 *   colour ints as Telegram has them, the page turns them into CSS), or
 *   null; a theme's wallpaper is left to the chat background code;
 * - `setChatTheme({ chat, emoticon })` — a theme of the list (emoticon ''
 *   for none) for a chat with a person (messages.setChatTheme), the one
 *   write. Only emoticons of the list are sent.
 * `themeOf(full)` is the emoticon of the theme a user's full info carries.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';

const CODES = {
  THEME_INVALID: 'invalid',
  CHAT_ID_INVALID: 'no-access',
  PEER_ID_INVALID: 'no-access',
  CHAT_WRITE_FORBIDDEN: 'no-access',
  USER_PRIVACY_RESTRICTED: 'no-access',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);

/** A private chat's id (a user, never a group or a channel). */
export const USER_CHAT = /^\d{1,20}$/;
const LIST_MS = 10 * 60_000;
const DARK_BASES = ['BaseThemeNight', 'BaseThemeTinted'];

const text = (value) =>
  value === null || value === undefined ? '' : String(value.value ?? value);

const BASES = {
  BaseThemeClassic: 'classic',
  BaseThemeDay: 'day',
  BaseThemeNight: 'night',
  BaseThemeTinted: 'tinted',
  BaseThemeArctic: 'arctic',
};

/** One ThemeSettings as `{ base, accent, outgoing, messages }`, or null. */
export const settingsPage = (settings) => {
  if (!settings || typeof settings.accentColor !== 'number') {
    return null;
  }
  const outgoing = settings.outboxAccentColor;
  return {
    base: BASES[settings.baseTheme?.className] ?? 'classic',
    accent: settings.accentColor,
    outgoing: typeof outgoing === 'number' ? outgoing : null,
    messages: (settings.messageColors ?? []).filter(
      (v) => typeof v === 'number'
    ),
  };
};

/** A Theme made for chats as the page keeps it, or null. */
export const themePage = (theme) => {
  const emoticon = String(theme?.emoticon ?? '');
  if (theme?.className !== 'Theme' || !emoticon || emoticon.length > 32) {
    return null;
  }
  const all = theme.settings ?? [];
  const dark = all.find((s) => DARK_BASES.includes(s.baseTheme?.className));
  const light = all.find((s) => s !== dark);
  return {
    emoticon,
    title: String(theme.title ?? ''),
    light: settingsPage(light),
    dark: settingsPage(dark),
  };
};

/** The emoticon of the theme a user's full info carries, or ''. */
export const themeOf = (full) =>
  full?.theme?.className === 'ChatTheme' ? String(full.theme.emoticon) : '';

export const createChatThemes = (env, { userClient }) => {
  let kept = null; // { at, hash, answer }

  const chatThemes = async ({ fresh = false } = {}) => {
    if (!fresh && kept && Date.now() - kept.at < LIST_MS) {
      return kept.answer;
    }
    return connected(env, userClient, failure, async (c) => {
      const got = await runIn(env, 'chat-themes:list', () =>
        c.client.invoke(
          new c.Api.account.GetChatThemes({
            hash: kept ? c.helpers.returnBigInt(kept.hash) : c.zero,
          })
        )
      );
      if (got?.className === 'account.ThemesNotModified' && kept) {
        kept.at = Date.now();
        return kept.answer;
      }
      const themes = (got?.themes ?? []).map(themePage).filter(Boolean);
      const answer = { ok: true, themes };
      kept = { at: Date.now(), hash: text(got?.hash) || '0', answer };
      return answer;
    });
  };

  // The one write: a theme of the list (or none) for a chat with a person.
  const setChatTheme = async ({ chat, emoticon = '' } = {}) => {
    const wanted = String(emoticon ?? '');
    if (!USER_CHAT.test(String(chat ?? ''))) {
      return { ok: false, error: 'bad chat', code: 'bad-request' };
    }
    if (wanted !== '') {
      const list = await chatThemes();
      if (!list.ok || !list.themes.some((th) => th.emoticon === wanted)) {
        return { ok: false, error: 'unknown theme', code: 'invalid' };
      }
    }
    return connected(env, userClient, failure, async (c) => {
      await runIn(env, `chat-theme-set:${chat}`, () =>
        env.connection.withPeer(c.client, String(chat), (peer) =>
          c.client.invoke(
            new c.Api.messages.SetChatTheme({
              peer,
              theme:
                wanted === ''
                  ? new c.Api.InputChatThemeEmpty()
                  : new c.Api.InputChatTheme({ emoticon: wanted }),
            })
          )
        )
      );
      return { ok: true };
    });
  };

  return { chatThemes, setChatTheme };
};

// Normal Telegram clients ignore tg://user?id (a Bot API abstraction).
// Use documented username/phone/message links; numeric-only peers use Web A's
// signed-in chat route instead of launching a native app without a destination.
// References: core.telegram.org/api/links; Ajaxy/telegram-tt src/util/routing.ts.
const resolvedLink = (handle, number, native) =>
  /^[a-zA-Z][a-zA-Z0-9_]{3,31}$/.test(handle)
    ? native
      ? `tg://resolve?domain=${handle}`
      : `https://t.me/${handle}`
    : /^[1-9]\d{6,14}$/.test(number)
      ? native
        ? `tg://resolve?phone=${number}`
        : `https://t.me/+${number}`
      : null;

export const telegramChatUrl = ({
  source,
  chat,
  username,
  phone,
  lastId,
  text,
  native = false,
} = {}) => {
  if (source !== 'telegram' || !/^-?[1-9]\d*$/.test(String(chat))) {
    return null;
  }
  const handle = String(username ?? '').replace(/^@/, '');
  const number = String(phone ?? '').replace(/[\s()+-]/g, '');
  const resolved = resolvedLink(handle, number, native);
  if (resolved) {
    return text
      ? `${resolved}${native ? '&' : '?'}text=${encodeURIComponent(text)}`
      : resolved;
  }
  const id = String(chat);
  if (/^-100\d+$/.test(id) && /^[1-9]\d*$/.test(String(lastId))) {
    return native
      ? `tg://privatepost?channel=${id.slice(4)}&post=${lastId}`
      : `https://t.me/c/${id.slice(4)}/${lastId}`;
  }
  return `https://web.telegram.org/a/#${id}`;
};

export const isTelegramWebUrl = (url) =>
  String(url ?? '').startsWith('https://web.telegram.org/a/#');

/**
 * Shared folders (chat lists), as Telegram Desktop has them (R-Y172;
 * learned, never copied): a folder whose chats others can add through a
 * `t.me/addlist/<slug>` link.
 *
 * - `chatlistInvites({ id })` — chatlists.getExportedInvites: the folder's
 *   links, `{ slug, title, url, chats: [chat] }`, and the names of the chats;
 * - `chatlistExport({ id, title?, chats })` — chatlists.exportChatlistInvite
 *   with the chats chosen from the folder's groups and channels; the folder
 *   becomes a shared one (`folderId` says which);
 * - `chatlistInviteEdit({ id, slug, title?, chats? })` —
 *   chatlists.editExportedInvite; `chatlistInviteDelete({ id, slug })` —
 *   chatlists.deleteExportedInvite;
 * - `chatlistCheck({ slug })` — chatlists.checkChatlistInvite, only a look:
 *   `{ ok, already, folderId?, title, emoticon, chats: [{ chat, name, kind,
 *   joined }] }` (`joined`: the user is in it; for a folder the user has,
 *   the chats not yet in are the new ones);
 * - `chatlistJoin({ slug, chats })` — only on the user's press:
 *   chatlists.joinChatlistInvite for a new folder, chatlists.
 *   joinChatlistUpdates for one the user already has; only chats the link
 *   names can be chosen;
 * - `chatlistLeaveSuggestions({ id })` — chatlists.getLeaveChatlistSuggestions:
 *   the chats it would be good to leave as well;
 *   `chatlistLeave({ id, chats })` — chatlists.leaveChatlist.
 * New chats in a shared folder the user joined (R-Y211):
 * - `chatlistUpdates({ id })` — chatlists.getChatlistUpdates: `{ ok, chats:
 *   [{ chat, name, kind }] }`, the chats the folder's owner has added;
 * - `chatlistUpdatesJoin({ id, chats })` — only on the user's press:
 *   chatlists.joinChatlistUpdates with chats the last look named;
 * - `chatlistUpdatesHide({ id })` — chatlists.hideChatlistUpdates, the
 *   notice put away.
 * Telegram's errors become codes the page shows as words.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';
import { inputsOf } from './telegram-folder-edit.js';
import { markedId } from './telegram-invite.js';

const CODES = {
  CHATLIST_EXCLUDE_INVALID: 'bad-chats',
  INVITES_TOO_MUCH: 'too-many-links',
  CHATLISTS_TOO_MUCH: 'too-many-shared',
  FILTER_ID_INVALID: 'id-invalid',
  FILTER_INCLUDE_EMPTY: 'include-empty',
  FILTER_NOT_SUPPORTED: 'not-supported',
  PEERS_LIST_EMPTY: 'no-chats',
  INVITE_SLUG_EXPIRED: 'invite-expired',
  INVITE_SLUG_INVALID: 'invite-invalid',
  INVITE_SLUG_EMPTY: 'invite-invalid',
  USER_CHANNELS_TOO_MUCH: 'too-many-chats',
  CHANNELS_TOO_MUCH: 'too-many-chats',
  DIALOG_FILTERS_TOO_MUCH: 'too-many-folders',
  USER_ALREADY_PARTICIPANT: 'already-member',
  CHAT_ADMIN_REQUIRED: 'not-admin',
  PEER_ID_INVALID: 'no-access',
  CHANNEL_PRIVATE: 'no-access',
  PREMIUM_ACCOUNT_REQUIRED: 'premium',
  USER_PREMIUM_REQUIRED: 'premium',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);
const BAD = { ok: false, error: 'bad request', code: 'failed' };

export const SLUG = /^[A-Za-z0-9_-]{8,64}$/;
const GROUP_CHAT = /^-\d{1,20}$/;
const LINK_TITLE_MAX = 32;
const CHATS_MAX = 200;

/** Whether `chats` is a list of group or channel ids (strict). */
export const validChats = (chats, { min = 0 } = {}) =>
  Array.isArray(chats) &&
  chats.length >= min &&
  chats.length <= CHATS_MAX &&
  chats.every((c) => typeof c === 'string' && GROUP_CHAT.test(c)) &&
  new Set(chats).size === chats.length;

/** Whether `title` is a link's name (up to 32 letters, may be empty). */
export const validLinkTitle = (title) =>
  title === undefined ||
  (typeof title === 'string' && [...title].length <= LINK_TITLE_MAX);

/** A folder id the page may name (2 and up). */
export const validFolderId = (id) =>
  Number.isInteger(id) && id >= 2 && id < 1000;

/** The slug a `t.me/addlist/<slug>` link carries, or null. */
export const slugOfUrl = (url) =>
  /\/addlist\/([A-Za-z0-9_-]+)\/?$/.exec(String(url ?? ''))?.[1] ?? null;

const text = (value) => String(value?.value ?? value);

// Every chat and user an answer names: marked id -> { name, kind, entity }.
const entitiesOf = (answer) => {
  const found = new Map();
  for (const chat of answer?.chats ?? []) {
    found.set(markedId(chat), {
      name: chat.title ?? '',
      kind: chat.broadcast ? 'channel' : 'group',
      entity: chat,
    });
  }
  for (const user of answer?.users ?? []) {
    const name = [user.firstName, user.lastName].filter(Boolean).join(' ');
    found.set(text(user.id), {
      name: name || user.username || text(user.id),
      kind: 'user',
      entity: user,
    });
  }
  return found;
};

// A Peer (not an InputPeer) as our chat id.
const peerIdOf = (peer) => {
  if (peer?.userId !== undefined) {
    return text(peer.userId);
  }
  if (peer?.chatId !== undefined) {
    return `-${text(peer.chatId)}`;
  }
  return peer?.channelId === undefined ? null : `-100${text(peer.channelId)}`;
};

const peerIds = (peers) => (peers ?? []).map(peerIdOf).filter(Boolean);

const namesOf = (entities, ids) =>
  [...new Set(ids)].map((chat) => ({
    chat,
    name: entities.get(chat)?.name || chat,
  }));

const linkOf = (invite) => ({
  slug: slugOfUrl(invite?.url),
  title: String(invite?.title ?? ''),
  url: String(invite?.url ?? ''),
  chats: peerIds(invite?.peers),
});

// The input peer of a chat in a link's answer, which the user may not be in.
const inputFromEntity = (c, entity) => {
  switch (entity.className) {
    case 'Channel':
    case 'ChannelForbidden':
      return new c.Api.InputPeerChannel({
        channelId: entity.id,
        accessHash: entity.accessHash,
      });
    case 'Chat':
    case 'ChatForbidden':
      return new c.Api.InputPeerChat({ chatId: entity.id });
    case 'User':
      return new c.Api.InputPeerUser({
        userId: entity.id,
        accessHash: entity.accessHash,
      });
    default:
      return null;
  }
};

const folderRef = (c, id) =>
  new c.Api.InputChatlistDialogFilter({ filterId: id });

// What a check of a link says, for the page.
const describeCheck = (answer) => {
  const entities = entitiesOf(answer);
  if (/ChatlistInviteAlready$/.test(answer.className ?? '')) {
    const missing = peerIds(answer.missingPeers);
    const already = peerIds(answer.alreadyPeers);
    return {
      entities,
      view: {
        ok: true,
        already: true,
        folderId: Number(answer.filterId),
        title: '',
        emoticon: null,
        chats: [
          ...missing.map((chat) => ({ chat, joined: false })),
          ...already.map((chat) => ({ chat, joined: true })),
        ].map((row) => ({
          ...row,
          name: entities.get(row.chat)?.name || row.chat,
          kind: entities.get(row.chat)?.kind ?? 'group',
        })),
      },
    };
  }
  return {
    entities,
    view: {
      ok: true,
      already: false,
      title: text(answer.title?.text ?? answer.title ?? ''),
      emoticon: answer.emoticon ?? null,
      chats: peerIds(answer.peers).map((chat) => ({
        chat,
        name: entities.get(chat)?.name || chat,
        kind: entities.get(chat)?.kind ?? 'group',
        joined: false,
      })),
    },
  };
};

// The folder's own links: listed, made, edited, deleted.
const createLinkActions = (env, inFolder) => ({
  /** `{ id }` → `{ ok, invites, chats }`. */
  chatlistInvites: async ({ id } = {}) =>
    !validFolderId(id)
      ? BAD
      : inFolder(async (c) => {
          const answer = await c.client.invoke(
            new c.Api.chatlists.GetExportedInvites({
              chatlist: folderRef(c, id),
            })
          );
          const invites = (answer?.invites ?? []).map(linkOf);
          const entities = entitiesOf(answer);
          return {
            ok: true,
            invites: invites.filter((i) => i.slug),
            chats: namesOf(
              entities,
              invites.flatMap((i) => i.chats)
            ),
          };
        }),

  /** `{ id, title?, chats }` → `{ ok, invite }`. */
  chatlistExport: async ({ id, title, chats } = {}) =>
    !validFolderId(id) ||
    !validLinkTitle(title) ||
    !validChats(chats, { min: 1 })
      ? BAD
      : inFolder(async (c) => {
          const answer = await c.client.invoke(
            new c.Api.chatlists.ExportChatlistInvite({
              chatlist: folderRef(c, id),
              title: title ?? '',
              peers: await inputsOf(env, c, chats),
            })
          );
          const invite = linkOf(answer?.invite);
          return invite.slug
            ? { ok: true, invite, folderId: id }
            : { ok: false, error: 'failed', code: 'failed' };
        }),

  /** `{ id, slug, title?, chats? }` → `{ ok, invite }`. */
  chatlistInviteEdit: async ({ id, slug, title, chats } = {}) =>
    !validFolderId(id) ||
    !SLUG.test(String(slug)) ||
    !validLinkTitle(title) ||
    (chats !== undefined && !validChats(chats, { min: 1 })) ||
    (title === undefined && chats === undefined)
      ? BAD
      : inFolder(async (c) => {
          const answer = await c.client.invoke(
            new c.Api.chatlists.EditExportedInvite({
              chatlist: folderRef(c, id),
              slug,
              ...(title === undefined ? {} : { title }),
              ...(chats === undefined
                ? {}
                : { peers: await inputsOf(env, c, chats) }),
            })
          );
          return { ok: true, invite: { ...linkOf(answer), slug } };
        }),

  /** `{ id, slug }` → `{ ok }`. */
  chatlistInviteDelete: async ({ id, slug } = {}) =>
    !validFolderId(id) || !SLUG.test(String(slug))
      ? BAD
      : inFolder(async (c) => {
          await c.client.invoke(
            new c.Api.chatlists.DeleteExportedInvite({
              chatlist: folderRef(c, id),
              slug,
            })
          );
          return { ok: true };
        }),
});

// New chats in a folder the user joined (R-Y211): looked at, joined on the
// user's press, or the notice hidden.
const createUpdateActions = (env, inFolder, apply) => {
  const heard = new Map(); // folder id -> Map(chat -> input peer)
  return {
    /** `{ id }` → `{ ok, chats }` the new chats of a joined folder. */
    chatlistUpdates: async ({ id } = {}) =>
      !validFolderId(id)
        ? BAD
        : inFolder(async (c) => {
            const answer = await c.client.invoke(
              new c.Api.chatlists.GetChatlistUpdates({
                chatlist: folderRef(c, id),
              })
            );
            const entities = entitiesOf(answer);
            const chats = peerIds(answer?.missingPeers).map((chat) => ({
              chat,
              name: entities.get(chat)?.name || chat,
              kind: entities.get(chat)?.kind ?? 'group',
            }));
            heard.set(
              id,
              new Map(
                chats.map((row) => [
                  row.chat,
                  inputFromEntity(c, entities.get(row.chat)?.entity ?? {}),
                ])
              )
            );
            return { ok: true, chats };
          }),

    /** `{ id, chats }` → `{ ok }`; only on the user's press. */
    chatlistUpdatesJoin: async ({ id, chats } = {}) =>
      !validFolderId(id) || !validChats(chats, { min: 1 })
        ? BAD
        : inFolder(async (c) => {
            const known = heard.get(id);
            const peers = chats.map((chat) => known?.get(chat));
            if (!known || peers.some((peer) => !peer)) {
              return {
                ok: false,
                error: 'not in the folder',
                code: 'bad-chats',
              };
            }
            const result = await c.client.invoke(
              new c.Api.chatlists.JoinChatlistUpdates({
                chatlist: folderRef(c, id),
                peers,
              })
            );
            heard.delete(id);
            if (result && typeof result === 'object') {
              await apply?.(c.client, result);
            }
            return { ok: true };
          }),

    /** `{ id }` → `{ ok }`: the notice put away. */
    chatlistUpdatesHide: async ({ id } = {}) =>
      !validFolderId(id)
        ? BAD
        : inFolder(async (c) => {
            await c.client.invoke(
              new c.Api.chatlists.HideChatlistUpdates({
                chatlist: folderRef(c, id),
              })
            );
            heard.delete(id);
            return { ok: true };
          }),
  };
};

export const createChatlists = (env, { userClient, apply }) => {
  const asUser = (use) => connected(env, userClient, failure, use);
  const seen = new Map(); // slug -> { already, folderId, inputs: Map }

  const look = async (c, slug) => {
    const answer = await runIn(env, `chatlist:check:${slug}`, () =>
      c.client.invoke(new c.Api.chatlists.CheckChatlistInvite({ slug }))
    );
    const { entities, view } = describeCheck(answer ?? {});
    const inputs = new Map(
      view.chats.map((row) => [
        row.chat,
        inputFromEntity(c, entities.get(row.chat)?.entity ?? {}),
      ])
    );
    seen.set(slug, { already: view.already, folderId: view.folderId, inputs });
    return view;
  };

  const inFolder = (use) => asUser((c) => runIn(env, 'chatlist', () => use(c)));

  return {
    ...createLinkActions(env, inFolder),
    ...createUpdateActions(env, inFolder, apply),
    /** `{ slug }` → what the link leads to; nothing is joined. */
    chatlistCheck: async ({ slug } = {}) =>
      !SLUG.test(String(slug))
        ? { ok: false, error: 'invite-invalid', code: 'invite-invalid' }
        : asUser((c) => look(c, slug)),

    /** `{ slug, chats }` → `{ ok }`; only on the user's press. */
    chatlistJoin: async ({ slug, chats } = {}) =>
      !SLUG.test(String(slug)) || !validChats(chats, { min: 1 })
        ? BAD
        : asUser(async (c) => {
            if (!seen.has(slug)) {
              await look(c, slug);
            }
            const known = seen.get(slug);
            const peers = chats.map((chat) => known.inputs.get(chat));
            if (peers.some((peer) => !peer)) {
              return { ok: false, error: 'not in the link', code: 'bad-chats' };
            }
            const result = await runIn(env, `chatlist:join:${slug}`, () =>
              c.client.invoke(
                known.already
                  ? new c.Api.chatlists.JoinChatlistUpdates({
                      chatlist: folderRef(c, known.folderId),
                      peers,
                    })
                  : new c.Api.chatlists.JoinChatlistInvite({ slug, peers })
              )
            );
            seen.delete(slug);
            if (result && typeof result === 'object') {
              await apply?.(c.client, result);
            }
            return { ok: true };
          }),

    /** `{ id }` → `{ ok, chats }` the chats suggested to leave too. */
    chatlistLeaveSuggestions: async ({ id } = {}) =>
      !validFolderId(id)
        ? BAD
        : inFolder(async (c) => {
            const peers = await c.client.invoke(
              new c.Api.chatlists.GetLeaveChatlistSuggestions({
                chatlist: folderRef(c, id),
              })
            );
            return {
              ok: true,
              chats: peerIds(Array.isArray(peers) ? peers : []),
            };
          }),

    /** `{ id, chats }` → `{ ok }`: the folder left, with these chats. */
    chatlistLeave: async ({ id, chats } = {}) =>
      !validFolderId(id) || !validChats(chats)
        ? BAD
        : inFolder(async (c) => {
            const result = await c.client.invoke(
              new c.Api.chatlists.LeaveChatlist({
                chatlist: folderRef(c, id),
                peers: await inputsOf(env, c, chats),
              })
            );
            if (result && typeof result === 'object') {
              await apply?.(c.client, result);
            }
            return { ok: true };
          }),
  };
};

/**
 * Cloud themes and the per-chat translation switch, as Telegram Desktop has
 * them (R-Y209; learned, never copied):
 * - `cloudThemes({ fresh })` — the themes of the account and Telegram's
 *   (account.getThemes in Desktop's 'tdesktop' format, asked again with the
 *   hash it gave) as `{ ok, themes: [cloudPage] }`;
 * - `cloudTheme({ slug })` — one theme by its t.me/addtheme slug
 *   (account.getTheme with InputThemeSlug) as `{ ok, theme }`;
 * - `installCloudTheme({ id, accessHash, slug, dark, reset })` — records the
 *   theme as the account's (account.installTheme), or with `reset` puts the
 *   default back; the page applies the colours on its own;
 * - `toggleTranslations({ chat, disabled })` — "Do not translate this chat"
 *   or the offer back (messages.togglePeerTranslations).
 * A theme's page form keeps the colours of its ThemeSettings only (the
 * `{ base, accent, outgoing, messages }` of chat themes, light and dark);
 * the .tdesktop-theme file is never parsed.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';
import { settingsPage } from './telegram-chat-themes.js';

const CODES = {
  THEME_INVALID: 'not-found',
  THEME_SLUG_INVALID: 'not-found',
  THEME_FORMAT_INVALID: 'invalid',
  CHAT_ID_INVALID: 'no-access',
  PEER_ID_INVALID: 'no-access',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);

export const SLUG = /^[A-Za-z0-9_-]{1,64}$/;
export const DIGITS = /^\d{1,20}$/;
export const CHAT = /^-?\d{1,20}$/;
const FORMAT = 'tdesktop';
const LIST_MS = 5 * 60_000;
const DARK_BASES = ['BaseThemeNight', 'BaseThemeTinted'];

const text = (value) =>
  value === null || value === undefined ? '' : String(value.value ?? value);

/** A Theme as the page keeps it, or null for anything else. */
export const cloudPage = (theme) => {
  if (theme?.className !== 'Theme' || !theme.slug) {
    return null;
  }
  const all = theme.settings ?? [];
  const dark = all.find((s) => DARK_BASES.includes(s.baseTheme?.className));
  const light = all.find((s) => s !== dark);
  return {
    id: text(theme.id),
    accessHash: text(theme.accessHash),
    slug: String(theme.slug),
    title: String(theme.title ?? ''),
    creator: Boolean(theme.creator),
    default: Boolean(theme.default),
    forChat: Boolean(theme.forChat),
    light: settingsPage(light),
    dark: settingsPage(dark),
  };
};

export const createCloudThemes = (env, { userClient }) => {
  let kept = null; // { at, hash, answer }

  const cloudThemes = async ({ fresh = false } = {}) => {
    if (!fresh && kept && Date.now() - kept.at < LIST_MS) {
      return kept.answer;
    }
    return connected(env, userClient, failure, async (c) => {
      const got = await runIn(env, 'cloud-themes:list', () =>
        c.client.invoke(
          new c.Api.account.GetThemes({
            format: FORMAT,
            hash: kept && !fresh ? c.helpers.returnBigInt(kept.hash) : c.zero,
          })
        )
      );
      if (got?.className === 'account.ThemesNotModified' && kept) {
        kept.at = Date.now();
        return kept.answer;
      }
      const themes = (got?.themes ?? []).map(cloudPage).filter(Boolean);
      const answer = { ok: true, themes };
      kept = { at: Date.now(), hash: text(got?.hash) || '0', answer };
      return answer;
    });
  };

  const cloudTheme = async ({ slug } = {}) => {
    if (!SLUG.test(String(slug ?? ''))) {
      return { ok: false, error: 'bad slug', code: 'bad-request' };
    }
    return connected(env, userClient, failure, async (c) => {
      const got = await runIn(env, `cloud-theme:${slug}`, () =>
        c.client.invoke(
          new c.Api.account.GetTheme({
            format: FORMAT,
            theme: new c.Api.InputThemeSlug({ slug }),
          })
        )
      );
      const theme = cloudPage(got);
      return theme ? { ok: true, theme } : { ok: false, code: 'not-found' };
    });
  };

  const inputOf = (c, { id, accessHash, slug }) =>
    slug
      ? new c.Api.InputThemeSlug({ slug })
      : new c.Api.InputTheme({
          id: c.helpers.returnBigInt(id),
          accessHash: c.helpers.returnBigInt(accessHash),
        });

  // The one account write for themes: the theme recorded, or the default.
  const installCloudTheme = async (body = {}) => {
    const { id, accessHash, slug, dark = false, reset = false } = body;
    const named = DIGITS.test(String(id ?? '')) && DIGITS.test(accessHash);
    if (!reset && !named && !SLUG.test(String(slug ?? ''))) {
      return { ok: false, error: 'bad theme', code: 'bad-request' };
    }
    return connected(env, userClient, failure, async (c) => {
      await runIn(env, 'cloud-theme:install', () =>
        c.client.invoke(
          new c.Api.account.InstallTheme({
            dark: dark === true,
            format: FORMAT,
            ...(reset ? {} : { theme: inputOf(c, { id, accessHash, slug }) }),
          })
        )
      );
      return { ok: true };
    });
  };

  const toggleTranslations = async ({ chat, disabled } = {}) => {
    if (!CHAT.test(String(chat ?? '')) || typeof disabled !== 'boolean') {
      return { ok: false, error: 'bad request', code: 'bad-request' };
    }
    return connected(env, userClient, failure, async (c) => {
      await runIn(env, `translations-toggle:${chat}`, () =>
        env.connection.withPeer(c.client, String(chat), (peer) =>
          c.client.invoke(
            new c.Api.messages.TogglePeerTranslations({ peer, disabled })
          )
        )
      );
      return { ok: true, disabled };
    });
  };

  return { cloudThemes, cloudTheme, installCloudTheme, toggleTranslations };
};

/**
 * A channel post's comments, and a group message's thread of replies,
 * as Telegram's apps open them (R-Y126; learned, never copied):
 *
 * - `comments({ chat, post, before, limit })` — `{ ok, group, root,
 *   unread, messages, complete }`: the discussion (messages.
 *   getDiscussionMessage: the group the comments are in and the post's
 *   copy there, `root`), then its replies by page, oldest first
 *   (messages.getReplies), the page before message `before` when given.
 *   The comments are given to the page, not stored: the discussion group
 *   is no chat of the user's list unless they joined it.
 * - `readComments({ chat, post, max })` — the comments up to `max` read
 *   (messages.readDiscussion on the post's copy in the group).
 * - `sendComment({ chat, post, text, replyTo, clientId })` — a comment
 *   sent to the discussion group, answering the post's copy (or the
 *   comment `replyTo`, with the copy as its thread's top).
 */

import { sendError, sendText } from './telegram-send.js';

const KEEP_MS = 10 * 60_000;
const ID = /^-?\d{1,20}$/;

const text = (value) => String(value?.value ?? value ?? '');

const usable = (m) => m && m.id !== undefined && m.className !== 'MessageEmpty';

// The discussion group in Telegram's answer: the chat the post's copy
// is in; its title and kind as the chat list names them.
const groupOf = (answer, root) => {
  const id = text(root.peerId?.channelId ?? root.peerId?.chatId);
  const entity = (answer.chats ?? []).find((c) => text(c.id) === id) ?? null;
  const chat = root.peerId?.channelId ? `-100${id}` : `-${id}`;
  return {
    chat,
    entity,
    title: String(entity?.title ?? ''),
  };
};

/**
 * `env` is the account's; `userClient()` the user client or null;
 * `tools` its `toLinks`.
 */
export const createComments = (
  env,
  { userClient, tools },
  { now = () => Date.now() } = {}
) => {
  const kept = new Map(); // `${chat}:${post}` -> { at, thread }

  // The post's discussion: its group and the post's copy there.
  const discussion = async (client, chat, post) => {
    const key = `${chat}:${post}`;
    const entry = kept.get(key);
    if (entry && now() - entry.at < KEEP_MS) {
      return entry.thread;
    }
    const { Api } = await env.importer();
    const answer = await env.queue.run(`discussion:${key}`, 'view', () =>
      env.connection.withPeer(client, chat, (peer) =>
        client.invoke(
          new Api.messages.GetDiscussionMessage({ peer, msgId: post })
        )
      )
    );
    // The thread's first message is the oldest one given.
    const root = [...(answer?.messages ?? [])]
      .filter(usable)
      .sort((a, b) => Number(a.id) - Number(b.id))[0];
    if (!root) {
      return null;
    }
    const group = groupOf(answer, root);
    // The group's peer kept, so its files and sends find it.
    if (group.entity) {
      await Promise.resolve(
        env.peers?.remember?.(group.chat, group.entity, {
          title: group.title,
          isChannel: Boolean(root.peerId?.channelId),
          isGroup: true,
        })
      ).catch(() => {});
    }
    const thread = {
      group: { chat: group.chat, title: group.title },
      root: Number(root.id),
      unread: Number(answer.unreadCount) || 0,
    };
    kept.set(key, { at: now(), thread });
    return thread;
  };

  const comments = async ({ chat, post, before = null, limit = 50 } = {}) => {
    const id = Number(post);
    const client =
      ID.test(String(chat ?? '')) && Number.isInteger(id) && id > 0
        ? await userClient()
        : null;
    if (!client) {
      return { ok: false, supported: false };
    }
    const target = String(chat);
    const thread = await discussion(client, target, id);
    if (!thread) {
      return { ok: false, error: 'no comments', code: 'no-comments' };
    }
    const offset = Number(before);
    const page = await env.queue.run(
      `comments:${thread.group.chat}:${thread.root}:${offset || 0}`,
      'view',
      () =>
        env.connection.withPeer(client, thread.group.chat, (peer) =>
          client.getMessages(peer, {
            replyTo: thread.root,
            limit,
            ...(Number.isInteger(offset) && offset > 0
              ? { offsetId: offset }
              : {}),
          })
        )
    );
    const messages = [...(page ?? [])]
      .filter(usable)
      .sort((a, b) => Number(a.id) - Number(b.id));
    const links = tools.toLinks(
      { id: thread.group.chat, title: thread.group.title, isGroup: true },
      messages
    );
    return {
      ok: true,
      ...thread,
      messages: links,
      complete: messages.length < limit,
    };
  };

  const sendComment = async ({
    chat,
    post,
    text: body,
    replyTo = null,
    clientId,
  } = {}) => {
    const client = await userClient();
    if (!client) {
      return { ok: false, supported: false };
    }
    const thread = await discussion(client, String(chat), Number(post));
    if (!thread) {
      return { ok: false, error: 'no comments', code: 'no-comments' };
    }
    const { Api, helpers } = await env.importer();
    try {
      await env.connection.withPeer(client, thread.group.chat, (peer) =>
        sendText({
          client,
          Api,
          helpers,
          peer,
          text: body,
          clientId,
          // A comment answers the post's copy; an answer to a comment
          // names the copy as its thread's top.
          replyTo: replyTo ?? thread.root,
          topic: replyTo ? thread.root : null,
        })
      );
    } catch (error) {
      throw sendError(error);
    }
    return { ok: true, chat: thread.group.chat };
  };

  // The comments seen up to `max` are read, as Telegram's apps mark
  // them once shown: the thread's mark in the discussion group.
  const readComments = async ({ chat, post, max } = {}) => {
    const client = await userClient();
    if (!client) {
      return { ok: false, supported: false };
    }
    const thread = await discussion(client, String(chat), Number(post));
    if (!thread) {
      return { ok: false, error: 'no comments', code: 'no-comments' };
    }
    const { Api } = await env.importer();
    await env.queue.run(
      `comments-read:${thread.group.chat}:${thread.root}`,
      'view',
      () =>
        env.connection.withPeer(client, thread.group.chat, (peer) =>
          client.invoke(
            new Api.messages.ReadDiscussion({
              peer,
              msgId: thread.root,
              readMaxId: Number(max),
            })
          )
        )
    );
    return { ok: true };
  };

  return { comments, sendComment, readComments };
};

/**
 * Groups in common with a person (R-Y158; learned, never copied), as
 * Telegram Desktop lists them from a person's profile:
 * - `commonChats({ chat, maxId? })` — the groups and channels both the
 *   account and the person are in, a page at a time
 *   (messages.getCommonChats) → `{ ok, chats: [{ chat, title, kind,
 *   members }], next }`. `chat` is the marked id (-100N for a supergroup
 *   or channel, -N for a basic group), `kind` 'group' or 'channel',
 *   `members` the count when Telegram says it (else null); `next` is the
 *   `maxId` for the following page (the last chat's own id), or null.
 * Read-only. Telegram's errors become codes the page shows as text.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';
import { inputUserOf } from './telegram-peer-actions.js';

const CODES = {
  USER_ID_INVALID: 'no-user',
  PEER_ID_INVALID: 'no-user',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);
const bad = { ok: false, error: 'bad request', code: 'failed' };
const USER = /^\d{1,20}$/;
export const COMMON_PAGE = 50;

const textOf = (value) => String(value?.value ?? value);

// A chat Telegram sent, as the page lists it; null for one it cannot open.
const chatOf = (raw) => {
  const kind = raw?.className;
  if (kind !== 'Channel' && kind !== 'Chat') {
    return null;
  }
  const id = textOf(raw.id);
  const channel = kind === 'Channel';
  return {
    id,
    chat: channel ? `-100${id}` : `-${id}`,
    title: raw.title ?? '',
    kind: channel && raw.broadcast ? 'channel' : 'group',
    members: raw.participantsCount ?? null,
  };
};

const createCommonChatsRead =
  (env, userClient) =>
  async (body = {}) => {
    const chat = String(body.chat ?? '');
    const maxId = String(body.maxId ?? '0');
    if (!USER.test(chat) || !USER.test(maxId)) {
      return bad;
    }
    return connected(env, userClient, failure, async (c) => {
      const answer = await runIn(env, `common-chats:${chat}:${maxId}`, () =>
        env.connection.withPeer(c.client, chat, async (peer) =>
          c.client.invoke(
            new c.Api.messages.GetCommonChats({
              userId: await inputUserOf(c, peer),
              maxId: c.helpers.returnBigInt(maxId),
              limit: COMMON_PAGE,
            })
          )
        )
      );
      const found = (answer?.chats ?? []).map(chatOf).filter(Boolean);
      const last = (answer?.chats ?? []).at(-1);
      return {
        ok: true,
        chats: found.map(({ id: _id, ...rest }) => rest),
        next:
          (answer?.chats ?? []).length >= COMMON_PAGE && last
            ? textOf(last.id)
            : null,
      };
    });
  };

export const createCommonChats = (env, context) => ({
  commonChats: createCommonChatsRead(env, context.userClient),
});

/**
 * What Telegram's official clients have on a contact besides the chat
 * (R-Y217; learned, never copied):
 * - `contactNote({ chat, note })` — a private note on a contact
 *   (contacts.updateContactNote; read back as `note` in the chat info);
 * - `contactToken()` — "Share my contact": a link and its expiry
 *   (contacts.exportContactToken) → `{ ok, url, expires }`;
 *   `contactTokenOpen({ token })` — opens such a link
 *   (contacts.importContactToken) → `{ ok, chat, name }`;
 * - `phoneResolve({ phone })` — t.me/+<digits> (contacts.resolvePhone) →
 *   `{ ok, found: false }` or `{ ok, found: true, chat, name }`;
 * - `contactPhoto({ chat, mode, token })` — a photo for a contact, `mode`
 *   `save` (only the user sees it), `suggest` (the contact is asked) or
 *   `reset` (the personal one removed): photos.uploadContactProfilePhoto
 *   with the page's upload;
 * - `birthdaySuggest({ chat, day, month, year? })` — users.suggestBirthday;
 * - `savedContacts()` — the count of imported contacts Telegram keeps
 *   (contacts.getSaved); `savedContactsReset()` — contacts.resetSaved;
 * - `blockFromReplies({ msgId, deleteMessage, deleteHistory, reportSpam })`
 *   — "Block user" on a message of the Replies chat
 *   (contacts.blockFromReplies).
 * Nothing is sent but on the user's explicit click. Telegram's errors
 * become codes the page shows as text.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';
import { writeFailureOf } from './telegram-write-outcome.js';
import { uploadedFile } from './telegram-chat-edit.js';
import { validBirthday } from './telegram-profile-extras.js';
import { inputUserOf } from './telegram-peer-actions.js';

const CODES = {
  USER_ID_INVALID: 'no-user',
  CONTACT_ID_INVALID: 'no-user',
  PEER_ID_INVALID: 'no-user',
  CONTACT_NOTE_INVALID: 'note-invalid',
  NOTE_TOO_LONG: 'note-invalid',
  TOKEN_INVALID: 'token-invalid',
  CONTACT_TOKEN_INVALID: 'token-invalid',
  TOKEN_EXPIRED: 'token-invalid',
  PHOTO_INVALID: 'photo-invalid',
  PHOTO_EXT_INVALID: 'photo-invalid',
  IMAGE_PROCESS_FAILED: 'photo-invalid',
  BIRTHDAY_INVALID: 'birthday-invalid',
  MSG_ID_INVALID: 'not-found',
  FLOOD_WAIT: 'flood',
};
const failure = failureOf(CODES);
const writeFailure = writeFailureOf(CODES);
const bad = (code) => ({ ok: false, error: code, code });

export const USER = /^\d{1,20}$/;
export const TOKEN = /^[A-Za-z0-9_-]{1,128}$/;
export const PHONE_DIGITS = /^\d{5,20}$/;
export const MODES = ['save', 'suggest', 'reset'];
export const NOTE_MAX = 128;
const MSG_MAX = 2_147_483_647;

const textOf = (value) => String(value?.value ?? value);
const nameOf = (user) =>
  [user.firstName, user.lastName].filter(Boolean).join(' ') ||
  user.username ||
  textOf(user.id);

/** The note Telegram keeps on a contact, from users.getFullUser, or {}. */
export const noteOf = (full) => {
  const note = String(full?.note?.text ?? '');
  return {
    ...(note === '' ? {} : { note }),
    ...(full?.personalPhoto ? { personalPhoto: true } : {}),
  };
};

/** Whether `msgId` can be a message id. */
export const validMsgId = (msgId) =>
  Number.isInteger(msgId) && msgId > 0 && msgId <= MSG_MAX;

// A person found: remembered in the peer store, with their chat id.
const found = async (env, user) => {
  const chat = textOf(user.id);
  const name = nameOf(user);
  await Promise.resolve(
    env.peers?.remember?.(chat, user, { isUser: true, name })
  ).catch(() => {});
  return { ok: true, found: true, chat, name };
};

// A person's InputUser through the queue.
const withUser = (env, c, chat, key, use) =>
  runIn(env, `${key}:${chat}`, () =>
    env.connection.withPeer(c.client, chat, async (peer) =>
      use(await inputUserOf(c, peer))
    )
  );

const notePage = (c, note) =>
  new c.Api.TextWithEntities({ text: note, entities: [] });

const setNote =
  (env, userClient) =>
  async (body = {}) => {
    const chat = String(body.chat ?? '');
    const note = typeof body.note === 'string' ? body.note.trim() : null;
    if (!USER.test(chat) || note === null || note.length > NOTE_MAX) {
      return bad('bad-request');
    }
    return connected(env, userClient, writeFailure, async (c) => {
      await withUser(env, c, chat, 'contact-note', (id) =>
        c.client.invoke(
          new c.Api.contacts.UpdateContactNote({ id, note: notePage(c, note) })
        )
      );
      return { ok: true, note };
    });
  };

const exportToken = (env, userClient) => async () =>
  connected(env, userClient, failure, async (c) => {
    const token = await runIn(env, 'contact-token', () =>
      c.client.invoke(new c.Api.contacts.ExportContactToken())
    );
    return { ok: true, url: String(token.url), expires: Number(token.expires) };
  });

const importToken =
  (env, userClient) =>
  async (body = {}) => {
    const token = String(body.token ?? '');
    if (!TOKEN.test(token)) {
      return bad('token-invalid');
    }
    return connected(env, userClient, failure, async (c) => {
      const user = await runIn(env, 'contact-token-open', () =>
        c.client.invoke(new c.Api.contacts.ImportContactToken({ token }))
      );
      return user?.id ? found(env, user) : bad('token-invalid');
    });
  };

// A number nobody has on Telegram is a plain "not found", not a failure.
const phoneFailure = (error) =>
  String(error?.errorMessage ?? error?.message ?? '').includes(
    'PHONE_NOT_OCCUPIED'
  )
    ? { ok: true, found: false }
    : failure(error);

const resolvePhone =
  (env, userClient) =>
  async (body = {}) => {
    const phone = String(body.phone ?? '').replace(/^\+/, '');
    if (!PHONE_DIGITS.test(phone)) {
      return bad('phone-invalid');
    }
    return connected(env, userClient, phoneFailure, async (c) => {
      const answer = await runIn(env, 'contact-phone', () =>
        c.client.invoke(new c.Api.contacts.ResolvePhone({ phone }))
      );
      const user = (answer?.users ?? []).find((u) => u?.id);
      return user ? found(env, user) : { ok: true, found: false };
    });
  };

const photoRequest = async (c, uploads, id, { mode, token }) => {
  if (mode === 'reset') {
    return new c.Api.photos.UploadContactProfilePhoto({
      userId: id,
      save: true,
    });
  }
  const file = await uploadedFile(c, uploads, token);
  return file
    ? new c.Api.photos.UploadContactProfilePhoto({
        userId: id,
        file,
        [mode === 'save' ? 'save' : 'suggest']: true,
      })
    : null;
};

const setPhoto =
  (env, { userClient, uploads }) =>
  async (body = {}) => {
    const chat = String(body.chat ?? '');
    const token = String(body.token ?? '');
    try {
      if (!USER.test(chat) || !MODES.includes(body.mode)) {
        return bad('bad-request');
      }
      return await connected(env, userClient, writeFailure, async (conn) => {
        // uploadedFile reads the importer from `c.env`.
        const c = { ...conn, env };
        const sent = await withUser(
          env,
          c,
          chat,
          'contact-photo',
          async (id) => {
            const request = await photoRequest(c, uploads, id, {
              mode: body.mode,
              token,
            });
            return request ? c.client.invoke(request) : null;
          }
        );
        return sent ? { ok: true, mode: body.mode } : bad('photo-invalid');
      });
    } finally {
      await uploads?.dropUpload?.(token);
    }
  };

const suggestBirthday =
  (env, userClient) =>
  async (body = {}) => {
    const chat = String(body.chat ?? '');
    const { day, month, year } = body;
    if (!USER.test(chat) || !validBirthday({ day, month, year })) {
      return bad('birthday-invalid');
    }
    return connected(env, userClient, writeFailure, async (c) => {
      await withUser(env, c, chat, 'contact-birthday', (id) =>
        c.client.invoke(
          new c.Api.users.SuggestBirthday({
            id,
            birthday: new c.Api.Birthday({
              day,
              month,
              ...(year === undefined ? {} : { year }),
            }),
          })
        )
      );
      return { ok: true };
    });
  };

const savedCount = (env, userClient) => async () =>
  connected(env, userClient, failure, async (c) => {
    const saved = await runIn(env, 'contacts:saved', () =>
      c.client.invoke(new c.Api.contacts.GetSaved())
    );
    return { ok: true, count: Array.isArray(saved) ? saved.length : 0 };
  });

const savedReset = (env, userClient) => async () =>
  connected(env, userClient, writeFailure, async (c) => {
    await runIn(env, 'contacts:saved-reset', () =>
      c.client.invoke(new c.Api.contacts.ResetSaved())
    );
    return { ok: true };
  });

const blockReplies =
  (env, userClient) =>
  async (body = {}) => {
    const flags = ['deleteMessage', 'deleteHistory', 'reportSpam'];
    if (
      !validMsgId(body.msgId) ||
      flags.some((k) => body[k] !== undefined && typeof body[k] !== 'boolean')
    ) {
      return bad('bad-request');
    }
    return connected(env, userClient, writeFailure, async (c) => {
      await runIn(env, 'block-from-replies', () =>
        c.client.invoke(
          new c.Api.contacts.BlockFromReplies({
            msgId: body.msgId,
            ...Object.fromEntries(
              flags.filter((k) => body[k]).map((k) => [k, true])
            ),
          })
        )
      );
      return { ok: true };
    });
  };

/** `context.uploads` has the page's uploads (`uploadOf`, `dropUpload`). */
export const createContactExtras = (env, context) => ({
  contactNote: setNote(env, context.userClient),
  contactToken: exportToken(env, context.userClient),
  contactTokenOpen: importToken(env, context.userClient),
  phoneResolve: resolvePhone(env, context.userClient),
  contactPhoto: setPhoto(env, context),
  birthdaySuggest: suggestBirthday(env, context.userClient),
  savedContacts: savedCount(env, context.userClient),
  savedContactsReset: savedReset(env, context.userClient),
  blockFromReplies: blockReplies(env, context.userClient),
});

/**
 * Close friends and adding a contact by phone number, as Telegram
 * Desktop has them (R-Y169; learned, never copied):
 * - `closeFriends()` — the user's contacts with who is a close friend now
 *   (contacts.getContacts, User.close_friend) →
 *   `{ ok, contacts: [{ id, name, username, closeFriend }] }`;
 * - `closeFriendsSet({ ids })` — the list saved as it is
 *   (contacts.editCloseFriends); an empty list clears it;
 * - `contactImport({ phone, firstName, lastName })` — one contact added
 *   by number (contacts.importContacts with an InputPhoneContact) →
 *   `{ ok, found: false }` when the number is not on Telegram, else
 *   `{ ok, found: true, contact: { id, name, username }, chat }`.
 * Telegram's errors become codes the page shows as text.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';
import { randomIdOf } from './telegram-send.js';

const CODES = {
  CONTACT_NAME_EMPTY: 'name-empty',
  PHONE_NUMBER_INVALID: 'phone-invalid',
  CONTACTS_TOO_MUCH: 'too-many',
  FLOOD_WAIT: 'flood',
  USER_ID_INVALID: 'bad-request',
};
const failure = failureOf(CODES);
const bad = (code) => ({ ok: false, error: code, code });

export const PHONE = /^\+\d{5,20}$/;
export const USER_ID = /^\d{1,20}$/;
export const MAX_NAME = 64;
export const MAX_IDS = 1000;

const textOf = (value) => String(value?.value ?? value);
const nameOf = (user) =>
  [user.firstName, user.lastName].filter(Boolean).join(' ') ||
  user.username ||
  textOf(user.id);

/** The user ids to save: distinct digit strings, up to 1000; else null. */
export const idsOf = (ids) => {
  if (!Array.isArray(ids) || ids.length > MAX_IDS) {
    return null;
  }
  const list = ids.map(String);
  return list.every((id) => USER_ID.test(id)) ? [...new Set(list)] : null;
};

/** A contact to add as Telegram takes it, or the code that refuses it. */
export const contactOf = (body = {}) => {
  const phone = String(body.phone ?? '').replace(/[\s()-]/g, '');
  const firstName = String(body.firstName ?? '').trim();
  const lastName = String(body.lastName ?? '').trim();
  if (!PHONE.test(phone)) {
    return bad('phone-invalid');
  }
  if (firstName === '') {
    return bad('name-empty');
  }
  if (
    Array.from(firstName).length > MAX_NAME ||
    Array.from(lastName).length > MAX_NAME
  ) {
    return bad('name-too-long');
  }
  return { ok: true, phone, firstName, lastName };
};

const listed = (user) => ({
  id: textOf(user.id),
  name: nameOf(user),
  username: user.username ?? null,
});

const createCloseFriends = (env, userClient) => async () =>
  connected(env, userClient, failure, async (c) => {
    const answer = await runIn(env, 'contacts:close-friends', () =>
      c.client.invoke(new c.Api.contacts.GetContacts({ hash: c.zero }))
    );
    const users = (answer?.users ?? []).filter(
      (u) => u && !u.self && !u.bot && !u.deleted
    );
    return {
      ok: true,
      contacts: users
        .map((u) => ({ ...listed(u), closeFriend: Boolean(u.closeFriend) }))
        .sort((a, b) => a.name.localeCompare(b.name)),
    };
  });

const createCloseFriendsSet =
  (env, userClient) =>
  async (body = {}) => {
    const ids = idsOf(body.ids);
    if (!ids) {
      return bad('bad-request');
    }
    return connected(env, userClient, failure, async (c) => {
      await runIn(env, 'contacts:close-friends-set', () =>
        c.client.invoke(
          new c.Api.contacts.EditCloseFriends({
            id: ids.map((id) => c.helpers.returnBigInt(id)),
          })
        )
      );
      return { ok: true, count: ids.length };
    });
  };

const createImport =
  (env, userClient) =>
  async (body = {}) => {
    const asked = contactOf(body);
    if (!asked.ok) {
      return asked;
    }
    return connected(env, userClient, failure, async (c) => {
      const answer = await runIn(env, 'contacts:import', () =>
        c.client.invoke(
          new c.Api.contacts.ImportContacts({
            contacts: [
              new c.Api.InputPhoneContact({
                clientId: randomIdOf(undefined, 0, c.helpers),
                phone: asked.phone,
                firstName: asked.firstName,
                lastName: asked.lastName,
              }),
            ],
          })
        )
      );
      const wanted = textOf(answer?.imported?.[0]?.userId ?? '');
      const user = (answer?.users ?? []).find((u) => textOf(u.id) === wanted);
      if (!wanted || !user) {
        return { ok: true, found: false };
      }
      const contact = listed(user);
      await Promise.resolve(
        env.peers?.remember?.(contact.id, user, {
          isUser: true,
          name: contact.name,
        })
      ).catch(() => {});
      return { ok: true, found: true, contact, chat: contact.id };
    });
  };

export const createContactsEdit = (env, { userClient }) => ({
  closeFriends: createCloseFriends(env, userClient),
  closeFriendsSet: createCloseFriendsSet(env, userClient),
  contactImport: createImport(env, userClient),
});

/**
 * The Contacts window's live statuses and the read time of one's own
 * message in a private chat, as Telegram Desktop shows them (R-Y189;
 * learned, never copied):
 * - `contactStatuses()` — every contact's last seen at once
 *   (contacts.getStatuses) → `{ ok, statuses: [{ id, online, lastSeen? }] }`,
 *   `lastSeen` an ISO time or recently / week / month (as chat info has it);
 * - `messageReadTime({ chat, id })` — when the person read the user's own
 *   message (messages.getOutboxReadDate) → `{ ok, read: true, date }`, `date`
 *   in ms. Telegram's refusals that still mean "read" answer
 *   `{ ok, read: true, date: null, code }`: `your-privacy` (the user hides
 *   their own read times), `peer-privacy` (the person hides theirs),
 *   `too-old` (older than 7 days); MESSAGE_NOT_READ_YET answers
 *   `{ ok, read: false }`. Other errors become codes.
 */

import { connected, runIn, failureOf } from './telegram-stickers.js';
import { statusOf } from './telegram-chat-info.js';

const CODES = {
  PEER_ID_INVALID: 'no-access',
  MESSAGE_ID_INVALID: 'not-found',
  PREMIUM_ACCOUNT_REQUIRED: 'premium',
  FLOOD_WAIT: 'flood',
};

// The refusals that mean the message was read, with the page's code.
const READ_ANYWAY = {
  YOUR_PRIVACY_RESTRICTED: 'your-privacy',
  USER_PRIVACY_RESTRICTED: 'peer-privacy',
  MESSAGE_TOO_OLD: 'too-old',
};

const failure = failureOf(CODES);
const PRIVATE = /^\d{1,20}$/;
const textOf = (value) => String(value?.value ?? value);
const errorName = (e) => String(e?.errorMessage ?? e?.message ?? '');

/** Telegram's error as the read-time answer. */
export const readFailure = (error) => {
  const name = errorName(error);
  if (name.includes('MESSAGE_NOT_READ_YET')) {
    return { ok: true, read: false };
  }
  const key = Object.keys(READ_ANYWAY).find((k) => name.includes(k));
  return key
    ? { ok: true, read: true, date: null, code: READ_ANYWAY[key] }
    : failure(error);
};

const createStatuses = (env, userClient) => async () =>
  connected(env, userClient, failure, async (c) => {
    const answer = await runIn(env, 'contacts:statuses', () =>
      c.client.invoke(new c.Api.contacts.GetStatuses())
    );
    return {
      ok: true,
      statuses: [...(Array.isArray(answer) ? answer : [])].map((one) => ({
        id: textOf(one.userId),
        ...statusOf(one.status),
      })),
    };
  });

const createReadTime =
  (env, userClient) =>
  async (body = {}) => {
    if (!PRIVATE.test(String(body.chat ?? '')) || !(Number(body.id) > 0)) {
      return { ok: false, error: 'bad-request', code: 'bad-request' };
    }
    return connected(env, userClient, readFailure, async (c) => {
      const answer = await runIn(env, `read-time:${body.chat}:${body.id}`, () =>
        env.connection.withPeer(c.client, body.chat, (peer) =>
          c.client.invoke(
            new c.Api.messages.GetOutboxReadDate({
              peer,
              msgId: Number(body.id),
            })
          )
        )
      );
      return { ok: true, read: true, date: Number(answer?.date) * 1000 };
    });
  };

export const createContactsActions = (env, context) => ({
  contactStatuses: createStatuses(env, context.userClient),
  messageReadTime: createReadTime(env, context.userClient),
});

/**
 * Custom emoji found by words, as Telegram Desktop's emoji status picker
 * and emoji panel search them for a Premium account (R-Y206; learned,
 * never copied):
 * - `customEmojiSearch({ q })` — the documents Telegram has for an emoji
 *   or a word (messages.searchCustomEmoji) → `{ ok, ids }`, decimal
 *   strings the page draws with the custom emoji pictures. Kept ten
 *   minutes by words.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';

const KEEP_MS = 10 * 60_000;
const KEPT_MAX = 40;
export const MAX_QUERY = 64;
const MAX_IDS = 200;

const failure = failureOf({
  PREMIUM_ACCOUNT_REQUIRED: 'premium-required',
  EMOTICON_EMPTY: 'bad-request',
});

/** The trimmed words, or null when empty or too long. */
export const queryOf = (q) => {
  const words = String(q ?? '').trim();
  return words && Array.from(words).length <= MAX_QUERY ? words : null;
};

export const createCustomEmojiSearch = (
  env,
  { userClient },
  { now = () => Date.now() } = {}
) => {
  const kept = new Map(); // words -> { at, answer }

  const customEmojiSearch = async ({ q } = {}) => {
    const words = queryOf(q);
    if (!words) {
      return { ok: false, error: 'bad request', code: 'bad-request' };
    }
    const entry = kept.get(words);
    if (entry && now() - entry.at < KEEP_MS) {
      return entry.answer;
    }
    const answer = await connected(env, userClient, failure, async (c) => {
      const list = await runIn(env, `custom-emoji:search:${words}`, () =>
        c.client.invoke(
          new c.Api.messages.SearchCustomEmoji({
            emoticon: words,
            hash: c.zero,
          })
        )
      );
      const ids = (list?.documentId ?? [])
        .map((id) => String(id?.value ?? id))
        .slice(0, MAX_IDS);
      return { ok: true, ids };
    });
    if (answer.ok) {
      kept.set(words, { at: now(), answer });
      while (kept.size > KEPT_MAX) {
        kept.delete(kept.keys().next().value);
      }
    }
    return answer;
  };

  return { customEmojiSearch };
};

/**
 * Custom emoji in messages, as Telegram's apps draw them (R-Y120;
 * learned, never copied). A message's `MessageEntityCustomEmoji` names a
 * document by id; this asks Telegram for those documents
 * (messages.getCustomEmojiDocuments), ids asked close together in one
 * request (up to 200), each document kept by id, and gives the page:
 *
 * - `customEmojiPicture({ id, full })` — the emoji's still picture: a
 *   webp sticker itself, else its thumbnail; `full` the animation (a
 *   .tgs, for the page's Lottie player) or the video (a webm), null for
 *   a still one. Each downloaded once into the app folder, with the
 *   sticker pictures' size limits.
 *
 * The page may name any id the message carried; one Telegram does not
 * know is refused (null). An expired file reference asks again once.
 */

import { promises as fs } from 'node:fs';
import path from 'node:path';
import { pickSize } from './telegram-media.js';
import { connect, formatOf, runIn, sniff } from './telegram-stickers.js';

const MAX_IDS = 200;
const BATCH_MS = 25;
const MAX_PICTURE = 512 * 1024;
const MAX_VIDEO = 4 * 1024 * 1024;
const ID = /^\d{1,20}$/;
const TYPE = /^(image\/|video\/|application\/x-tgsticker$)/;

const text = (value) =>
  value === null || value === undefined ? '' : String(value.value ?? value);

const bytesOf = (value) => {
  if (value instanceof Uint8Array) {
    return Buffer.from(value);
  }
  return typeof value?.bytes === 'string'
    ? Buffer.from(value.bytes, 'base64')
    : Buffer.alloc(0);
};

const expired = (error) =>
  /FILE_REFERENCE_(EXPIRED|INVALID)/.test(
    String(error?.errorMessage ?? error?.message ?? '')
  );

const readCache = async (file) => {
  try {
    const buffer = await fs.readFile(file);
    return buffer.length > 0 ? buffer : null;
  } catch {
    return null;
  }
};

// The documents, by id; ids asked within `delay` ms go in one request.
const createDocuments = (env, userClient, delay) => {
  const docs = new Map(); // id -> document, or null (Telegram has none)
  let batch = null;

  const ask = async (ids) => {
    const c = await connect(env, userClient);
    if (!c) {
      return;
    }
    const answer = await runIn(env, `custom-emoji:${ids[0]}`, () =>
      c.client.invoke(
        new c.Api.messages.GetCustomEmojiDocuments({
          documentId: ids.map((id) => c.helpers.returnBigInt(id)),
        })
      )
    );
    const list = Array.isArray(answer) ? answer : (answer?.documents ?? []);
    for (const id of ids) {
      docs.set(id, null);
    }
    for (const doc of list) {
      if (doc?.className === 'Document' && docs.has(text(doc.id))) {
        docs.set(text(doc.id), doc);
      }
    }
  };

  const open = () => {
    const made = { ids: new Set(), sent: false };
    made.done = new Promise((resolve) =>
      globalThis.setTimeout(resolve, delay)
    ).then(() => {
      made.sent = true;
      return ask([...made.ids]);
    });
    return made;
  };

  const lookup = async (id) => {
    if (docs.has(id)) {
      return docs.get(id);
    }
    if (!batch || batch.sent || batch.ids.size >= MAX_IDS) {
      batch = open();
    }
    batch.ids.add(id);
    await batch.done;
    return docs.get(id) ?? null;
  };

  return { lookup, forget: (id) => docs.delete(id) };
};

const pictureOf = (doc) => {
  if (formatOf(doc) === 'webp' && Number(doc.size ?? 0) <= MAX_PICTURE) {
    return { thumb: '', size: Number(doc.size) };
  }
  const thumb = pickSize(doc.thumbs ?? [], 'm');
  return thumb ? { thumb, size: MAX_PICTURE } : null;
};

const location = (c, doc, thumb) =>
  new c.Api.InputDocumentFileLocation({
    id: c.helpers.returnBigInt(text(doc.id)),
    accessHash: c.helpers.returnBigInt(text(doc.accessHash)),
    fileReference: bytesOf(doc.fileReference),
    thumbSize: thumb,
  });

const download = (env, c, name, doc, thumb, size) =>
  runIn(env, `file:custom-emoji:${name}`, async () => {
    const buffer = await c.client.downloadFile(location(c, doc, thumb), {
      dcId: Number(doc.dcId),
      fileSize: c.helpers.returnBigInt(String(Math.max(1, size))),
    });
    return buffer?.length ? Buffer.from(buffer) : null;
  });

// What the page shows for a document, or null when there is none.
const pictureFor = async (env, c, id, doc, full) => {
  if (full) {
    const size = Number(doc.size ?? 0);
    if (!['webm', 'tgs'].includes(formatOf(doc)) || size > MAX_VIDEO) {
      return null;
    }
    const buffer = await download(env, c, `${id}-full`, doc, '', size);
    return buffer ? { buffer, mimeType: doc.mimeType } : null;
  }
  const picture = pictureOf(doc);
  if (!picture) {
    return null;
  }
  const buffer = await download(
    env,
    c,
    `${id}-${picture.thumb || 'doc'}`,
    doc,
    picture.thumb,
    picture.size
  );
  return buffer ? { buffer, mimeType: sniff(buffer) } : null;
};

/** `env`: the account's; `userClient` its user client (null for a bot). */
export const createCustomEmoji = (
  env,
  { userClient, mediaDir },
  { delay = BATCH_MS } = {}
) => {
  const documents = createDocuments(env, userClient, delay);

  const fetchFresh = async (id, full, retry = true) => {
    const doc = await documents.lookup(id);
    const c = doc ? await connect(env, userClient) : null;
    if (!c) {
      return null;
    }
    try {
      return await pictureFor(env, c, id, doc, full);
    } catch (error) {
      if (!expired(error) || !retry) {
        throw error;
      }
      documents.forget(id);
      return fetchFresh(id, full, false);
    }
  };

  const customEmojiPicture = async ({ id, full = false } = {}) => {
    const key = String(id ?? '');
    if (!ID.test(key) || !mediaDir) {
      return null;
    }
    const name = `${key}${full ? '-full' : ''}`;
    const file = path.join(mediaDir, 'custom-emoji', name);
    const cached = await readCache(file);
    const type = cached ? String(await readCache(`${file}.type`)) : '';
    if (cached && TYPE.test(type)) {
      return { buffer: cached, mimeType: type };
    }
    const got = await fetchFresh(key, full);
    if (!got?.buffer) {
      return null;
    }
    await fs.mkdir(path.dirname(file), { recursive: true });
    await fs.writeFile(file, got.buffer);
    await fs.writeFile(`${file}.type`, got.mimeType);
    return got;
  };

  return { customEmojiPicture };
};

import { readLink } from './telegram-account-live.js';

const refreshForum = async (env, chat, read) => {
  if (!read?.forum) {
    return;
  }
  await env.actions?.forumTopics?.({ chat: String(chat), fresh: true });
};

/** Refresh one peer's counters without sending any read acknowledgement. */
export const createDialogState =
  (env, userChat) =>
  async ({ chat } = {}) => {
    if (!/^-?\d+$/.test(String(chat ?? ''))) {
      return { ok: false, code: 'bad-request' };
    }
    const target = await userChat(chat);
    if (!target) {
      return { ok: false, supported: false };
    }
    const { client, Api } = target;
    const id = `read:telegram:${chat}`;
    const before = await env.store.get(id);
    const result = await env.queue.run(`dialog-state:${chat}`, 'view', () =>
      env.connection.withPeer(client, String(chat), (peer) =>
        client.invoke(
          new Api.messages.GetPeerDialogs({
            peers: [new Api.InputDialogPeer({ peer })],
          })
        )
      )
    );
    const dialog = result?.dialogs?.[0];
    if (!dialog || !Number.isFinite(dialog.unreadCount)) {
      return { ok: false, code: 'dialog-unavailable' };
    }
    await refreshForum(env, chat, before);
    const latest = await env.store.get(id);
    // An update that arrived while Telegram answered is newer than this request.
    if (JSON.stringify(latest) !== JSON.stringify(before)) {
      return { ok: true, read: latest, changed: true };
    }
    const read = {
      ...before,
      ...readLink(String(chat), {
        inboxMaxId: dialog.readInboxMaxId,
        outboxMaxId: dialog.readOutboxMaxId,
        unreadCount: dialog.unreadCount,
        unreadTopId: dialog.topMessage,
        unreadMark: Boolean(dialog.unreadMark),
        unreadMentions: dialog.unreadMentionsCount,
        unreadReactions: dialog.unreadReactionsCount,
        muteUntil: Number(dialog.notifySettings?.muteUntil ?? 0),
        folder: Number(dialog.folderId ?? 0),
      }),
      checkedAt: new Date(env.now()).toISOString(),
    };
    await env.store.put(read);
    return { ok: true, read };
  };

/**
 * What the chat list's menu does to a chat, as Telegram's apps do it
 * (R-Y97; Telegram Desktop's dialogs menu, learned, never copied):
 *
 * - `pin` / `unpin` — messages.toggleDialogPin; Telegram refuses more
 *   pinned chats than the account may have (`PINNED_DIALOGS_TOO_MUCH`).
 * - `mute` (for `for` seconds, or for good) / `unmute` —
 *   account.updateNotifySettings on the chat.
 * - `archive` / `unarchive` — folders.editPeerFolders, folder 1 or 0.
 * - `unread` — messages.markDialogUnread: the chat's unread mark;
 *   `unmark` takes it off (the chat opened, as Desktop does).
 * - `read` — every message read (to the newest Telegram listed), the
 *   unread mark taken off.
 *
 * Each change is then written as the update Telegram sends the other
 * devices about it, through the same live handler, so the list moves at
 * once and the next update about it changes nothing.
 */

const SOURCE = 'telegram';

export const DIALOG_ACTIONS = Object.freeze([
  'pin',
  'unpin',
  'mute',
  'unmute',
  'archive',
  'unarchive',
  'read',
  'unread',
  'unmark',
]);

// Telegram's "for good": the largest 32-bit time.
export const MUTE_FOREVER = 2_147_483_647;

/** The Peer (as updates name it) of a marked chat id. */
export const peerOfChat = (chat) => {
  const id = String(chat);
  if (id.startsWith('-100')) {
    return { className: 'PeerChannel', channelId: id.slice(4) };
  }
  if (id.startsWith('-')) {
    return { className: 'PeerChat', chatId: id.slice(1) };
  }
  return { className: 'PeerUser', userId: id };
};

/** Until when a mute `for` seconds from `nowMs` lasts (Unix seconds). */
export const muteUntilOf = (seconds, nowMs) => {
  const span = Number(seconds);
  return Number.isFinite(span) && span > 0 && span < 366 * 24 * 3600
    ? Math.floor(nowMs / 1000) + Math.floor(span)
    : MUTE_FOREVER;
};

// The update Telegram's other devices get about the change.
const updateOf = (action, chat, extra) => {
  const peer = peerOfChat(chat);
  switch (action) {
    case 'pin':
    case 'unpin':
      return {
        className: 'UpdateDialogPinned',
        peer: { className: 'DialogPeer', peer },
        pinned: action === 'pin',
        folderId: extra.folder,
      };
    case 'mute':
    case 'unmute':
      return {
        className: 'UpdateNotifySettings',
        peer: { className: 'NotifyPeer', peer },
        notifySettings: { muteUntil: extra.muteUntil },
      };
    case 'archive':
    case 'unarchive':
      return {
        className: 'UpdateFolderPeers',
        folderPeers: [{ peer, folderId: action === 'archive' ? 1 : 0 }],
      };
    default:
      return {
        className: 'UpdateDialogUnreadMark',
        peer: { className: 'DialogPeer', peer },
        unread: action === 'unread',
      };
  }
};

/**
 * `env` is the account's; `userClient()` the connected user client or
 * null; `apply(client, result)` takes Telegram's answer through the
 * live handler.
 */
export const createDialogActions = (env, { userClient, apply }) => {
  const now = env.now ?? (() => Date.now());
  const readOf = (chat) => env.store.get(`read:${SOURCE}:${chat}`);

  const readAll = async (client, Api, chat, peer) => {
    const read = (await readOf(chat)) ?? {};
    const top = Number(read.unreadTopId ?? 0);
    if (top > Number(read.inboxMaxId ?? 0)) {
      const result = await client.invoke(
        chat.startsWith('-100')
          ? new Api.channels.ReadHistory({ channel: peer, maxId: top })
          : new Api.messages.ReadHistory({ peer, maxId: top })
      );
      env.catchUp?.observeResult(result);
      await env.live.readInbox?.({ chat, maxId: top });
    }
    if (read.unreadMark) {
      await client.invoke(
        new Api.messages.MarkDialogUnread({ peer, unread: false })
      );
    }
  };

  const ask = async (client, Api, { action, chat, peer, muteUntil }) => {
    if (action === 'pin' || action === 'unpin') {
      await client.invoke(
        new Api.messages.ToggleDialogPin({ peer, pinned: action === 'pin' })
      );
    } else if (action === 'mute' || action === 'unmute') {
      await client.invoke(
        new Api.account.UpdateNotifySettings({
          peer,
          settings: new Api.InputPeerNotifySettings({ muteUntil }),
        })
      );
    } else if (action === 'archive' || action === 'unarchive') {
      const input =
        typeof peer === 'object' ? peer : await client.getInputEntity(peer);
      return client.invoke(
        new Api.folders.EditPeerFolders({
          folderPeers: [
            new Api.InputFolderPeer({
              peer: input,
              folderId: action === 'archive' ? 1 : 0,
            }),
          ],
        })
      );
    } else if (action === 'unread' || action === 'unmark') {
      await client.invoke(
        new Api.messages.MarkDialogUnread({ peer, unread: action === 'unread' })
      );
    } else {
      await readAll(client, Api, chat, peer);
    }
    return null;
  };

  /** `{ chat, action, for? }` → `{ ok }`, or `{ ok: false, supported }`. */
  const dialogAction = async ({ chat, action, for: seconds } = {}) => {
    const client =
      chat && DIALOG_ACTIONS.includes(action) ? await userClient() : null;
    if (!client) {
      return { ok: false, supported: false };
    }
    const { Api } = await env.importer();
    const target = String(chat);
    const muteUntil =
      action === 'mute'
        ? muteUntilOf(seconds, now())
        : action === 'unmute'
          ? 0
          : undefined;
    const answer = await env.connection.withPeer(client, target, (peer) =>
      ask(client, Api, { action, chat: target, peer, muteUntil })
    );
    if (answer) {
      await apply(client, answer);
    }
    const folder = Number((await readOf(target))?.folder ?? 0) === 1 ? 1 : 0;
    await env.live.handle(
      client,
      updateOf(action, target, { folder, muteUntil })
    );
    return { ok: true, chat: target, action };
  };

  return { dialogAction };
};

/**
 * Cloud drafts kept in step with the other devices, as Telegram Desktop
 * does (R-Y207; learned, never copied):
 * - `syncDrafts()` — messages.getAllDrafts, whose answer is a set of
 *   UpdateDraftMessage; each goes through the live handler's draft writer
 *   (the same one that follows a draft typed on the phone), and a stored
 *   draft Telegram no longer lists (cleared elsewhere) is emptied →
 *   `{ ok, drafts, cleared }`.
 * - `clearAllDrafts()` — messages.clearAllDrafts, then every stored draft
 *   is emptied → `{ ok, cleared }`.
 * The per-chat save (saveDraft in telegram-account.js) is untouched.
 */

import { updatesOfResult } from './telegram-catchup.js';
import { updateEffect } from './telegram-updates.js';
import { connected, failureOf, runIn } from './telegram-stickers.js';

const failure = failureOf({ FLOOD_WAIT: 'flood' });

// The chats whose stored read link holds a draft.
const draftedChats = async (store) => {
  const links = await store.query(
    (link) =>
      link?.id?.startsWith('read:telegram:') &&
      typeof link.draft === 'string' &&
      link.draft !== ''
  );
  return links.map((link) => String(link.chat));
};

// Empties the stored drafts of `chats`; how many.
const emptyDrafts = async (env, chats) => {
  for (const chat of chats) {
    await env.live?.draft?.({ chat, text: '', date: null });
  }
  return chats.length;
};

/** The drafts an answer of getAllDrafts holds: `[{ chat, text, date }]`. */
export const draftsOf = (answer) =>
  updatesOfResult(answer)
    .filter((update) => update?.className === 'UpdateDraftMessage')
    .map((update) => updateEffect(update))
    .filter((effect) => effect?.kind === 'draft');

export const createDrafts = (env, { userClient }) => ({
  syncDrafts: async () =>
    connected(env, userClient, failure, async (c) => {
      const answer = await runIn(env, 'drafts:all', () =>
        c.client.invoke(new c.Api.messages.GetAllDrafts())
      );
      const listed = draftsOf(answer).filter((d) => d.text !== '');
      for (const draft of listed) {
        await env.live?.draft?.(draft);
      }
      const here = new Set(listed.map((d) => d.chat));
      const stale = (await draftedChats(env.store)).filter(
        (chat) => !here.has(chat)
      );
      return {
        ok: true,
        drafts: listed.length,
        cleared: await emptyDrafts(env, stale),
      };
    }),
  clearAllDrafts: async () =>
    connected(env, userClient, failure, async (c) => {
      await runIn(env, 'drafts:clear', () =>
        c.client.invoke(new c.Api.messages.ClearAllDrafts())
      );
      return {
        ok: true,
        cleared: await emptyDrafts(env, await draftedChats(env.store)),
      };
    }),
});

/**
 * Message effects, as Telegram Desktop and the mobile apps have them
 * (R-Y149; learned, never copied): a message in a private chat can be
 * sent with an effect (an emoji bursting over it when it arrives).
 * - `availableEffects()` — the effects Telegram offers
 *   (messages.getAvailableEffects, hash 0) → `{ ok, effects: [{ id,
 *   emoticon, premiumRequired? }], premium }`; ids are decimal strings,
 *   kept in memory for a few minutes. `premium` says whether the account
 *   has Premium (the page shows the Premium-only ones locked).
 * The animation documents are not fetched: the page plays the emoji.
 */

import { connected, runIn, failureOf } from './telegram-stickers.js';

const CODES = {
  PREMIUM_ACCOUNT_REQUIRED: 'premium',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);
const KEEP_MS = 10 * 60_000;

/** An effect id as the server takes it: a decimal string of a long. */
export const EFFECT_ID = /^\d{1,20}$/;

export const createEffects = (env, { userClient }) => {
  let kept = null; // { at, answer }
  const now = () => (env.now ?? Date.now)();

  const ask = (c) =>
    runIn(env, 'available-effects', async () => {
      const answer = await c.client.invoke(
        new c.Api.messages.GetAvailableEffects({ hash: 0 })
      );
      const effects = (answer?.effects ?? [])
        .filter((one) => one?.emoticon)
        .map((one) => ({
          id: String(one.id),
          emoticon: String(one.emoticon),
          ...(one.premiumRequired ? { premiumRequired: true } : {}),
        }));
      const me = await c.client.getMe?.().catch(() => null);
      return { ok: true, effects, premium: Boolean(me?.premium) };
    });

  const availableEffects = async () => {
    if (kept && now() - kept.at < KEEP_MS) {
      return kept.answer;
    }
    return connected(env, userClient, failure, async (c) => {
      const answer = await ask(c);
      kept = { at: now(), answer };
      return answer;
    });
  };

  return { availableEffects };
};

/**
 * What the emoji panel needs to offer custom emoji and category tabs, as
 * Telegram Desktop's does (R-Y214; learned, never copied):
 * - `emojiPanelInfo({ status })` → `{ ok, premium, groups }`: whether the
 *   account has Premium (users.getUsers, who may insert custom emoji
 *   anywhere) and Telegram's emoji groups ("Love", "Joy"…;
 *   messages.getEmojiGroups, or getEmojiStatusGroups for the status
 *   picker), each `{ title, iconEmojiId, emoticons }` — the custom emoji
 *   that draws its tab and the standard emoji it filters the grid to.
 *   Kept ten minutes by kind; a failure of the groups leaves `[]`.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';

const KEEP_MS = 10 * 60_000;
const MAX_GROUPS = 60;
const MAX_EMOTICONS = 400;

const failure = failureOf({});

const text = (value) => String(value?.value ?? value);

/** A group as the page takes it; null when it filters nothing. */
export const groupOf = (group) => {
  const emoticons = (group?.emoticons ?? [])
    .map(String)
    .filter(Boolean)
    .slice(0, MAX_EMOTICONS);
  return group?.title !== undefined && emoticons.length > 0
    ? {
        title: String(group.title),
        iconEmojiId: /^\d{1,20}$/.test(text(group.iconEmojiId))
          ? text(group.iconEmojiId)
          : null,
        emoticons,
      }
    : null;
};

const premiumOf = async (env, c) => {
  try {
    const users = await runIn(env, 'emoji-panel:self', () =>
      c.client.invoke(
        new c.Api.users.GetUsers({ id: [new c.Api.InputUserSelf()] })
      )
    );
    return Boolean(users?.[0]?.premium);
  } catch {
    return false;
  }
};

const groupsOf = async (env, c, status) => {
  const Request = status
    ? c.Api.messages.GetEmojiStatusGroups
    : c.Api.messages.GetEmojiGroups;
  try {
    const answer = await runIn(env, `emoji-panel:groups:${status}`, () =>
      c.client.invoke(new Request({ hash: 0 }))
    );
    return (answer?.groups ?? [])
      .map(groupOf)
      .filter(Boolean)
      .slice(0, MAX_GROUPS);
  } catch {
    return [];
  }
};

export const createEmojiGroups = (
  env,
  { userClient },
  { now = () => Date.now() } = {}
) => {
  const kept = new Map(); // 'status' | 'panel' -> { at, answer }

  const emojiPanelInfo = async ({ status = false } = {}) => {
    const key = status === true ? 'status' : 'panel';
    const entry = kept.get(key);
    if (entry && now() - entry.at < KEEP_MS) {
      return entry.answer;
    }
    const answer = await connected(env, userClient, failure, async (c) => ({
      ok: true,
      premium: await premiumOf(env, c),
      groups: await groupsOf(env, c, key === 'status'),
    }));
    if (answer.ok) {
      kept.set(key, { at: now(), answer });
    }
    return answer;
  };

  return { emojiPanelInfo };
};

/**
 * The words emoji are found by in the emoji panel's search and in the
 * ":word" suggestions of the message box, in the page's language, as
 * Telegram's apps find them (R-Y117, R-Y206; learned, never copied):
 * Telegram's own list (messages.getEmojiKeywords), asked once a day per
 * language and kept in memory and in the app's store. A list kept in the
 * store is brought up to date by what changed since its version
 * (messages.getEmojiKeywordsDifference) instead of being asked whole.
 *
 * - `emojiKeywords({ lang })` — `{ ok, lang, version, keywords }`,
 *   `keywords` `{ word: [emoji…] }`, the words in lower case.
 */

import { connect, runIn } from './telegram-stickers.js';

const KEEP_MS = 24 * 60 * 60_000;
// Telegram's lists are a few thousand words; more than this is not one.
const MAX_WORDS = 50_000;

const wordOf = (entry) =>
  String(entry.keyword ?? '')
    .trim()
    .toLowerCase();

/** Telegram's answer as `{ word: [emoji…] }`. */
export const keywordMap = (answer) => {
  const map = Object.create(null);
  let words = 0;
  for (const entry of answer?.keywords ?? []) {
    if (entry?.className !== 'EmojiKeyword' || words >= MAX_WORDS) {
      continue;
    }
    const word = wordOf(entry);
    const emoji = (entry.emoticons ?? []).map(String).filter(Boolean);
    if (word && emoji.length) {
      map[word] = [...new Set([...(map[word] ?? []), ...emoji])];
      words += 1;
    }
  }
  return map;
};

/** `map` with a difference's added and deleted words applied (a copy). */
export const applyDifference = (map, answer) => {
  const next = Object.create(null);
  Object.assign(next, map);
  for (const entry of answer?.keywords ?? []) {
    const word = wordOf(entry ?? {});
    const emoji = (entry?.emoticons ?? []).map(String).filter(Boolean);
    if (!word) {
      continue;
    }
    if (entry.className === 'EmojiKeyword' && emoji.length) {
      next[word] = [...new Set([...(next[word] ?? []), ...emoji])];
    } else if (entry.className === 'EmojiKeywordDeleted') {
      const left = (next[word] ?? []).filter((e) => !emoji.includes(e));
      if (left.length) {
        next[word] = left;
      } else {
        delete next[word];
      }
    }
  }
  return next;
};

const storeId = (lang) => `emojikw:${lang}`;

// The list kept in the store for a language, else null.
const readStored = async (env, lang) => {
  try {
    const link = await env.store?.get?.(storeId(lang));
    if (!link || !Number.isInteger(link.version) || !link.keywords) {
      return null;
    }
    const keywords = Object.create(null);
    Object.assign(keywords, link.keywords);
    return { version: link.version, keywords };
  } catch {
    return null;
  }
};

const writeStored = async (env, lang, version, keywords) => {
  try {
    await env.store?.put?.({
      id: storeId(lang),
      tokens: ['emoji', 'keywords', 'telegram'],
      kind: 'emoji-keywords',
      lang,
      version,
      keywords: { ...keywords },
    });
  } catch {
    // The list still serves from memory.
  }
};

// The list for a language: the stored one made current, else whole.
const fetchList = async (env, c, lang) => {
  const stored = await readStored(env, lang);
  if (stored) {
    const got = await runIn(env, `emoji:keywords-diff:${lang}`, () =>
      c.client.invoke(
        new c.Api.messages.GetEmojiKeywordsDifference({
          langCode: lang,
          fromVersion: stored.version,
        })
      )
    );
    const version = Number(got?.version ?? stored.version);
    if (version === stored.version) {
      return stored;
    }
    return { version, keywords: applyDifference(stored.keywords, got) };
  }
  const got = await runIn(env, `emoji:keywords:${lang}`, () =>
    c.client.invoke(new c.Api.messages.GetEmojiKeywords({ langCode: lang }))
  );
  return { version: Number(got?.version ?? 0), keywords: keywordMap(got) };
};

export const createEmojiKeywords = (
  env,
  { userClient },
  { now = () => Date.now() } = {}
) => {
  const kept = new Map(); // lang -> { at, answer }
  const asking = new Map(); // lang -> the answer coming

  const ask = async (lang) => {
    const c = await connect(env, userClient);
    if (!c) {
      return { ok: false, supported: false };
    }
    const { version, keywords } = await fetchList(env, c, lang);
    await writeStored(env, lang, version, keywords);
    const answer = { ok: true, lang, version, keywords };
    kept.set(lang, { at: now(), answer });
    return answer;
  };

  const emojiKeywords = async ({ lang = 'en' } = {}) => {
    const key = String(lang);
    const entry = kept.get(key);
    if (entry && now() - entry.at < KEEP_MS) {
      return entry.answer;
    }
    if (!asking.has(key)) {
      asking.set(
        key,
        ask(key).finally(() => asking.delete(key))
      );
    }
    return asking.get(key);
  };

  return { emojiKeywords };
};

/**
 * Emoji statuses, as Telegram Desktop and the mobile apps have them
 * (R-Y162; learned, never copied): a Premium account shows a custom emoji
 * after its name, for a while or until it changes it.
 * - `emojiStatuses()` → `{ ok, premium, current, defaults, recent }`:
 *   account.getDefaultEmojiStatuses and account.getRecentEmojiStatuses
 *   (hash 0); `current` is the account's own status, each status
 *   `{ id, until? }` with `id` the custom emoji's document id as a
 *   decimal string and `until` Unix seconds.
 * - `emojiStatusSet({ documentId|null, until? })` — account.updateEmojiStatus
 *   with EmojiStatus{documentId, until} or EmojiStatusEmpty (null removes
 *   it). Setting one is Premium-only: Telegram's refusal is the code
 *   `premium`.
 * - `statusOf(value)` is the status a user or channel entity carries (a
 *   collectible one by its emoji), `statusFields(entity, prefix)` its flat
 *   fields on a stored link, for the chat list and the messages.
 */

import { connected, runIn, failureOf } from './telegram-stickers.js';

const CODES = {
  PREMIUM_ACCOUNT_REQUIRED: 'premium',
  EMOJI_STATUS_INVALID: 'invalid',
  DOCUMENT_INVALID: 'invalid',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);

/** A document id as the server takes it: a decimal string of a long. */
export const DOCUMENT_ID = /^\d{1,20}$/;
export const MAX_UNTIL_SECONDS = 366 * 24 * 3600;

const text = (value) => String(value?.value ?? value);

/** `{ id, until? }` of an EmojiStatus (or a collectible), else null. */
export const statusOf = (value) => {
  const id = value?.documentId;
  if (id === undefined || id === null) {
    return null;
  }
  const until = Number(value.until);
  return {
    id: text(id),
    ...(Number.isFinite(until) && until > 0 ? { until } : {}),
  };
};

/**
 * The flat fields a stored link keeps for an entity's status: strings
 * and numbers compare with `!==`, so a re-sync rewrites only a changed
 * one. `prefix` is `senderEmoji` or `emoji`: `<prefix>Status`/`Until`.
 * A user seen without a status clears the stored one (null); an entity
 * that is not there says nothing.
 */
export const statusFields = (entity, prefix) => {
  if (!entity || typeof entity !== 'object') {
    return {};
  }
  const status = statusOf(entity.emojiStatus);
  return {
    [`${prefix}Status`]: status?.id ?? null,
    [`${prefix}Until`]: status?.until ?? null,
  };
};

const listOf = (answer) =>
  (answer?.statuses ?? []).map(statusOf).filter(Boolean);

export const createEmojiStatus = (env, { userClient }) => {
  const now = () => (env.now ?? Date.now)();

  const emojiStatuses = async () =>
    connected(env, userClient, failure, async (c) => {
      const hash = c.helpers.returnBigInt('0');
      const ask = (name) =>
        runIn(env, `emoji-status:${name}`, () =>
          c.client.invoke(new c.Api.account[name]({ hash }))
        );
      const defaults = await ask('GetDefaultEmojiStatuses');
      const recent = await ask('GetRecentEmojiStatuses');
      const me = await c.client.getMe?.().catch(() => null);
      return {
        ok: true,
        premium: Boolean(me?.premium),
        current: statusOf(me?.emojiStatus),
        defaults: listOf(defaults),
        recent: listOf(recent),
      };
    });

  const emojiStatusSet = async ({ documentId = null, until } = {}) => {
    const seconds = now() / 1000;
    const badUntil =
      until !== undefined &&
      !(
        Number.isInteger(until) &&
        until > seconds &&
        until <= seconds + MAX_UNTIL_SECONDS
      );
    if (
      (documentId !== null && !DOCUMENT_ID.test(String(documentId))) ||
      badUntil
    ) {
      return { ok: false, error: 'invalid', code: 'invalid' };
    }
    return connected(env, userClient, failure, async (c) => {
      const status =
        documentId === null
          ? new c.Api.EmojiStatusEmpty()
          : new c.Api.EmojiStatus({
              documentId: c.helpers.returnBigInt(String(documentId)),
              ...(until === undefined ? {} : { until }),
            });
      await runIn(env, 'emoji-status:set', () =>
        c.client.invoke(
          new c.Api.account.UpdateEmojiStatus({ emojiStatus: status })
        )
      );
      return { ok: true };
    });
  };

  return { emojiStatuses, emojiStatusSet };
};

/**
 * Ephemeral messages (layer 232; R-Y223; learned, never copied): a bot's
 * message shown to one user only (a group's welcome message, a bot's
 * private answer in a group). They are not part of the chat's history
 * and are never fetched: they arrive as updates only, so they are kept
 * in the store under their own id kind,
 *
 *   eph:telegram:<chat>:<id>   `ephemeral: true`, the message shaped as a
 *                              normal `msg:` link (text, `raw` with its
 *                              entities, media and inline keyboard),
 *                              `deleted` once Telegram deleted it
 *
 * so nothing that reads `msg:` links (repairs, history, counts, the chat
 * list) ever sees them. The page draws them in the chat by date.
 *
 * - `ephemeralMessages({ chat })` — the chat's ephemeral messages kept;
 * - `ephemeralCallback({ chat, id, data })` — a press on an inline
 *   callback button of one (ephemeral.getCallbackAnswer), answered like
 *   a normal bot button (./telegram-bots.js). Only on a click.
 *
 * Message text is never logged.
 */

import { answerOf } from './telegram-bots.js';
import { messageSenderId } from './telegram-updates.js';
import { connected, failureOf, runIn } from './telegram-stickers.js';

import { markDeleted as tombstone } from '../storage/soft-delete.js';

const SOURCE = 'telegram';
const CHAT = /^-?\d{1,20}$/;
const BASE64 = /^[A-Za-z0-9+/]{1,88}={0,2}$/;

const CODES = {
  DATA_INVALID: 'data-invalid',
  MESSAGE_ID_INVALID: 'message-gone',
  PEER_ID_INVALID: 'chat-gone',
  BOT_RESPONSE_TIMEOUT: 'timeout',
};
const failure = failureOf(CODES);

export const ephemeralLinkId = (chat, id) => `eph:${SOURCE}:${chat}:${id}`;

/** The `msg:`-shaped link `toLinks` made, moved to the `eph:` kind. */
export const ephemeralLinkOf = (link, message) => ({
  ...link,
  id: ephemeralLinkId(link.chat, message.id),
  tokens: ['ephemeral', SOURCE, String(link.chat), String(message.id)],
  children: [],
  ephemeral: true,
  welcome: Boolean(message.welcomeTemplate),
  ...(message.topMsgId ? { topMsgId: Number(message.topMsgId) } : {}),
});

/**
 * The live handler's writers for the two effects (./telegram-account-live.js
 * hands in its `store`, its store write `merge(link)`, the sync's message
 * mapping `toLinks(dialog, messages)`, `dialogFor(client, chat, entities)`
 * and `entityOf(entities, id)`). A new or edited message is stored,
 * replacing what its id held; a delete marks the messages `deleted`.
 * Each answers whether the page needs a refresh.
 */
export const ephemeralLive = ({
  store,
  merge,
  toLinks,
  dialogFor,
  entityOf,
}) => ({
  ephemeral: async (client, { chat, message, entities }) => {
    const dialog = await dialogFor(client, chat, entities);
    const sender = entityOf(entities, messageSenderId(message));
    const [link] = toLinks(dialog, [
      { ...message, editDate: null, sender: message.sender ?? sender },
    ]);
    if (!link) {
      return false;
    }
    await merge({ ...ephemeralLinkOf(link, message), deleted: false });
    return true;
  },
  'ephemeral-delete': async (_client, { chat, ids }) => {
    let changed = false;
    for (const id of ids) {
      const link = await store.get(ephemeralLinkId(chat, id));
      if (link && !link.deleted) {
        await store.put(
          tombstone(link, { by: 'telegram', reason: 'deleted-on-network' })
        );
        changed = true;
      }
    }
    return changed;
  },
});

const validPress = ({ chat, id, data } = {}) =>
  CHAT.test(String(chat ?? '')) &&
  Number.isInteger(id) &&
  id > 0 &&
  typeof data === 'string' &&
  BASE64.test(data);

export const createEphemeral = (env, { userClient }) => {
  const ephemeralMessages = async ({ chat } = {}) => {
    if (!CHAT.test(String(chat ?? '')) || !env.store?.query) {
      return { ok: false, messages: [] };
    }
    const prefix = ephemeralLinkId(chat, '');
    const messages = await env.store.query(
      (l) => l?.id?.startsWith(prefix) && !l.deleted
    );
    return { ok: true, messages };
  };

  const ephemeralCallback = async (body = {}) => {
    if (!validPress(body)) {
      return { ok: false, error: 'bad request', code: 'failed' };
    }
    const answer = await connected(env, userClient, failure, async (c) =>
      answerOf(
        await runIn(env, `ephemeral:${body.chat}:${body.id}:${body.data}`, () =>
          env.connection.withPeer(c.client, String(body.chat), (peer) =>
            c.client.invoke(
              new c.Api.ephemeral.GetCallbackAnswer({
                peer,
                id: body.id,
                data: Buffer.from(body.data, 'base64'),
              })
            )
          )
        )
      )
    );
    // A bot that did not answer in time still got the press.
    return answer.code === 'timeout'
      ? { ok: true, message: null, alert: false, url: null }
      : answer;
  };

  return { ephemeralMessages, ephemeralCallback };
};

/**
 * The HTML pages of an exported chat (R-Y186; Telegram Desktop's export
 * has `messages.html`, `messages2.html`, … with a small stylesheet; the
 * markup and the style here are our own): up to 1000 messages a page,
 * each page linking to the next, the media shown from relative links.
 * The pages are plain English, as the files are data for the user to
 * keep, not the app's screen.
 */

import { promises as fs } from 'node:fs';
import path from 'node:path';

export const PER_PAGE = 1000;

export const EXPORT_CSS = `body{margin:0;background:#fff;color:#222;font:14px/1.45 -apple-system,"Segoe UI",Roboto,sans-serif}
.page_header{background:#527da3;color:#fff;padding:14px 20px;font-size:17px}
.page_body{max-width:640px;margin:0 auto;padding:12px 16px}
.message{padding:4px 0;border-radius:6px}
.message .body{padding:4px 8px}
.message.default.joined .body{padding-top:0}
.message.service{text-align:center;color:#6c7a89}
.from_name{color:#3a6d99;font-weight:600}
.date{float:right;margin-left:12px}
.details,.status{color:#7a8794;font-size:12px}
.reply_to,.forwarded{border-left:3px solid #8fb3d1;padding-left:8px;margin:2px 0}
.text{white-space:normal;word-wrap:break-word}
.photo,.sticker,video{max-width:100%;max-height:420px;border-radius:6px;display:block}
audio{width:100%}
.media_file{display:block;padding:6px 8px;background:#eef3f7;border-radius:6px;margin:3px 0;color:#222;text-decoration:none}
.spoiler{background:#cdd5db;color:transparent;border-radius:3px}
.spoiler:hover{color:inherit;background:none}
blockquote{margin:2px 0;padding-left:8px;border-left:3px solid #8fb3d1}
pre{background:#f1f4f6;padding:6px;border-radius:4px;overflow:auto}
a{color:#2f6fa7}
.pagination{display:block;text-align:center;padding:14px;margin:12px 0}
@media (prefers-color-scheme:dark){body{background:#17212b;color:#e8eef3}.message .body{color:#e8eef3}.media_file{background:#22313f;color:#e8eef3}.from_name,a{color:#7ab6e6}pre{background:#202b36}}
`;

export const esc = (value) =>
  String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');

// Only web, mail and Telegram links become links.
const safeHref = (url) =>
  /^(https?:\/\/|mailto:|tg:)/i.test(String(url)) ? String(url) : null;

const WRAP = Object.freeze({
  bold: ['<strong>', '</strong>'],
  italic: ['<em>', '</em>'],
  underline: ['<u>', '</u>'],
  strikethrough: ['<s>', '</s>'],
  code: ['<code>', '</code>'],
  pre: ['<pre>', '</pre>'],
  spoiler: ['<span class="spoiler">', '</span>'],
  blockquote: ['<blockquote>', '</blockquote>'],
});

const wrapperOf = (entity, text) => {
  if (WRAP[entity.type]) {
    return WRAP[entity.type];
  }
  const url =
    entity.type === 'text_link'
      ? entity.extras?.href
      : entity.type === 'link'
        ? text
        : entity.type === 'email'
          ? `mailto:${text}`
          : null;
  const href = url ? safeHref(url) : null;
  return href ? [`<a href="${esc(href)}">`, '</a>'] : ['', ''];
};

/** A message's text, from `segmentsOf` pieces, as HTML. */
export const textHtml = (segments) =>
  segments
    .map((piece) => {
      const wraps = piece.covers.map((e) => wrapperOf(e, piece.text));
      return (
        wraps.map(([open]) => open).join('') +
        esc(piece.text).replace(/\n/g, '<br>') +
        wraps
          .map(([, close]) => close)
          .reverse()
          .join('')
      );
    })
    .join('');

const SERVICE_WORDS = Object.freeze({
  create_group: 'created group',
  create_channel: 'created channel',
  edit_group_title: 'changed group title to',
  edit_group_photo: 'changed group photo',
  delete_group_photo: 'deleted group photo',
  invite_members: 'invited',
  remove_members: 'removed',
  join_group_by_link: 'joined group by link',
  join_group_by_request: 'joined group by request',
  pin_message: 'pinned a message',
  clear_history: 'cleared the history',
  phone_call: 'made a call',
  topic_created: 'created topic',
});

const serviceText = (msg) => {
  const words =
    SERVICE_WORDS[msg.action] ?? String(msg.action ?? '').replace(/_/g, ' ');
  const extra = [msg.title, ...(msg.members ?? [])].filter(Boolean).join(', ');
  return `${esc(msg.actor ?? '')} ${esc(words)}${extra ? ` ${esc(extra)}` : ''}`;
};

const humanSize = (bytes) => {
  const n = Number(bytes) || 0;
  if (n >= 1024 * 1024) {
    return `${(n / 1024 / 1024).toFixed(1)} MB`;
  }
  return n >= 1024 ? `${Math.round(n / 1024)} KB` : `${n} B`;
};

const note = (text) => `<div class="status details">${esc(text)}</div>`;

const fileHtml = (msg) => {
  const target = msg.file;
  if (target.startsWith('(')) {
    return note(target);
  }
  const src = esc(target);
  switch (msg.media_type) {
    case 'video_file':
    case 'animation':
    case 'video_message':
      return `<video controls src="${src}"></video>`;
    case 'voice_message':
    case 'audio_file':
      return `<audio controls src="${src}"></audio>`;
    case 'sticker':
      return `<img class="sticker" src="${src}" alt="${esc(msg.sticker_emoji ?? '')}">`;
    default:
      return `<a class="media_file block_link" href="${src}">${esc(msg.file_name ?? path.basename(target))}<span class="details"> ${humanSize(msg.file_size)}</span></a>`;
  }
};

const mediaHtml = (msg) => {
  if (msg.photo) {
    return msg.photo.startsWith('(')
      ? note(msg.photo)
      : `<a href="${esc(msg.photo)}"><img class="photo" src="${esc(msg.photo)}" alt=""></a>`;
  }
  if (msg.file) {
    return fileHtml(msg);
  }
  if (msg.location_information) {
    const { latitude, longitude } = msg.location_information;
    return note(`Location: ${latitude}, ${longitude}`);
  }
  if (msg.contact_information) {
    const c = msg.contact_information;
    return note(`Contact: ${c.first_name} ${c.last_name} ${c.phone_number}`);
  }
  return msg.poll ? note(`Poll: ${msg.poll.question}`) : '';
};

const JOIN_WINDOW_S = 300;

const joinsPrevious = (msg, prev) =>
  Boolean(prev) &&
  prev.type === 'message' &&
  msg.type === 'message' &&
  prev.from_id === msg.from_id &&
  !msg.forwarded_from &&
  Number(msg.date_unixtime) - Number(prev.date_unixtime) <= JOIN_WINDOW_S;

/** One message (the JSON entry and its text's pieces) as HTML. */
export const messageHtml = (msg, segments, prev = null) => {
  if (msg.type === 'service') {
    return `<div class="message service" id="message${msg.id}"><div class="body details">${serviceText(msg)}</div></div>\n`;
  }
  const joined = joinsPrevious(msg, prev);
  const reply = msg.reply_to_message_id
    ? `<div class="reply_to details">In reply to <a href="#message${msg.reply_to_message_id}">this message</a></div>`
    : '';
  const forwarded = msg.forwarded_from
    ? `<div class="forwarded details">Forwarded from ${esc(msg.forwarded_from)}</div>`
    : '';
  const text = textHtml(segments);
  return [
    `<div class="message default clearfix${joined ? ' joined' : ''}" id="message${msg.id}"><div class="body">`,
    `<div class="pull_right date details" title="${esc(msg.date)}">${esc(msg.date.slice(11, 16))}</div>`,
    joined ? '' : `<div class="from_name">${esc(msg.from ?? '')}</div>`,
    forwarded,
    reply,
    mediaHtml(msg),
    text ? `<div class="text">${text}</div>` : '',
    '</div></div>\n',
  ].join('');
};

const MONTHS = [
  'January',
  'February',
  'March',
  'April',
  'May',
  'June',
  'July',
  'August',
  'September',
  'October',
  'November',
  'December',
];

const dayHtml = (day) => {
  const [y, m, d] = day.split('-').map(Number);
  return `<div class="message service"><div class="body details">${d} ${MONTHS[m - 1]} ${y}</div></div>\n`;
};

export const pageHtml = ({ title, body, next }) =>
  `<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<title>Exported Data</title>
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<link href="css/style.css" rel="stylesheet">
</head>
<body>
<div class="page_wrap">
<div class="page_header"><div class="content"><div class="text bold">${esc(title)}</div></div></div>
<div class="page_body chat_page"><div class="history">
${body}${next ? `<a class="pagination block_link" href="${esc(next)}">Next messages</a>\n` : ''}</div></div>
</div>
</body>
</html>
`;

export const pageName = (n) =>
  n === 1 ? 'messages.html' : `messages${n}.html`;

/**
 * Writes the pages as messages come: `add(msg, segments)`, `close()`.
 * A page is written once the next one begins (it must link to it), the
 * last one on `close`.
 */
export const createHtmlWriter = async ({ dir, title, perPage = PER_PAGE }) => {
  await fs.mkdir(path.join(dir, 'css'), { recursive: true });
  await fs.writeFile(path.join(dir, 'css', 'style.css'), EXPORT_CSS);
  let page = 1;
  let count = 0;
  let parts = [];
  let prev = null;
  let day = null;
  const flush = (next) =>
    fs.writeFile(
      path.join(dir, pageName(page)),
      pageHtml({ title, body: parts.join(''), next })
    );
  return {
    pages: () => (count > 0 ? page : 0),
    add: async (msg, segments) => {
      if (count > 0 && count % perPage === 0) {
        await flush(pageName(page + 1));
        page += 1;
        parts = [];
        prev = null;
        day = null;
      }
      const today = msg.date.slice(0, 10);
      if (today !== day) {
        parts.push(dayHtml(today));
        day = today;
        prev = null;
      }
      parts.push(messageHtml(msg, segments, prev));
      prev = msg;
      count += 1;
    },
    close: async () => {
      if (count === 0) {
        parts = [
          `<div class="message service"><div class="body details">No messages</div></div>\n`,
        ];
      }
      await flush(null);
    },
  };
};

/**
 * What an exported message carries besides its words (R-Y186; Telegram
 * Desktop's export, learned, never copied): which kind of file it is,
 * which of the export's folders it goes to, whether the user's choices
 * (kinds on or off, the size limit) let it be downloaded, and the JSON
 * fields that name the file or tell why there is none. Places, contacts
 * and polls need no file: they are written into the message itself.
 */

import path from 'node:path';
import { docKind, mediaOf } from './telegram-media.js';
import { safeName, stampOf } from './telegram-export-paths.js';

export const OPTION_OF = Object.freeze({
  photo: 'photos',
  video: 'videos',
  round: 'roundVideo',
  voice: 'voice',
  sticker: 'stickers',
  gif: 'gifs',
  audio: 'files',
  file: 'files',
});

export const FOLDER_OF = Object.freeze({
  photo: 'photos',
  video: 'video_files',
  gif: 'video_files',
  round: 'round_video_messages',
  voice: 'voice_messages',
  sticker: 'stickers',
  audio: 'files',
  file: 'files',
});

// The size limit applies to videos and files, as in Desktop.
const LIMITED = new Set(['video', 'gif', 'audio', 'file']);

const MEDIA_TYPE = Object.freeze({
  video: 'video_file',
  gif: 'animation',
  round: 'video_message',
  voice: 'voice_message',
  sticker: 'sticker',
  audio: 'audio_file',
});

const BASE = Object.freeze({
  photo: 'photo',
  video: 'video',
  gif: 'animation',
  round: 'video',
  voice: 'audio',
  sticker: 'sticker',
  audio: 'audio',
  file: 'file',
});

export const NOTE_TOO_LARGE =
  '(File exceeds maximum size. Change data exporting settings to download.)';
export const NOTE_OFF =
  '(File not included. Change data exporting settings to download.)';
export const NOTE_FAILED = '(File unavailable, please try again later.)';

const MIME_EXT = Object.freeze({
  'image/jpeg': 'jpg',
  'image/png': 'png',
  'image/webp': 'webp',
  'image/gif': 'gif',
  'video/mp4': 'mp4',
  'video/webm': 'webm',
  'audio/ogg': 'ogg',
  'audio/mpeg': 'mp3',
  'audio/mp4': 'm4a',
  'application/x-tgsticker': 'tgs',
  'application/pdf': 'pdf',
  'application/zip': 'zip',
  'text/plain': 'txt',
});

const SIZE_ORDER = ['w', 'y', 'x', 'm', 's'];

const sizeOf = (s) =>
  Array.isArray(s?.sizes) ? Math.max(0, ...s.sizes) : Number(s?.size ?? 0);

// The biggest real size of a photo (not the inline stripped preview).
const bestSize = (photo) => {
  const real = (photo?.sizes ?? []).filter(
    (s) =>
      s?.className === 'PhotoSize' || s?.className === 'PhotoSizeProgressive'
  );
  for (const type of SIZE_ORDER) {
    const hit = real.find((s) => s.type === type);
    if (hit) {
      return hit;
    }
  }
  return real.at(-1) ?? null;
};

const attrOf = (doc, className) =>
  (doc?.attributes ?? []).find((a) => a?.className === className);

const photoInfo = (photo) => {
  const size = bestSize(photo);
  return size && photo.id !== undefined
    ? {
        kind: 'photo',
        file: photo,
        thumb: size.type,
        size: sizeOf(size),
        ext: 'jpg',
        mime: 'image/jpeg',
        meta: { width: size.w, height: size.h },
      }
    : null;
};

const kindOfDocument = (doc) => {
  const kind = docKind(doc);
  return kind === 'video' && attrOf(doc, 'DocumentAttributeVideo')?.roundMessage
    ? 'round'
    : kind;
};

const extOf = (kind, doc, original) => {
  const named = path.extname(original ?? '').slice(1);
  return (
    named ||
    MIME_EXT[doc.mimeType] ||
    (kind === 'voice' ? 'ogg' : kind === 'round' ? 'mp4' : 'bin')
  );
};

// Sizes, length and tags a document's attributes tell.
const docMeta = (kind, doc) => {
  const video = attrOf(doc, 'DocumentAttributeVideo');
  const audio = attrOf(doc, 'DocumentAttributeAudio');
  const image = attrOf(doc, 'DocumentAttributeImageSize');
  const duration = video?.duration ?? audio?.duration;
  const tags = kind === 'audio' ? audio : null;
  return {
    media_type: MEDIA_TYPE[kind],
    mime_type: doc.mimeType,
    duration_seconds:
      duration === undefined ? undefined : Math.round(Number(duration)),
    width: video?.w ?? image?.w,
    height: video?.h ?? image?.h,
    sticker_emoji: attrOf(doc, 'DocumentAttributeSticker')?.alt,
    performer: tags?.performer,
    title: tags?.title,
  };
};

const documentInfo = (doc) => {
  const kind = kindOfDocument(doc);
  const original = attrOf(doc, 'DocumentAttributeFilename')?.fileName;
  return {
    kind,
    file: doc,
    thumb: '',
    size: Number(doc.size ?? 0),
    ext: extOf(kind, doc, original),
    mime: doc.mimeType,
    original,
    meta: docMeta(kind, doc),
  };
};

/**
 * The file a message carries: `{ kind, option, folder, limited, size,
 * ext, mime, file, thumb, meta, original? }`, or null (no file, an
 * expired or locked one).
 */
export const fileInfoOf = (raw) => {
  const media = mediaOf(raw);
  let info = null;
  if (media?.className === 'MessageMediaPhoto') {
    info = photoInfo(media.photo);
  } else if (
    media?.className === 'MessageMediaDocument' &&
    media.document?.id
  ) {
    info = documentInfo(media.document);
  }
  return info
    ? {
        ...info,
        option: OPTION_OF[info.kind],
        folder: FOLDER_OF[info.kind],
        limited: LIMITED.has(info.kind),
      }
    : null;
};

/** `null` to download, else the note that replaces the file's path. */
export const skipNote = (info, options) => {
  if (!options.media?.[info.option]) {
    return NOTE_OFF;
  }
  const limit = Number(options.sizeLimitMb) * 1024 * 1024;
  return info.limited && info.size > limit ? NOTE_TOO_LARGE : null;
};

/** The file's name inside its folder, e.g. `photo_3@23-10-2026_14-05-09.jpg`. */
export const wantedName = (info, { index, at }) =>
  info.original
    ? safeName(info.original)
    : `${BASE[info.kind]}_${index}@${stampOf(at * 1000)}.${info.ext}`;

/** The message's JSON fields for its file: the path, or the note. */
export const mediaFields = (info, target) => {
  const meta = Object.fromEntries(
    Object.entries(info.meta).filter(([, v]) => v !== undefined)
  );
  if (info.kind === 'photo') {
    return {
      photo: target,
      photo_file_size: info.size || undefined,
      ...meta,
    };
  }
  const { media_type: type, ...rest } = meta;
  return {
    file: target,
    ...(info.original ? { file_name: info.original } : {}),
    file_size: info.size || undefined,
    ...(type ? { media_type: type } : {}),
    ...rest,
  };
};

const words = (value) =>
  typeof value === 'string' ? value : String(value?.text ?? '');

const pollOf = (media) => {
  const results = media.results?.results ?? [];
  return {
    question: words(media.poll?.question),
    closed: Boolean(media.poll?.closed),
    total_voters: Number(media.results?.totalVoters ?? 0),
    answers: (media.poll?.answers ?? []).map((a) => {
      const hit = results.find((r) => r.option?.bytes === a.option?.bytes);
      return {
        text: words(a.text),
        voters: Number(hit?.voters ?? 0),
        chosen: Boolean(hit?.chosen),
      };
    }),
  };
};

/** Places, contacts and polls: written into the message, no file. */
export const inlineMediaOf = (raw) => {
  const media = raw?.media;
  switch (media?.className) {
    case 'MessageMediaGeo':
    case 'MessageMediaGeoLive':
      return {
        location_information: {
          latitude: media.geo?.lat,
          longitude: media.geo?.long,
        },
      };
    case 'MessageMediaContact':
      return {
        contact_information: {
          first_name: media.firstName ?? '',
          last_name: media.lastName ?? '',
          phone_number: media.phoneNumber ?? '',
        },
      };
    case 'MessageMediaPoll':
      return { poll: pollOf(media) };
    default:
      return {};
  }
};

/**
 * What an export writes to its folder (R-Y186): `result.json` as Telegram
 * Desktop's machine-readable export has it (`name`, `type`, `id`,
 * `messages[]`), written message by message so a cancelled export still
 * leaves a valid file, and/or the HTML pages (./telegram-export-html.js);
 * plus the chat's name, kind and id as the export's header says them.
 */

import { promises as fs } from 'node:fs';
import path from 'node:path';
import { createHtmlWriter } from './telegram-export-html.js';

/** The key the names map uses for a chat id: `user7`, `chat5`, `channel9`. */
export const keyOfChat = (chat) => {
  const id = String(chat);
  if (id.startsWith('-100')) {
    return `channel${id.slice(4)}`;
  }
  return id.startsWith('-') ? `chat${id.slice(1)}` : `user${id}`;
};

/** The chat's number in the export (Desktop writes it without the sign). */
export const exportIdOf = (chat) => {
  const key = keyOfChat(chat);
  return Number(key.replace(/^\D+/, ''));
};

/**
 * `{ name, type, id }` of the chat, from what the first answer told of it
 * (`entities`: key → `{ title, bot, self, username, megagroup }`).
 */
export const chatMeta = ({ chat, chatName, entities }) => {
  const key = keyOfChat(chat);
  const known = entities.get(key) ?? {};
  const name = known.title || chatName || `chat ${exportIdOf(chat)}`;
  let type = 'private_group';
  if (key.startsWith('user')) {
    type = known.self
      ? 'saved_messages'
      : known.bot
        ? 'bot_chat'
        : 'personal_chat';
  } else if (key.startsWith('channel')) {
    const scope = known.username ? 'public' : 'private';
    type = `${scope}_${known.megagroup ? 'supergroup' : 'channel'}`;
  }
  return { name, type, id: exportIdOf(chat) };
};

const openJson = async (file, meta) => {
  const handle = await fs.open(file, 'w');
  const head = ['name', 'type', 'id']
    .map((k) => ` ${JSON.stringify(k)}: ${JSON.stringify(meta[k])},`)
    .join('\n');
  await handle.write(`{\n${head}\n "messages": [`);
  let count = 0;
  return {
    add: async (msg) => {
      const body = JSON.stringify(msg, null, 1).replace(/^/gm, '  ');
      await handle.write(`${count > 0 ? ',' : ''}\n${body}`);
      count += 1;
    },
    close: async () => {
      await handle.write(`${count > 0 ? '\n ' : ''}]\n}\n`);
      await handle.close();
    },
  };
};

/**
 * Opens the folder's writers for `formats` (`'json'`, `'html'`):
 * `{ add(msg, segments), close() }`.
 */
export const openOutput = async ({ folder, formats, meta }) => {
  await fs.mkdir(folder, { recursive: true });
  const json = formats.includes('json')
    ? await openJson(path.join(folder, 'result.json'), meta)
    : null;
  const html = formats.includes('html')
    ? await createHtmlWriter({ dir: folder, title: meta.name })
    : null;
  return {
    add: async (msg, segments) => {
      await json?.add(msg);
      await html?.add(msg, segments);
    },
    close: async () => {
      await json?.close();
      await html?.close();
    },
  };
};

/**
 * Where an exported chat history goes and what its files are called
 * (R-Y186; Telegram Desktop's "Export chat history", learned, never
 * copied): the default folder `~/Downloads/Telegram Desktop/
 * ChatExport_<YYYY-MM-DD>`, the folder the user typed checked (absolute,
 * and never inside the app's own store directory), and file names made
 * safe and unique inside the export.
 */

import { promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';

const pad = (n) => String(n).padStart(2, '0');

/** `2026-10-23` in the local time zone. */
export const dayOf = (ms) => {
  const d = new Date(ms);
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
};

/** `2026-10-23T14:05:09`, Desktop's local date format. */
export const localIso = (ms) => {
  const d = new Date(ms);
  const time = `${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
  return `${dayOf(ms)}T${time}`;
};

/** `23-10-2026_14-05-09`, what Desktop puts in a media file's name. */
export const stampOf = (ms) => {
  const d = new Date(ms);
  const day = `${pad(d.getDate())}-${pad(d.getMonth() + 1)}-${d.getFullYear()}`;
  const time = `${pad(d.getHours())}-${pad(d.getMinutes())}-${pad(d.getSeconds())}`;
  return `${day}_${time}`;
};

const partsOf = (day) => String(day).split('-').map(Number);

/** The first instant of local day `YYYY-MM-DD`. */
export const dayStartMs = (day) => {
  const [y, m, d] = partsOf(day);
  return new Date(y, m - 1, d, 0, 0, 0, 0).getTime();
};

/** The last instant of local day `YYYY-MM-DD`. */
export const dayEndMs = (day) => {
  const [y, m, d] = partsOf(day);
  return new Date(y, m - 1, d, 23, 59, 59, 999).getTime();
};

export const isDay = (value) => {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(value))) {
    return false;
  }
  const ms = dayStartMs(value);
  return Number.isFinite(ms) && dayOf(ms) === value;
};

/** Desktop's default folder for an export started at `now`. */
export const defaultFolder = (now = Date.now(), home = os.homedir()) =>
  path.join(home, 'Downloads', 'Telegram Desktop', `ChatExport_${dayOf(now)}`);

const exists = async (file) => {
  try {
    await fs.access(file);
    return true;
  } catch {
    return false;
  }
};

/** The default folder, or `… (1)`, `… (2)` when it is already there. */
export const freeDefaultFolder = async (now, home) => {
  const base = defaultFolder(now, home);
  let candidate = base;
  for (let n = 1; (await exists(candidate)) && n < 1000; n += 1) {
    candidate = `${base} (${n})`;
  }
  return candidate;
};

// The nearest existing parent's real path (symlinks followed) with the
// part below it put back, so a link into the store cannot hide it.
const realOf = async (target) => {
  let rest = '';
  let here = target;
  for (;;) {
    try {
      return path.join(await fs.realpath(here), rest);
    } catch {
      const parent = path.dirname(here);
      if (parent === here) {
        return target;
      }
      rest = path.join(path.basename(here), rest);
      here = parent;
    }
  }
};

const inside = (child, parent) => {
  const relative = path.relative(parent, child);
  return (
    relative === '' ||
    (!relative.startsWith('..') && !path.isAbsolute(relative))
  );
};

/**
 * The folder the user typed as `{ ok: true, folder }`, or `{ ok: false,
 * code }`: `bad-folder` (not text, too long, the file system's root),
 * `relative-folder` (not absolute; a leading `~/` is the home folder) or
 * `inside-store` (in the app's own store directory).
 */
export const checkFolder = async (
  value,
  { storeDir = null, home = os.homedir() } = {}
) => {
  const typed = typeof value === 'string' ? value.trim() : '';
  if (!typed || typed.length > 1024 || typed.includes('\0')) {
    return { ok: false, code: 'bad-folder' };
  }
  const expanded = /^~(?=$|[\\/])/.test(typed)
    ? path.join(home, typed.slice(1))
    : typed;
  if (!path.isAbsolute(expanded)) {
    return { ok: false, code: 'relative-folder' };
  }
  const folder = path.resolve(expanded);
  if (path.dirname(folder) === folder) {
    return { ok: false, code: 'bad-folder' };
  }
  if (storeDir) {
    const protectedDir = await realOf(path.resolve(storeDir));
    if (inside(await realOf(folder), protectedDir)) {
      return { ok: false, code: 'inside-store' };
    }
  }
  return { ok: true, folder };
};

/** A file name without separators, control characters or a leading dot. */
export const safeName = (name, fallback = 'file') => {
  const cleaned = String(name ?? '')
    // eslint-disable-next-line no-control-regex
    .replace(/[\\/:*?"<>|\u0000-\u001f]/g, '_')
    .replace(/^\.+/, '_')
    .trim()
    .slice(0, 120);
  return cleaned || fallback;
};

/** Hands out `folder/name` paths that are unique within one export. */
export const createNamer = () => {
  const used = new Set();
  return (folder, wanted) => {
    const parsed = path.parse(wanted);
    let name = wanted;
    for (let n = 1; used.has(`${folder}/${name.toLowerCase()}`); n += 1) {
      name = `${parsed.name} (${n})${parsed.ext}`;
    }
    used.add(`${folder}/${name.toLowerCase()}`);
    return `${folder}/${name}`;
  };
};

/**
 * One export running in the background (R-Y186): the chat's history read
 * page by page, oldest first (messages.getHistory, through the account's
 * queue at `prefetch` priority, waiting out "wait N seconds"), each message
 * written to the folder with its file downloaded as the user's choices
 * allow. `r` is the run: `{ env, c, job, now, sleep, publish, ... }`.
 * Cancel is a `cancelling` state the loops look at between steps; what was
 * written stays. No message text is ever logged.
 */

import { promises as fs } from 'node:fs';
import path from 'node:path';
import { renameDurable } from '../storage/durable.js';
import { rawMessage, floodSeconds } from './telegram-history.js';
import { bigSize, locationOf, fileLocation } from './telegram-media.js';
import { failureOf } from './telegram-stickers.js';
import { createNamer, dayEndMs, dayStartMs } from './telegram-export-paths.js';
import { entitiesOf, messageOf, segmentsOf } from './telegram-export-shape.js';
import {
  NOTE_FAILED,
  fileInfoOf,
  inlineMediaOf,
  mediaFields,
  skipNote,
  wantedName,
} from './telegram-export-media.js';
import { chatMeta, keyOfChat, openOutput } from './telegram-export-output.js';

const PAGE = 100;
const MAX_WAIT_S = 3600;
const MAX_WAITS = 24;

export const failure = failureOf({
  CHANNEL_PRIVATE: 'no-access',
  CHAT_ID_INVALID: 'no-access',
  PEER_ID_INVALID: 'no-access',
  CHAT_ADMIN_REQUIRED: 'no-access',
  FLOOD_WAIT: 'flood',
});

const unixOf = (value) =>
  typeof value === 'string'
    ? Math.floor(Date.parse(value) / 1000) || 0
    : Number(value) || 0;

const nameOfUser = (u) =>
  [u.firstName, u.lastName].filter(Boolean).join(' ') ||
  u.username ||
  (u.deleted ? 'Deleted Account' : `user${u.id}`);

// What a page's users and chats tell: names and the chat's kind.
const absorb = (page, ctx) => {
  for (const u of page?.users ?? []) {
    const key = `user${u.id}`;
    ctx.names.set(key, nameOfUser(u));
    ctx.entities.set(key, {
      title: nameOfUser(u),
      bot: Boolean(u.bot),
      self: Boolean(u.self),
      username: u.username,
    });
    if (u.self) {
      ctx.self = key;
    }
  }
  for (const c of page?.chats ?? []) {
    const key = c.className?.startsWith('Channel')
      ? `channel${c.id}`
      : `chat${c.id}`;
    ctx.names.set(key, c.title ?? key);
    ctx.entities.set(key, {
      title: c.title,
      username: c.username,
      megagroup: Boolean(c.megagroup),
    });
  }
};

/** A new run of `job` on the connection `c`. */
export const newRun = ({ env, c, job, now, sleep, publish }) => ({
  env,
  c,
  job,
  now,
  sleep,
  publish,
  ctx: {
    names: new Map(),
    entities: new Map(),
    self: null,
    peer: keyOfChat(job.chat),
  },
  counts: {},
  name: createNamer(),
  out: null,
  fromMs: job.options.from === null ? null : dayStartMs(job.options.from),
  toMs: job.options.to === null ? null : dayEndMs(job.options.to),
});

export const stopping = (r) => r.job.state === 'cancelling';

// A wait Telegram asked for, cut short by Cancel.
const waitFor = async (r, seconds) => {
  const end = r.now() + seconds * 1000;
  while (r.now() < end && !stopping(r)) {
    await r.sleep(Math.min(1000, Math.max(0, end - r.now())));
  }
};

const waitSeconds = (error) =>
  error?.code === 'flood-wait'
    ? Number(error.retryAfter) || 1
    : floodSeconds(error);

// `use` through the queue; after "wait N seconds" wait and ask again.
export const asked = async (r, key, use) => {
  for (let tries = 0; ; tries += 1) {
    try {
      return await (r.env.queue
        ? r.env.queue.run(key, 'prefetch', use)
        : use());
    } catch (error) {
      const seconds = waitSeconds(error);
      if (seconds <= 0 || tries >= MAX_WAITS || stopping(r)) {
        throw error;
      }
      r.env.log?.({ level: 'info', event: 'telegram_export_waiting', seconds });
      await waitFor(r, Math.min(seconds, MAX_WAIT_S));
      if (stopping(r)) {
        throw error;
      }
    }
  }
};

const download = async (r, info, target) => {
  const { c, job } = r;
  const part = `${target}.part`;
  const location =
    info.kind === 'photo'
      ? locationOf(c.Api, c.helpers, info)
      : fileLocation(c.Api, c.helpers, info.file);
  const method = info.kind === 'photo' ? 'media' : 'file';
  await fs.mkdir(path.dirname(target), { recursive: true });
  try {
    await asked(r, `${method}:export:${job.chat}:${info.file.id}`, () =>
      c.client.downloadFile(location, {
        dcId: Number(info.file.dcId),
        fileSize: bigSize(c.helpers, info.size),
        outputFile: part,
      })
    );
    await renameDurable(part, target); // (R-Z19)
  } catch (error) {
    await fs.rm(part, { force: true });
    throw error;
  }
  job.bytes += (await fs.stat(target)).size;
};

// The message's file: downloaded, or the note why it is not.
const fileOf = async (r, info, at) => {
  const { job } = r;
  const note = skipNote(info, job.options);
  if (note) {
    job.skipped += 1;
    return mediaFields(info, note);
  }
  r.counts[info.folder] = (r.counts[info.folder] ?? 0) + 1;
  const relative = r.name(
    info.folder,
    wantedName(info, { index: r.counts[info.folder], at })
  );
  job.current = path.basename(relative);
  await r.publish();
  try {
    await download(r, info, path.join(job.folder, relative));
    job.files += 1;
    return mediaFields(info, relative);
  } catch (error) {
    if (stopping(r)) {
      throw error;
    }
    job.failed += 1;
    return mediaFields(info, NOTE_FAILED);
  }
};

const fieldsOf = async (r, raw) => {
  const info = raw.className === 'MessageService' ? null : fileInfoOf(raw);
  const inline = inlineMediaOf(raw);
  return info
    ? { ...inline, ...(await fileOf(r, info, unixOf(raw.date))) }
    : inline;
};

const writeMessage = async (r, raw) => {
  const media = await fieldsOf(r, raw);
  await r.out.add(
    messageOf(raw, r.ctx, media),
    segmentsOf(raw.message, entitiesOf(raw))
  );
  r.job.messages += 1;
  await r.publish();
};

const readPage = (r, cursor, n) =>
  asked(r, `messages:export:${r.job.chat}:${n}`, () =>
    r.env.connection.withPeer(r.c.client, r.job.chat, (peer) =>
      r.c.client.invoke(
        new r.c.Api.messages.GetHistory({
          peer,
          offsetId: cursor.offsetId,
          offsetDate: cursor.offsetDate,
          addOffset: -PAGE,
          limit: PAGE,
          maxId: 0,
          minId: 0,
          hash: r.c.zero,
        })
      )
    )
  );

// The first answer: how many there are, and the folder opened under the
// chat's name and kind.
const begin = async (r, page) => {
  const ranged = r.fromMs !== null || r.toMs !== null;
  r.job.total = ranged
    ? null
    : Number(page.count ?? page.messages?.length ?? 0);
  r.out = await openOutput({
    folder: r.job.folder,
    formats: r.job.formats,
    meta: chatMeta({
      chat: r.job.chat,
      chatName: r.job.chatName,
      entities: r.ctx.entities,
    }),
  });
};

// Writes the page's messages; `last` is the newest id seen, `done` that the
// end of the range or a Cancel was reached.
const consume = async (r, fresh, last) => {
  let newest = last;
  for (const message of fresh) {
    if (stopping(r)) {
      return { last: newest, done: true };
    }
    const raw = rawMessage(message);
    const at = unixOf(raw.date) * 1000;
    newest = Math.max(newest, Number(raw.id));
    if (r.toMs !== null && at > r.toMs) {
      return { last: newest, done: true };
    }
    if (r.fromMs === null || at >= r.fromMs) {
      await writeMessage(r, raw);
    }
  }
  return { last: newest, done: false };
};

const freshOf = (page, last) =>
  (page.messages ?? [])
    .filter((m) => m.className !== 'MessageEmpty' && Number(m.id) > last)
    .sort((a, b) => Number(a.id) - Number(b.id));

// Oldest first: each page is the messages after the cursor (a negative
// add_offset), the newest of them the next cursor; it ends when nothing
// newer comes.
const readAll = async (r) => {
  let cursor =
    r.fromMs === null
      ? { offsetId: 1, offsetDate: 0 }
      : { offsetId: 0, offsetDate: Math.floor(r.fromMs / 1000) };
  let last = 0;
  for (let n = 1; !stopping(r); n += 1) {
    const page = await readPage(r, cursor, n);
    absorb(page, r.ctx);
    if (n === 1) {
      await begin(r, page);
    }
    const fresh = freshOf(page, last);
    const step = fresh.length > 0 ? await consume(r, fresh, last) : null;
    if (!step || step.done) {
      return;
    }
    last = step.last;
    cursor = { offsetId: last, offsetDate: 0 };
  }
};

const finish = async (r, state, error = null) => {
  const { job } = r;
  job.state = state;
  job.current = null;
  job.finishedAt = new Date(r.now()).toISOString();
  if (error) {
    job.code = failure(error).code;
  }
  r.env.log?.({
    level: 'info',
    event: 'telegram_export_end',
    state,
    code: job.code ?? null,
    messages: job.messages,
    files: job.files,
    skipped: job.skipped,
    failed: job.failed,
    bytes: job.bytes,
  });
  await r.publish(true);
};

/** Runs the export to its end; never throws (the job's state tells). */
export const execute = async (r) => {
  try {
    await readAll(r);
    await r.out?.close();
    await finish(r, stopping(r) ? 'cancelled' : 'done');
  } catch (error) {
    await r.out?.close().catch(() => {});
    await finish(r, stopping(r) ? 'cancelled' : 'failed', error);
  }
};

/**
 * A Telegram message as one entry of the JSON export (R-Y186). The field
 * names are those of Telegram Desktop's documented machine-readable
 * export (`name`, `type`, `id`, `messages[]` with `id`, `type`, `date`,
 * `date_unixtime`, `from`, `from_id`, `text`, `text_entities`,
 * `reply_to_message_id`, …); the code is our own, working on the plain
 * message the store keeps (`rawMessage`, ./telegram-history.js).
 */

import { localIso } from './telegram-export-paths.js';

const ENTITY_TYPES = Object.freeze({
  MessageEntityBold: 'bold',
  MessageEntityItalic: 'italic',
  MessageEntityUnderline: 'underline',
  MessageEntityStrike: 'strikethrough',
  MessageEntityCode: 'code',
  MessageEntityPre: 'pre',
  MessageEntityTextUrl: 'text_link',
  MessageEntityUrl: 'link',
  MessageEntityMention: 'mention',
  MessageEntityMentionName: 'mention_name',
  MessageEntityHashtag: 'hashtag',
  MessageEntityCashtag: 'cashtag',
  MessageEntityBotCommand: 'bot_command',
  MessageEntityEmail: 'email',
  MessageEntityPhone: 'phone',
  MessageEntitySpoiler: 'spoiler',
  MessageEntityBlockquote: 'blockquote',
  MessageEntityCustomEmoji: 'custom_emoji',
  MessageEntityBankCard: 'bank_card',
  MessageEntityTonAddress: 'ton_address',
});

// What an entity says besides its kind.
const extrasOf = (entity) => {
  switch (entity.type) {
    case 'pre':
      return entity.language ? { language: entity.language } : {};
    case 'text_link':
      return { href: entity.url ?? '' };
    case 'mention_name':
      return { user_id: Number(entity.userId) };
    case 'custom_emoji':
      return { document_id: String(entity.documentId ?? '') };
    default:
      return {};
  }
};

/** The message's entities as `{ type, offset, length, … }`, known kinds only. */
export const entitiesOf = (raw) =>
  (raw?.entities ?? [])
    .filter((e) => ENTITY_TYPES[e?.className] && Number(e.length) > 0)
    .map((e) => {
      const entity = {
        type: ENTITY_TYPES[e.className],
        offset: Number(e.offset),
        length: Number(e.length),
        language: e.language,
        url: e.url,
        userId: e.userId,
        documentId: e.documentId,
      };
      return { ...entity, extras: extrasOf(entity) };
    })
    .sort((a, b) => a.offset - b.offset || b.length - a.length);

/**
 * The text cut where an entity starts or ends: `[{ text, covers }]`,
 * `covers` the entities over that piece (the outermost first).
 */
export const segmentsOf = (text, entities) => {
  const whole = String(text ?? '');
  const clamp = (n) => Math.max(0, Math.min(whole.length, n));
  const cuts = new Set([0, whole.length]);
  for (const e of entities) {
    cuts.add(clamp(e.offset));
    cuts.add(clamp(e.offset + e.length));
  }
  const points = [...cuts].sort((a, b) => a - b);
  const pieces = [];
  for (let i = 0; i + 1 < points.length; i += 1) {
    const [from, to] = [points[i], points[i + 1]];
    const covers = entities.filter(
      (e) => e.offset <= from && e.offset + e.length >= to
    );
    const last = pieces.at(-1);
    const same =
      last &&
      last.covers.length === covers.length &&
      last.covers.every((e, n) => e === covers[n]);
    if (same) {
      last.text += whole.slice(from, to);
    } else {
      pieces.push({ text: whole.slice(from, to), covers });
    }
  }
  return pieces;
};

/** `{ text, text_entities }` as Desktop writes them. */
export const textFieldsOf = (raw) => {
  const text = String(raw?.message ?? '');
  const entities = entitiesOf(raw);
  const pieces = segmentsOf(text, entities).filter((p) => p.text !== '');
  const parts = pieces.map((p) =>
    p.covers.length > 0
      ? { type: p.covers[0].type, text: p.text, ...p.covers[0].extras }
      : { type: 'plain', text: p.text }
  );
  const plain = parts.every((p) => p.type === 'plain');
  return {
    text: plain ? text : parts.map((p) => (p.type === 'plain' ? p.text : p)),
    text_entities: parts,
  };
};

const unixOf = (value) => {
  if (typeof value === 'string') {
    return Math.floor(Date.parse(value) / 1000) || 0;
  }
  return Number(value) || 0;
};

const peerKey = (peer) => {
  if (peer?.userId !== undefined) {
    return `user${peer.userId}`;
  }
  if (peer?.channelId !== undefined) {
    return `channel${peer.channelId}`;
  }
  return peer?.chatId === undefined ? null : `chat${peer.chatId}`;
};

/**
 * Who wrote it: `{ from, from_id }`. `names` maps `user<id>`,
 * `channel<id>`, `chat<id>` to a name; a message of a personal chat has
 * no sender of its own, so `ctx.self` / `ctx.peer` (keys) stand in.
 */
export const senderOf = (raw, ctx) => {
  const own = !raw?.post && raw?.out ? ctx.self : null;
  const key = peerKey(raw?.fromId) ?? own ?? peerKey(raw?.peerId);
  const id = key ?? ctx.self ?? ctx.peer ?? null;
  return { from: ctx.names.get(id) ?? null, from_id: id };
};

const snake = (name) =>
  String(name)
    .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
    .toLowerCase();

const namesOf = (ids, names) =>
  (ids ?? []).map((id) => names.get(`user${id}`) ?? `user${id}`);

/** What a service message (a join, a new title, a pin, a call) adds. */
export const actionFieldsOf = (action, names, raw) => {
  const kind = String(action?.className ?? '').replace('MessageAction', '');
  switch (kind) {
    case 'ChatCreate':
      return {
        action: 'create_group',
        title: action.title,
        members: namesOf(action.users, names),
      };
    case 'ChannelCreate':
      return { action: 'create_channel', title: action.title };
    case 'ChatEditTitle':
      return { action: 'edit_group_title', title: action.title };
    case 'ChatAddUser':
      return {
        action: 'invite_members',
        members: namesOf(action.users, names),
      };
    case 'ChatDeleteUser':
      return {
        action: 'remove_members',
        members: namesOf([action.userId], names),
      };
    case 'PinMessage':
      return { action: 'pin_message', message_id: raw?.replyTo?.replyToMsgId };
    case 'PhoneCall':
      return {
        action: 'phone_call',
        duration_seconds: action.duration,
        discard_reason: action.reason
          ? snake(
              String(action.reason.className).replace('PhoneCallDiscard', '')
            ).replace(/^reason_/, '')
          : undefined,
      };
    case 'TopicCreate':
      return { action: 'topic_created', title: action.title };
    default:
      return { action: snake(kind || 'unknown') };
  }
};

const compact = (object) =>
  Object.fromEntries(Object.entries(object).filter(([, v]) => v !== undefined));

/** A service message: `{ id, type: 'service', date, actor, action, … }`. */
export const serviceOf = (raw, ctx) => {
  const at = unixOf(raw.date);
  const who = senderOf(raw, ctx);
  return compact({
    id: Number(raw.id),
    type: 'service',
    date: localIso(at * 1000),
    date_unixtime: String(at),
    actor: who.from,
    actor_id: who.from_id,
    ...actionFieldsOf(raw.action, ctx.names, raw),
  });
};

const forwardedFrom = (raw, names) => {
  const fwd = raw?.fwdFrom;
  if (!fwd) {
    return {};
  }
  const key = peerKey(fwd.fromId);
  return {
    forwarded_from: fwd.fromName ?? (key ? (names.get(key) ?? key) : null),
  };
};

/**
 * One message as Desktop's JSON has it. `media` is what the exporter
 * decided about its file (`photo`, `file`, `media_type`, …) and is put
 * before the text, as Desktop does.
 */
export const messageOf = (raw, ctx, media = {}) => {
  if (raw?.className === 'MessageService') {
    return serviceOf(raw, ctx);
  }
  const at = unixOf(raw.date);
  const edited = raw.editDate ? unixOf(raw.editDate) : 0;
  const who = senderOf(raw, ctx);
  const viaBot = raw.viaBotId ? ctx.names.get(`user${raw.viaBotId}`) : null;
  return compact({
    id: Number(raw.id),
    type: 'message',
    date: localIso(at * 1000),
    date_unixtime: String(at),
    edited: edited ? localIso(edited * 1000) : undefined,
    edited_unixtime: edited ? String(edited) : undefined,
    from: who.from,
    from_id: who.from_id,
    ...forwardedFrom(raw, ctx.names),
    reply_to_message_id: raw.replyTo?.replyToMsgId
      ? Number(raw.replyTo.replyToMsgId)
      : undefined,
    via_bot: viaBot ?? undefined,
    media_group_id: raw.groupedId ? String(raw.groupedId) : undefined,
    ...media,
    ...textFieldsOf(raw),
  });
};

/**
 * "Export chat history", as Telegram Desktop has it in a chat's menu
 * (R-Y186; learned, never copied). The user picks what to include
 * (photos, videos, voice messages, round video messages, stickers, GIFs,
 * files), a size limit for videos and files, a date range, the format
 * (HTML, JSON or both) and a folder; the server then reads the chat's
 * whole history in the background and writes it there:
 * - `exportDefaults()` — `{ ok, folder, job }`: Desktop's default folder
 *   (`~/Downloads/Telegram Desktop/ChatExport_<YYYY-MM-DD>`) and the
 *   running or last export;
 * - `exportStart({ chat, chatName?, media, sizeLimitMb, from?, to?,
 *   formats, folder })` — checks everything first (`bad-request`,
 *   `relative-folder`, `inside-store`, `bad-folder`, `busy` when one is
 *   running; one export at a time), then starts it → `{ ok, job }`;
 * - `exportStatus()` — `{ ok, job }`, `job` null when none ran;
 * - `exportCancel()` — stops it (what was written stays) → `{ ok, job }`;
 * - `exportReveal()` — opens the finished export's folder in the file
 *   manager.
 * Only reads go to Telegram (./telegram-export-run.js): messages.getHistory
 * page by page and the files' downloads, through the account's queue. The
 * progress is an `export:telegram:<chat>` link (the events stream carries
 * it); no message text is ever logged.
 */

import { execFile } from 'node:child_process';
import os from 'node:os';
import path from 'node:path';
import { connected } from './telegram-stickers.js';
import {
  checkFolder,
  freeDefaultFolder,
  isDay,
} from './telegram-export-paths.js';
import { execute, failure, newRun } from './telegram-export-run.js';

export const MEDIA_KEYS = Object.freeze([
  'photos',
  'videos',
  'voice',
  'roundVideo',
  'stickers',
  'gifs',
  'files',
]);
export const FORMATS = Object.freeze(['html', 'json']);
export const MAX_LIMIT_MB = 4000;
export const DEFAULT_LIMIT_MB = 8;
const PUT_EVERY_MS = 300;
const CHAT = /^-?\d{1,20}$/;

const bad = (code) => ({ ok: false, error: code, code });

const validMedia = (media) =>
  Boolean(media) &&
  typeof media === 'object' &&
  !Array.isArray(media) &&
  Object.entries(media).every(
    ([k, v]) => MEDIA_KEYS.includes(k) && typeof v === 'boolean'
  );

export const validRange = (from, to) =>
  [from, to].every((d) => d === null || isDay(d)) &&
  (from === null || to === null || from <= to);

export const validFormats = (formats) =>
  Array.isArray(formats) &&
  formats.length > 0 &&
  new Set(formats).size === formats.length &&
  formats.every((f) => FORMATS.includes(f));

export const validLimit = (limit) =>
  Number.isInteger(limit) && limit >= 1 && limit <= MAX_LIMIT_MB;

/**
 * The request as `{ ok: true, value }`, or `{ ok: false, code:
 * 'bad-request' }`: a chat id, the kinds (known keys, booleans), a size
 * limit of 1 to 4000 MB, `from` and `to` as `YYYY-MM-DD` or none, one or
 * both formats.
 */
export const parseExport = (request) => {
  const r = request ?? {};
  const from = r.from ?? null;
  const to = r.to ?? null;
  const sizeLimitMb = r.sizeLimitMb ?? DEFAULT_LIMIT_MB;
  const name = r.chatName ?? '';
  const ok =
    CHAT.test(String(r.chat ?? '')) &&
    validMedia(r.media) &&
    validLimit(sizeLimitMb) &&
    validRange(from, to) &&
    validFormats(r.formats) &&
    typeof name === 'string' &&
    name.length <= 256;
  return ok
    ? {
        ok: true,
        value: {
          chat: String(r.chat),
          chatName: name,
          media: Object.fromEntries(
            MEDIA_KEYS.map((k) => [k, r.media[k] === true])
          ),
          sizeLimitMb,
          from,
          to,
          formats: FORMATS.filter((f) => r.formats.includes(f)),
          folder: r.folder,
        },
      }
    : bad('bad-request');
};

const snapshot = (job) =>
  job && {
    chat: job.chat,
    state: job.state,
    folder: job.folder,
    formats: job.formats,
    messages: job.messages,
    total: job.total,
    files: job.files,
    skipped: job.skipped,
    failed: job.failed,
    bytes: job.bytes,
    current: job.current,
    code: job.code ?? null,
    startedAt: job.startedAt,
    finishedAt: job.finishedAt ?? null,
  };

const linkOf = (job, at) => ({
  id: `export:telegram:${job.chat}`,
  tokens: ['export', 'telegram', job.chat],
  kind: 'export',
  source: 'telegram',
  ...snapshot(job),
  at,
});

const COMMANDS = { darwin: 'open', win32: 'explorer' };

// Opens a folder in the file manager.
export const opener = (folder) =>
  new Promise((resolve) => {
    execFile(COMMANDS[process.platform] ?? 'xdg-open', [folder], () =>
      resolve()
    );
  });

const newJob = (value, folder, at) => ({
  chat: value.chat,
  chatName: value.chatName,
  options: value,
  state: 'running',
  folder,
  formats: value.formats,
  messages: 0,
  total: null,
  files: 0,
  skipped: 0,
  failed: 0,
  bytes: 0,
  current: null,
  startedAt: new Date(at).toISOString(),
});

export const active = (job) => ['running', 'cancelling'].includes(job?.state);

// The app's store directory (media lives in `<store>/media/telegram`) and
// how to wait between Telegram's pages.
export const exportRuntime = (env, mediaDir) => ({
  storeDir: mediaDir ? path.resolve(mediaDir, '..', '..') : null,
  sleep:
    env.sleep ??
    ((ms) => new Promise((resolve) => globalThis.setTimeout(resolve, ms))),
});

// "Show in folder" for the export `current()` answers, once it is over.
export const revealOf = (current, reveal) => async () => {
  const job = current();
  if (!job || active(job)) {
    return bad('no-export');
  }
  await reveal(job.folder);
  return { ok: true };
};

export const createHistoryExport = (
  env,
  {
    userClient,
    mediaDir = null,
    home = os.homedir(),
    now = () => Date.now(),
    reveal = opener,
  }
) => {
  const { storeDir, sleep } = exportRuntime(env, mediaDir);
  let job = null;
  let starting = false;

  const publish = async (force = false) => {
    const at = now();
    if (!force && at - (job.putAt ?? 0) < PUT_EVERY_MS) {
      return;
    }
    job.putAt = at;
    await env.store
      ?.put(linkOf(job, new Date(at).toISOString()))
      .catch(() => {});
  };

  const launch = async (value, folder, c) => {
    job = newJob(value, folder, now());
    env.log?.({
      level: 'info',
      event: 'telegram_export_start',
      formats: value.formats,
    });
    await publish(true);
    // In the background: the page follows it through the events stream.
    execute(newRun({ env, c, job, now, sleep, publish })).catch(() => {});
    return { ok: true, job: snapshot(job) };
  };

  const start = async (request) => {
    const parsed = parseExport(request);
    if (!parsed.ok) {
      return parsed;
    }
    const { value } = parsed;
    const place = await checkFolder(value.folder, { storeDir, home });
    if (!place.ok) {
      return bad(place.code);
    }
    if (starting || active(job)) {
      return bad('busy');
    }
    starting = true;
    try {
      return await connected(env, userClient, failure, (c) =>
        launch(value, place.folder, c)
      );
    } finally {
      starting = false;
    }
  };

  return {
    exportDefaults: async () => ({
      ok: true,
      folder: await freeDefaultFolder(now(), home),
      job: snapshot(job),
    }),
    exportStatus: async () => ({ ok: true, job: snapshot(job) }),
    exportStart: start,
    exportCancel: async () => {
      if (job?.state === 'running') {
        job.state = 'cancelling';
        await publish(true);
      }
      return { ok: true, job: snapshot(job) };
    },
    exportReveal: revealOf(() => job, reveal),
  };
};

/**
 * Fact checks under messages, as Telegram Desktop shows them (R-Y166;
 * learned, never copied): a message whose fact check Telegram marks
 * `need_check` carries only its hash; the text is asked for.
 * - `factChecks({ chat, ids })` — messages.getFactCheck for the messages
 *   (up to 100) → `{ ok, items: [{ id, country, text, entities }] }`, the
 *   entities by className as a stored message's; a message with none is
 *   left out. Answers are kept in memory by chat and id.
 * Errors become codes.
 */

import { connected, runIn, failureOf } from './telegram-stickers.js';

const failure = failureOf({
  FLOOD_WAIT: 'flood',
  MSG_ID_INVALID: 'not-found',
});
const CHAT = /^-?\d{1,20}$/;
const MAX_IDS = 100;
const MAX_KEPT = 1000;

const plainEntity = (one) => ({
  className: one.className,
  offset: Number(one.offset),
  length: Number(one.length),
  ...(one.url ? { url: String(one.url) } : {}),
  ...(one.language ? { language: String(one.language) } : {}),
});

/** One fact check as the page draws it, or null when it says nothing. */
export const factOf = (id, raw) =>
  raw?.text?.text
    ? {
        id,
        country: String(raw.country ?? ''),
        text: String(raw.text.text),
        entities: (raw.text.entities ?? []).map(plainEntity),
      }
    : null;

/** Whether a request body is one the fetch answers. */
export const validFactRequest = ({ chat, ids } = {}) =>
  CHAT.test(String(chat ?? '')) &&
  Array.isArray(ids) &&
  ids.length > 0 &&
  ids.length <= MAX_IDS &&
  ids.every((id) => Number.isInteger(id) && id > 0);

export const createFactChecks = (env, { userClient }) => {
  const kept = new Map(); // chat:id -> item | null
  const keep = (key, item) => {
    kept.delete(key);
    kept.set(key, item);
    if (kept.size > MAX_KEPT) {
      kept.delete(kept.keys().next().value);
    }
  };

  const factChecks = async (body = {}) => {
    if (!validFactRequest(body)) {
      return { ok: false, error: 'bad request', code: 'failed' };
    }
    const { chat, ids } = body;
    const keyOf = (id) => `${chat}:${id}`;
    const have = () =>
      ids.map((id) => kept.get(keyOf(id))).filter((item) => item);
    const missing = ids.filter((id) => !kept.has(keyOf(id)));
    if (missing.length === 0) {
      return { ok: true, items: have() };
    }
    return connected(env, userClient, failure, async (c) => {
      const answer = await runIn(env, `fact:${chat}:${missing.join(',')}`, () =>
        env.connection.withPeer(c.client, chat, (peer) =>
          c.client.invoke(
            new c.Api.messages.GetFactCheck({ peer, msgId: missing })
          )
        )
      );
      const list = Array.isArray(answer) ? answer : (answer?.result ?? []);
      missing.forEach((id, i) => keep(keyOf(id), factOf(id, list[i])));
      return { ok: true, items: have() };
    });
  };

  return { factChecks };
};

/**
 * Creating, editing, deleting and ordering chat folders, as Telegram
 * Desktop's Settings → Folders and the folder tab's menu do (R-Y164;
 * learned, never copied). The folder is the page's shape (see
 * ./telegram-folders.js): `{ title, emoticon?, contacts, nonContacts,
 * groups, broadcasts, bots, excludeMuted, excludeRead, excludeArchived,
 * include, exclude, pinned }`, the lists being our chat ids.
 *
 * - `folderSave({ id?, folder })` — messages.updateDialogFilter with a
 *   DialogFilter (layer 225: the title is a TextWithEntities; a shared
 *   folder, `chatlist: true`, is a DialogFilterChatlist with chats only,
 *   R-Y172). With no `id` the folder is new and takes the next free id (Telegram wants the
 *   client to choose it, 2 or more);
 * - `folderDelete({ id })` — the same method with no filter;
 * - `foldersReorder({ order })` — messages.updateDialogFiltersOrder; the
 *   ids of every folder in the new order (0 is "All chats");
 * - `foldersSuggested()` — messages.getSuggestedDialogFilters, as
 *   `{ folder, description }` for the recommended folders.
 * Telegram's errors (too many folders, too many chats, ...) become codes
 * the page shows as words.
 */

import { connected, runIn, failureOf } from './telegram-stickers.js';
import { folderOf } from './telegram-folders.js';

const CODES = {
  FILTER_INCLUDE_EMPTY: 'include-empty',
  FILTER_INCLUDE_TOO_MUCH: 'include-too-much',
  FILTER_TITLE_EMPTY: 'title-empty',
  FILTER_ID_INVALID: 'id-invalid',
  FILTER_NOT_SUPPORTED: 'not-supported',
  DIALOG_FILTERS_TOO_MUCH: 'too-many-folders',
  FILTERS_TOO_MUCH: 'too-many-folders',
  PEER_ID_INVALID: 'no-access',
  CHANNEL_PRIVATE: 'no-access',
  CHAT_ID_INVALID: 'no-access',
  USER_PREMIUM_REQUIRED: 'premium',
  PREMIUM_ACCOUNT_REQUIRED: 'premium',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);
const BAD = { ok: false, error: 'bad request', code: 'failed' };

/** The tag colours a folder may take (R-Y180): 0 to 6. */
export const COLORS = 7;
const colorOk = (color) =>
  color === undefined ||
  color === null ||
  (Number.isInteger(color) && color >= 0 && color < COLORS);

/** Telegram's folder title limit, in letters. */
export const TITLE_MAX = 12;
export const CHATS_MAX = 200;
const CHAT = /^-?\d{1,20}$/;
const FLAGS = [
  'contacts',
  'nonContacts',
  'groups',
  'broadcasts',
  'bots',
  'excludeMuted',
  'excludeRead',
  'excludeArchived',
];

const chatList = (list) =>
  Array.isArray(list) &&
  list.length <= CHATS_MAX &&
  list.every((c) => typeof c === 'string' && CHAT.test(c)) &&
  new Set(list).size === list.length;

const flagOk = (folder, flag) =>
  folder[flag] === undefined || typeof folder[flag] === 'boolean';

// A shared folder (chat list) names its chats and nothing else.
const chatlistOk = (folder) =>
  ['chatlist', 'hasMyInvites'].every((flag) => flagOk(folder, flag)) &&
  (folder.chatlist !== true ||
    (FLAGS.every((flag) => folder[flag] !== true) &&
      (folder.exclude ?? []).length === 0));

/** Whether `folder` is a folder the page may send (strict). */
export const validFolder = (folder) => {
  if (!folder || typeof folder !== 'object' || Array.isArray(folder)) {
    return false;
  }
  const title = typeof folder.title === 'string' ? folder.title.trim() : '';
  return (
    title !== '' &&
    [...title].length <= TITLE_MAX &&
    (folder.emoticon === undefined ||
      folder.emoticon === null ||
      (typeof folder.emoticon === 'string' && folder.emoticon.length <= 16)) &&
    colorOk(folder.color) &&
    FLAGS.every((flag) => flagOk(folder, flag)) &&
    chatlistOk(folder) &&
    ['include', 'exclude', 'pinned'].every(
      (key) => folder[key] === undefined || chatList(folder[key])
    )
  );
};

/** A valid folder id: 2 and up (0 is "All chats", 1 the archive). */
export const validId = (id) => Number.isInteger(id) && id >= 2 && id < 1000;

// The input peer of a chat, whichever form the connection gives.
const inputOf = (env, c, chat) =>
  env.connection.withPeer(c.client, chat, async (peer) =>
    typeof peer === 'object' ? peer : await c.client.getInputEntity(peer)
  );

export const inputsOf = async (env, c, chats = []) => {
  const peers = [];
  for (const chat of chats) {
    peers.push(await inputOf(env, c, chat));
  }
  return peers;
};

// The DialogFilter for `folder` with the id given.
const filterOf = async (env, c, id, folder) => {
  const emoticon = {
    ...(folder.emoticon ? { emoticon: folder.emoticon } : {}),
    // The tag's colour (R-Y180).
    ...(Number.isInteger(folder.color) ? { color: folder.color } : {}),
  };
  const include = folder.include ?? [];
  const exclude = folder.exclude ?? [];
  const pinned = (folder.pinned ?? []).filter((x) => !exclude.includes(x));
  if (folder.chatlist === true) {
    // A shared folder takes chats by name only (layer 225: no flags).
    return new c.Api.DialogFilterChatlist({
      ...(folder.hasMyInvites ? { hasMyInvites: true } : {}),
      id,
      title: new c.Api.TextWithEntities({
        text: folder.title.trim(),
        entities: [],
      }),
      ...emoticon,
      pinnedPeers: await inputsOf(env, c, pinned),
      includePeers: await inputsOf(env, c, include),
    });
  }
  const flags = Object.fromEntries(
    FLAGS.filter((flag) => folder[flag] === true).map((flag) => [flag, true])
  );
  return new c.Api.DialogFilter({
    ...flags,
    id,
    title: new c.Api.TextWithEntities({
      text: folder.title.trim(),
      entities: [],
    }),
    ...emoticon,
    pinnedPeers: await inputsOf(env, c, pinned),
    includePeers: await inputsOf(env, c, include),
    excludePeers: await inputsOf(env, c, exclude),
  });
};

// The next free id: above every folder Telegram has.
const nextId = async (c) => {
  const answer = await c.client.invoke(new c.Api.messages.GetDialogFilters());
  const filters = Array.isArray(answer) ? answer : (answer?.filters ?? []);
  return Math.max(1, ...filters.map((f) => Number(f?.id) || 0)) + 1;
};

const suggestion = (s) => ({
  // Their chats are Telegram's examples: only the rules count.
  folder: { ...folderOf(s?.filter), include: [], exclude: [], pinned: [] },
  description: String(s?.description ?? ''),
});

export const createFolderEdit = (env, { userClient }) => {
  const edit = (use) =>
    connected(env, userClient, failure, (c) =>
      runIn(env, 'folders-edit', () => use(c))
    );
  return {
    /** `{ id?, folder }` → `{ ok, id }`. */
    folderSave: async ({ id, folder } = {}) => {
      if (!validFolder(folder) || (id !== undefined && !validId(id))) {
        return BAD;
      }
      return edit(async (c) => {
        const chosen = id ?? (await nextId(c));
        await c.client.invoke(
          new c.Api.messages.UpdateDialogFilter({
            id: chosen,
            filter: await filterOf(env, c, chosen, folder),
          })
        );
        return { ok: true, id: chosen };
      });
    },

    /** `{ id }` → `{ ok }`. */
    folderDelete: async ({ id } = {}) =>
      !validId(id)
        ? BAD
        : edit(async (c) => {
            await c.client.invoke(
              new c.Api.messages.UpdateDialogFilter({ id })
            );
            return { ok: true };
          }),

    /** `{ order }` (every folder id, 0 for "All chats") → `{ ok }`. */
    foldersReorder: async ({ order } = {}) => {
      const fine =
        Array.isArray(order) &&
        order.length > 0 &&
        order.length <= 100 &&
        order.every((n) => n === 0 || validId(n)) &&
        new Set(order).size === order.length;
      return !fine
        ? BAD
        : edit(async (c) => {
            await c.client.invoke(
              new c.Api.messages.UpdateDialogFiltersOrder({ order })
            );
            return { ok: true };
          });
    },

    /** `{}` → `{ ok, suggested: [{ folder, description }] }`. */
    foldersSuggested: async () =>
      connected(env, userClient, failure, async (c) => {
        const answer = await c.client.invoke(
          new c.Api.messages.GetSuggestedDialogFilters()
        );
        const suggested = (Array.isArray(answer) ? answer : [])
          .map(suggestion)
          .filter((s) => s.folder.title);
        return { ok: true, suggested };
      }),
  };
};

/**
 * Chat folders, as Telegram's apps show them (R-Y103; Telegram Desktop's
 * folders above the chat list, learned, never copied).
 *
 * `folderList({ fresh })` — messages.getDialogFilters, as plain data the
 * page applies to its chat list (./../web/chat-folders.js):
 *
 *   { id, title, emoticon,
 *     contacts, nonContacts, groups, broadcasts, bots,   // who is in
 *     excludeMuted, excludeRead, excludeArchived,       // who is not
 *     include: [chat], exclude: [chat], pinned: [chat],  // by name
 *     chatlist?, hasMyInvites? }                        // a shared one
 *
 * and `{ id: 0, all: true }` where "All chats" stands among them (a
 * Premium user may move it). Chats are our chat ids (Telegram's marked
 * ids: a user's id, -chat, -100channel). Kept for a minute: folders
 * change rarely, and only in Telegram's settings.
 */

const KEEP_MS = 60_000;

// An InputPeer as our chat id; null for one we cannot name.
export const peerChat = (peer, selfId = null) => {
  const text = (value) =>
    value === undefined || value === null ? null : String(value);
  switch (peer?.className) {
    case 'InputPeerUser':
    case 'InputPeerUserFromMessage':
      return text(peer.userId);
    case 'InputPeerChat':
      return peer.chatId === undefined ? null : `-${peer.chatId}`;
    case 'InputPeerChannel':
    case 'InputPeerChannelFromMessage':
      return peer.channelId === undefined ? null : `-100${peer.channelId}`;
    case 'InputPeerSelf':
      return text(selfId);
    default:
      return null;
  }
};

const titleOf = (title) =>
  typeof title === 'string' ? title : String(title?.text ?? '');

const chatsOf = (peers, selfId) =>
  (Array.isArray(peers) ? peers : [])
    .map((peer) => peerChat(peer, selfId))
    .filter(Boolean);

/** One of Telegram's DialogFilter* as the page's folder, or null. */
export const folderOf = (filter, selfId = null) => {
  if (filter?.className === 'DialogFilterDefault') {
    return { id: 0, all: true };
  }
  if (
    filter?.className !== 'DialogFilter' &&
    filter?.className !== 'DialogFilterChatlist'
  ) {
    return null;
  }
  const base = {
    id: Number(filter.id),
    title: titleOf(filter.title),
    emoticon: filter.emoticon ?? null,
    // The tag's colour, 0 to 6, when the folder has one (R-Y180).
    color: Number.isInteger(filter.color) ? filter.color : null,
    include: chatsOf(filter.includePeers, selfId),
    pinned: chatsOf(filter.pinnedPeers, selfId),
  };
  if (filter.className === 'DialogFilterChatlist') {
    // A shared folder: its chats by name only.
    return {
      ...base,
      chatlist: true,
      hasMyInvites: Boolean(filter.hasMyInvites),
      exclude: [],
    };
  }
  return {
    ...base,
    contacts: Boolean(filter.contacts),
    nonContacts: Boolean(filter.nonContacts),
    groups: Boolean(filter.groups),
    broadcasts: Boolean(filter.broadcasts),
    bots: Boolean(filter.bots),
    excludeMuted: Boolean(filter.excludeMuted),
    excludeRead: Boolean(filter.excludeRead),
    excludeArchived: Boolean(filter.excludeArchived),
    exclude: chatsOf(filter.excludePeers, selfId),
  };
};

const needsSelf = (filters) =>
  filters.some((f) =>
    [f?.includePeers, f?.excludePeers, f?.pinnedPeers].some((peers) =>
      (peers ?? []).some((p) => p?.className === 'InputPeerSelf')
    )
  );

/** `userClient()` is the connected user client, or null. */
export const createFolders = (
  env,
  { userClient },
  { now = () => Date.now() } = {}
) => {
  let kept = null; // { at, folders, tags }

  const folderList = async ({ fresh = false } = {}) => {
    if (!fresh && kept && now() - kept.at < KEEP_MS) {
      return { ok: true, folders: kept.folders, tags: kept.tags };
    }
    const client = await userClient();
    if (!client) {
      return { ok: false, supported: false };
    }
    const { Api } = await env.importer();
    const answer = await client.invoke(new Api.messages.GetDialogFilters());
    // Newer layers answer messages.dialogFilters, older ones a vector.
    const filters = Array.isArray(answer) ? answer : (answer?.filters ?? []);
    const self = needsSelf(filters) ? await client.getMe() : null;
    const folders = filters
      .map((filter) => folderOf(filter, self?.id ?? null))
      .filter(Boolean);
    // Whether folder tags show on the chat list (R-Y180).
    const tags = Boolean(answer?.tagsEnabled);
    kept = { at: now(), folders, tags };
    return { ok: true, folders, tags };
  };

  return { folderList };
};

/**
 * Text formatting as Telegram's apps send it (R-Y101; Telegram Desktop's
 * markdown and its formatting shortcuts, learned, never copied).
 *
 * What is typed is sent as Telegram's entities, the markers removed:
 *
 *   **bold**   __italic__   ~~strike~~   ||spoiler||   `code`
 *   <u>underline</u>   ```lang
 *   pre (a code block)```   [text](https://link)
 *
 * As in Desktop, a marker counts only at a word's edge ("2**3**4" and
 * "snake__case__name" stay as typed), the formatted text cannot start or
 * end with a space, a lone `*` or `_` stays, and nothing is parsed inside
 * code; underline, which Telegram's markdown has no marker for (Desktop
 * makes it with Ctrl+U), is <u>…</u>. Offsets and lengths are UTF-16 units — what Telegram counts and
 * what JS strings index.
 *
 * Pure: shared by the server (sending, editing) and the page (pending
 * messages, the composer's shortcuts, editing a formatted message).
 */

const PAIRS = [
  ['**', 'bold'],
  ['__', 'italic'],
  ['~~', 'strike'],
  ['||', 'spoiler'],
];

export const CLASS_OF = Object.freeze({
  bold: 'MessageEntityBold',
  italic: 'MessageEntityItalic',
  strike: 'MessageEntityStrike',
  spoiler: 'MessageEntitySpoiler',
  underline: 'MessageEntityUnderline',
  code: 'MessageEntityCode',
  pre: 'MessageEntityPre',
  link: 'MessageEntityTextUrl',
  customEmoji: 'MessageEntityCustomEmoji',
});

const TYPE_OF = Object.fromEntries(
  Object.entries(CLASS_OF).map(([type, name]) => [name, type])
);

const WORD = /[\p{L}\p{N}]/u;
const SPACE = /\s/u;
const LINK =
  /^\[([^[\]\n]+)\]\(((?:https?:\/\/|tg:\/\/|mailto:)[^\s()]+|(?:[\p{L}\p{N}-]+\.)+\p{L}{2,}(?:\/[^\s()]*)?)\)/u;
// ![😀](tg://emoji?id=5368324170671202286): a custom emoji (R-Y214) — the
// fallback emoji it stands for, then the document's id.
const EMOJI = /^!\[([^[\]\s]{1,32})\]\(tg:\/\/emoji\?id=(\d{1,20})\)/u;
const LANGUAGE = /^([\w+#.-]{1,32})\n/;

const isWord = (char) => Boolean(char) && WORD.test(char);
const isSpace = (char) => Boolean(char) && SPACE.test(char);

/** A link as Telegram takes it: a bare domain gets https://. */
export const linkUrl = (url) =>
  /^(?:[a-z][a-z0-9+.-]*:)/i.test(url) ? url : `https://${url}`;

// ```lang\ncode``` — taken as typed.
const preAt = (src, i) => {
  if (!src.startsWith('```', i)) {
    return null;
  }
  const close = src.indexOf('```', i + 3);
  if (close < 0) {
    return null;
  }
  let inner = src.slice(i + 3, close);
  const lang = LANGUAGE.exec(inner);
  const language = lang ? lang[1] : '';
  inner = lang ? inner.slice(lang[0].length) : inner.replace(/^\n/, '');
  inner = inner.replace(/\n$/, '');
  return inner
    ? { type: 'pre', inner, literal: true, end: close + 3, language }
    : null;
};

// `code` — one line, taken as typed.
const codeAt = (src, i) => {
  if (src[i] !== '`' || isWord(src[i - 1])) {
    return null;
  }
  const close = src.indexOf('`', i + 1);
  const inner = close > i + 1 ? src.slice(i + 1, close) : '';
  if (!inner || inner.includes('\n') || isWord(src[close + 1])) {
    return null;
  }
  return { type: 'code', inner, literal: true, end: close + 1 };
};

const linkAt = (src, i) => {
  if (src[i] !== '[') {
    return null;
  }
  const found = LINK.exec(src.slice(i));
  return found
    ? {
        type: 'link',
        inner: found[1],
        end: i + found[0].length,
        url: linkUrl(found[2]),
      }
    : null;
};

const emojiAt = (src, i) => {
  if (src[i] !== '!') {
    return null;
  }
  const found = EMOJI.exec(src.slice(i));
  return found
    ? {
        type: 'customEmoji',
        inner: found[1],
        literal: true,
        end: i + found[0].length,
        documentId: found[2],
      }
    : null;
};

// **bold**, __italic__, ~~strike~~, ||spoiler||: at a word's edge, not
// starting or ending with a space; the first close that fits ends it.
const pairAt = (src, i) => {
  const pair = PAIRS.find(([tag]) => src.startsWith(tag, i));
  if (!pair || isWord(src[i - 1])) {
    return null;
  }
  const [tag, type] = pair;
  const from = i + tag.length;
  if (!src[from] || isSpace(src[from]) || src.startsWith(tag, from)) {
    return null;
  }
  for (
    let close = src.indexOf(tag, from + 1);
    close > 0;
    close = src.indexOf(tag, close + 1)
  ) {
    const after = src[close + tag.length];
    if (
      !isSpace(src[close - 1]) &&
      !isWord(after) &&
      after !== tag[0] &&
      src[close - 1] !== tag[0]
    ) {
      return { type, inner: src.slice(from, close), end: close + tag.length };
    }
  }
  return null;
};

// <u>underline</u>: anywhere, not starting or ending with a space.
const underlineAt = (src, i) => {
  if (!src.startsWith('<u>', i)) {
    return null;
  }
  const close = src.indexOf('</u>', i + 3);
  const inner = close > i + 3 ? src.slice(i + 3, close) : '';
  return inner && inner.trim() === inner
    ? { type: 'underline', inner, end: close + 4 }
    : null;
};

const MATCHERS = [preAt, codeAt, emojiAt, linkAt, underlineAt, pairAt];

const parseInto = (src, out) => {
  let i = 0;
  while (i < src.length) {
    const match = MATCHERS.reduce((found, at) => found ?? at(src, i), null);
    if (!match) {
      out.text += src[i];
      i += 1;
      continue;
    }
    const offset = out.text.length;
    if (match.literal) {
      out.text += match.inner;
    } else {
      parseInto(match.inner, out);
    }
    const length = out.text.length - offset;
    if (length > 0) {
      out.entities.push({
        type: match.type,
        offset,
        length,
        ...(match.type === 'pre' ? { language: match.language } : {}),
        ...(match.url ? { url: match.url } : {}),
        ...(match.documentId ? { documentId: match.documentId } : {}),
      });
    }
    i = match.end;
  }
  return out;
};

const byPlace = (a, b) => a.offset - b.offset || b.length - a.length;

/** Typed text → `{ text, entities: [{ type, offset, length, url?, language? }] }`. */
export const parseFormatted = (input) => {
  const out = parseInto(String(input ?? ''), { text: '', entities: [] });
  out.entities.sort(byPlace);
  return out;
};

/** Our entities as GramJS's MessageEntity classes. */
export const apiEntities = (Api, entities = []) =>
  entities
    .filter((e) => Api?.[CLASS_OF[e.type]])
    .map((e) => {
      const { type, ...fields } = e;
      if (type === 'customEmoji') {
        // The document's id is a 64-bit number: a BigInt (R-Y214).
        return new Api[CLASS_OF[type]]({
          ...fields,
          documentId: BigInt(fields.documentId),
        });
      }
      return new Api[CLASS_OF[type]](
        type === 'pre' ? { ...fields, language: fields.language ?? '' } : fields
      );
    });

/** Our entities as a stored message's (`raw.entities`, by className). */
export const rawEntities = (entities = []) =>
  entities.map(({ type, ...fields }) => ({
    className: CLASS_OF[type],
    ...fields,
  }));

/**
 * `{ text, entities }` cut at `ranges` ([start, end) of the text, as the
 * long-message split gives them): each part with its own entities.
 */
export const sliceFormatted = ({ text, entities }, ranges) =>
  ranges.map(([start, end]) => ({
    text: text.slice(start, end),
    entities: entities
      .map((e) => {
        const from = Math.max(e.offset, start);
        const to = Math.min(e.offset + e.length, end);
        return { ...e, offset: from - start, length: to - from };
      })
      .filter((e) => e.length > 0),
  }));

const OPEN = {
  bold: () => '**',
  italic: () => '__',
  strike: () => '~~',
  spoiler: () => '||',
  underline: () => '<u>',
  code: () => '`',
  pre: (e) => `\`\`\`${e.language ?? ''}\n`,
  link: () => '[',
  customEmoji: () => '![',
};
const CLOSE = {
  ...OPEN,
  pre: () => '\n```',
  underline: () => '</u>',
  link: (e) => `](${e.url})`,
  customEmoji: (e) => `](tg://emoji?id=${e.documentId})`,
};

/**
 * A message's text and entities back as what one would type: editing a
 * formatted message keeps its formatting, as Desktop's edit box does.
 * Custom emoji come back as `![😀](tg://emoji?id=…)` (R-Y214); entities
 * markdown cannot say (quotes) are left out.
 */
export const toMarkdown = (text, entities = []) => {
  const known = entities
    .map((e) => ({
      ...e,
      type: e.type ?? TYPE_OF[e.className],
      documentId: e.documentId?.value ?? e.documentId,
    }))
    .filter(
      (e) =>
        OPEN[e.type] &&
        (e.type !== 'customEmoji' || /^\d{1,20}$/.test(String(e.documentId))) &&
        Number(e.length) > 0 &&
        (e.type !== 'link' || e.url) &&
        e.offset + e.length <= text.length
    )
    .sort(byPlace);
  // Closes before opens at one place; the inner closes first, the outer
  // opens first.
  const marks = [
    ...known.map((e, n) => ({
      at: e.offset,
      rank: 1,
      n,
      put: OPEN[e.type](e),
    })),
    ...known.map((e, n) => ({
      at: e.offset + e.length,
      rank: 0,
      n: -n,
      put: CLOSE[e.type](e),
    })),
  ].sort((a, b) => a.at - b.at || a.rank - b.rank || a.n - b.n);
  let out = '';
  let at = 0;
  for (const mark of marks) {
    out += text.slice(at, mark.at) + mark.put;
    at = mark.at;
  }
  return out + text.slice(at);
};

export const MARKERS = Object.freeze({
  bold: ['**', '**'],
  italic: ['__', '__'],
  strike: ['~~', '~~'],
  spoiler: ['||', '||'],
  underline: ['<u>', '</u>'],
  code: ['`', '`'],
  link: ['[', ']()'],
});

/**
 * The composer's shortcut: wrap the selection [start, end) of `value` in
 * `kind`'s markers — or take them off when it is wrapped already (a
 * toggle, as Desktop's). Spaces at the selection's edges stay outside.
 * Answers the replaced range, what goes there, and the new selection.
 */
export const wrapSelection = (value, start, end, kind) => {
  const [open, close] = MARKERS[kind];
  let from = start;
  let to = end;
  while (from < to && isSpace(value[from])) {
    from += 1;
  }
  while (to > from && isSpace(value[to - 1])) {
    to -= 1;
  }
  const inner = value.slice(from, to);
  if (
    kind !== 'link' &&
    value.slice(from - open.length, from) === open &&
    value.slice(to, to + close.length) === close
  ) {
    return {
      from: from - open.length,
      to: to + close.length,
      insert: inner,
      select: [from - open.length, to - open.length],
    };
  }
  const at = from + open.length;
  return {
    from,
    to,
    insert: `${open}${inner}${close}`,
    // A link's address goes between the brackets; else the text stays
    // selected (or the caret sits between the markers).
    select:
      kind === 'link'
        ? [at + inner.length + 2, at + inner.length + 2]
        : [at, at + inner.length],
  };
};

/**
 * A forum group seen as its whole message list or as its topics, as
 * Telegram Desktop's ⋯ menu has it (R-Y171; learned, never copied):
 * - `forumView({ chat, asMessages })` — channels.toggleViewForumAsMessages
 *   with `enabled` = asMessages → `{ ok, asMessages }`. Called only on the
 *   user's click; the flag Telegram keeps comes back with the chat info
 *   (channelFull view_forum_as_messages).
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';

const CODES = {
  CHANNEL_FORUM_MISSING: 'not-forum',
  CHANNEL_INVALID: 'no-access',
  CHANNEL_PRIVATE: 'no-access',
  CHAT_ID_INVALID: 'no-access',
  FLOOD_WAIT: 'flood',
};
const failure = failureOf(CODES);

export const createForumView = (env, { userClient }) => ({
  forumView: async ({ chat, asMessages } = {}) =>
    !/^-100\d{1,15}$/.test(String(chat ?? '')) ||
    typeof asMessages !== 'boolean'
      ? { ok: false, error: 'bad request', code: 'bad-request' }
      : connected(env, userClient, failure, async (c) => {
          await runIn(env, `forum-view:${chat}`, () =>
            env.connection.withPeer(c.client, String(chat), (peer) =>
              c.client.invoke(
                new c.Api.channels.ToggleViewForumAsMessages({
                  channel: peer,
                  enabled: asMessages,
                })
              )
            )
          );
          return { ok: true, asMessages };
        }),
});

/**
 * A forum group's topics, as Telegram's apps show them (R-Y122; Telegram
 * Desktop's forum, learned, never copied):
 *
 * - `forumTopics({ chat })` — `{ ok, forum, topics }`: the topics
 *   (messages.getForumTopics), pinned first, each `{ id, title,
 *   iconColor, iconEmojiId, top, unread, readInboxMaxId, mentions,
 *   pinned, closed,
 *   hidden, at, last }`, `last` the topic's newest message (stored as
 *   any read one is). A group that is not a forum: `forum: false`. Kept
 *   for a little while, so the page can ask as often as it shows them.
 * - `topicHistory({ chat, topic, before, limit })` — `{ written,
 *   complete }`: a topic's newest messages, or the page before message
 *   `before` (messages.getReplies on the topic's first message), stored;
 *   the page reads them from the store by the topic's key.
 */

import { GENERAL_TOPIC } from '../web/forum-topics.js';

const KEEP_MS = 15_000;
const TOPICS_LIMIT = 100;

const text = (value) =>
  value === null || value === undefined ? null : String(value.value ?? value);

const iso = (date) =>
  date ? new Date(Number(date) * 1000).toISOString() : null;

const notForum = (error) =>
  /CHANNEL_FORUM_MISSING|CHANNEL_INVALID|CHAT_ID_INVALID/.test(
    `${error?.errorMessage ?? ''} ${error?.message ?? ''}`
  );

/** One ForumTopic as the page shows it; null for a deleted one. */
export const topicOf = (topic, last = null) => {
  if (topic?.className !== 'ForumTopic') {
    return null;
  }
  const color = Number(topic.iconColor);
  return {
    id: Number(topic.id),
    title: String(topic.title ?? ''),
    iconColor: Number.isFinite(color) ? color : null,
    iconEmojiId: text(topic.iconEmojiId),
    top: Number(topic.topMessage) || 0,
    unread: Number(topic.unreadCount) || 0,
    readInboxMaxId: Number(topic.readInboxMaxId) || 0,
    mentions: Number(topic.unreadMentionsCount) || 0,
    pinned: Boolean(topic.pinned),
    closed: Boolean(topic.closed),
    mine: Boolean(topic.my),
    hidden: Boolean(topic.hidden),
    at: iso(topic.date),
    last,
  };
};

// Telegram's order, the pinned first (as listed among themselves).
const pinnedFirst = (topics) => [
  ...topics.filter((t) => t.pinned),
  ...topics.filter((t) => !t.pinned),
];

// A topic's newest message as the row under its name.
const lastOf = (link) =>
  link
    ? {
        id: link.id,
        body: String(link.body ?? ''),
        at: link.timestamp ?? null,
        mine: link.sender === 'me',
        senderName: link.senderName ?? null,
      }
    : null;

// Forum dialogs can retain a nonzero aggregate after every topic was read.
// Only a complete topic list can replace that aggregate with an exact count.
const saveTopicUnread = async (store, chat, topics, count, baseline) => {
  if (!Number.isFinite(count) || count < 0 || count > topics.length) {
    return false;
  }
  const before = await store.get(`read:telegram:${chat}`);
  if (
    ['inboxMaxId', 'unreadTopId', 'unreadCount'].some(
      (key) => before?.[key] !== baseline?.[key]
    )
  ) {
    return false;
  }
  const unreadCount = topics.reduce(
    (sum, topic) => sum + Math.max(0, topic.unread),
    0
  );
  const top = Math.max(
    Number(before?.unreadTopId ?? 0),
    ...topics.map((topic) => topic.top),
    0
  );
  await store.put({
    ...before,
    id: `read:telegram:${chat}`,
    tokens: ['read', 'telegram', chat],
    source: 'telegram',
    chat,
    forum: 1,
    forumUnreadCount: unreadCount,
    forumUnreadTopId: top,
    forumDialogUnreadCount: Number(before?.unreadCount ?? 0),
    forumReadInboxMaxId: Number(before?.inboxMaxId ?? 0),
  });
  return true;
};

/**
 * `env` is the account's; `userClient()` the user client or null;
 * `dialogOf(chat)` the chat as listed; `tools` its `toLinks` and
 * `writeChanged`.
 */
export const createForum = (
  env,
  { userClient, dialogOf, tools },
  { now = () => Date.now() } = {}
) => {
  const kept = new Map(); // chat -> { at, answer }
  const asking = new Map(); // chat -> the answer coming

  const ask = async (target) => {
    const client = await userClient();
    if (!client) {
      return { ok: false, supported: false };
    }
    const { Api } = await env.importer();
    const baseline = await env.store.get(`read:telegram:${target}`);
    let answer;
    try {
      answer = await env.queue.run(`forum-topics:${target}`, 'view', () =>
        env.connection.withPeer(client, target, (peer) =>
          client.invoke(
            new Api.messages.GetForumTopics({
              peer,
              offsetDate: 0,
              offsetId: 0,
              offsetTopic: 0,
              limit: TOPICS_LIMIT,
            })
          )
        )
      );
    } catch (error) {
      if (notForum(error)) {
        const plain = { ok: true, forum: false, topics: [] };
        kept.set(target, { at: now(), answer: plain });
        return plain;
      }
      throw error;
    }
    const messages = [...(answer?.messages ?? [])].filter(
      (m) => m && m.id !== undefined && m.className !== 'MessageEmpty'
    );
    const links = tools.toLinks(await dialogOf(target), messages);
    await tools.writeChanged(env.store, links);
    const byId = new Map(links.map((l) => [Number(l.id.split(':').at(-1)), l]));
    const topics = pinnedFirst(
      [...(answer?.topics ?? [])]
        .map((t) => topicOf(t, lastOf(byId.get(Number(t?.topMessage)))))
        .filter(Boolean)
    );
    const count = Number(answer?.count);
    const complete = await saveTopicUnread(
      env.store,
      target,
      topics,
      count,
      baseline
    );
    const result = { ok: true, forum: true, topics, count, complete };
    kept.set(target, { at: now(), answer: result });
    return result;
  };

  const forumTopics = async ({ chat, fresh = false } = {}) => {
    if (!chat || !String(chat).startsWith('-100')) {
      return { ok: true, forum: false, topics: [] };
    }
    const target = String(chat);
    const entry = kept.get(target);
    if (!fresh && entry && now() - entry.at < KEEP_MS) {
      return entry.answer;
    }
    if (!asking.has(target)) {
      asking.set(
        target,
        ask(target).finally(() => asking.delete(target))
      );
    }
    return asking.get(target);
  };

  const topicHistory = async ({
    chat,
    topic,
    before = null,
    limit = 50,
    priority = 'view',
  } = {}) => {
    const id = Number(topic);
    const client =
      chat && Number.isInteger(id) && id > 0 ? await userClient() : null;
    if (!client) {
      return { written: 0 };
    }
    const target = String(chat);
    const offset = Number(before);
    const page = await env.queue.run(
      `replies:${target}:${id}:${offset || 0}`,
      priority,
      () =>
        env.connection.withPeer(client, target, (peer) =>
          client.getMessages(peer, {
            replyTo: id,
            limit,
            ...(Number.isInteger(offset) && offset > 0
              ? { offsetId: offset }
              : {}),
          })
        )
    );
    const messages = [...(page ?? [])].filter(
      (m) => m && m.id !== undefined && m.className !== 'MessageEmpty'
    );
    const written = await tools.writeChanged(
      env.store,
      tools.toLinks(await dialogOf(target), messages)
    );
    // The topic's first message is its start (General has none: a short
    // page is).
    const reachedStart =
      messages.length < limit ||
      (id !== GENERAL_TOPIC && messages.some((m) => Number(m.id) === id));
    return { written, cached: false, complete: reachedStart };
  };

  return { forumTopics, topicHistory };
};

/**
 * HTML5 bot games, as Telegram Desktop shows them (R-Y190; learned, never
 * copied): `gameHighScores({ chat, id })` — a game message's high scores
 * (messages.getGameHighScores, asked as the user themself) →
 * `{ ok, scores: [{ pos, user, name, score, me }] }`, best first. Playing
 * itself is a bot button's press (messages.getBotCallbackAnswer with
 * `game`, in ./telegram-bots.js). Posting a score (setGameScore) is for
 * bots only and is not offered.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';

const CODES = {
  MESSAGE_ID_INVALID: 'not-found',
  USER_BOT_REQUIRED: 'not-found',
  PEER_ID_INVALID: 'no-access',
  CHANNEL_PRIVATE: 'no-access',
  CHAT_ID_INVALID: 'no-access',
};

const failure = failureOf(CODES);

const CHAT = /^-?\d{1,20}$/;
const textOf = (value) => String(value?.value ?? value);

const nameOf = (user) =>
  [user?.firstName, user?.lastName].filter(Boolean).join(' ') ||
  user?.username ||
  '';

/** The scores of an answer, each named by the users sent along. */
export const scoresOf = (answer) => {
  const users = new Map((answer?.users ?? []).map((u) => [textOf(u.id), u]));
  return (answer?.scores ?? []).map((one) => {
    const user = textOf(one.userId);
    return {
      pos: Number(one.pos) || 0,
      user,
      name: nameOf(users.get(user)) || user,
      score: Number(one.score) || 0,
      me: Boolean(users.get(user)?.self),
    };
  });
};

export const createGames = (env, context) => ({
  gameHighScores: async ({ chat, id } = {}) => {
    if (!CHAT.test(String(chat ?? '')) || !(Number(id) > 0)) {
      return { ok: false, error: 'bad request', code: 'failed' };
    }
    return connected(env, context.userClient, failure, async (c) => {
      const answer = await runIn(env, `game-scores:${chat}:${id}`, () =>
        env.connection.withPeer(c.client, String(chat), (peer) =>
          c.client.invoke(
            new c.Api.messages.GetGameHighScores({
              peer,
              id: Number(id),
              userId: new c.Api.InputUserSelf(),
            })
          )
        )
      );
      return { ok: true, scores: scoresOf(answer) };
    });
  },
});

/**
 * A GIF in a chat saved to the user's GIFs or taken from them, as Telegram
 * Desktop's message menu does (R-Y171; learned, never copied):
 * - `messageGifSave({ chat, message, unsave })` — `{ ok, id, saved }`:
 *   reads the message (its document comes with a fresh file reference),
 *   checks it is an animation, and asks messages.saveGif with its
 *   InputDocument (`unsave` true removes it). A FILE_REFERENCE_EXPIRED
 *   answer reads the message again once, as the file reader does. The
 *   panel's saved list (messages.getSavedGifs) is asked again after.
 * Telegram's errors become codes the page shows as text.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';

const CODES = {
  FILE_REFERENCE_EXPIRED: 'expired',
  DOCUMENT_INVALID: 'not-gif',
  MESSAGE_ID_INVALID: 'no-message',
  PEER_ID_INVALID: 'no-access',
  CHANNEL_PRIVATE: 'no-access',
  FLOOD_WAIT: 'flood',
};
const failure = failureOf(CODES);

const bad = (code) => ({ ok: false, error: code, code });

const textOf = (value) =>
  value === null || value === undefined ? '' : String(value.value ?? value);

const isGif = (doc) =>
  doc?.className === 'Document' &&
  (doc.attributes ?? []).some(
    (a) => a?.className === 'DocumentAttributeAnimated'
  );

const expired = (error) =>
  /FILE_REFERENCE_(EXPIRED|INVALID)/.test(
    String(error?.errorMessage ?? error?.message ?? '')
  );

// The message's animation, read from Telegram.
const gifOf = async (c, peer, id) => {
  const [message] = await c.client.getMessages(peer, { ids: [id] });
  const doc = message?.media?.document;
  return isGif(doc) ? doc : null;
};

const saveRequest = (c, doc, unsave) =>
  new c.Api.messages.SaveGif({
    id: new c.Api.InputDocument({
      id: c.helpers.returnBigInt(textOf(doc.id)),
      accessHash: c.helpers.returnBigInt(textOf(doc.accessHash)),
      fileReference: Buffer.from(doc.fileReference ?? []),
    }),
    unsave,
  });

// One try: read the message, save or unsave its GIF.
const attempt = async (c, peer, id, unsave) => {
  const doc = await gifOf(c, peer, id);
  if (!doc) {
    return bad('not-gif');
  }
  await c.client.invoke(saveRequest(c, doc, unsave));
  return { ok: true, id: textOf(doc.id), saved: !unsave };
};

// The same, read again once when the file reference had expired.
const withRetry = async (c, peer, id, unsave) => {
  try {
    return await attempt(c, peer, id, unsave);
  } catch (error) {
    if (!expired(error)) {
      throw error;
    }
    return attempt(c, peer, id, unsave);
  }
};

/** `stickers`: the sticker module's lists (`changed`). */
export const createGifSave = (env, { userClient, stickers }) => ({
  messageGifSave: async ({ chat, message, unsave = false } = {}) => {
    const id = Number(message);
    if (!/^-?\d{1,20}$/.test(String(chat ?? '')) || !(id > 0)) {
      return bad('bad-request');
    }
    return connected(env, userClient, failure, async (c) => {
      const answer = await runIn(env, `gif-save:${chat}:${id}`, () =>
        env.connection.withPeer(c.client, String(chat), (peer) =>
          withRetry(c, peer, id, unsave === true)
        )
      );
      if (answer.ok) {
        stickers?.changed?.();
      }
      return answer;
    });
  },
});

/**
 * Sending a gift to a person, as Telegram Desktop's "Send a gift" does
 * (R-Y185; learned, never copied):
 * - `giftCatalogue({ fresh? })` — the gifts one can buy
 *   (payments.getStarGifts, asked with the hash of the last answer, so an
 *   unchanged catalogue is not sent again) → `{ ok, gifts: [{ id, stars,
 *   title, limited, soldOut, remains, total, premium, birthday, sticker }] }`;
 *   each `sticker` is the sticker panel's item (see telegram-stickers.js);
 * - `giftSend({ chat, gift, stars, text?, hideName? })` — the only thing
 *   that pays, on the confirmation's button alone: payments.checkCanSendGift
 *   first (the person may not take gifts), then payments.getPaymentForm
 *   with an InputInvoiceStarGift, then payments.sendStarsForm with that
 *   form's id — and only when the form's price is the `stars` the page
 *   showed (else `code: 'price'`, nothing is paid).
 * Telegram's errors become codes the page shows as text.
 */

import { formPrice } from './telegram-stars.js';
import { connected, failureOf, panelItem, runIn } from './telegram-stickers.js';

/** The longest message with a gift Telegram's usual limit allows. */
export const TEXT_MAX = 255;

const CODES = {
  BALANCE_TOO_LOW: 'balance',
  STARS_BALANCE_TOO_LOW: 'balance',
  PAYMENT_FAILED: 'balance',
  STARGIFT_USAGE_LIMITED: 'sold-out',
  STARGIFT_INVALID: 'no-gift',
  STARGIFT_NOT_FOUND: 'no-gift',
  INVOICE_INVALID: 'no-gift',
  USER_PRIVACY_RESTRICTED: 'privacy',
  PEER_ID_INVALID: 'no-chat',
  USER_ID_INVALID: 'no-chat',
  FORM_ID_EXPIRED: 'expired',
  MESSAGE_TOO_LONG: 'too-long',
  FLOOD_WAIT: 'flood',
};
const failure = failureOf(CODES);
const BAD = { ok: false, error: 'bad request', code: 'failed' };
const USER = /^\d{1,20}$/;
const GIFT = /^\d{1,20}$/;

const text = (value) => String(value?.value ?? value ?? '');
const whole = (n) => Number(n ?? 0) || 0;

/** A catalogue gift as the page's card. */
export const giftCard = (gift, remember) => ({
  id: text(gift.id),
  stars: whole(gift.stars),
  title: String(gift.title ?? ''),
  limited: Boolean(gift.limited),
  soldOut: Boolean(gift.soldOut),
  remains: gift.limited ? whole(gift.availabilityRemains) : null,
  total: gift.limited ? whole(gift.availabilityTotal) : null,
  premium: Boolean(gift.requirePremium),
  birthday: Boolean(gift.birthday),
  sticker:
    gift.sticker?.className === 'Document' ? remember(gift.sticker) : null,
});

const valid = (request) =>
  USER.test(String(request?.chat ?? '')) &&
  GIFT.test(String(request?.gift ?? '')) &&
  Number.isInteger(request?.stars) &&
  request.stars >= 1 &&
  (request.text === undefined ||
    (typeof request.text === 'string' && request.text.length <= TEXT_MAX)) &&
  (request.hideName === undefined || typeof request.hideName === 'boolean');

export const createGiftSend = (env, { userClient, stickers }) => {
  let held = null; // { hash, gifts } of the last catalogue answer
  const doing = (key, use) =>
    connected(env, userClient, failure, (c) => runIn(env, key, () => use(c)));
  const remember = (doc) =>
    stickers?.remember
      ? stickers.remember([doc], 'gift:catalogue', 'sticker')[0]
      : panelItem(doc);

  const giftCatalogue = async ({ fresh = false } = {}) =>
    doing('gift-send:catalogue', async (c) => {
      const hash = held && !fresh ? held.hash : 0;
      const answer = await c.client.invoke(
        new c.Api.payments.GetStarGifts({ hash })
      );
      if (answer?.className === 'payments.StarGiftsNotModified' && held) {
        return { ok: true, gifts: held.gifts };
      }
      const gifts = (answer?.gifts ?? [])
        .filter((g) => g?.className === 'StarGift' && !g.auction)
        .map((g) => giftCard(g, remember));
      held = { hash: whole(answer?.hash), gifts };
      return { ok: true, gifts };
    });

  // A gift's sticker file reference expired: the catalogue, again.
  stickers?.onAgain?.('gift:catalogue', () => giftCatalogue({ fresh: true }));

  // Whether this person takes gifts: a reason in words, or null.
  const refusal = async (c, gift) => {
    if (!c.Api.payments.CheckCanSendGift) {
      return null;
    }
    const result = await c.client.invoke(
      new c.Api.payments.CheckCanSendGift({
        giftId: c.helpers.returnBigInt(gift),
      })
    );
    return result?.className === 'payments.CheckCanSendGiftResultFail'
      ? String(result.reason?.text ?? '')
      : null;
  };

  const pay = async (c, peer, request) => {
    const why = await refusal(c, String(request.gift));
    if (why !== null) {
      return { ok: false, error: why || 'cannot send', code: 'cannot' };
    }
    const invoice = new c.Api.InputInvoiceStarGift({
      peer,
      giftId: c.helpers.returnBigInt(String(request.gift)),
      ...(request.hideName ? { hideName: true } : {}),
      ...(request.text
        ? {
            message: new c.Api.TextWithEntities({
              text: request.text,
              entities: [],
            }),
          }
        : {}),
    });
    const form = await c.client.invoke(
      new c.Api.payments.GetPaymentForm({ invoice })
    );
    if (formPrice(form) !== request.stars) {
      return { ok: false, error: 'price changed', code: 'price' };
    }
    const result = await c.client.invoke(
      new c.Api.payments.SendStarsForm({ formId: form.formId, invoice })
    );
    return result?.className === 'payments.PaymentVerificationNeeded'
      ? { ok: false, error: 'verification needed', code: 'verify' }
      : { ok: true, paid: request.stars };
  };

  const giftSend = async (request = {}) =>
    !valid(request)
      ? BAD
      : doing(`gift-send:${request.chat}`, (c) =>
          env.connection.withPeer(c.client, String(request.chat), (peer) =>
            pay(c, peer, request)
          )
        );

  return { giftCatalogue, giftSend };
};

/**
 * Managing received gifts, unique (collectible) gifts and gift codes, as
 * Telegram Desktop does (R-Y193; learned, never copied). The list of a
 * person's gifts is `starGifts` (telegram-stars.js); this adds what is done
 * to one. A gift is named by `chat` and either `msgId` (a gift of a person,
 * InputSavedStarGiftUser) or `savedId` (a gift of a chat,
 * InputSavedStarGiftChat). Every write happens on its own click, behind the
 * page's confirmation:
 * - `giftConvert(ref)` — payments.convertStarGift → `{ ok }`;
 * - `giftUpgradePreview({ giftId })` — payments.getStarGiftUpgradePreview →
 *   `{ ok, models, patterns, backdrops, prices }` (what an upgrade may
 *   become; nothing is changed);
 * - `giftUpgrade({ ...ref, stars, keepDetails? })` — free (`stars` 0:
 *   payments.upgradeStarGift) or paid (a payment form with
 *   InputInvoiceStarGiftUpgrade, sent only when its price is the `stars`
 *   the page showed, else `code: 'price'`, nothing is paid);
 * - `giftTransfer({ ...ref, to, stars })` — the same for a unique gift
 *   given to the person `to` (payments.transferStarGift or an
 *   InputInvoiceStarGiftTransfer form);
 * - `giftPin({ chat, pins })` — payments.toggleStarGiftsPinnedToTop sets the
 *   pinned list (the app config's `stargifts_pinned_to_top_limit`, else 6;
 *   more is refused with `code: 'pin-limit'` and the `limit`);
 * - `giftUnique({ slug })` — payments.getUniqueStarGift → `{ ok, gift }`;
 * - `giftCodeCheck({ slug })` — payments.checkGiftCode → `{ ok, info }`;
 * - `giftCodeApply({ slug })` — payments.applyGiftCode (Premium, for the
 *   months the code holds).
 * Telegram's errors become codes the page shows as text.
 */

import { entitiesOf, formPrice, nameOf, peerEntity } from './telegram-stars.js';
import { connected, failureOf, runIn } from './telegram-stickers.js';

/** Telegram's default of gifts pinned to the top of a profile. */
export const PIN_LIMIT = 6;
const PIN_KEY = 'stargifts_pinned_to_top_limit';
const LISTED = 12; // the most of each kind of attribute a preview lists

const CODES = {
  STARGIFT_ALREADY_UPGRADED: 'already',
  STARGIFT_ALREADY_CONVERTED: 'already',
  STARGIFT_CONVERT_TOO_OLD: 'too-old',
  STARGIFT_UPGRADE_UNAVAILABLE: 'cannot-upgrade',
  STARGIFT_TRANSFER_TOO_EARLY: 'too-early',
  STARGIFT_NOT_UNIQUE: 'cannot-transfer',
  STARGIFT_OWNER_INVALID: 'cannot-transfer',
  STARGIFT_SLUG_INVALID: 'no-gift',
  STARGIFT_NOT_FOUND: 'no-gift',
  SAVED_ID_EMPTY: 'no-gift',
  PINNED_TO_TOP_LIMIT: 'pin-limit',
  PAYMENT_REQUIRED: 'price',
  BALANCE_TOO_LOW: 'balance',
  STARS_BALANCE_TOO_LOW: 'balance',
  PAYMENT_FAILED: 'balance',
  USER_PRIVACY_RESTRICTED: 'privacy',
  INVOICE_INVALID: 'no-gift',
  FORM_ID_EXPIRED: 'expired',
  PEER_ID_INVALID: 'no-chat',
  USER_ID_INVALID: 'no-chat',
  GIFT_SLUG_EXPIRED: 'code-expired',
  GIFT_SLUG_INVALID: 'no-code',
  GIFTCODE_NOT_ALLOWED: 'not-allowed',
  PREMIUM_SUB_ACTIVE_UNTIL: 'premium-active',
  FLOOD_WAIT: 'flood',
};
const failure = failureOf(CODES);
const BAD = { ok: false, error: 'bad request', code: 'failed' };
const CHAT = /^-?\d{1,20}$/;
const USER = /^\d{1,20}$/;
const SLUG = /^[A-Za-z0-9_-]{1,100}$/;
const GIFT = /^\d{1,20}$/;
const PINS_MAX = 100;

const text = (value) => String(value?.value ?? value ?? '');
const whole = (n) => Number(n ?? 0) || 0;

/** Whether `request` names one gift: a person's msgId, or a chat's savedId. */
export const validRef = (request) =>
  CHAT.test(String(request?.chat ?? '')) &&
  (Number.isInteger(request.msgId) && request.msgId >= 1
    ? request.savedId === undefined && USER.test(String(request.chat))
    : request.msgId === undefined && GIFT.test(String(request.savedId ?? '')));

/** The part of a request that names one gift (nothing else is passed on). */
export const refOf = (request) =>
  request.msgId !== undefined
    ? { chat: String(request.chat), msgId: request.msgId }
    : { chat: String(request.chat), savedId: String(request.savedId) };

/** A 24-bit colour as "#rrggbb". */
export const hexColor = (n) =>
  `#${((Number(n) >>> 0) & 0xffffff).toString(16).padStart(6, '0')}`;

const RARITIES = {
  StarGiftAttributeRarityUncommon: 'uncommon',
  StarGiftAttributeRarityRare: 'rare',
  StarGiftAttributeRarityEpic: 'epic',
  StarGiftAttributeRarityLegendary: 'legendary',
};

/** How rare an attribute is: `{ rarity }` (a name) or `{ permille }`. */
export const rarityOf = (rarity) =>
  rarity?.className === 'StarGiftAttributeRarity'
    ? { permille: whole(rarity.permille) }
    : { rarity: RARITIES[rarity?.className] ?? '' };

const kindOf = (attributes, className) =>
  (attributes ?? []).filter((a) => a?.className === className);

/** The pinned-gifts limit an app config gives, else Telegram's usual 6. */
export const pinLimitOf = (config) => {
  const entry = (config?.config?.value ?? []).find((e) => e?.key === PIN_KEY);
  const limit = Number(entry?.value?.value);
  return Number.isInteger(limit) && limit > 0 ? limit : PIN_LIMIT;
};

/** What a code says, as the page's info (`months` from its days). */
export const codeInfoOf = (answer) => {
  const entities = entitiesOf(answer);
  const from = answer?.fromId
    ? {
        id: text(
          answer.fromId.userId ??
            answer.fromId.channelId ??
            answer.fromId.chatId
        ),
        name: nameOf(peerEntity(answer.fromId, entities)),
      }
    : null;
  const days = whole(answer?.days);
  return {
    days,
    months: Math.max(1, Math.round(days / 30)),
    from,
    viaGiveaway: Boolean(answer?.viaGiveaway),
    date: whole(answer?.date),
    used: whole(answer?.usedDate) > 0,
    usedDate: whole(answer?.usedDate) || null,
    to: answer?.toId ? text(answer.toId) : null,
  };
};

// The lookups: a unique gift and a gift code, changing nothing but Apply.
const createLookups = ({ doing, sticker }) => {
  const listed = (attributes, className, one) =>
    kindOf(attributes, className).slice(0, LISTED).map(one);

  const giftUpgradePreview = async ({ giftId } = {}) =>
    !GIFT.test(String(giftId ?? ''))
      ? BAD
      : doing(`gift-manage:preview:${giftId}`, async (c) => {
          const answer = await c.client.invoke(
            new c.Api.payments.GetStarGiftUpgradePreview({
              giftId: c.helpers.returnBigInt(String(giftId)),
            })
          );
          const all = answer?.sampleAttributes ?? [];
          const named = (a) => ({
            name: String(a.name ?? ''),
            ...rarityOf(a.rarity),
          });
          return {
            ok: true,
            models: listed(all, 'StarGiftAttributeModel', (a) => ({
              ...named(a),
              sticker: sticker(a.document),
            })),
            patterns: listed(all, 'StarGiftAttributePattern', (a) => ({
              ...named(a),
              sticker: sticker(a.document),
            })),
            backdrops: listed(all, 'StarGiftAttributeBackdrop', (a) => ({
              ...named(a),
              center: hexColor(a.centerColor),
              edge: hexColor(a.edgeColor),
            })),
            prices: (answer?.prices ?? []).map((p) => ({
              date: whole(p.date),
              stars: whole(p.upgradeStars),
            })),
          };
        });

  const attrCard = (a) =>
    a ? { name: String(a.name ?? ''), ...rarityOf(a.rarity) } : null;

  const uniqueOf = (answer) => {
    const gift = answer?.gift;
    if (gift?.className !== 'StarGiftUnique') {
      return null;
    }
    const entities = entitiesOf(answer);
    const [model] = kindOf(gift.attributes, 'StarGiftAttributeModel');
    const [pattern] = kindOf(gift.attributes, 'StarGiftAttributePattern');
    const [backdrop] = kindOf(gift.attributes, 'StarGiftAttributeBackdrop');
    return {
      slug: String(gift.slug ?? ''),
      title: String(gift.title ?? ''),
      num: whole(gift.num),
      issued: whole(gift.availabilityIssued),
      total: whole(gift.availabilityTotal),
      owner: {
        id: gift.ownerId
          ? text(gift.ownerId.userId ?? gift.ownerId.channelId)
          : null,
        name:
          nameOf(peerEntity(gift.ownerId, entities)) ||
          String(gift.ownerName ?? ''),
      },
      model: model && { ...attrCard(model), sticker: sticker(model.document) },
      pattern: pattern && {
        ...attrCard(pattern),
        sticker: sticker(pattern.document),
      },
      backdrop: backdrop && {
        ...attrCard(backdrop),
        center: hexColor(backdrop.centerColor),
        edge: hexColor(backdrop.edgeColor),
        pattern: hexColor(backdrop.patternColor),
        text: hexColor(backdrop.textColor),
      },
    };
  };

  const giftUnique = async ({ slug } = {}) =>
    !SLUG.test(String(slug ?? ''))
      ? BAD
      : doing(`gift-manage:unique:${slug}`, async (c) => {
          const answer = await c.client.invoke(
            new c.Api.payments.GetUniqueStarGift({ slug: String(slug) })
          );
          const gift = uniqueOf(answer);
          return gift
            ? { ok: true, gift }
            : { ok: false, error: 'no gift', code: 'no-gift' };
        });

  const giftCodeCheck = async ({ slug } = {}) =>
    !SLUG.test(String(slug ?? ''))
      ? BAD
      : doing(`gift-manage:code:${slug}`, async (c) => ({
          ok: true,
          info: {
            slug: String(slug),
            ...codeInfoOf(
              await c.client.invoke(
                new c.Api.payments.CheckGiftCode({ slug: String(slug) })
              )
            ),
          },
        }));

  const giftCodeApply = async ({ slug } = {}) =>
    !SLUG.test(String(slug ?? ''))
      ? BAD
      : doing(`gift-manage:apply:${slug}`, async (c) => {
          await c.client.invoke(
            new c.Api.payments.ApplyGiftCode({ slug: String(slug) })
          );
          return { ok: true };
        });

  return { giftUpgradePreview, giftUnique, giftCodeCheck, giftCodeApply };
};

export const createGiftsManage = (env, { userClient, stickers }) => {
  const doing = (key, use) =>
    connected(env, userClient, failure, (c) => runIn(env, key, () => use(c)));
  const sticker = (doc) =>
    doc?.className === 'Document'
      ? (stickers?.remember?.([doc], 'gift:unique', 'sticker')?.[0] ?? null)
      : null;

  // The Telegram input naming one gift (a chat's needs its peer).
  const withRef = (c, ref, use) =>
    ref.msgId !== undefined
      ? use(new c.Api.InputSavedStarGiftUser({ msgId: ref.msgId }))
      : env.connection.withPeer(c.client, ref.chat, (peer) =>
          use(
            new c.Api.InputSavedStarGiftChat({
              peer,
              savedId: c.helpers.returnBigInt(ref.savedId),
            })
          )
        );
  const onRef = (name, request, use) =>
    !validRef(request)
      ? BAD
      : doing(`gift-manage:${name}:${request.chat}`, (c) =>
          withRef(c, refOf(request), (stargift) => use(c, stargift))
        );

  const giftConvert = async (request = {}) =>
    onRef('convert', request, async (c, stargift) => {
      await c.client.invoke(new c.Api.payments.ConvertStarGift({ stargift }));
      return { ok: true };
    });

  // Free: the call itself. Paid: a form, sent only at the price shown.
  const settle = async (c, { free, invoice, stars }) => {
    if (stars === 0) {
      await c.client.invoke(free());
      return { ok: true, paid: 0 };
    }
    const form = await c.client.invoke(
      new c.Api.payments.GetPaymentForm({ invoice })
    );
    if (formPrice(form) !== stars) {
      return { ok: false, error: 'price changed', code: 'price' };
    }
    const result = await c.client.invoke(
      new c.Api.payments.SendStarsForm({ formId: form.formId, invoice })
    );
    return result?.className === 'payments.PaymentVerificationNeeded'
      ? { ok: false, error: 'verification needed', code: 'verify' }
      : { ok: true, paid: stars };
  };

  const stars = (request) =>
    Number.isInteger(request?.stars) && request.stars >= 0;

  const giftUpgrade = async (request = {}) =>
    !stars(request) ||
    (request.keepDetails !== undefined &&
      typeof request.keepDetails !== 'boolean')
      ? BAD
      : onRef('upgrade', request, (c, stargift) => {
          const keep = request.keepDetails ? { keepOriginalDetails: true } : {};
          return settle(c, {
            stars: request.stars,
            free: () =>
              new c.Api.payments.UpgradeStarGift({ ...keep, stargift }),
            invoice: new c.Api.InputInvoiceStarGiftUpgrade({
              ...keep,
              stargift,
            }),
          });
        });

  const giftTransfer = async (request = {}) =>
    !stars(request) || !USER.test(String(request.to ?? ''))
      ? BAD
      : onRef('transfer', request, (c, stargift) =>
          env.connection.withPeer(c.client, String(request.to), (toId) =>
            settle(c, {
              stars: request.stars,
              free: () =>
                new c.Api.payments.TransferStarGift({ stargift, toId }),
              invoice: new c.Api.InputInvoiceStarGiftTransfer({
                stargift,
                toId,
              }),
            })
          )
        );

  const pinLimit = async (c) => {
    try {
      const config = await c.client.invoke(
        new c.Api.help.GetAppConfig({ hash: 0 })
      );
      return pinLimitOf(config);
    } catch {
      return PIN_LIMIT;
    }
  };

  const giftPin = async ({ chat, pins } = {}) =>
    !CHAT.test(String(chat ?? '')) ||
    !Array.isArray(pins) ||
    pins.length > PINS_MAX ||
    !pins.every((one) => validRef({ ...one, chat }))
      ? BAD
      : doing(`gift-manage:pin:${chat}`, async (c) => {
          const limit = await pinLimit(c);
          if (pins.length > limit) {
            return { ok: false, error: 'pin limit', code: 'pin-limit', limit };
          }
          return env.connection.withPeer(
            c.client,
            String(chat),
            async (peer) => {
              const inputs = [];
              for (const one of pins) {
                await withRef(c, refOf({ ...one, chat }), (input) =>
                  inputs.push(input)
                );
              }
              await c.client.invoke(
                new c.Api.payments.ToggleStarGiftsPinnedToTop({
                  peer,
                  stargift: inputs,
                })
              );
              return { ok: true, pinned: pins.length, limit };
            }
          );
        });

  return {
    giftConvert,
    giftUpgrade,
    giftTransfer,
    giftPin,
    ...createLookups({ doing, sticker }),
  };
};

/**
 * Giveaways, as Telegram Desktop shows them (R-Y184; learned, never
 * copied). Read only: nothing here creates, joins or changes a giveaway.
 * - `giveawayInfo({ chat, id, channels?, winners? })` —
 *   payments.getGiveawayInfo of the giveaway message `id` in `chat` →
 *   `{ ok, ended: false, participating, preparing, startDate,
 *   joinedTooEarlyDate?, disallowedChat?, disallowedCountry? }` while it
 *   runs, or `{ ok, ended: true, winner, refunded, startDate, finishDate,
 *   winnersCount, activatedCount?, slug?, starsPrize? }` when it is over.
 *   `channels` and `winners` are ids from the card; their names come back
 *   as `channelNames` and `winnerNames` where we can read them (an id we
 *   cannot read stays out), at most MAX_NAMES each.
 * Telegram's errors become codes the page shows as text.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';

export const MAX_NAMES = 100;

const CODES = {
  MESSAGE_ID_INVALID: 'no-message',
  PEER_ID_INVALID: 'no-chat',
  CHANNEL_INVALID: 'no-chat',
  CHANNEL_PRIVATE: 'no-chat',
  GIVEAWAY_NOT_FOUND: 'no-giveaway',
  FLOOD_WAIT: 'flood',
};
const failure = failureOf(CODES);
const BAD = { ok: false, error: 'bad request', code: 'bad-request' };
const CHAT = /^-?\d{1,20}$/;
const ID = /^\d{1,20}$/;
const text = (value) => String(value?.value ?? value ?? '');
const num = (value) => Number(value?.value ?? value ?? 0) || 0;

/** Whether `list` is absent or an array of at most MAX_NAMES numeric ids. */
export const validIds = (list) =>
  list === undefined ||
  (Array.isArray(list) &&
    list.length <= MAX_NAMES &&
    list.every((id) => ID.test(String(id))));

const endedInfo = (answer) => ({
  ended: true,
  winner: Boolean(answer.winner),
  refunded: Boolean(answer.refunded),
  startDate: num(answer.startDate),
  finishDate: num(answer.finishDate),
  winnersCount: num(answer.winnersCount),
  ...(answer.activatedCount === undefined
    ? {}
    : { activatedCount: num(answer.activatedCount) }),
  ...(answer.giftCodeSlug ? { slug: String(answer.giftCodeSlug) } : {}),
  ...(answer.starsPrize === undefined
    ? {}
    : { starsPrize: num(answer.starsPrize) }),
});

const runningInfo = (answer) => ({
  ended: false,
  participating: Boolean(answer?.participating),
  preparing: Boolean(answer?.preparingResults),
  startDate: num(answer?.startDate),
  ...(answer?.joinedTooEarlyDate
    ? { joinedTooEarlyDate: num(answer.joinedTooEarlyDate) }
    : {}),
  ...(answer?.adminDisallowedChatId
    ? { disallowedChat: `-100${text(answer.adminDisallowedChatId)}` }
    : {}),
  ...(answer?.disallowedCountry
    ? { disallowedCountry: String(answer.disallowedCountry) }
    : {}),
});

/** What Telegram's answer says, in the page's shape. */
export const infoOf = (answer) =>
  /GiveawayInfoResults$/.test(String(answer?.className))
    ? endedInfo(answer)
    : runningInfo(answer);

const nameOf = (entity) =>
  entity?.title ||
  [entity?.firstName, entity?.lastName].filter(Boolean).join(' ') ||
  (entity?.username ? `@${entity.username}` : '');

// The names of ids we already know how to reach; the rest stay out.
const namesOf = async (env, c, ids, channel) => {
  const found = [];
  for (const id of (ids ?? []).slice(0, MAX_NAMES)) {
    try {
      const input = await env.peers.input(channel ? `-100${id}` : String(id));
      if (!input) {
        continue;
      }
      const answer = await c.client.invoke(
        channel
          ? new c.Api.channels.GetChannels({ id: [input] })
          : new c.Api.users.GetUsers({ id: [input] })
      );
      const name = nameOf(channel ? answer?.chats?.[0] : answer?.[0]);
      if (name) {
        found.push({ id: String(id), name });
      }
    } catch {
      // A name we cannot read is left out, never a failure.
    }
  }
  return found;
};

export const createGiveaways = (env, { userClient }) => ({
  giveawayInfo: async ({ chat, id, channels, winners } = {}) =>
    !CHAT.test(String(chat ?? '')) ||
    !Number.isInteger(id) ||
    id <= 0 ||
    !validIds(channels) ||
    !validIds(winners)
      ? BAD
      : connected(env, userClient, failure, async (c) => {
          const answer = await runIn(env, `giveaway:${chat}:${id}`, () =>
            env.connection.withPeer(c.client, String(chat), (peer) =>
              c.client.invoke(
                new c.Api.payments.GetGiveawayInfo({ peer, msgId: id })
              )
            )
          );
          return {
            ok: true,
            ...infoOf(answer),
            channelNames: await namesOf(env, c, channels, true),
            winnerNames: await namesOf(env, c, winners, false),
          };
        }),
});

/**
 * Search across Telegram, as Telegram's apps search from the chat list's
 * box (R-Y107; learned, never copied): people and chats by name or
 * username — the user's own first, then public ones (contacts.search) —
 * and messages in every chat (messages.searchGlobal), newest first, a
 * page at a time. What is found is stored as any read message or chat
 * is: a found chat opens at once, a found message is there to show.
 *
 * `searchPeers({ q })` → `{ ok, peers: [{ chat, name, username, kind,
 * members, mine }] }`;
 * `searchGlobal({ q, cursor? })` → `{ ok, messages, count, more, cursor }`
 * — `messages` the found ones as links, newest first; `cursor` asks for
 * the page after them;
 * `searchTag({ tag, scope, cursor? })` (R-Y182) — a hashtag or cashtag in
 * every chat (`scope: 'all'`, messages.searchGlobal) or in public posts
 * (`scope: 'public'`, channels.searchPosts), answered as searchGlobal.
 */

export const GLOBAL_PAGE = 30;
export const PEERS_LIMIT = 20;
export const MAX_GLOBAL_QUERY = 128;
const CURSORS = 64;

const queryOf = (q) =>
  String(q ?? '')
    .trim()
    .slice(0, MAX_GLOBAL_QUERY);

export const usernameOf = (entity) =>
  entity?.username ??
  entity?.usernames?.find((u) => u?.active)?.username ??
  null;

export const kindOf = (entity) => {
  if (entity?.className === 'User') {
    return entity.bot ? 'bot' : 'user';
  }
  return entity?.className === 'Channel' && !entity.megagroup
    ? 'channel'
    : 'group';
};

export const nameOf = (entity) =>
  [entity?.firstName, entity?.lastName].filter(Boolean).join(' ') ||
  entity?.title ||
  usernameOf(entity) ||
  null;

// The users and chats of an answer, by their (marked) chat id.
export const entitiesOf = (answer, utils) => {
  const entities = new Map();
  for (const entity of [...(answer?.users ?? []), ...(answer?.chats ?? [])]) {
    try {
      entities.set(String(utils.getPeerId(entity)), entity);
    } catch {
      // An entity GramJS cannot address is left out.
    }
  }
  return entities;
};

export const peerIdOf = (utils, peer) => {
  try {
    return String(utils.getPeerId(peer));
  } catch {
    return null;
  }
};

// A link as the search answers it: what a row shows, not all Telegram said.
const slim = (link) => {
  const { raw: _raw, ...shown } = link;
  return shown;
};

// messages.searchGlobal from the start, or after the page `after` ended.
const globalRequest = (Api, query, after) =>
  new Api.messages.SearchGlobal({
    q: query,
    filter: new Api.InputMessagesFilterEmpty(),
    minDate: 0,
    maxDate: 0,
    offsetRate: after?.rate ?? 0,
    offsetPeer: after?.peer ?? new Api.InputPeerEmpty(),
    offsetId: after?.id ?? 0,
    limit: GLOBAL_PAGE,
  });

// channels.searchPosts (R-Y182): a hashtag by itself, a cashtag as a query.
const postsRequest = (Api, tag, after) =>
  new Api.channels.SearchPosts({
    ...(tag.startsWith('#') ? { hashtag: tag.slice(1) } : { query: tag }),
    offsetRate: after?.rate ?? 0,
    offsetPeer: after?.peer ?? new Api.InputPeerEmpty(),
    offsetId: after?.id ?? 0,
    limit: GLOBAL_PAGE,
  });

// Telegram's refusal of a search as the page's code.
const tagFailure = (error) => {
  const name = String(error?.errorMessage ?? error?.message ?? '');
  return {
    ok: false,
    error: name,
    code: /FLOOD|STARS/.test(name) ? 'flood' : 'failed',
  };
};

/** A hashtag (#tag) or cashtag ($TAG) as the search takes it. */
export const TAG = /^[#$][\p{L}\p{N}_]{1,64}$/u;

const realOf = (answer) =>
  (answer?.messages ?? []).filter(
    (m) => m && m.id !== undefined && m.className !== 'MessageEmpty'
  );

// How many Telegram counts in all (a page that is all there is: its own).
const countOf = (answer, list) => Number(answer?.count) || list.length;

// Where the next page starts, after the last message of this one.
const nextOf = (Api, answer, last) => ({
  rate: answer?.nextRate ?? last.date ?? 0,
  peer: last.inputChat ?? new Api.InputPeerEmpty(),
  id: last.id,
});

/**
 * `env` is the account's; `userClient()` the user client or null;
 * `tools` its `toLinks`, `writeChanged` and `dialogOfEntity`.
 */
export const createGlobalSearch = (env, { userClient, tools }) => {
  const cursors = new Map(); // token -> { rate, peer, id }
  let tokens = 0;

  const keepCursor = (state) => {
    const token = `c${(tokens += 1)}`;
    cursors.set(token, state);
    if (cursors.size > CURSORS) {
      cursors.delete(cursors.keys().next().value);
    }
    return token;
  };

  // A found chat is remembered: opening it reads it at once.
  const remember = async (chat, entity) => {
    const dialog = tools.dialogOfEntity(chat, entity);
    await env.peers?.remember(chat, entity, dialog);
    return dialog;
  };

  const searchPeers = async ({ q, priority = 'view' } = {}) => {
    const query = queryOf(q);
    const client = query ? await userClient() : null;
    if (!client) {
      return { ok: false, supported: false };
    }
    const { Api, utils } = await env.importer();
    const answer = await env.queue.run(`peers:${query}`, priority, () =>
      client.invoke(new Api.contacts.Search({ q: query, limit: PEERS_LIMIT }))
    );
    const entities = entitiesOf(answer, utils);
    const found = [
      ...(answer?.myResults ?? []).map((peer) => ({ peer, mine: true })),
      ...(answer?.results ?? []).map((peer) => ({ peer, mine: false })),
    ];
    const peers = [];
    const seen = new Set();
    for (const { peer, mine } of found) {
      const chat = peerIdOf(utils, peer);
      const entity = entities.get(chat);
      if (!entity || seen.has(chat)) {
        continue;
      }
      seen.add(chat);
      await remember(chat, entity);
      peers.push({
        chat,
        name: nameOf(entity),
        username: usernameOf(entity),
        kind: kindOf(entity),
        members: entity.participantsCount ?? null,
        mine,
      });
    }
    return { ok: true, peers };
  };

  // The found messages stored, chat by chat; their links in found order.
  const store = async (client, list, entities, utils) => {
    const byChat = new Map();
    for (const message of list) {
      try {
        message._finishInit?.(client, entities, undefined);
      } catch {
        // GramJS names the sender when it can; the chat list names it later.
      }
      const chat = peerIdOf(utils, message.peerId);
      if (chat) {
        byChat.set(chat, [...(byChat.get(chat) ?? []), message]);
      }
    }
    const links = new Map();
    for (const [chat, messages] of byChat) {
      const entity = entities.get(chat);
      const dialog =
        env.live?.chats?.get(chat) ??
        (entity ? await remember(chat, entity) : { id: chat });
      for (const link of tools.toLinks(dialog, messages)) {
        links.set(link.id, link);
      }
    }
    await tools.writeChanged(env.store, [...links.values()]);
    return list
      .map((m) =>
        links.get(`msg:telegram:${peerIdOf(utils, m.peerId)}:${m.id}`)
      )
      .filter(Boolean)
      .map(slim);
  };

  // One page of what Telegram finds, stored, with the next page's cursor.
  const page = async ({ Api, utils, client, key, request, priority }) => {
    const answer = await env.queue.run(key, priority ?? 'view', () =>
      client.invoke(request)
    );
    const list = realOf(answer);
    const entities = entitiesOf(answer, utils);
    const messages = await store(client, list, entities, utils);
    const more = list.length >= GLOBAL_PAGE;
    return {
      ok: true,
      messages,
      count: countOf(answer, list),
      more,
      cursor: more ? keepCursor(nextOf(Api, answer, list.at(-1))) : null,
    };
  };

  const searchGlobal = async ({ q, cursor = null, priority = 'view' } = {}) => {
    const query = queryOf(q);
    const client = query ? await userClient() : null;
    if (!client) {
      return { ok: false, supported: false };
    }
    const after = cursor ? cursors.get(cursor) : null;
    if (cursor && !after) {
      return { ok: true, messages: [], count: 0, more: false, cursor: null };
    }
    const { Api, utils } = await env.importer();
    return page({
      Api,
      utils,
      client,
      priority,
      key: `global:${query}:${cursor ?? ''}`,
      request: globalRequest(Api, query, after),
    });
  };

  // A hashtag or cashtag everywhere, or in public posts (R-Y182).
  const searchTag = async ({ tag, scope = 'all', cursor = null } = {}) => {
    const client = TAG.test(String(tag)) ? await userClient() : null;
    if (!client) {
      return { ok: false, supported: false };
    }
    const after = cursor ? cursors.get(cursor) : null;
    if (cursor && !after) {
      return { ok: true, messages: [], count: 0, more: false, cursor: null };
    }
    const { Api, utils } = await env.importer();
    const make = scope === 'public' ? postsRequest : globalRequest;
    try {
      return await page({
        Api,
        utils,
        client,
        key: `tag:${scope}:${tag}:${cursor ?? ''}`,
        request: make(Api, tag, after),
      });
    } catch (error) {
      return tagFailure(error);
    }
  };

  return { searchPeers, searchGlobal, searchTag };
};

/**
 * A supergroup's own sticker set and emoji pack, and the account's "New
 * contacts joined Telegram" notification, as Telegram Desktop has them
 * (R-Y211; learned, never copied):
 *
 * - `groupStickerSet({ chat, shortName, emojis? })` — channels.setStickers
 *   with the set named by its short name (InputStickerSetShortName), or
 *   InputStickerSetEmpty with `shortName` null to remove it; `emojis`
 *   sets the group's emoji pack instead (channels.setEmojiStickers). The
 *   preview of a set before saving is the sticker box's
 *   (`stickerSetBox({ shortName })`, messages.getStickerSet);
 * - `contactSignUpGet()` — account.getContactSignUpNotification → `{ ok,
 *   on }` (the call answers whether notifications are silenced);
 * - `contactSignUpSet({ on })` — account.setContactSignUpNotification.
 * `groupStickersInfo(entity, full)` is what the chat info says about both.
 * Telegram's errors become codes the page shows as text.
 */

import { connected, runIn } from './telegram-stickers.js';
import { quietFailureOf } from './telegram-chat-settings.js';

const CODES = {
  CHAT_ADMIN_REQUIRED: 'not-admin',
  CHAT_NOT_MODIFIED: 'not-modified',
  STICKERSET_INVALID: 'unknown-set',
  PARTICIPANTS_TOO_FEW: 'too-few',
  CHANNEL_PRIVATE: 'no-access',
  CHANNEL_INVALID: 'no-access',
  PEER_ID_INVALID: 'no-access',
  BOOSTS_REQUIRED: 'boosts',
  FLOOD_WAIT: 'flood',
};

const failure = quietFailureOf(CODES);
const bad = () => ({ ok: false, error: 'bad-request', code: 'bad-request' });

export const CHANNEL = /^-100\d{1,20}$/;
export const SHORT_NAME = /^[A-Za-z0-9_]{1,64}$/;

const text = (value) => String(value?.value ?? value);

// A StickerSet as the page names it, or null.
const setOf = (set) =>
  set && set.id !== undefined
    ? {
        id: text(set.id),
        shortName: String(set.shortName ?? ''),
        title: String(set.title ?? ''),
        count: Number(set.count ?? 0),
      }
    : null;

/**
 * What a channel's info says about its sticker set and emoji pack: whether
 * the user may set them (the creator, or an admin who may change info, in
 * a supergroup the full channel allows it for) and the sets it has.
 */
export const groupStickersInfo = (entity = {}, full = {}) => {
  const may =
    !entity.broadcast &&
    Boolean(entity.creator || entity.adminRights?.changeInfo);
  return {
    canSetStickers: may && Boolean(full.canSetStickers),
    groupStickers: {
      stickers: setOf(full.stickerset),
      emojis: setOf(full.emojiset),
    },
  };
};

/** Whether `body` names a chat and a set (or none) to set. */
export const validGroupSet = (body = {}) =>
  CHANNEL.test(String(body.chat ?? '')) &&
  (body.shortName === null || SHORT_NAME.test(String(body.shortName))) &&
  (body.emojis === undefined || typeof body.emojis === 'boolean');

const createGroupSet =
  (env, userClient) =>
  async (body = {}) => {
    if (!validGroupSet({ ...body, shortName: body.shortName ?? null })) {
      return bad();
    }
    const chat = String(body.chat);
    const shortName = body.shortName ?? null;
    return connected(env, userClient, failure, async (c) => {
      const stickerset =
        shortName === null
          ? new c.Api.InputStickerSetEmpty()
          : new c.Api.InputStickerSetShortName({ shortName });
      const Request = body.emojis
        ? c.Api.channels.SetEmojiStickers
        : c.Api.channels.SetStickers;
      await runIn(env, `group-stickers:${chat}`, () =>
        env.connection.withPeer(c.client, chat, (peer) =>
          c.client.invoke(new Request({ channel: peer, stickerset }))
        )
      );
      return { ok: true };
    });
  };

export const createGroupExtras = (env, { userClient }) => ({
  groupStickerSet: createGroupSet(env, userClient),
  contactSignUpGet: async () =>
    connected(env, userClient, failure, async (c) => {
      const silent = await runIn(env, 'signup:get', () =>
        c.client.invoke(new c.Api.account.GetContactSignUpNotification())
      );
      return { ok: true, on: silent !== true };
    }),
  contactSignUpSet: async ({ on } = {}) =>
    typeof on !== 'boolean'
      ? bad()
      : connected(env, userClient, failure, async (c) => {
          await runIn(env, 'signup:set', () =>
            c.client.invoke(
              new c.Api.account.SetContactSignUpNotification({ silent: !on })
            )
          );
          return { ok: true, on };
        }),
});

/**
 * What of each Telegram chat is already in the store, so Telegram is
 * asked only for what is missing (R-Y24 .. R-Y28).
 *
 * Every message ever loaded stays in the store (`data.lino` and
 * `data.bin`), with everything Telegram said about it (`raw`). A chat's
 * `history:telegram:<chat>` link records the stretch of it that is
 * stored without holes, from `newest` back to `oldest`, and `complete`
 * once that stretch reaches the chat's first message. Opening a chat
 * again, or scrolling back over what was read before, is then answered
 * from the store; Telegram is asked for older pages, for a chat never
 * opened, and — for channels, whose updates the account-wide catch-up
 * does not carry — for what came after `newest`.
 *
 * Requests to Telegram go one at a time through `createFetchQueue`, the
 * most urgent first: the chat the user is looking at, then the chat
 * list, then chats visible in it, then the slow background download.
 */

import { AsyncLocalStorage } from 'node:async_hooks';
import { actionNamesOf } from './telegram-service-names.js';

const SOURCE = 'telegram';

export const historyLinkId = (chat) => `history:${SOURCE}:${chat}`;

/** The `history:` link for a chat, with the covered stretch. */
export const historyLink = (chat, cover) => ({
  id: historyLinkId(chat),
  tokens: ['history', SOURCE, String(chat)],
  kind: 'history',
  source: SOURCE,
  chat: String(chat),
  newest: cover.newest ?? null,
  oldest: cover.oldest ?? null,
  complete: Boolean(cover.complete),
  at: cover.at ?? null,
});

const numbers = (ids) => ids.map(Number).filter(Number.isFinite);

/**
 * The covered stretch after one slice of a chat was read:
 *
 *   - `mode: 'newest'` — the newest `limit` messages: joins the stretch
 *     when it overlaps it, otherwise starts a new one (what lies between
 *     was never read); fewer than `limit` means the whole chat.
 *   - `mode: 'since'` — messages after `newest` (`minId`): a full page
 *     may leave a hole behind it, so the stretch starts again there.
 *   - `mode: 'older'` — the page before `oldest` (`offsetId`); fewer than
 *     `limit` means the first message was reached.
 *   - `mode: 'newer'` — messages read far back, then toward the newest
 *     (a jump to a date): they join the stretch only once they reach it.
 */
const known = (value) => value !== null && value !== undefined;

// A page older than the stretch: it moves `oldest` back.
const coverOlder = (before, got, full) => ({
  ...before,
  oldest: got.length ? Math.min(...got) : (before.oldest ?? null),
  complete: Boolean(before.complete) || !full,
});

// Nothing came: a `since` read found nothing new, a `newest` one an
// empty chat (or one already whole).
const coverNothing = (before, mode, at) =>
  mode === 'since'
    ? { ...before, at }
    : {
        ...before,
        complete: !known(before.newest) || Boolean(before.complete),
        at,
      };

// A stretch read far back (a jump to a date, R-Y106): it moves `oldest`
// back once it reaches the stored stretch; otherwise nothing changes.
const coverNewer = (record, got) => {
  if (
    !record ||
    !known(record.oldest) ||
    got.length === 0 ||
    Math.max(...got) < Number(record.oldest)
  ) {
    return record;
  }
  return {
    ...record,
    oldest: Math.min(Number(record.oldest), ...got),
    newest: Math.max(Number(record.newest), ...got),
  };
};

export const coverSlice = (record, { ids, limit, mode, at }) => {
  const got = numbers(ids);
  const full = got.length >= limit;
  const before = record ?? {};
  if (mode === 'newer') {
    return coverNewer(record, got);
  }
  if (mode === 'older') {
    return coverOlder(before, got, full);
  }
  if (got.length === 0) {
    return coverNothing(before, mode, at);
  }
  const min = Math.min(...got);
  const max = Math.max(...got);
  const whole = mode === 'newest' && !full;
  const joins =
    known(before.newest) &&
    (mode === 'since' ? !full : min <= Number(before.newest));
  if (!joins) {
    return { newest: max, oldest: min, complete: whole, at };
  }
  return {
    newest: Math.max(Number(before.newest), max),
    oldest: Math.min(Number(before.oldest ?? min), min),
    complete: Boolean(before.complete) || whole,
    at,
  };
};

// Channels and supergroups: their updates are not in the account-wide
// difference, so what came after `newest` is asked for again — at most
// this often per chat.
export const CHANNEL_FRESH_MS = 60_000;
export const isChannelChat = (chat) => String(chat).startsWith('-100');

/**
 * What one request for a chat's history needs from Telegram, given its
 * `history:` record: `null` when the store already has it, otherwise
 * the `getMessages` options and the slice mode.
 */
const olderPlan = (record, before, limit) => {
  if (record?.complete && Number(record.oldest ?? 0) <= Number(before)) {
    return null;
  }
  const from = known(record?.oldest)
    ? Math.min(Number(record.oldest), Number(before))
    : Number(before);
  return { mode: 'older', options: { limit, offsetId: from } };
};

export const historyPlan = (record, { before = null, limit, now }) => {
  if (known(before)) {
    return olderPlan(record, before, limit);
  }
  if (!known(record?.newest)) {
    return record?.complete ? null : { mode: 'newest', options: { limit } };
  }
  const fresh = now - (Date.parse(record.at ?? '') || 0) < CHANNEL_FRESH_MS;
  if (!isChannelChat(record.chat) || fresh) {
    return null;
  }
  return { mode: 'since', options: { limit, minId: Number(record.newest) } };
};

// ---- the request queue ----------------------------------------------

export const PRIORITIES = ['view', 'list', 'prefetch', 'background'];
const rank = (priority) => {
  const at = PRIORITIES.indexOf(priority);
  return at < 0 ? PRIORITIES.indexOf('prefetch') : at;
};

/**
 * How fast each priority may ask Telegram (R-Y34): the least time since
 * the last request of any priority, and how many requests of the last
 * minute it still lets through — so background work runs only while the
 * minute is quiet and never in a burst. Far below what Telegram allows
 * an account; its own apps ask about as often while the user scrolls.
 */
export const PACE = Object.freeze({
  view: { gapMs: 250, perMinute: 60 },
  list: { gapMs: 500, perMinute: 45 },
  prefetch: { gapMs: 1500, perMinute: 30 },
  background: { gapMs: 3000, perMinute: 20 },
});
/** No pacing (tests). */
export const NO_PACE = Object.freeze(
  Object.fromEntries(
    PRIORITIES.map((p) => [p, { gapMs: 0, perMinute: Infinity }])
  )
);
const MINUTE_MS = 60_000;
// After Telegram asked to wait, everything goes this much slower for
// SLOW_FOR_MS (background and prefetch; the user's own requests half).
export const SLOW_FOR_MS = 60 * MINUTE_MS;
const SLOW_FACTOR = 4;
// A wait this short is waited out by what the user looks at.
const VIEW_WAITS_MS = 3000;
// Telegram's wait is for the method that was asked too often; the
// others pause this long too, so a burst cools down.
const ALL_WAIT_MS = 30_000;
// A request with no answer by then is given up, so the queue moves on:
// GramJS can lose its connection without a word and then never answer.
// A file may take its time.
export const STUCK_MS = Object.freeze({ file: 10 * MINUTE_MS, other: 60_000 });

/** The method a queue key names: `messages:42:…` → `messages`. */
export const methodOf = (key) => String(key ?? '').split(':')[0];

export const floodSeconds = (error) => {
  const text = `${error?.errorMessage ?? ''} ${error?.message ?? ''}`;
  const match =
    /FLOOD_(?:PREMIUM_)?WAIT_(\d+)/.exec(text) ??
    /A wait of (\d+) seconds is required/.exec(text);
  return match ? Number(match[1]) : Number(error?.seconds) || 0;
};

// GramJS while its connection is down ("Cannot send requests while
// disconnected"): it reconnects by itself within seconds, so a request
// waits for it — 1 s, 2 s, 4 s, 8 s — instead of failing (R-Y75), as
// Telegram's apps queue requests until they are connected again.
const DISCONNECTED_RETRIES = 4;
export const isDisconnected = (error) =>
  /while disconnected|not connected|connection (?:was )?closed/i.test(
    String(error?.message ?? error ?? '')
  );

const floodError = (retryAfter) =>
  Object.assign(new Error('Telegram asked to wait'), {
    code: 'flood-wait',
    retryAfter,
  });

/**
 * One Telegram request at a time, the most urgent first, at the pace of
 * `PACE`. The same `key` asked again while waiting is merged (and takes
 * the higher priority); its first part names the method (`methodOf`).
 * After Telegram's "wait N seconds" — from a request of the queue or
 * from anywhere else (`note`) — that method is not asked for that long,
 * nothing at all for up to ALL_WAIT_MS (what waits is turned down with
 * `code: 'flood-wait'` and `retryAfter`), and then everything goes
 * slower for an hour. `onHold(holds)` saves the holds, `hold(holds)`
 * restores them after a restart. A request with no answer within
 * `stuck` is turned down (`code: 'telegram-stuck'`) and `onStuck(job)`
 * told, so the connection can be opened anew. A request asked by one in
 * flight (the peer a refresh needs looked up) is part of it and runs at
 * once: queued, it would wait for the request waiting for it.
 */
// The queue's clock: when each request of the last minute began, and
// Telegram's waits (`holdUntil`: nothing; `methods`: one method).
const createPacing = ({ pace, now }) => {
  const started = [];
  let holdUntil = 0;
  let slowUntil = 0;
  const methods = new Map();

  const paceOf = (priority) => {
    const base = pace[priority] ?? pace.prefetch;
    if (now() >= slowUntil) {
      return base;
    }
    const factor = rank(priority) >= rank('prefetch') ? SLOW_FACTOR : 2;
    return { gapMs: base.gapMs * factor, perMinute: base.perMinute / factor };
  };

  // When `job` may go: after its gap, within its share of the minute.
  const readyAt = (job) => {
    while (started.length > 0 && started[0] <= now() - MINUTE_MS) {
      started.shift();
    }
    const { gapMs, perMinute } = paceOf(job.priority);
    const last = started.at(-1) ?? -Infinity;
    const over = started.length - Math.floor(perMinute) + 1;
    const budget = over > 0 ? started[over - 1] + MINUTE_MS : -Infinity;
    return Math.max(
      last + gapMs,
      budget,
      heldUntil(job.method),
      job.notBefore ?? 0
    );
  };

  function heldUntil(method) {
    return Math.max(holdUntil, methods.get(method) ?? 0);
  }

  const holds = () => ({
    holdUntil,
    slowUntil,
    methods: Object.fromEntries(
      [...methods].filter(([, until]) => until > now())
    ),
  });

  /** Restore (or add) holds: `{ holdUntil, slowUntil, methods }`. */
  const hold = (saved = {}) => {
    holdUntil = Math.max(holdUntil, Number(saved.holdUntil) || 0);
    slowUntil = Math.max(slowUntil, Number(saved.slowUntil) || 0);
    for (const [method, until] of Object.entries(saved.methods ?? {})) {
      methods.set(method, Math.max(methods.get(method) ?? 0, Number(until)));
    }
  };

  const state = () => ({
    heldFor: Math.max(0, holdUntil - now()),
    methods: Object.fromEntries(
      [...methods]
        .filter(([, until]) => until > now())
        .map(([method, until]) => [method, Math.ceil((until - now()) / 1000)])
    ),
    slowFor: Math.max(0, slowUntil - now()),
    lastMinute: started.filter((at) => at > now() - MINUTE_MS).length,
  });

  return {
    readyAt,
    heldUntil,
    hold,
    holds,
    state,
    began: () => started.push(now()),
  };
};

// The job's answer, or its turn-down once it is stuck (`STUCK_MS`).
const answerWithin = (job, { stuck, log, onStuck, setTimer, clearTimer }) => {
  let given = null;
  let over = false;
  const ms = stuck[job.method] ?? stuck.other;
  const gaveUp = new Promise((resolve, reject) => {
    given = setTimer(() => {
      if (over) {
        return; // answered meanwhile: nothing to turn down
      }
      log({
        level: 'warn',
        event: 'telegram_request_stuck',
        method: job.method,
        priority: job.priority,
        seconds: Math.round(ms / 1000),
      });
      onStuck(job);
      reject(
        Object.assign(new Error('Telegram did not answer'), {
          code: 'telegram-stuck',
        })
      );
    }, ms);
    given?.unref?.();
  });
  gaveUp.catch(() => {}); // only the race below reports it
  return Promise.race([job.task(), gaveUp]).finally(() => {
    over = true;
    clearTimer(given);
  });
};

// A request in the queue: what it asks and the promise it answers.
const newJob = (key, priority, task, seq) => {
  const job = { key, method: methodOf(key), priority, task, seq };
  job.promise = new Promise((resolve, reject) => {
    job.resolve = resolve;
    job.reject = reject;
  });
  return job;
};

const promoteJobs = (waiting, matches, priority, pump) => {
  for (const job of waiting) {
    if (matches(job.key) && rank(priority) < rank(job.priority)) {
      job.priority = priority;
    }
  }
  pump();
};

export const createFetchQueue = ({
  now = () => Date.now(),
  log = () => {},
  pace = PACE,
  onHold = () => {},
  stuck = STUCK_MS,
  onStuck = () => {},
  setTimer = (fn, ms) => globalThis.setTimeout(fn, ms),
  clearTimer = (timer) => globalThis.clearTimeout(timer),
} = {}) => {
  const waiting = [];
  const byKey = new Map();
  const inJob = new AsyncLocalStorage();
  const pacing = createPacing({ pace, now });
  const { readyAt, heldUntil, hold, holds } = pacing;
  let busy = false;
  let timer = null;

  const take = () => {
    waiting.sort(
      (a, b) => rank(a.priority) - rank(b.priority) || a.seq - b.seq
    );
    return waiting[0];
  };

  const drop = (job) => {
    waiting.splice(waiting.indexOf(job), 1);
    byKey.delete(job.key);
  };

  /** Telegram's answer to any request: a "wait" holds the queue. */
  const note = (error, { method = null, priority = null } = {}) => {
    const seconds = floodSeconds(error);
    if (seconds > 0) {
      const until = now() + seconds * 1000;
      hold({
        holdUntil: Math.min(until, now() + ALL_WAIT_MS),
        slowUntil: until + SLOW_FOR_MS,
        methods: method ? { [method]: until } : {},
      });
      onHold(holds());
      // The client's own watch and the queue see the same error once.
      if (!error.floodNoted) {
        log({
          level: 'warn',
          event: 'telegram_flood_wait',
          seconds,
          method,
          priority,
        });
      }
      Object.assign(error, { floodNoted: true });
      pump();
    }
    return seconds;
  };

  const runJob = async (job) => {
    pacing.began();
    try {
      job.resolve(
        await inJob.run(job, () =>
          answerWithin(job, { stuck, log, onStuck, setTimer, clearTimer })
        )
      );
      job.done = true;
    } catch (error) {
      job.done = true;
      note(error, job);
      const tries = job.reconnectTries ?? 0;
      if (isDisconnected(error) && tries < DISCONNECTED_RETRIES) {
        // Back in line once the connection had time to come back.
        job.reconnectTries = tries + 1;
        job.done = false;
        job.notBefore = now() + 1000 * 2 ** tries;
        byKey.set(job.key, job);
        waiting.push(job);
        return;
      }
      job.reject(error);
    }
  };

  // Turn down what waits while Telegram asked to wait (a short wait is
  // waited out by the user's own requests).
  const turnDownHeld = () => {
    for (const job of [...waiting]) {
      const left = heldUntil(job.method) - now();
      if (left > 0 && (job.priority !== 'view' || left > VIEW_WAITS_MS)) {
        drop(job);
        job.reject(floodError(Math.ceil(left / 1000)));
      }
    }
  };

  const wake = (ms) => {
    clearTimer(timer);
    timer = setTimer(() => {
      timer = null;
      pump();
    }, ms);
    timer?.unref?.();
  };

  async function pump() {
    if (busy) {
      return;
    }
    busy = true;
    try {
      for (;;) {
        turnDownHeld();
        const job = take();
        if (!job) {
          return;
        }
        const wait = readyAt(job) - now();
        if (wait > 0) {
          wake(wait);
          return;
        }
        drop(job);
        await runJob(job);
      }
    } finally {
      busy = false;
    }
  }

  let seq = 0;
  const run = (key, priority, task) => {
    // Asked by a request in flight (a peer looked up for it): it is part
    // of that request, and the queue it would wait in waits for it.
    const asking = inJob.getStore();
    if (asking && !asking.done) {
      return Promise.resolve().then(task);
    }
    const queued = byKey.get(key);
    if (queued) {
      if (rank(priority) < rank(queued.priority)) {
        queued.priority = priority;
        pump();
      }
      return queued.promise;
    }
    const job = newJob(key, priority, task, (seq += 1));
    byKey.set(key, job);
    waiting.push(job);
    pump();
    return job.promise;
  };

  return {
    run,
    note,
    hold,
    /** Promote queued work when a prefetched chat is opened. */
    promote: (matches, priority = 'view') =>
      promoteJobs(waiting, matches, priority, pump),
    /** How many requests wait at `priority` or more urgent. */
    pending: (priority = 'background') =>
      waiting.filter((job) => rank(job.priority) <= rank(priority)).length,
    /** How long nothing (or nothing of `method`) is asked, in ms. */
    heldFor: (method = null) => Math.max(0, heldUntil(method) - now()),
    holds,
    /** For the status: the waits, the slow hour, the last minute's count. */
    state: () => ({ ...pacing.state(), waiting: waiting.length }),
  };
};

// ---- everything Telegram said about a message -------------------------

const SKIPPED_KEYS = new Set([
  'originalArgs',
  'CONSTRUCTOR_ID',
  'SUBCLASS_OF_ID',
  'classType',
  'flags',
  'flags2',
]);
const MAX_DEPTH = 8;

const isBigInteger = (value) =>
  typeof value?.toJSNumber === 'function' &&
  typeof value?.toString === 'function';

const isBytes = (value) =>
  value instanceof Uint8Array || globalThis.Buffer?.isBuffer?.(value);

const plainOf = (value, depth, seen) => {
  if (value === null || value === undefined) {
    return null;
  }
  if (typeof value === 'bigint') {
    return value.toString();
  }
  if (['string', 'number', 'boolean'].includes(typeof value)) {
    return Number.isNaN(value) ? null : value;
  }
  if (typeof value !== 'object' || depth > MAX_DEPTH || seen.has(value)) {
    return null;
  }
  if (isBigInteger(value)) {
    return value.toString();
  }
  if (value instanceof Date) {
    return value.toISOString();
  }
  if (isBytes(value)) {
    return { bytes: globalThis.Buffer.from(value).toString('base64') };
  }
  seen.add(value);
  const out = Array.isArray(value)
    ? value.map((item) => plainOf(item, depth + 1, seen))
    : objectOf(value, depth, seen);
  seen.delete(value);
  return out;
};

// A rich message (layer 232, R-Y220) is a tree of page blocks (lists in
// lists, text in text), deeper than the other fields: it gets its own
// depth. The pictures' inline previews (stripped or cached sizes, document
// thumbnails, waveforms) are bytes the page never reads; they are left
// out so a long answer does not weigh the store down.
const RICH_DEPTH = -24;
const slimFile = (file) => {
  for (const list of [file?.sizes, file?.thumbs, file?.videoThumbs]) {
    for (const size of Array.isArray(list) ? list : []) {
      delete size?.bytes;
    }
  }
  for (const one of Array.isArray(file?.attributes) ? file.attributes : []) {
    delete one?.waveform;
  }
  return file;
};

const slimRich = (rich) => {
  for (const file of [...(rich.photos ?? []), ...(rich.documents ?? [])]) {
    slimFile(file);
  }
  return rich;
};

function objectOf(value, depth, seen) {
  const out = {};
  for (const [key, item] of Object.entries(value)) {
    if (
      key.startsWith('_') ||
      SKIPPED_KEYS.has(key) ||
      typeof item === 'function'
    ) {
      continue;
    }
    const rich = key === 'richMessage';
    let plain = plainOf(item, rich ? RICH_DEPTH : depth + 1, seen);
    if (rich && plain) {
      plain = slimRich(plain);
    }
    if (plain !== null) {
      out[key] = plain;
    }
  }
  return out;
}

/**
 * A GramJS message (a TL object) as plain JSON — every field Telegram
 * sent (entities, media, forward and reply headers, views, reactions,
 * edit date, …), so the store can be analysed and learned from offline.
 * Client-side caches (`_sender`, `_chat`, …), TL bookkeeping and
 * duplicated `originalArgs` are left out; numbers too big for JS become
 * strings and bytes `{ bytes: <base64> }`.
 */
export const rawMessage = (message) => {
  if (!message || typeof message !== 'object') {
    return null;
  }
  const raw = plainOf(message, 0, new WeakSet());
  delete raw?.sender; // the sender's entity: a person link has it
  // The names a service message's action holds ids of (R-Y221).
  const names = actionNamesOf(message);
  return names && raw ? { ...raw, actionNames: names } : raw;
};

/**
 * Inline bots in the message box, as Telegram Desktop's (R-Y138;
 * learned, never copied): `@gif cats` asks the bot @gif for answers.
 *
 * - `inlineBot({ username })` — the bot behind a name
 *   (contacts.resolveUsername); only a bot with an inline placeholder
 *   counts → `{ ok, bot: { id, username, name, placeholder } }`, else
 *   code `not-inline` (a user, or a bot without inline mode) or `no-bot`;
 * - `inlineResults({ chat, username, query, offset })` — the bot's
 *   answers for the words, in this chat (messages.getInlineBotResults),
 *   a page at a time → `{ ok, bot, queryId, gallery, results: [{ id,
 *   type, title, description, doc }], next, switchPm, switchWebview }`.
 *   A result with a file (GIF, sticker, video) has `doc`, a panel item
 *   whose picture the sticker route serves; a photo or a result that
 *   only names a web address has none — the page never loads another
 *   site's address, and this server fetches none either;
 * - `inlineSend({ chat, queryId, id, replyTo, clientId, sendAs })` — one
 *   answer sent (messages.sendInlineBotResult, as the chat's picked "send
 *   as" identity when `sendAs` names one, R-Y147); only an answer this
 *   module gave in that chat; Telegram's reply goes through the live
 *   handler;
 * - `inlineStartBot({ username, startParam })` — the "switch to PM" button
 *   above the results (messages.startBot: bot, peer = the bot, randomId,
 *   startParam; R-Y147); only a start parameter that bot's answer offered.
 *
 * Bots are kept ten minutes, answers as long as the bot says
 * (`cacheTime`, at most five minutes). Telegram's errors become codes.
 */

import { connect, failureOf, runIn } from './telegram-stickers.js';
import { randomIdOf, replyHeader } from './telegram-send.js';
import { withSendAs } from './telegram-send-as-client.js';

const BOT_MS = 10 * 60_000;
const MAX_CACHE_S = 300;
const KEEP = 40;
const SENDABLE_MS = 60 * 60_000;

export const NAME = /^[A-Za-z][A-Za-z0-9_]{2,31}$/;
export const MAX_QUERY = 256;
export const MAX_OFFSET = 256;
export const MAX_RESULT_ID = 128;

const CODES = {
  BOT_INLINE_DISABLED: 'bot-inline-disabled',
  BOT_RESPONSE_TIMEOUT: 'bot-timeout',
  BOT_INVALID: 'no-bot',
  USERNAME_NOT_OCCUPIED: 'no-bot',
  USERNAME_INVALID: 'no-bot',
  CHAT_SEND_INLINE_FORBIDDEN: 'inline-forbidden',
  CHAT_SEND_GIFS_FORBIDDEN: 'inline-forbidden',
  CHAT_SEND_STICKERS_FORBIDDEN: 'inline-forbidden',
  CHAT_SEND_MEDIA_FORBIDDEN: 'inline-forbidden',
  CHAT_WRITE_FORBIDDEN: 'write-forbidden',
  USER_BANNED_IN_CHANNEL: 'write-forbidden',
  QUERY_ID_INVALID: 'expired',
  RESULT_ID_INVALID: 'expired',
  RESULT_ID_DUPLICATE: 'expired',
  FLOOD_WAIT: 'flood-wait',
  SLOWMODE_WAIT: 'flood-wait',
  CHANNEL_PRIVATE: 'no-access',
  PEER_ID_INVALID: 'no-access',
  CHAT_ID_INVALID: 'no-access',
  SEND_AS_PEER_INVALID: 'send-as-invalid',
  PREMIUM_ACCOUNT_REQUIRED: 'send-as-invalid',
  BOT_START_PARAM_INVALID: 'expired',
  BOT_PRIVACY_EXPIRED: 'expired',
};

const CHAT = /^-?\d{1,20}$/;
const QUERY_ID = /^-?\d{1,20}$/;

const text = (value) =>
  value === null || value === undefined ? '' : String(value.value ?? value);

/** The bot a name stands for (its user), or null for anything else. */
export const resolveBotUser = async (c, username) => {
  const answer = await c.client.invoke(
    new c.Api.contacts.ResolveUsername({ username })
  );
  return (answer?.users ?? []).find((u) => u?.bot) ?? null;
};

/** A user as the input a request names a bot by. */
export const inputBot = (c, user) =>
  new c.Api.InputUser({ userId: user.id, accessHash: user.accessHash });

const nameOf = (user) =>
  [user.firstName, user.lastName].filter(Boolean).join(' ') ||
  String(user.username ?? '');

const botInfo = (user, username) => ({
  id: text(user.id),
  username: String(user.username ?? username),
  name: nameOf(user),
  placeholder: String(user.botInlinePlaceholder),
});

const switchOf = (answer) => ({
  switchPm: answer.switchPm
    ? {
        text: String(answer.switchPm.text ?? ''),
        startParam: String(answer.switchPm.startParam ?? ''),
      }
    : null,
  switchWebview: answer.switchWebview
    ? {
        text: String(answer.switchWebview.text ?? ''),
        url: String(answer.switchWebview.url ?? ''),
      }
    : null,
});

const shapeResult = (result, lists, from, queryId) => {
  const media = result?.className === 'BotInlineMediaResult';
  const doc = media && result.document?.className === 'Document';
  return {
    id: String(result.id ?? ''),
    // Each page has its own query: a result is sent with the page's.
    queryId,
    type: String(result.type ?? ''),
    title: String(result.title ?? ''),
    description: String(result.description ?? ''),
    doc: doc
      ? (lists.remember(
          [result.document],
          from,
          result.type === 'gif' ? 'gif' : 'sticker'
        )[0] ?? null)
      : null,
  };
};

// A small map with the oldest dropped first.
const createKeeper = () => {
  const map = new Map();
  return {
    get: (key) => map.get(key),
    set: (key, value) => {
      map.delete(key);
      map.set(key, value);
      while (map.size > KEEP) {
        map.delete(map.keys().next().value);
      }
      return value;
    },
  };
};

// The bot's answer as the page gets it; what it may send is kept.
const shapeAnswer = ({
  answer,
  user,
  name,
  request,
  lists,
  now,
  sendable,
  offered,
}) => {
  const from = `inline:${JSON.stringify(request)}`;
  const queryId = text(answer.queryId);
  const results = (answer.results ?? [])
    .filter((r) => r?.id !== undefined)
    .map((r) => shapeResult(r, lists, from, queryId));
  if (answer.switchPm) {
    offered.set(
      `${name.toLowerCase()}:${String(answer.switchPm.startParam ?? '')}`,
      true
    );
  }
  sendable.set(queryId, {
    at: now(),
    chat: request[0],
    ids: new Set(results.map((r) => r.id)),
  });
  return {
    ok: true,
    bot: botInfo(user, name),
    queryId,
    gallery: Boolean(answer.gallery),
    results,
    next: answer.nextOffset ? String(answer.nextOffset) : null,
    ...switchOf(answer),
  };
};

// A mini app's prepared message may go to any chat the user picks
// (R-Y194): offered by its query and result id.
const createOffer =
  (sendable, now) =>
  ({ queryId, id }) =>
    sendable.set(String(queryId), {
      at: now(),
      chat: null,
      ids: new Set([String(id)]),
    });

// "Switch to PM" (R-Y147): messages.startBot with a parameter the bot's
// own answer offered, in the bot's private chat.
const createStartBot =
  ({ guarded, botOf, offered, run, apply }) =>
  async ({ username, startParam } = {}) => {
    const name = String(username ?? '');
    const param = String(startParam ?? '');
    if (!NAME.test(name) || !offered.get(`${name.toLowerCase()}:${param}`)) {
      return { ok: false, error: 'unknown start', code: 'expired' };
    }
    return guarded(async (c) => {
      const user = await botOf(c, name);
      if (!user) {
        return { ok: false, error: 'not an inline bot', code: 'not-inline' };
      }
      const result = await run(`inline:start:${user.id}`, () =>
        c.client.invoke(
          new c.Api.messages.StartBot({
            bot: inputBot(c, user),
            peer: new c.Api.InputPeerUser({
              userId: user.id,
              accessHash: user.accessHash,
            }),
            randomId: randomIdOf(null, 0, c.helpers),
            startParam: param,
          })
        )
      );
      if (result && typeof result === 'object') {
        await apply(c.client, result);
      }
      return { ok: true, chat: text(user.id) };
    });
  };

export const createInlineBots = (env, { userClient, apply, lists, now }) => {
  const failure = failureOf(CODES);
  const bots = createKeeper(); // lowercase name -> { at, user | null }
  const answers = createKeeper(); // request -> { at, ttl, answer }
  const sendable = createKeeper(); // queryId -> { at, chat, ids }
  const offered = createKeeper(); // bot:param -> true (a "switch to PM")
  const run = (key, use) => runIn(env, key, use);

  const guarded = async (use) => {
    const c = await connect(env, userClient);
    if (!c) {
      return { ok: false, supported: false };
    }
    try {
      return await use(c);
    } catch (error) {
      return failure(error);
    }
  };

  const botOf = async (c, username) => {
    const key = username.toLowerCase();
    const hit = bots.get(key);
    if (hit && now() - hit.at < BOT_MS) {
      return hit.user;
    }
    const found = await run(`inline:bot:${key}`, () =>
      resolveBotUser(c, username)
    );
    const user = typeof found?.botInlinePlaceholder === 'string' ? found : null;
    bots.set(key, { at: now(), user });
    return user;
  };

  const inlineBot = ({ username } = {}) => {
    const name = String(username ?? '');
    if (!NAME.test(name)) {
      return { ok: false, error: 'bad name', code: 'no-bot' };
    }
    return guarded(async (c) => {
      const user = await botOf(c, name);
      return user
        ? { ok: true, bot: botInfo(user, name) }
        : { ok: false, error: 'not an inline bot', code: 'not-inline' };
    });
  };

  const ask = async (c, user, { chat, query, offset }) =>
    run(`inline:query:${user.id}:${chat}`, () =>
      env.connection.withPeer(c.client, chat, (peer) =>
        c.client.invoke(
          new c.Api.messages.GetInlineBotResults({
            bot: inputBot(c, user),
            peer,
            query,
            offset,
          })
        )
      )
    );

  const shape = (answer, user, name, request) =>
    shapeAnswer({ answer, user, name, request, lists, now, sendable, offered });

  const inlineResults = async (body = {}) => {
    const chat = String(body.chat ?? '');
    const name = String(body.username ?? '');
    const query = String(body.query ?? '');
    const offset = String(body.offset ?? '');
    if (
      !CHAT.test(chat) ||
      !NAME.test(name) ||
      query.length > MAX_QUERY ||
      offset.length > MAX_OFFSET
    ) {
      return { ok: false, error: 'bad request', code: 'bad-request' };
    }
    const request = [chat, name.toLowerCase(), query, offset];
    const key = JSON.stringify(request);
    const hit = answers.get(key);
    if (!body.fresh && hit && now() - hit.at < hit.ttl * 1000) {
      return hit.answer;
    }
    return guarded(async (c) => {
      const user = await botOf(c, name);
      if (!user) {
        return { ok: false, error: 'not an inline bot', code: 'not-inline' };
      }
      const got = await ask(c, user, { chat, query, offset });
      const answer = shape(got, user, name, request);
      const ttl = Math.min(
        Math.max(Number(got.cacheTime) || 0, 0),
        MAX_CACHE_S
      );
      answers.set(key, { at: now(), ttl, answer });
      return answer;
    });
  };

  // A document's picture asks its list again: the query asked afresh.
  lists.onAgain('inline:', (rest) => {
    const [chat, username, query, offset] = JSON.parse(rest);
    return inlineResults({ chat, username, query, offset, fresh: true });
  });

  const inlineSend = async (draft = {}) => {
    const chat = String(draft.chat ?? '');
    const queryId = String(draft.queryId ?? '');
    const id = String(draft.id ?? '');
    const kept = QUERY_ID.test(queryId) ? sendable.get(queryId) : null;
    if (
      !kept ||
      (kept.chat !== null && kept.chat !== chat) ||
      !kept.ids.has(id) ||
      now() - kept.at > SENDABLE_MS
    ) {
      return { ok: false, error: 'unknown answer', code: 'expired' };
    }
    return guarded(async (c) => {
      const client = await withSendAs(
        env,
        c.client,
        draft.sendAs,
        draft.allowPaidStars
      );
      const result = await env.connection.withPeer(client, chat, (peer) =>
        client.invoke(
          new c.Api.messages.SendInlineBotResult({
            peer,
            randomId: randomIdOf(draft.clientId, 0, c.helpers),
            queryId: c.helpers.returnBigInt(queryId),
            id,
            clearDraft: false,
            ...(draft.silent ? { silent: true } : {}),
            ...replyHeader(c.Api, draft.replyTo, null),
          })
        )
      );
      if (result && typeof result === 'object') {
        await apply(c.client, result);
      }
      return { ok: true, chat };
    });
  };

  const inlineStartBot = createStartBot({
    guarded,
    botOf,
    offered,
    run,
    apply,
  });

  return {
    inlineBot,
    inlineResults,
    inlineSend,
    inlineStartBot,
    inlineOffer: createOffer(sendable, now),
  };
};

/**
 * Instant View pages as a safe JSON tree (R-Y205; learned, never copied):
 * Telegram's `Page` (blocks of `PageBlock`, text as `RichText`) becomes
 * plain objects the page draws with React elements only. Ids are strings,
 * every link is http, https or tg (or an anchor of the same page), and
 * what is unknown or too deep is dropped.
 *
 * - `safeHref(url)` — the url if it may be linked, else null;
 * - `shapeText(rich, ctx)` — a RichText as inline nodes: `{ t: 'text', s }`,
 *   `{ t: 'b'|'i'|'u'|'s'|'code'|'sub'|'sup'|'mark', c }`, `{ t: 'a', href,
 *   c }`, `{ t: 'a', anchor, c }` (same page), `{ t: 'anchor', name, c }`,
 *   `{ t: 'img', id, w, h }`, and (R-Y225; learned, never copied) the
 *   rich-text kinds of Telegram's entities: `{ t: 'tag', s, c }` (hashtag,
 *   cashtag, bot command), `{ t: 'bankcard', s, c }`, `{ t: 'user', id,
 *   c }`, `{ t: 'date', date, ...flags, s, c }`, `{ t: 'emoji', id, s }`,
 *   `{ t: 'button', c, type, style }` and `{ t: 'math', s }`;
 * - `shapePage(page)` — `{ url, rtl, blocks, photos, documents }`, the
 *   last two the ids the page may ask the media route for.
 */

const MAX_DEPTH = 12;
const MAX_BLOCKS = 4000;
const SAFE = new Set(['http:', 'https:', 'tg:']);
const EMAIL = /^[^\s<>@]{1,64}@[^\s<>@]{1,255}$/;
const PHONE = /^\+?[\d\s().-]{3,30}$/;
const NAME = /^\S{1,128}$/;

const plain = (value) =>
  value === null || value === undefined ? '' : String(value.value ?? value);

/** The url if it may be linked (http, https, tg), else null. */
export const safeHref = (url) => {
  const text = plain(url).trim();
  if (text.length === 0 || text.length > 4096) {
    return null;
  }
  try {
    const parsed = new URL(text);
    if (!SAFE.has(parsed.protocol) || parsed.username || parsed.password) {
      return null;
    }
    return parsed.href;
  } catch {
    return null;
  }
};

// Layer 232 (R-Y220): rich messages use the same blocks and add some;
// they are shaped here too (see `shapeRich`).
const INLINE = {
  TextSpoiler: 'spoiler',
  TextTonAddress: 'code',
  TextBold: 'b',
  TextItalic: 'i',
  TextUnderline: 'u',
  TextStrike: 's',
  TextFixed: 'code',
  TextSubscript: 'sub',
  TextSuperscript: 'sup',
  TextMarked: 'mark',
};

const decodeSafely = (value) => {
  try {
    return decodeURIComponent(value);
  } catch {
    return value;
  }
};

const newContext = (url = '', page = null) => ({
  url,
  photos: new Set(),
  documents: new Set(),
  files: new Map((page?.documents ?? []).map((d) => [plain(d.id), d])),
  count: 0,
});

// A link inside the page: `#name` or the page's own url with `#name`.
const anchorOf = (url, ctx) => {
  const text = plain(url);
  const hash = text.indexOf('#');
  if (hash < 0) {
    return null;
  }
  const base = text.slice(0, hash);
  const name = decodeSafely(text.slice(hash + 1));
  const own = plain(ctx.url).split('#')[0];
  return (base === '' || (own && base === own)) && NAME.test(name)
    ? name
    : null;
};

const wrap = (node, children) =>
  children.length > 0 ? [{ ...node, c: children }] : [];

// The words of shaped inline nodes (a mention's name, a link's text).
const wordsIn = (nodes) =>
  nodes
    .map((node) =>
      typeof node.s === 'string' ? node.s : wordsIn(node.c ?? [])
    )
    .join('');

const MENTION = /^@?([A-Za-z0-9_]{3,64})$/;

// Links the words themselves are (R-Y225): the entity kinds of a normal
// message, which have no address of their own. Null when the words are
// not one (the kind then stays plain words).
const AUTO = {
  TextMention: (words) => {
    const name = MENTION.exec(words)?.[1];
    return name ? `https://t.me/${name}` : null;
  },
  TextAutoUrl: (words) =>
    safeHref(/^[a-z][a-z0-9+.-]*:/i.test(words) ? words : `https://${words}`),
  TextAutoEmail: (words) => (EMAIL.test(words) ? `mailto:${words}` : null),
  TextAutoPhone: (words) =>
    PHONE.test(words) ? `tel:${words.replace(/[^\d+]/g, '')}` : null,
};

const linkOf = (rich, children, ctx) => {
  const name = rich.className;
  if (AUTO[name]) {
    const href = AUTO[name](wordsIn(children).trim());
    return href ? wrap({ t: 'a', href }, children) : children;
  }
  if (name === 'TextEmail') {
    const email = plain(rich.email).trim();
    return EMAIL.test(email)
      ? wrap({ t: 'a', href: `mailto:${email}` }, children)
      : children;
  }
  if (name === 'TextPhone') {
    const phone = plain(rich.phone).trim();
    return PHONE.test(phone)
      ? wrap({ t: 'a', href: `tel:${phone.replace(/[^\d+]/g, '')}` }, children)
      : children;
  }
  const anchor = anchorOf(rich.url, ctx);
  if (anchor) {
    return wrap({ t: 'a', anchor }, children);
  }
  const href = safeHref(rich.url);
  // An unsafe link keeps its words but is no link.
  return href ? wrap({ t: 'a', href }, children) : children;
};

const imageOf = (rich, ctx) => {
  const id = plain(rich.documentId);
  if (!/^\d{1,20}$/.test(id)) {
    return [];
  }
  ctx.documents.add(id);
  return [{ t: 'img', id, w: Number(rich.w) || 0, h: Number(rich.h) || 0 }];
};

// Text with no text inside (R-Y220): a formula, a custom emoji's picture
// (its `alt` word stays as the fallback).
const LEAVES = {
  TextMath: (rich) =>
    plain(rich.source) ? [{ t: 'math', s: plain(rich.source) }] : [],
  TextCustomEmoji: (rich) => {
    const alt = plain(rich.alt);
    const id = /^\d{1,20}$/.test(plain(rich.documentId))
      ? plain(rich.documentId)
      : null;
    if (!alt) {
      return [];
    }
    return id ? [{ t: 'emoji', id, s: alt }] : [{ t: 'text', s: alt }];
  },
};

const DATE_FLAGS = [
  'relative',
  'shortTime',
  'longTime',
  'shortDate',
  'longDate',
  'dayOfWeek',
];

// Kinds that wrap their words in a node of their own (R-Y225).
const WRAPPED = {
  TextHashtag: () => ({ t: 'tag' }),
  TextCashtag: () => ({ t: 'tag' }),
  TextBotCommand: () => ({ t: 'tag' }),
  TextBankCard: () => ({ t: 'bankcard' }),
  TextMentionName: (rich) =>
    /^\d{1,20}$/.test(plain(rich.userId))
      ? { t: 'user', id: plain(rich.userId) }
      : null,
  TextDate: (rich) => ({
    t: 'date',
    date: Number(rich.date) || 0,
    ...Object.fromEntries(DATE_FLAGS.map((key) => [key, Boolean(rich[key])])),
  }),
};

// The node of a wrapping kind, with the words it holds as `s`.
const wrappedNode = (rich, children) => {
  const node = WRAPPED[rich.className]?.(rich);
  return node ? wrap({ ...node, s: wordsIn(children) }, children) : children;
};

const LINKS = new Set([
  'TextUrl',
  'TextEmail',
  'TextPhone',
  ...Object.keys(AUTO),
]);

// Kinds with a shape of their own: an anchor, a button (R-Y225), and
// the words wrapped in a node.
const OWN = {
  TextAnchor: (rich, children) => {
    const anchor = plain(rich.name);
    return NAME.test(anchor)
      ? [{ t: 'anchor', name: anchor, c: children }]
      : children;
  },
  TextButton: (rich, children, ctx) =>
    children.length > 0 ? [{ t: 'button', ...pageButton(rich, ctx) }] : [],
  ...Object.fromEntries(
    Object.keys(WRAPPED).map((name) => [name, wrappedNode])
  ),
};

const richNodes = (rich, ctx, depth) => {
  if (!rich || depth > MAX_DEPTH) {
    return [];
  }
  const name = rich.className;
  if (name === 'TextPlain') {
    const s = plain(rich.text);
    return s ? [{ t: 'text', s }] : [];
  }
  if (name === 'TextConcat') {
    return (rich.texts ?? []).flatMap((one) => richNodes(one, ctx, depth + 1));
  }
  if (name === 'TextImage') {
    return imageOf(rich, ctx);
  }
  if (LEAVES[name]) {
    return LEAVES[name](rich);
  }
  const children = richNodes(rich.text, ctx, depth + 1);
  if (INLINE[name]) {
    return wrap({ t: INLINE[name] }, children);
  }
  if (OWN[name]) {
    return OWN[name](rich, children, ctx);
  }
  return LINKS.has(name) ? linkOf(rich, children, ctx) : children;
};

/** A RichText as inline nodes (see the header). */
export const shapeText = (rich, ctx = newContext()) => richNodes(rich, ctx, 0);

const idOf = (value) => {
  const id = plain(value);
  return /^\d{1,20}$/.test(id) ? id : null;
};

const caption = (cap, ctx) => ({
  c: shapeText(cap?.text, ctx),
  credit: shapeText(cap?.credit, ctx),
});

const TEXT_BLOCKS = {
  PageBlockHeading1: 'h1',
  PageBlockHeading2: 'h2',
  PageBlockHeading3: 'h3',
  PageBlockHeading4: 'h4',
  PageBlockHeading5: 'h5',
  PageBlockHeading6: 'h6',
  PageBlockThinking: 'thinking',
  PageBlockTitle: 'title',
  PageBlockSubtitle: 'subtitle',
  PageBlockHeader: 'header',
  PageBlockSubheader: 'subheader',
  PageBlockParagraph: 'p',
  PageBlockFooter: 'footer',
  PageBlockKicker: 'kicker',
};

const photoBlock = (block, ctx) => {
  const id = idOf(block.photoId);
  if (!id) {
    return null;
  }
  ctx.photos.add(id);
  const href = block.url ? safeHref(block.url) : null;
  return {
    k: 'photo',
    id,
    caption: caption(block.caption, ctx),
    ...(href ? { href } : {}),
  };
};

// A document's name, type and size from the page's or message's
// documents, for a file row and a player (R-Y224; learned, never copied).
const docInfo = (id, ctx) => {
  const doc = ctx.files.get(id);
  const named = (doc?.attributes ?? []).find((a) => a?.fileName);
  return {
    name: plain(named?.fileName).slice(0, 255),
    mime: plain(doc?.mimeType).slice(0, 100),
    size: Number(plain(doc?.size)) || 0,
  };
};

const mediaBlock = (kind, block, ctx, field) => {
  const id = idOf(block[field]);
  if (!id) {
    return null;
  }
  ctx.documents.add(id);
  return {
    k: kind,
    id,
    ...docInfo(id, ctx),
    caption: caption(block.caption, ctx),
  };
};

const embedBlock = (block, ctx) => {
  const href = block.url ? safeHref(block.url) : null;
  const poster = idOf(block.posterPhotoId);
  if (poster) {
    ctx.photos.add(poster);
  }
  return {
    k: 'embed',
    ...(href ? { href } : {}),
    ...(poster ? { poster } : {}),
    caption: caption(block.caption, ctx),
  };
};

const listItems = (items, ctx, depth, ordered) =>
  (items ?? []).map((item) => {
    const num = ordered
      ? { num: plain(item.num).slice(0, 16) || String(item.value ?? '') }
      : {};
    // A task-list item (R-Y220): `check` is its box, ticked or not.
    const check = item.checkbox ? { check: Boolean(item.checked) } : {};
    return item.blocks
      ? { ...num, ...check, blocks: shapeBlocks(item.blocks, ctx, depth + 1) }
      : { ...num, ...check, c: shapeText(item.text, ctx) };
  });

const span = (value) =>
  Number(value) > 1 ? Math.min(Number(value), 50) : undefined;

const cellOf = (cell, ctx) => ({
  c: shapeText(cell.text, ctx),
  ...(cell.header ? { header: true } : {}),
  ...(cell.alignCenter ? { center: true } : {}),
  ...(cell.alignRight ? { right: true } : {}),
  ...(cell.valignMiddle ? { vmiddle: true } : {}),
  ...(cell.valignBottom ? { vbottom: true } : {}),
  ...(span(cell.colspan) ? { colspan: span(cell.colspan) } : {}),
  ...(span(cell.rowspan) ? { rowspan: span(cell.rowspan) } : {}),
});

const tableBlock = (block, ctx) => ({
  k: 'table',
  bordered: Boolean(block.bordered),
  striped: Boolean(block.striped),
  title: shapeText(block.title, ctx),
  rows: (block.rows ?? [])
    .slice(0, 500)
    .map((row) =>
      (row.cells ?? []).slice(0, 50).map((cell) => cellOf(cell, ctx))
    ),
});

const articleOf = (one, ctx) => {
  const href = safeHref(one.url);
  if (!href) {
    return null;
  }
  const photo = idOf(one.photoId);
  if (photo) {
    ctx.photos.add(photo);
  }
  return {
    href,
    title: plain(one.title),
    description: plain(one.description),
    author: plain(one.author),
    ...(photo ? { photo } : {}),
    ...(Number(one.publishedDate) ? { date: Number(one.publishedDate) } : {}),
  };
};

const channelBlock = (block) => {
  const chat = block.channel ?? {};
  const username = plain(chat.username);
  return {
    k: 'channel',
    title: plain(chat.title),
    ...(/^[A-Za-z0-9_]{1,64}$/.test(username) ? { username } : {}),
  };
};

const mapBlock = (block, ctx) => {
  const lat = Number(block.geo?.lat);
  const lon = Number(block.geo?.long);
  return Number.isFinite(lat) && Number.isFinite(lon)
    ? {
        k: 'map',
        lat,
        lon,
        zoom: Number(block.zoom) || 0,
        caption: caption(block.caption, ctx),
      }
    : null;
};

// Blocks that hold other blocks.
const nested = {
  PageBlockCover: (b, ctx, d) => {
    const inner = shapeBlock(b.cover, ctx, d + 1);
    return inner ? { k: 'cover', block: inner } : null;
  },
  PageBlockEmbedPost: (b, ctx, d) => ({
    k: 'embedpost',
    ...(safeHref(b.url) ? { href: safeHref(b.url) } : {}),
    author: plain(b.author),
    date: Number(b.date) || 0,
    blocks: shapeBlocks(b.blocks, ctx, d + 1),
    caption: caption(b.caption, ctx),
  }),
  PageBlockCollage: (b, ctx, d) => ({
    k: 'collage',
    items: shapeBlocks(b.items, ctx, d + 1),
    caption: caption(b.caption, ctx),
  }),
  PageBlockSlideshow: (b, ctx, d) => ({
    k: 'slideshow',
    items: shapeBlocks(b.items, ctx, d + 1),
    caption: caption(b.caption, ctx),
  }),
  PageBlockDetails: (b, ctx, d) => ({
    k: 'details',
    open: Boolean(b.open),
    title: shapeText(b.title, ctx),
    blocks: shapeBlocks(b.blocks, ctx, d + 1),
  }),
  PageBlockList: (b, ctx, d) => ({
    k: 'list',
    ordered: false,
    items: listItems(b.items, ctx, d, false),
  }),
  PageBlockOrderedList: (b, ctx, d) => ({
    k: 'list',
    ordered: true,
    ...(Number.isInteger(Number(b.start)) && b.start !== undefined
      ? { start: Number(b.start) }
      : {}),
    ...(b.reversed ? { reversed: true } : {}),
    items: listItems(b.items, ctx, d, true),
  }),
  PageBlockBlockquoteBlocks: (b, ctx, d) => ({
    k: 'quoteblocks',
    blocks: shapeBlocks(b.blocks, ctx, d + 1),
    credit: shapeText(b.caption, ctx),
  }),
};

// A button of a rich message's row (R-Y220): its words, what pressing
// it does (the raw `type`, read by the page like an inline keyboard's)
// and its colour.
const BUTTON_TYPE_KEYS = [
  'className',
  'url',
  'data',
  'requiresPassword',
  'query',
  'samePeer',
  'userId',
  'copyText',
  'buttonId',
];
const pageButton = (one, ctx) => {
  const type = {};
  for (const key of BUTTON_TYPE_KEYS) {
    if (one.type?.[key] !== undefined && one.type[key] !== null) {
      type[key] = one.type[key];
    }
  }
  const style = one.style ?? {};
  return {
    c: shapeText(one.text, ctx),
    type,
    style: {
      bgPrimary: Boolean(style.bgPrimary),
      bgDanger: Boolean(style.bgDanger),
      bgSuccess: Boolean(style.bgSuccess),
      link: Boolean(style.link),
    },
  };
};

const buttonRow = (b, ctx) => ({
  k: 'buttons',
  align: b.alignRight ? 'right' : b.alignCenter ? 'center' : 'left',
  buttons: (b.buttons ?? []).slice(0, 20).map((one) => pageButton(one, ctx)),
});

// A file of a rich message: its name and size from the message's documents.
const fileBlock = (b, ctx) => {
  const id = idOf(b.documentId);
  if (!id) {
    return null;
  }
  ctx.documents.add(id);
  return {
    k: 'file',
    id,
    ...docInfo(id, ctx),
    caption: caption(b.caption, ctx),
  };
};

const flat = {
  PageBlockMath: (b) =>
    plain(b.source) ? { k: 'math', source: plain(b.source) } : null,
  PageBlockButtonRow: buttonRow,
  PageBlockDocument: fileBlock,
  PageBlockPreformatted: (b, ctx) => ({
    k: 'pre',
    c: shapeText(b.text, ctx),
    language: plain(b.language).slice(0, 32),
  }),
  PageBlockAuthorDate: (b, ctx) => ({
    k: 'authordate',
    c: shapeText(b.author, ctx),
    date: Number(b.publishedDate) || 0,
  }),
  PageBlockDivider: () => ({ k: 'divider' }),
  PageBlockAnchor: (b) =>
    NAME.test(plain(b.name)) ? { k: 'anchor', name: plain(b.name) } : null,
  PageBlockBlockquote: (b, ctx) => ({
    k: 'quote',
    ...(b.collapsed ? { collapsed: true } : {}),
    c: shapeText(b.text, ctx),
    credit: shapeText(b.caption, ctx),
  }),
  PageBlockPullquote: (b, ctx) => ({
    k: 'pullquote',
    c: shapeText(b.text, ctx),
    credit: shapeText(b.caption, ctx),
  }),
  PageBlockPhoto: photoBlock,
  PageBlockVideo: (b, ctx) => mediaBlock('video', b, ctx, 'videoId'),
  PageBlockAudio: (b, ctx) => mediaBlock('audio', b, ctx, 'audioId'),
  PageBlockEmbed: embedBlock,
  PageBlockChannel: channelBlock,
  PageBlockTable: tableBlock,
  PageBlockMap: mapBlock,
  PageBlockRelatedArticles: (b, ctx) => ({
    k: 'related',
    title: shapeText(b.title, ctx),
    articles: (b.articles ?? [])
      .slice(0, 50)
      .map((one) => articleOf(one, ctx))
      .filter(Boolean),
  }),
};

function shapeBlock(block, ctx, depth) {
  if (!block || depth > MAX_DEPTH || ctx.count >= MAX_BLOCKS) {
    return null;
  }
  ctx.count += 1;
  const name = block.className;
  if (TEXT_BLOCKS[name]) {
    return { k: TEXT_BLOCKS[name], c: shapeText(block.text, ctx) };
  }
  if (nested[name]) {
    return nested[name](block, ctx, depth);
  }
  return flat[name] ? flat[name](block, ctx) : null;
}

function shapeBlocks(blocks, ctx, depth) {
  return (blocks ?? [])
    .map((block) => shapeBlock(block, ctx, depth))
    .filter(Boolean);
}

/**
 * A Page as `{ url, rtl, blocks, photos, documents }`; `photos` and
 * `documents` list the ids (strings) the page uses.
 */
export const shapePage = (page) => {
  const ctx = newContext(plain(page?.url), page);
  const blocks = shapeBlocks(page?.blocks, ctx, 0);
  return {
    url: ctx.url,
    rtl: Boolean(page?.rtl),
    blocks,
    photos: [...ctx.photos],
    documents: [...ctx.documents],
  };
};

/**
 * A message's `rich_message` (R-Y220) as `{ rtl, part, blocks, photos,
 * documents }`: the blocks of an Instant View page, with the same safety
 * (see `shapePage`); `part` marks an answer still being written.
 */
export const shapeRich = (rich) => {
  const ctx = newContext('', rich);
  const blocks = shapeBlocks(rich?.blocks, ctx, 0);
  return {
    rtl: Boolean(rich?.rtl),
    part: Boolean(rich?.part),
    blocks,
    photos: [...ctx.photos],
    documents: [...ctx.documents],
  };
};

// The words of shaped blocks, one line per block (a list item, a button).
const wordsOf = (node, out) => {
  if (Array.isArray(node)) {
    node.forEach((one) => wordsOf(one, out));
  } else if (node && typeof node === 'object') {
    if (typeof node.s === 'string') {
      out.push(node.s);
    }
    for (const key of [
      'c',
      'items',
      'blocks',
      'buttons',
      'title',
      'credit',
      'caption',
    ]) {
      if (node[key] !== undefined) {
        wordsOf(node[key], out);
      }
    }
    if (typeof node.source === 'string') {
      out.push(node.source);
    }
    if (!node.t) {
      out.push('\n');
    }
  }
};

/** A rich message as plain text, for the chat list, search and notices. */
export const richPlainText = (rich, limit = 4000) => {
  const out = [];
  wordsOf(shapeRich(rich).blocks, out);
  return out
    .join('')
    .replace(/\n{2,}/g, '\n')
    .trim()
    .slice(0, limit);
};

/**
 * The whole file of a document an Instant View page used: its video, audio
 * or file (R-Y224; learned, never copied). Read-only: downloaded through
 * the Telegram client (up to 64 MB), never from the page's own site; the
 * last two are kept so a player's range requests share one download.
 *   `createWholeFiles(env, context, files)(key)` -> `{ buffer, mimeType,
 *   name }`, `{ error: 'too-large', size }` or null; `key` is
 *   `document:<id>` of the `files` map the page remembered.
 */

import { runIn, connected } from './telegram-stickers.js';
import { bigSize, fileLocation, nameOf } from './telegram-media.js';

const MAX_BYTES = 64 * 1024 * 1024;
const MAX_KEPT = 2;

const plain = (value) =>
  value === null || value === undefined ? '' : String(value.value ?? value);

export const createWholeFiles = (env, context, files) => {
  const kept = new Map(); // key -> { buffer, mimeType, name }
  const reading = new Map(); // key -> the download going on

  const download = async (c, file) => {
    const size = Number(plain(file.size)) || 0;
    if (size > MAX_BYTES) {
      return { error: 'too-large', size };
    }
    const buffer = await runIn(
      env,
      `instant-view-file:document:${plain(file.id)}:full`,
      () =>
        c.client.downloadFile(fileLocation(c.Api, c.helpers, file), {
          dcId: Number(file.dcId),
          fileSize: bigSize(c.helpers, size),
        })
    );
    return buffer?.length
      ? {
          buffer: Buffer.from(buffer),
          mimeType: plain(file.mimeType) || 'application/octet-stream',
          name: nameOf(file),
        }
      : null;
  };

  return async (key) => {
    if (kept.has(key)) {
      return kept.get(key);
    }
    if (!reading.has(key)) {
      reading.set(
        key,
        connected(
          env,
          context.userClient,
          () => null,
          (c) => download(c, files.get(key))
        ).finally(() => reading.delete(key))
      );
    }
    const got = await reading.get(key);
    if (got?.buffer) {
      kept.set(key, got);
      if (kept.size > MAX_KEPT) {
        kept.delete(kept.keys().next().value);
      }
    }
    return got;
  };
};

/**
 * Instant View, as Telegram Desktop and the official clients offer it
 * (R-Y205; learned, never copied). Read-only:
 * - `instantView({ url, hash? })` — messages.getWebPage → `{ ok,
 *   available: true, siteName, title, page }` where `page` is the safe
 *   tree of ./telegram-instant-view-shape.js, or `{ ok, available: false
 *   }` when Telegram has no cached page for the link (the page offers
 *   "Open in browser"). A `t.me/iv?url=…` link names the page it wraps.
 *   Telegram's errors (WEBPAGE_NOT_FOUND, …) become codes;
 * - `instantViewFile({ kind, id })` — a picture the last pages used
 *   (`kind` 'photo' or 'document'), downloaded through the Telegram
 *   client with the media helpers (never from the page's own site) →
 *   `{ buffer, mimeType }` or null. Pages and pictures are kept in memory.
 *   With `full: true` a document comes whole (up to 64 MB) with its name,
 *   for a page's video, audio and files (R-Y224; learned, never copied);
 *   the last two are kept so a player's range requests share one download.
 */

import { runIn, connected, failureOf } from './telegram-stickers.js';
import {
  pickSize,
  locationOf,
  bigSize,
  documentPicture,
} from './telegram-media.js';
import { createWholeFiles } from './telegram-instant-view-whole.js';
import { shapePage, safeHref } from './telegram-instant-view-shape.js';

const CODES = {
  WEBPAGE_NOT_FOUND: 'not-found',
  WEBPAGE_CURL_FAILED: 'unreachable',
  WEBPAGE_URL_INVALID: 'bad-url',
  URL_INVALID: 'bad-url',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);

const KEEP_MS = 5 * 60_000;
const MAX_PAGES = 30;
const MAX_FILES = 300;
const MAX_BYTES = 8 * 1024 * 1024;
const URL_MAX = 2048;
const ID = /^\d{1,20}$/;
export const KINDS = Object.freeze(['photo', 'document']);
const IV_HOSTS = /^(?:www\.)?(?:t\.me|telegram\.me|telegram\.dog)$/i;

const plain = (value) =>
  value === null || value === undefined ? '' : String(value.value ?? value);

const safeHttp = (text) => {
  const href = safeHref(text);
  return href && /^https?:/i.test(href) ? href : null;
};

/** The link to ask Telegram about: a t.me/iv?url=… link gives its url. */
export const targetOf = (link) => {
  const text = String(link ?? '').trim();
  if (text.length === 0 || text.length > URL_MAX) {
    return null;
  }
  try {
    const url = new URL(text);
    if (
      ['http:', 'https:'].includes(url.protocol) &&
      IV_HOSTS.test(url.hostname) &&
      url.pathname === '/iv'
    ) {
      const inner = url.searchParams.get('url') ?? '';
      return inner.length <= URL_MAX ? safeHttp(inner) : null;
    }
  } catch {
    return null;
  }
  return safeHttp(text);
};

const evict = (map, max) => {
  if (map.size > max) {
    map.delete(map.keys().next().value);
  }
};

export const createInstantView = (env, context) => {
  const pages = new Map(); // url -> { at, answer }
  const files = new Map(); // `kind:id` -> Photo | Document
  const bytes = new Map(); // `kind:id` -> { buffer, mimeType }
  const wholeFile = createWholeFiles(env, context, files);
  const now = () => (env.now ? env.now() : Date.now());

  const remember = (page, shaped) => {
    const want = {
      photo: new Set(shaped.photos),
      document: new Set(shaped.documents),
    };
    const add = (kind, list) => {
      for (const one of list ?? []) {
        const id = plain(one.id);
        if (want[kind].has(id) && ID.test(id)) {
          files.delete(`${kind}:${id}`);
          files.set(`${kind}:${id}`, one);
          evict(files, MAX_FILES);
        }
      }
    };
    add('photo', page.photos);
    add('document', page.documents);
  };

  const ask = async (c, url, hash) => {
    const got = await runIn(env, 'instant-view', () =>
      c.client.invoke(new c.Api.messages.GetWebPage({ url, hash }))
    );
    const web = got?.webpage;
    const cached = web?.className === 'WebPage' ? web.cachedPage : null;
    if (!cached || cached.className !== 'Page') {
      return { ok: true, available: false };
    }
    const shaped = shapePage(cached);
    remember(cached, shaped);
    const tree = { url: shaped.url, rtl: shaped.rtl, blocks: shaped.blocks };
    return {
      ok: true,
      available: true,
      siteName: plain(web.siteName),
      title: plain(web.title),
      page: { ...tree, url: tree.url || url },
    };
  };

  const instantView = async ({ url, hash = 0 } = {}) => {
    const target = targetOf(url);
    if (!target || !Number.isInteger(hash) || hash < 0 || hash > 2 ** 31 - 1) {
      return { ok: false, error: 'bad request', code: 'bad-request' };
    }
    const hit = pages.get(target);
    if (hit && now() - hit.at < KEEP_MS) {
      return hit.answer;
    }
    const answer = await connected(env, context.userClient, failure, (c) =>
      ask(c, target, hash)
    );
    if (answer.ok) {
      pages.delete(target);
      pages.set(target, { at: now(), answer });
      evict(pages, MAX_PAGES);
    }
    return answer;
  };

  const download = async (c, kind, file) => {
    const picture =
      kind === 'photo'
        ? {
            kind,
            file,
            thumb: pickSize(file.sizes ?? [], 'x'),
            mimeType: 'image/jpeg',
          }
        : documentPicture(file, 'x');
    if (!picture?.thumb && kind === 'photo') {
      return null;
    }
    const buffer = await runIn(
      env,
      `instant-view-file:${kind}:${plain(file.id)}`,
      () =>
        c.client.downloadFile(locationOf(c.Api, c.helpers, picture), {
          dcId: Number(file.dcId),
          fileSize: bigSize(c.helpers, MAX_BYTES),
        })
    );
    return buffer?.length
      ? { buffer: Buffer.from(buffer), mimeType: picture.mimeType }
      : null;
  };

  const instantViewFile = async ({ kind, id, full = false } = {}) => {
    const key = `${kind}:${id}`;
    if (full && kind === 'document' && files.has(key) && ID.test(id)) {
      return wholeFile(key);
    }
    if (
      !KINDS.includes(kind) ||
      !ID.test(String(id ?? '')) ||
      !files.has(key)
    ) {
      return null;
    }
    if (bytes.has(key)) {
      return bytes.get(key);
    }
    const got = await connected(
      env,
      context.userClient,
      () => null,
      (c) => download(c, kind, files.get(key))
    );
    if (got?.buffer) {
      bytes.set(key, got);
      evict(bytes, MAX_FILES);
      return got;
    }
    return null;
  };

  return { instantView, instantViewFile };
};

/**
 * A group's or channel's invite links and join requests, as Telegram
 * Desktop's "Manage" screens have them (R-Y152; learned, never copied):
 * - `inviteLinks({ chat, revoked?, offsetDate?, offsetLink? })` — the
 *   user's own links (messages.getExportedChatInvites, adminId = self),
 *   or the revoked ones → `{ ok, primary, links, count, next }`;
 * - `inviteCreate({ chat, title?, expireDate?, usageLimit?, requestNeeded? })`
 *   — a new link (messages.exportChatInvite) → `{ ok, invite }`;
 * - `inviteEdit({ chat, link, revoked?, title?, expireDate?, usageLimit?,
 *   requestNeeded? })` — a link changed or revoked
 *   (messages.editExportedChatInvite) → `{ ok, invite, replacement? }`;
 * - `inviteDelete({ chat, link })` / `inviteDeleteRevoked({ chat })` — one
 *   revoked link, or all of them, deleted;
 * - `inviteImporters({ chat, link?, requested?, offset? })` — who joined
 *   through a link, or who asks to join (messages.getChatInviteImporters)
 *   → `{ ok, importers, count, next }`;
 * - `joinRequestHide({ chat, user, accessHash?, approved })` and
 *   `joinRequestsHideAll({ chat, approved, link? })` — requests approved
 *   or dismissed (messages.hideChatJoinRequest, hideAllChatJoinRequests).
 * Expire dates sent are unix seconds; dates read are milliseconds.
 * Telegram's errors become codes the page shows as text.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';

export const INVITE_LINK =
  /^(?:https:\/\/)?t\.me\/(?:\+[A-Za-z0-9_-]{8,64}|joinchat\/[A-Za-z0-9_-]{8,64})$/;
export const TITLE_MAX = 32;
export const LIMIT_MAX = 99999;
const CHAT = /^-\d{1,20}$/;
const USER = /^\d{1,20}$/;
const PAGE = 50;
const TEN_YEARS = 10 * 365 * 86400;

const CODES = {
  CHAT_ADMIN_REQUIRED: 'not-admin',
  CHAT_ADMIN_INVITE_REQUIRED: 'not-admin',
  USER_NOT_PARTICIPANT: 'not-admin',
  CHANNEL_PRIVATE: 'no-access',
  CHANNEL_INVALID: 'no-access',
  PEER_ID_INVALID: 'no-access',
  INVITE_HASH_EXPIRED: 'link-gone',
  INVITE_HASH_INVALID: 'link-gone',
  INVITE_REVOKED_MISSING: 'link-gone',
  INVITE_EXPIRE_DATE_INVALID: 'expire-invalid',
  USAGE_LIMIT_INVALID: 'usage-invalid',
  HIDE_REQUESTER_MISSING: 'request-gone',
  USER_ID_INVALID: 'request-gone',
  ADMIN_INVITES_TOO_MUCH: 'too-many',
  INVITES_TOO_MUCH: 'too-many',
};

const failure = failureOf(CODES);
const bad = { ok: false, error: 'bad-request', code: 'bad-request' };

const textOf = (value) => String(value?.value ?? value);
const nameOf = (user) =>
  [user?.firstName, user?.lastName].filter(Boolean).join(' ') ||
  user?.username ||
  '';
const secondsOf = (ms) => Math.floor(Number(ms) / 1000);

/** An ExportedChatInvite as the page reads it (dates in ms). */
export const shapeInvite = (invite = {}) => ({
  link: invite.link ?? '',
  title: invite.title ?? '',
  revoked: Boolean(invite.revoked),
  permanent: Boolean(invite.permanent),
  requestNeeded: Boolean(invite.requestNeeded),
  date: Number(invite.date ?? 0) * 1000,
  expireDate: Number(invite.expireDate ?? 0) * 1000,
  usageLimit: Number(invite.usageLimit ?? 0),
  usage: Number(invite.usage ?? 0),
  requested: Number(invite.requested ?? 0),
});

export const validLink = (link) => INVITE_LINK.test(String(link ?? ''));
const validTitle = (title) =>
  title === undefined ||
  (typeof title === 'string' && Array.from(title).length <= TITLE_MAX);
const validExpire = (date, now) =>
  date === undefined ||
  date === 0 ||
  (Number.isInteger(date) && date > now && date < now + TEN_YEARS);
const validLimit = (limit) =>
  limit === undefined ||
  (Number.isInteger(limit) && limit >= 0 && limit <= LIMIT_MAX);

/** Whether `body` holds well-formed link settings (expire date in seconds). */
export const validSettings = (body, now = Math.floor(Date.now() / 1000)) =>
  validTitle(body.title) &&
  validExpire(body.expireDate, now) &&
  validLimit(body.usageLimit) &&
  (body.requestNeeded === undefined ||
    typeof body.requestNeeded === 'boolean') &&
  !(body.requestNeeded === true && body.usageLimit > 0);

// The settings Telegram's calls take; `keepZero` sends explicit zeros so an
// edit can clear what a link had.
const settingsOf = (body, keepZero) => ({
  ...(body.title === undefined ? {} : { title: body.title }),
  ...(body.expireDate === undefined || (!keepZero && !body.expireDate)
    ? {}
    : { expireDate: body.expireDate }),
  ...(body.usageLimit === undefined || (!keepZero && !body.usageLimit)
    ? {}
    : { usageLimit: body.usageLimit }),
});

const createList =
  (env, userClient) =>
  async (body = {}) => {
    const chat = String(body.chat ?? '');
    const { offsetLink } = body;
    if (
      !CHAT.test(chat) ||
      (offsetLink !== undefined && !validLink(offsetLink)) ||
      (body.offsetDate !== undefined && !Number.isInteger(body.offsetDate))
    ) {
      return bad;
    }
    const revoked = body.revoked === true;
    return connected(env, userClient, failure, async (c) => {
      const answer = await runIn(env, `links:list:${chat}:${revoked}`, () =>
        env.connection.withPeer(c.client, chat, (peer) =>
          c.client.invoke(
            new c.Api.messages.GetExportedChatInvites({
              peer,
              adminId: new c.Api.InputUserSelf(),
              limit: PAGE,
              ...(revoked ? { revoked: true } : {}),
              ...(offsetLink
                ? {
                    offsetDate: secondsOf(body.offsetDate ?? 0),
                    offsetLink,
                  }
                : {}),
            })
          )
        )
      );
      const all = (answer?.invites ?? []).map(shapeInvite);
      const primary = revoked ? null : all.find((i) => i.permanent);
      const last = all.at(-1);
      return {
        ok: true,
        primary: primary?.link ?? null,
        links: all.filter((i) => i !== primary),
        count: Number(answer?.count ?? all.length),
        next:
          all.length >= PAGE && last
            ? { offsetDate: last.date, offsetLink: last.link }
            : null,
      };
    });
  };

const inviteOf = (answer) =>
  answer?.newInvite
    ? {
        invite: shapeInvite(answer.invite),
        replacement: shapeInvite(answer.newInvite),
      }
    : { invite: shapeInvite(answer?.invite ?? answer) };

// One call on the chat's peer, run in its own queue slot.
const onPeer = (env, c, key, chat, make) =>
  runIn(env, key, () =>
    env.connection.withPeer(c.client, chat, (peer) =>
      c.client.invoke(make(peer))
    )
  );

const createCreate =
  (env, userClient) =>
  async (body = {}) => {
    const chat = String(body.chat ?? '');
    if (!CHAT.test(chat) || !validSettings(body)) {
      return bad;
    }
    return connected(env, userClient, failure, async (c) => {
      const answer = await onPeer(
        env,
        c,
        `links:create:${chat}`,
        chat,
        (peer) =>
          new c.Api.messages.ExportChatInvite({
            peer,
            ...settingsOf(body, false),
            ...(body.requestNeeded ? { requestNeeded: true } : {}),
          })
      );
      return { ok: true, ...inviteOf(answer) };
    });
  };

const createEdit =
  (env, userClient) =>
  async (body = {}) => {
    const chat = String(body.chat ?? '');
    if (
      !CHAT.test(chat) ||
      !validLink(body.link) ||
      !validSettings(body) ||
      (body.revoked !== undefined && body.revoked !== true)
    ) {
      return bad;
    }
    return connected(env, userClient, failure, async (c) => {
      const answer = await onPeer(
        env,
        c,
        `links:edit:${chat}`,
        chat,
        (peer) =>
          new c.Api.messages.EditExportedChatInvite({
            peer,
            link: body.link,
            ...(body.revoked ? { revoked: true } : settingsOf(body, true)),
            ...(!body.revoked && body.requestNeeded !== undefined
              ? { requestNeeded: body.requestNeeded }
              : {}),
          })
      );
      return { ok: true, ...inviteOf(answer) };
    });
  };

const createDelete =
  (env, userClient) =>
  async (body = {}) => {
    const chat = String(body.chat ?? '');
    if (!CHAT.test(chat) || !validLink(body.link)) {
      return bad;
    }
    return connected(env, userClient, failure, async (c) => {
      await onPeer(
        env,
        c,
        `links:delete:${chat}`,
        chat,
        (peer) =>
          new c.Api.messages.DeleteExportedChatInvite({
            peer,
            link: body.link,
          })
      );
      return { ok: true };
    });
  };

const createDeleteRevoked =
  (env, userClient) =>
  async (body = {}) => {
    const chat = String(body.chat ?? '');
    if (!CHAT.test(chat)) {
      return bad;
    }
    return connected(env, userClient, failure, async (c) => {
      await onPeer(
        env,
        c,
        `links:delete-revoked:${chat}`,
        chat,
        (peer) =>
          new c.Api.messages.DeleteRevokedExportedChatInvites({
            peer,
            adminId: new c.Api.InputUserSelf(),
          })
      );
      return { ok: true };
    });
  };

export const validOffset = (offset) =>
  offset === undefined ||
  (Number.isInteger(offset?.date) &&
    USER.test(String(offset.user ?? '')) &&
    (offset.accessHash === undefined || USER.test(String(offset.accessHash))));

// A person as an input user: by the hash the list gave, else as known.
const inputUser = async (c, id, accessHash) =>
  accessHash === undefined
    ? c.client.getInputEntity(c.helpers.returnBigInt(id))
    : new c.Api.InputUser({
        userId: c.helpers.returnBigInt(id),
        accessHash: c.helpers.returnBigInt(String(accessHash)),
      });

const importerOf = (importer, users) => {
  const id = textOf(importer.userId);
  const user = users.get(id);
  return {
    id,
    ...(user?.accessHash === undefined
      ? {}
      : { accessHash: textOf(user.accessHash) }),
    name: nameOf(user) || id,
    ...(user?.username ? { username: user.username } : {}),
    date: Number(importer.date) * 1000,
    ...(importer.about ? { about: importer.about } : {}),
    requested: Boolean(importer.requested),
  };
};

const createImporters =
  (env, userClient) =>
  async (body = {}) => {
    const chat = String(body.chat ?? '');
    if (
      !CHAT.test(chat) ||
      (body.link !== undefined && !validLink(body.link)) ||
      (body.requested !== undefined && typeof body.requested !== 'boolean') ||
      !validOffset(body.offset) ||
      (body.link === undefined && body.requested !== true)
    ) {
      return bad;
    }
    return connected(env, userClient, failure, async (c) => {
      const { offset } = body;
      const offsetUser = offset
        ? await inputUser(c, String(offset.user), offset.accessHash)
        : new c.Api.InputUserEmpty();
      const answer = await onPeer(
        env,
        c,
        `links:importers:${chat}`,
        chat,
        (peer) =>
          new c.Api.messages.GetChatInviteImporters({
            peer,
            offsetDate: offset ? secondsOf(offset.date) : 0,
            offsetUser,
            limit: PAGE,
            ...(body.link ? { link: body.link } : {}),
            ...(body.requested ? { requested: true } : {}),
          })
      );
      const users = new Map(
        (answer?.users ?? []).map((u) => [textOf(u.id), u])
      );
      const importers = (answer?.importers ?? []).map((i) =>
        importerOf(i, users)
      );
      const last = importers.at(-1);
      return {
        ok: true,
        importers,
        count: Number(answer?.count ?? importers.length),
        next:
          importers.length >= PAGE && last
            ? {
                date: last.date,
                user: last.id,
                ...(last.accessHash === undefined
                  ? {}
                  : { accessHash: last.accessHash }),
              }
            : null,
      };
    });
  };

const createHide =
  (env, userClient) =>
  async (body = {}) => {
    const chat = String(body.chat ?? '');
    const user = String(body.user ?? '');
    if (
      !CHAT.test(chat) ||
      !USER.test(user) ||
      typeof body.approved !== 'boolean' ||
      (body.accessHash !== undefined && !USER.test(String(body.accessHash)))
    ) {
      return bad;
    }
    return connected(env, userClient, failure, async (c) => {
      const userId = await inputUser(c, user, body.accessHash);
      await onPeer(
        env,
        c,
        `links:hide:${chat}:${user}`,
        chat,
        (peer) =>
          new c.Api.messages.HideChatJoinRequest({
            peer,
            userId,
            ...(body.approved ? { approved: true } : {}),
          })
      );
      return { ok: true };
    });
  };

const createHideAll =
  (env, userClient) =>
  async (body = {}) => {
    const chat = String(body.chat ?? '');
    if (
      !CHAT.test(chat) ||
      typeof body.approved !== 'boolean' ||
      (body.link !== undefined && !validLink(body.link))
    ) {
      return bad;
    }
    return connected(env, userClient, failure, async (c) => {
      await onPeer(
        env,
        c,
        `links:hide-all:${chat}`,
        chat,
        (peer) =>
          new c.Api.messages.HideAllChatJoinRequests({
            peer,
            ...(body.approved ? { approved: true } : {}),
            ...(body.link ? { link: body.link } : {}),
          })
      );
      return { ok: true };
    });
  };

export const createInviteLinks = (env, context) => ({
  inviteLinks: createList(env, context.userClient),
  inviteCreate: createCreate(env, context.userClient),
  inviteEdit: createEdit(env, context.userClient),
  inviteDelete: createDelete(env, context.userClient),
  inviteDeleteRevoked: createDeleteRevoked(env, context.userClient),
  inviteImporters: createImporters(env, context.userClient),
  joinRequestHide: createHide(env, context.userClient),
  joinRequestsHideAll: createHideAll(env, context.userClient),
});

/**
 * Chat invite links, as Telegram Desktop handles them (R-Y123; learned,
 * never copied):
 * - `checkChatInvite({ hash })` — what a link leads to
 *   (messages.checkChatInvite): `{ ok, already, chat }` when the user is in
 *   the chat (open it), else `{ ok, invite: { title, about, members,
 *   channel, broadcast, requestNeeded } }`;
 * - `joinChatInvite({ hash })` — only on the user's press of Join
 *   (messages.importChatInvite); the answer goes through the live handler,
 *   so the chat appears in the list;
 * - `revokeChatInvite({ chat })` — a chat's primary link replaced by a new
 *   one (messages.exportChatInvite with legacyRevokePermanent) →
 *   `{ ok, link }`.
 * Telegram's errors become codes the page shows as text.
 */

import { runIn, connected, failureOf } from './telegram-stickers.js';

export const INVITE_HASH = /^[A-Za-z0-9_-]{8,64}$/;

const CODES = {
  INVITE_HASH_EXPIRED: 'invite-expired',
  INVITE_HASH_INVALID: 'invite-invalid',
  INVITE_HASH_EMPTY: 'invite-invalid',
  INVITE_REQUEST_SENT: 'invite-request-sent',
  USERS_TOO_MUCH: 'chat-full',
  CHANNELS_TOO_MUCH: 'too-many-chats',
  USER_ALREADY_PARTICIPANT: 'already-member',
  CHAT_ADMIN_REQUIRED: 'not-admin',
};

const failure = failureOf(CODES);

const BAD_HASH = { ok: false, error: 'invite-invalid', code: 'invite-invalid' };

const textOf = (value) => String(value?.value ?? value);

// The chat's address in the list: a channel's marked id, a group's.
export const markedId = (chat) =>
  chat.className === 'Channel' || chat.className === 'ChannelForbidden'
    ? `-100${textOf(chat.id)}`
    : `-${textOf(chat.id)}`;

const describe = (found) => {
  if (
    (found.className === 'ChatInviteAlready' ||
      found.className === 'ChatInvitePeek') &&
    found.chat
  ) {
    return {
      ok: true,
      already: true,
      chat: markedId(found.chat),
      title: found.chat.title ?? '',
    };
  }
  return {
    ok: true,
    already: false,
    invite: {
      title: found.title ?? '',
      about: found.about ?? '',
      members: Number(found.participantsCount ?? 0),
      channel: Boolean(found.channel),
      broadcast: Boolean(found.broadcast),
      megagroup: Boolean(found.megagroup),
      requestNeeded: Boolean(found.requestNeeded),
    },
  };
};

const createChecker =
  (env, userClient) =>
  async (request = {}) => {
    const hash = String(request.hash ?? '');
    if (!INVITE_HASH.test(hash)) {
      return BAD_HASH;
    }
    return connected(env, userClient, failure, async (c) => {
      const found = await runIn(env, `invite:check:${hash}`, () =>
        c.client.invoke(new c.Api.messages.CheckChatInvite({ hash }))
      );
      return describe(found ?? {});
    });
  };

const createJoiner =
  (env, { userClient, apply }) =>
  async (request = {}) => {
    const hash = String(request.hash ?? '');
    if (!INVITE_HASH.test(hash)) {
      return BAD_HASH;
    }
    return connected(env, userClient, failure, async (c) => {
      const answer = await runIn(env, `invite:join:${hash}`, () =>
        c.client.invoke(new c.Api.messages.ImportChatInvite({ hash }))
      );
      // Layer 232 wraps the updates (R-Y220): chatInviteJoinResultOk; a
      // web-view result (a bot asks first) has none.
      const result = answer?.updates ?? (answer?.queryId ? null : answer);
      if (result && typeof result === 'object') {
        await apply(c.client, result);
      }
      const chat = (result?.chats ?? []).find(Boolean);
      return { ok: true, ...(chat ? { chat: markedId(chat) } : {}) };
    });
  };

const createRevoker =
  (env, userClient) =>
  async (request = {}) => {
    const target = String(request.chat ?? '');
    if (!/^-\d{1,20}$/.test(target)) {
      return { ok: false, error: 'bad chat', code: 'failed' };
    }
    return connected(env, userClient, failure, async (c) => {
      const result = await runIn(env, `invite:revoke:${target}`, () =>
        env.connection.withPeer(c.client, target, (peer) =>
          c.client.invoke(
            new c.Api.messages.ExportChatInvite({
              peer,
              legacyRevokePermanent: true,
            })
          )
        )
      );
      const link = (result?.newInvite ?? result?.invite ?? result)?.link;
      return typeof link === 'string' && link
        ? { ok: true, link }
        : { ok: false, error: 'failed', code: 'failed' };
    });
  };

/** `env` is the account's; `apply(client, result)` the live handler. */
export const createInvites = (env, context) => ({
  checkChatInvite: createChecker(env, context.userClient),
  joinChatInvite: createJoiner(env, context),
  revokeChatInvite: createRevoker(env, context.userClient),
});

/**
 * A chat opened far back, as Telegram's apps open it on a date picked
 * in the calendar (R-Y106; learned, never copied): the first message on
 * or after that moment, with a page around it, read from Telegram and
 * stored; then the pages after it, one at a time, as the user scrolls
 * down toward the newest. Nothing between there and the newest is read
 * first.
 *
 * What is read joins the chat's stored stretch (./telegram-history.js)
 * once it reaches it, so the rest comes from the store.
 */

import { coverSlice, historyLink, historyLinkId } from './telegram-history.js';

const iso = (ms) => new Date(ms).toISOString();

const real = (list) =>
  [...(list ?? [])].filter(
    (m) => m && m.id !== undefined && m.className !== 'MessageEmpty'
  );

// Whether the stored stretch holds message `id` and what follows it.
const covers = (record, id) =>
  record?.oldest !== null &&
  record?.oldest !== undefined &&
  Number(id) >= Number(record.oldest) &&
  Number(id) <= Number(record.newest);

/**
 * `env` is the account's; `tools` the page reader's; `whereIs(env,
 * tools, client, chat, priority)` → `{ peer, dialog }`.
 */
export const createHistoryJump = (env, tools, { whereIs }) => {
  const { store, connection, queue, now } = env;

  const open = async (target, priority) => {
    const creds = await tools.credentials();
    if (creds?.kind !== 'user') {
      return null;
    }
    const { client } = await connection.open(creds);
    const { peer, dialog } = await whereIs(
      env,
      tools,
      client,
      target,
      priority
    );
    return { client, peer, dialog };
  };

  // Store what was read; join the stretch when it reaches it.
  const keep = async (target, dialog, list) => {
    const written = await tools.writeChanged(
      store,
      tools.toLinks(dialog, list)
    );
    const record = await store.get(historyLinkId(target));
    const cover = coverSlice(record, {
      ids: list.map((m) => m.id),
      limit: list.length,
      mode: 'newer',
      at: iso(now()),
    });
    if (cover !== record) {
      await store.put(historyLink(target, cover));
    }
    return written;
  };

  /**
   * The first message at or after `date` (unix seconds) and the messages
   * around it, stored: `{ ok, id, newest }` — `id` null when nothing is
   * that late (the chat's newest is where to go), `newest` when the
   * page reaches the chat's newest message.
   */
  const historyAt = async ({ chat, date, limit = 50, priority = 'view' }) => {
    const target = String(chat ?? '');
    const at = target && date > 0 ? await open(target, priority) : null;
    if (!at) {
      return { ok: false, supported: false };
    }
    const half = Math.max(1, Math.floor(limit / 2));
    const read = (side, options) =>
      queue.run(`at:${target}:${date}:${side}`, priority, () =>
        at.client.getMessages(at.peer, options)
      );
    const later = real(
      await read('after', { offsetDate: date, reverse: true, limit: half })
    );
    const earlier = real(
      await read('before', { offsetDate: date, limit: limit - half })
    );
    const written = await keep(target, at.dialog, [...earlier, ...later]);
    return {
      ok: true,
      id: later.length ? Number(later[0].id) : null,
      newest: later.length < half,
      written,
    };
  };

  /**
   * Message `id` and the messages around it, stored (from Telegram unless
   * the stretch already holds it): `{ ok, id, newest }` — `id` null when
   * Telegram has no such message (deleted).
   */
  const historyAround = async ({ chat, id, limit = 50, priority = 'view' }) => {
    const target = String(chat ?? '');
    const record = await store.get(historyLinkId(target));
    if (target && covers(record, id)) {
      return { ok: true, id: Number(id), newest: false, cached: true };
    }
    const at = target && id > 0 ? await open(target, priority) : null;
    if (!at) {
      return { ok: false, supported: false };
    }
    const half = Math.max(1, Math.floor(limit / 2));
    const read = (side, options) =>
      queue.run(`around:${target}:${id}:${side}`, priority, () =>
        at.client.getMessages(at.peer, options)
      );
    // Messages after `id - 1`, oldest first: `id` itself, then newer.
    const later = real(
      await read('after', { offsetId: id - 1, reverse: true, limit: half })
    );
    const earlier = real(
      await read('before', { offsetId: id, limit: limit - half })
    );
    const written = await keep(target, at.dialog, [...earlier, ...later]);
    const found = later.find((m) => Number(m.id) === Number(id));
    return {
      ok: true,
      id: found ? Number(id) : (later[0]?.id ?? null),
      newest: later.length < half,
      written,
    };
  };

  /**
   * The page after message `after`, stored (from Telegram unless the
   * stretch already holds it): `{ written, cached, newest }`.
   */
  const newer = async ({ chat, after, limit = 50, priority = 'view' }) => {
    const target = String(chat ?? '');
    const record = await store.get(historyLinkId(target));
    if (covers(record, after)) {
      return { written: 0, cached: true, newest: false };
    }
    const at = await open(target, priority);
    if (!at) {
      return { written: 0 };
    }
    const list = real(
      await queue.run(`newer:${target}:${after}:${limit}`, priority, () =>
        at.client.getMessages(at.peer, {
          offsetId: Number(after),
          reverse: true,
          limit,
        })
      )
    );
    const written = await keep(target, at.dialog, list);
    return { written, cached: false, newest: list.length < limit };
  };

  return { historyAt, historyAround, newer };
};

/**
 * GramJS speaking Telegram's current API layer (R-Y76).
 *
 * GramJS builds every TL class from one schema text (`telegram/tl/apiTl.js`)
 * and names its layer when it connects (`AllTLObjects.LAYER`). Its copy
 * is older than Telegram's, and Telegram sends a client what its layer
 * cannot describe — checklists, polls since their new constructor, newer
 * media — as `messageMediaUnsupported`, which no later read can repair.
 * So before GramJS loads, its schema module is given the layer Telegram
 * publishes (./telegram-api/layer-N.tl, made by
 * js/scripts/telegram-schema.mjs), and its LAYER set to match.
 *
 * Anything going wrong here leaves GramJS as it was: older, but working.
 */

import { readFileSync } from 'node:fs';
import Module, { createRequire } from 'node:module';
import { configureTelegramCrypto } from './telegram-runtime.js';

export const LAYER = 232;

/**
 * The revision of the schema file at that layer (R-Y220). The repair that
 * reads unsupported messages again keeps its marker per layer *and*
 * revision, so a newly generated file (rich messages arrived at layer 232
 * after a first trial of it) makes the re-read run once more. Bump it
 * whenever layer-N.tl is regenerated.
 */
export const SCHEMA_REV = 2;

const SCHEMA = new URL(`./telegram-api/layer-${LAYER}.tl`, import.meta.url);

let installed = null;

/**
 * Give GramJS the newer schema; `{ layer, from? , error? }`. Must run
 * before the first `import('teleproto')`; later it only reports.
 */
export const installTelegramLayer = ({ schema = SCHEMA } = {}) => {
  configureTelegramCrypto();
  if (installed) {
    return installed;
  }
  try {
    const require = createRequire(import.meta.url);
    // Maintained teleproto ships generated classes at the current layer.
    // Keep the legacy schema repair for older GramJS installations.
    const current = require('teleproto/tl').LAYER;
    if (current >= LAYER) {
      installed = { layer: current, from: current };
      return installed;
    }
    const file = require.resolve('teleproto/tl/apiTl.js');
    if (require.cache[file]) {
      // GramJS was loaded first: its classes are already built.
      const { LAYER: current } = require('teleproto/tl/AllTLObjects.js');
      installed = { layer: current, error: 'telegram loaded before' };
      return installed;
    }
    const tl = readFileSync(schema, 'utf8');
    const seeded = new Module(file);
    seeded.filename = file;
    seeded.loaded = true;
    seeded.exports = tl;
    require.cache[file] = seeded;
    const all = require('teleproto/tl/AllTLObjects.js');
    const from = all.LAYER;
    all.LAYER = LAYER;
    installed = { layer: LAYER, from };
  } catch (error) {
    installed = { layer: null, error: String(error?.message ?? error) };
  }
  return installed;
};

// Dialogs that name no chat or person: a community (layer 232, R-Y220)
// is a `dialogCommunity` with a community id and no peer. GramJS builds
// every dialog from `dialog.peer`, so one such entry would fail the whole
// list; these are left out where the list is read.
export const peerDialogs = (dialogs) =>
  Array.isArray(dialogs) ? dialogs.filter((d) => d && d.peer) : dialogs;

const DIALOG_LISTS = ['Dialogs', 'DialogsSlice', 'PeerDialogs'];
const patched = new WeakSet();

// Run `fix(answer)` on every answer of `Class` GramJS reads.
const afterRead = (Class, fix) => {
  const read = Class?.fromReader;
  if (typeof read === 'function') {
    Class.fromReader = function fromReader(reader) {
      const answer = read.call(this, reader);
      fix(answer);
      return answer;
    };
  }
};

/** Make GramJS skip dialogs without a peer when it reads a dialog list. */
export const skipPeerlessDialogs = (Api) => {
  if (!Api?.messages || patched.has(Api)) {
    return;
  }
  patched.add(Api);
  for (const name of DIALOG_LISTS) {
    afterRead(Api.messages[name], (list) => {
      list.dialogs = peerDialogs(list.dialogs);
    });
  }
};

// Communities (layer 232, R-Y222): Telegram lists a `community` or
// `communityForbidden` among the `chats` of its answers, and GramJS's
// `getPeerId` / `getInputPeer` throw "Cannot cast Community to any kind
// of int" on them, failing the dialog sync and message reads. They are
// not shown, so they are dropped where an answer is read.
const COMMUNITIES = new Set(['Community', 'CommunityForbidden']);

export const withoutCommunities = (chats) =>
  Array.isArray(chats)
    ? chats.filter((c) => !COMMUNITIES.has(c?.className))
    : chats;

// The classes whose constructor has a `chats:Vector<Chat>` field, from
// the schema text: `messages.dialogsSlice` is `Api.messages.DialogsSlice`.
export const chatListClasses = (tl) =>
  tl
    .split('---functions---')[0]
    .split('\n')
    .filter((line) => line.includes(' chats:Vector<Chat>'))
    .map((line) => line.split('#')[0].split('.'));

const communitiesDropped = new WeakSet();

/** Make GramJS never see a community in an answer's `chats` (R-Y222). */
export const skipCommunities = (Api, tl) => {
  if (!Api || communitiesDropped.has(Api)) {
    return;
  }
  communitiesDropped.add(Api);
  for (const path of chatListClasses(tl)) {
    const name = path.pop();
    const Class = path.reduce((ns, part) => ns?.[part], Api)?.[
      name[0].toUpperCase() + name.slice(1)
    ];
    afterRead(Class, (answer) => {
      answer.chats = withoutCommunities(answer.chats);
    });
  }
};

// Layer 232 folded the button classes (`keyboardButtonUrl`, …) into a
// button's `type`. GramJS's message helpers still test a button against
// those classes when `message.buttons` is read, and testing against a class
// that does not exist throws. Empty stand-ins, which no
// button is ever an instance of, keep that harmless.
const OLD_BUTTONS = [
  'Url',
  'Callback',
  'RequestPhone',
  'RequestGeoLocation',
  'SwitchInline',
  'Game',
  'Buy',
  'UrlAuth',
  'RequestPoll',
  'UserProfile',
  'WebView',
  'SimpleWebView',
  'RequestPeer',
  'Copy',
];

export const quietOldButtons = (Api) => {
  for (const name of OLD_BUTTONS) {
    for (const prefix of ['KeyboardButton', 'InputKeyboardButton']) {
      if (Api && Api[`${prefix}${name}`] === undefined) {
        Api[`${prefix}${name}`] = class {};
      }
    }
  }
};

/** `import('teleproto')` at the current layer. */
export const importTelegram = async () => {
  installTelegramLayer();
  // Use the same CommonJS registry as the reader and layer probe. Deno's
  // npm import map can otherwise load a second copy with unpatched classes.
  const telegram = createRequire(import.meta.url)('teleproto');
  try {
    skipPeerlessDialogs(telegram.Api);
    skipCommunities(telegram.Api, readFileSync(SCHEMA, 'utf8'));
    quietOldButtons(telegram.Api);
  } catch {
    // GramJS stays as it was.
  }
  return telegram;
};

/**
 * The channels the user left, as Telegram Desktop shows them when the
 * channel limit is hit (R-Y200; learned, never copied):
 * - `leftChannels({ offset? })` — one page (channels.getLeftChannels, by
 *   how many were already read) → `{ ok, channels: [{ chat (-100…), title,
 *   username, members, broadcast }], next }`; `next` is the offset of the
 *   following page, or null at the end. Read only: nothing is joined here;
 *   the page's preview does that on the explicit Join.
 * Telegram's errors become codes the page shows as text.
 */

import { similarOf } from './telegram-similar-channels.js';
import { connected, failureOf, runIn } from './telegram-stickers.js';

const failure = failureOf({ FLOOD_WAIT: 'flood' });
const OFFSET = /^\d{1,6}$/;
// Without a total from Telegram, a page this full may have another behind.
const FULL_PAGE = 100;

/** The offset after a page, or null at the end. */
export const nextOffset = (answer, offset, count) => {
  const total = Number(answer?.count);
  // Only a slice carries a total.
  if (answer?.count !== undefined && Number.isFinite(total)) {
    return offset + count < total ? offset + count : null;
  }
  return count >= FULL_PAGE ? offset + count : null;
};

const createLeft =
  (env, userClient) =>
  async (body = {}) => {
    const offset = body.offset === undefined ? 0 : body.offset;
    if (!OFFSET.test(String(offset))) {
      return { ok: false, error: 'bad-request', code: 'bad-request' };
    }
    const from = Number(offset);
    return connected(env, userClient, failure, async (c) => {
      const answer = await runIn(env, `left-channels:${from}`, () =>
        c.client.invoke(new c.Api.channels.GetLeftChannels({ offset: from }))
      );
      const channels = (answer?.chats ?? []).map(similarOf).filter(Boolean);
      return {
        ok: true,
        channels,
        next: nextOffset(answer, from, channels.length),
      };
    });
  };

export const createLeftChannels = (env, context) => ({
  leftChannels: createLeft(env, context.userClient),
});

/**
 * The link preview of the message box, as Telegram Desktop shows it
 * (R-Y145; learned, never copied):
 *
 * - `linkPreview({ text, url })` — messages.getWebPagePreview with the
 *   text and its entities → `{ ok, state: 'ready', preview }` (`preview`:
 *   `{ url, displayUrl, siteName, title, description, photo, large }`,
 *   `photo` the id of a picture the route below serves, else null),
 *   `{ ok, state: 'pending' }` while Telegram is still fetching the page
 *   (the page asks again), or `{ ok, state: 'empty' }` (no preview).
 *   Ready and empty answers are kept for five minutes per link;
 * - `linkPreviewPhoto({ id })` — the picture of a page Telegram sent in
 *   a preview, downloaded through the Telegram client (never from the
 *   page's own site); only ids this module handed out are served.
 *
 * `previewFields(body)` validates what a send carries about it:
 * `noWebpage`, `invertMedia`, and `previewUrl` with `previewSize`
 * ('large' | 'small') → the draft's fields, or null when invalid.
 */

import { runIn, connected, failureOf } from './telegram-stickers.js';
import { pickSize } from './telegram-media.js';
import { apiEntities, parseFormatted } from './telegram-format.js';

const failure = failureOf({ FLOOD_WAIT: 'flood', MESSAGE_EMPTY: 'empty' });

const KEEP_MS = 5 * 60_000;
const MAX_KEPT = 200;
const MAX_PHOTOS = 100;
const MAX_TEXT = 8192;
const URL_MAX = 2048;
const ID = /^\d{1,20}$/;
export const PREVIEW_URL = /^(https?:\/\/)?[^\s<>"']{3,2048}$/i;
export const PREVIEW_SIZES = Object.freeze(['large', 'small']);

const plain = (value) =>
  value === null || value === undefined ? '' : String(value.value ?? value);

const bytesOf = (value) => {
  if (value instanceof Uint8Array) {
    return Buffer.from(value);
  }
  return typeof value?.bytes === 'string'
    ? Buffer.from(value.bytes, 'base64')
    : Buffer.alloc(0);
};

const validUrlAndSize = ({ previewUrl, previewSize }) =>
  typeof previewUrl === 'string' &&
  previewUrl.length <= URL_MAX &&
  PREVIEW_URL.test(previewUrl) &&
  PREVIEW_SIZES.includes(previewSize);

/** The send's preview fields from a request body, or null if invalid. */
export const previewFields = (body = {}) => {
  const { noWebpage, invertMedia, previewUrl, previewSize } = body;
  if (
    [noWebpage, invertMedia].some(
      (v) => v !== undefined && v !== true && v !== false
    )
  ) {
    return null;
  }
  const hasUrl = previewUrl !== undefined;
  if (hasUrl !== (previewSize !== undefined)) {
    return null;
  }
  if (hasUrl && !validUrlAndSize(body)) {
    return null;
  }
  return {
    ...(noWebpage === true ? { noWebpage: true } : {}),
    ...(invertMedia === true ? { invertMedia: true } : {}),
    ...(hasUrl && noWebpage !== true ? { previewUrl, previewSize } : {}),
  };
};

// A WebPage as the page draws its bar; null when there is nothing to show.
const shape = (page, remember) => {
  if (page?.className !== 'WebPage') {
    return null;
  }
  const photo = page.photo?.className === 'Photo' ? page.photo : null;
  const photoId = photo ? plain(photo.id) : null;
  if (photo) {
    remember(photoId, photo);
  }
  return {
    url: plain(page.url),
    displayUrl: plain(page.displayUrl),
    siteName: plain(page.siteName),
    title: plain(page.title),
    description: plain(page.description),
    photo: photoId,
    large: Boolean(page.hasLargeMedia),
  };
};

export const createLinkPreview = (env, context) => {
  const kept = new Map(); // url -> { at, answer }
  const photos = new Map(); // id -> Photo
  const bytes = new Map(); // id -> { buffer, mimeType }
  const now = () => (env.now ? env.now() : Date.now());

  const remember = (id, photo) => {
    photos.delete(id);
    photos.set(id, photo);
    if (photos.size > MAX_PHOTOS) {
      const old = photos.keys().next().value;
      photos.delete(old);
      bytes.delete(old);
    }
  };

  const keep = (url, answer) => {
    kept.delete(url);
    kept.set(url, { at: now(), answer });
    if (kept.size > MAX_KEPT) {
      kept.delete(kept.keys().next().value);
    }
  };

  const ask = async (c, text) => {
    const formatted = parseFormatted(text);
    const entities = apiEntities(c.Api, formatted.entities);
    const got = await runIn(env, 'link-preview', () =>
      c.client.invoke(
        new c.Api.messages.GetWebPagePreview({
          message: formatted.text,
          ...(entities.length > 0 ? { entities } : {}),
        })
      )
    );
    const page = got?.media?.webpage ?? null;
    if (page?.className === 'WebPagePending') {
      return { ok: true, state: 'pending' };
    }
    const preview = shape(page, remember);
    return preview
      ? { ok: true, state: 'ready', preview }
      : { ok: true, state: 'empty' };
  };

  const linkPreview = async ({ text, url } = {}) => {
    const link = String(url ?? '');
    if (
      typeof text !== 'string' ||
      text.length === 0 ||
      text.length > MAX_TEXT ||
      !PREVIEW_URL.test(link) ||
      !text.toLowerCase().includes(link.toLowerCase())
    ) {
      return { ok: false, error: 'bad request', code: 'bad-request' };
    }
    const hit = kept.get(link);
    if (hit && now() - hit.at < KEEP_MS) {
      return hit.answer;
    }
    const answer = await connected(env, context.userClient, failure, (c) =>
      ask(c, text)
    );
    if (answer.ok && answer.state !== 'pending') {
      keep(link, answer);
    }
    return answer;
  };

  const download = async (c, photo) => {
    const type = pickSize(photo.sizes ?? [], 'm');
    if (!type) {
      return null;
    }
    const buffer = await runIn(
      env,
      `link-preview-photo:${plain(photo.id)}`,
      () =>
        c.client.downloadFile(
          new c.Api.InputPhotoFileLocation({
            id: c.helpers.returnBigInt(plain(photo.id)),
            accessHash: c.helpers.returnBigInt(plain(photo.accessHash)),
            fileReference: bytesOf(photo.fileReference),
            thumbSize: type,
          }),
          { dcId: Number(photo.dcId) }
        )
    );
    return buffer?.length
      ? { buffer: Buffer.from(buffer), mimeType: 'image/jpeg' }
      : null;
  };

  const linkPreviewPhoto = async ({ id } = {}) => {
    const key = String(id ?? '');
    if (!ID.test(key) || !photos.has(key)) {
      return null;
    }
    if (bytes.has(key)) {
      return bytes.get(key);
    }
    const got = await connected(
      env,
      context.userClient,
      () => null,
      (c) => download(c, photos.get(key))
    );
    if (got?.buffer) {
      bytes.set(key, got);
      return got;
    }
    return null;
  };

  return { linkPreview, linkPreviewPhoto };
};

/**
 * Map pictures for places (R-Y131), as Telegram Desktop draws them
 * (learned, never copied): a place in a chat shows a map image that
 * Telegram makes, asked with upload.getWebFile for an
 * InputWebFileGeoPointLocation.
 *
 * - `mapImage({ lat, lon, accessHash?, w, h, zoom, scale })` — the image
 *   `{ ok, mime, bytes }`, read in 128 KiB chunks until the bytes run
 *   out. Kept in memory (about 64 pictures), so a place seen again is
 *   not asked again.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';

const CHUNK = 128 * 1024;
// A map picture is small; more than this is not one.
const MAX_BYTES = 4 * 1024 * 1024;
const KEPT = 64;

const CODES = {
  FLOOD_WAIT: 'flood',
  WEBFILE_NOT_AVAILABLE: 'map-unavailable',
  LOCATION_INVALID: 'map-unavailable',
  GEO_POINT_INVALID: 'map-unavailable',
};

const bytesOf = (value) =>
  value instanceof Uint8Array ? Buffer.from(value) : Buffer.alloc(0);

const MIMES = {
  'storage.FileJpeg': 'image/jpeg',
  'storage.FilePng': 'image/png',
};

// The picture's type: Telegram's own, else from its file type.
const mimeOf = (file) => {
  const mime = String(file?.mimeType ?? '');
  return mime.startsWith('image/')
    ? mime
    : (MIMES[file?.fileType?.className] ?? 'image/png');
};

export const createMapActions = (env, context) => {
  const { userClient } = context;
  const kept = new Map(); // key -> { ok, mime, bytes }
  const fail = failureOf(CODES);

  const read = async (c, location) => {
    const parts = [];
    let mime = 'image/png';
    let offset = 0;
    while (offset < MAX_BYTES) {
      const file = await c.client.invoke(
        new c.Api.upload.GetWebFile({ location, offset, limit: CHUNK })
      );
      const part = bytesOf(file?.bytes);
      if (offset === 0) {
        mime = mimeOf(file);
      }
      parts.push(part);
      offset += part.length;
      if (part.length < CHUNK || (file?.size && offset >= file.size)) {
        break;
      }
    }
    return { ok: offset > 0, mime, bytes: Buffer.concat(parts) };
  };

  const mapImage = async ({ lat, lon, accessHash, w, h, zoom, scale }) => {
    const key = [lat, lon, accessHash ?? '', w, h, zoom, scale].join('|');
    if (kept.has(key)) {
      return kept.get(key);
    }
    const answer = await connected(env, userClient, fail, (c) =>
      runIn(env, `map:${key}`, () =>
        read(
          c,
          new c.Api.InputWebFileGeoPointLocation({
            geoPoint: new c.Api.InputGeoPoint({ lat, long: lon }),
            accessHash: c.helpers.returnBigInt(accessHash ?? 0),
            w,
            h,
            zoom,
            scale,
          })
        )
      )
    );
    if (answer.ok) {
      kept.set(key, answer);
      if (kept.size > KEPT) {
        kept.delete(kept.keys().next().value);
      }
    }
    return answer;
  };

  return { mapImage };
};

// A number in [min, max] (whole when `whole`) from a query, else null.
const numberIn = (value, min, max, whole) => {
  const n = /^-?\d+(\.\d+)?$/.test(value ?? '') ? Number(value) : NaN;
  return n >= min && n <= max && (!whole || Number.isInteger(n)) ? n : null;
};

/** A map request's query checked: the arguments, or null. */
export const mapQuery = (query) => {
  const args = {
    lat: numberIn(query.get('lat'), -90, 90, false),
    lon: numberIn(query.get('lon'), -180, 180, false),
    w: numberIn(query.get('w'), 16, 1024, true),
    h: numberIn(query.get('h'), 16, 1024, true),
    zoom: numberIn(query.get('zoom'), 13, 20, true),
    scale: numberIn(query.get('scale'), 1, 3, true),
  };
  const hash = query.get('hash') ?? '';
  if (Object.values(args).includes(null) || !/^(-?\d{1,20})?$/.test(hash)) {
    return null;
  }
  return hash ? { ...args, accessHash: hash } : args;
};

const reply = (status, body, headers = {}) => ({
  status,
  body,
  headers: { 'x-content-type-options': 'nosniff', ...headers },
});

const answerOf = async (account, query) => {
  const args = mapQuery(query);
  if (!args) {
    return reply(400, 'bad map request');
  }
  if (typeof account.mapImage !== 'function') {
    return reply(501, 'maps not available');
  }
  const map = await account.mapImage(args);
  return map?.ok
    ? reply(200, map.bytes, {
        'content-type': map.mime || 'image/png',
        'content-length': map.bytes.length,
        // A place's map keeps; the browser may hold it for a day.
        'cache-control': 'private, max-age=86400',
      })
    : reply(404, 'no map');
};

/** The route's answer to `req`, written to `res`. */
export const answerMap = async (account, req, res) => {
  const query = new URL(req.url, 'http://local').searchParams;
  const { status, headers, body } = await answerOf(account, query);
  res.writeHead(status, headers);
  res.end(body);
  return true;
};

/**
 * Pictures of Telegram messages, store first (R-Y36): a photo, a link
 * preview's photo, a file's thumbnail or a small picture sent as a file
 * (a sticker), for the chat to show inline as Telegram's apps do.
 *
 * Where a picture is comes from the stored message (`raw.media`, R-Y28):
 * its id, access hash, file reference and data centre. So showing it is
 * one download, never a re-read of the message first; only when Telegram
 * says the file reference expired is the message read again (by its
 * stored peer, through the queue) and the download tried once more.
 *
 * Each picture is downloaded once: it is kept in the app folder
 * (`<store>/media/telegram/<chat>/<id>-<size>`) and served from there.
 * Downloads go through the account's queue at `list` priority — after
 * what the user scrolls to, before anything read ahead (R-Y34). Videos,
 * voice notes and large files are never downloaded here.
 */

import { promises as fs } from 'node:fs';
import path from 'node:path';
import { importTelegram } from './telegram-layer.js';

// Pictures larger than this are not downloaded (a thumbnail is).
const MAX_BYTES = 2 * 1024 * 1024;
// Photo sizes, the largest first, for `size=x`; `m` prefers the medium.
const SIZE_ORDER = ['w', 'y', 'x', 'm', 's'];
const SIZES = new Set(['s', 'm', 'x', 'y', 'w']);

const CHAT = /^-?\d{1,20}$/;

const whole = (n, min, max = Infinity) =>
  Number.isInteger(n) && n >= min && n <= max;

const text = (value) =>
  value === null || value === undefined ? null : String(value.value ?? value);

// GramJS sizes its download parts by `fileSize.lesser(…)`: a plain
// number throws ("fileSize.lesser is not a function"), so every photo,
// sticker and file would fail.
export const bigSize = (helpers, size) =>
  helpers.returnBigInt(String(Math.max(0, Math.floor(Number(size) || 0))));

const bytesOf = (value) => {
  if (value instanceof Uint8Array) {
    return Buffer.from(value);
  }
  if (typeof value?.bytes === 'string') {
    return Buffer.from(value.bytes, 'base64');
  }
  return Buffer.alloc(0);
};

const sizeBytes = (s) =>
  Array.isArray(s?.sizes) ? Math.max(...s.sizes) : Number(s?.size ?? 0);

// Downloadable sizes (not the inline stripped one) and their type.
const realSizes = (sizes = []) =>
  sizes.filter(
    (s) =>
      s?.className === 'PhotoSize' || s?.className === 'PhotoSizeProgressive'
  );

/** The size type to download for `want` among `sizes`, or null. */
export const pickSize = (sizes, want = 'm') => {
  const real = realSizes(sizes).filter((s) => sizeBytes(s) <= MAX_BYTES);
  const has = (type) => real.some((s) => s.type === type);
  if (has(want)) {
    return want;
  }
  const from = SIZE_ORDER.indexOf(want);
  const order =
    from < 0
      ? SIZE_ORDER
      : [...SIZE_ORDER.slice(from + 1), ...SIZE_ORDER.slice(0, from).reverse()];
  return order.find(has) ?? real.at(-1)?.type ?? null;
};

const isSmallImage = (doc) =>
  /^image\/(jpeg|png|webp|gif)$/.test(doc?.mimeType ?? '') &&
  Number(doc?.size ?? Infinity) <= MAX_BYTES;

// A photo: of the message, or of its link preview.
const photoOf = (media) => {
  if (media?.className === 'MessageMediaPhoto') {
    return media.photo;
  }
  if (media?.className === 'MessageMediaGame') {
    return media.game?.photo;
  }
  return media?.className === 'MessageMediaWebPage'
    ? media.webpage?.photo
    : null;
};

export const documentPicture = (doc, want) => {
  if (isSmallImage(doc) && want !== 's') {
    return { kind: 'document', file: doc, thumb: '', mimeType: doc.mimeType };
  }
  const thumb = pickSize(doc.thumbs ?? [], want);
  return thumb
    ? { kind: 'document', file: doc, thumb, mimeType: 'image/jpeg' }
    : null;
};

/**
 * The media a message shows: its own, or for paid media (R-Y176) the
 * `part`th item once unlocked (a locked one has no file), else null.
 */
export const mediaOf = (raw, part = 0) => {
  // A service message's photo (a new group photo, a suggested profile
  // photo) is downloaded as a message's photo (R-Y221).
  const media =
    raw?.media ??
    (raw?.action?.photo
      ? { className: 'MessageMediaPhoto', photo: raw.action.photo }
      : undefined);
  if (media?.className !== 'MessageMediaPaidMedia') {
    return media;
  }
  const item = media.extendedMedia?.[part];
  return item?.className === 'MessageExtendedMedia' ? item.media : null;
};

// `photo:<id>` or `document:<id>`: a file of a rich message (R-Y220).
const RICH_FILE = /^(photo|document):(\d{1,20})$/;

const richPicture = (raw, rich, want) => {
  const [, kind, id] = RICH_FILE.exec(rich) ?? [];
  const list = kind === 'photo' ? raw?.richMessage?.photos : null;
  const file = (list ?? raw?.richMessage?.documents ?? []).find(
    (one) => text(one?.id) === id
  );
  if (!kind || !file) {
    return null;
  }
  if (kind === 'photo') {
    const thumb = pickSize(file.sizes ?? [], want);
    return thumb ? { kind, file, thumb, mimeType: 'image/jpeg' } : null;
  }
  return documentPicture(file, want);
};

/**
 * What to download for a stored message: `{ kind, file, thumb, mimeType }`
 * (`file` the photo or document as stored), or null when it has no picture.
 * `rich`: `photo:<id>` / `document:<id>`, a picture of its rich message.
 */
export const pictureOf = (raw, want = 'm', part = 0, rich = '') => {
  if (rich) {
    return richPicture(raw, rich, want);
  }
  const media = mediaOf(raw, part);
  const photo = photoOf(media);
  if (photo?.id !== undefined && photo.sizes) {
    const thumb = pickSize(photo.sizes, want);
    return thumb
      ? { kind: 'photo', file: photo, thumb, mimeType: 'image/jpeg' }
      : null;
  }
  const doc =
    media?.className === 'MessageMediaDocument' ? media.document : null;
  return doc?.id ? documentPicture(doc, want) : null;
};

export const locationOf = (Api, helpers, picture) => {
  const big = (value) => helpers.returnBigInt(text(value));
  const fields = {
    id: big(picture.file.id),
    accessHash: big(picture.file.accessHash),
    fileReference: bytesOf(picture.file.fileReference),
    thumbSize: picture.thumb,
  };
  return picture.kind === 'photo'
    ? new Api.InputPhotoFileLocation(fields)
    : new Api.InputDocumentFileLocation(fields);
};

const expired = (error) =>
  /FILE_REFERENCE_(EXPIRED|INVALID)/.test(
    String(error?.errorMessage ?? error?.message ?? '')
  );

export const readCache = async (file) => {
  try {
    const buffer = await fs.readFile(file);
    return buffer.length > 0 ? buffer : null;
  } catch {
    return null;
  }
};

/** `document:<id>`: a whole file of a rich message (R-Y224). */
export const RICH_DOCUMENT = /^document:\d{1,20}$/;

const validRequest = (chat, msg, part, rich) =>
  CHAT.test(chat) &&
  whole(msg, 1) &&
  whole(part, 0, 9) &&
  (!rich || RICH_FILE.test(rich));

/**
 * `read({ chat, id, size })` → `{ buffer, mimeType }`, or null when the
 * message has no picture. `client()` is the connected GramJS client (or
 * null), `peerOf(chat)` the stored input peer, `refresh(chat, ids)` reads
 * messages again into the store.
 */
export const createMediaReader = ({
  store,
  dir,
  queue,
  client: clientOf,
  refresh,
  importer = importTelegram,
  log = () => {},
}) => {
  const download = async (client, picture) => {
    const { Api, helpers } = await importer();
    const buffer = await client.downloadFile(
      locationOf(Api, helpers, picture),
      {
        dcId: Number(picture.file.dcId),
        fileSize: bigSize(helpers, MAX_BYTES),
      }
    );
    return buffer?.length ? Buffer.from(buffer) : null;
  };

  const fetchPicture = async (chat, id, want, part, rich) => {
    const linkId = `msg:telegram:${chat}:${id}`;
    const picture = pictureOf((await store.get(linkId))?.raw, want, part, rich);
    const client = picture ? await clientOf() : null;
    if (!client) {
      return null;
    }
    const key = `media:${chat}:${id}:${picture.thumb}${part ? `:p${part}` : ''}${rich ? `:${rich}` : ''}`;
    try {
      return {
        buffer: await queue.run(key, 'list', () => download(client, picture)),
        mimeType: picture.mimeType,
      };
    } catch (error) {
      if (!expired(error) || !refresh) {
        throw error;
      }
      // The file reference is old: read the message again, then retry.
      log({ event: 'telegram_media_reference_expired' });
      await refresh({ chat, ids: [id], priority: 'list' });
      const fresh = pictureOf((await store.get(linkId))?.raw, want, part, rich);
      return fresh
        ? {
            buffer: await queue.run(`${key}:again`, 'list', () =>
              download(client, fresh)
            ),
            mimeType: fresh.mimeType,
          }
        : null;
    }
  };

  const read = async ({ chat, id, size = 'm', part = 0, rich = '' } = {}) => {
    const target = String(chat ?? '');
    const msg = Number(id);
    const want = SIZES.has(size) ? size : 'm';
    // All name a path in the app folder: digits only. `part` is the item
    // of a paid-media message (R-Y176), `rich` a file of a rich message
    // (R-Y220).
    if (!validRequest(target, msg, part, rich)) {
      return null;
    }
    const tag = rich ? `-${rich.replace(':', '')}` : '';
    const file = path.join(
      dir,
      target,
      `${msg}-${want}${part ? `-p${part}` : ''}${tag}`
    );
    const cached = await readCache(file);
    if (cached) {
      const meta = await readCache(`${file}.type`);
      return { buffer: cached, mimeType: meta?.toString() || 'image/jpeg' };
    }
    const got = await fetchPicture(target, msg, want, part, rich);
    if (!got?.buffer) {
      return null;
    }
    await fs.mkdir(path.dirname(file), { recursive: true, mode: 0o700 });
    await fs.writeFile(file, got.buffer, { mode: 0o600 });
    await fs.writeFile(`${file}.type`, got.mimeType, { mode: 0o600 });
    return got;
  };

  return { read };
};

// Documents up to this size are downloaded and served.
const MAX_FILE_BYTES = 64 * 1024 * 1024;

// Document kind for the log (best-effort from mime and attributes).
export const docKind = (doc) => {
  const mime = doc?.mimeType ?? '';
  const attrs = doc?.attributes ?? [];
  if (attrs.some((a) => a?.className === 'DocumentAttributeAnimated')) {
    return 'gif';
  }
  if (
    attrs.some(
      (a) => a?.className === 'DocumentAttributeAudio' && a.voice === true
    )
  ) {
    return 'voice';
  }
  if (mime.startsWith('video/')) {
    return 'video';
  }
  if (mime.startsWith('audio/')) {
    return 'audio';
  }
  if (
    mime === 'application/x-tgsticker' ||
    (mime === 'image/webp' &&
      attrs.some((a) => a?.className === 'DocumentAttributeSticker'))
  ) {
    return 'sticker';
  }
  return 'file';
};

export const fileLocation = (Api, helpers, doc) => {
  const big = (value) => helpers.returnBigInt(text(value));
  return new Api.InputDocumentFileLocation({
    id: big(doc.id),
    accessHash: big(doc.accessHash),
    fileReference: bytesOf(doc.fileReference),
    thumbSize: '',
  });
};

/** A document's file name (its DocumentAttributeFilename), or ''. */
export const nameOf = (doc) =>
  (
    text((doc?.attributes ?? []).find((a) => a?.fileName)?.fileName) ?? ''
  ).slice(0, 255);

/**
 * `read({ chat, id, rich? })` → `{ buffer, mimeType, name }`, or null when
 * the message has no document (`rich`: `document:<id>` of its rich message,
 * R-Y224), or `{ error: 'too-large', size }` when the
 * file exceeds 64 MB. Concurrent requests for the same file share one
 * download. An expired file reference triggers one re-read and retry.
 */
export const createFileReader = ({
  store,
  dir,
  queue,
  client: clientOf,
  refresh,
  importer = importTelegram,
  log = () => {},
}) => {
  // Concurrent requests for the same chat:id share one download promise.
  const inFlight = new Map();

  const download = async (client, doc) => {
    const { Api, helpers } = await importer();
    const size = Number(doc.size ?? 0);
    const priority = size <= MAX_BYTES ? 'view' : 'list';
    const key = `file:${text(doc.id)}`;
    const buffer = await queue.run(key, priority, () =>
      client.downloadFile(fileLocation(Api, helpers, doc), {
        dcId: Number(doc.dcId),
        fileSize: bigSize(helpers, size),
      })
    );
    return buffer?.length ? Buffer.from(buffer) : null;
  };

  // The message's document, or the rich message's `document:<id>`
  // (R-Y224; learned, never copied).
  const getDoc = async (chat, id, rich = '') => {
    const link = await store.get(`msg:${SOURCE}:${chat}:${id}`);
    if (rich) {
      const want = rich.slice('document:'.length);
      return (
        (link?.raw?.richMessage?.documents ?? []).find(
          (one) => text(one?.id) === want
        ) ?? null
      );
    }
    const media = mediaOf(link?.raw);
    return media?.className === 'MessageMediaDocument' ? media.document : null;
  };

  const downloadWithRetry = async (client, chat, id, rich) => {
    const doc = await getDoc(chat, id, rich);
    if (!doc?.id) {
      return null;
    }
    try {
      return {
        buffer: await download(client, doc),
        mimeType: doc.mimeType,
        name: nameOf(doc),
      };
    } catch (error) {
      if (!expired(error) || !refresh) {
        throw error;
      }
      log({ event: 'telegram_file_reference_expired' });
      await refresh({ chat, ids: [id], priority: 'list' });
      const fresh = await getDoc(chat, id, rich);
      if (!fresh?.id) {
        return null;
      }
      return {
        buffer: await download(client, fresh),
        mimeType: fresh.mimeType,
        name: nameOf(fresh),
      };
    }
  };

  const fromDisk = async (file, buffer, doc, started) => {
    const typeBuf = await readCache(`${file}.type`);
    log({
      event: 'telegram_file',
      kind: docKind(doc),
      bytes: buffer.length,
      cached: true,
      duration_ms: Date.now() - started,
    });
    return {
      buffer,
      mimeType: typeBuf?.toString() || 'application/octet-stream',
      name: nameOf(doc),
    };
  };

  const read = async ({ chat, id, rich = '' } = {}) => {
    const target = String(chat ?? '');
    const msg = Number(id);
    if (
      !CHAT.test(target) ||
      !Number.isInteger(msg) ||
      msg <= 0 ||
      (rich && !RICH_DOCUMENT.test(rich))
    ) {
      return null;
    }
    // Digits only, so the name stays inside the media folder.
    const tag = rich ? `-${rich.replace(':', '')}` : '';
    const file = path.join(dir, target, `${msg}-file${tag}`);
    const opened = Date.now();
    const cachedBuf = await readCache(file);
    const doc = await getDoc(target, msg, rich);
    if (cachedBuf) {
      return fromDisk(file, cachedBuf, doc, opened);
    }
    // Check size before downloading.
    if (!doc?.id) {
      return null;
    }
    const size = Number(doc.size ?? 0);
    return size > MAX_FILE_BYTES
      ? { error: 'too-large', size }
      : fetchFile(file, { target, msg, rich, doc });
  };

  const fetchFile = async (file, { target, msg, rich, doc }) => {
    const flightKey = `${target}:${msg}:${rich}`;
    if (inFlight.has(flightKey)) {
      return inFlight.get(flightKey);
    }
    const started = Date.now();
    const client = await clientOf();
    if (!client) {
      return null;
    }
    const kind = docKind(doc);
    const p = downloadWithRetry(client, target, msg, rich)
      .then(async (got) => {
        if (!got?.buffer) {
          return null;
        }
        await fs.mkdir(path.dirname(file), { recursive: true, mode: 0o700 });
        await fs.writeFile(file, got.buffer, { mode: 0o600 });
        await fs.writeFile(`${file}.type`, got.mimeType ?? '', { mode: 0o600 });
        log({
          event: 'telegram_file',
          kind,
          bytes: got.buffer.length,
          cached: false,
          duration_ms: Date.now() - started,
        });
        return got;
      })
      .catch((error) => {
        log({
          level: 'warn',
          event: 'telegram_file_failed',
          error: error.errorMessage ?? error.message,
        });
        return null;
      })
      .finally(() => inFlight.delete(flightKey));
    inFlight.set(flightKey, p);
    return p;
  };

  return { read };
};

// SOURCE used in store key lookups inside this module.
const SOURCE = 'telegram';

/**
 * A group's members, as Telegram Desktop lists them in the info column
 * (R-Y125; learned, never copied):
 * - `chatMembers({ chat, q, offset, limit })` — a supergroup's page
 *   (channels.getParticipants, the recent ones, or a search by `q`), a
 *   basic group's (messages.getFullChat) → `{ ok, total, members: [{ id,
 *   name, username, role, rank, self }], canBan, canInvite }`; `role` is
 *   creator, admin, member, restricted or banned;
 * - `removeMember({ chat, user })` — "Remove from group": the user banned
 *   and at once unbanned in a supergroup (so they may come back), a basic
 *   group's member deleted (messages.deleteChatUser).
 * Telegram's errors become codes the page shows as text.
 */

import { runIn, connected, failureOf } from './telegram-stickers.js';

const CODES = {
  CHAT_ADMIN_REQUIRED: 'not-admin',
  USER_ADMIN_INVALID: 'user-admin',
  USER_NOT_PARTICIPANT: 'not-member',
  PARTICIPANT_ID_INVALID: 'not-member',
  CHANNEL_PRIVATE: 'no-access',
  CHAT_ID_INVALID: 'no-access',
};

const failure = failureOf(CODES);

const CHAT = /^-\d{1,20}$/;
const USER = /^\d{1,20}$/;
const textOf = (value) => String(value?.value ?? value);
const isChannel = (chat) => chat.startsWith('-100');

const nameOf = (user) =>
  [user?.firstName, user?.lastName].filter(Boolean).join(' ') ||
  user?.username ||
  '';

const ROLES = {
  ChannelParticipantCreator: 'creator',
  ChatParticipantCreator: 'creator',
  ChannelParticipantAdmin: 'admin',
  ChatParticipantAdmin: 'admin',
  ChannelParticipantBanned: 'restricted',
};

const roleOf = (participant) => {
  const role = ROLES[participant.className] ?? 'member';
  return role === 'restricted' && participant.bannedRights?.viewMessages
    ? 'banned'
    : role;
};

// The user a participant is: a banned one names a peer, the rest a user id.
const userIdOf = (participant) =>
  participant.userId === undefined && participant.peer?.userId === undefined
    ? ''
    : textOf(participant.userId ?? participant.peer.userId);

const memberOf = (participant, users) => {
  const id = userIdOf(participant);
  const user = users.get(id);
  return {
    id,
    name: nameOf(user) || id,
    username: user?.username ?? null,
    role: roleOf(participant),
    rank: participant.rank ?? null,
    self: Boolean(user?.self),
  };
};

// The user may remove people: the creator, or an admin allowed to ban.
const canBanIn = (entity = {}) =>
  Boolean(entity.creator || entity.adminRights?.banUsers);
const canInviteIn = (entity = {}) =>
  Boolean(entity.creator || entity.adminRights?.inviteUsers);

const shape = (answer, participants, total, offset = 0) => {
  const users = new Map((answer?.users ?? []).map((u) => [textOf(u.id), u]));
  const entity = (answer?.chats ?? []).find(Boolean) ?? {};
  return {
    ok: true,
    total,
    offset,
    members: participants
      .map((p) => memberOf(p, users))
      .filter((m) => m.id !== ''),
    canBan: canBanIn(entity),
    canInvite: canInviteIn(entity),
    // R-Y200: delete all from a member, transfer ownership.
    canDelete: Boolean(entity.creator || entity.adminRights?.deleteMessages),
    owner: Boolean(entity.creator),
  };
};

const readChannel = async (c, env, { chat, q, offset, limit }) => {
  const filter = q
    ? new c.Api.ChannelParticipantsSearch({ q })
    : new c.Api.ChannelParticipantsRecent();
  const answer = await runIn(env, `members:${chat}:${q}:${offset}`, () =>
    env.connection.withPeer(c.client, chat, (peer) =>
      c.client.invoke(
        new c.Api.channels.GetParticipants({
          channel: peer,
          filter,
          offset,
          limit,
          hash: c.zero,
        })
      )
    )
  );
  const found = answer?.participants ?? [];
  return shape(answer, found, Number(answer?.count ?? found.length), offset);
};

const readGroup = async (c, env, { chat, q, offset, limit }) => {
  const answer = await runIn(env, `members:${chat}`, () =>
    c.client.invoke(
      new c.Api.messages.GetFullChat({
        chatId: c.helpers.returnBigInt(chat.slice(1)),
      })
    )
  );
  const all = answer?.fullChat?.participants?.participants ?? [];
  const whole = shape(answer, all, all.length);
  const words = q.toLowerCase();
  const kept = whole.members.filter(
    (m) =>
      !words ||
      m.name.toLowerCase().includes(words) ||
      (m.username ?? '').toLowerCase().includes(words)
  );
  return { ...whole, offset, members: kept.slice(offset, offset + limit) };
};

const createReader =
  (env, userClient) =>
  async (request = {}) => {
    const chat = String(request.chat ?? '');
    if (!CHAT.test(chat)) {
      return { ok: false, error: 'bad chat', code: 'failed' };
    }
    const q = typeof request.q === 'string' ? request.q.trim() : '';
    const offset = Math.max(0, Math.floor(Number(request.offset) || 0));
    const limit = Math.min(200, Math.max(1, Number(request.limit) || 50));
    return connected(env, userClient, failure, async (c) => {
      const ask = isChannel(chat) ? readChannel : readGroup;
      return await ask(c, env, { chat, q, offset, limit });
    });
  };

// The person as an input peer, from what GramJS knows, else by id alone.
export const inputPeerOf = async (c, user) => {
  const id = c.helpers.returnBigInt(user);
  const known = await Promise.resolve()
    .then(() => c.client.getInputEntity?.(id))
    .catch(() => null);
  return (
    known ??
    new c.Api.InputPeerUser({
      userId: id,
      accessHash: c.helpers.returnBigInt(0),
    })
  );
};

const rights = (c, on) =>
  new c.Api.ChatBannedRights({
    ...(on ? { viewMessages: true } : {}),
    untilDate: 0,
  });

// Banned and at once let go: out of the group, free to come back.
const removeFromChannel = async (c, peer, participant) => {
  for (const on of [true, false]) {
    await c.client.invoke(
      new c.Api.channels.EditBanned({
        channel: peer,
        participant,
        bannedRights: rights(c, on),
      })
    );
  }
};

const removeFromGroup = (c, chat, participant) =>
  c.client.invoke(
    new c.Api.messages.DeleteChatUser({
      chatId: c.helpers.returnBigInt(chat.slice(1)),
      userId: new c.Api.InputUser({
        userId: participant.userId,
        accessHash: participant.accessHash ?? c.helpers.returnBigInt(0),
      }),
    })
  );

const createRemover =
  (env, userClient) =>
  async (request = {}) => {
    const chat = String(request.chat ?? '');
    const user = String(request.user ?? '');
    if (!CHAT.test(chat) || !USER.test(user)) {
      return { ok: false, error: 'bad request', code: 'failed' };
    }
    return connected(env, userClient, failure, async (c) => {
      const participant = await inputPeerOf(c, user);
      await runIn(env, `member-remove:${chat}:${user}`, () =>
        isChannel(chat)
          ? env.connection.withPeer(c.client, chat, (peer) =>
              removeFromChannel(c, peer, participant)
            )
          : removeFromGroup(c, chat, participant)
      );
      return { ok: true };
    });
  };

export const createMembers = (env, context) => ({
  chatMembers: createReader(env, context.userClient),
  removeMember: createRemover(env, context.userClient),
});

/**
 * Links to messages, as Telegram Desktop has them (R-Y154; learned, never
 * copied):
 *
 * - `messageLink({ chat, id, thread })` — "Copy link" of a message in a
 *   supergroup or channel (channels.exportMessageLink); `thread` asks for
 *   the link of a message inside a topic or a comment thread →
 *   `{ ok, link }`;
 * - `resolveLink({ username })` — the chat a t.me/username/123 link names
 *   (contacts.resolveUsername) → `{ ok, chat, name, username, kind }` with
 *   `chat` the marked id (-100…); a username of a person or a bot is code
 *   `not-chat`, an unknown one `no-chat`.
 * Telegram's errors become codes the page reads.
 */

import { runIn, connected, failureOf } from './telegram-stickers.js';

export const CHANNEL_CHAT = /^-100\d{1,15}$/;
export const LINK_USERNAME = /^[A-Za-z][A-Za-z0-9_]{3,31}$/;
export const MAX_MESSAGE_ID = 2_147_483_647;

const CODES = {
  USERNAME_NOT_OCCUPIED: 'no-chat',
  USERNAME_INVALID: 'no-chat',
  CHANNEL_PRIVATE: 'no-access',
  CHANNEL_INVALID: 'no-access',
  PEER_ID_INVALID: 'no-access',
  MESSAGE_ID_INVALID: 'no-message',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);
const BAD = { ok: false, error: 'bad request', code: 'failed' };

/** Whether `id` is a message id Telegram numbers (a positive 32-bit). */
export const validMessageId = (id) =>
  Number.isInteger(id) && id > 0 && id <= MAX_MESSAGE_ID;

const text = (value) => String(value?.value ?? value ?? '');

const hasName = (chat, lower) =>
  String(chat.username ?? '').toLowerCase() === lower ||
  (chat.usernames ?? []).some(
    (u) => String(u.username ?? '').toLowerCase() === lower
  );

// The chat a resolved username stands for, from the chats of the answer.
const chatOf = (answer, username) => {
  const lower = username.toLowerCase();
  const found = (answer?.chats ?? []).find(
    (c) => c?.className === 'Channel' && hasName(c, lower)
  );
  return found
    ? {
        ok: true,
        chat: `-100${text(found.id)}`,
        name: found.title ?? '',
        username,
        kind: found.broadcast ? 'channel' : 'group',
      }
    : { ok: false, error: 'not a chat', code: 'not-chat' };
};

export const createMessageLinks = (env, { userClient }) => ({
  messageLink: async ({ chat, id, thread = false } = {}) => {
    if (
      !CHANNEL_CHAT.test(String(chat ?? '')) ||
      !validMessageId(id) ||
      typeof thread !== 'boolean'
    ) {
      return BAD;
    }
    return connected(env, userClient, failure, (c) =>
      runIn(env, `message-link:${chat}`, () =>
        env.connection.withPeer(c.client, String(chat), async (peer) => {
          const answer = await c.client.invoke(
            new c.Api.channels.ExportMessageLink({
              channel: peer,
              id,
              ...(thread ? { thread: true } : {}),
            })
          );
          return answer?.link
            ? { ok: true, link: String(answer.link) }
            : { ok: false, error: 'no link', code: 'failed' };
        })
      )
    );
  },
  resolveLink: async ({ username } = {}) => {
    const name = String(username ?? '');
    if (!LINK_USERNAME.test(name)) {
      return BAD;
    }
    return connected(env, userClient, failure, (c) =>
      runIn(env, `resolve-link:${name.toLowerCase()}`, async () =>
        chatOf(
          await c.client.invoke(
            new c.Api.contacts.ResolveUsername({ username: name })
          ),
          name
        )
      )
    );
  },
});

/**
 * Moderating a supergroup's members, as Telegram
 * Desktop's admin dialogs do (R-Y200; learned, never copied):
 * - `moderateUser({ chat, user, ids?, reportSpam?, ban?, deleteAll? })` —
 *   what the delete dialog's checkboxes ask: "Report spam" for the
 *   message ids (channels.reportSpam, first, while they still exist),
 *   "Ban user" (channels.editBanned, view messages off for good) and
 *   "Delete all from <name>" (channels.deleteParticipantHistory, asked
 *   again while Telegram's AffectedHistory says an `offset` is left) →
 *   `{ ok, deleted }`; supergroups only;
 * - `notSpam({ chat, msgId })` — "Not spam" for a message anti-spam
 *   deleted (channels.reportAntiSpamFalsePositive);
 * Telegram's errors become codes the page shows as text.
 */

import { inputPeerOf } from './telegram-members.js';
import { connected, failureOf, runIn } from './telegram-stickers.js';

const CODES = {
  CHAT_ADMIN_REQUIRED: 'not-admin',
  USER_ADMIN_INVALID: 'user-admin',
  USER_NOT_PARTICIPANT: 'not-member',
  PARTICIPANT_ID_INVALID: 'not-member',
  MESSAGE_ID_INVALID: 'no-message',
  CHANNEL_PRIVATE: 'no-access',
  CHANNEL_INVALID: 'no-access',
  USER_ID_INVALID: 'not-member',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);
const bad = () => ({ ok: false, error: 'bad-request', code: 'bad-request' });

const CHANNEL = /^-100\d{1,20}$/;
const USER = /^\d{1,20}$/;
const MSG = /^\d{1,12}$/;
const MAX_ROUNDS = 50;
const MAX_IDS = 100;

const idsOk = (value) =>
  Array.isArray(value) &&
  value.length > 0 &&
  value.length <= MAX_IDS &&
  value.every((id) => Number.isInteger(id) && id > 0);

/** Whether `body` is a valid moderateUser request. */
export const moderationBody = (body = {}) =>
  CHANNEL.test(String(body.chat ?? '')) &&
  USER.test(String(body.user ?? '')) &&
  ['reportSpam', 'ban', 'deleteAll'].every(
    (k) => body[k] === undefined || typeof body[k] === 'boolean'
  ) &&
  (body.ids === undefined || idsOk(body.ids)) &&
  // Reporting needs the messages; at least one thing must be asked.
  (!body.reportSpam || body.ids !== undefined) &&
  Boolean(body.reportSpam || body.ban || body.deleteAll);

// Asked again while Telegram says more is left of the person's messages.
const clearHistory = async (env, c, chat, participant) => {
  for (let round = 0; round < MAX_ROUNDS; round += 1) {
    const answer = await runIn(env, `moderate:all:${chat}:${round}`, () =>
      env.connection.withPeer(c.client, chat, (peer) =>
        c.client.invoke(
          new c.Api.channels.DeleteParticipantHistory({
            channel: peer,
            participant,
          })
        )
      )
    );
    if (!Number(answer?.offset)) {
      return;
    }
  }
};

const createModerate =
  (env, userClient) =>
  async (body = {}) => {
    if (!moderationBody(body)) {
      return bad();
    }
    const chat = String(body.chat);
    return connected(env, userClient, failure, async (c) => {
      const participant = await inputPeerOf(c, String(body.user));
      const through = (key, make) =>
        runIn(env, `moderate:${key}:${chat}:${body.user}`, () =>
          env.connection.withPeer(c.client, chat, (peer) =>
            c.client.invoke(make(peer))
          )
        );
      // The report first: it needs the messages to still be there.
      if (body.reportSpam) {
        await through(
          'spam',
          (channel) =>
            new c.Api.channels.ReportSpam({
              channel,
              participant,
              id: body.ids,
            })
        );
      }
      if (body.ban) {
        await through(
          'ban',
          (channel) =>
            new c.Api.channels.EditBanned({
              channel,
              participant,
              bannedRights: new c.Api.ChatBannedRights({
                viewMessages: true,
                untilDate: 0,
              }),
            })
        );
      }
      if (body.deleteAll) {
        await clearHistory(env, c, chat, participant);
      }
      return { ok: true, deleted: Boolean(body.deleteAll) };
    });
  };

const createNotSpam =
  (env, userClient) =>
  async (body = {}) => {
    const chat = String(body.chat ?? '');
    const msgId = String(body.msgId ?? '');
    if (!CHANNEL.test(chat) || !MSG.test(msgId)) {
      return bad();
    }
    return connected(env, userClient, failure, async (c) => {
      await runIn(env, `antispam:${chat}:${msgId}`, () =>
        env.connection.withPeer(c.client, chat, (peer) =>
          c.client.invoke(
            new c.Api.channels.ReportAntiSpamFalsePositive({
              channel: peer,
              msgId: Number(msgId),
            })
          )
        )
      );
      return { ok: true };
    });
  };

export const createModeration = (env, context) => ({
  moderateUser: createModerate(env, context.userClient),
  notSpam: createNotSpam(env, context.userClient),
});

/**
 * Telegram **user-account** auth over MTProto, the way konard/telegram-bot
 * does it: a GramJS `TelegramClient` built from an `api_id` / `api_hash`
 * and a `StringSession`, signed in with `client.start({ phoneNumber,
 * phoneCode, password })`, then `client.session.save()` is the reusable
 * session string (that project writes it to `.telegram_session`).
 *
 * GramJS (the `telegram` package) is a heavy, optional dependency, loaded
 * lazily so the rest of the server never needs it. The client itself is
 * injected (`clientFactory`) so the login state machine is unit-tested
 * with a fake and the real GramJS lives only in `gramjsClientFactory`.
 *
 * Two entry points:
 *   identify({apiId,apiHash,session})  connect with an existing session,
 *                                      read the account (getMe), disconnect.
 *   createLogin({apiId,apiHash,phone}) drive the interactive sign-in across
 *                                      HTTP requests: start → code → (2FA)
 *                                      password → a saved session string.
 *   createQrLogin({apiId,apiHash})     the same by QR code (R-Y203), see
 *                                      ./telegram-qr-login.js.
 */

import { importTelegram } from './telegram-layer.js';
import { proxyOptions } from './telegram-proxy.js';
import { startQrLogin } from './telegram-qr-login.js';

const deferred = () => {
  let resolve;
  let reject;
  const promise = new Promise((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
};

// GramJS returns the id as a BigInt (or a big-integer object) and camelCase
// names; normalize the id to a plain string so it survives JSON.stringify
// (a raw BigInt throws "Do not know how to serialize a BigInt").
const idOf = (me) => {
  const raw = me?.id ?? null;
  return raw === null ? null : String(raw.value ?? raw);
};

export const accountOf = (me = {}) => ({
  id: idOf(me),
  username: me.username ?? null,
  firstName: me.firstName ?? me.first_name ?? null,
  lastName: me.lastName ?? me.last_name ?? null,
  phone: me.phone ?? null,
});

// `{ proxy }` for GramJS when a proxy is set, else nothing (direct).
const proxyParams = (setting) => {
  const proxy = proxyOptions(setting);
  return proxy ? { proxy } : {};
};

// Build the real GramJS client. Imported lazily; absent in environments
// that never do user-account auth.
// `proxy()` (optional) answers the saved connection proxy setting when a
// client is built (R-Y192), so a changed proxy is used by the next one.
export const gramjsClientFactory =
  (importer = importTelegram, { proxy = async () => null } = {}) =>
  async ({ apiId, apiHash, session }) => {
    const telegram = await importer();
    const { TelegramClient } = telegram;
    const { StringSession } = telegram.sessions;
    const client = new TelegramClient(
      new StringSession(session ?? ''),
      Number(apiId),
      String(apiHash),
      // Every "wait N seconds" reaches the account's queue, which holds
      // all requests that long (GramJS would otherwise sleep through
      // waits under a minute and retry at once, unseen).
      {
        connectionRetries: 5,
        floodSleepThreshold: 0,
        ...proxyParams(await proxy()),
      }
    );
    return client;
  };

export const createTelegramMtproto = ({
  // (opts) -> a GramJS-like client ({ start, connect, disconnect, getMe,
  // session: { save() } }). Defaults to the real GramJS client.
  clientFactory = gramjsClientFactory(),
  now = () => Date.now(),
  // The GramJS `Api` namespace (the QR sign-in builds requests with it).
  loadApi = async () => (await importTelegram()).Api,
} = {}) => {
  // Connect with an existing session string and read the account. Used by
  // the credential finder to resolve a discovered `.telegram_session` to
  // its real @username instead of grouping it only by phone.
  const identify = async ({ apiId, apiHash, session }) => {
    const client = await clientFactory({ apiId, apiHash, session });
    await client.connect();
    try {
      return accountOf(await client.getMe());
    } finally {
      await client.disconnect?.();
    }
  };

  // The interactive sign-in, bridged across separate HTTP requests: the
  // GramJS `start()` callbacks await deferreds that later requests resolve.
  const createLogin = async ({ apiId, apiHash, phone }) => {
    const client = await clientFactory({ apiId, apiHash, session: '' });
    const code = deferred();
    const password = deferred();
    const ctrl = {
      state: 'starting',
      error: null,
      account: null,
      session: null,
    };
    driveLogin({ client, ctrl, code, password, phone });
    return loginController({
      client,
      ctrl,
      code,
      password,
      settle: settleFor(ctrl, now),
    });
  };

  // The sign-in by QR code (R-Y203): same controller shape as createLogin's.
  const createQrLogin = async ({ apiId, apiHash }) =>
    startQrLogin({
      client: await clientFactory({ apiId, apiHash, session: '' }),
      apiId,
      apiHash,
      Api: await loadApi(),
      accountOf,
      now,
    });

  return { identify, createLogin, createQrLogin };
};

// Wait until the login flow leaves `want` (asks for the next thing,
// finishes, or fails). The GramJS callbacks flip `ctrl.state`.
const settleFor = (ctrl, now) => async (want) => {
  const deadline = now() + 60000;
  while (ctrl.state === want && now() < deadline && !ctrl.error) {
    await new Promise((r) => globalThis.setTimeout(r, 25));
  }
  if (ctrl.error) {
    throw ctrl.error;
  }
  return ctrl.state;
};

// Kick off GramJS `start()`; its callbacks resolve from the deferreds and
// flip `ctrl.state` so the HTTP layer knows what to ask for next.
const driveLogin = ({ client, ctrl, code, password, phone }) => {
  client
    .start({
      phoneNumber: async () => phone,
      phoneCode: async () => {
        ctrl.state = 'code';
        return code.promise;
      },
      password: async () => {
        ctrl.state = 'password';
        return password.promise;
      },
      onError: (error) => {
        ctrl.error = error;
      },
    })
    .then(async () => {
      ctrl.session = client.session.save();
      ctrl.account = accountOf(await client.getMe());
      ctrl.state = 'done';
    })
    .catch((error) => {
      ctrl.error = ctrl.error ?? error;
      ctrl.state = 'error';
    });
};

const loginController = ({ client, ctrl, code, password, settle }) => ({
  get state() {
    return ctrl.state;
  },
  get account() {
    return ctrl.account;
  },
  get session() {
    return ctrl.session;
  },
  // Telegram has sent the code; the client is now waiting for it.
  async ready() {
    return settle('starting');
  },
  async submitCode(value) {
    code.resolve(String(value));
    return settle('code');
  },
  async submitPassword(value) {
    password.resolve(String(value));
    return settle('password');
  },
  async cancel() {
    code.reject?.(new Error('cancelled'));
    password.reject?.(new Error('cancelled'));
    await client.disconnect?.();
  },
});

/**
 * Reaction notifications, resetting the notification settings and
 * Telegram's own automatic-download preset (R-Y215; learned, never
 * copied):
 *
 * - `reactionNotifyGet()` — account.getReactionsNotifySettings → `{ ok,
 *   messages, stories, previews, sound }`: who the account is told of
 *   reactions to its messages and stories from ('nobody', 'contacts' or
 *   'all'), whether the notification shows a preview and whether it has a
 *   sound;
 * - `reactionNotifySet({ messages?, stories?, previews?, sound? })` —
 *   account.setReactionsNotifySettings with the rest kept as it was (the
 *   poll votes setting, a chosen ringtone) → the same row;
 * - `notifyResetAll()` — account.resetNotifySettings: every notification
 *   setting back to Telegram's default;
 * - `autoDownloadPreset()` — account.getAutoDownloadSettings → `{ ok,
 *   medium: { disabled, photoMax, videoMax, fileMax } }` (bytes), the
 *   preset the page maps to its own settings.
 * Telegram's errors become codes the page shows as text.
 */

import { connected, runIn, failureOf } from './telegram-stickers.js';

const failure = failureOf({ FLOOD_WAIT: 'flood' });
const BAD = { ok: false, error: 'bad request', code: 'bad-request' };

export const FROM = Object.freeze(['nobody', 'contacts', 'all']);
const FROM_CLASS = {
  contacts: 'ReactionNotificationsFromContacts',
  all: 'ReactionNotificationsFromAll',
};

/** 'nobody', 'contacts' or 'all' from Telegram's ReactionNotificationsFrom. */
export const fromOf = (value) => {
  if (value?.className === FROM_CLASS.contacts) {
    return 'contacts';
  }
  return value?.className === FROM_CLASS.all ? 'all' : 'nobody';
};

/** The page's row from Telegram's ReactionsNotifySettings. */
export const reactionRowOf = (settings = {}) => ({
  messages: fromOf(settings.messagesNotifyFrom),
  stories: fromOf(settings.storiesNotifyFrom),
  previews: settings.showPreviews !== false,
  sound: settings.sound?.className !== 'NotificationSoundNone',
});

export const validReactionChange = (b = {}) =>
  (b.messages === undefined || FROM.includes(b.messages)) &&
  (b.stories === undefined || FROM.includes(b.stories)) &&
  (b.previews === undefined || typeof b.previews === 'boolean') &&
  (b.sound === undefined || typeof b.sound === 'boolean') &&
  (b.messages !== undefined ||
    b.stories !== undefined ||
    b.previews !== undefined ||
    b.sound !== undefined);

const fromInput = (c, value, kept) => {
  if (value === undefined) {
    return kept;
  }
  return value === 'nobody' ? undefined : new c.Api[FROM_CLASS[value]]();
};

// The settings to write: what Telegram has, with the page's changes.
const reactionFields = (c, current, body) => {
  const fields = {
    showPreviews: body.previews ?? current.showPreviews !== false,
    sound: current.sound ?? new c.Api.NotificationSoundDefault(),
  };
  if (body.sound !== undefined) {
    fields.sound = body.sound
      ? new c.Api.NotificationSoundDefault()
      : new c.Api.NotificationSoundNone();
  }
  const entries = {
    messagesNotifyFrom: fromInput(c, body.messages, current.messagesNotifyFrom),
    storiesNotifyFrom: fromInput(c, body.stories, current.storiesNotifyFrom),
    pollVotesNotifyFrom: current.pollVotesNotifyFrom,
  };
  for (const [key, value] of Object.entries(entries)) {
    if (value) {
      fields[key] = value;
    }
  }
  return fields;
};

const sizeOf = (value) => Number(value?.value ?? value ?? 0) || 0;

/** The page's view of Telegram's AutoDownloadSettings (sizes in bytes). */
export const presetOf = (settings = {}) => ({
  disabled: settings.disabled === true,
  photoMax: sizeOf(settings.photoSizeMax),
  videoMax: sizeOf(settings.videoSizeMax),
  fileMax: sizeOf(settings.fileSizeMax),
});

export const createNotifyExtras = (env, { userClient }) => ({
  reactionNotifyGet: async () =>
    connected(env, userClient, failure, (c) =>
      runIn(env, 'reaction-notify', async () => ({
        ok: true,
        ...reactionRowOf(
          await c.client.invoke(new c.Api.account.GetReactionsNotifySettings())
        ),
      }))
    ),
  reactionNotifySet: async (body = {}) =>
    validReactionChange(body)
      ? connected(env, userClient, failure, (c) =>
          runIn(env, 'reaction-notify', async () => {
            const current =
              (await c.client.invoke(
                new c.Api.account.GetReactionsNotifySettings()
              )) ?? {};
            const fields = reactionFields(c, current, body);
            await c.client.invoke(
              new c.Api.account.SetReactionsNotifySettings({
                settings: new c.Api.ReactionsNotifySettings(fields),
              })
            );
            return { ok: true, ...reactionRowOf(fields) };
          })
        )
      : BAD,
  notifyResetAll: async () =>
    connected(env, userClient, failure, (c) =>
      runIn(env, 'notify-reset', async () => {
        await c.client.invoke(new c.Api.account.ResetNotifySettings());
        return { ok: true };
      })
    ),
  autoDownloadPreset: async () =>
    connected(env, userClient, failure, (c) =>
      runIn(env, 'auto-download-preset', async () => {
        const all = await c.client.invoke(
          new c.Api.account.GetAutoDownloadSettings()
        );
        return { ok: true, medium: presetOf(all?.medium) };
      })
    ),
});

/**
 * Notification settings, as Telegram Desktop's Settings → Notifications
 * and a chat's "Notifications" have them (R-Y157; learned, never copied):
 *
 * - `notifyOverview()` — the account's global settings for private chats,
 *   groups and channels (account.getNotifySettings with InputNotifyUsers,
 *   InputNotifyChats, InputNotifyBroadcasts) and the chats that differ
 *   (account.getNotifyExceptions, sounds not compared) → `{ ok, scopes:
 *   { users | chats | broadcasts: { on, previews, stories } }, exceptions:
 *   [{ chat, name, scope, state: 'muted' | 'unmuted' | 'custom',
 *   muteUntil, forever, previews }] }`;
 * - `notifyScopeSet({ scope, on, previews, stories })` — one change to a
 *   scope (account.updateNotifySettings; off is muted for good, on is
 *   muteUntil 0), the rest of its settings kept → `{ ok, scope, ...row }`;
 * - `notifyChat({ chat })` — one chat's own settings (getNotifySettings
 *   with InputNotifyPeer) → `{ ok, chat, exception, muteUntil, forever,
 *   previews, stories }`;
 * - `notifyChatSet({ chat, mute, previews, reset })` — a chat's own: `mute`
 *   'off', 'forever' or seconds; `previews` 'default', 'on' or 'off';
 *   `reset` sends empty settings so the chat follows the global ones.
 * A chat's sound (R-Y181): `notifyChat` answers `sound` — 'default', 'none'
 * or a saved ringtone's id — and `notifyChatSet({ sound })` sets it
 * (NotificationSoundDefault is no sound field, NotificationSoundNone,
 * NotificationSoundRingtone); exceptions carry it too.
 * Layer 225 has no per-chat flag for pinned messages or for mentions, so
 * neither is offered; stories are muted by `storiesMuted`.
 * Telegram's errors become codes the page shows as text.
 */

import { connected, runIn, failureOf } from './telegram-stickers.js';
import { MUTE_FOREVER, muteUntilOf, peerOfChat } from './telegram-dialogs.js';

const CODES = {
  PEER_ID_INVALID: 'no-access',
  CHANNEL_PRIVATE: 'no-access',
  CHAT_ID_INVALID: 'no-access',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);
const CHAT = /^-?\d{1,20}$/;

export const SCOPES = Object.freeze(['users', 'chats', 'broadcasts']);
const INPUT = {
  users: 'InputNotifyUsers',
  chats: 'InputNotifyChats',
  broadcasts: 'InputNotifyBroadcasts',
};
const BAD = { ok: false, error: 'bad request', code: 'failed' };
// Longer than this left is "for good" in a list.
const FOREVER_MS = 5 * 365 * 24 * 3600 * 1000;

const bool = (v) => (typeof v === 'boolean' ? v : undefined);
const text = (value) => String(value?.value ?? value ?? '');

/** A scope's row for the page, from Telegram's PeerNotifySettings. */
export const rowOf = (settings = {}, nowMs = Date.now()) => ({
  on: !(Number(settings.muteUntil ?? 0) * 1000 > nowMs),
  previews: settings.showPreviews !== false,
  stories: settings.storiesMuted !== true,
});

// The fields of what Telegram has, as an input to write back with
// changes: everything kept that the page does not touch.
const keptFields = (settings = {}) => {
  const fields = {};
  for (const key of ['showPreviews', 'silent', 'storiesMuted']) {
    if (bool(settings[key]) !== undefined) {
      fields[key] = settings[key];
    }
  }
  if (bool(settings.storiesHideSender) !== undefined) {
    fields.storiesHideSender = settings.storiesHideSender;
  }
  if (settings.muteUntil !== undefined) {
    fields.muteUntil = Number(settings.muteUntil);
  }
  if (settings.otherSound) {
    fields.sound = settings.otherSound;
  }
  return fields;
};

/** A NotificationSound as 'default', 'none' or a ringtone's id. */
export const soundText = (sound) => {
  if (sound?.className === 'NotificationSoundNone') {
    return 'none';
  }
  return sound?.className === 'NotificationSoundRingtone'
    ? text(sound.id)
    : 'default';
};

const SOUND = /^(default|none|\d{1,20})$/;

const without = (fields, key) =>
  Object.fromEntries(Object.entries(fields).filter(([k]) => k !== key));

// Who an exception is about: a marked chat id.
const idOf = (peer = {}) => {
  if (peer.userId !== undefined) {
    return text(peer.userId);
  }
  if (peer.chatId !== undefined) {
    return `-${text(peer.chatId)}`;
  }
  return peer.channelId === undefined ? null : `-100${text(peer.channelId)}`;
};

const entityName = (e = {}) =>
  e.title ??
  ([e.firstName, e.lastName].filter(Boolean).join(' ') ||
    e.username ||
    text(e.id));

const entityOf = (result, peer) => {
  const key = text(peer.userId ?? peer.chatId ?? peer.channelId);
  const list = peer.userId === undefined ? result.chats : result.users;
  return (list ?? []).find((e) => text(e.id) === key) ?? {};
};

const scopeOfPeer = (peer, entity) => {
  if (peer.userId !== undefined) {
    return 'users';
  }
  return peer.channelId !== undefined && entity.broadcast
    ? 'broadcasts'
    : 'chats';
};

/** One exception from Telegram's UpdateNotifySettings, or null. */
export const exceptionOf = (result, update, nowMs = Date.now()) => {
  const peer = update.peer?.peer;
  const chat = peer ? idOf(peer) : null;
  if (update.peer?.className !== 'NotifyPeer' || !chat) {
    return null;
  }
  const settings = update.notifySettings ?? {};
  const entity = entityOf(result, peer);
  const until = Number(settings.muteUntil ?? 0);
  let state = 'custom';
  if (settings.muteUntil !== undefined) {
    state = until * 1000 > nowMs ? 'muted' : 'unmuted';
  }
  return {
    chat,
    name: entityName(entity),
    scope: scopeOfPeer(peer, entity),
    state,
    muteUntil: state === 'muted' ? until : 0,
    forever: state === 'muted' && until * 1000 - nowMs > FOREVER_MS,
    previews: bool(settings.showPreviews) ?? null,
    sound: soundText(settings.otherSound),
  };
};

const muteOf = (mute, nowMs) => {
  if (mute === 'off') {
    return 0;
  }
  return mute === 'forever' ? MUTE_FOREVER : muteUntilOf(mute, nowMs);
};

/** A chat's change over what it has: the fields to write. */
export const chatFields = (current, body, nowMs, makeSound) => {
  const { mute, previews, sound } = body;
  let fields = keptFields(current);
  if (sound === 'default') {
    fields = without(fields, 'sound');
  } else if (sound !== undefined && makeSound) {
    fields = { ...fields, sound: makeSound(sound) };
  }
  if (mute !== undefined) {
    fields = { ...fields, muteUntil: muteOf(mute, nowMs) };
  }
  if (previews === 'default') {
    fields = without(fields, 'showPreviews');
  } else if (previews !== undefined) {
    fields = { ...fields, showPreviews: previews === 'on' };
  }
  return fields;
};

const validMute = (v) =>
  v === undefined ||
  v === 'off' ||
  v === 'forever' ||
  (Number.isInteger(v) && v > 0);
const validPreviews = (v) =>
  v === undefined || v === 'default' || v === 'on' || v === 'off';

const validSound = (v) => v === undefined || SOUND.test(String(v));

export const validChatChange = (b = {}) =>
  CHAT.test(String(b.chat ?? '')) &&
  (b.reset === undefined || typeof b.reset === 'boolean') &&
  validMute(b.mute) &&
  validPreviews(b.previews) &&
  validSound(b.sound) &&
  (b.reset === true ||
    b.mute !== undefined ||
    b.previews !== undefined ||
    b.sound !== undefined);

export const validScopeChange = (b = {}) =>
  SCOPES.includes(b.scope) &&
  (b.on === undefined || typeof b.on === 'boolean') &&
  (b.previews === undefined || typeof b.previews === 'boolean') &&
  (b.stories === undefined || typeof b.stories === 'boolean') &&
  (b.on !== undefined || b.previews !== undefined || b.stories !== undefined);

const scopeFields = (current, body) => {
  const fields = keptFields(current);
  if (body.on !== undefined) {
    fields.muteUntil = body.on ? 0 : MUTE_FOREVER;
  }
  if (body.previews !== undefined) {
    fields.showPreviews = body.previews;
  }
  if (body.stories !== undefined) {
    fields.storiesMuted = !body.stories;
  }
  return fields;
};

export const createNotifySettings = (env, { userClient }) => {
  const now = env.now ?? (() => Date.now());
  const read = (c, peer) =>
    c.client.invoke(new c.Api.account.GetNotifySettings({ peer }));
  const write = (c, peer, fields) =>
    c.client.invoke(
      new c.Api.account.UpdateNotifySettings({
        peer,
        settings: new c.Api.InputPeerNotifySettings(fields),
      })
    );

  const notifyOverview = async () =>
    connected(env, userClient, failure, (c) =>
      runIn(env, 'notify-settings', async () => {
        const nowMs = now();
        const scopes = {};
        for (const scope of SCOPES) {
          scopes[scope] = rowOf(
            await read(c, new c.Api[INPUT[scope]]()),
            nowMs
          );
        }
        const result = await c.client.invoke(
          new c.Api.account.GetNotifyExceptions({ compareSound: true })
        );
        const exceptions = (result?.updates ?? [])
          .filter((u) => u.className === 'UpdateNotifySettings')
          .map((u) => exceptionOf(result, u, nowMs))
          .filter(Boolean);
        return { ok: true, scopes, exceptions };
      })
    );

  const notifyScopeSet = async (body = {}) => {
    if (!validScopeChange(body)) {
      return BAD;
    }
    return connected(env, userClient, failure, (c) =>
      runIn(env, `notify-scope:${body.scope}`, async () => {
        const peer = new c.Api[INPUT[body.scope]]();
        const fields = scopeFields(await read(c, peer), body);
        await write(c, peer, fields);
        return { ok: true, scope: body.scope, ...rowOf(fields, now()) };
      })
    );
  };

  const chatRow = (chat, settings, nowMs) => {
    const until = Number(settings.muteUntil ?? 0);
    return {
      ok: true,
      chat,
      exception:
        settings.showPreviews !== undefined ||
        settings.muteUntil !== undefined ||
        settings.silent !== undefined ||
        soundText(settings.otherSound ?? settings.sound) !== 'default',
      muteUntil: until * 1000 > nowMs ? until : 0,
      forever: until * 1000 - nowMs > FOREVER_MS,
      previews: bool(settings.showPreviews) ?? null,
      stories: settings.storiesMuted !== true,
      sound: soundText(settings.otherSound ?? settings.sound),
    };
  };

  const makeSound = (c) => (sound) =>
    sound === 'none'
      ? new c.Api.NotificationSoundNone()
      : new c.Api.NotificationSoundRingtone({
          id: c.helpers.returnBigInt(sound),
        });

  const withNotifyPeer = (c, chat, use) =>
    env.connection.withPeer(c.client, chat, (peer) =>
      use(new c.Api.InputNotifyPeer({ peer }))
    );

  const notifyChat = async ({ chat } = {}) => {
    if (!CHAT.test(String(chat ?? ''))) {
      return BAD;
    }
    const id = String(chat);
    return connected(env, userClient, failure, (c) =>
      runIn(env, `notify-chat:${id}`, async () =>
        chatRow(id, await withNotifyPeer(c, id, (peer) => read(c, peer)), now())
      )
    );
  };

  const notifyChatSet = async (body = {}) => {
    if (!validChatChange(body)) {
      return BAD;
    }
    const id = String(body.chat);
    return connected(env, userClient, failure, (c) =>
      runIn(env, `notify-chat:${id}`, async () => {
        const nowMs = now();
        const fields = await withNotifyPeer(c, id, async (peer) => {
          const next = body.reset
            ? {}
            : chatFields(await read(c, peer), body, nowMs, makeSound(c));
          await write(c, peer, next);
          return next;
        });
        // The list follows at once, as it does for a mute from its menu.
        await env.live?.handle?.(c.client, {
          className: 'UpdateNotifySettings',
          peer: { className: 'NotifyPeer', peer: peerOfChat(id) },
          notifySettings: { muteUntil: fields.muteUntil ?? 0 },
        });
        return chatRow(id, fields, nowMs);
      })
    );
  };

  return { notifyOverview, notifyScopeSet, notifyChat, notifyChatSet };
};

/**
 * Ownership of a chat, as Telegram Desktop's edit dialog has it (R-Y200;
 * learned, never copied):
 * - `convertToGigagroup({ chat, confirm })` — the supergroup becomes a
 *   broadcast group where only admins write (channels.convertToGigagroup);
 *   cannot be undone, so `confirm: true` is required;
 * - `transferOwnership({ chat, user, password })` — the chat handed to a
 *   member (messages.editChatCreator, layer 225's call for groups and
 *   channels) with the 2-Step Verification password checked by the
 *   `telegram` package's SRP helper (`computeCheck`). The password lives
 *   only in the request in memory: never logged, stored, put into an error
 *   or answered. PASSWORD_MISSING, PASSWORD_TOO_FRESH_* and
 *   SESSION_TOO_FRESH_* come back as codes (with `waitSeconds`).
 * Telegram's errors become codes the page shows as text.
 */

import { inputPeerOf } from './telegram-members.js';
import { connected, failureOf, runIn } from './telegram-stickers.js';

const CODES = {
  CHAT_ADMIN_REQUIRED: 'not-admin',
  USER_NOT_PARTICIPANT: 'not-member',
  USER_ID_INVALID: 'not-member',
  MEGAGROUP_REQUIRED: 'not-supergroup',
  PARTICIPANTS_TOO_FEW: 'too-few',
  CHANNEL_PRIVATE: 'no-access',
  CHANNEL_INVALID: 'no-access',
  PASSWORD_MISSING: 'password-missing',
  PASSWORD_TOO_FRESH_: 'password-fresh',
  SESSION_TOO_FRESH_: 'session-fresh',
  PASSWORD_HASH_INVALID: 'password-wrong',
  SRP_PASSWORD_CHANGED: 'srp-invalid',
  SRP_ID_INVALID: 'srp-invalid',
  CHANNELS_ADMIN_PUBLIC_TOO_MUCH: 'too-many-public',
  CHANNELS_ADMIN_LOCATED_TOO_MUCH: 'too-many-public',
  USER_CHANNELS_TOO_MUCH: 'too-many-public',
  USER_PRIVACY_RESTRICTED: 'privacy',
  FLOOD_WAIT: 'flood',
};

const asFailure = failureOf(CODES);
const nameOf = (error) => String(error?.errorMessage ?? error?.message ?? '');
// Only the error's name is read, never anything of the request: the
// password cannot reach an answer.
const failure = (error) => {
  const out = asFailure(error);
  const wait = /(?:PASSWORD|SESSION)_TOO_FRESH_(\d+)/.exec(nameOf(error));
  return wait ? { ...out, waitSeconds: Number(wait[1]) } : out;
};
const bad = () => ({ ok: false, error: 'bad-request', code: 'bad-request' });

const CHANNEL = /^-100\d{1,20}$/;
const CHAT = /^-\d{1,20}$/;
const USER = /^\d{1,20}$/;
export const PASSWORD_MAX = 256;

const createGigagroup =
  (env, userClient) =>
  async (body = {}) => {
    const chat = String(body.chat ?? '');
    if (!CHANNEL.test(chat) || body.confirm !== true) {
      return bad();
    }
    return connected(env, userClient, failure, async (c) => {
      await runIn(env, `gigagroup:${chat}`, () =>
        env.connection.withPeer(c.client, chat, (peer) =>
          c.client.invoke(
            new c.Api.channels.ConvertToGigagroup({ channel: peer })
          )
        )
      );
      return { ok: true };
    });
  };

// The user as an InputUser, from what GramJS knows, else by id alone.
const inputUserOf = async (c, user) => {
  const known = await inputPeerOf(c, user);
  return new c.Api.InputUser({
    userId: known.userId ?? c.helpers.returnBigInt(user),
    accessHash: known.accessHash ?? c.helpers.returnBigInt(0),
  });
};

// One try: fresh SRP data, the check made by the package's helper.
const tryTransfer = async (env, c, srp, { chat, user, password }) => {
  const pwd = await c.client.invoke(new c.Api.account.GetPassword());
  if (!pwd.hasPassword) {
    return { ok: false, error: 'PASSWORD_MISSING', code: 'password-missing' };
  }
  const check = await srp.computeCheck(pwd, password);
  const target = await inputUserOf(c, user);
  await runIn(env, `transfer:${chat}`, () =>
    env.connection.withPeer(c.client, chat, (peer) =>
      c.client.invoke(
        new c.Api.messages.EditChatCreator({
          peer,
          userId: target,
          password: check,
        })
      )
    )
  );
  return { ok: true };
};

const createTransfer =
  (env, userClient) =>
  async (body = {}) => {
    const chat = String(body.chat ?? '');
    const { password } = body;
    if (
      !CHAT.test(chat) ||
      !USER.test(String(body.user ?? '')) ||
      typeof password !== 'string' ||
      password === '' ||
      password.length > PASSWORD_MAX
    ) {
      return bad();
    }
    return connected(env, userClient, failure, async (c) => {
      const { password: srp } = await env.importer();
      // Repeated once when Telegram says its SRP data went stale.
      for (let attempt = 0; ; attempt += 1) {
        try {
          return await tryTransfer(env, c, srp, {
            chat,
            user: String(body.user),
            password,
          });
        } catch (error) {
          if (attempt === 0 && failure(error).code === 'srp-invalid') {
            continue;
          }
          return failure(error);
        }
      }
    });
  };

export const createOwnership = (env, context) => ({
  convertToGigagroup: createGigagroup(env, context.userClient),
  transferOwnership: createTransfer(env, context.userClient),
});

/**
 * Reading Telegram page by page, store first (R-Y24 .. R-Y26): one
 * chat's history (newest, then older pages as the user scrolls back) and
 * the chat list beyond its first page. What the store already holds is
 * never asked for again (./telegram-history.js says what that is); every
 * request goes through the account's queue at the caller's priority.
 *
 * A chat is asked for by its stored input peer (./telegram-peers.js),
 * so reading it is one request; a channel the user reads is caught up
 * through its own difference (./telegram-channels.js), which also brings
 * its edits and deletions.
 *
 * The helpers that turn GramJS objects into links live in
 * ./telegram-account.js and come in through `tools`, so this module has
 * no import cycle with it.
 */

import {
  coverSlice,
  historyLink,
  historyLinkId,
  historyPlan,
} from './telegram-history.js';
import { createHistoryJump } from './telegram-jump.js';

const iso = (ms) => new Date(ms).toISOString();

const idOf = (value) =>
  value === undefined || value === null ? null : String(value?.value ?? value);

/**
 * Where the next page of the chat list starts: after the oldest dialog of
 * this one (pinned dialogs are listed first, out of date order).
 */
export const dialogsCursor = (listed = []) => {
  const dated = listed
    .filter((d) => !d?.pinned && d?.message?.date)
    .map((d) => ({
      offsetDate: Number(d.message.date),
      offsetId: Number(d.message.id) || 0,
      chat: idOf(d.id),
    }));
  if (dated.length === 0) {
    return null;
  }
  return dated.reduce((oldest, d) =>
    d.offsetDate < oldest.offsetDate ? d : oldest
  );
};

// A page that ends where the last one did would loop forever.
const cursorMoved = (next, cursor) =>
  !cursor ||
  next.offsetDate < cursor.offsetDate ||
  (next.offsetDate === cursor.offsetDate && next.chat !== cursor.chat);

// The chat's input peer and kind: stored, else looked up once (through
// the queue) and stored.
const whereIs = async (env, tools, client, chat, priority) => {
  const { queue, connection } = env;
  const stored = await env.peers?.input(chat);
  const known = env.live?.chats?.get(chat) ?? (await env.peers?.dialog(chat));
  if (stored && known) {
    return { peer: stored, dialog: known };
  }
  const entity = await queue.run(`entity:${chat}`, priority, () =>
    connection.withPeer(client, chat, (peer) => client.getEntity(peer))
  );
  const dialog = tools.dialogOfEntity(chat, entity);
  await env.peers?.remember(chat, entity, dialog);
  return { peer: stored ?? entity, dialog };
};

// The chat list's next page: after `cursor`, from that chat's peer.
const pageParams = (listedPeers, cursor, limit) => {
  if (!cursor) {
    return { limit };
  }
  const peer = listedPeers.get(cursor.chat);
  return {
    limit,
    offsetDate: cursor.offsetDate,
    offsetId: cursor.offsetId,
    ignorePinned: true,
    ...(peer ? { offsetPeer: peer } : {}),
  };
};

// A channel the user reads: its own difference brings what came after
// the stored messages, with edits and deletions (instead of `since`).
const channelCatchUp = async (env, chat, plan, priority) => {
  if (priority === 'view') {
    env.channels?.opened(chat);
  }
  if (plan.mode !== 'since' || !(await env.channels?.follows(chat))) {
    return null;
  }
  const fed = await env.channels.difference(chat, priority);
  return { written: fed ?? 0, cached: false };
};

const coalesceHistory = (readHistory, queue) => {
  const histories = new Map();
  return (options = {}) => {
    const key = JSON.stringify([String(options.chat), options.before ?? null]);
    const existing = histories.get(key);
    if ((options.priority ?? 'view') === 'view') {
      if (existing) {
        existing.options.priority = 'view';
      }
      const chat = String(options.chat);
      queue.promote?.(
        (key) => key === `entity:${chat}` || key.startsWith(`messages:${chat}:`)
      );
    }
    if (existing) {
      return existing.promise;
    }
    const entry = { options: { ...options } };
    entry.promise = readHistory(entry.options).finally(() =>
      histories.delete(key)
    );
    histories.set(key, entry);
    return entry.promise;
  };
};

const createPages = (env, tools) => {
  const { store, connection, queue, now } = env;
  // Input peers of listed dialogs, so the next page can say where to go on.
  const listedPeers = new Map();

  const getMessages = (client, entity, chat, plan, priority) =>
    queue.run(
      `messages:${chat}:${plan.mode}:${JSON.stringify(plan.options)}`,
      priority,
      () => client.getMessages(entity, plan.options)
    );

  /** Messages of a listed dialog after what is stored, as the sync reads them. */
  const readNew = async (client, dialog, chat, { limit, since, priority }) => {
    const record = await store.get(historyLinkId(chat));
    const after = record?.newest ?? (since ? Number(since) : null);
    const plan = after
      ? { mode: 'since', options: { limit, minId: Number(after) } }
      : { mode: 'newest', options: { limit } };
    const list = [
      ...((await getMessages(
        client,
        dialog.entity ?? chat,
        chat,
        plan,
        priority
      )) ?? []),
    ];
    const cover = coverSlice(record ? { ...record } : null, {
      ids: list.map((m) => m?.id),
      limit,
      mode: plan.mode,
      at: iso(now()),
    });
    return {
      links: tools.toLinks(dialog, list),
      cover: historyLink(chat, cover),
    };
  };

  /**
   * One chat's history, store first: `before` asks for the page older
   * than that message id (the user scrolls back), none for the newest.
   * Returns what was written and whether the chat's start is stored.
   */
  const readHistory = async (options = {}) => {
    const { chat, limit = 50, before = null } = options;
    const priority = () => options.priority ?? 'view';
    const creds = await tools.credentials();
    if (creds?.kind !== 'user' || !chat) {
      return { written: 0 };
    }
    const target = String(chat);
    const record = await store.get(historyLinkId(target));
    const plan = historyPlan(record ? { ...record, chat: target } : null, {
      before,
      limit,
      now: now(),
    });
    if (!plan) {
      return {
        written: 0,
        cached: true,
        complete: Boolean(record?.complete),
      };
    }
    const caughtUp = await channelCatchUp(env, target, plan, priority());
    if (caughtUp) {
      return { ...caughtUp, complete: Boolean(record?.complete) };
    }
    const { client } = await connection.open(creds);
    const { peer, dialog } = await whereIs(
      env,
      tools,
      client,
      target,
      priority()
    );
    const list = [
      ...((await getMessages(client, peer, target, plan, priority())) ?? []),
    ];
    const written = await tools.writeChanged(
      store,
      tools.toLinks(dialog, list)
    );
    // Live updates or another page may have advanced coverage while the
    // RPC was queued. Merge with the current record, preserving that work.
    const cover = coverSlice(await store.get(historyLinkId(target)), {
      ids: list.map((m) => m?.id),
      limit,
      mode: plan.mode,
      at: iso(now()),
    });
    await store.put(historyLink(target, cover));
    if (written > 0) {
      await tools.recordSync(store, { changedAt: iso(now()) });
    }
    return { written, cached: false, complete: Boolean(cover.complete) };
  };

  const history = coalesceHistory(readHistory, queue);

  /**
   * Remember the input peers of listed dialogs (for `offsetPeer`, and in
   * the store for reading the chat later) and each channel's number.
   */
  const remember = async (listed) => {
    for (const dialog of listed) {
      const chat = idOf(dialog?.id);
      if (chat && dialog.inputEntity) {
        listedPeers.set(chat, dialog.inputEntity);
        await env.peers?.remember(
          chat,
          dialog.inputEntity,
          tools.dialogInfo(chat, dialog.entity)
        );
        await env.channels?.seed(chat, dialog.dialog?.pts);
      }
    }
  };

  // Each listed chat's read state and newest message (its row in Chat).
  const listedLinks = (listed) => {
    const links = [];
    const ranks = tools.pinnedRanks?.(listed) ?? new Map();
    for (const dialog of listed) {
      const chat = idOf(dialog?.id);
      if (!chat) {
        continue;
      }
      env.live?.chats?.set(chat, tools.dialogInfo(chat, dialog.entity));
      links.push(tools.dialogReadLink(chat, dialog, ranks.get(dialog)));
      if (dialog.message) {
        links.push(...tools.toLinks(dialog, [dialog.message]));
      }
    }
    return [...links, ...tools.partnersOf(listed)];
  };

  /**
   * The next page of the chat list, after the furthest one read. A chat's
   * history is read when it is opened or shown (`history`).
   */
  const moreDialogs = async ({ limit = 40, priority = 'list' } = {}) => {
    const creds = await tools.credentials();
    if (creds?.kind !== 'user') {
      return { written: 0, complete: true };
    }
    const state = (await store.get(tools.syncId)) ?? {};
    if (state.dialogsComplete) {
      return { written: 0, complete: true, cached: true };
    }
    const { client } = await connection.open(creds);
    const cursor = state.dialogsCursor ?? null;
    const listed = [
      ...((await queue.run(`dialogs:${JSON.stringify(cursor)}`, priority, () =>
        client.getDialogs(pageParams(listedPeers, cursor, limit))
      )) ?? []),
    ];
    await remember(listed);
    const written = await tools.writeChanged(store, listedLinks(listed));
    const next = dialogsCursor(listed);
    const moved = Boolean(next) && cursorMoved(next, cursor);
    const complete = listed.length < limit || !moved;
    await tools.recordSync(store, {
      dialogsCursor: moved ? next : cursor,
      dialogsComplete: complete,
      ...(written > 0 ? { changedAt: iso(now()) } : {}),
    });
    return { written, complete, chats: listed.length };
  };

  return { readNew, history, moreDialogs, remember };
};

/** The page reader, with jumps far back (./telegram-jump.js, R-Y106). */
export const createPageReader = (env, tools) => ({
  ...createPages(env, tools),
  ...createHistoryJump(env, tools, { whereIs }),
});

/**
 * Paid messages, as Telegram Desktop has them (R-Y184; learned, never
 * copied): a person or a group may charge Stars per message.
 * - `paidPrice({ chat })` — what one message costs the user in `chat`:
 *   a person's price from users.getRequirementsToContact, a supergroup's
 *   from its `send_paid_messages_stars` (channels.getChannels; an owner or
 *   admin writes free) → `{ ok, stars }` (0: free). Read only;
 * - `paidSettings()` — account.getGlobalPrivacySettings → `{ ok, stars }`,
 *   the price the user charges non-contacts (0: nobody is charged);
 * - `paidSettingsSave({ stars })` — account.setGlobalPrivacySettings with
 *   `noncontact_peers_paid_stars` = stars (0 removes it) and every other
 *   setting KEPT as read (a WRITE, on Save only), 0..PAID_STARS_MAX;
 * - `paidRevenue({ user })` — account.getPaidMessagesRevenue → `{ ok,
 *   stars }` earned from one person (read only);
 * - `paidException({ user, allow, refund })` — account.
 *   toggleNoPaidMessagesException: `allow` lets the person write for free
 *   (optionally refunding what they paid), otherwise they pay again (a
 *   WRITE, on a confirmation only);
 * - `paidPriceSave({ chat, stars })` — channels.updatePaidMessagesPrice for
 *   a group the user admins, 0 turns it off (a WRITE, on Save only).
 * Sending into such a chat is not here: a send carries the Stars the user
 * confirmed (`allowPaidStars`, telegram-send-as-client.js). Telegram's
 * errors become codes the page shows as text.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';

export const PAID_STARS_MAX = 10_000;

const CODES = {
  CHAT_ADMIN_REQUIRED: 'not-admin',
  STARS_AMOUNT_INVALID: 'bad-price',
  PAID_MESSAGE_STARS_INVALID: 'bad-price',
  USER_ID_INVALID: 'no-user',
  PEER_ID_INVALID: 'no-chat',
  CHANNEL_INVALID: 'no-chat',
  CHANNEL_PRIVATE: 'no-chat',
  FLOOD_WAIT: 'flood',
};
const failure = failureOf(CODES);
const BAD = { ok: false, error: 'bad request', code: 'bad-request' };
const USER = /^\d{1,20}$/;
const CHANNEL = /^-100\d{1,20}$/;
const whole = (n) => Number(n?.value ?? n ?? 0) || 0;

/** Whether `stars` is a whole price from 0 to the most Telegram takes. */
export const validPrice = (stars) =>
  Number.isInteger(stars) && stars >= 0 && stars <= PAID_STARS_MAX;

// The Stars a person asks, from users.getRequirementsToContact's answer.
const personStars = (answer) => {
  const one = Array.isArray(answer) ? answer[0] : null;
  return one?.className === 'RequirementToContactPaidMessages'
    ? whole(one.starsAmount)
    : 0;
};

// A group's price for this user: admins and the owner write free.
const groupStars = (answer) => {
  const channel = (answer?.chats ?? [])[0];
  if (!channel || channel.creator || channel.adminRights) {
    return 0;
  }
  return whole(channel.sendPaidMessagesStars);
};

const price = (env, userClient) => async (body) => {
  const chat = String(body?.chat ?? '');
  if (!USER.test(chat) && !CHANNEL.test(chat)) {
    // A basic group never charges.
    return /^-\d{1,20}$/.test(chat) ? { ok: true, stars: 0 } : BAD;
  }
  return connected(env, userClient, failure, async (c) => {
    const person = USER.test(chat);
    const answer = await runIn(env, `paid:price:${chat}`, () =>
      env.connection.withPeer(c.client, chat, (peer) =>
        c.client.invoke(
          person
            ? new c.Api.users.GetRequirementsToContact({ id: [peer] })
            : new c.Api.channels.GetChannels({ id: [peer] })
        )
      )
    );
    return {
      ok: true,
      stars: person ? personStars(answer) : groupStars(answer),
    };
  });
};

// The settings as Telegram has them, to be set again with one changed.
const KEPT = [
  'archiveAndMuteNewNoncontactPeers',
  'keepArchivedUnmuted',
  'keepArchivedFolders',
  'hideReadMarks',
  'newNoncontactPeersRequirePremium',
  'displayGiftsButton',
  'disallowedGifts',
];

const settingsWith = (c, current, stars) =>
  new c.Api.GlobalPrivacySettings({
    ...Object.fromEntries(
      KEPT.filter(
        (k) => current?.[k] !== undefined && current[k] !== false
      ).map((k) => [k, current[k]])
    ),
    ...(stars > 0 ? { noncontactPeersPaidStars: stars } : {}),
  });

const settings = (env, userClient) => async () =>
  connected(env, userClient, failure, async (c) => {
    const current = await runIn(env, 'paid:settings', () =>
      c.client.invoke(new c.Api.account.GetGlobalPrivacySettings())
    );
    return { ok: true, stars: whole(current?.noncontactPeersPaidStars) };
  });

const settingsSave =
  (env, userClient) =>
  async ({ stars } = {}) =>
    !validPrice(stars)
      ? BAD
      : connected(env, userClient, failure, async (c) => {
          const current = await runIn(env, 'paid:settings', () =>
            c.client.invoke(new c.Api.account.GetGlobalPrivacySettings())
          );
          await runIn(env, 'paid:settings', () =>
            c.client.invoke(
              new c.Api.account.SetGlobalPrivacySettings({
                settings: settingsWith(c, current, stars),
              })
            )
          );
          return { ok: true, stars };
        });

const revenue =
  (env, userClient) =>
  async ({ user } = {}) =>
    !USER.test(String(user ?? ''))
      ? BAD
      : connected(env, userClient, failure, async (c) => {
          const answer = await runIn(env, `paid:revenue:${user}`, () =>
            env.connection.withPeer(c.client, String(user), (peer) =>
              c.client.invoke(
                new c.Api.account.GetPaidMessagesRevenue({ userId: peer })
              )
            )
          );
          return { ok: true, stars: whole(answer?.starsAmount) };
        });

const exception =
  (env, userClient) =>
  async ({ user, allow, refund } = {}) =>
    !USER.test(String(user ?? '')) || typeof allow !== 'boolean'
      ? BAD
      : connected(env, userClient, failure, async (c) => {
          await runIn(env, `paid:exception:${user}`, () =>
            env.connection.withPeer(c.client, String(user), (peer) =>
              c.client.invoke(
                new c.Api.account.ToggleNoPaidMessagesException({
                  userId: peer,
                  ...(allow
                    ? refund === true
                      ? { refundCharged: true }
                      : {}
                    : { requirePayment: true }),
                })
              )
            )
          );
          return { ok: true, allow };
        });

const priceSave =
  (env, userClient) =>
  async ({ chat, stars } = {}) =>
    !CHANNEL.test(String(chat ?? '')) || !validPrice(stars)
      ? BAD
      : connected(env, userClient, failure, async (c) => {
          await runIn(env, `paid:price-save:${chat}`, () =>
            env.connection.withPeer(c.client, String(chat), (channel) =>
              c.client.invoke(
                new c.Api.channels.UpdatePaidMessagesPrice({
                  channel,
                  sendPaidMessagesStars: stars,
                })
              )
            )
          );
          return { ok: true, stars };
        });

export const createPaidMessages = (env, { userClient }) => ({
  paidPrice: price(env, userClient),
  paidSettings: settings(env, userClient),
  paidSettingsSave: settingsSave(env, userClient),
  paidRevenue: revenue(env, userClient),
  paidException: exception(env, userClient),
  paidPriceSave: priceSave(env, userClient),
});

/**
 * What Telegram Desktop offers on a person or a chat besides talking
 * (R-Y128; learned, never copied):
 * - `peerBlock({ chat, block })` — "Block user" / "Unblock user"
 *   (contacts.block, contacts.unblock);
 * - `peerContact({ chat, add, firstName, lastName, share })` — "Add to
 *   contacts" with the name typed (contacts.addContact; `share` lets them
 *   see our phone number) / "Delete contact" (contacts.deleteContacts);
 * - `peerReport({ chat, option, message, ids })` — "Report" as layer 225
 *   has it (messages.report on the whole chat, or — with `ids`, up to a
 *   hundred message ids of the chat, R-Y175 — on those messages): the first
 *   call, with no option, answers `{ result: 'choose', title, options:
 *   [{ text, option }] }`; a call with a chosen `option` (base64 of its
 *   bytes) answers `choose` again (a narrower list), `comment` (Telegram
 *   asks for words: `optional`, `option`) or `reported`; the comment comes
 *   back in `message`;
 * - `peerReportSpam({ chat })` — "Report spam" on a stranger's chat
 *   (messages.reportSpam).
 * The bar over a chat with a stranger (R-Y137):
 * - `peerSettings({ chat })` — what Telegram offers there
 *   (messages.getPeerSettings) → `{ ok, bar: { reportSpam, addContact,
 *   blockContact, shareContact, autoarchived, registered, country } }`;
 * - `peerHideBar({ chat })` — the bar's × (messages.hidePeerSettingsBar);
 * - `peerShareContact({ chat })` — "Share my phone number"
 *   (contacts.acceptContact).
 * Telegram's errors become codes the page shows as text.
 */

import { runIn, connected, failureOf } from './telegram-stickers.js';

const CODES = {
  USER_ID_INVALID: 'no-user',
  CONTACT_ID_INVALID: 'no-user',
  PEER_ID_INVALID: 'no-access',
  CHANNEL_PRIVATE: 'no-access',
  CHAT_ID_INVALID: 'no-access',
  CONTACT_NAME_EMPTY: 'name-empty',
  OPTION_INVALID: 'bad-option',
  MESSAGE_TOO_LONG: 'too-long',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);

const USER = /^\d{1,20}$/;
const CHAT = /^-?\d{1,20}$/;
const BASE64 = /^[A-Za-z0-9+/]*={0,2}$/;

export const bytesOf = (value) => Buffer.from(String(value ?? ''), 'base64');
const base64Of = (bytes) => Buffer.from(bytes ?? []).toString('base64');

// A person as an input user, from the peer the chat resolves to.
export const inputUserOf = async (c, peer) => {
  const known =
    typeof peer === 'string'
      ? await c.client.getInputEntity(c.helpers.returnBigInt(peer))
      : peer;
  return new c.Api.InputUser({
    userId: known.userId,
    accessHash: known.accessHash ?? c.zero,
  });
};

// Telegram's ReportResult as the page reads it.
export const shapeReport = (result) => {
  switch (result?.className) {
    case 'ReportResultChooseOption':
      return {
        ok: true,
        result: 'choose',
        title: result.title ?? '',
        options: (result.options ?? []).map((o) => ({
          text: o.text,
          option: base64Of(o.option),
        })),
      };
    case 'ReportResultAddComment':
      return {
        ok: true,
        result: 'comment',
        optional: Boolean(result.optional),
        option: base64Of(result.option),
      };
    default:
      return { ok: true, result: 'reported' };
  }
};

// Checks the request, connects, runs `use` on the peer through the queue,
// and maps Telegram's errors.
const doing = (env, userClient, valid, name, use) => async (request) => {
  const chat = String(request?.chat ?? '');
  if (!valid(chat, request ?? {})) {
    return { ok: false, error: 'bad request', code: 'failed' };
  }
  return connected(
    env,
    userClient,
    failure,
    async (c) =>
      await runIn(env, `${name}:${chat}`, () =>
        env.connection.withPeer(c.client, chat, (peer) => use(c, peer, request))
      )
  );
};

const block = async (c, peer, { block: on }) => {
  const Request = on ? c.Api.contacts.Block : c.Api.contacts.Unblock;
  await c.client.invoke(new Request({ id: peer }));
  return { ok: true, blocked: on };
};

const contact = async (c, peer, request) => {
  const id = await inputUserOf(c, peer);
  if (!request.add) {
    await c.client.invoke(new c.Api.contacts.DeleteContacts({ id: [id] }));
    return { ok: true, contact: false };
  }
  await c.client.invoke(
    new c.Api.contacts.AddContact({
      id,
      firstName: request.firstName.trim(),
      lastName: (request.lastName ?? '').trim(),
      phone: '',
      ...(request.share ? { addPhonePrivacyException: true } : {}),
    })
  );
  return { ok: true, contact: true };
};

const report = async (c, peer, request) =>
  shapeReport(
    await c.client.invoke(
      new c.Api.messages.Report({
        peer,
        id: request.ids ?? [],
        option: bytesOf(request.option),
        message: request.message ?? '',
      })
    )
  );

const reportSpam = async (c, peer) => {
  await c.client.invoke(new c.Api.messages.ReportSpam({ peer }));
  return { ok: true };
};

// Telegram's PeerSettings as the page reads it.
const barOf = (settings = {}) => ({
  reportSpam: Boolean(settings.reportSpam),
  addContact: Boolean(settings.addContact),
  blockContact: Boolean(settings.blockContact),
  shareContact: Boolean(settings.shareContact),
  autoarchived: Boolean(settings.autoarchived),
  registered: settings.registrationMonth ?? null,
  country: settings.phoneCountry ?? null,
});

const peerSettings = async (c, peer) => {
  const answer = await c.client.invoke(
    new c.Api.messages.GetPeerSettings({ peer })
  );
  return { ok: true, bar: barOf(answer?.settings) };
};

const hideBar = async (c, peer) => {
  await c.client.invoke(new c.Api.messages.HidePeerSettingsBar({ peer }));
  return { ok: true };
};

const shareContact = async (c, peer) => {
  const id = await inputUserOf(c, peer);
  await c.client.invoke(new c.Api.contacts.AcceptContact({ id }));
  return { ok: true };
};

const text = (value, max) => typeof value === 'string' && value.length <= max;

const validContact = (chat, r) =>
  USER.test(chat) &&
  (r.add !== true ||
    (text(r.firstName, 64) &&
      r.firstName.trim() !== '' &&
      (r.lastName === undefined || text(r.lastName, 64))));

const validIds = (ids) =>
  ids === undefined ||
  (Array.isArray(ids) &&
    ids.length > 0 &&
    ids.length <= 100 &&
    ids.every((id) => Number.isInteger(id) && id > 0));

const validReport = (chat, r) =>
  CHAT.test(chat) &&
  validIds(r.ids) &&
  (r.option === undefined || (text(r.option, 2048) && BASE64.test(r.option))) &&
  (r.message === undefined || text(r.message, 512));

const anyChat = (chat) => CHAT.test(chat);

export const createPeerActions = (env, { userClient }) => ({
  peerBlock: doing(
    env,
    userClient,
    (chat, r) => USER.test(chat) && typeof r.block === 'boolean',
    'peer-block',
    block
  ),
  peerContact: doing(env, userClient, validContact, 'peer-contact', contact),
  peerReport: doing(env, userClient, validReport, 'peer-report', report),
  peerReportSpam: doing(
    env,
    userClient,
    anyChat,
    'peer-report-spam',
    reportSpam
  ),
  peerSettings: doing(env, userClient, anyChat, 'peer-settings', peerSettings),
  peerHideBar: doing(env, userClient, anyChat, 'peer-hide-bar', hideBar),
  peerShareContact: doing(
    env,
    userClient,
    (chat) => USER.test(chat),
    'peer-share-contact',
    shareContact
  ),
});

/**
 * Where each Telegram chat is, kept in the store (R-Y34): the input peer
 * Telegram needs to be asked about a chat (its id and access hash), and
 * what kind of chat it is, as `peer:telegram:<chat>` links.
 *
 * GramJS knows a chat only after it has seen it in an answer; after a
 * restart, asking for a chat by its bare id made it look the chat up
 * (`getEntity`) or list the dialogs again — a request more for every
 * chat read. With the peer stored, reading a chat is one request, and
 * the chat list is asked for only to read the chat list.
 */

import { importTelegram } from './telegram-layer.js';

const SOURCE = 'telegram';

export const peerLinkId = (chat) => `peer:${SOURCE}:${chat}`;

const text = (value) =>
  value === null || value === undefined ? null : String(value.value ?? value);

// An input peer or an entity as `{ kind, id, accessHash }`; null for a
// "min" entity, whose access hash does not work for asking.
const KINDS = {
  InputPeerUser: (p) => ({ kind: 'user', id: p.userId, hash: p.accessHash }),
  InputPeerChat: (p) => ({ kind: 'chat', id: p.chatId, hash: null }),
  InputPeerChannel: (p) => ({
    kind: 'channel',
    id: p.channelId,
    hash: p.accessHash,
  }),
  User: (e) => ({ kind: 'user', id: e.id, hash: e.accessHash }),
  Chat: (e) => ({ kind: 'chat', id: e.id, hash: null }),
  Channel: (e) => ({ kind: 'channel', id: e.id, hash: e.accessHash }),
};

/** The stored form of an input peer or entity, or null. */
export const peerRecord = (value) => {
  const make = KINDS[value?.className];
  if (!make || value.min) {
    return null;
  }
  const { kind, id, hash } = make(value);
  if (id === undefined || (kind !== 'chat' && !text(hash))) {
    return null;
  }
  return { kind, peerId: text(id), accessHash: text(hash) };
};

/** What the chat is, for the links its messages become. */
const infoOf = (dialog = {}) => ({
  title: dialog.title ?? dialog.name ?? null,
  isUser: Boolean(dialog.isUser),
  isGroup: Boolean(dialog.isGroup),
  isChannel: Boolean(dialog.isChannel),
});

const sameRecord = (a, b) =>
  Boolean(a) &&
  ['kind', 'peerId', 'accessHash', 'title', 'isGroup', 'isChannel'].every(
    (f) => (a[f] ?? null) === (b[f] ?? null)
  );

/**
 * `remember(chat, inputPeer, dialog)` stores a chat's peer (only when it
 * changed); `input(chat)` rebuilds the GramJS input peer, or null when
 * the chat was never listed; `dialog(chat)` the chat's kind and name.
 */
export const createPeers = ({ store, importer = importTelegram }) => {
  const known = new Map(); // chat -> stored record (or null)

  const read = async (chat) => {
    if (!known.has(chat)) {
      known.set(chat, (await store.get(peerLinkId(chat))) ?? null);
    }
    return known.get(chat);
  };

  const remember = async (chat, value, dialog) => {
    const record = peerRecord(value);
    if (!chat || !record) {
      return false;
    }
    const link = {
      id: peerLinkId(chat),
      tokens: ['peer', SOURCE, String(chat)],
      kind: 'peer',
      source: SOURCE,
      chat: String(chat),
      ...record,
      ...infoOf(dialog),
    };
    // An entity seen in an update has no dialog: keep the listed name.
    const before = await read(String(chat));
    const next = dialog ? link : { ...link, ...(before ? infoOf(before) : {}) };
    if (sameRecord(before, next)) {
      return false;
    }
    known.set(String(chat), next);
    await store.put({ ...(before ?? {}), ...next });
    return true;
  };

  const input = async (chat) => {
    const record = await read(String(chat));
    if (!record?.peerId) {
      return null;
    }
    const { Api, helpers } = await importer();
    const big = (value) => helpers.returnBigInt(String(value));
    if (record.kind === 'user') {
      return new Api.InputPeerUser({
        userId: big(record.peerId),
        accessHash: big(record.accessHash),
      });
    }
    if (record.kind === 'chat') {
      return new Api.InputPeerChat({ chatId: big(record.peerId) });
    }
    return new Api.InputPeerChannel({
      channelId: big(record.peerId),
      accessHash: big(record.accessHash),
    });
  };

  const dialog = async (chat) => {
    const record = await read(String(chat));
    return record ? { id: String(chat), ...infoOf(record) } : null;
  };

  return { remember, input, dialog };
};

/**
 * Change phone number, as Telegram Desktop's Settings → My Account has it
 * (R-Y212; learned, never copied):
 * - `phoneChangeSend({ phone })` — account.sendChangePhoneCode with the
 *   default CodeSettings → `{ ok, phoneCodeHash, length, timeout }`; the
 *   code goes to the new number;
 * - `phoneChangeConfirm({ phone, phoneCodeHash, code })` —
 *   account.changePhone → `{ ok, phone }`, the number the account has now.
 * Telegram's errors (PHONE_NUMBER_OCCUPIED, PHONE_CODE_INVALID, …) become
 * codes the page shows as text. The code is never logged or kept.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';

export const PHONE = /^\+?\d{5,15}$/;
export const CODE = /^\d{3,8}$/;
const HASH = /^[\w-]{1,128}$/;

const failure = failureOf({
  PHONE_NUMBER_OCCUPIED: 'occupied',
  PHONE_NUMBER_INVALID: 'phone-invalid',
  PHONE_NUMBER_BANNED: 'banned',
  PHONE_NUMBER_FLOOD: 'flood',
  PHONE_CODE_INVALID: 'code-invalid',
  PHONE_CODE_EMPTY: 'code-invalid',
  PHONE_CODE_EXPIRED: 'code-expired',
  PHONE_CODE_HASH_EMPTY: 'code-expired',
  FRESH_CHANGE_PHONE_FORBIDDEN: 'fresh',
  FLOOD_WAIT: 'flood',
  SMS_CODE_CREATE_FAILED: 'send-failed',
  TIMEOUT: 'send-failed',
});

const bad = (code) => ({ ok: false, error: code, code });

const send = (env, userClient) => async (request) => {
  const phone = String(request?.phone ?? '').trim();
  if (!PHONE.test(phone)) {
    return bad('phone-invalid');
  }
  return connected(env, userClient, failure, async (c) => {
    const sent = await runIn(env, 'phone-change:send', () =>
      c.client.invoke(
        new c.Api.account.SendChangePhoneCode({
          phoneNumber: phone,
          settings: new c.Api.CodeSettings({}),
        })
      )
    );
    if (!sent?.phoneCodeHash) {
      return bad('send-failed');
    }
    return {
      ok: true,
      phoneCodeHash: String(sent.phoneCodeHash),
      length: Number(sent.type?.length) || null,
      timeout: Number(sent.timeout) || null,
    };
  });
};

const confirm = (env, userClient) => async (request) => {
  const phone = String(request?.phone ?? '').trim();
  const code = String(request?.code ?? '').trim();
  const hash = String(request?.phoneCodeHash ?? '');
  if (!PHONE.test(phone) || !HASH.test(hash)) {
    return bad('bad-request');
  }
  if (!CODE.test(code)) {
    return bad('code-invalid');
  }
  return connected(env, userClient, failure, async (c) => {
    const user = await runIn(env, 'phone-change:confirm', () =>
      c.client.invoke(
        new c.Api.account.ChangePhone({
          phoneNumber: phone,
          phoneCodeHash: hash,
          phoneCode: code,
        })
      )
    );
    return { ok: true, phone: String(user?.phone ?? phone.replace(/^\+/, '')) };
  });
};

export const createPhoneChange = (env, { userClient }) => ({
  phoneChangeSend: send(env, userClient),
  phoneChangeConfirm: confirm(env, userClient),
});

/**
 * A chat's pinned messages as a list, and "Unpin all", as Telegram
 * Desktop has them (R-Y166; learned, never copied):
 * - `pinnedList({ chat, topMsgId?, offsetId? })` — the chat's pinned
 *   messages (messages.search with InputMessagesFilterPinned), newest
 *   first, a page at a time → `{ ok, messages, count, next }`: the messages
 *   as the history's links, `count` how many Telegram says are pinned,
 *   `next` the id to ask again with (null at the end). `topMsgId` is a
 *   forum topic's id.
 * - `unpinAll({ chat, topMsgId? })` — every pinned message (in the topic)
 *   unpinned (messages.unpinAllMessages, asked again while Telegram says
 *   there is more) → `{ ok }`.
 * Telegram's errors become codes the page shows as text.
 */

import { connected, runIn, failureOf } from './telegram-stickers.js';

const CODES = {
  CHAT_ADMIN_REQUIRED: 'no-right',
  CHAT_NOT_MODIFIED: 'none',
  MESSAGE_ID_INVALID: 'not-found',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);

export const PINNED_PAGE = 50;
const MAX_ROUNDS = 20;
const CHAT = /^-?\d{1,20}$/;
const DIGITS = /^\d{1,12}$/;
const BAD = { ok: false, error: 'bad request', code: 'failed' };

/** Whether a request body names a chat, optionally a topic and a page. */
export const validPinnedRequest = (body = {}) =>
  CHAT.test(String(body.chat ?? '')) &&
  [body.topMsgId, body.offsetId].every(
    (n) => n === undefined || DIGITS.test(String(n))
  );

const usable = (m) => m && m.id !== undefined && m.className !== 'MessageEmpty';

export const createPinnedList = (env, { userClient, dialogOf, tools }) => {
  const doing = (key, use) =>
    connected(env, userClient, failure, (c) => runIn(env, key, () => use(c)));

  const search = (c, { chat, top, offsetId }) =>
    env.connection.withPeer(c.client, chat, (peer) =>
      c.client.invoke(
        new c.Api.messages.Search({
          peer,
          q: '',
          ...(top ? { topMsgId: top } : {}),
          filter: new c.Api.InputMessagesFilterPinned(),
          minDate: 0,
          maxDate: 0,
          offsetId,
          addOffset: 0,
          limit: PINNED_PAGE,
          maxId: 0,
          minId: 0,
          hash: c.zero,
        })
      )
    );

  const pinnedList = async (body = {}) => {
    if (!validPinnedRequest(body)) {
      return BAD;
    }
    const { chat } = body;
    const top = Number(body.topMsgId ?? 0);
    const offsetId = Number(body.offsetId ?? 0);
    return doing(`pinned-list:${chat}:${top}:${offsetId}`, async (c) => {
      const answer = await search(c, { chat, top, offsetId });
      const found = [...(answer?.messages ?? [])].filter(usable);
      const ordered = found.sort((a, b) => Number(b.id) - Number(a.id));
      return {
        ok: true,
        messages: tools.toLinks(await dialogOf(chat), ordered),
        count: Number(answer?.count ?? found.length) || found.length,
        next: found.length >= PINNED_PAGE ? Number(ordered.at(-1).id) : null,
      };
    });
  };

  const unpinAll = async (body = {}) => {
    if (!validPinnedRequest(body)) {
      return BAD;
    }
    const top = Number(body.topMsgId ?? 0);
    return doing(`unpin-all:${body.chat}:${top}`, async (c) => {
      for (let round = 0; round < MAX_ROUNDS; round += 1) {
        const done = await env.connection.withPeer(
          c.client,
          body.chat,
          (peer) =>
            c.client.invoke(
              new c.Api.messages.UnpinAllMessages({
                peer,
                ...(top ? { topMsgId: top } : {}),
              })
            )
        );
        if (!Number(done?.offset ?? 0)) {
          break;
        }
      }
      return { ok: true };
    });
  };

  return { pinnedList, unpinAll };
};

/**
 * Reordering the pinned chats, as Telegram Desktop lets the user drag
 * them (R-Y159; learned, never copied):
 *
 * - `reorderPinned({ folder, chats })` — messages.reorderPinnedDialogs
 *   with `force`, for the main list (folder 0) or the Archive (folder 1);
 *   `chats` are all the pinned chats of that folder, first on top. A
 *   chat Telegram has pinned there that the request leaves out is added
 *   at the end, so `force` never unpins one by accident. Telegram's
 *   answer is then written as the update the other devices get, through
 *   the live handler, so the list keeps that order (the pinned rank, not
 *   the date).
 * Telegram's errors become codes the page shows as text.
 */

import { connected, runIn, failureOf } from './telegram-stickers.js';
import { peerOfChat } from './telegram-dialogs.js';

const CODES = {
  PEER_ID_INVALID: 'no-access',
  CHANNEL_PRIVATE: 'no-access',
  CHAT_ID_INVALID: 'no-access',
  PINNED_DIALOGS_TOO_MUCH: 'too-many',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);
const CHAT = /^-?\d{1,20}$/;
const BAD = { ok: false, error: 'bad request', code: 'failed' };

/** At most this many chats in one request. */
export const MAX_PINNED = 100;

/** Whether `chats` is a list of distinct, valid chat ids (at most 100). */
export const validOrder = (chats) =>
  Array.isArray(chats) &&
  chats.length > 0 &&
  chats.length <= MAX_PINNED &&
  chats.every((c) => typeof c === 'string' && CHAT.test(c)) &&
  new Set(chats).size === chats.length;

// The input peer of a chat, whichever form the connection gives.
const inputOf = (env, c, chat) =>
  env.connection.withPeer(c.client, chat, async (peer) =>
    typeof peer === 'object' ? peer : await c.client.getInputEntity(peer)
  );

// The chats pinned in the folder that the request leaves out.
const pinnedElsewhere = async (env, folder, chats) => {
  const rows =
    (await env.store?.query?.(
      (l) =>
        l?.kind === 'read' &&
        l.source === 'telegram' &&
        Number(l.pinnedRank ?? 0) > 0 &&
        (Number(l.folder ?? 0) === 1 ? 1 : 0) === folder
    )) ?? [];
  return [...rows]
    .sort((a, b) => a.pinnedRank - b.pinnedRank)
    .map((l) => String(l.chat))
    .filter((chat) => !chats.includes(chat));
};

export const createPinnedOrder = (env, { userClient }) => ({
  /** `{ folder, chats }` → `{ ok, folder, chats }`. */
  reorderPinned: async ({ folder, chats } = {}) => {
    if ((folder !== 0 && folder !== 1) || !validOrder(chats)) {
      return BAD;
    }
    return connected(env, userClient, failure, async (c) => {
      const order = [...chats, ...(await pinnedElsewhere(env, folder, chats))];
      return await runIn(env, `pinned-order:${folder}`, async () => {
        const peers = [];
        for (const chat of order) {
          peers.push(
            new c.Api.InputDialogPeer({ peer: await inputOf(env, c, chat) })
          );
        }
        await c.client.invoke(
          new c.Api.messages.ReorderPinnedDialogs({
            force: true,
            folderId: folder,
            order: peers,
          })
        );
        await env.live?.handle?.(c.client, {
          className: 'UpdatePinnedDialogs',
          folderId: folder,
          order: order.map((chat) => ({
            className: 'DialogPeer',
            peer: peerOfChat(chat),
          })),
        });
        return { ok: true, folder, chats: order };
      });
    });
  },
});

/**
 * Polls and checklists, as Telegram's own apps have them (R-Y74).
 *
 * - `UpdateMessagePoll` (a vote anywhere, ours too; its effect is in
 *   ./telegram-updates.js) writes the poll's
 *   results into the stored message's `raw.media`. Results marked `min`
 *   carry counts only: what we chose and which answer is right are kept
 *   from what was stored.
 * - `vote` (messages.sendVote; no options retracts), `stop` (the poll's
 *   author closes it: messages.editMessage with the poll `closed`),
 *   `results` (messages.getPollResults, for a poll on screen: Telegram
 *   sends a poll's results only to who asks), `votes` (who voted for
 *   what in a public poll: messages.getPollVotes) and `toggleTodo`
 *   (messages.toggleTodoCompleted).
 *
 * - `sendPoll` (a new poll, R-Y121: messages.sendMedia with InputMediaPoll; its
 *   answers as InputPollAnswer, a quiz's right one by its place;
 *   Telegram's answer goes to the live handler).
 *
 * - `sendTodo` (a new checklist, R-Y195: the same send path with
 *   InputMediaTodo) and `appendTodo` (messages.appendTodoList).
 *
 * An option is bytes; the app and the store name it in base64 (R-Y28).
 */

import { peerChatId } from './telegram-updates.js';
import { withSendAs } from './telegram-send-as-client.js';
import { randomIdOf, replyHeader, sendError } from './telegram-send.js';

const SOURCE = 'telegram';

const text = (value) =>
  value === null || value === undefined ? null : String(value.value ?? value);

const msgIdOf = (link) =>
  Number(
    String(link?.id ?? '')
      .split(':')
      .pop()
  );

const optionKey = (option) => option?.bytes ?? JSON.stringify(option ?? null);

/**
 * `next` results over `before`: a `min` answer (counts only) keeps what
 * we chose, which answer is right and the solution from `before`.
 */
export const mergePollResults = (before, next) => {
  if (!next) {
    return before ?? null;
  }
  if (!next.min || !before) {
    return next;
  }
  const known = new Map(
    (before.results ?? []).map((r) => [optionKey(r.option), r])
  );
  return {
    ...next,
    results: (next.results ?? before.results ?? []).map((r) => {
      const was = known.get(optionKey(r.option));
      return {
        ...r,
        chosen: r.chosen ?? was?.chosen ?? null,
        correct: r.correct ?? was?.correct ?? null,
      };
    }),
    solution: next.solution ?? before.solution ?? null,
    solutionEntities: next.solutionEntities ?? before.solutionEntities ?? null,
  };
};

const isPollOf = (pollId) => (l) =>
  l?.id?.startsWith(`msg:${SOURCE}:`) &&
  l.raw?.media?.className === 'MessageMediaPoll' &&
  text(l.raw.media.poll?.id) === pollId;

/** Write a poll effect; true when a stored message changed. */
export const pollWriter = async (store, effect) => {
  const named =
    effect.chat && effect.id
      ? [await store.get(`msg:${SOURCE}:${effect.chat}:${effect.id}`)]
      : await store.query(isPollOf(effect.pollId));
  let changed = false;
  for (const link of named.filter(Boolean)) {
    const media = link.raw?.media;
    if (media?.className !== 'MessageMediaPoll') {
      continue;
    }
    const next = {
      ...media,
      poll: effect.poll ?? media.poll,
      results: mergePollResults(media.results, effect.results),
    };
    if (JSON.stringify(next) !== JSON.stringify(media)) {
      await store.put({ ...link, raw: { ...link.raw, media: next } });
      changed = true;
    }
  }
  return changed;
};

const bytesOf = (b64) => Buffer.from(String(b64 ?? ''), 'base64');

const cleanOptions = (options) =>
  Array.isArray(options)
    ? options.filter((o) => typeof o === 'string' && o.length > 0).slice(0, 20)
    : [];

const cleanIds = (ids) =>
  Array.isArray(ids)
    ? ids.filter((id) => Number.isInteger(id) && id > 0).slice(0, 100)
    : [];

// The stored poll as GramJS's `Poll`, closed: what stops a poll.
const closedPoll = (Api, helpers, poll) =>
  new Api.Poll({
    id: helpers.returnBigInt(String(poll.id)),
    closed: true,
    publicVoters: Boolean(poll.publicVoters),
    multipleChoice: Boolean(poll.multipleChoice),
    quiz: Boolean(poll.quiz),
    question: new Api.TextWithEntities({
      text: poll.question?.text ?? String(poll.question ?? ''),
      entities: [],
    }),
    answers: (poll.answers ?? []).map(
      (a) =>
        new Api.PollAnswer({
          text: new Api.TextWithEntities({
            text: a.text?.text ?? String(a.text ?? ''),
            entities: [],
          }),
          option: bytesOf(a.option?.bytes),
        })
    ),
    hash: helpers.returnBigInt(String(poll.hash ?? 0)),
  });

const withText = (Api, value) =>
  new Api.TextWithEntities({ text: String(value), entities: [] });

// A new poll as `InputMediaPoll`: its answers as `InputPollAnswer`
// (Telegram names them), the right one of a quiz by its place — layer
// 225's way of making a poll.
const newPoll = (Api, helpers, draft) => {
  const quiz = draft.quiz === true;
  return new Api.InputMediaPoll({
    poll: new Api.Poll({
      id: helpers.returnBigInt(0),
      publicVoters: draft.anonymous === false,
      multipleChoice: !quiz && draft.multiple === true,
      quiz,
      question: withText(Api, draft.question),
      answers: draft.options.map(
        (option) => new Api.InputPollAnswer({ text: withText(Api, option) })
      ),
      hash: helpers.returnBigInt(0),
    }),
    ...(quiz ? { correctAnswers: [draft.correct] } : {}),
    ...(quiz && draft.solution
      ? { solution: String(draft.solution), solutionEntities: [] }
      : {}),
  });
};

// Who voted, by name: from the users and chats Telegram sent along.
const namesOf = (result) => {
  const names = new Map();
  for (const u of result?.users ?? []) {
    names.set(
      text(u.id),
      [u.firstName, u.lastName].filter(Boolean).join(' ') ||
        (u.username ? `@${u.username}` : null)
    );
  }
  for (const c of result?.chats ?? []) {
    names.set(`-${text(c.id)}`, c.title ?? null);
    names.set(`-100${text(c.id)}`, c.title ?? null);
  }
  return names;
};

const voteOf = (names) => (v) => {
  const peer = peerChatId(v.peer);
  const options = v.options ?? (v.option ? [v.option] : []);
  return {
    peer,
    name: names.get(peer) ?? null,
    options: options.map((o) => Buffer.from(o).toString('base64')),
    date: Number(v.date) || null,
  };
};

// A new poll or checklist (messages.sendMedia); Telegram's answer goes
// through the live handler, so it shows in the chat as other sends do.
// `media(Api, helpers, draft)` makes the InputMedia (R-Y195 shares this
// path for checklists, so Send as and paid confirmations apply to both).
const createMediaSender =
  (env, { userClient, apply }, { key, media }) =>
  async (draft = {}) => {
    const target = String(draft.chat ?? '');
    const own = target ? await userClient() : null;
    if (!own) {
      return { ok: false, supported: false };
    }
    const { Api, helpers } = await env.importer();
    try {
      const client = await withSendAs(
        env,
        own,
        draft.sendAs,
        draft.allowPaidStars
      );
      const result = await env.connection.withPeer(client, target, (peer) =>
        env.queue.run(`${key}:send:${target}`, 'view', () =>
          client.invoke(
            new Api.messages.SendMedia({
              peer,
              media: media(Api, helpers, draft),
              message: '',
              randomId: randomIdOf(draft.clientId, 0, helpers),
              clearDraft: false,
              ...(draft.silent ? { silent: true } : {}),
              ...(draft.scheduleDate
                ? { scheduleDate: draft.scheduleDate }
                : {}),
              ...replyHeader(Api, draft.replyTo, null),
            })
          )
        )
      );
      if (result && typeof result === 'object') {
        await apply(client, result);
      }
    } catch (error) {
      throw sendError(error);
    }
    if (draft.scheduleDate) {
      env.actions?.scheduledChanged?.(target);
      return { ok: true, chat: target, scheduled: true };
    }
    return { ok: true, chat: target };
  };

/** Checklist limits (Telegram's app-config defaults; R-Y195). */
export const TODO_LIMITS = { items: 30, title: 32, item: 64 };

// A new checklist as `InputMediaTodo`; tasks numbered from 1.
const newTodo = (Api, _helpers, draft) =>
  new Api.InputMediaTodo({
    todo: new Api.TodoList({
      othersCanAppend: draft.othersCanAppend === true,
      othersCanComplete: draft.othersCanComplete === true,
      title: withText(Api, draft.title),
      list: draft.items.map(
        (title, i) =>
          new Api.TodoItem({ id: i + 1, title: withText(Api, title) })
      ),
    }),
  });

// "Add tasks" (messages.appendTodoList): numbered on from the stored
// checklist's highest id, within the limit; only its author, or anyone
// when it lets others append (R-Y195).
const appendTodoOf = (withMessage, apply) => (request) =>
  withMessage(request, async (client, peer, Api, _h, link) => {
    const todo = link.raw?.media?.todo;
    const items = (request.items ?? []).map((i) => String(i).trim());
    const have = todo?.list ?? [];
    if (!todo) {
      return { ok: false, code: 'not-a-todo' };
    }
    if (!link.raw?.out && !todo.othersCanAppend) {
      return { ok: false, code: 'not-allowed' };
    }
    if (have.length + items.length > TODO_LIMITS.items) {
      return { ok: false, code: 'too-many' };
    }
    const first = Math.max(0, ...have.map((i) => Number(i.id))) + 1;
    const result = await client.invoke(
      new Api.messages.AppendTodoList({
        peer,
        msgId: msgIdOf(link),
        list: items.map(
          (title, i) =>
            new Api.TodoItem({ id: first + i, title: withText(Api, title) })
        ),
      })
    );
    await apply(client, result);
    return { ok: true, added: items.length };
  });

/**
 * The poll and checklist actions over the user's client. `apply(client,
 * result)` sends Telegram's answer through the live handler.
 */
export const createPollActions = (env, { userClient, apply }) => {
  const { store } = env;

  // `fn(client, peer, Api, helpers, link)` for one stored message.
  const withMessage = async ({ chat, id }, fn) => {
    const msgId = Number(id);
    const client = chat && msgId > 0 ? await userClient() : null;
    if (!client) {
      return { ok: false, supported: false };
    }
    const target = String(chat);
    const link = await store.get(`msg:${SOURCE}:${target}:${msgId}`);
    const { Api, helpers } = await env.importer();
    return env.connection.withPeer(client, target, (peer) =>
      fn(client, peer, Api, helpers, link ?? { id: `msg:x:${msgId}` })
    );
  };

  const vote = (request) =>
    withMessage(request, async (client, peer, Api, _h, link) => {
      const options = cleanOptions(request.options);
      const result = await env.queue.run(
        `vote:${request.chat}:${msgIdOf(link)}`,
        'view',
        () =>
          client.invoke(
            new Api.messages.SendVote({
              peer,
              msgId: msgIdOf(link),
              options: options.map(bytesOf),
            })
          )
      );
      await apply(client, result);
      return { ok: true, voted: options.length, retracted: !options.length };
    });

  const stop = (request) =>
    withMessage(request, async (client, peer, Api, helpers, link) => {
      const poll = link.raw?.media?.poll;
      if (!poll?.id) {
        return { ok: false, code: 'not-a-poll' };
      }
      const result = await client.invoke(
        new Api.messages.EditMessage({
          peer,
          id: msgIdOf(link),
          media: new Api.InputMediaPoll({
            poll: closedPoll(Api, helpers, poll),
          }),
        })
      );
      await apply(client, result);
      return { ok: true, stopped: msgIdOf(link) };
    });

  const results = (request) =>
    withMessage(request, async (client, peer, Api, helpers, link) => {
      const poll = link.raw?.media?.poll;
      const result = await env.queue.run(
        `poll-results:${request.chat}:${msgIdOf(link)}`,
        'prefetch',
        () =>
          client.invoke(
            new Api.messages.GetPollResults({
              peer,
              msgId: msgIdOf(link),
              pollHash: helpers.returnBigInt(String(poll?.hash ?? 0)),
            })
          )
      );
      await apply(client, result);
      return { ok: true };
    });

  const votes = (request) =>
    withMessage(request, async (client, peer, Api, _h, link) => {
      const result = await env.queue.run(
        `poll-votes:${request.chat}:${msgIdOf(link)}:${request.option ?? ''}:${request.offset ?? ''}`,
        'view',
        () =>
          client.invoke(
            new Api.messages.GetPollVotes({
              peer,
              id: msgIdOf(link),
              ...(request.option ? { option: bytesOf(request.option) } : {}),
              ...(request.offset ? { offset: String(request.offset) } : {}),
              limit: Math.min(Math.max(Number(request.limit) || 50, 1), 100),
            })
          )
      );
      const names = namesOf(result);
      return {
        ok: true,
        count: Number(result?.count ?? 0),
        nextOffset: result?.nextOffset ?? null,
        votes: (result?.votes ?? []).map(voteOf(names)),
      };
    });

  const toggleTodo = (request) =>
    withMessage(request, async (client, peer, Api, _h, link) => {
      const result = await client.invoke(
        new Api.messages.ToggleTodoCompleted({
          peer,
          msgId: msgIdOf(link),
          completed: cleanIds(request.completed),
          incompleted: cleanIds(request.incompleted),
        })
      );
      await apply(client, result);
      return { ok: true };
    });

  return {
    sendPoll: createMediaSender(
      env,
      { userClient, apply },
      { key: 'poll', media: newPoll }
    ),
    sendTodo: createMediaSender(
      env,
      { userClient, apply },
      { key: 'todo', media: newTodo }
    ),
    appendTodo: appendTodoOf(withMessage, apply),
    votePoll: vote,
    stopPoll: stop,
    pollResults: results,
    pollVotes: votes,
    toggleTodo,
  };
};

/**
 * Privacy and security of the connected account, as Telegram Desktop's
 * Settings → Privacy and Security has it (R-Y139; learned, never copied):
 * - `privacyRules()` — account.getPrivacy for each key → `{ ok, keys:
 *   [{ key, choice, label, allow, disallow, options }] }`; `choice` is
 *   `everybody`, `contacts`, `nobody` or `other` (then `label` names it:
 *   `close-friends`, `premium` or `except-contacts`), `allow` and
 *   `disallow` count the exceptions (people and chats) and are only
 *   shown, never edited;
 * - `setPrivacy({ key, choice })` — account.setPrivacy with the base rule
 *   of the choice and the existing exceptions KEPT: the users come back
 *   with their access hashes in the answer to getPrivacy and go out as
 *   InputUser; the chats go out as the same ids; the bots rules stay. A
 *   key whose exceptions cannot all be converted is refused
 *   (`exceptions-unsupported`), never saved with fewer;
 * - `sessions()` — account.getAuthorizations → `{ ok, ttlDays, sessions }`;
 *   `terminateSession({ hash })` — account.resetAuthorization (never the
 *   current session); `terminateOthers()` — auth.resetAuthorizations;
 * - `blockedUsers({ offset, limit })` — contacts.getBlocked → `{ ok,
 *   count, items, next }`; `unblockUser({ id, accessHash })` —
 *   contacts.unblock.
 * - `defaultTtl()` — messages.getDefaultHistoryTTL → `{ ok, period }`
 *   (seconds, 0 off); `setDefaultTtl({ period })` —
 *   messages.setDefaultHistoryTTL, the timer new chats start with
 *   (R-Y151; the period is one of TTL_PERIODS).
 * Telegram's errors become codes the page shows as text.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';
import { TTL_PERIODS } from './telegram-ttl.js';

/** The page's key → the InputPrivacyKey constructor. */
export const PRIVACY_KEYS = {
  phoneNumber: 'InputPrivacyKeyPhoneNumber',
  addedByPhone: 'InputPrivacyKeyAddedByPhone',
  lastSeen: 'InputPrivacyKeyStatusTimestamp',
  profilePhoto: 'InputPrivacyKeyProfilePhoto',
  about: 'InputPrivacyKeyAbout',
  birthday: 'InputPrivacyKeyBirthday',
  forwards: 'InputPrivacyKeyForwards',
  calls: 'InputPrivacyKeyPhoneCall',
  voiceMessages: 'InputPrivacyKeyVoiceMessages',
  invites: 'InputPrivacyKeyChatInvite',
};
export const CHOICES = ['everybody', 'contacts', 'nobody'];
// "Who can find me by my number" is only everybody or my contacts.
const FIND_CHOICES = ['everybody', 'contacts'];
export const PAGE_MAX = 100;

const CODES = {
  FRESH_RESET_AUTHORISATION_FORBIDDEN: 'fresh-reset',
  HASH_INVALID: 'hash-invalid',
  PRIVACY_TOO_LONG: 'privacy-too-long',
  PRIVACY_KEY_INVALID: 'key-invalid',
  PRIVACY_VALUE_INVALID: 'value-invalid',
  USER_ID_INVALID: 'user-invalid',
  TTL_PERIOD_INVALID: 'bad-period',
  FLOOD_WAIT: 'flood',
};
const failure = failureOf(CODES);

const bad = (code) => ({ ok: false, error: code, code });
const textOf = (value) => String(value?.value ?? value);

const optionsOf = (key) => (key === 'addedByPhone' ? FIND_CHOICES : CHOICES);

// The base rules decide the choice; these beside them make it "other".
const BASES = {
  PrivacyValueAllowAll: 'everybody',
  PrivacyValueAllowContacts: 'contacts',
  PrivacyValueDisallowAll: 'nobody',
};
const LABELS = {
  PrivacyValueAllowCloseFriends: 'close-friends',
  PrivacyValueAllowPremium: 'premium',
  PrivacyValueDisallowContacts: 'except-contacts',
};
const USER_RULES = ['PrivacyValueAllowUsers', 'PrivacyValueDisallowUsers'];
const CHAT_RULES = [
  'PrivacyValueAllowChatParticipants',
  'PrivacyValueDisallowChatParticipants',
];
// The bots rules are neither a choice nor an exception: kept as they are.
const KEPT_OTHER = {
  PrivacyValueAllowBots: 'InputPrivacyValueAllowBots',
  PrivacyValueDisallowBots: 'InputPrivacyValueDisallowBots',
};

const nameOfRule = (rule) => String(rule?.className ?? '');

/**
 * The rules Telegram returned as the page shows them: the choice, a label
 * when it is none of the three, and the exception counts.
 */
export const choiceOf = (rules) => {
  const counts = { allow: 0, disallow: 0 };
  let choice = null;
  let label = null;
  for (const rule of rules ?? []) {
    const name = nameOfRule(rule);
    if (USER_RULES.includes(name) || CHAT_RULES.includes(name)) {
      const side = name.includes('Disallow') ? 'disallow' : 'allow';
      counts[side] += (rule.users ?? rule.chats ?? []).length;
    } else if (BASES[name]) {
      choice = BASES[name];
    } else if (LABELS[name]) {
      label = label ?? LABELS[name];
    }
  }
  return label
    ? { choice: 'other', label, ...counts }
    : { choice: choice ?? 'nobody', label: null, ...counts };
};

// A rule's people as InputUser, from the users the answer carries; null
// when one of them has no access hash there.
const inputUsers = (c, rule, users) => {
  const out = [];
  for (const id of rule.users ?? []) {
    const user = users.get(textOf(id));
    if (!user || user.accessHash === undefined || user.accessHash === null) {
      return null;
    }
    out.push(
      new c.Api.InputUser({
        userId: c.helpers.returnBigInt(textOf(id)),
        accessHash: user.accessHash,
      })
    );
  }
  return out;
};

const BASE_INPUT = {
  everybody: 'InputPrivacyValueAllowAll',
  contacts: 'InputPrivacyValueAllowContacts',
  nobody: 'InputPrivacyValueDisallowAll',
};

// One existing rule as its input form: the exceptions kept, the bots
// rules passed on, every other rule dropped (the choice replaces it).
// `undefined` drops it; null means it cannot be converted.
const inputRule = (c, rule, users) => {
  const name = nameOfRule(rule);
  if (USER_RULES.includes(name)) {
    const list = inputUsers(c, rule, users);
    return list && new c.Api[`Input${name}`]({ users: list });
  }
  if (CHAT_RULES.includes(name)) {
    return new c.Api[`Input${name}`]({
      chats: (rule.chats ?? []).map((id) => c.helpers.returnBigInt(textOf(id))),
    });
  }
  return KEPT_OTHER[name] ? new c.Api[KEPT_OTHER[name]]() : undefined;
};

/**
 * The input rules for a new choice, the existing exceptions kept; null
 * when one of them cannot be converted.
 */
export const rulesFor = (c, answer, choice) => {
  const users = new Map((answer?.users ?? []).map((u) => [textOf(u.id), u]));
  const out = [];
  for (const rule of answer?.rules ?? []) {
    const converted = inputRule(c, rule, users);
    if (converted === null || converted === false) {
      return null;
    }
    if (converted) {
      out.push(converted);
    }
  }
  return [...out, new c.Api[BASE_INPUT[choice]]()];
};

const summary = (key, answer) => ({
  key,
  ...choiceOf(answer?.rules),
  options: optionsOf(key),
});

const ask = (env, c, queue, request) =>
  runIn(env, `privacy:${queue}`, () => c.client.invoke(request));

const getRules = (env, c, key) =>
  ask(
    env,
    c,
    key,
    new c.Api.account.GetPrivacy({ key: new c.Api[PRIVACY_KEYS[key]]() })
  );

const readRules = (env, userClient) => async () =>
  connected(env, userClient, failure, async (c) => {
    const keys = [];
    let first = null;
    for (const key of Object.keys(PRIVACY_KEYS)) {
      if (!c.Api[PRIVACY_KEYS[key]]) {
        continue;
      }
      try {
        keys.push(summary(key, await getRules(env, c, key)));
      } catch (error) {
        first = first ?? error;
      }
    }
    return keys.length === 0 && first ? failure(first) : { ok: true, keys };
  });

const writeRule =
  (env, userClient) =>
  async (request = {}) => {
    const { key, choice } = request;
    if (!Object.hasOwn(PRIVACY_KEYS, key) || !optionsOf(key).includes(choice)) {
      return bad('bad-request');
    }
    return connected(env, userClient, failure, async (c) => {
      const rules = rulesFor(c, await getRules(env, c, key), choice);
      if (!rules) {
        return bad('exceptions-unsupported');
      }
      const next = await ask(
        env,
        c,
        key,
        new c.Api.account.SetPrivacy({
          key: new c.Api[PRIVACY_KEYS[key]](),
          rules,
        })
      );
      return { ok: true, ...summary(key, next) };
    });
  };

const iso = (seconds) =>
  Number.isFinite(Number(seconds)) && seconds
    ? new Date(Number(seconds) * 1000).toISOString()
    : null;

/** An Authorization as the page lists it. */
export const sessionOf = (a) => ({
  hash: textOf(a.hash),
  current: Boolean(a.current),
  official: Boolean(a.officialApp),
  // R-Y177: Telegram's flags say what is refused.
  secretChats: !a.encryptedRequestsDisabled,
  calls: !a.callRequestsDisabled,
  pending: Boolean(a.unconfirmed),
  device: a.deviceModel ?? '',
  platform: a.platform ?? '',
  system: a.systemVersion ?? '',
  app: a.appName ?? '',
  appVersion: a.appVersion ?? '',
  ip: a.ip ?? '',
  country: a.country ?? '',
  region: a.region ?? '',
  created: iso(a.dateCreated),
  active: iso(a.dateActive),
});

const authorizations = (env, c) =>
  ask(env, c, 'sessions', new c.Api.account.GetAuthorizations());

const readSessions = (env, userClient) => async () =>
  connected(env, userClient, failure, async (c) => {
    const answer = await authorizations(env, c);
    return {
      ok: true,
      ttlDays: Number(answer?.authorizationTtlDays ?? 0),
      sessions: (answer?.authorizations ?? []).map(sessionOf),
    };
  });

const endOne =
  (env, userClient) =>
  async (request = {}) => {
    const hash = String(request.hash ?? '');
    if (!/^-?\d{1,20}$/.test(hash)) {
      return bad('bad-request');
    }
    return connected(env, userClient, failure, async (c) => {
      // Never the session in use: Telegram would log this app out.
      const list = await authorizations(env, c);
      const mine = (list?.authorizations ?? []).find((a) => a.current);
      if (mine && textOf(mine.hash) === hash) {
        return bad('current-session');
      }
      await ask(
        env,
        c,
        'sessions',
        new c.Api.account.ResetAuthorization({
          hash: c.helpers.returnBigInt(hash),
        })
      );
      return { ok: true };
    });
  };

const endOthers = (env, userClient) => async () =>
  connected(env, userClient, failure, async (c) => {
    await ask(env, c, 'sessions', new c.Api.auth.ResetAuthorizations());
    return { ok: true };
  });

const personName = (user) =>
  [user?.firstName, user?.lastName].filter(Boolean).join(' ') ||
  user?.username ||
  '';

const blockedItem = (b, users) => {
  const id = textOf(b.peerId.userId);
  const user = users.get(id) ?? {};
  return {
    id,
    accessHash:
      user.accessHash === undefined || user.accessHash === null
        ? ''
        : textOf(user.accessHash),
    name: personName(user),
    username: user.username ?? '',
  };
};

const readBlocked =
  (env, userClient) =>
  async (request = {}) => {
    const offset = Math.max(0, Math.trunc(Number(request.offset ?? 0)));
    const limit = Math.min(PAGE_MAX, Math.max(1, Number(request.limit ?? 50)));
    return connected(env, userClient, failure, async (c) => {
      const answer = await ask(
        env,
        c,
        'blocked',
        new c.Api.contacts.GetBlocked({ offset, limit })
      );
      const users = new Map(
        (answer?.users ?? []).map((u) => [textOf(u.id), u])
      );
      const rows = answer?.blocked ?? [];
      const count = Number(answer?.count ?? offset + rows.length);
      return {
        ok: true,
        count,
        items: rows
          .filter((b) => b?.peerId?.className === 'PeerUser')
          .map((b) => blockedItem(b, users)),
        next:
          rows.length > 0 && offset + rows.length < count
            ? offset + rows.length
            : null,
      };
    });
  };

const unblock =
  (env, userClient) =>
  async (request = {}) => {
    const id = String(request.id ?? '');
    const hash = String(request.accessHash ?? '');
    if (!/^\d{1,20}$/.test(id) || !/^-?\d{1,20}$/.test(hash)) {
      return bad('bad-request');
    }
    return connected(env, userClient, failure, async (c) => {
      await ask(
        env,
        c,
        'blocked',
        new c.Api.contacts.Unblock({
          id: new c.Api.InputPeerUser({
            userId: c.helpers.returnBigInt(id),
            accessHash: c.helpers.returnBigInt(hash),
          }),
        })
      );
      return { ok: true };
    });
  };

const readDefaultTtl = (env, userClient) => async () =>
  connected(env, userClient, failure, async (c) => {
    const answer = await ask(
      env,
      c,
      'default-ttl',
      new c.Api.messages.GetDefaultHistoryTTL()
    );
    return { ok: true, period: Number(answer?.period ?? 0) || 0 };
  });

const writeDefaultTtl =
  (env, userClient) =>
  async (request = {}) => {
    const { period } = request;
    if (!TTL_PERIODS.includes(period)) {
      return bad('bad-request');
    }
    return connected(env, userClient, failure, async (c) => {
      await ask(
        env,
        c,
        'default-ttl',
        new c.Api.messages.SetDefaultHistoryTTL({ period })
      );
      return { ok: true, period };
    });
  };

export const createPrivacy = (env, context) => ({
  defaultTtl: readDefaultTtl(env, context.userClient),
  setDefaultTtl: writeDefaultTtl(env, context.userClient),
  privacyRules: readRules(env, context.userClient),
  setPrivacy: writeRule(env, context.userClient),
  sessions: readSessions(env, context.userClient),
  terminateSession: endOne(env, context.userClient),
  terminateOthers: endOthers(env, context.userClient),
  blockedUsers: readBlocked(env, context.userClient),
  unblockUser: unblock(env, context.userClient),
});

/**
 * Private (one-to-one) voice calls, as Telegram's clients place and take
 * them (R-Y196; learned, never copied). Nothing rings, dials or asks for
 * the microphone by itself: every write below answers a click, except
 * answering Telegram's own updates (receivedCall, the DH steps).
 *
 * The call's state machine and its Diffie-Hellman key stay on the server
 * (./private-call-machine.js, ./private-call-dh.js); the page reads the
 * view of the call from the link `phonecall:telegram` (streamed like the
 * other live links) and only ever sees the emoji of the key.
 *
 * - `privateCallStart({ user, name? })` — "Call" in a private chat's
 *   header: phone.getCallConfig, messages.getDhConfig, phone.requestCall
 *   with g_a_hash → `{ ok, callId }`;
 * - `privateCallAccept({ id })` — Accept: phone.receivedCall already
 *   answered when it rang; now messages.getDhConfig and phone.acceptCall
 *   with g_b;
 * - `privateCallDiscard({ id, reason? })` — Decline / End / ring timeout:
 *   phone.discardCall with the duration and the reason (hangup, missed,
 *   busy, disconnect);
 * - `privateCallRate({ id, rating, comment? })` — phone.setCallRating
 *   after the call (1 to 5);
 * - `privateCallState()` — the call's view now or null;
 * - `phoneCalls.handle(client, effect)` (internal) — UpdatePhoneCall from
 *   the live handler drives the machine (the update's phoneCallRequested /
 *   phoneCallWaiting / phoneCallAccepted / phoneCall / phoneCallDiscarded);
 *   UpdatePhoneCallSignalingData is read and dropped.
 * Media is not done (see ./private-call-machine.js): the view says
 * `media: false`, and the PhoneConnectionWebrtc servers are only counted.
 * Telegram's errors become codes the page shows as text.
 */

import crypto from 'node:crypto';
import { connected, failureOf } from './telegram-stickers.js';
import { inputUserOf } from './telegram-peer-actions.js';
import {
  createCallMachine,
  DISCARD_REASONS,
  PROTOCOL,
} from './private-call-machine.js';

const CODES = {
  USER_PRIVACY_RESTRICTED: 'privacy',
  USER_IS_BLOCKED: 'blocked',
  PARTICIPANT_VERSION_OUTDATED: 'outdated',
  CALL_PROTOCOL_LAYER_INVALID: 'outdated',
  CALL_PROTOCOL_FLAGS_INVALID: 'outdated',
  CALL_ALREADY_ACCEPTED: 'answered',
  CALL_ALREADY_DECLINED: 'gone',
  CALL_PEER_INVALID: 'gone',
  CALL_OCCUPY_FAILED: 'busy',
  USER_ID_INVALID: 'no-access',
  PEER_ID_INVALID: 'no-access',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);
const codeOf = (error) => failure(error).code;
const bad = () => ({ ok: false, error: 'bad request', code: 'failed' });

export const LINK_ID = 'phonecall:telegram';

const DIGITS = /^\d{1,20}$/;
const text = (value) => String(value ?? '');

/** Whether a body names a call: its id as digits. */
export const validCallId = (body) =>
  typeof body?.id === 'string' && DIGITS.test(body.id);

export const validStart = (body) =>
  typeof body?.user === 'string' &&
  DIGITS.test(body.user) &&
  (body.name === undefined ||
    (typeof body.name === 'string' && body.name.length <= 200));

export const validDiscard = (body) =>
  validCallId(body) &&
  (body.reason === undefined || DISCARD_REASONS.includes(body.reason));

export const validRating = (body) =>
  validCallId(body) &&
  Number.isInteger(body.rating) &&
  body.rating >= 1 &&
  body.rating <= 5 &&
  (body.comment === undefined ||
    (typeof body.comment === 'string' && body.comment.length <= 400));

const REASON_CLASS = {
  hangup: 'PhoneCallDiscardReasonHangup',
  missed: 'PhoneCallDiscardReasonMissed',
  busy: 'PhoneCallDiscardReasonBusy',
  disconnect: 'PhoneCallDiscardReasonDisconnect',
};

const nameOf = (entity) =>
  [entity?.firstName, entity?.lastName].filter(Boolean).join(' ') ||
  entity?.username ||
  '';

/** The machine's `api` for one connected client (and the update's users). */
export const apiOf = (env, c, entities = null) => {
  const big = (value) => c.helpers.returnBigInt(text(value));
  const peer = ({ id, accessHash }) =>
    new c.Api.InputPhoneCall({ id: big(id), accessHash: big(accessHash) });
  const protocol = () => new c.Api.PhoneCallProtocol({ ...PROTOCOL });
  const call = (request) => c.client.invoke(request);
  return {
    dhConfig: async () => {
      const answer = await call(
        new c.Api.messages.GetDhConfig({ version: 0, randomLength: 256 })
      );
      return {
        g: answer.g,
        p: answer.p,
        version: answer.version,
        random: answer.random,
      };
    },
    callConfig: () => call(new c.Api.phone.GetCallConfig()),
    request: async ({ user, gaHash, video }) =>
      call(
        new c.Api.phone.RequestCall({
          userId: await env.connection.withPeer(c.client, user, (p) =>
            inputUserOf(c, p)
          ),
          randomId: crypto.randomInt(-(2 ** 31), 2 ** 31),
          gAHash: gaHash,
          protocol: protocol(),
          ...(video ? { video: true } : {}),
        })
      ),
    accept: (args) =>
      call(
        new c.Api.phone.AcceptCall({
          peer: peer(args),
          gB: args.gb,
          protocol: protocol(),
        })
      ),
    confirm: (args) =>
      call(
        new c.Api.phone.ConfirmCall({
          peer: peer(args),
          gA: args.ga,
          keyFingerprint: big(args.fingerprint),
          protocol: protocol(),
        })
      ),
    received: (args) =>
      call(new c.Api.phone.ReceivedCall({ peer: peer(args) })),
    discard: (args) =>
      call(
        new c.Api.phone.DiscardCall({
          peer: peer(args),
          duration: Number(args.duration) || 0,
          reason: new c.Api[REASON_CLASS[args.reason] ?? REASON_CLASS.hangup](),
          connectionId: c.zero,
        })
      ),
    rate: (args) =>
      call(
        new c.Api.phone.SetCallRating({
          userInitiative: true,
          peer: peer(args),
          rating: args.rating,
          comment: text(args.comment),
        })
      ),
    nameOf: async (user) => {
      const known = entities?.get?.(text(user));
      if (known) {
        return nameOf(known);
      }
      try {
        return nameOf(await c.client.getEntity(big(user)));
      } catch {
        return '';
      }
    },
  };
};

// The call's view as a link the page follows.
const writer = (env) => async (view) => {
  await env.store.put({
    id: LINK_ID,
    tokens: ['phonecall', 'telegram'],
    kind: 'phone-call',
    source: 'telegram',
    ...view,
    at: new Date((env.now ?? Date.now)()).toISOString(),
  });
};

// A call left over from before a restart is over.
const closeStale = async (env, publish) => {
  const before = await env.store.get(LINK_ID).catch(() => null);
  if (before && before.phase !== 'ended') {
    await publish({
      ...before,
      phase: 'ended',
      reason: 'failed',
      code: 'restart',
      needRating: false,
      endedAt: (env.now ?? Date.now)(),
    });
  }
};

export const createPrivateCall = (env, { userClient }) => {
  const publish = writer(env);
  const machine = createCallMachine({
    now: env.now ?? Date.now,
    publish,
    codeOf,
  });
  closeStale(env, publish).catch(() => {});

  const run = (use) => connected(env, userClient, failure, use);
  const done = (answer) =>
    answer.ok ? answer : { ok: false, error: answer.code, code: answer.code };

  // UpdatePhoneCall of the live handler.
  env.phoneCalls = {
    handle: async (client, effect) => {
      const { Api, helpers } = await env.importer();
      const c = { client, Api, helpers, zero: helpers.returnBigInt(0) };
      await machine.onUpdate(apiOf(env, c, effect.entities), effect.phoneCall);
    },
  };

  const privateCallStart = async (body = {}) =>
    validStart(body)
      ? run(async (c) =>
          done(
            await machine.start(apiOf(env, c), {
              user: body.user,
              name: body.name,
            })
          )
        )
      : bad();

  const privateCallAccept = async (body = {}) =>
    validCallId(body)
      ? run(async (c) => done(await machine.accept(apiOf(env, c), body)))
      : bad();

  const privateCallDiscard = async (body = {}) =>
    validDiscard(body)
      ? run(async (c) => done(await machine.discard(apiOf(env, c), body)))
      : bad();

  const privateCallRate = async (body = {}) =>
    validRating(body)
      ? run(async (c) => done(await machine.rate(apiOf(env, c), body)))
      : bad();

  const privateCallState = async () => ({ ok: true, call: machine.view() });

  return {
    privateCallStart,
    privateCallAccept,
    privateCallDiscard,
    privateCallRate,
    privateCallState,
  };
};

/**
 * Profile extras, as Telegram Desktop has them (R-Y178; learned, never
 * copied): a birthday, a name colour and a profile colour (Premium), a
 * personal channel — the user's own, and other people's on their profiles.
 * - `profileExtras()` → `{ ok, premium, birthday, color, profileColor,
 *   personalChannel }` from users.getFullUser of the user; a colour is
 *   `{ color, emoji }` (the palette index and the background emoji's
 *   document id as a decimal string) or null, a birthday `{ day, month,
 *   year? }`, the personal channel `{ chat, title }`.
 * - `birthdaySave({ day, month, year? } | { remove: true })` —
 *   account.updateBirthday.
 * - `colors()` → `{ ok, name, profile }`: help.getPeerColors and
 *   help.getPeerProfileColors (kept by their hash for the session), each
 *   option `{ id, colors, dark? }` with `#rrggbb` strings.
 * - `colorSave({ forProfile, color?, emoji? })` — account.updateColor;
 *   neither colour nor emoji removes it. Premium only: the code `premium`.
 * - `personalChannels()` → `{ ok, channels }` — channels.getAdminedPublicChannels
 *   with `forPersonal`; `personalChannelSave({ chat } | { remove: true })` —
 *   account.updatePersonalChannel with one of those channels.
 * - `personalChannelCard({ chat })` → `{ ok, card: null | { chat, title,
 *   username, members, message } }` — a person's personal channel with its
 *   latest post (the one UserFull names), read-only.
 * - `birthdays()` → `{ ok, birthdays: [{ chat, name, day, month, year? }] }`
 *   — contacts.getBirthdays, the contacts whose birthday is today or soon.
 * Telegram's errors become codes the page shows as text.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';
import { inputUserOf } from './telegram-peer-actions.js';

const CODES = {
  PREMIUM_ACCOUNT_REQUIRED: 'premium',
  BIRTHDAY_INVALID: 'birthday-invalid',
  CHANNEL_INVALID: 'no-channel',
  CHANNELS_ADMIN_PUBLIC_TOO_MUCH: 'no-channel',
  PEER_ID_INVALID: 'no-user',
  USER_ID_INVALID: 'no-user',
  COLOR_INVALID: 'color-invalid',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);
const bad = (code) => ({ ok: false, error: code, code });
const text = (value) => String(value?.value ?? value);
const USER = /^\d{1,20}$/;
const EMOJI = /^\d{1,20}$/;
export const MAX_COLOR = 20;
export const BIRTHDAY_DAYS = 7;

const DAYS = [31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

/** Whether `{ day, month, year? }` is a date that can exist. */
export const validBirthday = (b) =>
  Number.isInteger(b?.month) &&
  b.month >= 1 &&
  b.month <= 12 &&
  Number.isInteger(b.day) &&
  b.day >= 1 &&
  b.day <= DAYS[b.month - 1] &&
  (b.year === undefined ||
    (Number.isInteger(b.year) &&
      b.year >= 1900 &&
      b.year <= 2100 &&
      (b.day !== 29 || b.month !== 2 || b.year % 4 === 0)));

/** `{ day, month, year? }` of a Birthday, else null. */
export const birthdayOf = (raw) =>
  Number.isInteger(raw?.day) && Number.isInteger(raw?.month)
    ? {
        day: raw.day,
        month: raw.month,
        ...(Number.isInteger(raw.year) && raw.year > 0
          ? { year: raw.year }
          : {}),
      }
    : null;

/** `{ color, emoji }` of a PeerColor (a collectible has only its emoji). */
export const colorOf = (raw) => {
  if (!raw || typeof raw !== 'object') {
    return null;
  }
  const color = Number.isInteger(raw.color) ? raw.color : null;
  const emoji =
    raw.backgroundEmojiId === undefined || raw.backgroundEmojiId === null
      ? null
      : text(raw.backgroundEmojiId);
  return color === null && emoji === null ? null : { color, emoji };
};

const hex = (n) => `#${(Number(n) & 0xffffff).toString(16).padStart(6, '0')}`;

// The colours of one set: a name colour's list, a profile colour's
// palette and background colours.
const setColors = (set) => {
  const list = set?.bgColors?.length
    ? set.bgColors
    : (set?.paletteColors ?? set?.colors);
  return Array.isArray(list) && list.length > 0 ? list.map(hex) : null;
};

/** `{ id, colors, dark? }` of the options of help.peerColors; hidden dropped. */
export const optionsOf = (answer) =>
  (answer?.colors ?? [])
    .filter((o) => o && !o.hidden && Number.isInteger(o.colorId))
    .map((o) => {
      const colors = setColors(o.colors);
      const dark = setColors(o.darkColors);
      return colors
        ? { id: o.colorId, colors, ...(dark ? { dark } : {}) }
        : null;
    })
    .filter(Boolean);

const postOf = (message) => {
  if (!message || message.className === 'MessageEmpty') {
    return null;
  }
  const body = String(message.message ?? '');
  return { id: Number(message.id), text: body.slice(0, 280) };
};

const channelOf = (raw) =>
  raw?.className === 'Channel'
    ? {
        chat: `-100${text(raw.id)}`,
        title: raw.title ?? '',
        username: raw.username ?? '',
        members: Number.isInteger(raw.participantsCount)
          ? raw.participantsCount
          : null,
      }
    : null;

/**
 * Whole days from `now` to the next `day`/`month` (0: today); a 29
 * February in a year without one falls on 1 March, as Date does.
 */
export const daysUntil = (birthday, now) => {
  const base = Date.UTC(now.getFullYear(), now.getMonth(), now.getDate());
  for (const year of [now.getFullYear(), now.getFullYear() + 1]) {
    const days = Math.round(
      (Date.UTC(year, birthday.month - 1, birthday.day) - base) / 86_400_000
    );
    if (days >= 0) {
      return days;
    }
  }
  return Infinity;
};

const ask = (env, c, key, request) =>
  runIn(env, key, () => c.client.invoke(request));

// The full user of `id` with the user entity and the chats named.
const fullOf = async (env, c, id) => {
  const answer = await ask(
    env,
    c,
    'profile-extras:user',
    new c.Api.users.GetFullUser({ id })
  );
  const users = answer?.users ?? [];
  const self = id.className === 'InputUserSelf';
  const user =
    users.find((u) => (self ? u?.self : text(u?.id) === text(id.userId))) ??
    users[0] ??
    {};
  return { full: answer?.fullUser ?? {}, user, chats: answer?.chats ?? [] };
};

const personalOf = (f, chats) =>
  channelOf(chats.find((x) => text(x?.id) === text(f.personalChannelId ?? '')));

const createOwn = (env, userClient) => ({
  profileExtras: async () =>
    connected(env, userClient, failure, async (c) => {
      const {
        full: f,
        user,
        chats,
      } = await fullOf(env, c, new c.Api.InputUserSelf());
      const channel = personalOf(f, chats);
      return {
        ok: true,
        premium: Boolean(user.premium),
        birthday: birthdayOf(f.birthday),
        color: colorOf(user.color),
        profileColor: colorOf(user.profileColor),
        personalChannel: channel
          ? { chat: channel.chat, title: channel.title }
          : null,
      };
    }),
  birthdaySave: async (request = {}) => {
    const remove = request.remove === true;
    if (!remove && !validBirthday(request)) {
      return bad('birthday-invalid');
    }
    return connected(env, userClient, failure, async (c) => {
      const { day, month, year } = request;
      await ask(
        env,
        c,
        'profile-extras:birthday',
        new c.Api.account.UpdateBirthday(
          remove
            ? {}
            : {
                birthday: new c.Api.Birthday({
                  day,
                  month,
                  ...(year === undefined ? {} : { year }),
                }),
              }
        )
      );
      return { ok: true };
    });
  },
});

const colorRefused = ({ forProfile, color, emoji }) =>
  typeof forProfile !== 'boolean' ||
  (color !== undefined &&
    !(Number.isInteger(color) && color >= 0 && color <= MAX_COLOR)) ||
  (emoji !== undefined && !EMOJI.test(String(emoji)));

// The PeerColor to set; nothing when neither colour nor emoji is given.
const peerColorOf = (c, { color, emoji }) =>
  color === undefined && emoji === undefined
    ? {}
    : {
        color: new c.Api.PeerColor({
          ...(color === undefined ? {} : { color }),
          ...(emoji === undefined
            ? {}
            : { backgroundEmojiId: c.helpers.returnBigInt(emoji) }),
        }),
      };

const createColors = (env, userClient) => {
  const kept = { name: null, profile: null };
  const palette = async (c, which) => {
    const Method =
      which === 'name'
        ? c.Api.help.GetPeerColors
        : c.Api.help.GetPeerProfileColors;
    const answer = await ask(
      env,
      c,
      `profile-extras:${which}`,
      new Method({ hash: kept[which]?.hash ?? 0 })
    );
    if (answer?.className === 'help.PeerColorsNotModified' && kept[which]) {
      return kept[which].options;
    }
    const options = optionsOf(answer);
    kept[which] = { hash: Number(answer?.hash) || 0, options };
    return options;
  };
  return {
    profileColors: async () =>
      connected(env, userClient, failure, async (c) => ({
        ok: true,
        name: await palette(c, 'name'),
        profile: await palette(c, 'profile'),
      })),
    colorSave: async (request = {}) =>
      colorRefused(request)
        ? bad('color-invalid')
        : connected(env, userClient, failure, async (c) => {
            await ask(
              env,
              c,
              'profile-extras:color',
              new c.Api.account.UpdateColor({
                ...(request.forProfile ? { forProfile: true } : {}),
                ...peerColorOf(c, request),
              })
            );
            return { ok: true };
          }),
  };
};

const createChannels = (env, userClient) => {
  const admined = async (c) => {
    const answer = await ask(
      env,
      c,
      'profile-extras:channels',
      new c.Api.channels.GetAdminedPublicChannels({ forPersonal: true })
    );
    return (answer?.chats ?? []).filter((x) => x?.className === 'Channel');
  };
  // The InputChannel of one of the user's public channels, or null.
  const inputOf = async (c, chat) => {
    const found = (await admined(c)).find((x) => `-100${text(x.id)}` === chat);
    return found
      ? new c.Api.InputChannel({
          channelId: found.id,
          accessHash: found.accessHash,
        })
      : null;
  };
  return {
    personalChannels: async () =>
      connected(env, userClient, failure, async (c) => ({
        ok: true,
        channels: (await admined(c)).map(channelOf).filter(Boolean),
      })),
    personalChannelSave: async (request = {}) => {
      const remove = request.remove === true;
      const chat = String(request.chat ?? '');
      if (!remove && !/^-100\d{1,20}$/.test(chat)) {
        return bad('no-channel');
      }
      return connected(env, userClient, failure, async (c) => {
        const channel = remove
          ? new c.Api.InputChannelEmpty()
          : await inputOf(c, chat);
        if (!channel) {
          return bad('no-channel');
        }
        await ask(
          env,
          c,
          'profile-extras:personal',
          new c.Api.account.UpdatePersonalChannel({ channel })
        );
        return { ok: true };
      });
    },
  };
};

// A person's personal channel: its entity, subscribers, the post named.
const cardOf = async (env, c, chat) => {
  const id = await env.connection.withPeer(c.client, chat, (peer) =>
    inputUserOf(c, peer)
  );
  const { full: f, chats } = await fullOf(env, c, id);
  const channel = personalOf(f, chats);
  if (!channel) {
    return null;
  }
  const raw = chats.find((x) => `-100${text(x?.id)}` === channel.chat);
  const input = new c.Api.InputChannel({
    channelId: raw.id,
    accessHash: raw.accessHash,
  });
  const [messages, info] = await Promise.all([
    f.personalChannelMessage
      ? ask(
          env,
          c,
          'profile-extras:post',
          new c.Api.channels.GetMessages({
            channel: input,
            id: [new c.Api.InputMessageID({ id: f.personalChannelMessage })],
          })
        ).catch(() => null)
      : null,
    ask(
      env,
      c,
      'profile-extras:channel',
      new c.Api.channels.GetFullChannel({ channel: input })
    ).catch(() => null),
  ]);
  const members = info?.fullChat?.participantsCount;
  return {
    ...channel,
    members: Number.isInteger(members) ? members : channel.members,
    message: postOf((messages?.messages ?? [])[0]),
  };
};

const nameOfUser = (user, id) =>
  [user.firstName, user.lastName].filter(Boolean).join(' ') ||
  user.username ||
  id;

// The contacts whose birthday is within a week, nearest first.
const soonOf = (answer, today) => {
  const byId = new Map((answer?.users ?? []).map((u) => [text(u.id), u]));
  return (answer?.contacts ?? [])
    .map((entry) => {
      const birthday = birthdayOf(entry.birthday);
      const id = text(entry.contactId);
      const days = birthday ? daysUntil(birthday, today) : Infinity;
      return birthday && days <= BIRTHDAY_DAYS
        ? {
            chat: id,
            name: nameOfUser(byId.get(id) ?? {}, id),
            ...birthday,
            days,
          }
        : null;
    })
    .filter(Boolean)
    .sort((a, b) => a.days - b.days);
};

const createPeople = (env, userClient) => ({
  personalChannelCard: async (request = {}) => {
    const chat = String(request.chat ?? '');
    if (!USER.test(chat)) {
      return bad('no-user');
    }
    return connected(env, userClient, failure, async (c) => ({
      ok: true,
      card: await cardOf(env, c, chat),
    }));
  },
  contactBirthdays: async () =>
    connected(env, userClient, failure, async (c) => {
      const answer = await ask(
        env,
        c,
        'profile-extras:birthdays',
        new c.Api.contacts.GetBirthdays()
      );
      const today = new Date((env.now ?? Date.now)());
      return { ok: true, birthdays: soonOf(answer, today) };
    }),
});

export const createProfileExtras = (env, { userClient }) => ({
  ...createOwn(env, userClient),
  ...createColors(env, userClient),
  ...createChannels(env, userClient),
  ...createPeople(env, userClient),
});

/**
 * Music on a profile, as Telegram Desktop shows it (R-Y185; learned, never
 * copied):
 * - `savedMusic({ chat, offset? })` — a person's saved songs
 *   (users.getSavedMusic, a page of 30) → `{ ok, count, mine, tracks: [{ id,
 *   title, performer, duration, size, name }], next }`; the documents are
 *   kept by id so a track can be played or removed;
 * - `musicFile({ id })` — a kept track's audio, downloaded once into the
 *   app folder (up to 64 MB), for the page's audio player (GET
 *   /api/telegram/music);
 * - `messageMusicSave({ chat, message, unsave? })` — a song from a chat's
 *   audio message added to the user's own profile music (account.saveMusic;
 *   a WRITE, on a click only); the message is read for a fresh file
 *   reference first and must be a song, not a voice note;
 * - `musicRemove({ id })` — one of one's own tracks taken off the profile
 *   (account.saveMusic with unsave; a WRITE, on a click only).
 * Telegram's errors become codes the page shows as text.
 */

import { promises as fs } from 'node:fs';
import path from 'node:path';
import { bigSize, locationOf, readCache } from './telegram-media.js';
import { connected, failureOf, runIn } from './telegram-stickers.js';

export const PAGE = 30;
export const ID = /^\d{1,20}$/;
// A track larger than this is not downloaded.
const MAX_AUDIO = 64 * 1024 * 1024;
// How many documents are kept by id at most.
const KEPT = 600;

const CODES = {
  DOCUMENT_INVALID: 'not-music',
  MESSAGE_ID_INVALID: 'no-message',
  PEER_ID_INVALID: 'no-access',
  USER_ID_INVALID: 'no-access',
  CHANNEL_PRIVATE: 'no-access',
  FILE_REFERENCE_EXPIRED: 'expired',
  SAVED_MUSIC_LIMIT: 'too-many',
  FLOOD_WAIT: 'flood',
};
const failure = failureOf(CODES);
const BAD = { ok: false, error: 'bad request', code: 'failed' };
const CHAT = /^-?\d{1,20}$/;

const text = (value) => String(value?.value ?? value ?? '');
const audioOf = (doc) =>
  (doc?.attributes ?? []).find(
    (a) => a?.className === 'DocumentAttributeAudio'
  );
const nameOf = (doc) =>
  (doc?.attributes ?? []).find(
    (a) => a?.className === 'DocumentAttributeFilename'
  )?.fileName;

/** Whether a document is a song (audio, not a voice note). */
export const isSong = (doc) => {
  const audio = audioOf(doc);
  return (
    doc?.className === 'Document' &&
    !audio?.voice &&
    (Boolean(audio) || /^audio\//.test(doc.mimeType ?? ''))
  );
};

/** A song's document as the page's row. */
export const trackOf = (doc) => {
  const audio = audioOf(doc);
  const name = String(nameOf(doc) ?? '');
  return {
    id: text(doc.id),
    title: String(audio?.title ?? '') || name.replace(/\.[^.]{1,5}$/, ''),
    performer: String(audio?.performer ?? ''),
    duration: Number(audio?.duration ?? 0) || 0,
    size: Number(doc.size ?? 0) || 0,
    name,
  };
};

const expired = (error) =>
  /FILE_REFERENCE_(EXPIRED|INVALID)/.test(
    String(error?.errorMessage ?? error?.message ?? '')
  );

// A kept track's audio: downloaded once into the app folder, then from it.
const createMusicFile = (env, { userClient, mediaDir }, kept) => {
  const flights = new Map();
  const download = (key, file) =>
    connected(
      env,
      userClient,
      () => null,
      async (c) => {
        const doc = kept.get(key);
        if (!doc || Number(doc.size ?? 0) > MAX_AUDIO) {
          return null;
        }
        const buffer = await c.client.downloadFile(
          locationOf(c.Api, c.helpers, {
            kind: 'document',
            file: doc,
            thumb: '',
          }),
          {
            dcId: Number(doc.dcId),
            fileSize: bigSize(c.helpers, Number(doc.size ?? 0)),
          }
        );
        if (!buffer?.length) {
          return null;
        }
        const mimeType = String(doc.mimeType ?? 'audio/mpeg');
        await fs.mkdir(path.dirname(file), { recursive: true });
        await fs.writeFile(file, buffer);
        await fs.writeFile(`${file}.type`, mimeType);
        return { buffer: Buffer.from(buffer), mimeType };
      }
    );

  const musicFile = async ({ id } = {}) => {
    const key = String(id ?? '');
    if (!ID.test(key) || !mediaDir) {
      return null;
    }
    const file = path.join(mediaDir, 'music', key);
    const cached = await readCache(file);
    const type = cached ? String(await readCache(`${file}.type`)) : '';
    if (cached && /^audio\//.test(type)) {
      return { buffer: cached, mimeType: type };
    }
    if (!flights.has(key)) {
      flights.set(
        key,
        download(key, file)
          .catch(() => null)
          .finally(() => flights.delete(key))
      );
    }
    return flights.get(key);
  };

  return musicFile;
};

export const createProfileMusic = (env, { userClient, mediaDir }) => {
  const kept = new Map(); // id -> Document
  const keep = (doc) => {
    kept.delete(text(doc.id));
    kept.set(text(doc.id), doc);
    if (kept.size > KEPT) {
      kept.delete(kept.keys().next().value);
    }
  };
  const doing = (key, use) =>
    connected(env, userClient, failure, (c) => runIn(env, key, () => use(c)));
  const inputOf = (c, doc) =>
    new c.Api.InputDocument({
      id: c.helpers.returnBigInt(text(doc.id)),
      accessHash: c.helpers.returnBigInt(text(doc.accessHash)),
      fileReference: Buffer.from(doc.fileReference ?? []),
    });
  // A person's InputUser from the peer a chat id resolves to.
  const userOf = (c, peer) => {
    if (peer?.className === 'InputPeerSelf') {
      return new c.Api.InputUserSelf();
    }
    return peer?.userId === undefined
      ? null
      : new c.Api.InputUser({
          userId: peer.userId,
          accessHash: peer.accessHash,
        });
  };

  const readSongs = async (c, chat, offset) =>
    env.connection.withPeer(c.client, chat, async (peer) => {
      const id = userOf(c, peer);
      if (!id) {
        return { ok: false, error: 'not a person', code: 'no-access' };
      }
      const answer = await c.client.invoke(
        new c.Api.users.GetSavedMusic({
          id,
          offset,
          limit: PAGE,
          hash: c.zero,
        })
      );
      const docs = (answer?.documents ?? []).filter(isSong);
      docs.forEach(keep);
      const total = Number(answer?.count ?? 0) || 0;
      const me = text((await c.client.getMe?.().catch(() => null))?.id);
      return {
        ok: true,
        count: total,
        mine: me !== '' && me === chat,
        tracks: docs.map(trackOf),
        next:
          docs.length > 0 && offset + docs.length < total
            ? offset + docs.length
            : null,
      };
    });

  const savedMusic = async ({ chat, offset = 0 } = {}) =>
    !CHAT.test(String(chat ?? '')) || !Number.isInteger(offset) || offset < 0
      ? BAD
      : doing(`music:${chat}`, (c) => readSongs(c, String(chat), offset));

  const messageSong = async (c, peer, id) => {
    const [message] = await c.client.getMessages(peer, { ids: [id] });
    const doc = message?.media?.document;
    return isSong(doc) ? doc : null;
  };

  const saveFrom = async (c, peer, id, unsave) => {
    const doc = await messageSong(c, peer, id);
    if (!doc) {
      return { ok: false, error: 'not music', code: 'not-music' };
    }
    await c.client.invoke(
      new c.Api.account.SaveMusic({ id: inputOf(c, doc), unsave })
    );
    return { ok: true, id: text(doc.id), saved: !unsave };
  };

  const messageMusicSave = async ({ chat, message, unsave = false } = {}) => {
    const id = Number(message);
    return !CHAT.test(String(chat ?? '')) || !(id > 0)
      ? BAD
      : doing(`music-save:${chat}:${id}`, (c) =>
          env.connection.withPeer(c.client, String(chat), async (peer) => {
            try {
              return await saveFrom(c, peer, id, unsave === true);
            } catch (error) {
              // The message is read again for a fresh file reference.
              if (!expired(error)) {
                throw error;
              }
              return saveFrom(c, peer, id, unsave === true);
            }
          })
        );
  };

  const musicRemove = async ({ id } = {}) =>
    !ID.test(String(id ?? ''))
      ? BAD
      : doing('music-remove', async (c) => {
          const doc = kept.get(String(id));
          if (!doc) {
            return { ok: false, error: 'unknown track', code: 'no-track' };
          }
          await c.client.invoke(
            new c.Api.account.SaveMusic({ id: inputOf(c, doc), unsave: true })
          );
          kept.delete(String(id));
          return { ok: true, id: String(id) };
        });

  const musicFile = createMusicFile(env, { userClient, mediaDir }, kept);

  return { savedMusic, messageMusicSave, musicRemove, musicFile };
};

/**
 * Stories on a profile, as Telegram Desktop shows them (R-Y185; learned,
 * never copied):
 * - `profileStories({ chat, album?, offset? })` — a person's or channel's
 *   pinned stories (stories.getPinnedStories, `offset` the id to go on
 *   from) or, with `album`, one album's (stories.getAlbumStories, `offset`
 *   a count); the first page of the pinned ones also names the albums
 *   (stories.getAlbums) → `{ ok, count, mine, me, stories: [{ …shapeStory,
 *   pinned, top }], albums: [{ id, title }], next }`;
 * - `storiesArchive({ offset? })` — one's own archive of expired stories
 *   (stories.getStoriesArchive), the same story rows;
 * - `storyPin({ chat, ids, pinned })` — stories shown on or taken off the
 *   profile (stories.togglePinned; a WRITE, on a click only);
 * - `storyPinTop({ chat, ids })` — the stories fixed at the top of the
 *   profile (stories.togglePinnedToTop, up to 3; `[]` clears; a WRITE, on a
 *   click only).
 * The pictures and videos are the story viewer's (`storyMedia`).
 * Telegram's errors become codes the page shows as text.
 */

import { shapeStory } from './telegram-stories.js';
import { connected, failureOf, runIn } from './telegram-stickers.js';

export const PAGE = 30;
export const TOP_MAX = 3;

const CODES = {
  PEER_ID_INVALID: 'no-access',
  CHANNEL_PRIVATE: 'no-access',
  USER_ID_INVALID: 'no-access',
  STORY_ID_INVALID: 'gone',
  STORIES_NEVER_CREATED: 'gone',
  ALBUM_ID_INVALID: 'gone',
  STORY_ID_EMPTY: 'gone',
  PINNED_TOO_MUCH: 'too-many',
  STORIES_TOO_MUCH: 'too-many',
  FLOOD_WAIT: 'flood',
};
const failure = failureOf(CODES);
const BAD = { ok: false, error: 'bad request', code: 'failed' };
const CHAT = /^-?\d{1,20}$/;

const text = (value) => String(value?.value ?? value ?? '');
const count = (n) => Number(n ?? 0) || 0;
const natural = (n) => Number.isInteger(n) && n >= 0;
const idList = (ids, max) =>
  Array.isArray(ids) &&
  ids.length <= max &&
  ids.every((id) => Number.isInteger(id) && id > 0);

/** The stories of an answer as the page's rows (`top`: fixed on top). */
export const rowsOf = (answer) => {
  const top = new Set((answer?.pinnedToTop ?? []).map(Number));
  return (answer?.stories ?? [])
    .map((item) => {
      const story = shapeStory(item);
      return story && !story.partial
        ? { ...story, pinned: Boolean(item.pinned), top: top.has(story.id) }
        : null;
    })
    .filter(Boolean);
};

/** An album as the page's chip. */
export const albumOf = (album) => ({
  id: count(album.albumId),
  title: String(album.title ?? ''),
});

// Where the next page begins, or null at the end: an album's by a count,
// the pinned ones' by the lowest id of a full page.
const nextOf = (album, offset, answer, rows) => {
  if (album) {
    const total = count(answer?.count);
    return rows.length > 0 && offset + rows.length < total
      ? offset + rows.length
      : null;
  }
  const items = answer?.stories ?? [];
  return items.length >= PAGE
    ? Math.min(...items.map((s) => count(s.id)))
    : null;
};

export const createProfileStories = (env, { userClient }) => {
  const doing = (key, use) =>
    connected(env, userClient, failure, (c) => runIn(env, key, () => use(c)));
  const withChat = (c, chat, use) =>
    env.connection.withPeer(c.client, chat, use);
  const meOf = async (c) =>
    text((await c.client.getMe?.().catch(() => null))?.id);

  // Telegram answers an albums request only when it has some.
  const albumsOf = async (c, peer) => {
    try {
      const answer = await c.client.invoke(
        new c.Api.stories.GetAlbums({ peer, hash: c.zero })
      );
      return (answer?.albums ?? []).map(albumOf);
    } catch {
      return [];
    }
  };

  const asked = (c, peer, { album, offset }) =>
    album
      ? c.client.invoke(
          new c.Api.stories.GetAlbumStories({
            peer,
            albumId: album,
            offset,
            limit: PAGE,
          })
        )
      : c.client.invoke(
          new c.Api.stories.GetPinnedStories({
            peer,
            offsetId: offset,
            limit: PAGE,
          })
        );

  const profileStories = async ({ chat, album, offset = 0 } = {}) =>
    !CHAT.test(String(chat ?? '')) ||
    !natural(offset) ||
    (album !== undefined && !(Number.isInteger(album) && album > 0))
      ? BAD
      : doing(`profile-stories:${chat}`, (c) =>
          withChat(c, String(chat), async (peer) => {
            const answer = await asked(c, peer, { album, offset });
            const rows = rowsOf(answer);
            const me = await meOf(c);
            return {
              ok: true,
              count: count(answer?.count),
              me,
              mine: me !== '' && me === String(chat),
              stories: rows,
              albums: !album && offset === 0 ? await albumsOf(c, peer) : [],
              next: nextOf(album, offset, answer, rows),
            };
          })
        );

  const storiesArchive = async ({ offset = 0 } = {}) =>
    !natural(offset)
      ? BAD
      : doing('profile-stories:archive', async (c) => {
          const answer = await c.client.invoke(
            new c.Api.stories.GetStoriesArchive({
              peer: new c.Api.InputPeerSelf(),
              offsetId: offset,
              limit: PAGE,
            })
          );
          const rows = rowsOf(answer);
          return {
            ok: true,
            count: count(answer?.count),
            me: await meOf(c),
            stories: rows,
            next: nextOf(0, offset, answer, rows),
          };
        });

  const storyPin = async ({ chat, ids, pinned } = {}) =>
    !CHAT.test(String(chat ?? '')) ||
    !idList(ids, PAGE) ||
    ids.length === 0 ||
    typeof pinned !== 'boolean'
      ? BAD
      : doing(`profile-stories:pin:${chat}`, (c) =>
          withChat(c, String(chat), async (peer) => {
            const done = await c.client.invoke(
              new c.Api.stories.TogglePinned({ peer, id: ids, pinned })
            );
            return { ok: true, pinned, ids: (done ?? []).map(Number) };
          })
        );

  const storyPinTop = async ({ chat, ids } = {}) =>
    !CHAT.test(String(chat ?? '')) || !idList(ids, TOP_MAX)
      ? BAD
      : doing(`profile-stories:top:${chat}`, (c) =>
          withChat(c, String(chat), async (peer) => {
            await c.client.invoke(
              new c.Api.stories.TogglePinnedToTop({ peer, id: ids })
            );
            return { ok: true, ids };
          })
        );

  return { profileStories, storiesArchive, storyPin, storyPinTop };
};

/**
 * The user's own Telegram profile, as Telegram Desktop's Settings → My
 * Account has it (R-Y136; learned, never copied):
 * - `myProfile()` — users.getFullUser of the user → `{ ok, id, firstName,
 *   lastName, about, username, phone, hasPhoto, aboutMax }` (the bio
 *   is 70 characters, 140 with Premium);
 * - `saveProfile({ firstName, lastName, about })` — account.updateProfile
 *   with only what is given;
 * - `checkUsername({ username })` → `{ ok, status }`, `status` being
 *   `available`, `taken` or `invalid` (account.checkUsername);
 * - `saveUsername({ username })` — account.updateUsername ('' removes it);
 * - `setProfilePhoto({ token })` — the page's upload as the photo
 *   (photos.uploadProfilePhoto); `removeProfilePhoto()` —
 *   photos.deletePhotos with the current photo.
 * A saved name or username also moves the account the status shows.
 * Telegram's errors become codes the page shows as text.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';
import { uploadedFile } from './telegram-chat-edit.js';
import { statusOf } from './telegram-emoji-status.js';
import { usernamesOf } from './telegram-usernames.js';

export const ABOUT_MAX = 70;
export const ABOUT_MAX_PREMIUM = 140;
export const USERNAME = /^$|^[A-Za-z][A-Za-z0-9_]{3,31}$/;

// The stored sync state holds the account the status shows.
const SYNC_ID = 'sync:telegram';

const CODES = {
  FIRSTNAME_INVALID: 'name-invalid',
  ABOUT_TOO_LONG: 'about-too-long',
  USERNAME_INVALID: 'username-invalid',
  USERNAME_OCCUPIED: 'username-taken',
  USERNAME_PURCHASE_AVAILABLE: 'username-taken',
  PHOTO_INVALID: 'photo-invalid',
  PHOTO_EXT_INVALID: 'photo-invalid',
  IMAGE_PROCESS_FAILED: 'photo-invalid',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);

const messageOf = (error) =>
  String(error?.errorMessage ?? error?.message ?? '');

// Telegram saying nothing changed is no failure.
const forgiving = (error) =>
  messageOf(error).includes('_NOT_MODIFIED') ? { ok: true } : failure(error);

const bad = (code) => ({ ok: false, error: code, code });
const length = (value) => Array.from(String(value)).length;
const textOf = (value) => String(value?.value ?? value);

// The account the status shows, moved to what was saved.
const refreshAccount = async (env, user) => {
  if (!user || typeof user !== 'object') {
    return;
  }
  try {
    const link = await env.store?.get?.(SYNC_ID);
    if (!link?.account) {
      return;
    }
    const account = { ...link.account };
    for (const key of ['firstName', 'lastName', 'username']) {
      if (user[key] !== undefined) {
        account[key] = user[key] ?? null;
      }
    }
    await env.store.put({ ...link, account });
  } catch {
    // the status is a convenience; the save stands
  }
};

// One request, through the queue.
const ask = (env, c, key, request) =>
  runIn(env, key, () => c.client.invoke(request));

const fullOf = async (env, c) => {
  const answer = await ask(
    env,
    c,
    'profile:me',
    new c.Api.users.GetFullUser({ id: new c.Api.InputUserSelf() })
  );
  const user =
    (answer?.users ?? []).find((u) => u?.self) ?? answer?.users?.[0] ?? {};
  return { full: answer?.fullUser ?? {}, user };
};

const hasPhoto = (full) =>
  Boolean(full.profilePhoto) && full.profilePhoto.className !== 'PhotoEmpty';

const readMine = (env, userClient) => async () =>
  connected(env, userClient, failure, async (c) => {
    const { full, user } = await fullOf(env, c);
    return {
      ok: true,
      id: textOf(user.id ?? ''),
      firstName: user.firstName ?? '',
      lastName: user.lastName ?? '',
      about: full.about ?? '',
      username: user.username ?? '',
      // Collectible usernames besides it (R-Y170).
      usernames: usernamesOf(user.usernames),
      phone: user.phone ? `+${String(user.phone).replace(/^\+/, '')}` : '',
      hasPhoto: hasPhoto(full),
      aboutMax: user.premium ? ABOUT_MAX_PREMIUM : ABOUT_MAX,
      // The emoji status row (R-Y162).
      premium: Boolean(user.premium),
      emojiStatus: statusOf(user.emojiStatus),
    };
  });

// The code that refuses a save, or null.
const refusal = ({ firstName, lastName, about }) => {
  if (firstName !== undefined && length(firstName.trim()) < 1) {
    return 'name-invalid';
  }
  if ([firstName, lastName].some((n) => n !== undefined && length(n) > 64)) {
    return 'name-invalid';
  }
  return about !== undefined && length(about) > ABOUT_MAX_PREMIUM
    ? 'about-too-long'
    : null;
};

const saveMine =
  (env, userClient) =>
  async (request = {}) => {
    const fields = ['firstName', 'lastName', 'about'].filter(
      (k) => typeof request[k] === 'string'
    );
    const code = refusal(request);
    if (code || fields.length === 0) {
      return bad(code ?? 'failed');
    }
    return connected(env, userClient, forgiving, async (c) => {
      const user = await ask(
        env,
        c,
        'profile:save',
        new c.Api.account.UpdateProfile(
          Object.fromEntries(fields.map((k) => [k, request[k]]))
        )
      );
      await refreshAccount(env, user);
      return { ok: true };
    });
  };

// A refused check is an answer, not a failure.
const checked = (error) => {
  const found = failure(error);
  const status = { 'username-invalid': 'invalid', 'username-taken': 'taken' }[
    found.code
  ];
  if (messageOf(error).includes('_NOT_MODIFIED')) {
    return { ok: true, status: 'available' };
  }
  return status ? { ok: true, status } : found;
};

const checkName =
  (env, userClient) =>
  async (request = {}) => {
    const username = String(request.username ?? '');
    if (!USERNAME.test(username)) {
      return { ok: true, status: 'invalid' };
    }
    if (username === '') {
      return { ok: true, status: 'available' };
    }
    return connected(env, userClient, checked, async (c) => {
      const free = await ask(
        env,
        c,
        'profile:username-check',
        new c.Api.account.CheckUsername({ username })
      );
      return { ok: true, status: free ? 'available' : 'taken' };
    });
  };

const saveName =
  (env, userClient) =>
  async (request = {}) => {
    const username = String(request.username ?? '');
    if (!USERNAME.test(username)) {
      return bad('username-invalid');
    }
    return connected(env, userClient, forgiving, async (c) => {
      const user = await ask(
        env,
        c,
        'profile:username',
        new c.Api.account.UpdateUsername({ username })
      );
      await refreshAccount(env, user ?? { username: username || null });
      return { ok: true };
    });
  };

const setPhoto =
  (env, { userClient, uploads }) =>
  async (request = {}) => {
    const token = String(request.token ?? '');
    try {
      return await connected(env, userClient, failure, async (c) => {
        const file = await uploadedFile({ ...c, env }, uploads, token);
        if (!file) {
          return bad('photo-invalid');
        }
        await ask(
          env,
          c,
          'profile:photo',
          new c.Api.photos.UploadProfilePhoto({ file })
        );
        return { ok: true };
      });
    } finally {
      await uploads?.dropUpload?.(token);
    }
  };

// The current photo, asked for fresh (its file reference ages).
const removePhoto = (env, userClient) => async () =>
  connected(env, userClient, failure, async (c) => {
    const { full } = await fullOf(env, c);
    const photo = hasPhoto(full) ? full.profilePhoto : null;
    if (photo) {
      await ask(
        env,
        c,
        'profile:photo',
        new c.Api.photos.DeletePhotos({
          id: [
            new c.Api.InputPhoto({
              id: photo.id,
              accessHash: photo.accessHash,
              fileReference: photo.fileReference,
            }),
          ],
        })
      );
    }
    return { ok: true };
  });

/** `context.uploads` has the page's uploads (`uploadOf`, `dropUpload`). */
export const createProfile = (env, context) => ({
  myProfile: readMine(env, context.userClient),
  saveProfile: saveMine(env, context.userClient),
  checkUsername: checkName(env, context.userClient),
  saveUsername: saveName(env, context.userClient),
  setProfilePhoto: setPhoto(env, context),
  removeProfilePhoto: removePhoto(env, context.userClient),
});

/**
 * The connection proxy, as Telegram Desktop's Settings → Advanced →
 * Connection type has it (R-Y192; learned, never copied): direct (the
 * default), a SOCKS5 proxy (host, port, optional user and password) or
 * an MTProto proxy (host, port, secret).
 *
 * - `proxyGet()`   — the saved setting as the page may see it: the kind,
 *   host, port and user name, and only whether a password or a secret
 *   is set (`passwordSet`, `secretSet`). Those two are write-only;
 * - `proxySave(body)` — validated and kept (under `secret:telegram:proxy`
 *   beside the session, never in it). A password or secret left out
 *   keeps the saved one (for the same host only); an empty password clears it. The connection is
 *   then dropped and opened again through the existing reopen path, so
 *   the new proxy is used at once (if reopening fails, the next poll
 *   opens it, still through the new proxy);
 * - `proxyCheck({host, port})` — a short TCP connect to the proxy's
 *   address (the user's own action), its answer `{reachable, ms}`. The
 *   probe is injected (`env.proxyProbe`) so tests never open a socket.
 *
 * Neither the password nor the secret is ever logged, returned or put in
 * an error. GramJS takes the proxy in `proxyOptions` form (see
 * `gramjsClientFactory`). Voice and video calls are set up through
 * Telegram's own relays by the page, not this client, so there is no
 * "use proxy for calls" switch.
 */

import net from 'node:net';
import { portOf, validHost } from '../web/proxy-model.js';

export { portOf, validHost };

export const PROXY_ID = 'secret:telegram:proxy';
export const KINDS = Object.freeze(['none', 'socks5', 'mtproto']);

const HEX = /^[0-9a-f]+$/i;
const BASE64URL = /^[A-Za-z0-9_-]+$/;
const CHECK_MS = 5000;

/**
 * An MTProto secret in the forms proxy links carry (hex, or base64url)
 * as `{ hex }` (16 bytes, or 17 with the leading dd of "secure"
 * proxies), `{ error: 'unsupported-secret' }` for the fake-TLS ee form
 * GramJS cannot speak, or null when it is not a secret at all.
 */
export const secretOf = (value) => {
  if (typeof value !== 'string' || value.length < 16 || value.length > 512) {
    return null;
  }
  let bytes = null;
  if (HEX.test(value) && value.length % 2 === 0) {
    bytes = Buffer.from(value, 'hex');
  } else if (BASE64URL.test(value) && value.length % 4 !== 1) {
    bytes = Buffer.from(value, 'base64url');
  }
  if (!bytes) {
    return null;
  }
  if (bytes[0] === 0xee && bytes.length > 17) {
    return { error: 'unsupported-secret' };
  }
  const plain = bytes.length === 16;
  const secure = bytes.length === 17 && bytes[0] === 0xdd;
  return plain || secure ? { hex: bytes.toString('hex') } : null;
};

const fail = (code) => ({ ok: false, code });
const good = (value) => ({ ok: true, value });

const textOf = (value, max) =>
  typeof value === 'string' && Buffer.byteLength(value) <= max;

// A saved password or secret is kept only for the same server: it is
// never sent to another host the user types in.
const sameServer = (body, before, kind) =>
  before?.kind === kind && before.host === body.host;

// A SOCKS5 login: a user name, a password only with one (RFC 1929: up to
// 255 bytes each). A password left out keeps the saved one.
const socksOf = (body, before) => {
  const username = body.username ?? '';
  const keep =
    body.password === undefined && sameServer(body, before, 'socks5');
  const password = keep ? (before.password ?? '') : (body.password ?? '');
  if (!textOf(username, 255) || !textOf(password, 255)) {
    return fail('bad-login');
  }
  return password && !username
    ? fail('bad-login')
    : good({ username, password });
};

const mtprotoOf = (body, before) => {
  if (body.secret === undefined && sameServer(body, before, 'mtproto')) {
    return good({ secret: before.secret });
  }
  const secret = secretOf(body.secret);
  if (!secret || secret.error) {
    return fail(secret?.error ?? 'bad-secret');
  }
  return good({ secret: secret.hex });
};

/**
 * A page's body checked into the setting to keep: `{ ok, value }` or
 * `{ ok: false, code }`. `before` is the saved one (for a password or
 * secret the body leaves out).
 */
export const validateProxy = (body, before = null) => {
  if (!body || typeof body !== 'object' || !KINDS.includes(body.kind)) {
    return fail('bad-kind');
  }
  if (body.kind === 'none') {
    return good({ kind: 'none' });
  }
  const port = portOf(body.port);
  if (!validHost(body.host)) {
    return fail('bad-host');
  }
  if (port === null) {
    return fail('bad-port');
  }
  const rest =
    body.kind === 'socks5' ? socksOf(body, before) : mtprotoOf(body, before);
  return rest.ok
    ? good({ kind: body.kind, host: body.host, port, ...rest.value })
    : rest;
};

/** What the page may see of a setting: no password, no secret. */
export const publicProxy = (setting) => {
  if (!setting || setting.kind === 'none' || !KINDS.includes(setting.kind)) {
    return { kind: 'none' };
  }
  const shown = { kind: setting.kind, host: setting.host, port: setting.port };
  return setting.kind === 'socks5'
    ? {
        ...shown,
        username: setting.username ?? '',
        passwordSet: Boolean(setting.password),
      }
    : { ...shown, secretSet: Boolean(setting.secret) };
};

/** The `proxy` option of GramJS's TelegramClient, or undefined (direct). */
export const proxyOptions = (setting) => {
  if (setting?.kind === 'socks5') {
    return {
      ip: setting.host,
      port: setting.port,
      socksType: 5,
      timeout: 10,
      ...(setting.username ? { username: setting.username } : {}),
      ...(setting.password ? { password: setting.password } : {}),
    };
  }
  if (setting?.kind === 'mtproto') {
    return {
      ip: setting.host,
      port: setting.port,
      MTProxy: true,
      secret: setting.secret,
    };
  }
  return undefined;
};

/** The saved setting (or null), read from the store; never throws. */
export const readProxy = async (store) => {
  try {
    const record = await store?.get(PROXY_ID);
    const parsed = JSON.parse(record?.value ?? 'null');
    const checked = parsed && validateProxy(parsed, parsed);
    return checked?.ok ? checked.value : null;
  } catch {
    return null;
  }
};

/** A TCP connect to host:port; `{ reachable, ms }`. Opens a real socket. */
export const tcpProbe = ({ host, port, timeoutMs = CHECK_MS }) =>
  new Promise((resolve) => {
    const started = Date.now();
    const socket = net.connect({ host, port });
    const done = (reachable) => {
      socket.destroy();
      resolve({ reachable, ms: Date.now() - started });
    };
    socket.setTimeout(timeoutMs, () => done(false));
    socket.once('connect', () => done(true));
    socket.once('error', () => done(false));
  });

const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);

export const createProxy = (env) => {
  const proxyGet = async () => ({
    ok: true,
    proxy: publicProxy(await readProxy(env.store)),
  });

  const proxySave = async (body) => {
    const before = await readProxy(env.store);
    const checked = validateProxy(body, before);
    if (!checked.ok) {
      return { ok: false, code: checked.code };
    }
    if (!same(before ?? { kind: 'none' }, checked.value)) {
      await env.store.put({
        id: PROXY_ID,
        tokens: ['secret', 'telegram', 'proxy'],
        value: JSON.stringify(checked.value),
        updated: new Date(env.now?.() ?? Date.now()).toISOString(),
      });
      // The open connection used the old proxy: drop it and open anew.
      await env.connection?.disconnect?.();
      Promise.resolve(env.reopen?.()).catch(() => {});
    }
    env.log?.({
      level: 'info',
      event: 'telegram_proxy_saved',
      kind: checked.value.kind,
    });
    return { ok: true, proxy: publicProxy(checked.value) };
  };

  const proxyCheck = async (body = {}) => {
    const saved = await readProxy(env.store);
    const host = body.host ?? saved?.host;
    const port = portOf(body.port ?? saved?.port);
    if (!validHost(host)) {
      return { ok: false, code: 'bad-host' };
    }
    if (port === null) {
      return { ok: false, code: 'bad-port' };
    }
    const probe = env.proxyProbe ?? tcpProbe;
    const { reachable, ms } = await probe({ host, port, timeoutMs: CHECK_MS });
    return { ok: true, host, port, reachable: Boolean(reachable), ms };
  };

  return { proxyGet, proxySave, proxyCheck };
};

/**
 * Sign in to Telegram by QR code, as Telegram Desktop offers it (R-Y203;
 * learned, never copied): the page shows `tg://login?token=<base64url>`
 * as a QR code, the user opens Telegram on the phone, Settings > Devices >
 * Link Desktop Device, and points the phone at the screen.
 *
 * The flow over MTProto:
 *   auth.exportLoginToken { api_id, api_hash, except_ids: [] }
 *     -> auth.loginToken { expires, token }   show it; ask again when it
 *        expires (Desktop refreshes the code too)
 *     -> auth.loginTokenSuccess               signed in
 *     -> auth.loginTokenMigrateTo { dc_id, token }
 *        switch the client to that data centre and call
 *        auth.importLoginToken { token }, which answers the same way
 *   updateLoginToken arrives once the phone confirmed: call
 *   auth.exportLoginToken again for the answer.
 *   SESSION_PASSWORD_NEEDED (2-Step Verification) goes on to the password
 *   step, the same one the phone-number sign-in has.
 *
 * The controller has the shape of the phone sign-in's (`state`, `account`,
 * `session`, `submitPassword`, `cancel`), so the routes treat both alike.
 * Never logged or returned except the code's own URL: the token, the
 * session, the password.
 */

const deferred = () => {
  let resolve;
  let reject;
  const promise = new Promise((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
};

const sleep = (ms) => new Promise((r) => globalThis.setTimeout(r, ms));

/** The URL a phone scans: the token as base64url. */
export const loginUrl = (token) =>
  `tg://login?token=${Buffer.from(token).toString('base64url')}`;

/**
 * Start a QR sign-in on `client` (a GramJS-like client, not yet connected).
 * `Api` is GramJS's constructor namespace, `accountOf` names the account.
 * The returned controller's `state` is 'qr' (show `url`), 'password',
 * 'checking' (the password is being checked), 'done' or 'error'.
 */
export const startQrLogin = async ({
  client,
  apiId,
  apiHash,
  Api,
  accountOf,
  now = () => Date.now(),
  // Ask for a fresh code this long before it expires, and at the latest
  // this long after the last one (clock differences with Telegram).
  margin = 2000,
  maxAge = 25000,
  pollMs = 25,
}) => {
  const ctrl = {
    state: 'qr',
    url: null,
    expires: 0,
    fetchedAt: 0,
    error: null,
    account: null,
    session: null,
    password: null,
    cancelled: false,
  };
  let inflight = null;

  const finish = async (user) => {
    ctrl.session = client.session.save();
    ctrl.account = accountOf(user);
    ctrl.state = 'done';
    await client.disconnect?.();
  };

  // 2-Step Verification: GramJS asks for the password through a callback;
  // a wrong one comes back to onError and is asked for again.
  const askPassword = () => {
    ctrl.state = 'password';
    client
      .signInWithPassword(
        { apiId: Number(apiId), apiHash },
        {
          password: async () => {
            ctrl.state = 'password';
            ctrl.password = deferred();
            return ctrl.password.promise;
          },
          onError: async (error) => {
            ctrl.error = error;
            return ctrl.cancelled;
          },
        }
      )
      .then(finish)
      .catch((error) => {
        ctrl.error = ctrl.error ?? error;
        ctrl.state = 'error';
      });
  };

  const exchange = async (request) => {
    const answer = await client.invoke(request);
    if (answer?.className !== 'auth.LoginTokenMigrateTo') {
      return answer;
    }
    // The account lives on another data centre: go there, import the token.
    await client._switchDC(answer.dcId);
    return client.invoke(
      new Api.auth.ImportLoginToken({ token: answer.token })
    );
  };

  const apply = async (answer) => {
    if (answer?.className === 'auth.LoginToken') {
      ctrl.url = loginUrl(answer.token);
      ctrl.expires = Number(answer.expires);
      ctrl.fetchedAt = now();
    } else if (answer?.className === 'auth.LoginTokenSuccess') {
      await finish(answer.authorization?.user);
    } else {
      throw new Error('unexpected answer to the QR login');
    }
  };

  const refresh = () => {
    inflight ??= (async () => {
      try {
        await apply(
          await exchange(
            new Api.auth.ExportLoginToken({
              apiId: Number(apiId),
              apiHash,
              exceptIds: [],
            })
          )
        );
      } catch (error) {
        if (error?.errorMessage === 'SESSION_PASSWORD_NEEDED') {
          askPassword();
        } else {
          ctrl.error = error;
          ctrl.state = 'error';
        }
      } finally {
        inflight = null;
      }
    })();
    return inflight;
  };

  const stale = () =>
    ctrl.url === null ||
    now() >= Math.min(ctrl.expires * 1000 - margin, ctrl.fetchedAt + maxAge);

  const fail = async (error) => {
    await client.disconnect?.();
    throw error;
  };

  await client.connect();
  client.addEventHandler?.((update) => {
    // The phone confirmed: the next export answers with the account.
    if (update?.className === 'UpdateLoginToken' && ctrl.state === 'qr') {
      refresh();
    }
  });
  await refresh();
  if (ctrl.state === 'error') {
    return fail(ctrl.error);
  }

  return controllerOf({
    ctrl,
    client,
    refresh,
    stale,
    pending: () => inflight,
    settle: settleFor(ctrl, now, pollMs),
  });
};

// Wait while the state is `want`; a wrong password is thrown once.
const settleFor = (ctrl, now, pollMs) => async (want) => {
  const deadline = now() + 60000;
  while (ctrl.state === want && now() < deadline) {
    await sleep(pollMs);
  }
  if (ctrl.error) {
    const error = ctrl.error;
    ctrl.error = null;
    throw error;
  }
  return ctrl.state;
};

const controllerOf = ({ ctrl, client, refresh, stale, pending, settle }) => ({
  get state() {
    return ctrl.state;
  },
  get url() {
    return ctrl.url;
  },
  get expires() {
    return ctrl.expires;
  },
  get account() {
    return ctrl.account;
  },
  get session() {
    return ctrl.session;
  },
  // One poll: renew an expiring code, wait for an export in flight.
  async status() {
    if (ctrl.state === 'qr' && stale()) {
      await refresh();
    } else if (pending()) {
      await pending();
    }
    if (ctrl.state === 'error') {
      throw ctrl.error;
    }
    return ctrl.state;
  },
  async submitPassword(value) {
    if (ctrl.state !== 'password' || !ctrl.password) {
      throw new Error('no password is asked for now');
    }
    ctrl.error = null;
    ctrl.state = 'checking';
    ctrl.password.resolve(String(value));
    return settle('checking');
  },
  async cancel() {
    ctrl.cancelled = true;
    ctrl.password?.reject(new Error('cancelled'));
    await client.disconnect?.();
  },
});

/**
 * The quick (double-tap) reaction, as Telegram Desktop's Settings → Chat
 * Settings → Quick reaction (R-Y206; learned, never copied):
 * - `quickReaction()` — the account's default reaction, read from
 *   help.getConfig (`reactions_default`) → `{ ok, emoji }`, `emoji` null
 *   when it is a custom emoji or none (the page then uses its own);
 * - `quickReactionSet({ emoji })` — a new one (messages.setDefaultReaction),
 *   remembered at once.
 * The emoji is a short string, as the chat reactions' are.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';
import { MAX_EMOJI_LENGTH } from './telegram-chat-reactions.js';

const CODES = {
  REACTION_INVALID: 'reaction-invalid',
  REACTION_EMPTY: 'reaction-invalid',
};

const failure = failureOf(CODES);

/** The emoji a Reaction names, else null. */
export const emojiOf = (reaction) =>
  reaction?.className === 'ReactionEmoji' &&
  typeof reaction.emoticon === 'string'
    ? reaction.emoticon
    : null;

/** Whether `emoji` is one short string with no spaces. */
export const validEmoji = (emoji) =>
  typeof emoji === 'string' &&
  emoji.length > 0 &&
  emoji.length <= MAX_EMOJI_LENGTH &&
  !/\s/.test(emoji);

export const createQuickReaction = (env, { userClient }) => {
  const kept = { emoji: undefined };

  const quickReaction = async () => {
    if (kept.emoji !== undefined) {
      return { ok: true, emoji: kept.emoji };
    }
    return connected(env, userClient, failure, async (c) => {
      const config = await runIn(env, 'reactions:default', () =>
        c.client.invoke(new c.Api.help.GetConfig())
      );
      kept.emoji = emojiOf(config?.reactionsDefault);
      return { ok: true, emoji: kept.emoji };
    });
  };

  const quickReactionSet = async ({ emoji } = {}) => {
    if (!validEmoji(emoji)) {
      return { ok: false, error: 'bad request', code: 'bad-request' };
    }
    return connected(env, userClient, failure, async (c) => {
      await runIn(env, 'reactions:default-set', () =>
        c.client.invoke(
          new c.Api.messages.SetDefaultReaction({
            reaction: new c.Api.ReactionEmoji({ emoticon: emoji }),
          })
        )
      );
      kept.emoji = emoji;
      return { ok: true, emoji };
    });
  };

  return { quickReaction, quickReactionSet };
};

/**
 * Quick replies, as Telegram Desktop's Settings → Telegram Business →
 * Quick Replies has them (R-Y179; learned, never copied). A shortcut is a
 * name ("hello") with a few messages kept on Telegram's side; they are
 * written to the user's own "chat" (InputPeerSelf) with the shortcut named:
 * - `quickReplies()` — messages.getQuickReplies → `{ ok, replies: [{ id,
 *   name, count, preview }] }`, in the order Telegram keeps;
 * - `quickReplyMessages({ shortcutId })` — messages.getQuickReplyMessages →
 *   `{ ok, messages: [{ id, text, media }] }`;
 * - `quickReplyCreate({ name, text })` — the shortcut made by sending its
 *   first message (messages.checkQuickReplyShortcut first) → `{ ok }`;
 * - `quickReplyAdd({ shortcutId, text })` — messages.sendMessage into it;
 * - `quickReplyEdit({ shortcutId, id, text })` — messages.editMessage with
 *   quickReplyShortcutId; `quickReplyDeleteMessages({ shortcutId, ids })`
 *   — messages.deleteQuickReplyMessages;
 * - `quickReplyRename({ shortcutId, name })` —
 *   messages.editQuickReplyShortcut; `quickReplyDelete({ shortcutId })` —
 *   messages.deleteQuickReplyShortcut; `quickReplyReorder({ order })` —
 *   messages.reorderQuickReplies;
 * - `quickReplySend({ chat, shortcutId })` — the shortcut's messages sent
 *   to a chat (messages.sendQuickReplyMessages), only when asked.
 * Telegram's refusals (Premium needed, name taken, too many) become codes.
 */

import { runIn, connected, failureOf } from './telegram-stickers.js';
import { randomIdOf } from './telegram-send.js';

export const NAME = /^[\p{L}\p{N}_]{1,32}$/u;
const ID = /^\d{1,10}$/;
const TEXT_MAX = 4096;

const CODES = {
  PREMIUM_ACCOUNT_REQUIRED: 'premium',
  BUSINESS_PEER_INVALID: 'no-access',
  SHORTCUT_INVALID: 'bad-name',
  SHORTCUT_OCCUPIED: 'name-taken',
  QUICK_REPLIES_TOO_MUCH: 'too-many',
  MESSAGE_TOO_LONG: 'too-long',
  MESSAGE_EMPTY: 'empty',
  MESSAGE_NOT_MODIFIED: 'unchanged',
  PEER_ID_INVALID: 'no-access',
  USER_ID_INVALID: 'no-access',
  FLOOD_WAIT: 'flood',
};

export const quickFailure = failureOf(CODES);

const bad = (code) => ({ ok: false, error: code, code });
const MEDIA = {
  MessageMediaPhoto: 'photo',
  MessageMediaDocument: 'file',
  MessageMediaGeo: 'location',
  MessageMediaContact: 'contact',
  MessageMediaPoll: 'poll',
};
const mediaOf = (message) =>
  message?.media ? (MEDIA[message.media.className] ?? 'file') : null;

const shapeMessage = (m) => ({
  id: Number(m.id),
  text: String(m.message ?? ''),
  media: mediaOf(m),
});

const shapeReplies = (answer) => {
  const tops = new Map((answer?.messages ?? []).map((m) => [Number(m.id), m]));
  return (answer?.quickReplies ?? []).map((q) => {
    const top = tops.get(Number(q.topMessage));
    return {
      id: Number(q.shortcutId),
      name: String(q.shortcut),
      count: Number(q.count ?? 0),
      preview: top ? shapeMessage(top).text || mediaOf(top) || '' : '',
    };
  });
};

// A trimmed text of a sensible length, or the code that refuses it.
const textProblem = (text) => {
  const value = String(text ?? '');
  if (value.trim() === '') {
    return 'empty';
  }
  return Array.from(value).length > TEXT_MAX ? 'too-long' : null;
};

const ids = (list) =>
  Array.isArray(list) &&
  list.length > 0 &&
  list.length <= 100 &&
  list.every((n) => Number.isInteger(n) && n > 0);

const shortcutOf = (c, key) =>
  new c.Api.InputQuickReplyShortcutId({ shortcutId: Number(key) });

const toolsOf = (env, userClient) => {
  const run = (key, use) => runIn(env, `quick-replies:${key}`, use);
  const act = (key, use) =>
    connected(env, userClient, quickFailure, (c) =>
      run(key, () => use(c)).then((r) => r ?? { ok: true })
    );
  const invoke = (c, request) => c.client.invoke(request);

  const messagesOf = async (c, shortcutId) => {
    const answer = await invoke(
      c,
      new c.Api.messages.GetQuickReplyMessages({
        shortcutId: Number(shortcutId),
        hash: c.zero,
      })
    );
    return (answer?.messages ?? []).map(shapeMessage);
  };

  const sendInto = (c, shortcut, text) =>
    invoke(
      c,
      new c.Api.messages.SendMessage({
        peer: new c.Api.InputPeerSelf(),
        message: String(text),
        randomId: randomIdOf(null, 0, c.helpers),
        quickReplyShortcut: shortcut,
      })
    );

  return { env, act, invoke, messagesOf, sendInto };
};

const readActions = ({ act, invoke, messagesOf }) => ({
  quickReplies: () =>
    act('list', async (c) => ({
      ok: true,
      replies: shapeReplies(
        await invoke(c, new c.Api.messages.GetQuickReplies({ hash: c.zero }))
      ),
    })),
  quickReplyMessages: async ({ shortcutId } = {}) =>
    ID.test(String(shortcutId))
      ? act(`messages:${shortcutId}`, async (c) => ({
          ok: true,
          messages: await messagesOf(c, shortcutId),
        }))
      : bad('bad-request'),
});

const writeActions = ({ env, act, invoke, messagesOf, sendInto }) => ({
  quickReplyCreate: async ({ name, text } = {}) => {
    const problem = NAME.test(String(name ?? ''))
      ? textProblem(text)
      : 'bad-name';
    if (problem) {
      return bad(problem);
    }
    return act('create', async (c) => {
      const free = await invoke(
        c,
        new c.Api.messages.CheckQuickReplyShortcut({ shortcut: name })
      );
      if (free === false) {
        return bad('name-taken');
      }
      await sendInto(
        c,
        new c.Api.InputQuickReplyShortcut({ shortcut: name }),
        text
      );
      return { ok: true };
    });
  },
  quickReplyAdd: async ({ shortcutId, text } = {}) => {
    const problem = ID.test(String(shortcutId))
      ? textProblem(text)
      : 'bad-request';
    return problem
      ? bad(problem)
      : act(`add:${shortcutId}`, async (c) => {
          await sendInto(c, shortcutOf(c, shortcutId), text);
          return { ok: true };
        });
  },
  quickReplyEdit: async ({ shortcutId, id, text } = {}) => {
    const problem =
      ID.test(String(shortcutId)) && ID.test(String(id))
        ? textProblem(text)
        : 'bad-request';
    return problem
      ? bad(problem)
      : act(`edit:${shortcutId}`, async (c) => {
          await invoke(
            c,
            new c.Api.messages.EditMessage({
              peer: new c.Api.InputPeerSelf(),
              id: Number(id),
              message: String(text),
              quickReplyShortcutId: Number(shortcutId),
            })
          );
          return { ok: true };
        });
  },
  quickReplyDeleteMessages: async ({ shortcutId, ids: list } = {}) =>
    ID.test(String(shortcutId)) && ids(list)
      ? act(`delete-messages:${shortcutId}`, async (c) => {
          await invoke(
            c,
            new c.Api.messages.DeleteQuickReplyMessages({
              shortcutId: Number(shortcutId),
              id: list,
            })
          );
          return { ok: true };
        })
      : bad('bad-request'),
  quickReplyRename: async ({ shortcutId, name } = {}) =>
    ID.test(String(shortcutId)) && NAME.test(String(name ?? ''))
      ? act(`rename:${shortcutId}`, async (c) => {
          await invoke(
            c,
            new c.Api.messages.EditQuickReplyShortcut({
              shortcutId: Number(shortcutId),
              shortcut: name,
            })
          );
          return { ok: true };
        })
      : bad(ID.test(String(shortcutId)) ? 'bad-name' : 'bad-request'),
  quickReplyDelete: async ({ shortcutId } = {}) =>
    ID.test(String(shortcutId))
      ? act(`delete:${shortcutId}`, async (c) => {
          await invoke(
            c,
            new c.Api.messages.DeleteQuickReplyShortcut({
              shortcutId: Number(shortcutId),
            })
          );
          return { ok: true };
        })
      : bad('bad-request'),
  quickReplyReorder: async ({ order } = {}) =>
    ids(order)
      ? act('reorder', async (c) => {
          await invoke(c, new c.Api.messages.ReorderQuickReplies({ order }));
          return { ok: true };
        })
      : bad('bad-request'),
  quickReplySend: async ({ chat, shortcutId } = {}) =>
    /^\d{1,20}$/.test(String(chat ?? '')) && ID.test(String(shortcutId))
      ? act(`send:${chat}`, async (c) => {
          const list = await messagesOf(c, shortcutId);
          if (list.length === 0) {
            return bad('empty');
          }
          await env.connection.withPeer(c.client, String(chat), (peer) =>
            invoke(
              c,
              new c.Api.messages.SendQuickReplyMessages({
                peer,
                shortcutId: Number(shortcutId),
                id: list.map((m) => m.id),
                randomId: list.map((_, i) => randomIdOf(null, i, c.helpers)),
              })
            )
          );
          return { ok: true, sent: list.length };
        })
      : bad('bad-request'),
});

export const createQuickReplies = (env, { userClient }) => {
  const tools = toolsOf(env, userClient);
  return { ...readActions(tools), ...writeActions(tools) };
};

/**
 * Who read a message and who reacted to it, as Telegram's apps list them
 * (R-Y127; learned, never copied):
 * - `messageReaders({ chat, id })` — in a small group (Telegram decides:
 *   at most 100 members, the message a day or two old at most), the people
 *   who read the user's own message and when (messages.
 *   getMessageReadParticipants) → `{ ok, readers: [{ id, name, date }] }`,
 *   `date` in ms, the latest first;
 * - `messageReactors({ chat, id, emoji?, offset? })` — who reacted, with
 *   which emoji (messages.getMessageReactionsList), a page at a time →
 *   `{ ok, count, items: [{ peer, name, emoji, customEmojiId, date, my }],
 *   next }`, `next` the offset of the following page or null.
 * - `reportReaction({ chat, id, peer })` — an admin reports the reaction
 *   a member (`peer`, a user id) left on a group message
 *   (messages.reportReaction; R-Y195) → `{ ok }`.
 * Telegram's errors (MSG_TOO_OLD, CHAT_TOO_BIG…) become codes the page
 * shows as text.
 */

import { connect, runIn, failureOf } from './telegram-stickers.js';

const CODES = {
  MSG_TOO_OLD: 'too-old',
  CHAT_TOO_BIG: 'too-big',
  MESSAGE_ID_INVALID: 'not-found',
  CHAT_ADMIN_REQUIRED: 'not-allowed',
  USER_ID_INVALID: 'not-found',
  PEER_ID_INVALID: 'no-access',
  CHANNEL_PRIVATE: 'no-access',
};

const failure = failureOf(CODES);

const CHAT = /^-?\d{1,20}$/;
const DIGITS = /^\d{1,20}$/;
const textOf = (value) => String(value?.value ?? value);
const MAX_READERS = 100;

const nameOf = (entity) =>
  entity?.title ||
  [entity?.firstName, entity?.lastName].filter(Boolean).join(' ') ||
  entity?.username ||
  '';

// A peer's id as the chat list writes it: users plain, groups negative,
// channels -100…
const peerId = (peer) => {
  if (peer?.userId !== undefined) {
    return textOf(peer.userId);
  }
  if (peer?.channelId !== undefined) {
    return `-100${textOf(peer.channelId)}`;
  }
  return peer?.chatId === undefined ? '' : `-${textOf(peer.chatId)}`;
};

// A reader's name: the account may know them already; else their id.
const readerName = async (client, id) => {
  try {
    return nameOf(await client.getEntity(id)) || id;
  } catch {
    return id;
  }
};

const valid = (body) =>
  CHAT.test(String(body.chat ?? '')) && Number(body.id) > 0;

const createReaders =
  (env, userClient) =>
  async (body = {}) => {
    const c = valid(body) ? await connect(env, userClient) : null;
    if (!c) {
      return { ok: false, supported: false };
    }
    try {
      const answer = await runIn(env, `readers:${body.chat}:${body.id}`, () =>
        env.connection.withPeer(c.client, body.chat, (peer) =>
          c.client.invoke(
            new c.Api.messages.GetMessageReadParticipants({
              peer,
              msgId: Number(body.id),
            })
          )
        )
      );
      const found = [...(Array.isArray(answer) ? answer : [])]
        .slice(0, MAX_READERS)
        .sort((a, b) => Number(b.date) - Number(a.date));
      const readers = await Promise.all(
        found.map(async (one) => {
          const user = textOf(one.userId);
          return {
            id: user,
            name: await readerName(c.client, user),
            date: Number(one.date) * 1000,
          };
        })
      );
      return { ok: true, readers };
    } catch (error) {
      return failure(error);
    }
  };

const reactorOf = (one, names) => {
  const peer = peerId(one.peerId);
  const custom = one.reaction?.documentId;
  return {
    peer,
    name: names.get(peer) || peer,
    emoji: one.reaction?.emoticon ?? null,
    customEmojiId: custom === undefined ? null : textOf(custom),
    date: Number(one.date) * 1000,
    my: Boolean(one.my),
  };
};

// The names Telegram sent with the page: users and chats by marked id.
const namesIn = (answer) =>
  new Map([
    ...(answer.users ?? []).map((u) => [textOf(u.id), nameOf(u)]),
    ...(answer.chats ?? []).map((c) => [
      c.className === 'Channel' ? `-100${textOf(c.id)}` : `-${textOf(c.id)}`,
      nameOf(c),
    ]),
  ]);

const createReactors =
  (env, userClient) =>
  async (body = {}) => {
    const c = valid(body) ? await connect(env, userClient) : null;
    if (!c) {
      return { ok: false, supported: false };
    }
    const emoji = String(body.emoji ?? '');
    const offset = String(body.offset ?? '');
    try {
      const answer = await runIn(
        env,
        `reactors:${body.chat}:${body.id}:${emoji}:${offset}`,
        () =>
          env.connection.withPeer(c.client, body.chat, (peer) =>
            c.client.invoke(
              new c.Api.messages.GetMessageReactionsList({
                peer,
                id: Number(body.id),
                limit: 50,
                ...(emoji
                  ? { reaction: new c.Api.ReactionEmoji({ emoticon: emoji }) }
                  : {}),
                ...(offset ? { offset } : {}),
              })
            )
          )
      );
      const names = namesIn(answer ?? {});
      const items = (answer?.reactions ?? []).map((one) =>
        reactorOf(one, names)
      );
      return {
        ok: true,
        count: Number(answer?.count ?? items.length),
        items,
        next: answer?.nextOffset || null,
      };
    } catch (error) {
      return failure(error);
    }
  };

// The one reaction of `peer` on message `id`, reported (an admin's act).
const createReportReaction =
  (env, userClient) =>
  async (body = {}) => {
    const c =
      valid(body) && DIGITS.test(String(body.peer ?? ''))
        ? await connect(env, userClient)
        : null;
    if (!c) {
      return { ok: false, supported: false };
    }
    try {
      await runIn(env, `report-reaction:${body.chat}:${body.id}`, () =>
        env.connection.withPeer(c.client, body.chat, (peer) =>
          env.connection.withPeer(c.client, String(body.peer), (reactionPeer) =>
            c.client.invoke(
              new c.Api.messages.ReportReaction({
                peer,
                id: Number(body.id),
                reactionPeer,
              })
            )
          )
        )
      );
      return { ok: true };
    } catch (error) {
      return failure(error);
    }
  };

export const createReadersActions = (env, context) => ({
  reportReaction: createReportReaction(env, context.userClient),
  messageReaders: createReaders(env, context.userClient),
  messageReactors: createReactors(env, context.userClient),
});

/**
 * One-time repairs of Telegram messages already in the store, each run
 * once (its marker link says it ran) when the account starts.
 *
 * `senders-v1`: a message read raw — from an update or a channel's
 * difference — was stored with its chat as its sender, because GramJS
 * fills `senderId` only for the messages it builds itself. Its author is
 * in `raw.fromId` (R-Y28 kept it): the sender is set from there, and the
 * name from that person's other messages, so a group shows who wrote
 * what again.
 */

import { unreachableChat } from './telegram-backfill.js';
import { peerChatId } from './telegram-updates.js';

const SOURCE = 'telegram';
const MARKER = 'repair:telegram:senders-v1';

const isGroupMessage = (l) =>
  l?.id?.startsWith(`msg:${SOURCE}:`) &&
  l.chatType !== 'personal_chat' &&
  l.sender !== 'me';

// Stored as the chat although `fromId` names someone else.
const misattributed = (l) => {
  if (!isGroupMessage(l) || String(l.sender) !== String(l.chat)) {
    return false;
  }
  const author = peerChatId(l.raw?.fromId);
  return Boolean(author) && author !== String(l.chat);
};

/** Each sender's name: from the address book, else their messages. */
const namesBySender = (links) => {
  const names = new Map();
  for (const l of links) {
    if (l?.id?.startsWith(`person:${SOURCE}:`) && l.name) {
      names.set(String(l.user), l.name);
    }
  }
  for (const l of links) {
    if (
      isGroupMessage(l) &&
      l.senderName &&
      String(l.sender) !== String(l.chat)
    ) {
      names.set(String(l.sender), names.get(String(l.sender)) ?? l.senderName);
    }
  }
  return names;
};

/**
 * Fix the misattributed senders in `store`; resolves to how many were
 * fixed. Runs once: later calls find the marker and do nothing.
 */
export const repairSenders = async (store, { log = () => {} } = {}) => {
  if (await store.get(MARKER)) {
    return 0;
  }
  const started = Date.now();
  const links = await store.query(
    (l) =>
      l?.id?.startsWith(`msg:${SOURCE}:`) ||
      l?.id?.startsWith(`person:${SOURCE}:`)
  );
  const wrong = links.filter(misattributed);
  const names = namesBySender(links);
  for (const link of wrong) {
    const sender = peerChatId(link.raw.fromId);
    await store.put({
      ...link,
      sender,
      senderName: names.get(sender) ?? null,
    });
  }
  await store.put({
    id: MARKER,
    fixed: wrong.length,
    at: new Date().toISOString(),
  });
  log({
    event: 'telegram_repair_senders',
    scanned: links.length,
    fixed: wrong.length,
    named: wrong.filter((l) => names.has(peerChatId(l.raw.fromId))).length,
    duration_ms: Date.now() - started,
  });
  return wrong.length;
};

// Each chat's messages, a hundred at a time: how many reads failed, and
// how many chats Telegram cannot address.
// While Telegram asks to wait, the queue turns background requests down
// (`code: 'flood-wait'`, `retryAfter` seconds); a repair waits that long
// and asks again, as Telegram's apps do, instead of failing the chat.
const FLOOD_RETRIES = 8;
const pause = (ms) =>
  new Promise((resolve) => globalThis.setTimeout(resolve, ms).unref?.());

const askPatiently = async (refresh, request, wait) => {
  for (let tries = 0; ; tries += 1) {
    try {
      return await refresh(request);
    } catch (error) {
      if (error?.code !== 'flood-wait' || tries >= FLOOD_RETRIES) {
        throw error;
      }
      await wait(Math.max(1, Number(error.retryAfter) || 30) * 1000);
    }
  }
};

// Why a read failed, as a short code: never a chat id, name or text (R-Y222).
const reasonOf = (error) =>
  String(
    error?.code ??
      error?.errorMessage ??
      String(error?.message ?? error)
        .replace(/\d+/g, '')
        .slice(0, 40)
  );

const readAgain = async (byChat, refresh, priority, wait = pause) => {
  const reasons = {};
  let failed = 0;
  let unreachable = 0;
  for (const [chat, ids] of byChat) {
    for (let at = 0; at < ids.length; at += 100) {
      try {
        await askPatiently(
          refresh,
          { chat, ids: ids.slice(at, at + 100), priority },
          wait
        );
      } catch (error) {
        if (unreachableChat(error)) {
          unreachable += 1;
          break;
        }
        failed += 1;
        const reason = reasonOf(error);
        reasons[reason] = (reasons[reason] ?? 0) + 1;
      }
    }
  }
  return { failed, unreachable, reasons };
};

/**
 * `unsupported-layer-N`: what Telegram sent as `messageMediaUnsupported`
 * while GramJS spoke an older layer (./telegram-layer.js, R-Y76) is read
 * again at the current one, a chat at a time in the background, so a
 * checklist, a new poll or newer media shows as it is. Resolves to how
 * many messages were asked for; a failed chat is asked again on the next
 * start (the marker is set only when every chat was read). A chat
 * Telegram cannot address (R-Y80) is passed over, not failed: asking
 * again would not reach it either (R-Y82).
 */
export const rereadUnsupported = async (
  store,
  { refresh, layer, rev, log = () => {}, priority = 'prefetch', wait } = {}
) => {
  // `rev`: the schema file's revision (R-Y220), so a regenerated file at
  // the same layer asks once more.
  const marker = `repair:telegram:unsupported-layer-${layer}${rev ? `-r${rev}` : ''}`;
  if (!refresh || !layer || (await store.get(marker))) {
    return 0;
  }
  const started = Date.now();
  const links = await store.query(
    (l) =>
      l?.id?.startsWith(`msg:${SOURCE}:`) &&
      !l.deleted &&
      l.raw?.media?.className === 'MessageMediaUnsupported'
  );
  const byChat = new Map();
  for (const l of links) {
    const id = Number(l.id.split(':').pop());
    if (Number.isInteger(id) && id > 0) {
      byChat.set(String(l.chat), [...(byChat.get(String(l.chat)) ?? []), id]);
    }
  }
  const { failed, unreachable, reasons } = await readAgain(
    byChat,
    refresh,
    priority,
    wait
  );
  const left = (
    await store.query(
      (l) =>
        l?.id?.startsWith(`msg:${SOURCE}:`) &&
        !l.deleted &&
        l.raw?.media?.className === 'MessageMediaUnsupported'
    )
  ).length;
  if (failed === 0) {
    await store.put({
      id: marker,
      asked: links.length,
      left,
      at: new Date().toISOString(),
    });
  }
  log({
    event: 'telegram_repair_unsupported',
    layer,
    chats: byChat.size,
    asked: links.length,
    left,
    failed,
    reasons,
    unreachable,
    duration_ms: Date.now() - started,
  });
  return links.length;
};

// A forward whose source the store cannot name: no name from Telegram,
// none stored, and its channel, group or person not among the chats.
const unnamedForward = (l, chats) => {
  const fwd = l.raw?.fwdFrom;
  if (!fwd || fwd.fromName || l.forwardedFrom?.name || l.deleted) {
    return false;
  }
  const from = peerChatId(fwd.fromId);
  return Boolean(from) && !chats.has(from);
};

/**
 * `forward-names-v1`: a forward stored before its source's name was kept
 * (R-Y90) shows only "Forwarded message" when that channel, group or
 * person is not one of the user's chats — Telegram Desktop names it, as
 * Telegram sends the source with the message. Such forwards are read
 * again in the background, which stores the name. Resolves to how many
 * were asked for; a failed chat is asked again on the next start.
 */
export const nameForwards = async (
  store,
  { refresh, log = () => {}, priority = 'prefetch', wait } = {}
) => {
  const marker = 'repair:telegram:forward-names-v1';
  if (!refresh || (await store.get(marker))) {
    return 0;
  }
  const started = Date.now();
  const messages = await store.query((l) =>
    l?.id?.startsWith(`msg:${SOURCE}:`)
  );
  const chats = new Set(messages.map((l) => String(l.chat)));
  const unnamed = (list) => list.filter((l) => unnamedForward(l, chats));
  const links = unnamed(messages);
  const byChat = new Map();
  for (const l of links) {
    const id = Number(l.id.split(':').pop());
    if (Number.isInteger(id) && id > 0) {
      byChat.set(String(l.chat), [...(byChat.get(String(l.chat)) ?? []), id]);
    }
  }
  const { failed, unreachable, reasons } = await readAgain(
    byChat,
    refresh,
    priority,
    wait
  );
  const left = unnamed(
    await store.query((l) => l?.id?.startsWith(`msg:${SOURCE}:`))
  ).length;
  if (failed === 0) {
    await store.put({
      id: marker,
      asked: links.length,
      left,
      at: new Date().toISOString(),
    });
  }
  log({
    event: 'telegram_repair_forward_names',
    chats: byChat.size,
    asked: links.length,
    left,
    failed,
    reasons,
    unreachable,
    duration_ms: Date.now() - started,
  });
  return links.length;
};

/**
 * A bot asking for a chat or a person, and a chat's recent places, as
 * Telegram Desktop has them (R-Y208; learned, never copied):
 * - `requestPeerCandidates({ type })` — the chats and people the bot's
 *   "request peer" keyboard button may be answered with: only those that
 *   satisfy the button's constraints. `type` is `{ kind: 'user' | 'chat' |
 *   'broadcast', bot?, premium?, creator?, hasUsername?, forum?,
 *   userAdminRights?: [right names] }` (booleans as the button gave them;
 *   unset means any). The check runs here, on the entities Telegram sent
 *   (the user's rights in a chat), never on the page → `{ ok, candidates:
 *   [{ id, name, username }] }`. What only the bot can fulfil (that it is
 *   a member, the rights it will get) is left to Telegram;
 * - `sendRequestedPeers({ chat, msgId, buttonId, peers })` — the answer
 *   (messages.sendBotRequestedPeer) with the chosen ids as input peers;
 * - `recentLocations({ chat })` — the places shared in a chat lately
 *   (messages.getRecentLocations) → `{ ok, places: [{ id, lat, lon, date,
 *   title, address }] }`, newest first.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';

const CODES = {
  PEER_ID_INVALID: 'no-access',
  CHANNEL_PRIVATE: 'no-access',
  CHAT_ID_INVALID: 'no-access',
  MESSAGE_ID_INVALID: 'not-found',
  BUTTON_ID_INVALID: 'not-found',
  REQUESTED_PEER_INVALID: 'bad-peer',
  PEER_TYPE_INVALID: 'bad-peer',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);

const CHAT = /^-?\d{1,20}$/;
const KINDS = ['user', 'chat', 'broadcast'];
const MAX_PEERS = 10;
const LIMIT = 20;
const DIALOGS = 300;

const textOf = (value) => String(value?.value ?? value);
const bad = () => ({ ok: false, error: 'bad request', code: 'failed' });

const nameOf = (entity) =>
  entity?.title ||
  [entity?.firstName, entity?.lastName].filter(Boolean).join(' ') ||
  entity?.username ||
  '';

/** Whether `type` is a well-formed request type of the page. */
export const validType = (type) =>
  Boolean(type) &&
  KINDS.includes(type.kind) &&
  ['bot', 'premium', 'creator', 'hasUsername', 'forum'].every(
    (k) => type[k] === undefined || typeof type[k] === 'boolean'
  ) &&
  (type.userAdminRights === undefined ||
    (Array.isArray(type.userAdminRights) &&
      type.userAdminRights.every((r) => /^[a-zA-Z]{1,40}$/.test(r))));

const hasName = (entity) =>
  Boolean(entity.username) ||
  (entity.usernames ?? []).some((u) => u.active !== false && u.username);

// A boolean constraint: unset means any.
const fits = (want, have) => want === undefined || want === Boolean(have);

// Whether the user holds all of `rights` in the chat: its creator does.
const holdsRights = (entity, rights = []) =>
  rights.length === 0 ||
  Boolean(entity.creator) ||
  rights.every((r) => entity.adminRights?.[r] === true);

const userFits = (entity, type) =>
  entity.className === 'User' &&
  !entity.self &&
  !entity.deleted &&
  fits(type.bot, entity.bot) &&
  fits(type.premium, entity.premium);

const chatFits = (entity, type) => {
  const group =
    entity.className === 'Chat' ||
    (entity.className === 'Channel' && !entity.broadcast);
  return (
    group &&
    !entity.left &&
    !entity.deactivated &&
    (type.creator !== true || Boolean(entity.creator)) &&
    fits(type.hasUsername, hasName(entity)) &&
    fits(type.forum, entity.forum) &&
    holdsRights(entity, type.userAdminRights)
  );
};

const broadcastFits = (entity, type) =>
  entity.className === 'Channel' &&
  Boolean(entity.broadcast) &&
  !entity.left &&
  (type.creator !== true || Boolean(entity.creator)) &&
  fits(type.hasUsername, hasName(entity)) &&
  holdsRights(entity, type.userAdminRights);

const FITS = { user: userFits, chat: chatFits, broadcast: broadcastFits };

/** Whether `entity` (a GramJS user, chat or channel) may answer `type`. */
export const satisfies = (entity, type) =>
  Boolean(entity) && FITS[type.kind](entity, type);

// The people of the address book, for a "user" request.
const contactsOf = async (env, c) => {
  const answer = await runIn(env, 'contacts:list', () =>
    c.client.invoke(new c.Api.contacts.GetContacts({ hash: c.zero }))
  ).catch(() => null);
  return (answer?.users ?? []).map((entity) => ({ entity }));
};

const candidatesOf = async (env, c, type) => {
  const listed = await c.client.getDialogs({ limit: DIALOGS }).catch(() => []);
  const dialogs = [...(listed ?? [])].map((d) => ({
    entity: d.entity,
    id: d.id,
  }));
  const all =
    type.kind === 'user'
      ? [...dialogs, ...(await contactsOf(env, c))]
      : dialogs;
  const seen = new Set();
  const out = [];
  for (const { entity, id } of all) {
    const key = entity ? textOf(id ?? entity.id) : '';
    if (satisfies(entity, type) && !seen.has(key)) {
      seen.add(key);
      out.push({
        id: key,
        name: nameOf(entity) || key,
        username: entity.username ?? null,
      });
    }
  }
  return out.sort((a, b) => a.name.localeCompare(b.name));
};

// The input peer of a chat id.
const inputOf = (c, peer) =>
  typeof peer === 'string'
    ? c.client.getInputEntity(c.helpers.returnBigInt(peer))
    : peer;

/** A shared place of a message of getRecentLocations, or null. */
export const placeOf = (message) => {
  const media = message?.media;
  const geo = media?.geo;
  if (!geo || geo.lat === undefined || geo.long === undefined) {
    return null;
  }
  return {
    id: Number(message.id) || 0,
    lat: Number(geo.lat),
    lon: Number(geo.long),
    date: Number(message.date) || 0,
    title: media.title ? String(media.title) : null,
    address: media.address ? String(media.address) : null,
  };
};

/** True when `peers` is a short list of distinct chat ids. */
export const validPeers = (peers) =>
  Array.isArray(peers) &&
  peers.length > 0 &&
  peers.length <= MAX_PEERS &&
  peers.every((p) => CHAT.test(String(p))) &&
  new Set(peers.map(String)).size === peers.length;

export const createRequestPeer = (env, context) => ({
  requestPeerCandidates: async ({ type } = {}) =>
    validType(type)
      ? connected(env, context.userClient, failure, async (c) => ({
          ok: true,
          candidates: await candidatesOf(env, c, type),
        }))
      : bad(),
  sendRequestedPeers: async ({ chat, msgId, buttonId, peers } = {}) => {
    if (
      !CHAT.test(String(chat ?? '')) ||
      !(Number(msgId) > 0) ||
      !Number.isInteger(buttonId) ||
      !validPeers(peers)
    ) {
      return bad();
    }
    return connected(env, context.userClient, failure, async (c) => {
      const requestedPeers = [];
      for (const id of peers) {
        requestedPeers.push(
          await env.connection.withPeer(c.client, String(id), (peer) =>
            inputOf(c, peer)
          )
        );
      }
      await runIn(env, `request-peer:${chat}:${msgId}`, () =>
        env.connection.withPeer(c.client, String(chat), (peer) =>
          c.client.invoke(
            new c.Api.messages.SendBotRequestedPeer({
              peer,
              msgId: Number(msgId),
              buttonId,
              requestedPeers,
            })
          )
        )
      );
      return { ok: true };
    });
  },
  recentLocations: async ({ chat } = {}) => {
    if (!CHAT.test(String(chat ?? ''))) {
      return bad();
    }
    return connected(env, context.userClient, failure, async (c) => {
      const answer = await runIn(env, `recent-locations:${chat}`, () =>
        env.connection.withPeer(c.client, String(chat), (peer) =>
          c.client.invoke(
            new c.Api.messages.GetRecentLocations({
              peer,
              limit: LIMIT,
              hash: c.zero,
            })
          )
        )
      );
      return {
        ok: true,
        places: (answer?.messages ?? []).map(placeOf).filter(Boolean),
      };
    });
  },
});

/**
 * Notification sounds, as Telegram Desktop's "Sound" in a chat's
 * notifications has them (R-Y181; learned, never copied):
 *
 * - `ringtoneList()` — the account's saved ringtones
 *   (account.getSavedRingtones) → `{ ok, ringtones: [{ id, title,
 *   duration, size }], limits: { sizeBytes, seconds, count } }`;
 * - `ringtoneAdd({ token })` — the page's upload (R-Y99) sent as a new
 *   ringtone (account.uploadRingtone, then account.saveRingtone) →
 *   `{ ok, ringtone }`; Telegram takes a short, small audio file;
 * - `ringtoneRemove({ id })` — account.saveRingtone with unsave;
 * - `ringtoneFile({ id })` — a saved ringtone's audio, downloaded once
 *   into the app folder, for the page to play when a notification shows.
 * Telegram's errors become codes the page shows as text. The sound of one
 * chat is set with that chat's notification settings
 * (./telegram-notify-settings.js).
 */

import { promises as fs } from 'node:fs';
import path from 'node:path';
import { locationOf, bigSize, readCache } from './telegram-media.js';
import { uploadedFile } from './telegram-chat-edit.js';
import { connected, failureOf, runIn } from './telegram-stickers.js';

const CODES = {
  RINGTONE_INVALID: 'invalid',
  RINGTONE_MIME_INVALID: 'bad-type',
  RINGTONE_SIZE_TOO_BIG: 'too-big',
  RINGTONE_DURATION_TOO_LONG: 'too-long',
  RINGTONE_NOT_FOUND: 'unknown',
  DOCUMENT_INVALID: 'invalid',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);

export const ID = /^\d{1,20}$/;
// What Telegram takes (its app config's ringtone_size_max,
// ringtone_duration_max, ringtone_saved_count_max).
export const LIMITS = Object.freeze({
  sizeBytes: 300 * 1024,
  seconds: 5,
  count: 100,
});

const TYPES = {
  mp3: 'audio/mpeg',
  ogg: 'audio/ogg',
  opus: 'audio/ogg',
  m4a: 'audio/mp4',
  aac: 'audio/aac',
  wav: 'audio/wav',
};

const text = (value) =>
  value === null || value === undefined ? '' : String(value.value ?? value);

const attribute = (doc, name) =>
  (doc?.attributes ?? []).find((a) => a?.className === name) ?? null;

/** The mime type for an audio file's name, or null when not an audio. */
export const mimeOfName = (name) =>
  TYPES[
    String(name ?? '')
      .split('.')
      .pop()
      .toLowerCase()
  ] ?? null;

/** A saved ringtone's document as the page's row. */
export const ringtoneRow = (doc) => {
  const name = attribute(doc, 'DocumentAttributeFilename')?.fileName;
  return {
    id: text(doc.id),
    title: String(name ?? '').replace(/\.[^.]{1,5}$/, '') || text(doc.id),
    duration: Number(attribute(doc, 'DocumentAttributeAudio')?.duration ?? 0),
    size: Number(doc.size ?? 0),
  };
};

export const createRingtones = (env, { userClient, uploads, mediaDir }) => {
  const known = new Map(); // id -> Document
  const flights = new Map();

  const list = (c) =>
    runIn(env, 'ringtones:list', async () => {
      const got = await c.client.invoke(
        new c.Api.account.GetSavedRingtones({ hash: c.zero })
      );
      known.clear();
      for (const doc of got?.ringtones ?? []) {
        known.set(text(doc.id), doc);
      }
      return [...known.values()].map(ringtoneRow);
    });

  const ringtoneList = async () =>
    connected(env, userClient, failure, async (c) => ({
      ok: true,
      ringtones: await list(c),
      limits: LIMITS,
    }));

  const input = (c, doc) =>
    new c.Api.InputDocument({
      id: doc.id,
      accessHash: doc.accessHash,
      fileReference: doc.fileReference,
    });

  const ringtoneAdd = async ({ token } = {}) => {
    const key = String(token ?? '');
    const entry = uploads?.uploadOf?.(key);
    const mimeType = mimeOfName(entry?.name);
    try {
      if (!entry || !mimeType) {
        return { ok: false, error: 'not an audio file', code: 'bad-type' };
      }
      if (Number(entry.size) > LIMITS.sizeBytes) {
        return { ok: false, error: 'too big', code: 'too-big' };
      }
      return await connected(env, userClient, failure, (c) =>
        runIn(env, 'ringtones:add', async () => {
          const file = await uploadedFile({ ...c, env }, uploads, key);
          const doc = await c.client.invoke(
            new c.Api.account.UploadRingtone({
              file,
              fileName: entry.name,
              mimeType,
            })
          );
          await c.client.invoke(
            new c.Api.account.SaveRingtone({
              id: input(c, doc),
              unsave: false,
            })
          );
          known.set(text(doc.id), doc);
          return { ok: true, ringtone: ringtoneRow(doc) };
        })
      );
    } finally {
      await uploads?.dropUpload?.(key);
    }
  };

  const ringtoneRemove = async ({ id } = {}) => {
    const key = String(id ?? '');
    if (!ID.test(key)) {
      return { ok: false, error: 'bad request', code: 'failed' };
    }
    return connected(env, userClient, failure, async (c) => {
      if (!known.has(key)) {
        await list(c);
      }
      const doc = known.get(key);
      if (!doc) {
        return { ok: false, error: 'unknown ringtone', code: 'unknown' };
      }
      await runIn(env, 'ringtones:remove', () =>
        c.client.invoke(
          new c.Api.account.SaveRingtone({ id: input(c, doc), unsave: true })
        )
      );
      known.delete(key);
      return { ok: true };
    });
  };

  const fetchAudio = (key, file) =>
    connected(
      env,
      userClient,
      () => null,
      async (c) => {
        if (!known.has(key)) {
          await list(c);
        }
        const doc = known.get(key);
        if (!doc || Number(doc.size ?? 0) > LIMITS.sizeBytes * 2) {
          return null;
        }
        const buffer = await c.client.downloadFile(
          locationOf(c.Api, c.helpers, {
            kind: 'document',
            file: doc,
            thumb: '',
          }),
          {
            dcId: Number(doc.dcId),
            fileSize: bigSize(c.helpers, Number(doc.size ?? 0)),
          }
        );
        if (!buffer?.length) {
          return null;
        }
        const mimeType = String(doc.mimeType ?? 'audio/mpeg');
        await fs.mkdir(path.dirname(file), { recursive: true });
        await fs.writeFile(file, buffer);
        await fs.writeFile(`${file}.type`, mimeType);
        return { buffer: Buffer.from(buffer), mimeType };
      }
    );

  const ringtoneFile = async ({ id } = {}) => {
    const key = String(id ?? '');
    if (!ID.test(key) || !mediaDir) {
      return null;
    }
    const file = path.join(mediaDir, 'ringtones', key);
    const cached = await readCache(file);
    const type = cached ? String(await readCache(`${file}.type`)) : '';
    if (cached && /^audio\//.test(type)) {
      return { buffer: cached, mimeType: type };
    }
    if (!flights.has(key)) {
      flights.set(
        key,
        fetchAudio(key, file)
          .catch(() => null)
          .finally(() => flights.delete(key))
      );
    }
    return flights.get(key);
  };

  return { ringtoneList, ringtoneAdd, ringtoneRemove, ringtoneFile };
};

// Round video messages, "video notes" (R-Y150; learned, never copied):
// the page records a square clip from the camera and uploads it; this
// builds what Telegram needs to show it as a circle — a document with
// DocumentAttributeVideo { roundMessage, duration, w, h } and no caption.

// A round video lasts a minute at most; its side is a square of up to
// 1280 pixels (Telegram's apps record 384 or 640).
export const MAX_ROUND_SECONDS = 60;
export const MAX_ROUND_SIDE = 1280;

const clamp = (value, min, max) =>
  Math.max(min, Math.min(max, Math.round(Number(value) || 0)));

const isMp4 = (name) => /\.mp4$/i.test(String(name ?? ''));

/** The mime type a clip's name says: MP4, else the WebM browsers record. */
export const roundMime = (name) => (isMp4(name) ? 'video/mp4' : 'video/webm');

/**
 * What the send needs of the page's words: whole seconds (1..60), the
 * square's side, the reply and when.
 */
export const roundOptions = ({
  duration = 0,
  size = 0,
  replyTo = null,
  silent = false,
  scheduleDate = null,
}) => ({
  seconds: clamp(duration, 1, MAX_ROUND_SECONDS),
  side: clamp(size || 240, 1, MAX_ROUND_SIDE),
  extra: {
    ...(replyTo ? { replyTo } : {}),
    ...(silent ? { silent: true } : {}),
    ...(scheduleDate ? { scheduleDate } : {}),
  },
});

/** The DocumentAttributeVideo of a round video. */
export const roundAttribute = (Api, options) =>
  new Api.DocumentAttributeVideo({
    roundMessage: true,
    supportsStreaming: true,
    duration: options.seconds,
    w: options.side,
    h: options.side,
  });

/** GramJS's sendFile options for a round video; no caption. */
export const roundFileOf = (upload, options) => (telegram) => {
  const CustomFile =
    telegram.client?.uploads?.CustomFile ?? telegram.CustomFile;
  const name = isMp4(upload.name) ? 'round.mp4' : 'round.webm';
  return {
    file: new CustomFile(name, upload.size, upload.path),
    forceDocument: false,
    mimeType: roundMime(name),
    attributes: [roundAttribute(telegram.Api, options)],
    clearDraft: true,
    ...options.extra,
  };
};

/** Select a working AES backend before teleproto initializes cifrante. */
export const configureTelegramCrypto = ({
  deno = Boolean(globalThis.Deno?.version?.deno),
  platform = process.platform,
  env = process.env,
} = {}) => {
  // cifrante 0.6.0's Windows native addon terminates Deno with 0xC0000005
  // during IGE construction. Its supported WASM backend passes the same
  // offline cipher comparisons. This must precede the first native probe;
  // a JavaScript catch cannot recover from an access violation.
  if (deno && platform === 'win32') {
    env.CIFRANTE_NATIVE = '0';
  }
};

/**
 * Reaction tags of Saved Messages, as Telegram Desktop has them (R-Y151;
 * learned, never copied): a saved message tagged with a reaction can be
 * found by it, and Premium accounts name the tags.
 * - `savedTags()` — messages.getSavedReactionTags → `{ ok, premium, tags:
 *   [{ reaction, title, count }] }`; a `reaction` is `{ emoji }` or
 *   `{ custom }` (a custom emoji's document id); `premium` says the
 *   account may rename tags;
 * - `savedTagSearch({ chat, reaction, offsetId? })` — the saved messages
 *   with that reaction (messages.search in the account's own chat,
 *   savedReaction, no filter), a page of 50, as the page's message links
 *   of the Saved Messages chat `chat`, oldest first → `{ ok, messages,
 *   more }`;
 * - `savedTagRename({ reaction, title })` — messages.updateSavedReactionTag
 *   (an empty title removes the name; at most TITLE_MAX characters;
 *   Premium only).
 * Telegram's errors become codes the page shows as text.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';

export const TITLE_MAX = 12;
export const TAG_PAGE = 50;

const CODES = {
  PREMIUM_ACCOUNT_REQUIRED: 'premium',
  REACTION_INVALID: 'bad-reaction',
  FLOOD_WAIT: 'flood',
};
const failure = failureOf(CODES);
const BAD = { ok: false, error: 'bad request', code: 'bad-request' };
const text = (value) => String(value?.value ?? value ?? '');

/** Whether the page's reaction is `{ emoji }` or `{ custom }` and sane. */
export const validReaction = (r) =>
  Boolean(r) &&
  typeof r === 'object' &&
  ((typeof r.emoji === 'string' &&
    r.emoji.length > 0 &&
    r.emoji.length <= 32 &&
    r.custom === undefined) ||
    (typeof r.custom === 'string' &&
      /^\d{1,20}$/.test(r.custom) &&
      r.emoji === undefined));

const inputOf = (c, r) =>
  r.emoji === undefined
    ? new c.Api.ReactionCustomEmoji({
        documentId: c.helpers.returnBigInt(r.custom),
      })
    : new c.Api.ReactionEmoji({ emoticon: r.emoji });

// Telegram's reaction as the page's.
const shapeReaction = (reaction) => {
  if (reaction?.className === 'ReactionCustomEmoji') {
    return { custom: text(reaction.documentId) };
  }
  return reaction?.className === 'ReactionEmoji'
    ? { emoji: String(reaction.emoticon) }
    : null;
};

/** Telegram's tags as the page's list. */
export const tagsOf = (answer) =>
  (answer?.tags ?? [])
    .map((tag) => ({
      reaction: shapeReaction(tag.reaction),
      title: String(tag.title ?? ''),
      count: Number(tag.count ?? 0) || 0,
    }))
    .filter((tag) => tag.reaction);

const usable = (m) => m && m.id !== undefined && m.className !== 'MessageEmpty';

export const createSavedTags = (env, { userClient, tools }) => {
  const doing = (key, use) =>
    connected(env, userClient, failure, (c) => runIn(env, key, () => use(c)));

  const savedTags = async () =>
    doing('saved-tags', async (c) => {
      const answer = await c.client.invoke(
        new c.Api.messages.GetSavedReactionTags({ hash: c.zero })
      );
      const me = await c.client.getMe?.().catch(() => null);
      return {
        ok: true,
        premium: Boolean(me?.premium),
        tags: tagsOf(answer),
      };
    });

  const savedTagSearch = async ({ chat, reaction, offsetId = 0 } = {}) =>
    !/^\d{1,20}$/.test(String(chat ?? '')) || !validReaction(reaction)
      ? BAD
      : doing(`saved-tag-search:${chat}`, async (c) => {
          const answer = await c.client.invoke(
            new c.Api.messages.Search({
              peer: new c.Api.InputPeerSelf(),
              q: '',
              savedReaction: [inputOf(c, reaction)],
              filter: new c.Api.InputMessagesFilterEmpty(),
              minDate: 0,
              maxDate: 0,
              offsetId,
              addOffset: 0,
              limit: TAG_PAGE,
              maxId: 0,
              minId: 0,
              hash: c.zero,
            })
          );
          const found = [...(answer?.messages ?? [])].filter(usable);
          const messages = found.sort((a, b) => Number(a.id) - Number(b.id));
          return {
            ok: true,
            messages: tools.toLinks(
              { id: String(chat), isUser: true },
              messages
            ),
            more: found.length >= TAG_PAGE,
          };
        });

  const savedTagRename = async ({ reaction, title } = {}) => {
    const name = typeof title === 'string' ? title.trim() : null;
    return name === null || name.length > TITLE_MAX || !validReaction(reaction)
      ? BAD
      : doing('saved-tag-rename', async (c) => {
          await c.client.invoke(
            new c.Api.messages.UpdateSavedReactionTag({
              reaction: inputOf(c, reaction),
              ...(name ? { title: name } : {}),
            })
          );
          return { ok: true, title: name };
        });
  };

  return { savedTags, savedTagSearch, savedTagRename };
};

/**
 * Scheduled messages, as Telegram's apps keep them (R-Y102; Telegram
 * Desktop's "Schedule message" and its scheduled messages section,
 * learned, never copied).
 *
 * A message sent with a `schedule_date` is not in the chat: Telegram
 * holds it and sends it then (the chat gets it as a new message). The
 * chat's scheduled ones are listed apart:
 *
 * - `scheduledList({ chat })` — messages.getScheduledHistory, as links
 *   (`sched:telegram:<chat>:<id>`, the time it goes as their time), the
 *   soonest first. Kept a little while, so opening a chat again does not
 *   ask again; anything done to them here asks afresh.
 * - `scheduledSendNow({ chat, ids })` — messages.sendScheduledMessages:
 *   sent at once (they come into the chat as new messages).
 * - `scheduledDelete({ chat, ids })` — messages.deleteScheduledMessages.
 * - `scheduledReschedule({ chat, id, date })` — messages.editMessage with
 *   a new schedule_date.
 *
 * "Send when online" (R-Y197): `schedule_date` 0x7FFFFFFE, which
 * Telegram's clients use for a message held until the other person is
 * next online; the list shows it as "When online", not as a date.
 */

const SOURCE = 'telegram';
const KEEP_MS = 30_000;
export const MAX_SCHEDULED_IDS = 100;
// Telegram takes a time from a few seconds to a year ahead.
export const MIN_AHEAD_S = 10;
export const MAX_AHEAD_S = 366 * 86_400;

/** The `schedule_date` of a message held until the person is online. */
export const WHEN_ONLINE = 0x7f_ff_ff_fe;

/** Whether `date` (unix seconds) is a time Telegram schedules for. */
export const validSchedule = (date, nowS = Math.floor(Date.now() / 1000)) =>
  date === WHEN_ONLINE ||
  (Number.isInteger(date) &&
    date >= nowS + MIN_AHEAD_S &&
    date <= nowS + MAX_AHEAD_S);

export const scheduledId = (chat, id) => `sched:${SOURCE}:${chat}:${id}`;

/**
 * `env` is the account's; `userClient()` the connected user client or
 * null; `apply(client, result)` takes Telegram's answer through the live
 * handler; `dialogOf(chat)` the chat as listed; `tools.toLinks` turns
 * messages into links.
 */
export const createScheduled = (
  env,
  { userClient, apply, dialogOf, tools },
  { now = () => Date.now() } = {}
) => {
  const kept = new Map(); // chat -> { at, links }

  const ask = async (chat, use) => {
    const client = chat ? await userClient() : null;
    if (!client) {
      return null;
    }
    const { Api } = await env.importer();
    return env.connection.withPeer(client, String(chat), (peer) =>
      use({ client, Api, peer })
    );
  };

  const toScheduled = async (chat, messages) => {
    const links = tools.toLinks(await dialogOf(chat), messages);
    return links
      .map((link) => ({
        ...link,
        id: scheduledId(chat, link.id.split(':').pop()),
        scheduled: true,
      }))
      .sort((a, b) => String(a.timestamp).localeCompare(b.timestamp));
  };

  const scheduledList = async ({ chat, fresh = false } = {}) => {
    const target = String(chat ?? '');
    const known = kept.get(target);
    if (!fresh && known && now() - known.at < KEEP_MS) {
      return { ok: true, chat: target, links: known.links };
    }
    const answer = await ask(target, ({ client, Api, peer }) =>
      client.invoke(new Api.messages.GetScheduledHistory({ peer, hash: 0 }))
    );
    if (!answer) {
      return { ok: false, supported: false };
    }
    const messages = (answer.messages ?? []).filter(
      (m) => m && m.className !== 'MessageEmpty'
    );
    const links = await toScheduled(target, messages);
    kept.set(target, { at: now(), links });
    return { ok: true, chat: target, links };
  };

  // A change to the chat's scheduled ones: Telegram's answer through the
  // live handler, and the list asked afresh.
  const change = async (chat, use) => {
    const target = String(chat ?? '');
    let client = null;
    const result = await ask(target, (context) => {
      client = context.client;
      return use(context);
    });
    if (!client) {
      return { ok: false, supported: false };
    }
    if (result && typeof result === 'object') {
      await apply(client, result);
    }
    kept.delete(target);
    return { ok: true, chat: target };
  };

  const idsOf = (ids) =>
    (Array.isArray(ids) ? ids : [])
      .map(Number)
      .filter((n) => Number.isInteger(n) && n > 0)
      .slice(0, MAX_SCHEDULED_IDS);

  const scheduledSendNow = ({ chat, ids } = {}) =>
    change(chat, ({ client, Api, peer }) =>
      client.invoke(
        new Api.messages.SendScheduledMessages({ peer, id: idsOf(ids) })
      )
    );

  const scheduledDelete = ({ chat, ids } = {}) =>
    change(chat, ({ client, Api, peer }) =>
      client.invoke(
        new Api.messages.DeleteScheduledMessages({ peer, id: idsOf(ids) })
      )
    );

  const scheduledReschedule = ({ chat, id, date } = {}) =>
    change(chat, ({ client, Api, peer }) =>
      client.invoke(
        new Api.messages.EditMessage({
          peer,
          id: Number(id),
          scheduleDate: date,
        })
      )
    );

  /** Forget what is kept for `chat` (a message was just scheduled). */
  const scheduledChanged = (chat) => {
    kept.delete(String(chat));
  };

  return {
    scheduledList,
    scheduledSendNow,
    scheduledDelete,
    scheduledReschedule,
    scheduledChanged,
  };
};

/**
 * Search in one chat, as Telegram's apps do it (R-Y98): Telegram is
 * asked (messages.search through GramJS's getMessages, the chat's every message, not only those the
 * page holds), newest first, a page at a time; the messages found are
 * stored as any read ones are, so the chat can show them at once.
 *
 * `searchChat({ chat, q, offsetId? })` → `{ ids, count, more }`: the
 * network ids found (newest first), how many Telegram counts in all,
 * and whether there are older ones (ask again with the last id). With
 * `links: true` (a hashtag's list, R-Y182) it also answers `messages`
 * (the found ones as links) and `cursor` (the last id, when there is more).
 */

export const SEARCH_PAGE = 50;
export const MAX_QUERY = 256;

/**
 * `env` is the account's; `userClient()` the user client or null;
 * `dialogOf(chat)` the chat as listed; `tools` its `toLinks` and
 * `writeChanged`.
 */
export const createChatSearch = (env, { userClient, dialogOf, tools }) => {
  const searchChat = async ({ chat, q, offsetId = 0, links = false } = {}) => {
    const query = String(q ?? '')
      .trim()
      .slice(0, MAX_QUERY);
    const client = chat && query ? await userClient() : null;
    if (!client) {
      return { ok: false, supported: false };
    }
    const target = String(chat);
    const offset = Number(offsetId);
    // GramJS's getMessages with `search` is messages.search, its answer
    // built as history's is (senders named); `total` is Telegram's count.
    const found = await env.queue.run(
      `search:${target}:${query}:${offset}`,
      'view',
      () =>
        env.connection.withPeer(client, target, (peer) =>
          client.getMessages(peer, {
            search: query,
            limit: SEARCH_PAGE,
            ...(Number.isInteger(offset) && offset > 0
              ? { offsetId: offset }
              : {}),
          })
        )
    );
    const messages = [...(found ?? [])].filter(
      (m) => m && m.id !== undefined && m.className !== 'MessageEmpty'
    );
    const shown = tools.toLinks(await dialogOf(target), messages);
    await tools.writeChanged(env.store, shown);
    const ids = messages.map((m) => Number(m.id));
    const count = Number(found?.total ?? ids.length) || ids.length;
    const more = ids.length === SEARCH_PAGE; // a full page: older ones may be
    return {
      ok: true,
      ids,
      count,
      more,
      // A hashtag's list (R-Y182) wants the messages, and where to go on.
      ...(links
        ? {
            messages: shown.map(({ raw: _raw, ...row }) => row),
            cursor: more ? String(ids.at(-1)) : null,
          }
        : {}),
    };
  };
  return { searchChat };
};

/**
 * More of Settings → Privacy and Security (R-Y218; learned, never copied):
 * - `loginEmailSend({ email })` — account.sendVerifyEmailCode with the
 *   purpose "login change" → `{ ok, pattern, length }`;
 *   `loginEmailVerify({ code })` — account.verifyEmail → `{ ok, email }`;
 * - `recoveryRequest()` — auth.requestPasswordRecovery (the recovery email
 *   gets a code) → `{ ok, pattern }`; `recoveryConfirm({ code })` —
 *   auth.recoverPassword with no new settings: the password is removed;
 * - `passwordReset()` — account.resetPassword → `{ ok, result: 'ok' |
 *   'wait' | 'failed-wait', until }`; `passwordResetCancel()` —
 *   account.declinePasswordReset;
 * - `passkeys()` — account.getPasskeys; `passkeyOptions()` —
 *   account.initPasskeyRegistration → `{ ok, options }` (WebAuthn JSON);
 *   `passkeyRegister({ id, rawId, clientData, attestation })` —
 *   account.registerPasskey (attestation in base64url);
 *   `passkeyDelete({ id })` — account.deletePasskey;
 * - `signInCodes()` — the login codes Telegram's service account (777000)
 *   sent in the last few minutes; `invalidateCodes({ codes })` —
 *   account.invalidateSignInCodes, asked when the user shares such a code.
 * A code is never logged or put in an error. Telegram's errors become codes;
 * a change whose answer never came is `send-unknown` (./telegram-write-outcome.js).
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';
import { writeFailureOf } from './telegram-write-outcome.js';

const CODES = {
  EMAIL_INVALID: 'email-invalid',
  EMAIL_NOT_ALLOWED: 'email-not-allowed',
  EMAIL_VERIFY_EXPIRED: 'code-expired',
  CODE_INVALID: 'code-invalid',
  CODE_EMPTY: 'code-invalid',
  CODE_HASH_INVALID: 'code-invalid',
  PASSWORD_RECOVERY_NA: 'recovery-na',
  PASSWORD_RECOVERY_EXPIRED: 'code-expired',
  PASSWORD_HASH_INVALID: 'wrong-password',
  RESET_REQUEST_MISSING: 'no-reset',
  PASSKEY_CREDENTIAL_INVALID: 'passkey-invalid',
  PASSKEY_ID_INVALID: 'passkey-invalid',
  FLOOD_WAIT: 'flood',
};
const failure = failureOf(CODES);
const writeFailure = writeFailureOf(CODES);
const bad = { ok: false, error: 'bad-request', code: 'bad-request' };

/** The service account that sends login codes. */
export const SERVICE_ID = '777000';
/** How long a login code counts as fresh, in seconds. */
export const FRESH_SECONDS = 5 * 60;
const EMAIL = /^[^\s@]{1,64}@[^\s@]{1,255}$/;
const CODE = /^[0-9A-Za-z]{1,16}$/;
const text = (v) => (typeof v === 'string' ? v : '');

/** The 5 or 6 digit codes in a text (a pure helper). */
export const codesIn = (body) =>
  [...String(body ?? '').matchAll(/(?<!\d)\d{5,6}(?!\d)/g)].map((m) => m[0]);

/** The fresh codes of service messages `[{ message, date }]`. */
export const freshCodes = (messages, nowSeconds) => [
  ...new Set(
    (messages ?? [])
      .filter((m) => nowSeconds - Number(m.date ?? 0) <= FRESH_SECONDS)
      .flatMap((m) => codesIn(m.message))
  ),
];

const toIso = (seconds) =>
  seconds ? new Date(Number(seconds) * 1000).toISOString() : null;

const passkeyOf = (p) => ({
  id: String(p.id),
  name: p.name ?? '',
  created: toIso(p.date),
  lastUsed: toIso(p.lastUsageDate),
});

const RESETS = {
  'account.ResetPasswordOk': () => ({ result: 'ok' }),
  'account.ResetPasswordRequestedWait': (a) => ({
    result: 'wait',
    until: toIso(a.untilDate),
  }),
  // Too early to ask again: an error that carries the date.
  'account.ResetPasswordFailedWait': (a) => ({
    ...{ ok: false, error: 'failed-wait', code: 'reset-wait' },
    result: 'failed-wait',
    until: toIso(a.retryDate),
  }),
};

const registerOk = (r) =>
  [r.id, r.rawId, r.clientData, r.attestation].every(
    (v) => typeof v === 'string' && v !== '' && v.length < 100_000
  );

const registration = (c, r) =>
  new c.Api.account.RegisterPasskey({
    credential: new c.Api.InputPasskeyCredentialPublicKey({
      id: r.id,
      rawId: r.rawId,
      response: new c.Api.InputPasskeyResponseRegister({
        clientData: new c.Api.DataJSON({ data: r.clientData }),
        attestationData: Buffer.from(r.attestation, 'base64url'),
      }),
    }),
  });

const historyOf = (c, peer) =>
  new c.Api.messages.GetHistory({
    peer,
    ...{ offsetId: 0, offsetDate: 0, addOffset: 0, limit: 5 },
    ...{ maxId: 0, minId: 0, hash: c.zero },
  });

const codesOk = (r) =>
  Array.isArray(r.codes) &&
  r.codes.length > 0 &&
  r.codes.length <= 10 &&
  r.codes.every((v) => /^\d{5,6}$/.test(text(v)));

export const createSecurityExtras = (env, context) => {
  const run =
    (valid, build, done = () => ({}), fail = writeFailure) =>
    async (request = {}) =>
      valid(request)
        ? connected(env, context.userClient, fail, async (c) => {
            const answer = await runIn(env, 'security', () =>
              c.client.invoke(build(c, request))
            );
            return { ok: true, ...done(answer, request) };
          })
        : bad;
  const any = () => true;
  const change = (c) => new c.Api.EmailVerifyPurposeLoginChange();
  return {
    loginEmailSend: run(
      (r) => EMAIL.test(text(r.email)),
      (c, r) =>
        new c.Api.account.SendVerifyEmailCode({
          purpose: change(c),
          email: r.email,
        }),
      (a) => ({ pattern: a.emailPattern ?? '', length: Number(a.length) || 6 })
    ),
    loginEmailVerify: run(
      (r) => CODE.test(text(r.code)),
      (c, r) =>
        new c.Api.account.VerifyEmail({
          purpose: change(c),
          verification: new c.Api.EmailVerificationCode({ code: r.code }),
        }),
      (a) => ({ email: a.email ?? '' })
    ),
    recoveryRequest: run(
      any,
      (c) => new c.Api.auth.RequestPasswordRecovery(),
      (a) => ({ pattern: a.emailPattern ?? '' })
    ),
    recoveryConfirm: run(
      (r) => CODE.test(text(r.code)),
      (c, r) => new c.Api.auth.RecoverPassword({ code: r.code })
    ),
    passwordReset: run(
      any,
      (c) => new c.Api.account.ResetPassword(),
      (a) => RESETS[a?.className]?.(a) ?? { result: 'ok' }
    ),
    passwordResetCancel: run(
      any,
      (c) => new c.Api.account.DeclinePasswordReset()
    ),
    passkeys: run(
      any,
      (c) => new c.Api.account.GetPasskeys(),
      (a) => ({ passkeys: (a.passkeys ?? []).map(passkeyOf) }),
      failure
    ),
    passkeyOptions: run(
      any,
      (c) => new c.Api.account.InitPasskeyRegistration(),
      (a) => ({ options: text(a.options?.data) }),
      failure
    ),
    passkeyRegister: run(registerOk, registration, (a) => ({
      passkey: passkeyOf(a),
    })),
    passkeyDelete: run(
      (r) => typeof r.id === 'string' && r.id !== '' && r.id.length < 1024,
      (c, r) => new c.Api.account.DeletePasskey({ id: r.id })
    ),
    signInCodes: async (_request, now = Date.now) =>
      connected(env, context.userClient, failure, async (c) => {
        const page = await runIn(env, 'security', () =>
          env.connection.withPeer(c.client, SERVICE_ID, (peer) =>
            c.client.invoke(historyOf(c, peer))
          )
        );
        return {
          ok: true,
          codes: freshCodes(page?.messages, Math.floor(now() / 1000)),
        };
      }),
    invalidateCodes: run(
      codesOk,
      (c, r) => new c.Api.account.InvalidateSignInCodes({ codes: r.codes })
    ),
  };
};

/**
 * The security extras of Settings → Privacy and Security (R-Y177; learned,
 * never copied):
 * - `securityState()` — account.getPassword + account.getAccountTTL +
 *   account.getContentSettings → `{ ok, password: { has, hint, hasRecovery,
 *   emailPending, emailPattern, resetPending }, accountTtlDays, content: {
 *   enabled, canChange } }`; a part Telegram refuses is `null`, all of them
 *   refused is an error;
 * - `setPassword({ current?, password, hint, email? })` — the two-step
 *   verification set or changed: account.updatePasswordSettings with the
 *   check and the digest made by the `telegram` package's own SRP helper
 *   (`computeCheck`, `computeDigest`); a recovery email Telegram must
 *   confirm answers `{ ok: false, code: 'email-unconfirmed', codeLength }`;
 * - `removePassword({ current })` — the same call with an empty digest;
 * - `confirmPasswordEmail({ code })`, `resendPasswordEmail()`,
 *   `cancelPasswordEmail()` — account.confirmPasswordEmail / resend / cancel;
 * - `setAccountTtl({ days })` — account.setAccountTTL (30, 90, 180, 365, 548, 730; R-Y212);
 * - `setSensitive({ enabled })` — account.setContentSettings, only when
 *   Telegram says it can be changed;
 * - `setSessionSettings({ hash, secretChats, calls })` —
 *   account.changeAuthorizationSettings; `setSessionTtl({ days })` —
 *   account.setAuthorizationTTL.
 * Passwords and codes live only in the request in memory: never logged,
 * stored, put in an error or returned. Telegram's errors become codes.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';

export const ACCOUNT_TTL_DAYS = [30, 90, 180, 365, 548, 730];
export const SESSION_TTL_DAYS = [7, 30, 90, 180, 365];
export const PASSWORD_MAX = 256;
export const HINT_MAX = 255;

const CODES = {
  PASSWORD_HASH_INVALID: 'wrong-password',
  EMAIL_UNCONFIRMED: 'email-unconfirmed',
  PASSWORD_TOO_FRESH: 'too-fresh',
  SESSION_TOO_FRESH: 'too-fresh',
  SRP_ID_INVALID: 'srp-invalid',
  SRP_PASSWORD_CHANGED: 'srp-invalid',
  NEW_SETTINGS_INVALID: 'bad-settings',
  EMAIL_INVALID: 'email-invalid',
  CODE_INVALID: 'code-invalid',
  CODE_EMPTY: 'code-invalid',
  EMAIL_HASH_EXPIRED: 'code-expired',
  HASH_INVALID: 'hash-invalid',
  FLOOD_WAIT: 'flood',
};
const failure = failureOf(CODES);
const bad = (code) => ({ ok: false, error: code, code });

const nameOf = (error) => String(error?.errorMessage ?? error?.message ?? '');

// The answer for an error: the e-mail code's length rides along. Only the
// error's name is read, never anything of the request.
const failed = (error) => {
  const answer = failure(error);
  if (answer.code === 'email-unconfirmed') {
    const length = Number(
      /EMAIL_UNCONFIRMED_?(\d+)/.exec(nameOf(error))?.[1] ?? error?.codeLength
    );
    return { ...answer, codeLength: Number.isFinite(length) ? length : 6 };
  }
  return answer;
};

const ask = (env, c, request) =>
  runIn(env, 'security', () => c.client.invoke(request));

const passwordOf = (answer) => ({
  has: Boolean(answer?.hasPassword),
  hint: answer?.hint ?? '',
  hasRecovery: Boolean(answer?.hasRecovery),
  emailPending: Boolean(answer?.emailUnconfirmedPattern),
  emailPattern: answer?.emailUnconfirmedPattern ?? '',
  resetPending: Number(answer?.pendingResetDate ?? 0) > 0,
  // The login email's pattern and the date a reset becomes final (R-Y218).
  loginEmail: answer?.loginEmailPattern ?? '',
  resetDate: answer?.pendingResetDate
    ? new Date(Number(answer.pendingResetDate) * 1000).toISOString()
    : null,
});

const settle = async (promise) => {
  try {
    return { value: await promise };
  } catch (error) {
    return { error };
  }
};

const readState = (env, userClient) => async () =>
  connected(env, userClient, failed, async (c) => {
    const [pwd, ttl, content] = await Promise.all([
      settle(ask(env, c, new c.Api.account.GetPassword())),
      settle(ask(env, c, new c.Api.account.GetAccountTTL())),
      settle(ask(env, c, new c.Api.account.GetContentSettings())),
    ]);
    if (pwd.error && ttl.error && content.error) {
      return failed(pwd.error);
    }
    return {
      ok: true,
      password: pwd.value ? passwordOf(pwd.value) : null,
      accountTtlDays: ttl.value ? Number(ttl.value.days ?? 0) : null,
      content: content.value
        ? {
            enabled: Boolean(content.value.sensitiveEnabled),
            canChange: Boolean(content.value.sensitiveCanChange),
          }
        : null,
    };
  });

// Telegram's salt for a new password gets 32 random bytes of ours.
const freshAlgo = (c, pwd) => {
  const algo = pwd.newAlgo;
  if (algo?.className === 'PasswordKdfAlgoUnknown' || !algo?.salt1) {
    return null;
  }
  algo.salt1 = Buffer.concat([algo.salt1, c.helpers.generateRandomBytes(32)]);
  return algo;
};

const checkOf = (c, srp, pwd, current) =>
  pwd.hasPassword
    ? srp.computeCheck(pwd, current)
    : new c.Api.InputCheckPasswordEmpty();

// One try of the update: the SRP data read fresh, the check and the digest
// made by the package's helper.
const tryUpdate = async (env, c, srp, { current, password, hint, email }) => {
  const pwd = await ask(env, c, new c.Api.account.GetPassword());
  if (pwd.hasPassword && !current) {
    return bad('password-required');
  }
  const algo = freshAlgo(c, pwd);
  if (!algo) {
    return bad('failed');
  }
  const check = await checkOf(c, srp, pwd, current);
  const digest = password
    ? await srp.computeDigest(algo, password)
    : Buffer.alloc(0);
  await ask(
    env,
    c,
    new c.Api.account.UpdatePasswordSettings({
      password: check,
      newSettings: new c.Api.account.PasswordInputSettings({
        newAlgo: algo,
        newPasswordHash: digest,
        hint: password ? hint : '',
        email: password ? email : '',
      }),
    })
  );
  return { ok: true };
};

// The call is repeated once when Telegram says its SRP data went stale.
const update = async (env, c, fields) => {
  const { password: srp } = await env.importer();
  for (let attempt = 0; ; attempt += 1) {
    try {
      return await tryUpdate(env, c, srp, fields);
    } catch (error) {
      if (attempt === 0 && failure(error).code === 'srp-invalid') {
        continue;
      }
      return failed(error);
    }
  }
};

const text = (v) => (typeof v === 'string' ? v : '');

const writePassword =
  (env, userClient) =>
  async (request = {}) => {
    const password = text(request.password);
    const hint = text(request.hint);
    const email = text(request.email);
    const current = text(request.current);
    if (
      !password ||
      password.length > PASSWORD_MAX ||
      current.length > PASSWORD_MAX ||
      hint.length > HINT_MAX
    ) {
      return bad('bad-request');
    }
    if (hint && hint.toLowerCase().includes(password.toLowerCase())) {
      return bad('hint-is-password');
    }
    if (current && current === password) {
      return bad('same-password');
    }
    return connected(env, userClient, failed, (c) =>
      update(env, c, { current, password, hint, email: email || undefined })
    );
  };

const dropPassword =
  (env, userClient) =>
  async (request = {}) => {
    const current = text(request.current);
    if (!current || current.length > PASSWORD_MAX) {
      return bad('bad-request');
    }
    return connected(env, userClient, failed, (c) =>
      update(env, c, { current, password: '', hint: '', email: '' })
    );
  };

// A write with nothing to read back: `build(c)` is its request.
const plain = (env, userClient, build) =>
  connected(env, userClient, failed, async (c) => {
    await ask(env, c, build(c));
    return { ok: true };
  });

const confirmEmail =
  (env, userClient) =>
  async (request = {}) => {
    const code = text(request.code);
    if (!/^[0-9A-Za-z]{1,16}$/.test(code)) {
      return bad('bad-request');
    }
    return plain(
      env,
      userClient,
      (c) => new c.Api.account.ConfirmPasswordEmail({ code })
    );
  };

const resendEmail = (env, userClient) => async () =>
  plain(env, userClient, (c) => new c.Api.account.ResendPasswordEmail());

const cancelEmail = (env, userClient) => async () =>
  plain(env, userClient, (c) => new c.Api.account.CancelPasswordEmail());

const writeAccountTtl =
  (env, userClient) =>
  async (request = {}) => {
    const { days } = request;
    if (!ACCOUNT_TTL_DAYS.includes(days)) {
      return bad('bad-request');
    }
    const done = await plain(
      env,
      userClient,
      (c) =>
        new c.Api.account.SetAccountTTL({
          ttl: new c.Api.AccountDaysTTL({ days }),
        })
    );
    return done.ok ? { ok: true, days } : done;
  };

const writeSensitive =
  (env, userClient) =>
  async (request = {}) => {
    if (typeof request.enabled !== 'boolean') {
      return bad('bad-request');
    }
    return connected(env, userClient, failed, async (c) => {
      const now = await ask(env, c, new c.Api.account.GetContentSettings());
      if (!now?.sensitiveCanChange) {
        return bad('cannot-change');
      }
      await ask(
        env,
        c,
        new c.Api.account.SetContentSettings(
          request.enabled ? { sensitiveEnabled: true } : {}
        )
      );
      return { ok: true, enabled: request.enabled };
    });
  };

const writeSession =
  (env, userClient) =>
  async (request = {}) => {
    const { hash, secretChats, calls } = request;
    if (
      !/^-?\d{1,20}$/.test(String(hash ?? '')) ||
      typeof secretChats !== 'boolean' ||
      typeof calls !== 'boolean'
    ) {
      return bad('bad-request');
    }
    const done = await plain(
      env,
      userClient,
      (c) =>
        new c.Api.account.ChangeAuthorizationSettings({
          hash: c.helpers.returnBigInt(String(hash)),
          encryptedRequestsDisabled: !secretChats,
          callRequestsDisabled: !calls,
        })
    );
    return done.ok ? { ok: true, secretChats, calls } : done;
  };

const writeSessionTtl =
  (env, userClient) =>
  async (request = {}) => {
    const { days } = request;
    if (!SESSION_TTL_DAYS.includes(days)) {
      return bad('bad-request');
    }
    const done = await plain(
      env,
      userClient,
      (c) =>
        new c.Api.account.SetAuthorizationTTL({ authorizationTtlDays: days })
    );
    return done.ok ? { ok: true, days } : done;
  };

export const createSecurity = (env, context) => ({
  securityState: readState(env, context.userClient),
  setPassword: writePassword(env, context.userClient),
  removePassword: dropPassword(env, context.userClient),
  confirmPasswordEmail: confirmEmail(env, context.userClient),
  resendPasswordEmail: resendEmail(env, context.userClient),
  cancelPasswordEmail: cancelEmail(env, context.userClient),
  setAccountTtl: writeAccountTtl(env, context.userClient),
  setSensitive: writeSensitive(env, context.userClient),
  setSessionSettings: writeSession(env, context.userClient),
  setSessionTtl: writeSessionTtl(env, context.userClient),
});

// The client every send path uses to send as another identity (R-Y141;
// learned, never copied): its send requests carry `send_as`. Apart from
// telegram-send-as.js so the send modules can use it without a cycle.

const PEER_ID = /^-?\d{1,20}$/;
const SENDS =
  /^(messages\.)?(SendMessage|SendMedia|SendMultiMedia|SendInlineBotResult)$/;
// What a confirmed paid send stamps (R-Y184): those and a forward.
const PAID_SENDS =
  /^(messages\.)?(SendMessage|SendMedia|SendMultiMedia|SendInlineBotResult|ForwardMessages)$/;

/** The most Stars one send may be confirmed for. */
export const PAID_STARS_MAX = 1_000_000;

/** Whether `value` is a confirmed total of Stars (a positive whole number). */
export const validPaidStars = (value) =>
  Number.isSafeInteger(value) && value > 0 && value <= PAID_STARS_MAX;

/**
 * `{ allowPaidStars }` for what a body carries, or nothing (R-Y184): the
 * total the user confirmed for a paid send. A value that is not a whole
 * positive number is dropped, so the send goes unpaid and Telegram
 * refuses it (ALLOW_PAYMENT_REQUIRED) instead of charging.
 */
export const paidField = (body) =>
  validPaidStars(body?.allowPaidStars)
    ? { allowPaidStars: body.allowPaidStars }
    : {};

/** Whether `value` is a peer id the page may name, or absent. */
export const validSendAs = (value) =>
  value === undefined || (typeof value === 'string' && PEER_ID.test(value));

const text = (value) => String(value ?? '');

// The input peers an answer named, to send as them without a lookup.
const knownInputs = new WeakMap(); // client -> Map(id -> InputPeer)

export const rememberInputs = (client, inputs) =>
  knownInputs.set(client, inputs);

const invalid = () =>
  Object.assign(new Error('SEND_AS_PEER_INVALID'), {
    errorMessage: 'SEND_AS_PEER_INVALID',
  });

// The input peer of a peer id: one an answer named, else resolved.
export const inputOf = async (env, client, id) => {
  if (!PEER_ID.test(id)) {
    throw invalid();
  }
  return (
    knownInputs.get(client)?.get(id) ??
    env.connection.withPeer(client, id, (peer) => client.getInputEntity(peer))
  );
};

// `client` with `send_as` and the confirmed `allow_paid_stars` set on its
// send requests. The Stars are the very number the user confirmed, never
// computed here: a request that already names its own is left alone.
const stamped = (client, sendAs, paidStars) =>
  new Proxy(client, {
    get: (target, key, receiver) =>
      key === 'invoke'
        ? (request, ...rest) => {
            const name = String(request?.className);
            if (sendAs && SENDS.test(name) && !request.sendAs) {
              request.sendAs = sendAs;
            }
            if (paidStars && PAID_SENDS.test(name) && !request.allowPaidStars) {
              request.allowPaidStars = paidStars;
            }
            return target.invoke(request, ...rest);
          }
        : Reflect.get(target, key, receiver),
  });

/**
 * `client`, or — with a peer id `sendAs` and/or the `paidStars` the user
 * confirmed — a client whose sends go as that peer and carry exactly that
 * many Stars. Rejects (a Telegram error) when the peer is not valid.
 */
export const withSendAs = async (env, client, sendAs, paidStars) => {
  const input = sendAs ? await inputOf(env, client, text(sendAs)) : null;
  return input || validPaidStars(paidStars)
    ? stamped(client, input, validPaidStars(paidStars) ? paidStars : null)
    : client;
};

/**
 * "Send as", as Telegram Desktop has it (R-Y141; learned, never copied):
 * in a supergroup (and a channel's discussion group) the small avatar
 * button left of the box chooses which identity sends.
 * - `sendAsList({ chat })` — who may send in the chat (channels.getSendAs)
 *   and who does by default (channels.getFullChannel → defaultSendAs, else
 *   the user) → `{ ok, current, peers: [{ id, kind, name, username?,
 *   count?, premium? }], premium }`; kept per chat for a few minutes.
 *   `kind` is `user`, `channel` or `group`; `premium` on a peer says
 *   Premium is required to send as it, `premium` on the answer that the
 *   user has it;
 * - `sendAsSave({ chat, sendAs })` — the choice kept by Telegram
 *   (messages.saveDefaultSendAs).
 * `withSendAs(env, client, id)` is what every send path uses: the client
 * whose send requests (messages.sendMessage, sendMedia, sendMultiMedia,
 * sendInlineBotResult — also those GramJS builds inside sendFile) carry
 * `send_as`. Telegram's refusals become codes the page shows as text.
 */

import { connected, runIn, failureOf } from './telegram-stickers.js';
import { inputOf, rememberInputs } from './telegram-send-as-client.js';

const CODES = {
  SEND_AS_PEER_INVALID: 'send-as-invalid',
  PREMIUM_ACCOUNT_REQUIRED: 'premium',
  CHAT_ADMIN_REQUIRED: 'no-rights',
  CHANNEL_PRIVATE: 'no-access',
  PEER_ID_INVALID: 'no-access',
  CHAT_ID_INVALID: 'no-access',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);

const SUPERGROUP = /^-100\d{1,15}$/;
const PEER_ID = /^-?\d{1,20}$/;
const KEEP_MS = 3 * 60_000;
const text = (value) => String(value ?? '');

// A Telegram peer as our chat id and kind.
const peerId = (peer) => {
  switch (peer?.className) {
    case 'PeerUser':
      return { id: text(peer.userId), kind: 'user' };
    case 'PeerChannel':
      return { id: `-100${text(peer.channelId)}`, kind: 'channel' };
    case 'PeerChat':
      return { id: `-${text(peer.chatId)}`, kind: 'group' };
    default:
      return null;
  }
};

const nameOf = (entity) =>
  entity?.title ??
  ([entity?.firstName, entity?.lastName].filter(Boolean).join(' ') ||
    entity?.username ||
    '');

// The entity a peer names, among the answer's users and chats.
const entityOf = (answer, peer) => {
  const key = peer?.userId ?? peer?.channelId ?? peer?.chatId;
  const list = peer?.userId ? answer.users : answer.chats;
  return (list ?? []).find((e) => text(e.id) === text(key));
};

const shapePeer = (answer, one) => {
  const peer = peerId(one.peer);
  if (!peer) {
    return null;
  }
  const entity = entityOf(answer, one.peer);
  const count = Number(entity?.participantsCount);
  return {
    ...peer,
    name: nameOf(entity),
    ...(entity?.username ? { username: text(entity.username) } : {}),
    ...(Number.isFinite(count) && count > 0 ? { count } : {}),
    ...(one.premiumRequired ? { premium: true } : {}),
  };
};

// The input peers an answer names, to send as them without a lookup.
const inputsOf = (c, answer) => {
  const found = new Map();
  for (const user of answer.users ?? []) {
    found.set(
      text(user.id),
      new c.Api.InputPeerUser({
        userId: user.id,
        accessHash: user.accessHash ?? c.zero,
      })
    );
  }
  for (const chat of answer.chats ?? []) {
    if (chat.className === 'Channel') {
      found.set(
        `-100${text(chat.id)}`,
        new c.Api.InputPeerChannel({
          channelId: chat.id,
          accessHash: chat.accessHash ?? c.zero,
        })
      );
    }
  }
  return found;
};

export const createSendAs = (env, { userClient }) => {
  const kept = new Map(); // chat -> { at, answer }
  const now = () => (env.now ?? Date.now)();

  const defaultOf = async (c, peer) => {
    const full = await c.client.invoke(
      new c.Api.channels.GetFullChannel({ channel: peer })
    );
    return peerId(full?.fullChat?.defaultSendAs)?.id ?? null;
  };

  const premiumOf = async (c) =>
    Boolean((await c.client.getMe?.().catch(() => null))?.premium);

  const ask = (c, chat) =>
    runIn(env, `send-as:${chat}`, () =>
      env.connection.withPeer(c.client, chat, async (peer) => {
        const answer = await c.client.invoke(
          new c.Api.channels.GetSendAs({ peer })
        );
        const peers = (answer?.peers ?? [])
          .map((one) => shapePeer(answer, one))
          .filter(Boolean);
        const saved = peers.length > 1 ? await defaultOf(c, peer) : null;
        rememberInputs(c.client, inputsOf(c, answer));
        return {
          ok: true,
          current: saved ?? peers.find((p) => p.kind === 'user')?.id ?? null,
          peers,
          premium: peers.length > 1 ? await premiumOf(c) : false,
        };
      })
    );

  const sendAsList = async ({ chat } = {}) => {
    if (!SUPERGROUP.test(text(chat))) {
      return { ok: false, supported: false };
    }
    const hit = kept.get(chat);
    if (hit && now() - hit.at < KEEP_MS) {
      return hit.answer;
    }
    return connected(env, userClient, failure, async (c) => {
      const answer = await ask(c, chat);
      kept.set(chat, { at: now(), answer });
      return answer;
    });
  };

  const sendAsSave = async ({ chat, sendAs } = {}) => {
    if (!SUPERGROUP.test(text(chat)) || !PEER_ID.test(text(sendAs))) {
      return { ok: false, supported: false };
    }
    return connected(env, userClient, failure, async (c) => {
      const as = await inputOf(env, c.client, text(sendAs));
      await runIn(env, `send-as-save:${chat}`, () =>
        env.connection.withPeer(c.client, chat, (peer) =>
          c.client.invoke(
            new c.Api.messages.SaveDefaultSendAs({ peer, sendAs: as })
          )
        )
      );
      const hit = kept.get(chat);
      if (hit) {
        hit.answer = { ...hit.answer, current: text(sendAs) };
      }
      return { ok: true, current: text(sendAs) };
    });
  };

  return { sendAsList, sendAsSave };
};

/**
 * Sending as the user (MTProto), the way Telegram's own apps do it.
 *
 *   - Exactly once: every message carries a `random_id`. Telegram drops a
 *     second request with the same one (RANDOM_ID_DUPLICATE), so a retry
 *     after a lost answer never posts twice. It is derived from the
 *     composer's `clientId`, so a retry of the same draft reuses it.
 *   - Formatting as Telegram Desktop's: `**bold**`, `__italic__`,
 *     `~~strike~~`, `||spoiler||`, `` `code` ``, ```` ```pre``` ```` and
 *     `[text](link)` go as entities (./telegram-format.js); a lone `*` or
 *     `_` stays as typed.
 *   - Long text is split at Telegram's limit (`message_length_max` from
 *     the server's config, 4096 by default; UTF-16 units, like JS
 *     strings), on a line or word break when there is one, never inside
 *     an emoji, and sent in order.
 *   - Sending clears the chat's cloud draft (`clear_draft`), as Telegram
 *     Desktop always does.
 *   - "Send without sound" (`silent`) and "Schedule message"
 *     (`schedule_date`), as Desktop's Send button menu (R-Y102).
 *   - Telegram's errors become codes the composer can explain.
 */

import { createHash } from 'node:crypto';

import {
  apiEntities,
  parseFormatted,
  sliceFormatted,
} from './telegram-format.js';

export const MAX_MESSAGE_LENGTH = 4096;

const isHighSurrogate = (code) => code >= 0xd800 && code <= 0xdbff;

/**
 * Where to split text into Telegram-sized parts, preferring line/word
 * breaks: `[[start, end], …]` of the text (the break between two parts
 * is dropped).
 */
export const splitRanges = (text, max = MAX_MESSAGE_LENGTH) => {
  const all = String(text ?? '');
  const ranges = [];
  let start = 0;
  while (all.length - start > max) {
    const window = all.slice(start, start + max);
    const cut = Math.max(window.lastIndexOf('\n'), window.lastIndexOf(' '));
    // A break in the first half would leave a tiny part; cut hard instead,
    // but not between the two halves of an emoji (a surrogate pair).
    let at = cut > max / 2 ? cut : max;
    if (at === max && isHighSurrogate(all.charCodeAt(start + max - 1))) {
      at -= 1;
    }
    ranges.push([start, start + at]);
    start += at;
    if (all[start] === '\n' || all[start] === ' ') {
      start += 1;
    }
  }
  if (start < all.length || ranges.length === 0) {
    ranges.push([start, all.length]);
  }
  return ranges;
};

/** Split text into Telegram-sized parts, preferring line/word breaks. */
export const splitMessage = (text, max = MAX_MESSAGE_LENGTH) =>
  splitRanges(text, max).map(([start, end]) =>
    String(text ?? '').slice(start, end)
  );

/**
 * What is typed as Telegram's parts: the markdown made entities
 * (./telegram-format.js), then split at the limit, each part with its
 * own entities.
 */
export const formattedParts = (typed, max = MAX_MESSAGE_LENGTH) => {
  const formatted = parseFormatted(typed);
  return sliceFormatted(formatted, splitRanges(formatted.text, max));
};

/** A stable 64-bit random_id for part `index` of draft `clientId`. */
export const randomIdOf = (clientId, index, helpers) => {
  const seed = clientId ? `${clientId}:${index}` : `${Math.random()}:${index}`;
  const bytes = createHash('sha256').update(seed).digest().subarray(0, 8);
  return helpers.readBigIntFromBuffer(bytes, true, true);
};

const errorText = (error) =>
  String(error?.errorMessage ?? error?.message ?? '');

const codeError = (code, message, extra = {}) =>
  Object.assign(new Error(message), { code, fallback: false, ...extra });

// A refused "send as" (R-Y141).
const refusedSendAs = (text) => {
  if (/SEND_AS_PEER_INVALID/.test(text)) {
    return codeError('send-as-invalid', text);
  }
  return /PREMIUM_ACCOUNT_REQUIRED/.test(text)
    ? codeError('premium-required', text)
    : null;
};

// A paid chat (R-Y184): nothing was paid; the price is not the one the user
// confirmed, or the Stars are not there.
const refusedPaid = (text) => {
  if (/ALLOW_PAYMENT_REQUIRED/.test(text)) {
    return codeError('paid-required', text);
  }
  return /BALANCE_TOO_LOW/.test(text) ? codeError('paid-balance', text) : null;
};

const otherSendError = (error) => {
  const text = errorText(error);
  const flood = /FLOOD_WAIT_?(\d+)?/.exec(text);
  if (flood) {
    const seconds = Number(error?.seconds ?? flood[1] ?? 0) || null;
    return codeError('flood-wait', text, { retryAfter: seconds });
  }
  if (
    /CHAT_WRITE_FORBIDDEN|CHAT_SEND_POLL_FORBIDDEN|CHAT_ADMIN_REQUIRED|USER_BANNED_IN_CHANNEL|CHAT_RESTRICTED|USER_IS_BLOCKED|YOU_BLOCKED_USER|CHAT_SEND_PLAIN_FORBIDDEN/.test(
      text
    )
  ) {
    return codeError('write-forbidden', text);
  }
  if (
    /PEER_ID_INVALID|input entity|CHANNEL_PRIVATE|CHANNEL_INVALID/i.test(text)
  ) {
    return codeError('unknown-chat', text);
  }
  if (/MESSAGE_TOO_LONG|MEDIA_CAPTION_TOO_LONG/.test(text)) {
    return codeError('too-long', text);
  }
  if (/FILE_PARTS_INVALID|FILE_PART_TOO_BIG|FILE_TOO_BIG/.test(text)) {
    return codeError('too-large', text);
  }
  if (/MESSAGE_EMPTY/.test(text)) {
    return codeError('bad-draft', text);
  }
  // Anything else (network, auth): never retried through another channel
  // — a message that may already be sent must not be sent again.
  return codeError(error?.code ?? 'send-failed', text || 'send failed');
};

/** Telegram's error as a composer-friendly `{ code, retryAfter? }` error. */
export const sendError = (error) =>
  refusedSendAs(errorText(error)) ??
  refusedPaid(errorText(error)) ??
  otherSendError(error);

// Whom the message answers, and the part of it quoted; in a forum
// topic (R-Y122), the topic: its first message answered when nothing
// else is, else named as the top one (General needs neither).
export const replyHeader = (Api, replyTo, replyQuote, topic = null) => {
  const inTopic = Number.isInteger(topic) && topic > 1;
  const answers = replyTo || (inTopic ? topic : null);
  return answers
    ? {
        replyTo: new Api.InputReplyToMessage({
          replyToMsgId: answers,
          ...(inTopic && replyTo && replyTo !== topic
            ? { topMsgId: topic }
            : {}),
          ...(replyTo && replyQuote ? { quoteText: replyQuote } : {}),
        }),
      }
    : {};
};

// A client without raw invoke (tests, other libraries).
const sendThroughLibrary = (
  client,
  peer,
  { text, formatting, replyTo, topic, when = {}, preview = null }
) =>
  client.sendMessage(peer, {
    message: text,
    parseMode: false,
    ...(formatting.length > 0 ? { formattingEntities: formatting } : {}),
    ...(replyTo || topic > 1 ? { replyTo: replyTo ?? topic } : {}),
    ...(when.silent ? { silent: true } : {}),
    ...(when.scheduleDate ? { schedule: when.scheduleDate } : {}),
    ...(preview?.noWebpage ? { linkPreview: false } : {}),
  });

// Without sound, and when (R-Y102): Telegram's `silent` and
// `schedule_date`.
const whenFields = ({
  silent = false,
  scheduleDate = null,
  effect = null,
} = {}) => ({
  ...(silent ? { silent: true } : {}),
  ...(scheduleDate ? { scheduleDate } : {}),
  // A message effect (R-Y149): a long, made in sendText.
  ...(effect ? { effect } : {}),
});

// An effect id (decimal string) as the library's long (R-Y149).
export const longOf = (helpers, id) =>
  id && helpers?.returnBigInt ? helpers.returnBigInt(id) : id;

/**
 * `client` with a message effect on the media sends it makes (R-Y161;
 * learned, never copied): GramJS's sendFile has no `effect` option, so
 * messages.sendMedia / sendMultiMedia carry it from here.
 */
export const withEffect = (client, effect) =>
  !effect
    ? client
    : new Proxy(client, {
        get: (target, key, receiver) =>
          key === 'invoke'
            ? (request, ...rest) => {
                if (
                  /^(messages\.)?(SendMedia|SendMultiMedia)$/.test(
                    String(request?.className)
                  ) &&
                  !request.effect
                ) {
                  request.effect = effect;
                }
                return target.invoke(request, ...rest);
              }
            : Reflect.get(target, key, receiver),
      });

// The emoji Telegram's apps send as a die when sent alone (R-Y130).
export const DICE = Object.freeze(['🎲', '🎯', '🏀', '⚽', '🎳', '🎰']);

/** The die a message's whole text names, or null. */
export const diceOf = (text) => {
  const bare = String(text ?? '')
    .trim()
    .replaceAll('\uFE0F', '');
  return DICE.includes(bare) ? bare : null;
};

// The link preview's choice for a part (R-Y145): `noWebpage` sends
// without it, `invertMedia` puts it above the text; a size makes the
// message a messages.sendMedia with the page as InputMediaWebPage (as
// Telegram Desktop does for larger or smaller media).
const absoluteUrl = (url) =>
  /^https?:\/\//i.test(url) ? url : `http://${url}`;
export const previewMedia = (Api, preview) =>
  preview?.previewUrl && preview.previewSize && !preview.noWebpage
    ? new Api.InputMediaWebPage({
        url: absoluteUrl(preview.previewUrl),
        optional: true,
        ...(preview.previewSize === 'large'
          ? { forceLargeMedia: true }
          : { forceSmallMedia: true }),
      })
    : null;

// What a part is sent as: a die (messages.sendMedia) for a lone die's
// emoji, a message with a sized link preview (messages.sendMedia), else
// the text (messages.sendMessage).
const partRequest = (Api, { text, formatting, preview, ...fields }) => {
  const dice = formatting.length === 0 && Api.InputMediaDice && diceOf(text);
  const page = !dice && Api.InputMediaWebPage && previewMedia(Api, preview);
  const flags = preview?.invertMedia ? { invertMedia: true } : {};
  if (page) {
    return new Api.messages.SendMedia({
      ...fields,
      ...flags,
      media: page,
      message: text,
      ...(formatting.length > 0 ? { entities: formatting } : {}),
    });
  }
  return dice
    ? new Api.messages.SendMedia({
        ...fields,
        media: new Api.InputMediaDice({ emoticon: dice }),
        message: '',
      })
    : new Api.messages.SendMessage({
        ...fields,
        ...flags,
        ...(preview?.noWebpage ? { noWebpage: true } : {}),
        message: text,
        ...(formatting.length > 0 ? { entities: formatting } : {}),
      });
};

// One part through messages.SendMessage, with our random_id. `onResult`
// sees Telegram's raw answer: it carries the update counter (pts) that
// the catch-up tracks, and GramJS does not pass RPC answers to the
// update handlers.
const sendPart = async ({
  client,
  Api,
  peer,
  text,
  entities = [],
  randomId,
  replyTo,
  replyQuote = null,
  topic,
  when,
  preview = null,
  onResult,
}) => {
  const formatting = apiEntities(Api, entities);
  if (!Api?.messages?.SendMessage || typeof client.invoke !== 'function') {
    return sendThroughLibrary(client, peer, {
      text,
      formatting,
      replyTo,
      topic,
      when,
      preview,
    });
  }
  const request = partRequest(Api, {
    text,
    formatting,
    preview,
    peer: await client.getInputEntity(peer),
    randomId,
    clearDraft: true,
    ...whenFields(when),
    ...replyHeader(Api, replyTo, replyQuote, topic),
  });
  try {
    const result = await client.invoke(request);
    onResult?.(result);
    if (result?.className === 'UpdateShortSentMessage') {
      return { id: result.id, date: result.date };
    }
    return client._getResponseMessage?.(request, result, peer) ?? null;
  } catch (error) {
    if (/RANDOM_ID_DUPLICATE/.test(errorText(error))) {
      // Telegram already has this exact message (an earlier try got
      // through): it is sent, we just do not know its id here.
      return { id: null, duplicate: true };
    }
    throw error;
  }
};

// The preview's size is for the first part, which holds the link.
const previewOfPart = (preview, index) =>
  index === 0 || !preview ? preview : { ...preview, previewUrl: undefined };

const firstPartOnly = (index, { replyTo, replyQuote }) => ({
  replyTo: index === 0 ? replyTo : null,
  replyQuote: index === 0 ? replyQuote : null,
});

/**
 * Send `text` to `peer`, part by part.
 * Returns `[{ id, date, text, entities, duplicate? }]`, one per part.
 */
const recordSend = (log, fields) =>
  log?.({
    level: 'debug',
    event: 'telegram_send_request',
    clientId: fields.clientId ?? null,
    replyTo: fields.replyTo ?? null,
    quoted: Boolean(fields.replyQuote),
    topic: fields.topic,
    parts: fields.parts,
    scheduled: Boolean(fields.scheduleDate),
  });

export const sendText = async ({
  client,
  Api,
  helpers,
  peer,
  text,
  clientId,
  maxLength = MAX_MESSAGE_LENGTH,
  replyTo = null,
  replyQuote = null,
  topic = null,
  silent,
  scheduleDate,
  effect,
  preview = null,
  onResult,
  log,
}) => {
  const parts = formattedParts(text, maxLength);
  recordSend(log, {
    clientId,
    replyTo,
    replyQuote,
    topic,
    parts: parts.length,
    scheduleDate,
  });
  const sent = [];
  for (const [index, part] of parts.entries()) {
    const randomId = helpers ? randomIdOf(clientId, index, helpers) : undefined;
    const message = await sendPart({
      client,
      Api,
      peer,
      text: part.text,
      entities: part.entities,
      randomId,
      // A long reply answers with its first part, as Telegram's apps do.
      ...firstPartOnly(index, { replyTo, replyQuote }),
      // Every part goes to the topic (R-Y122).
      topic,
      // The effect is the first part's (R-Y149).
      when: {
        silent,
        scheduleDate,
        ...(index === 0 ? { effect: longOf(helpers, effect) } : {}),
      },
      preview: previewOfPart(preview, index),
      onResult,
    });
    sent.push({
      id: message?.id ?? null,
      date: message?.date ?? null,
      text: part.text,
      entities: part.entities,
      ...(message?.duplicate ? { duplicate: true } : {}),
    });
  }
  return sent;
};

/**
 * Who a service message names (R-Y221; learned, never copied). A service
 * message holds only ids ("added 4711"); the names come in the same
 * answer from Telegram, in the message's entity map. `actionNamesOf`
 * reads that map for every person or chat the action names and gives
 * `{ <peer id>: { name, self } }` — a user by its id, a group by `-id`,
 * a channel by `-100id` — which the page words as "Ann added Bob" or
 * "Ann added you". It is kept with the message's `raw` as `actionNames`.
 */

const text = (value) =>
  value === null || value === undefined ? '' : String(value.value ?? value);

// The id fields an action names a person with, as a user id.
const USER_FIELDS = ['userId', 'inviterId', 'newCreatorId', 'botId'];
// The fields that hold a Peer, and the ones that hold a list of them.
const PEER_FIELDS = ['fromId', 'toId', 'peer', 'boostPeer'];
const PEER_LISTS = ['otherParticipants', 'peers'];

// The entity-map key of a Peer (as GramJS's `getPeerId` writes it).
const peerKey = (peer) => {
  if (peer?.userId !== undefined) {
    return text(peer.userId);
  }
  if (peer?.chatId !== undefined) {
    return `-${text(peer.chatId)}`;
  }
  return peer?.channelId === undefined ? '' : `-100${text(peer.channelId)}`;
};

const keysOf = (action) => {
  const keys = (action.users ?? []).map(text);
  for (const field of USER_FIELDS) {
    if (action[field] !== undefined && action[field] !== null) {
      keys.push(text(action[field]));
    }
  }
  const peers = PEER_FIELDS.map((f) => action[f]).concat(
    PEER_LISTS.flatMap((f) => action[f] ?? [])
  );
  return keys.concat(peers.map(peerKey)).filter(Boolean);
};

const nameOf = (entity) =>
  [entity.firstName, entity.lastName].filter(Boolean).join(' ') ||
  entity.title ||
  entity.username ||
  '';

/** `{ <peer id>: { name, self } }` for what a message's action names, or null. */
export const actionNamesOf = (message) => {
  const entities = message?._entities;
  if (!message?.action || typeof entities?.get !== 'function') {
    return null;
  }
  const out = {};
  for (const key of keysOf(message.action)) {
    const entity = entities.get(key);
    const name = entity ? nameOf(entity) : '';
    if (name || entity?.self) {
      out[key] = { name, self: Boolean(entity.self) };
    }
  }
  return Object.keys(out).length > 0 ? out : null;
};

/**
 * Sharing a place and a contact from the composer, as Telegram's apps do
 * (R-Y142; learned, never copied):
 * - `sendLocation({ chat, lat, lon, accuracy?, live?, replyTo?, clientId?,
 *   silent?, scheduleDate? })` — a place (messages.sendMedia with
 *   InputMediaGeoPoint, InputGeoPoint lat/long/accuracyRadius) or, with
 *   `live` (900, 3600 or 28800 seconds), a live location
 *   (InputMediaGeoLive with that period) → `{ ok, chat }`;
 * - `stopLiveLocation({ chat, id })` — "Stop sharing" for our own live
 *   location message (messages.editMessage with InputMediaGeoLive
 *   `stopped`, its point taken from the stored message) → `{ ok }`;
 * - `sendContact({ chat, contact | firstName, lastName, phone, ... })` —
 *   a contact card (InputMediaContact, vcard ''). A picked `contact` is
 *   one of the account's contacts (contacts.getContacts) and its phone is
 *   read here, never taken from the page; a typed card carries its own
 *   validated phone → `{ ok, chat }`.
 * - `updateLiveLocation({ chat, id, lat, lon, accuracy?, heading? })` — the
 *   moving point of our own live location (messages.editMessage with
 *   InputMediaGeoLive, the new InputGeoPoint and `heading` 1..360; R-Y147),
 *   with `proximity` (metres, 1..100000) also the radius of "Notify when
 *   nearby" (proximity_notification_radius; R-Y197)
 *   → `{ ok }`. A place and a contact take `sendAs` (a peer id): sent as
 *   that identity in a supergroup (R-Y147).
 * Telegram's answer goes through the live handler. Errors become codes.
 */

import { runIn, connect, connected, failureOf } from './telegram-stickers.js';
import { randomIdOf, replyHeader, sendError } from './telegram-send.js';
import { withSendAs } from './telegram-send-as-client.js';

export const LIVE_PERIODS = [900, 3600, 28800];
// "Notify when nearby" (R-Y197): the farthest radius, in metres.
export const MAX_PROXIMITY = 100_000;
export const MAX_ACCURACY = 1500;
const NAME_MAX = 64;
const PHONE = /^\+?[0-9][0-9 ()-]{3,22}[0-9]$/;
const CHAT = /^-?\d{1,20}$/;

const CODES = {
  MESSAGE_ID_INVALID: 'not-found',
  MESSAGE_AUTHOR_REQUIRED: 'not-yours',
  GEO_POINT_INVALID: 'bad-place',
  CONTACT_ID_INVALID: 'no-user',
  PEER_ID_INVALID: 'no-access',
  FLOOD_WAIT: 'flood',
  MESSAGE_NOT_MODIFIED: 'unchanged',
  MESSAGE_EDIT_TIME_EXPIRED: 'not-found',
  SEND_AS_PEER_INVALID: 'send-as-invalid',
};
const failure = failureOf(CODES);

const textOf = (value) =>
  value === null || value === undefined ? '' : String(value.value ?? value);

/** A latitude and a longitude within the globe, else null. */
export const validPoint = (lat, lon) =>
  Number.isFinite(lat) &&
  Number.isFinite(lon) &&
  Math.abs(lat) <= 90 &&
  Math.abs(lon) <= 180
    ? { lat, lon }
    : null;

/** The phone as digits with a leading plus, or null when not a phone. */
export const cleanPhone = (value) => {
  const raw = String(value ?? '').trim();
  if (!PHONE.test(raw)) {
    return null;
  }
  const digits = raw.replace(/\D/g, '');
  return digits.length >= 5 && digits.length <= 15 ? `+${digits}` : null;
};

const name = (value, required) => {
  const text = typeof value === 'string' ? value.trim() : '';
  return text.length <= NAME_MAX && (!required || text !== '') ? text : null;
};

const geoPoint = (Api, { lat, lon, accuracy }) =>
  new Api.InputGeoPoint({
    lat,
    long: lon,
    ...(accuracy ? { accuracyRadius: accuracy } : {}),
  });

const placeMedia = (Api, r) =>
  r.live
    ? new Api.InputMediaGeoLive({
        geoPoint: geoPoint(Api, r),
        period: r.live,
      })
    : new Api.InputMediaGeoPoint({ geoPoint: geoPoint(Api, r) });

// The request as it will be sent, or null when the place is not valid.
const placeRequest = (r) => {
  const point = validPoint(r.lat, r.lon);
  const accuracy = r.accuracy === undefined ? 0 : Number(r.accuracy);
  const liveOk = r.live === undefined || LIVE_PERIODS.includes(r.live);
  const accuracyOk =
    Number.isInteger(accuracy) && accuracy >= 0 && accuracy <= MAX_ACCURACY;
  return point && liveOk && accuracyOk && CHAT.test(r.chat)
    ? { ...r, ...point, accuracy }
    : null;
};

// messages.sendMedia of what `makeMedia(c)` builds, the answer through the
// live handler.
const sendMedia = async (env, { userClient, apply }, r, makeMedia) => {
  const c = await connect(env, userClient);
  if (!c) {
    return { ok: false, supported: false };
  }
  try {
    const media = await makeMedia(c);
    const client = await withSendAs(env, c.client, r.sendAs, r.allowPaidStars);
    const result = await runIn(env, `share:${r.chat}`, () =>
      env.connection.withPeer(client, r.chat, (peer) =>
        client.invoke(
          new c.Api.messages.SendMedia({
            peer,
            media,
            message: '',
            randomId: randomIdOf(r.clientId, 0, c.helpers),
            clearDraft: false,
            ...(r.silent ? { silent: true } : {}),
            ...(r.scheduleDate ? { scheduleDate: r.scheduleDate } : {}),
            ...replyHeader(c.Api, r.replyTo, null),
          })
        )
      )
    );
    if (result && typeof result === 'object') {
      await apply(c.client, result);
    }
  } catch (error) {
    if (error?.shared) {
      return { ok: false, error: error.message, code: error.shared };
    }
    throw sendError(error);
  }
  if (r.scheduleDate) {
    env.actions?.scheduledChanged?.(r.chat);
    return { ok: true, chat: r.chat, scheduled: true };
  }
  return { ok: true, chat: r.chat };
};

const bad = (error = 'bad request') => ({ ok: false, error, code: 'failed' });

// A picked contact: the account's own contact list is read now, so the
// phone comes from Telegram and never from the page.
const pickedCard = async (env, c, id) => {
  const answer = await runIn(env, 'share:contacts', () =>
    c.client.invoke(new c.Api.contacts.GetContacts({ hash: c.zero }))
  );
  const user = (answer?.users ?? []).find((u) => textOf(u.id) === id);
  const phone = user?.phone ? `+${String(user.phone).replace(/^\+/, '')}` : '';
  if (!phone) {
    throw Object.assign(new Error('no phone'), { shared: 'no-phone' });
  }
  return {
    phone,
    firstName: user.firstName ?? '',
    lastName: user.lastName ?? '',
  };
};

const contactMedia = (Api, card) =>
  new Api.InputMediaContact({
    phoneNumber: card.phone,
    firstName: card.firstName,
    lastName: card.lastName,
    vcard: '',
  });

const typedCard = (r) => {
  const phone = cleanPhone(r.phone);
  const firstName = name(r.firstName, true);
  const lastName = name(r.lastName ?? '', false);
  return phone && firstName !== null && lastName !== null
    ? { phone, firstName, lastName }
    : null;
};

const createContactSender = (env, context) => async (request) => {
  const r = { ...request, chat: String(request?.chat ?? '') };
  if (!CHAT.test(r.chat)) {
    return bad();
  }
  if (r.contact !== undefined) {
    return /^\d{1,20}$/.test(String(r.contact))
      ? sendMedia(env, context, r, async (c) =>
          contactMedia(c.Api, await pickedCard(env, c, String(r.contact)))
        )
      : bad();
  }
  const card = typedCard(r);
  return card
    ? sendMedia(env, context, r, async (c) => contactMedia(c.Api, card))
    : bad('name and phone required');
};

// Edit our stored live location message with `liveMedia(c, point)`; the
// point defaults to the stored one. Used to stop it and to move it.
const createLiveEditor =
  (env, { userClient, apply }, key) =>
  async ({ chat, id, ...rest } = {}, liveMedia) => {
    const msgId = Number(id);
    if (!CHAT.test(String(chat ?? '')) || !(msgId > 0)) {
      return bad();
    }
    return connected(env, userClient, failure, async (c) => {
      const link = await env.store.get(`msg:telegram:${chat}:${msgId}`);
      const media = link?.raw?.media;
      const point = validPoint(
        Number(media?.geo?.lat),
        Number(media?.geo?.long)
      );
      if (media?.className !== 'MessageMediaGeoLive' || !point) {
        return { ok: false, error: 'not a live location', code: 'not-found' };
      }
      const result = await runIn(env, `${key}:${chat}`, () =>
        env.connection.withPeer(c.client, String(chat), (peer) =>
          c.client.invoke(
            new c.Api.messages.EditMessage({
              peer,
              id: msgId,
              media: liveMedia(c, point, rest),
            })
          )
        )
      );
      if (result && typeof result === 'object') {
        await apply(c.client, result);
      }
      return { ok: true };
    });
  };

const createStopper = (env, context) => {
  const edit = createLiveEditor(env, context, 'share-stop');
  return ({ chat, id } = {}) =>
    edit(
      { chat, id },
      (c, point) =>
        new c.Api.InputMediaGeoLive({
          stopped: true,
          geoPoint: geoPoint(c.Api, point),
        })
    );
};

// A heading in degrees as Telegram takes it (1..360), or undefined.
const headingOf = (value) => {
  const degrees = Math.round(Number(value));
  return Number.isFinite(degrees) && value !== null && value !== undefined
    ? ((degrees % 360) + 360) % 360 || 360
    : undefined;
};

// The live place moved: the new point, and the heading when known.
const createMover = (env, context) => {
  const edit = createLiveEditor(env, context, 'share-move');
  return ({ chat, id, lat, lon, accuracy, heading, proximity } = {}) => {
    const point = validPoint(lat, lon);
    const radius = accuracy === undefined ? 0 : Number(accuracy);
    const near = proximity === undefined ? 0 : Number(proximity);
    if (
      !Number.isInteger(near) ||
      near < 0 ||
      near > MAX_PROXIMITY ||
      !point ||
      !Number.isInteger(radius) ||
      radius < 0 ||
      radius > MAX_ACCURACY
    ) {
      return bad('a valid place required');
    }
    const degrees = headingOf(heading);
    return edit(
      { chat, id },
      (c) =>
        new c.Api.InputMediaGeoLive({
          geoPoint: geoPoint(c.Api, { ...point, accuracy: radius }),
          ...(degrees ? { heading: degrees } : {}),
          ...(near ? { proximityNotificationRadius: near } : {}),
        })
    );
  };
};

export const createShareMedia = (env, context) => ({
  sendLocation: async (request) => {
    const r = placeRequest({ ...request, chat: String(request?.chat ?? '') });
    return r
      ? sendMedia(env, context, r, async (c) => placeMedia(c.Api, r))
      : bad('a valid place required');
  },
  stopLiveLocation: createStopper(env, context),
  updateLiveLocation: createMover(env, context),
  sendContact: createContactSender(env, context),
});

/**
 * A chat's shared media, as the profile column of Telegram's apps lists
 * it (R-Y111): how many photos, videos, files, music, links, voice
 * messages and GIFs the chat has (messages.getSearchCounters), and each
 * kind's messages, newest first, a page at a time (messages.search with
 * the kind's filter, through GramJS's getMessages); the messages read
 * are stored as any read ones are.
 *
 * `sharedCounts({ chat })` → `{ ok, counts: { photos, … } }`;
 * `sharedMedia({ chat, kind, offsetId? })` → `{ ok, messages, count,
 * more, last }`: the messages as links, how many Telegram counts, whether
 * older ones remain (ask again with `last`).
 */

export const SHARED_PAGE = 40;

// Each kind and Telegram's filter for it, in the order the column lists.
export const SHARED_KINDS = Object.freeze({
  photos: 'InputMessagesFilterPhotos',
  videos: 'InputMessagesFilterVideo',
  files: 'InputMessagesFilterDocument',
  music: 'InputMessagesFilterMusic',
  links: 'InputMessagesFilterUrl',
  voice: 'InputMessagesFilterRoundVoice',
  gifs: 'InputMessagesFilterGif',
});

const KIND_OF = new Map(
  Object.entries(SHARED_KINDS).map(([kind, filter]) => [filter, kind])
);

/**
 * `env` is the account's; `userClient()` the user client or null;
 * `dialogOf(chat)` the chat as listed; `tools` its `toLinks` and
 * `writeChanged`.
 */
export const createSharedMedia = (env, { userClient, dialogOf, tools }) => {
  const sharedCounts = async ({ chat } = {}) => {
    const client = chat ? await userClient() : null;
    if (!client) {
      return { ok: false, supported: false };
    }
    const { Api } = await env.importer();
    const target = String(chat);
    const answer = await env.queue.run(`shared-counts:${target}`, 'view', () =>
      env.connection.withPeer(client, target, (peer) =>
        client.invoke(
          new Api.messages.GetSearchCounters({
            peer,
            filters: Object.values(SHARED_KINDS).map((name) => new Api[name]()),
          })
        )
      )
    );
    const counts = Object.fromEntries(
      Object.keys(SHARED_KINDS).map((kind) => [kind, 0])
    );
    for (const counter of answer ?? []) {
      const kind = KIND_OF.get(counter?.filter?.className);
      if (kind) {
        counts[kind] = Number(counter.count) || 0;
      }
    }
    return { ok: true, counts };
  };

  const sharedMedia = async ({ chat, kind, offsetId = 0 } = {}) => {
    const filter = Object.hasOwn(SHARED_KINDS, String(kind))
      ? SHARED_KINDS[kind]
      : null;
    const client = chat && filter ? await userClient() : null;
    if (!client) {
      return { ok: false, supported: false };
    }
    const { Api } = await env.importer();
    const target = String(chat);
    const offset = Number(offsetId);
    const found = await env.queue.run(
      `shared:${target}:${kind}:${offset}`,
      'view',
      () =>
        env.connection.withPeer(client, target, (peer) =>
          client.getMessages(peer, {
            filter: new Api[filter](),
            limit: SHARED_PAGE,
            ...(Number.isInteger(offset) && offset > 0
              ? { offsetId: offset }
              : {}),
          })
        )
    );
    const messages = [...(found ?? [])].filter(
      (m) => m && m.id !== undefined && m.className !== 'MessageEmpty'
    );
    const links = tools.toLinks(await dialogOf(target), messages);
    await tools.writeChanged(env.store, links);
    const last = messages.length ? Number(messages.at(-1).id) : 0;
    return {
      ok: true,
      messages: links,
      count: Number(found?.total ?? links.length) || links.length,
      // A full page: there may be older ones.
      more: messages.length === SHARED_PAGE,
      last,
    };
  };

  return { sharedCounts, sharedMedia };
};

/**
 * Similar channels, as Telegram Desktop shows them in a channel's info
 * (R-Y166; learned, never copied):
 * - `similarChannels({ chat })` — the channels Telegram recommends beside
 *   a channel (channels.getChannelRecommendations) → `{ ok, channels:
 *   [{ chat (-100…), title, username, members, broadcast }] }`. Read only.
 * - `similarJoin({ chat })` — joins a channel (channels.joinChannel); only
 *   ever asked for by the explicit Join click on a channel's preview →
 *   `{ ok, chat }`.
 * Answers are kept five minutes by channel. Errors become codes.
 */

import { connected, runIn, failureOf } from './telegram-stickers.js';

const CODES = {
  CHANNEL_INVALID: 'not-found',
  CHANNEL_PRIVATE: 'private',
  CHANNELS_TOO_MUCH: 'too-many',
  INVITE_REQUEST_SENT: 'request-sent',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);
const BAD = { ok: false, error: 'bad request', code: 'failed' };
const CHANNEL = /^-100\d{1,15}$/;
const KEEP_MS = 5 * 60_000;

const textOf = (value) => String(value?.value ?? value);

/** A channel Telegram sent as the page lists it; null for any other chat. */
export const similarOf = (raw) =>
  raw?.className === 'Channel'
    ? {
        chat: `-100${textOf(raw.id)}`,
        title: raw.title ?? '',
        username: raw.username ?? null,
        members: raw.participantsCount ?? null,
        broadcast: Boolean(raw.broadcast),
      }
    : null;

export const createSimilarChannels = (env, { userClient }) => {
  const kept = new Map(); // chat -> { at, channels }
  const now = env.now ?? Date.now;

  const similarChannels = async (body = {}) => {
    const chat = String(body.chat ?? '');
    if (!CHANNEL.test(chat)) {
      return BAD;
    }
    const have = kept.get(chat);
    if (have && now() - have.at < KEEP_MS) {
      return { ok: true, channels: have.channels };
    }
    return connected(env, userClient, failure, async (c) => {
      const answer = await runIn(env, `similar:${chat}`, () =>
        env.connection.withPeer(c.client, chat, (peer) =>
          c.client.invoke(
            new c.Api.channels.GetChannelRecommendations({ channel: peer })
          )
        )
      );
      const channels = (answer?.chats ?? []).map(similarOf).filter(Boolean);
      kept.set(chat, { at: now(), channels });
      return { ok: true, channels };
    });
  };

  const similarJoin = async (body = {}) => {
    const chat = String(body.chat ?? '');
    if (!CHANNEL.test(chat)) {
      return BAD;
    }
    return connected(env, userClient, failure, async (c) => {
      await runIn(env, `similar-join:${chat}`, () =>
        env.connection.withPeer(c.client, chat, (peer) =>
          c.client.invoke(new c.Api.channels.JoinChannel({ channel: peer }))
        )
      );
      return { ok: true, chat };
    });
  };

  return { similarChannels, similarJoin };
};

/**
 * Telegram Stars, as Telegram Desktop shows them (R-Y176; learned, never
 * copied). Buying Stars is not here: they are bought in the official apps.
 * - `starsStatus()` — payments.getStarsStatus for the user's own peer →
 *   `{ ok, balance }`;
 * - `starsHistory({ filter?, offset? })` — payments.getStarsTransactions
 *   (`filter` all, in or out; a page of 30) → `{ ok, balance,
 *   transactions: [{ id, amount (signed), date, title, description, kind,
 *   source: { kind, name }, refund, pending, failed }], next }`;
 * - `starGifts({ chat, offset? })` — payments.getSavedStarGifts of a person
 *   (a page of 24) → `{ ok, count, mine, gifts: [{ msgId, savedId, from,
 *   fromName, anonymous, date, stars, title, text, hidden, sticker }], next
 *   }`; each `sticker` is the sticker panel's item (the sticker renderer
 *   draws it by id, see telegram-stickers.js);
 * - `starGiftSave({ chat, msgId, unsave })` — payments.saveStarGift: shows
 *   a gift on the profile or hides it (a WRITE, on a click only);
 * - `paidReaction({ chat, id, count })` — messages.sendPaidReaction with a
 *   random id (a WRITE, on the dialog's Send only), 1..PAID_REACTION_MAX;
 * - `paidMediaUnlock({ chat, id, stars })` — payments.getPaymentForm with
 *   InputInvoiceMessage, then payments.sendStarsForm with that form id, only
 *   when the form's price is the `stars` the page showed (a WRITE, on the
 *   confirmation only); the message is read again after.
 * Telegram's errors become codes the page shows as text.
 */

import { connected, failureOf, panelItem, runIn } from './telegram-stickers.js';
import { randomIdOf } from './telegram-send.js';

export const HISTORY_PAGE = 30;
export const GIFTS_PAGE = 24;
// Telegram's default limit of one paid reaction (its appConfig may differ).
export const PAID_REACTION_MAX = 2500;

const CODES = {
  BALANCE_TOO_LOW: 'balance',
  STARS_BALANCE_TOO_LOW: 'balance',
  PAYMENT_FAILED: 'balance',
  MESSAGE_ID_INVALID: 'no-message',
  PEER_ID_INVALID: 'no-chat',
  CHANNEL_INVALID: 'no-chat',
  CHANNEL_PRIVATE: 'no-chat',
  REACTION_INVALID: 'not-allowed',
  PAID_REACTION_NOT_ALLOWED: 'not-allowed',
  INVOICE_INVALID: 'no-invoice',
  FORM_ID_EXPIRED: 'expired',
  SAVED_ID_EMPTY: 'no-gift',
  STARGIFT_NOT_FOUND: 'no-gift',
  FLOOD_WAIT: 'flood',
};
const failure = failureOf(CODES);
const BAD = { ok: false, error: 'bad request', code: 'failed' };
const CHAT = /^-?\d{1,20}$/;
const USER = /^\d{1,20}$/;
const text = (value) => String(value?.value ?? value ?? '');
const whole = (n) => Number(n ?? 0) || 0;
const FILTERS = { all: {}, in: { inbound: true }, out: { outbound: true } };

/** A StarsAmount as a number of Stars (nanos are billionths). */
export const amountOf = (amount) =>
  Number(amount?.amount ?? 0) + whole(amount?.nanos) / 1e9;

export const nameOf = (entity) =>
  entity?.title ||
  [entity?.firstName, entity?.lastName].filter(Boolean).join(' ') ||
  (entity?.username ? `@${entity.username}` : '');

export const entitiesOf = (answer) =>
  new Map(
    [...(answer?.users ?? []), ...(answer?.chats ?? [])].map((e) => [
      text(e.id),
      e,
    ])
  );

export const peerEntity = (peer, entities) =>
  entities.get(text(peer?.userId ?? peer?.channelId ?? peer?.chatId));

const KINDS = {
  StarsTransactionPeerFragment: 'fragment',
  StarsTransactionPeerAppStore: 'appstore',
  StarsTransactionPeerPlayMarket: 'playmarket',
  StarsTransactionPeerPremiumBot: 'premiumbot',
  StarsTransactionPeerAds: 'ads',
  StarsTransactionPeerAPI: 'api',
};

/** Where a transaction came from: `{ kind, name }`. */
export const sourceOf = (peer, entities) => {
  if (peer?.className === 'StarsTransactionPeer') {
    return {
      kind: 'peer',
      name: nameOf(peerEntity(peer.peer, entities)),
    };
  }
  return { kind: KINDS[peer?.className] ?? 'unknown', name: '' };
};

// What a transaction is for, as the row's label.
const purposeOf = (t) => {
  if (t.gift || t.stargift) {
    return 'gift';
  }
  if (t.reaction) {
    return 'reaction';
  }
  if ((t.extendedMedia ?? []).length > 0) {
    return 'media';
  }
  return t.subscriptionPeriod ? 'subscription' : '';
};

/** Telegram's transactions as the page's rows. */
export const transactionsOf = (answer) => {
  const entities = entitiesOf(answer);
  return (answer?.history ?? []).map((t) => ({
    id: String(t.id ?? ''),
    amount: amountOf(t.amount),
    date: whole(t.date),
    title: String(t.title ?? ''),
    description: String(t.description ?? ''),
    kind: purposeOf(t),
    source: sourceOf(t.peer, entities),
    refund: Boolean(t.refund),
    pending: Boolean(t.pending),
    failed: Boolean(t.failed),
  }));
};

// A gift's sticker document: a regular gift's, or a unique one's model.
const stickerDoc = (gift) =>
  gift?.sticker ??
  (gift?.attributes ?? []).find(
    (a) => a?.className === 'StarGiftAttributeModel'
  )?.document;

// What can be done to a received gift (R-Y193): its numbers, as Telegram
// gave them (a price of 0 is "free").
const manageOf = (saved) => {
  const gift = saved.gift ?? {};
  const unique = gift.className === 'StarGiftUnique';
  return {
    giftId: text(unique ? gift.giftId : gift.id),
    unique: unique
      ? {
          slug: String(gift.slug ?? ''),
          num: whole(gift.num),
          title: String(gift.title ?? ''),
        }
      : null,
    canUpgrade: Boolean(saved.canUpgrade) && !unique,
    prepaid: Boolean(saved.prepaidUpgradeHash),
    upgradeStars: whole(
      saved.upgradeStars ?? (saved.prepaidUpgradeHash ? 0 : gift.upgradeStars)
    ),
    convertStars: whole(saved.convertStars),
    transferStars: whole(saved.transferStars),
    canTransferAt: whole(saved.canTransferAt),
    pinned: Boolean(saved.pinnedToTop),
  };
};

const giftOf = (saved, entities, remember) => {
  const doc = stickerDoc(saved.gift);
  const anonymous = Boolean(saved.nameHidden) || !saved.fromId;
  return {
    ...manageOf(saved),
    msgId: whole(saved.msgId),
    savedId: text(saved.savedId),
    from: anonymous ? null : text(saved.fromId.userId),
    fromName: anonymous ? '' : nameOf(peerEntity(saved.fromId, entities)),
    anonymous,
    date: whole(saved.date),
    stars: whole(saved.gift?.stars ?? saved.gift?.valueAmount),
    title: String(saved.gift?.title ?? ''),
    text: String(saved.message?.text ?? ''),
    hidden: Boolean(saved.unsaved),
    sticker: doc?.className === 'Document' ? remember(doc) : null,
  };
};

/** Telegram's saved gifts as the page's. */
export const giftsOf = (answer, remember = (doc) => panelItem(doc)) => {
  const entities = entitiesOf(answer);
  return (answer?.gifts ?? []).map((g) => giftOf(g, entities, remember));
};

/** The price of a payment form in Stars: the sum of the invoice's prices. */
export const formPrice = (form) =>
  (form?.invoice?.prices ?? []).reduce((sum, p) => sum + whole(p.amount), 0);

export const createStars = (env, { userClient, stickers }) => {
  // The messages read again once the account's actions exist.
  const refreshMessages = (request) => env.actions?.refreshMessages?.(request);
  const doing = (key, use) =>
    connected(env, userClient, failure, (c) => runIn(env, key, () => use(c)));
  const withChat = (c, chat, use) =>
    env.connection.withPeer(c.client, chat, use);
  const statusOf = (c) =>
    c.client.invoke(
      new c.Api.payments.GetStarsStatus({ peer: new c.Api.InputPeerSelf() })
    );

  const starsStatus = async () =>
    doing('stars:status', async (c) => ({
      ok: true,
      balance: amountOf((await statusOf(c))?.balance),
    }));

  const starsHistory = async ({ filter = 'all', offset = '' } = {}) =>
    !Object.hasOwn(FILTERS, filter) ||
    typeof offset !== 'string' ||
    offset.length > 200
      ? BAD
      : doing(`stars:history:${filter}`, async (c) => {
          const answer = await c.client.invoke(
            new c.Api.payments.GetStarsTransactions({
              ...FILTERS[filter],
              peer: new c.Api.InputPeerSelf(),
              offset,
              limit: HISTORY_PAGE,
            })
          );
          return {
            ok: true,
            balance: amountOf(answer?.balance),
            transactions: transactionsOf(answer),
            next: answer?.nextOffset ? String(answer.nextOffset) : null,
          };
        });

  // A gift's sticker is kept by the sticker lists, so the page's sticker
  // renderer can ask for its picture by id.
  const remember = (chat) => (doc) =>
    stickers?.remember
      ? stickers.remember([doc], `gift:${chat}`, 'sticker')[0]
      : panelItem(doc);

  const starGifts = async ({ chat, offset = '' } = {}) =>
    !USER.test(String(chat ?? '')) ||
    typeof offset !== 'string' ||
    offset.length > 200
      ? BAD
      : doing(`stars:gifts:${chat}`, (c) =>
          withChat(c, String(chat), async (peer) => {
            const answer = await c.client.invoke(
              new c.Api.payments.GetSavedStarGifts({
                peer,
                offset,
                limit: GIFTS_PAGE,
              })
            );
            const me = await c.client.getMe?.().catch(() => null);
            return {
              ok: true,
              count: whole(answer?.count),
              mine: Boolean(me) && text(me.id) === String(chat),
              gifts: giftsOf(answer, remember(String(chat))),
              next: answer?.nextOffset ? String(answer.nextOffset) : null,
            };
          })
        );

  const starGiftSave = async ({ chat, msgId, unsave } = {}) =>
    !USER.test(String(chat ?? '')) ||
    !Number.isInteger(msgId) ||
    msgId < 1 ||
    typeof unsave !== 'boolean'
      ? BAD
      : doing(`stars:gift-save:${chat}`, async (c) => {
          await c.client.invoke(
            new c.Api.payments.SaveStarGift({
              unsave,
              stargift: new c.Api.InputSavedStarGiftUser({ msgId }),
            })
          );
          return { ok: true, hidden: unsave };
        });

  const paidReaction = async ({ chat, id, count } = {}) =>
    !CHAT.test(String(chat ?? '')) ||
    !Number.isInteger(id) ||
    id < 1 ||
    !Number.isInteger(count) ||
    count < 1 ||
    count > PAID_REACTION_MAX
      ? BAD
      : doing(`stars:react:${chat}:${id}`, (c) =>
          withChat(c, String(chat), async (peer) => {
            await c.client.invoke(
              new c.Api.messages.SendPaidReaction({
                peer,
                msgId: id,
                count,
                randomId: randomIdOf(null, 0, c.helpers),
              })
            );
            await refreshMessages?.({ chat: String(chat), ids: [id] });
            return { ok: true, sent: count };
          })
        );

  const paidMediaUnlock = async ({ chat, id, stars } = {}) =>
    !CHAT.test(String(chat ?? '')) ||
    !Number.isInteger(id) ||
    id < 1 ||
    !Number.isInteger(stars) ||
    stars < 1
      ? BAD
      : doing(`stars:unlock:${chat}:${id}`, (c) =>
          withChat(c, String(chat), async (peer) => {
            const invoice = new c.Api.InputInvoiceMessage({ peer, msgId: id });
            const form = await c.client.invoke(
              new c.Api.payments.GetPaymentForm({ invoice })
            );
            if (formPrice(form) !== stars) {
              return { ok: false, error: 'price changed', code: 'price' };
            }
            await c.client.invoke(
              new c.Api.payments.SendStarsForm({ formId: form.formId, invoice })
            );
            await refreshMessages?.({ chat: String(chat), ids: [id] });
            return { ok: true, paid: stars };
          })
        );

  // A gift sticker's file reference expired: its person's gifts, again.
  stickers?.onAgain?.('gift:', (chat) => starGifts({ chat }));

  return {
    starsStatus,
    starsHistory,
    starGifts,
    starGiftSave,
    paidReaction,
    paidMediaUnlock,
  };
};

/**
 * The rest of Telegram Desktop's statistics views (R-Y195; learned, never
 * copied), added to the actions of ./telegram-stats.js:
 * - `messageStats({ chat, id })` — a channel post's views and reactions
 *   graphs (stats.getMessageStats) → `{ ok, graphs: [{ key, graph }] }`;
 * - `publicForwards({ chat, id, offset? })` — the public channels that
 *   shared the post, a page at a time (stats.getMessagePublicForwards) →
 *   `{ ok, count, items: [{ kind, name, chat?, id?, username?, views?,
 *   date? }], next }`, `next` the offset of the following page or null;
 * - `starsRevenue({ chat })` — the Stars a channel (-100…) or a bot (a user
 *   id) earned: the revenue graph, the balances and the USD rate
 *   (payments.getStarsRevenueStats) → `{ ok, graph, topHours?, status:
 *   { current, available, overall, withdrawalEnabled }, usdRate }`; the
 *   graph may come as a token (`stats.loadAsyncGraph`, the stats-graph
 *   route). Withdrawing is not offered here.
 * Read-only. Telegram's errors become codes the page shows as text.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';

const CODES = {
  CHAT_ADMIN_REQUIRED: 'no-access',
  BROADCAST_REQUIRED: 'no-access',
  CHANNEL_PRIVATE: 'no-access',
  MESSAGE_ID_INVALID: 'not-found',
  FLOOD_WAIT: 'flood',
};
const failure = failureOf(CODES);
const bad = { ok: false, error: 'bad request', code: 'failed' };
const noAccess = { ok: false, error: 'no access', code: 'no-access' };
const CHANNEL = /^-100\d{1,15}$/;
const USER = /^\d{1,15}$/;
const OFFSET_MAX = 512;
export const FORWARDS_PAGE = 20;
const SNIPPET = 90;

const num = (value) => Number(value?.value ?? value) || 0;
const textOf = (value) => String(value?.value ?? value);

/** A StarsAmount (`amount` + `nanos`) as a number of Stars. */
export const starsOf = (amount) =>
  num(amount?.amount) + (Number(amount?.nanos) || 0) / 1e9;

const nameOf = (chat) =>
  chat?.title ||
  [chat?.firstName, chat?.lastName].filter(Boolean).join(' ') ||
  chat?.username ||
  '';

const snippetOf = (text) => {
  const clean = String(text ?? '')
    .replace(/\s+/g, ' ')
    .trim();
  return clean.length > SNIPPET ? `${clean.slice(0, SNIPPET)}…` : clean;
};

// One public forward: a channel's post (with a link's parts) or a story.
const forwardOf = (one, chats) => {
  const peer = one.className === 'PublicForwardMessage' ? one.message : one;
  const id = textOf(peer.peerId?.channelId ?? peer.peer?.channelId ?? '');
  const chat = chats.get(id);
  const name = nameOf(chat) || id;
  if (one.className !== 'PublicForwardMessage') {
    return { kind: 'story', name, ...(id ? { chat: `-100${id}` } : {}) };
  }
  const message = one.message;
  return {
    kind: 'message',
    name,
    chat: `-100${id}`,
    id: num(message.id),
    views: num(message.views),
    date: num(message.date),
    text: snippetOf(message.message),
    ...(chat?.username ? { username: String(chat.username) } : {}),
  };
};

const statusOf = (status = {}) => ({
  current: starsOf(status.currentBalance),
  available: starsOf(status.availableBalance),
  overall: starsOf(status.overallRevenue),
  withdrawalEnabled: Boolean(status.withdrawalEnabled),
});

export const createStatsMore = (
  env,
  context,
  { access, invokeOn, dcs, graphOf }
) => {
  const messageStats = async (body = {}) => {
    const chat = String(body.chat ?? '');
    const id = Number(body.id);
    if (!CHANNEL.test(chat) || !Number.isInteger(id) || id <= 0) {
      return bad;
    }
    return connected(env, context.userClient, failure, (c) =>
      runIn(env, `message-stats:${chat}:${id}`, () =>
        env.connection.withPeer(c.client, chat, async (peer) => {
          const may = await access(c, chat, peer);
          if (!may?.broadcast) {
            return noAccess;
          }
          const stats = await invokeOn(
            c,
            chat,
            () => new c.Api.stats.GetMessageStats({ channel: peer, msgId: id })
          );
          const graphs = [
            { key: 'views', graph: graphOf(stats.viewsGraph) },
            { key: 'reactions', graph: graphOf(stats.reactionsByEmotionGraph) },
          ].filter((one) => one.graph);
          return { ok: true, graphs };
        })
      )
    );
  };

  const publicForwards = async (body = {}) => {
    const chat = String(body.chat ?? '');
    const id = Number(body.id);
    const offset = String(body.offset ?? '');
    if (
      !CHANNEL.test(chat) ||
      !Number.isInteger(id) ||
      id <= 0 ||
      offset.length > OFFSET_MAX
    ) {
      return bad;
    }
    return connected(env, context.userClient, failure, (c) =>
      runIn(env, `public-forwards:${chat}:${id}:${offset}`, () =>
        env.connection.withPeer(c.client, chat, async (peer) => {
          if (!dcs.has(chat) && !(await access(c, chat, peer))) {
            return noAccess;
          }
          const answer = await invokeOn(
            c,
            chat,
            () =>
              new c.Api.stats.GetMessagePublicForwards({
                channel: peer,
                msgId: id,
                offset,
                limit: FORWARDS_PAGE,
              })
          );
          const chats = new Map(
            (answer.chats ?? []).map((one) => [textOf(one.id), one])
          );
          const items = (answer.forwards ?? []).map((one) =>
            forwardOf(one, chats)
          );
          return {
            ok: true,
            count: num(answer.count) || items.length,
            items,
            next: answer.nextOffset || null,
          };
        })
      )
    );
  };

  // May the user see the Stars revenue: a channel's or a bot's own flag.
  const mayView = async (c, chat, peer) => {
    if (CHANNEL.test(chat)) {
      const result = await c.client.invoke(
        new c.Api.channels.GetFullChannel({ channel: peer })
      );
      dcs.set(chat, Number(result.fullChat?.statsDc) || 0);
      return Boolean(result.fullChat?.canViewStarsRevenue);
    }
    const result = await c.client.invoke(
      new c.Api.users.GetFullUser({
        id: new c.Api.InputUser({
          userId: peer.userId ?? c.helpers.returnBigInt(chat),
          accessHash: peer.accessHash ?? c.helpers.returnBigInt('0'),
        }),
      })
    );
    dcs.set(chat, 0);
    return Boolean((result.fullUser ?? result).canViewRevenue);
  };

  const starsRevenue = async (body = {}) => {
    const chat = String(body.chat ?? '');
    if (!CHANNEL.test(chat) && !USER.test(chat)) {
      return bad;
    }
    return connected(env, context.userClient, failure, (c) =>
      runIn(env, `stars-revenue:${chat}`, () =>
        env.connection.withPeer(c.client, chat, async (peer) => {
          if (!(await mayView(c, chat, peer))) {
            return noAccess;
          }
          const stats = await invokeOn(
            c,
            chat,
            () => new c.Api.payments.GetStarsRevenueStats({ peer })
          );
          return {
            ok: true,
            graph: graphOf(stats.revenueGraph),
            ...(stats.topHoursGraph
              ? { topHours: graphOf(stats.topHoursGraph) }
              : {}),
            status: statusOf(stats.status),
            usdRate: num(stats.usdRate),
          };
        })
      )
    );
  };

  return { messageStats, publicForwards, starsRevenue };
};

/**
 * Statistics of a channel or a big supergroup, as Telegram Desktop's
 * "Statistics" shows them to its admins (R-Y167; learned, never copied):
 * - `chatStats({ chat })` — a channel's overview (followers, views, shares
 *   and reactions per post, enabled notifications), its graphs and its
 *   recent posts (stats.getBroadcastStats), or a supergroup's overview
 *   (members, messages, viewing and posting members), graphs, top posters,
 *   top admins and top inviters (stats.getMegagroupStats) →
 *   `{ ok, kind: 'broadcast' | 'megagroup', period: { from, to },
 *   overview: [{ key, current, previous }], notifications?: { part, total },
 *   graphs: [{ key, graph }], posts?, posters?, admins?, inviters? }`.
 * - `statsGraph({ chat, token, x? })` — a graph Telegram sent as a token,
 *   or the zoomed one (stats.loadAsyncGraph; `x` the clicked point, ms)
 *   → `{ ok, graph }`.
 * A `graph` is `{ json, zoom? }` (Telegram's chart JSON as text, `zoom` the
 * token that zooms into a day), `{ token }` (to load) or `{ error }`.
 *
 * Statistics live on the DC the full channel names (`stats_dc`). GramJS
 * sends a request to another DC through `client.invoke(request, dcId)`
 * (a borrowed sender, authorised by exporting the account's key); the DC
 * is learned from channels.getFullChannel, kept by chat, and when Telegram
 * still answers STATS_MIGRATE_X the request is asked again on DC X.
 * R-Y195 adds a post's statistics, public shares and Stars revenue
 * (./telegram-stats-more.js), and `statsGraph` also takes a bot's id.
 * Read-only. Telegram's errors become codes the page shows as text.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';
import { createStatsMore } from './telegram-stats-more.js';

const CODES = {
  CHAT_ADMIN_REQUIRED: 'no-access',
  BROADCAST_REQUIRED: 'no-access',
  MEGAGROUP_REQUIRED: 'no-access',
  CHANNEL_PRIVATE: 'no-access',
  GRAPH_OUTDATED_RELOAD: 'outdated',
  GRAPH_INVALID_RELOAD: 'outdated',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);
const bad = { ok: false, error: 'bad request', code: 'failed' };
const noAccess = { ok: false, error: 'no access', code: 'no-access' };
const CHANNEL = /^-100\d{1,15}$/;
const DIGITS = /^\d{1,20}$/;
const BOT = /^\d{1,15}$/;
export const MAX_TOKEN = 1024;
export const POSTS_SHOWN = 20;
const SNIPPET = 90;

const BROADCAST_OVERVIEW = [
  ['followers', 'followers'],
  ['viewsPerPost', 'viewsPerPost'],
  ['sharesPerPost', 'sharesPerPost'],
  ['reactionsPerPost', 'reactionsPerPost'],
];
const BROADCAST_GRAPHS = [
  ['growth', 'growthGraph'],
  ['followers', 'followersGraph'],
  ['mute', 'muteGraph'],
  ['topHours', 'topHoursGraph'],
  ['interactions', 'interactionsGraph'],
  ['ivInteractions', 'ivInteractionsGraph'],
  ['viewsBySource', 'viewsBySourceGraph'],
  ['newFollowersBySource', 'newFollowersBySourceGraph'],
  ['languages', 'languagesGraph'],
  ['reactions', 'reactionsByEmotionGraph'],
];
const MEGAGROUP_OVERVIEW = [
  ['members', 'members'],
  ['messages', 'messages'],
  ['viewers', 'viewers'],
  ['posters', 'posters'],
];
const MEGAGROUP_GRAPHS = [
  ['growth', 'growthGraph'],
  ['members', 'membersGraph'],
  ['newMembersBySource', 'newMembersBySourceGraph'],
  ['languages', 'languagesGraph'],
  ['messages', 'messagesGraph'],
  ['actions', 'actionsGraph'],
  ['topHours', 'topHoursGraph'],
  ['weekdays', 'weekdaysGraph'],
];

const num = (value) => Number(value?.value ?? value) || 0;
const textOf = (value) => String(value?.value ?? value);

/** A StatsGraph as the page takes it: the JSON text, a token or an error. */
export const graphOf = (raw) => {
  switch (raw?.className) {
    case 'StatsGraph':
      return {
        json: String(raw.json?.data ?? ''),
        ...(raw.zoomToken ? { zoom: String(raw.zoomToken) } : {}),
      };
    case 'StatsGraphAsync':
      return { token: String(raw.token) };
    case 'StatsGraphError':
      return { error: String(raw.error ?? '') };
    default:
      return null;
  }
};

const overviewOf = (stats, keys) =>
  keys.map(([key, field]) => ({
    key,
    current: num(stats[field]?.current),
    previous: num(stats[field]?.previous),
  }));

const graphsOf = (stats, keys) =>
  keys
    .map(([key, field]) => ({ key, graph: graphOf(stats[field]) }))
    .filter((one) => one.graph);

const nameOf = (user) =>
  [user?.firstName, user?.lastName].filter(Boolean).join(' ') ||
  user?.username ||
  '';

// People in a top list: the user's id and name beside the figures.
const peopleOf = (list, users, pick) => {
  const byId = new Map((users ?? []).map((u) => [textOf(u.id), u]));
  return (list ?? []).map((one) => {
    const id = textOf(one.userId);
    return { id, name: nameOf(byId.get(id)) || id, ...pick(one) };
  });
};

const megagroupOf = (stats) => ({
  kind: 'megagroup',
  overview: overviewOf(stats, MEGAGROUP_OVERVIEW),
  graphs: graphsOf(stats, MEGAGROUP_GRAPHS),
  posters: peopleOf(stats.topPosters, stats.users, (one) => ({
    messages: num(one.messages),
    avgChars: num(one.avgChars),
  })),
  admins: peopleOf(stats.topAdmins, stats.users, (one) => ({
    deleted: num(one.deleted),
    kicked: num(one.kicked),
    banned: num(one.banned),
  })),
  inviters: peopleOf(stats.topInviters, stats.users, (one) => ({
    invitations: num(one.invitations),
  })),
});

const snippetOf = (message) => {
  const text = String(message?.message ?? '')
    .replace(/\s+/g, ' ')
    .trim();
  return text.length > SNIPPET ? `${text.slice(0, SNIPPET)}…` : text;
};

// The latest posts' counters (not stories), newest first.
const postCounters = (stats) =>
  (stats.recentPostsInteractions ?? [])
    .filter((one) => one.className === 'PostInteractionCountersMessage')
    .sort((a, b) => num(b.msgId) - num(a.msgId))
    .slice(0, POSTS_SHOWN);

const postOf = (one, message) => ({
  id: num(one.msgId),
  views: num(one.views),
  forwards: num(one.forwards),
  reactions: num(one.reactions),
  text: snippetOf(message),
  media: Boolean(
    message?.media && message.media.className !== 'MessageMediaEmpty'
  ),
  ...(message?.date ? { date: num(message.date) } : {}),
});

export const createStats = (env, context) => {
  const dcs = new Map(); // chat -> the DC its statistics live on (0: ours)

  const send = (c, request, dc) =>
    dc && dc !== c.client.session?.dcId
      ? c.client.invoke(request, dc)
      : c.client.invoke(request);

  // Asks on the chat's stats DC; STATS_MIGRATE_X moves it to DC X.
  const invokeOn = async (c, chat, build) => {
    try {
      return await send(c, build(), dcs.get(chat) ?? 0);
    } catch (error) {
      const moved = /STATS_MIGRATE_(\d+)/.exec(
        String(error?.errorMessage ?? error?.message ?? '')
      );
      if (!moved) {
        throw error;
      }
      dcs.set(chat, Number(moved[1]));
      return send(c, build(), Number(moved[1]));
    }
  };

  // The full channel: may the user see statistics, which kind, on which DC.
  const access = async (c, chat, peer) => {
    const result = await c.client.invoke(
      new c.Api.channels.GetFullChannel({ channel: peer })
    );
    const full = result.fullChat ?? {};
    const entity =
      (result.chats ?? []).find((x) => textOf(x.id) === chat.slice(4)) ??
      (result.chats ?? []).find(Boolean) ??
      {};
    dcs.set(chat, Number(full.statsDc) || 0);
    return full.canViewStats ? { broadcast: Boolean(entity.broadcast) } : null;
  };

  const postsOf = async (c, peer, counters) => {
    if (counters.length === 0) {
      return [];
    }
    const answer = await c.client
      .invoke(
        new c.Api.channels.GetMessages({
          channel: peer,
          id: counters.map(
            (one) => new c.Api.InputMessageID({ id: num(one.msgId) })
          ),
        })
      )
      .catch(() => null);
    const byId = new Map((answer?.messages ?? []).map((m) => [num(m.id), m]));
    return counters.map((one) => postOf(one, byId.get(num(one.msgId))));
  };

  const broadcastOf = async (c, chat, peer) => {
    const stats = await invokeOn(
      c,
      chat,
      () => new c.Api.stats.GetBroadcastStats({ channel: peer })
    );
    return {
      stats,
      kind: 'broadcast',
      overview: overviewOf(stats, BROADCAST_OVERVIEW),
      notifications: {
        part: num(stats.enabledNotifications?.part),
        total: num(stats.enabledNotifications?.total),
      },
      graphs: graphsOf(stats, BROADCAST_GRAPHS),
      posts: await postsOf(c, peer, postCounters(stats)),
    };
  };

  const megagroupStats = async (c, chat, peer) => {
    const stats = await invokeOn(
      c,
      chat,
      () => new c.Api.stats.GetMegagroupStats({ channel: peer })
    );
    return { stats, ...megagroupOf(stats) };
  };

  const chatStats = async (body = {}) => {
    const chat = String(body.chat ?? '');
    if (!CHANNEL.test(chat)) {
      return bad;
    }
    return connected(env, context.userClient, failure, (c) =>
      runIn(env, `stats:${chat}`, () =>
        env.connection.withPeer(c.client, chat, async (peer) => {
          const may = await access(c, chat, peer);
          if (!may) {
            return noAccess;
          }
          const { stats, ...made } = may.broadcast
            ? await broadcastOf(c, chat, peer)
            : await megagroupStats(c, chat, peer);
          return {
            ok: true,
            ...made,
            period: {
              from: num(stats.period?.minDate),
              to: num(stats.period?.maxDate),
            },
          };
        })
      )
    );
  };

  const statsGraph = async (body = {}) => {
    const chat = String(body.chat ?? '');
    const token = body.token;
    const x = body.x === undefined ? undefined : String(body.x);
    if (
      !(CHANNEL.test(chat) || BOT.test(chat)) ||
      typeof token !== 'string' ||
      token.length === 0 ||
      token.length > MAX_TOKEN ||
      (x !== undefined && !DIGITS.test(x))
    ) {
      return bad;
    }
    return connected(env, context.userClient, failure, (c) =>
      runIn(env, `stats-graph:${chat}`, () =>
        env.connection.withPeer(c.client, chat, async (peer) => {
          // A bot's statistics (its Stars revenue) are on our own DC.
          if (!CHANNEL.test(chat)) {
            dcs.set(chat, 0);
          } else if (!dcs.has(chat) && !(await access(c, chat, peer))) {
            return noAccess;
          }
          const result = await invokeOn(
            c,
            chat,
            () =>
              new c.Api.stats.LoadAsyncGraph({
                token,
                ...(x === undefined ? {} : { x: c.helpers.returnBigInt(x) }),
              })
          );
          const graph = graphOf(result);
          return graph ? { ok: true, graph } : failure(new Error('failed'));
        })
      )
    );
  };

  return {
    chatStats,
    statsGraph,
    // A post's statistics, its public shares, Stars revenue (R-Y195).
    ...createStatsMore(env, context, { access, invokeOn, dcs, graphOf }),
  };
};

/**
 * Searching stickers and GIFs from the panel by the message box, as
 * Telegram Desktop's (R-Y112; learned, never copied):
 *
 * - `stickerSearch({ q, lang })` — an emoji finds the stickers Telegram
 *   has for it (messages.getStickers); words find stickers by their
 *   keywords (messages.searchStickers) and sticker sets by name, the
 *   user's or not (messages.searchStickerSets), each set's stickers
 *   then asked as any set's are;
 * - `gifSearch({ q, offset })` — GIFs found by Telegram's @gif bot
 *   (messages.getInlineBotResults), a page at a time, as Telegram's
 *   apps search them.
 *
 * What is found is kept ten minutes and may be sent as the panel's own
 * (the documents named by id); an expired file reference asks the
 * search again. Nothing is sent to the bot but the words searched.
 */

import { connect, panelSet, runIn } from './telegram-stickers.js';
import { inputBot, resolveBotUser } from './telegram-inline-bots.js';

const SEARCH_MS = 10 * 60_000;
const KEEP = 40;
const LIMIT = 50;

/** Whether the words are an emoji (no letters or digits in them). */
export const isEmojiQuery = (q) =>
  /\p{Extended_Pictographic}|\p{Regional_Indicator}/u.test(q) &&
  !/[\p{L}\p{N}]/u.test(q);

// The few searches kept, oldest dropped first.
const createKept = (now) => {
  const kept = new Map();
  return {
    get: (key) => {
      const entry = kept.get(key);
      return entry && now() - entry.at < SEARCH_MS ? entry.answer : null;
    },
    set: (key, answer) => {
      kept.delete(key);
      kept.set(key, { at: now(), answer });
      while (kept.size > KEEP) {
        kept.delete(kept.keys().next().value);
      }
      return answer;
    },
  };
};

// A request Telegram refuses (one it does not know, words it will not
// search): nothing found; a wait or a lost session goes on up.
const tolerant = async (use) => {
  try {
    return await use();
  } catch (error) {
    if (error?.code !== 400) {
      throw error;
    }
    return null;
  }
};

const documentsOf = (answer) =>
  (answer?.stickers ?? []).filter((d) => d?.className === 'Document');

// Stickers and sets for words or an emoji.
const findStickers = async (c, q, lang) => {
  if (isEmojiQuery(q)) {
    const got = await tolerant(() =>
      c.client.invoke(
        new c.Api.messages.GetStickers({ emoticon: q, hash: c.zero })
      )
    );
    return { documents: documentsOf(got), sets: [] };
  }
  const found = await tolerant(() =>
    c.client.invoke(
      new c.Api.messages.SearchStickers({
        q,
        emoticon: '',
        langCode: [lang],
        offset: 0,
        limit: LIMIT,
        hash: c.zero,
      })
    )
  );
  const covered = await tolerant(() =>
    c.client.invoke(new c.Api.messages.SearchStickerSets({ q, hash: c.zero }))
  );
  return {
    documents: documentsOf(found),
    sets: (covered?.sets ?? []).map((s) => s?.set).filter(Boolean),
  };
};

// Telegram's @gif bot, found once (the lookup inline bots share).
const createGifBot = (c) => {
  let bot = null;
  return async () => {
    if (!bot) {
      const user = await resolveBotUser(c, 'gif');
      bot = user ? inputBot(c, user) : null;
    }
    return bot;
  };
};

export const createStickerSearch = (env, { userClient, lists, now }) => {
  const kept = createKept(now);
  const bots = new WeakMap(); // client -> its @gif bot
  const run = (key, use) => runIn(env, key, use);

  const stickerSearch = async ({ q, lang = 'en', fresh = false } = {}) => {
    const words = String(q ?? '').trim();
    const key = `stickers:${lang}:${words}`;
    if (!words) {
      return { ok: true, stickers: [], sets: [] };
    }
    if (!fresh && kept.get(key)) {
      return kept.get(key);
    }
    const c = await connect(env, userClient);
    if (!c) {
      return { ok: false, supported: false };
    }
    const found = await run(`stickers:search:${key}`, () =>
      findStickers(c, words, lang)
    );
    found.sets.forEach(lists.learnSet);
    return kept.set(key, {
      ok: true,
      stickers: lists.remember(
        found.documents,
        `stickersearch:${JSON.stringify([words, lang])}`,
        'sticker'
      ),
      sets: found.sets
        .filter((s) => !s.emojis)
        .map((s) => ({
          ...panelSet(s),
          installed: lists.installed(String(s.id)),
        })),
    });
  };

  const gifSearch = async ({ q, offset = '', fresh = false } = {}) => {
    const words = String(q ?? '').trim();
    const at = String(offset ?? '');
    const key = `gifs:${at}:${words}`;
    if (!words) {
      return { ok: true, gifs: [], next: null };
    }
    if (!fresh && kept.get(key)) {
      return kept.get(key);
    }
    const c = await connect(env, userClient);
    if (!c) {
      return { ok: false, supported: false };
    }
    if (!bots.has(c.client)) {
      bots.set(c.client, createGifBot(c));
    }
    const answer = await run(`gifs:search:${key}`, async () => {
      const bot = await bots.get(c.client)();
      return bot
        ? c.client.invoke(
            new c.Api.messages.GetInlineBotResults({
              bot,
              peer: new c.Api.InputPeerSelf(),
              query: words,
              offset: at,
            })
          )
        : null;
    });
    if (!answer) {
      return { ok: false, supported: false };
    }
    const documents = (answer.results ?? [])
      .map((r) => r?.document)
      .filter((d) => d?.className === 'Document');
    return kept.set(key, {
      ok: true,
      gifs: lists.remember(
        documents,
        `gifsearch:${JSON.stringify([words, at])}`,
        'gif'
      ),
      next: answer.nextOffset ? String(answer.nextOffset) : null,
    });
  };

  lists.onAgain('stickersearch:', (rest) => {
    const [q, lang] = JSON.parse(rest);
    return stickerSearch({ q, lang, fresh: true });
  });
  lists.onAgain('gifsearch:', (rest) => {
    const [q, offset] = JSON.parse(rest);
    return gifSearch({ q, offset, fresh: true });
  });

  return { stickerSearch, gifSearch };
};

/**
 * The user's sticker and custom emoji sets, as Telegram Desktop's
 * Settings → Stickers and emoji manages them (R-Y169; learned, never
 * copied):
 * - `setsList({ emojis })` — the installed sets in the user's order
 *   (messages.getAllStickers, or getEmojiStickers for emoji sets) →
 *   `{ ok, sets: [{ id, title, count, format, emoji, official }] }`;
 * - `setsReorder({ ids, emojis })` — a new order (messages.reorderStickerSets);
 * - `setArchive({ id })` — a set archived (messages.installStickerSet with
 *   archived), `setRemove({ id })` — removed (uninstallStickerSet),
 *   `setAdd({ id })` — an archived set installed again;
 * - `archivedList({ emojis, offsetId, limit })` — the archived sets, a page
 *   at a time (messages.getArchivedStickers) → `{ ok, count, sets, next }`.
 * Only sets this list (or the panel) showed may be named, by id. The
 * panel's lists are asked again after every change. Telegram's errors
 * become codes the page shows as text.
 */

import {
  connected,
  failureOf,
  inputSet,
  panelSet,
  runIn,
} from './telegram-stickers.js';

const CODES = {
  STICKERSET_INVALID: 'unknown-set',
  STICKERSET_NOT_MODIFIED: 'not-modified',
  STICKERS_TOO_MUCH: 'too-many',
  STICKERSETS_INVALID: 'bad-request',
  OFFSET_INVALID: 'bad-request',
};

const asFailure = failureOf(CODES);
// Nothing to change is no failure.
const failure = (error) => {
  const out = asFailure(error);
  return out.code === 'not-modified' ? { ok: true } : out;
};
const bad = (code) => ({ ok: false, error: code, code });

export const SET_ID = /^-?\d{1,20}$/;
export const MAX_SETS = 1000;
export const MAX_PAGE = 100;

const textOf = (value) => String(value?.value ?? value);

/** A set as the settings list it. */
export const settingsSet = (set) => ({
  ...panelSet(set),
  official: Boolean(set.official),
});

/** The ids of a new order: distinct set ids, one to 1000; else null. */
export const orderOf = (ids) => {
  if (!Array.isArray(ids) || ids.length === 0 || ids.length > MAX_SETS) {
    return null;
  }
  const list = ids.map(String);
  const valid = list.every((id) => SET_ID.test(id));
  return valid && new Set(list).size === list.length ? list : null;
};

const createLister = (env, userClient, hooks) => ({
  setsList: async ({ emojis = false } = {}) =>
    connected(env, userClient, failure, async (c) => {
      const Request = emojis
        ? c.Api.messages.GetEmojiStickers
        : c.Api.messages.GetAllStickers;
      const answer = await runIn(env, `stickers:settings:${emojis}`, () =>
        c.client.invoke(new Request({ hash: c.zero }))
      );
      const sets = (answer?.sets ?? []).filter(
        (s) => Boolean(s.emojis) === Boolean(emojis) && !s.masks
      );
      sets.forEach((set) => hooks.learn(set));
      return { ok: true, sets: sets.map(settingsSet) };
    }),

  archivedList: async (body = {}) => {
    const offsetId = String(body.offsetId ?? '0');
    const limit = Number(body.limit ?? 20);
    if (
      !SET_ID.test(offsetId) ||
      !Number.isInteger(limit) ||
      limit < 1 ||
      limit > MAX_PAGE
    ) {
      return bad('bad-request');
    }
    return connected(env, userClient, failure, async (c) => {
      const answer = await runIn(env, `stickers:archived:${offsetId}`, () =>
        c.client.invoke(
          new c.Api.messages.GetArchivedStickers({
            ...(body.emojis ? { emojis: true } : {}),
            offsetId: c.helpers.returnBigInt(offsetId),
            limit,
          })
        )
      );
      const sets = (answer?.sets ?? []).map((s) => s.set ?? s);
      sets.forEach((set) => hooks.learn(set));
      return {
        ok: true,
        count: Number(answer?.count ?? sets.length),
        sets: sets.map(settingsSet),
        next: sets.length >= limit ? textOf(sets.at(-1).id) : null,
      };
    });
  },
});

const createReorder =
  (env, userClient, hooks) =>
  async ({ ids, emojis = false } = {}) => {
    const order = orderOf(ids);
    if (!order) {
      return bad('bad-request');
    }
    return connected(env, userClient, failure, async (c) => {
      await runIn(env, 'stickers:reorder', () =>
        c.client.invoke(
          new c.Api.messages.ReorderStickerSets({
            ...(emojis ? { emojis: true } : {}),
            order: order.map((id) => c.helpers.returnBigInt(id)),
          })
        )
      );
      hooks.changed();
      return { ok: true };
    });
  };

// Archive, Remove and Add: one known set, one request.
const createChange =
  (env, userClient, hooks, name, request) =>
  async (body = {}) => {
    const id = String(body.id ?? '');
    if (!SET_ID.test(id)) {
      return bad('bad-request');
    }
    const set = hooks.known(id);
    if (!set) {
      return bad('unknown-set');
    }
    return connected(env, userClient, failure, async (c) => {
      await runIn(env, `stickers:${name}:${id}`, () =>
        c.client.invoke(request(c, inputSet(c, set)))
      );
      hooks.changed();
      return { ok: true, id };
    });
  };

/**
 * `stickers`: the sticker module's hooks `{ learn(set), known(id),
 * changed() }` (./telegram-stickers.js).
 */
export const createStickerSets = (env, { userClient, stickers }) => {
  const change = (name, request) =>
    createChange(env, userClient, stickers, name, request);
  return {
    ...createLister(env, userClient, stickers),
    setsReorder: createReorder(env, userClient, stickers),
    setArchive: change(
      'archive',
      (c, stickerset) =>
        new c.Api.messages.InstallStickerSet({ stickerset, archived: true })
    ),
    setAdd: change(
      'add',
      (c, stickerset) =>
        new c.Api.messages.InstallStickerSet({ stickerset, archived: false })
    ),
    setRemove: change(
      'remove',
      (c, stickerset) => new c.Api.messages.UninstallStickerSet({ stickerset })
    ),
  };
};

/**
 * Trending stickers and the other extras of the sticker panel, as
 * Telegram Desktop offers them (R-Y206; learned, never copied):
 * - `featuredStickers({ emojis, old, offset, limit })` — the trending
 *   sticker sets (messages.getFeaturedStickers), further ones a page at a
 *   time (getOldFeaturedStickers), or the trending custom emoji sets
 *   (getFeaturedEmojiStickers) → `{ ok, count, sets, unread, next }`; each
 *   set is `{ id, title, count, format, emoji, installed, unread }`;
 * - `featuredRead({ ids })` — sets seen in the list
 *   (messages.readFeaturedStickers), so they lose their "new" mark;
 * - `recentStickersClear()` — "Clear recent stickers"
 *   (messages.clearRecentStickers);
 * - `attachedStickers({ chat, id })` — the sticker sets used in a photo
 *   or video of a stored message (messages.getAttachedStickers).
 * The sets are learned by the sticker module, so their stickers are asked
 * as any set's, and Add installs them as the panel's Add does. Telegram's
 * errors become codes the page shows as text.
 */

import { connected, failureOf, panelSet, runIn } from './telegram-stickers.js';

const CODES = {
  STICKER_ID_INVALID: 'bad-request',
  MEDIA_INVALID: 'no-stickers',
  FILE_REFERENCE_EXPIRED: 'expired',
  FILE_REFERENCE_INVALID: 'expired',
  OFFSET_INVALID: 'bad-request',
};

const failure = failureOf(CODES);
const bad = (code = 'bad-request') => ({ ok: false, error: code, code });

export const SET_ID = /^-?\d{1,20}$/;
export const MAX_PAGE = 100;
export const MAX_READ = 200;
const CHAT = /^-?\d{1,20}$/;
const MESSAGE = /^\d{1,12}$/;

const textOf = (value) => String(value?.value ?? value);

/** A message's media that can carry stickers: `photo` or `document`, or null. */
export const stickeredOf = (raw) => {
  const media = raw?.media;
  if (media?.className === 'MessageMediaPhoto' && media.photo?.id) {
    return { kind: 'photo', file: media.photo };
  }
  const doc = media?.document;
  const marked = (doc?.attributes ?? []).some(
    (a) => a?.className === 'DocumentAttributeHasStickers'
  );
  return media?.className === 'MessageMediaDocument' && doc?.id && marked
    ? { kind: 'document', file: doc }
    : null;
};

const bytesOf = (value) => {
  if (value instanceof Uint8Array) {
    return Buffer.from(value);
  }
  return typeof value?.bytes === 'string'
    ? Buffer.from(value.bytes, 'base64')
    : Buffer.alloc(0);
};

const stickeredMedia = (c, { kind, file }) => {
  const fields = {
    id: c.helpers.returnBigInt(textOf(file.id)),
    accessHash: c.helpers.returnBigInt(textOf(file.accessHash)),
    fileReference: bytesOf(file.fileReference),
  };
  return kind === 'photo'
    ? new c.Api.InputStickeredMediaPhoto({ id: new c.Api.InputPhoto(fields) })
    : new c.Api.InputStickeredMediaDocument({
        id: new c.Api.InputDocument(fields),
      });
};

// A covered set (stickerSetCovered and its variants) as the page lists it.
const listed = (covered, unread) => {
  const set = covered?.set ?? covered;
  return {
    ...panelSet(set),
    // For the set's box, which names a set by id and access hash.
    accessHash: textOf(set.accessHash),
    installed: Boolean(set.installedDate) && !set.archived,
    unread: unread.has(textOf(set.id)),
  };
};

const featuredRequest = (c, { emojis, old, offset, limit }) => {
  if (emojis) {
    return new c.Api.messages.GetFeaturedEmojiStickers({ hash: c.zero });
  }
  return old
    ? new c.Api.messages.GetOldFeaturedStickers({ offset, limit, hash: c.zero })
    : new c.Api.messages.GetFeaturedStickers({ hash: c.zero });
};

const pageOf = (body) => {
  const offset = Number(body.offset ?? 0);
  const limit = Number(body.limit ?? 20);
  const ok =
    Number.isInteger(offset) &&
    offset >= 0 &&
    Number.isInteger(limit) &&
    limit >= 1 &&
    limit <= MAX_PAGE;
  return ok ? { offset, limit } : null;
};

/**
 * `stickers`: the sticker module's hooks `{ learn(set), changed() }`
 * (./telegram-stickers.js).
 */
export const createStickerTrending = (env, { userClient, stickers: hooks }) => {
  const featuredStickers = async (body = {}) => {
    const page = pageOf(body);
    if (!page) {
      return bad();
    }
    const asked = { emojis: body.emojis === true, old: body.old === true };
    return connected(env, userClient, failure, async (c) => {
      const answer = await runIn(
        env,
        `stickers:featured:${asked.emojis}:${asked.old}:${page.offset}`,
        () => c.client.invoke(featuredRequest(c, { ...asked, ...page }))
      );
      const unread = new Set((answer?.unread ?? []).map(textOf));
      const covered = answer?.sets ?? [];
      covered.forEach((s) => hooks.learn(s?.set ?? s));
      const sets = covered.map((s) => listed(s, unread));
      return {
        ok: true,
        count: Number(answer?.count ?? sets.length),
        sets,
        unread: [...unread],
        next:
          asked.old && !asked.emojis && sets.length >= page.limit
            ? page.offset + sets.length
            : null,
      };
    });
  };

  const featuredRead = async ({ ids } = {}) => {
    const list = Array.isArray(ids) ? ids.map(String) : [];
    if (
      list.length === 0 ||
      list.length > MAX_READ ||
      !list.every((id) => SET_ID.test(id))
    ) {
      return bad();
    }
    return connected(env, userClient, failure, async (c) => {
      await runIn(env, 'stickers:featured-read', () =>
        c.client.invoke(
          new c.Api.messages.ReadFeaturedStickers({
            id: list.map((id) => c.helpers.returnBigInt(id)),
          })
        )
      );
      return { ok: true };
    });
  };

  const recentStickersClear = async () =>
    connected(env, userClient, failure, async (c) => {
      await runIn(env, 'stickers:recent-clear', () =>
        c.client.invoke(new c.Api.messages.ClearRecentStickers({}))
      );
      hooks.changed();
      return { ok: true };
    });

  const attachedStickers = async ({ chat, id } = {}) => {
    if (!CHAT.test(String(chat ?? '')) || !MESSAGE.test(String(id ?? ''))) {
      return bad();
    }
    const stored = await env.store?.get?.(`msg:telegram:${chat}:${id}`);
    const media = stickeredOf(stored?.raw);
    if (!media) {
      return bad('no-stickers');
    }
    return connected(env, userClient, failure, async (c) => {
      const answer = await runIn(env, `stickers:attached:${chat}:${id}`, () =>
        c.client.invoke(
          new c.Api.messages.GetAttachedStickers({
            media: stickeredMedia(c, media),
          })
        )
      );
      const covered = Array.isArray(answer) ? answer : [];
      covered.forEach((s) => hooks.learn(s?.set ?? s));
      return { ok: true, sets: covered.map((s) => listed(s, new Set())) };
    });
  };

  return {
    featuredStickers,
    featuredRead,
    recentStickersClear,
    attachedStickers,
  };
};

/**
 * Stickers and saved GIFs for the panel by the message box, as Telegram
 * Desktop's (R-Y105; learned, never copied):
 *
 * - `stickerPanel({ fresh })` — the user's sticker sets
 *   (messages.getAllStickers), recently sent (getRecentStickers) and
 *   favourite ones (getFavedStickers);
 * - `stickerSet({ id })` — one set's stickers (getStickerSet), asked
 *   when the panel comes to it;
 * - `savedGifs({ fresh })` — the saved GIFs (getSavedGifs);
 * - `stickerPicture({ id | set, full })` — what the panel shows: a
 *   still sticker itself, else a sticker's or GIF's thumbnail, a set's
 *   own picture; `full` a video sticker's or GIF's video, or an
 *   animated sticker's animation (R-Y113), to play while on screen.
 *   Each downloaded once into the app folder;
 * - `stickerSave({ id, action })` — the panel's menu (R-Y115): a sticker
 *   made a favourite or not (messages.faveSticker), taken from the recent
 *   ones (saveRecentSticker), a GIF saved or not (saveGif);
 * - `stickerSetInstall({ id, install })` — a set found by a search added
 *   to the user's (messages.installStickerSet, R-Y116), or one of theirs
 *   removed (uninstallStickerSet);
 * - `stickerSetBox({ id, accessHash } | { shortName })` — the set a
 *   sticker in a chat belongs to (messages.getStickerSet, R-Y124), for
 *   the box a click on it opens: the set, its stickers and whether it is
 *   the user's. The set and its documents join the lists, so the install
 *   above and the send below accept them;
 * - `sendDocument({ chat, id, replyTo, silent, scheduleDate, clientId })`
 *   — a sticker or GIF sent as it is (messages.sendMedia); Telegram's
 *   answer goes through the live handler, so it shows in the chat.
 *
 * The documents the page may name are only those listed here (by id);
 * an expired file reference asks their list again, then tries once
 * more. Lists are kept ten minutes, a set an hour.
 */

import { promises as fs } from 'node:fs';
import path from 'node:path';
import { pickSize } from './telegram-media.js';
import { withSendAs } from './telegram-send-as-client.js';
import { DICE, randomIdOf, replyHeader, sendError } from './telegram-send.js';
import { createStickerSearch } from './telegram-sticker-search.js';
import { createInlineBots } from './telegram-inline-bots.js';

const LISTS_MS = 10 * 60_000;
const SET_MS = 60 * 60_000;
// Pictures and videos larger than this are not downloaded for the panel.
const MAX_PICTURE = 512 * 1024;
const MAX_VIDEO = 4 * 1024 * 1024;
const ID = /^\d{1,20}$/;
// A set's id and access hash are signed 64-bit numbers; a short name.
const SET_ID = /^-?\d{1,20}$/;
const SHORT_NAME = /^[A-Za-z0-9_]{1,64}$/;
// What the panel is given: a picture, a video or an animated sticker.
const FULL_TYPE = /^(image\/|video\/|application\/x-tgsticker$)/;

const text = (value) =>
  value === null || value === undefined ? '' : String(value.value ?? value);

const bytesOf = (value) => {
  if (value instanceof Uint8Array) {
    return Buffer.from(value);
  }
  return typeof value?.bytes === 'string'
    ? Buffer.from(value.bytes, 'base64')
    : Buffer.alloc(0);
};

const expired = (error) =>
  /FILE_REFERENCE_(EXPIRED|INVALID)/.test(
    String(error?.errorMessage ?? error?.message ?? '')
  );

const attribute = (doc, name) =>
  (doc?.attributes ?? []).find((a) => a?.className === name) ?? null;

/** A sticker's or GIF's format: webp, tgs, webm or mp4 (or the type). */
export const formatOf = (doc) => {
  const mime = String(doc?.mimeType ?? '');
  if (mime === 'application/x-tgsticker') {
    return 'tgs';
  }
  if (mime === 'video/webm') {
    return 'webm';
  }
  if (mime === 'video/mp4') {
    return 'mp4';
  }
  return mime === 'image/webp' ? 'webp' : mime;
};

/** A document as the page's sticker or GIF. */
export const panelItem = (doc, kind = 'sticker') => {
  const size =
    attribute(doc, 'DocumentAttributeImageSize') ??
    attribute(doc, 'DocumentAttributeVideo');
  return {
    id: text(doc.id),
    kind,
    format: formatOf(doc),
    // A custom emoji's alt is the emoji it stands for (R-Y214).
    emoji:
      (
        attribute(doc, 'DocumentAttributeSticker') ??
        attribute(doc, 'DocumentAttributeCustomEmoji')
      )?.alt ?? null,
    w: Number(size?.w ?? 0) || null,
    h: Number(size?.h ?? 0) || null,
  };
};

/** A sticker set as the page lists it. */
export const panelSet = (set) => ({
  id: text(set.id),
  title: String(set.title ?? ''),
  count: Number(set.count ?? 0),
  format: set.videos ? 'webm' : set.animated ? 'tgs' : 'webp',
  emoji: Boolean(set.emojis),
});

// What the panel shows for a document: the still sticker itself, else
// its thumbnail; null when there is none small enough.
const pictureOf = (doc) => {
  if (formatOf(doc) === 'webp' && Number(doc.size ?? 0) <= MAX_PICTURE) {
    return { doc, thumb: '', size: Number(doc.size) };
  }
  const thumb = pickSize(doc.thumbs ?? [], 'm');
  return thumb ? { doc, thumb, size: MAX_PICTURE } : null;
};

/** The picture's type, from its first bytes. */
export const sniff = (buffer) => {
  const head = buffer.subarray(0, 12);
  if (head.subarray(0, 4).toString() === 'RIFF') {
    return 'image/webp';
  }
  if (head[0] === 0xff && head[1] === 0xd8) {
    return 'image/jpeg';
  }
  return head.subarray(1, 4).toString() === 'PNG'
    ? 'image/png'
    : 'application/octet-stream';
};

const readCache = async (file) => {
  try {
    const buffer = await fs.readFile(file);
    return buffer.length > 0 ? buffer : null;
  } catch {
    return null;
  }
};

// Through the account's queue, at the pace of what the user is looking
// at; one request per key (the same key asked again is merged).
export const runIn = (env, key, use) =>
  env.queue ? env.queue.run(key, 'view', use) : use();

export const connect = async (env, userClient) => {
  const client = await userClient();
  if (!client) {
    return null;
  }
  const { Api, helpers } = await env.importer();
  return { client, Api, helpers, zero: helpers.returnBigInt(0) };
};

// Connects, runs `use` with the connection, and turns Telegram's errors
// into the page's codes with `fail`.
export const connected = async (env, userClient, fail, use) => {
  const c = await connect(env, userClient);
  if (!c) {
    return { ok: false, supported: false };
  }
  try {
    return await use(c);
  } catch (error) {
    return fail(error);
  }
};

// Telegram's error names, by `codes`, as the page's codes.
export const failureOf = (codes) => (error) => {
  const name = String(error?.errorMessage ?? error?.message ?? '');
  const key = Object.keys(codes).find((k) => name.includes(k));
  return { ok: false, error: key ?? 'failed', code: codes[key] ?? 'failed' };
};

export const inputSet = (c, set) =>
  new c.Api.InputStickerSetID({
    id: c.helpers.returnBigInt(text(set.id)),
    accessHash: c.helpers.returnBigInt(text(set.accessHash)),
  });

// Telegram's hash of a list of ids (messages.getSavedGifs asks by it, and
// answers savedGifsNotModified when the list is the same).
const hashOf = (helpers, gifs) => {
  let hash = 0n;
  for (const gif of gifs) {
    hash ^= hash >> 21n;
    hash = BigInt.asUintN(64, hash ^ (hash << 35n));
    hash ^= hash >> 4n;
    hash = BigInt.asUintN(64, hash + BigInt(gif.id));
  }
  return helpers.returnBigInt(BigInt.asIntN(64, hash).toString());
};

// The lists: the panel's, a set's, the saved GIFs; every document they
// name kept by id, with the list it came from.
const createLists = (env, userClient, now) => {
  const docs = new Map(); // id -> { doc, from }
  const sets = new Map(); // id -> { set, at, items }
  const refetch = new Map(); // a list's prefix -> ask it again
  const kept = { panel: null, gifs: null, gifList: null }; // { at, answer }
  const run = (key, use) => runIn(env, key, use);
  const fresher = (entry, ms) => entry && now() - entry.at < ms;

  const remember = (documents, from, kind) =>
    (documents ?? [])
      .filter((doc) => doc?.className === 'Document')
      .map((doc) => {
        docs.set(text(doc.id), { doc, from });
        return panelItem(doc, kind);
      });

  const ask = (c, key, Request) =>
    run(`stickers:${key}`, () =>
      c.client.invoke(new Request({ hash: c.zero }))
    );

  const stickerPanel = async ({ fresh = false } = {}) => {
    if (!fresh && fresher(kept.panel, LISTS_MS)) {
      return kept.panel.answer;
    }
    const c = await connect(env, userClient);
    if (!c) {
      return { ok: false, supported: false };
    }
    const all = await ask(c, 'sets', c.Api.messages.GetAllStickers);
    const recent = await ask(c, 'recent', c.Api.messages.GetRecentStickers);
    const faved = await ask(c, 'faved', c.Api.messages.GetFavedStickers);
    for (const set of all?.sets ?? []) {
      sets.set(text(set.id), { ...sets.get(text(set.id)), set });
    }
    const answer = {
      ok: true,
      faved: remember(faved?.stickers, 'faved', 'sticker'),
      recent: remember(recent?.stickers, 'recent', 'sticker'),
      sets: (all?.sets ?? []).filter((s) => !s.emojis).map(panelSet),
    };
    kept.panel = { at: now(), answer };
    return answer;
  };

  const stickerSet = async ({ id, fresh = false } = {}) => {
    const key = String(id ?? '');
    const known = sets.get(key);
    if (!known?.set) {
      return { ok: false, error: 'unknown set', code: 'unknown-set' };
    }
    if (!fresh && known.items && fresher(known, SET_MS)) {
      return { ok: true, id: key, stickers: known.items };
    }
    const c = await connect(env, userClient);
    if (!c) {
      return { ok: false, supported: false };
    }
    const answer = await run(`stickers:set:${key}`, () =>
      c.client.invoke(
        new c.Api.messages.GetStickerSet({
          stickerset: inputSet(c, known.set),
          hash: 0,
        })
      )
    );
    const items = remember(answer?.documents, `set:${key}`, 'sticker');
    sets.set(key, { set: answer?.set ?? known.set, at: now(), items });
    return { ok: true, id: key, stickers: items };
  };

  // `full`: ask for the whole list, not by hash (a file reference expired).
  const savedGifs = async ({ fresh = false, full = false } = {}) => {
    if (!fresh && fresher(kept.gifs, LISTS_MS)) {
      return kept.gifs.answer;
    }
    const c = await connect(env, userClient);
    if (!c) {
      return { ok: false, supported: false };
    }
    const before = kept.gifList;
    const hash = before && !full ? hashOf(c.helpers, before) : c.zero;
    const answer = await run('stickers:gifs', () =>
      c.client.invoke(new c.Api.messages.GetSavedGifs({ hash }))
    );
    const same = answer?.className === 'messages.SavedGifsNotModified';
    const gifs =
      same && before ? before : remember(answer?.gifs, 'gifs', 'gif');
    kept.gifList = gifs;
    kept.gifs = { at: now(), answer: { ok: true, gifs } };
    return kept.gifs.answer;
  };

  // The document's list asked again (its file reference expired).
  const again = async (id) => {
    const from = docs.get(id)?.from ?? '';
    const other = [...refetch].find(([prefix]) => from.startsWith(prefix));
    if (other) {
      await other[1](from.slice(other[0].length));
    } else if (from.startsWith('set:')) {
      await stickerSet({ id: from.slice(4), fresh: true });
    } else if (from === 'gifs') {
      await savedGifs({ fresh: true, full: true });
    } else {
      await stickerPanel({ fresh: true });
    }
    return docs.get(id)?.doc ?? null;
  };

  // Use a document, asking its list again once if its reference expired.
  const withDoc = async (id, use) => {
    const doc = docs.get(id)?.doc;
    if (!doc) {
      return null;
    }
    try {
      return await use(doc);
    } catch (error) {
      if (!expired(error)) {
        throw error;
      }
      const fresh = await again(id);
      return fresh ? use(fresh) : null;
    }
  };

  return {
    stickerPanel,
    stickerSet,
    savedGifs,
    withDoc,
    known: (id) => docs.has(id),
    setOf: (id) => sets.get(id) ?? null,
    remember,
    // A set opened from a chat's sticker: it and its stickers kept.
    keepSet: (set, answer) => {
      const key = text(set.id);
      const items = remember(answer?.documents, `set:${key}`, 'sticker');
      sets.set(key, { set, at: now(), items });
      return items;
    },
    // Sets found by a search, so their stickers can be asked.
    learnSet: (set) => {
      if (set?.id !== undefined && !sets.get(text(set.id))?.set) {
        sets.set(text(set.id), { set });
      }
    },
    installed: (id) =>
      Boolean(kept.panel?.answer?.sets?.some((s) => s.id === id)),
    // `ask(rest)` asks the list from `prefix + rest` again.
    onAgain: (prefix, ask) => refetch.set(prefix, ask),
    // Telegram puts a sent sticker first among the recent ones.
    sent: () => {
      kept.panel = null;
    },
    // A favourite, a recent sticker or a saved GIF changed.
    changed: () => {
      kept.panel = null;
      kept.gifs = null;
    },
  };
};

const docLocation = (c, doc, thumb) =>
  new c.Api.InputDocumentFileLocation({
    id: c.helpers.returnBigInt(text(doc.id)),
    accessHash: c.helpers.returnBigInt(text(doc.accessHash)),
    fileReference: bytesOf(doc.fileReference),
    thumbSize: thumb,
  });

// The panel's pictures and videos, downloaded once into `mediaDir`.
const createPictures = (env, { userClient, mediaDir }, lists) => {
  const download = async (c, name, location, dcId, size) =>
    runIn(env, `file:sticker:${name}`, async () => {
      const buffer = await c.client.downloadFile(location, {
        dcId: Number(dcId),
        fileSize: c.helpers.returnBigInt(String(Math.max(1, size))),
      });
      return buffer?.length ? Buffer.from(buffer) : null;
    });

  // A video sticker's or GIF's video, or an animated sticker's
  // animation (R-Y113), when small enough.
  const video = async (c, id, doc) => {
    const size = Number(doc.size ?? 0);
    if (!['webm', 'mp4', 'tgs'].includes(formatOf(doc)) || size > MAX_VIDEO) {
      return null;
    }
    const buffer = await download(
      c,
      `${id}-full`,
      docLocation(c, doc, ''),
      doc.dcId,
      size
    );
    return { buffer, mimeType: doc.mimeType };
  };

  const fetchDoc = async (c, id, full) =>
    lists.withDoc(id, async (doc) => {
      if (full) {
        return video(c, id, doc);
      }
      const picture = pictureOf(doc);
      if (!picture) {
        return null;
      }
      const buffer = await download(
        c,
        `${id}-${picture.thumb || 'doc'}`,
        docLocation(c, doc, picture.thumb),
        doc.dcId,
        picture.size
      );
      return buffer ? { buffer, mimeType: sniff(buffer) } : null;
    });

  // A set's own picture, when it is a still one (an animated or video
  // set's is Lottie or a video, not for an <img>).
  const setThumb = async (c, id, set) => {
    const has = (set?.thumbs ?? []).some((t) => t?.className === 'PhotoSize');
    if (!has || set.thumbDcId === undefined) {
      return null;
    }
    const location = new c.Api.InputStickerSetThumb({
      stickerset: inputSet(c, set),
      thumbVersion: Number(set.thumbVersion ?? 0),
    });
    const buffer = await download(
      c,
      `set-${id}`,
      location,
      set.thumbDcId,
      MAX_PICTURE
    );
    const mimeType = buffer ? sniff(buffer) : '';
    return mimeType.startsWith('image/') ? { buffer, mimeType } : null;
  };

  // Else its first sticker's picture, the set asked for it if need be.
  const fetchSet = async (c, id) => {
    const thumb = await setThumb(c, id, lists.setOf(id)?.set);
    if (thumb) {
      return thumb;
    }
    if (lists.setOf(id)?.set && !lists.setOf(id).items) {
      await lists.stickerSet({ id });
    }
    const first = lists.setOf(id)?.items?.[0]?.id;
    return first ? fetchDoc(c, first, false) : null;
  };

  const fetchFresh = async ({ key, set, full }) => {
    const c = await connect(env, userClient);
    if (!c) {
      return null;
    }
    return set ? fetchSet(c, key) : fetchDoc(c, key, full);
  };

  const stickerPicture = async ({ id, set, full = false } = {}) => {
    const key = set ? String(set) : String(id ?? '');
    if (!ID.test(key) || !mediaDir) {
      return null;
    }
    const name = set ? `set-${key}` : `${key}${full ? '-full' : ''}`;
    const file = path.join(mediaDir, 'stickers', name);
    const cached = await readCache(file);
    const type = cached ? String(await readCache(`${file}.type`)) : '';
    if (cached && FULL_TYPE.test(type)) {
      return { buffer: cached, mimeType: type };
    }
    const got = await fetchFresh({ key, set, full });
    if (!got?.buffer) {
      return null;
    }
    await fs.mkdir(path.dirname(file), { recursive: true });
    await fs.writeFile(file, got.buffer);
    await fs.writeFile(`${file}.type`, got.mimeType);
    return got;
  };

  return stickerPicture;
};

const inputDocument = (c, doc) =>
  new c.Api.InputDocument({
    id: c.helpers.returnBigInt(text(doc.id)),
    accessHash: c.helpers.returnBigInt(text(doc.accessHash)),
    fileReference: bytesOf(doc.fileReference),
  });

const sendRequest = (c, doc, peer, draft) =>
  new c.Api.messages.SendMedia({
    peer,
    media: new c.Api.InputMediaDocument({ id: inputDocument(c, doc) }),
    message: '',
    randomId: randomIdOf(draft.clientId, 0, c.helpers),
    clearDraft: false,
    ...(draft.silent ? { silent: true } : {}),
    ...(draft.scheduleDate ? { scheduleDate: draft.scheduleDate } : {}),
    ...replyHeader(c.Api, draft.replyTo, null),
  });

// A sticker or GIF sent as it is; Telegram's answer to the live handler.
const createSender = (env, { userClient, apply }, lists) => {
  const sendDocument = async (draft = {}) => {
    const target = String(draft.chat ?? '');
    const key = String(draft.id ?? '');
    if (!lists.known(key) || !target) {
      return { ok: false, error: 'unknown sticker', code: 'unknown-sticker' };
    }
    const c = await connect(env, userClient);
    if (!c) {
      return { ok: false, supported: false };
    }
    try {
      const client = await withSendAs(
        env,
        c.client,
        draft.sendAs,
        draft.allowPaidStars
      );
      const result = await lists.withDoc(key, (doc) =>
        env.connection.withPeer(client, target, (peer) =>
          client.invoke(sendRequest(c, doc, peer, draft))
        )
      );
      if (result && typeof result === 'object') {
        await apply(c.client, result);
      }
    } catch (error) {
      throw sendError(error);
    }
    lists.sent();
    if (draft.scheduleDate) {
      env.actions?.scheduledChanged?.(target);
      return { ok: true, chat: target, scheduled: true };
    }
    return { ok: true, chat: target };
  };
  return sendDocument;
};

// What the panel's menu changes (R-Y115), as Telegram asks it.
const SAVES = {
  fave: (c, id) => new c.Api.messages.FaveSticker({ id, unfave: false }),
  unfave: (c, id) => new c.Api.messages.FaveSticker({ id, unfave: true }),
  unrecent: (c, id) =>
    new c.Api.messages.SaveRecentSticker({ id, attached: false, unsave: true }),
  saveGif: (c, id) => new c.Api.messages.SaveGif({ id, unsave: false }),
  unsaveGif: (c, id) => new c.Api.messages.SaveGif({ id, unsave: true }),
};
export const STICKER_SAVES = Object.freeze(Object.keys(SAVES));

// A sticker made a favourite or not, taken from the recent ones, a GIF
// saved or not; the lists asked again after.
const createSaver =
  (env, { userClient }, lists) =>
  async ({ id, action } = {}) => {
    const key = String(id ?? '');
    if (!lists.known(key) || !Object.hasOwn(SAVES, String(action))) {
      return { ok: false, error: 'unknown sticker', code: 'unknown-sticker' };
    }
    const c = await connect(env, userClient);
    if (!c) {
      return { ok: false, supported: false };
    }
    await lists.withDoc(key, (doc) =>
      runIn(env, `stickers:save:${action}:${key}`, () =>
        c.client.invoke(SAVES[action](c, inputDocument(c, doc)))
      )
    );
    lists.changed();
    return { ok: true };
  };

// A set the panel showed added to the user's sets, or removed; the
// panel's lists asked again after.
const createInstaller =
  (env, { userClient }, lists) =>
  async ({ id, install = true } = {}) => {
    const key = String(id ?? '');
    const set = lists.setOf(key)?.set;
    if (!set) {
      return { ok: false, error: 'unknown set', code: 'unknown-set' };
    }
    const c = await connect(env, userClient);
    if (!c) {
      return { ok: false, supported: false };
    }
    const stickerset = inputSet(c, set);
    await runIn(env, `stickers:install:${key}`, () =>
      c.client.invoke(
        install
          ? new c.Api.messages.InstallStickerSet({
              stickerset,
              archived: false,
            })
          : new c.Api.messages.UninstallStickerSet({ stickerset })
      )
    );
    lists.changed();
    return { ok: true, id: key, installed: Boolean(install) };
  };

// The set a chat's sticker belongs to, by id and access hash or by
// short name; Telegram's answer kept in the lists (R-Y124). The box
// says "Remove" for a set the user has (`installedDate`).
// What Telegram is asked for: the id and access hash, else the name.
const boxRequest = (c, { id, accessHash, shortName }) => {
  if (SET_ID.test(String(id ?? '')) && SET_ID.test(String(accessHash ?? ''))) {
    return inputSet(c, { id, accessHash });
  }
  return SHORT_NAME.test(String(shortName ?? ''))
    ? new c.Api.InputStickerSetShortName({ shortName: String(shortName) })
    : null;
};

const createBox =
  (env, { userClient }, lists) =>
  async (named = {}) => {
    const c = await connect(env, userClient);
    if (!c) {
      return { ok: false, supported: false };
    }
    const stickerset = boxRequest(c, named);
    const answer = stickerset
      ? await runIn(env, `stickers:box:${named.id ?? named.shortName}`, () =>
          c.client.invoke(
            new c.Api.messages.GetStickerSet({ stickerset, hash: 0 })
          )
        )
      : null;
    const set = answer?.set;
    if (!set || set.id === undefined) {
      return { ok: false, error: 'unknown set', code: 'unknown-set' };
    }
    const items = lists.keepSet(set, answer);
    return {
      ok: true,
      set: {
        ...panelSet(set),
        shortName: String(set.shortName ?? ''),
        count: items.length || Number(set.count ?? 0),
        installed: Boolean(set.installedDate),
      },
      items,
    };
  };

// A die's animations (R-Y130): Telegram's set for its emoji
// (inputStickerSetDice), the n-th sticker rolling to the value n, the
// first one the die at rest; kept an hour.
const createDice = (env, { userClient }, lists, now) => {
  const kept = new Map(); // emoticon -> { at, answer }
  return async ({ emoticon } = {}) => {
    const key = String(emoticon ?? '');
    if (!DICE.includes(key)) {
      return { ok: false, error: 'unknown die', code: 'bad-request' };
    }
    const entry = kept.get(key);
    if (entry && now() - entry.at < SET_MS) {
      return entry.answer;
    }
    const c = await connect(env, userClient);
    if (!c) {
      return { ok: false, supported: false };
    }
    const answer = await runIn(env, `stickers:dice:${key}`, () =>
      c.client.invoke(
        new c.Api.messages.GetStickerSet({
          stickerset: new c.Api.InputStickerSetDice({ emoticon: key }),
          hash: 0,
        })
      )
    );
    if (!answer?.set || answer.set.id === undefined) {
      return { ok: false, error: 'unknown set', code: 'unknown-set' };
    }
    const result = {
      ok: true,
      emoticon: key,
      items: lists.keepSet(answer.set, answer),
    };
    kept.set(key, { at: now(), answer: result });
    return result;
  };
};

/** `env`: the account's; `apply(client, result)` the live handler. */
export const createStickers = (
  env,
  { userClient, apply, mediaDir },
  { now = () => Date.now() } = {}
) => {
  const lists = createLists(env, userClient, now);
  return {
    stickerPanel: lists.stickerPanel,
    stickerSet: lists.stickerSet,
    savedGifs: lists.savedGifs,
    ...createStickerSearch(env, { userClient, lists, now }),
    ...createInlineBots(env, { userClient, apply, lists, now }),
    stickerPicture: createPictures(env, { userClient, mediaDir }, lists),
    sendDocument: createSender(env, { userClient, apply }, lists),
    stickerSave: createSaver(env, { userClient }, lists),
    stickerSetInstall: createInstaller(env, { userClient }, lists),
    stickerSetBox: createBox(env, { userClient }, lists),
    stickerDice: createDice(env, { userClient }, lists, now),
    // What the settings' sets list (R-Y169) shares with the panel.
    stickerLists: {
      learn: lists.learnSet,
      known: (id) => lists.setOf(id)?.set ?? null,
      changed: lists.changed,
      // Documents of other lists (a gift's sticker, R-Y176).
      remember: lists.remember,
      onAgain: lists.onAgain,
    },
  };
};

/**
 * Local storage management, as Telegram Desktop's Settings → Advanced →
 * Manage local storage has it (R-Y215; learned, never copied): the media
 * the server cached under `<store>/media/telegram`, counted by kind, and
 * cleared by kind or all at once; an optional size limit and an age limit
 * applied on a timer and at start, the least recently used files first.
 *
 * - `storageUsage()` → `{ ok, total: { bytes, files }, kinds: { photos |
 *   videos | voice | files | stickers | other: { bytes, files } }, chats:
 *   [{ chat, bytes, files }] (largest first, at most 100), limits: {
 *   maxGb, olderDays } }`;
 * - `storageClear({ kind } | { all: true })` → `{ ok, removed: { bytes,
 *   files } }`;
 * - `storageLimits()` / `storageLimitsSet({ maxGb, olderDays })` — the
 *   limits (maxGb 0, 1, 5 or 20; olderDays 0, 7, 30 or 365; 0 is none),
 *   kept in `<media>/.cache-limits.json`; setting them applies them;
 * - `storageEnforce()` applies the limits now → `{ ok, removed }`.
 *
 * Only metadata is read (name, size, times), plus the small `.type` file
 * the cache keeps beside a download — its mime type — to tell videos and
 * voice notes from other files. Only regular files inside the media
 * folder are counted or removed: a symbolic link is skipped and never
 * followed, every path is resolved and checked to lie inside the folder
 * before it is removed, and nothing outside it (the store's database, the
 * sessions, the exports) is touched. The kind comes from the folder the
 * file is in (`stickers`, `custom-emoji`, `avatars`, `wallpapers`, …) or,
 * in a chat's folder, from the file's name and mime type. The least
 * recently used is judged by the later of a file's access and change time.
 */

import fs from 'node:fs/promises';
import path from 'node:path';
import { setInterval } from 'node:timers';

export const KINDS = Object.freeze([
  'photos',
  'videos',
  'voice',
  'files',
  'stickers',
  'other',
]);
export const MAX_GB = Object.freeze([0, 1, 5, 20]);
export const OLDER_DAYS = Object.freeze([0, 7, 30, 365]);

const LIMITS_FILE = '.cache-limits.json';
const GB = 1024 ** 3;
const DAY_MS = 24 * 3600 * 1000;
const HOUR_MS = 3600 * 1000;
const TYPE_BYTES = 128;
const CHATS_SHOWN = 100;
const CHAT = /^-?\d{1,20}$/;
const FOLDER_KIND = {
  stickers: 'stickers',
  'custom-emoji': 'stickers',
  music: 'files',
  ringtones: 'voice',
  avatars: 'other',
  wallpapers: 'other',
};

const empty = () => ({ bytes: 0, files: 0 });

/** The kind of a mime type the cache recorded. */
export const kindOfMime = (mime = '') => {
  const type = String(mime).split(';')[0].trim().toLowerCase();
  if (type === 'image/gif') {
    return 'stickers';
  }
  if (type.startsWith('image/')) {
    return 'photos';
  }
  if (type.startsWith('video/')) {
    return 'videos';
  }
  return type.startsWith('audio/') ? 'voice' : 'files';
};

/**
 * The kind of a cached file from its path inside the media folder
 * (`parts` of the relative path) and, when the cache recorded one, its
 * mime type. A chat's `<msg>-<size>` picture is a photo, a `<msg>-file`
 * is by its mime type.
 */
export const kindOfFile = (parts, mime = '') => {
  const [top, ...rest] = parts;
  if (Object.hasOwn(FOLDER_KIND, top)) {
    return FOLDER_KIND[top];
  }
  const name = parts.at(-1) ?? '';
  if (top === 'stories' || name.endsWith('-file')) {
    return mime ? kindOfMime(mime) : 'files';
  }
  return CHAT.test(top ?? '') && rest.length > 0 ? 'photos' : 'other';
};

/** The chat a file belongs to (its folder), or null. */
export const chatOfFile = (parts) =>
  CHAT.test(parts[0] ?? '') && parts.length > 1 ? parts[0] : null;

/** Limits from whatever was kept or sent: only the offered values. */
export const limitsFrom = (raw) => {
  const kept = raw && typeof raw === 'object' ? raw : {};
  return {
    maxGb: MAX_GB.includes(kept.maxGb) ? kept.maxGb : 0,
    olderDays: OLDER_DAYS.includes(kept.olderDays) ? kept.olderDays : 0,
  };
};

export const validLimits = (b = {}) =>
  MAX_GB.includes(b.maxGb) && OLDER_DAYS.includes(b.olderDays);

export const validClear = (b = {}) =>
  (b.all === true && b.kind === undefined) ||
  (b.all === undefined && KINDS.includes(b.kind));

/**
 * The indexes of the `files` ([{ bytes, used }]) to remove for the
 * limits: those not used since `olderDays`, then the least recently used
 * until the rest fit in `maxGb`. Pure.
 */
export const expired = (files, limits, nowMs) => {
  const { maxGb, olderDays } = limitsFrom(limits);
  const gone = new Set();
  if (olderDays > 0) {
    files.forEach((f, i) => f.used < nowMs - olderDays * DAY_MS && gone.add(i));
  }
  if (maxGb > 0) {
    let total = files.reduce(
      (sum, f, i) => (gone.has(i) ? sum : sum + f.bytes),
      0
    );
    const order = files
      .map((_, i) => i)
      .filter((i) => !gone.has(i))
      .sort((a, b) => files[a].used - files[b].used);
    for (const i of order) {
      if (total <= maxGb * GB) {
        break;
      }
      gone.add(i);
      total -= files[i].bytes;
    }
  }
  return [...gone];
};

const readType = async (file) => {
  let handle;
  try {
    handle = await fs.open(file, 'r');
    const buffer = Buffer.alloc(TYPE_BYTES);
    const { bytesRead } = await handle.read(buffer, 0, TYPE_BYTES, 0);
    return buffer.subarray(0, bytesRead).toString();
  } catch {
    return '';
  } finally {
    await handle?.close();
  }
};

// Every regular file of the folder, no link followed and no dot file at
// its top: Map of path → { parts, stat }.
const walkFiles = async (root) => {
  const found = new Map();
  const walk = async (dir, parts) => {
    const entries = await fs
      .readdir(dir, { withFileTypes: true })
      .catch(() => []);
    for (const entry of entries) {
      const file = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        await walk(file, [...parts, entry.name]);
      } else if (
        entry.isFile() &&
        !(parts.length === 0 && entry.name.startsWith('.'))
      ) {
        const stat = await fs.lstat(file).catch(() => null);
        if (stat?.isFile()) {
          found.set(file, { parts: [...parts, entry.name], stat });
        }
      }
    }
  };
  await walk(root, []);
  return found;
};

// The cached files, each with its `.type` file's size and name added:
// `{ file, side, bytes, used, kind, chat }`.
const scan = async (root) => {
  const found = await walkFiles(root);
  const files = [];
  for (const [file, { parts, stat }] of found) {
    const base = file.endsWith('.type') ? file.slice(0, -5) : null;
    if (base && found.has(base)) {
      continue;
    }
    const sideFile = `${file}.type`;
    const side = found.get(sideFile);
    files.push({
      file,
      side: side ? sideFile : null,
      bytes: stat.size + (side?.stat.size ?? 0),
      used: Math.max(stat.atimeMs, stat.mtimeMs),
      kind: kindOfFile(parts, side ? await readType(sideFile) : ''),
      chat: chatOfFile(parts),
    });
  }
  return files;
};

// Removes a file only when its real path is inside the real root and it is
// still a regular file, not a link. → bytes freed, or 0.
const removeInside = async (root, file) => {
  try {
    const stat = await fs.lstat(file);
    const real = await fs.realpath(path.dirname(file));
    const relative = path.relative(root, path.join(real, path.basename(file)));
    if (
      !stat.isFile() ||
      relative === '' ||
      relative.startsWith('..') ||
      path.isAbsolute(relative)
    ) {
      return 0;
    }
    await fs.unlink(file);
    return stat.size;
  } catch {
    return 0;
  }
};

const removeAll = async (root, items) => {
  const removed = empty();
  for (const item of items) {
    const bytes = await removeInside(root, item.file);
    if (bytes > 0 || item.bytes === 0) {
      removed.files += 1;
    }
    removed.bytes += bytes;
    if (item.side) {
      removed.bytes += await removeInside(root, item.side);
    }
  }
  return removed;
};

const countBy = (files, keyOf) => {
  const rows = new Map();
  for (const f of files) {
    const key = keyOf(f);
    if (key !== null) {
      const row = rows.get(key) ?? empty();
      row.bytes += f.bytes;
      row.files += 1;
      rows.set(key, row);
    }
  }
  return rows;
};

const readLimits = async (dir) => {
  try {
    return limitsFrom(
      JSON.parse(await fs.readFile(path.join(dir, LIMITS_FILE)))
    );
  } catch {
    return limitsFrom(null);
  }
};

/**
 * The storage actions of the media folder `mediaDir` (none without one).
 * `timer: false` leaves the periodic enforcement off (tests).
 */
export const createStorage = (env, { mediaDir = null, timer = true } = {}) => {
  const now = env?.now ?? (() => Date.now());
  const none = { ok: false, error: 'no media folder', code: 'unavailable' };
  // The real path of the folder, made when first needed.
  const rootOf = async () => {
    if (!mediaDir) {
      return null;
    }
    await fs.mkdir(mediaDir, { recursive: true });
    return fs.realpath(mediaDir);
  };

  const storageLimits = async () =>
    mediaDir ? { ok: true, ...(await readLimits(mediaDir)) } : none;

  const storageEnforce = async () => {
    if (!mediaDir) {
      return none;
    }
    const limits = await readLimits(mediaDir);
    if (limits.maxGb === 0 && limits.olderDays === 0) {
      return { ok: true, removed: empty() };
    }
    const root = await rootOf();
    const files = await scan(root);
    const doomed = expired(files, limits, now());
    const removed = await removeAll(
      root,
      doomed.map((i) => files[i])
    );
    return { ok: true, removed };
  };

  const storageUsage = async () => {
    const root = await rootOf();
    if (!root) {
      return none;
    }
    const files = await scan(root);
    const kinds = Object.fromEntries(KINDS.map((k) => [k, empty()]));
    for (const [kind, row] of countBy(files, (f) => f.kind)) {
      kinds[kind] = row;
    }
    const chats = [...countBy(files, (f) => f.chat)]
      .map(([chat, row]) => ({ chat, ...row }))
      .sort((a, b) => b.bytes - a.bytes)
      .slice(0, CHATS_SHOWN);
    const total = files.reduce(
      (sum, f) => ({ bytes: sum.bytes + f.bytes, files: sum.files + 1 }),
      empty()
    );
    return {
      ok: true,
      total,
      kinds,
      chats,
      limits: await readLimits(root),
    };
  };

  const storageClear = async (body = {}) => {
    if (!validClear(body)) {
      return { ok: false, error: 'bad request', code: 'bad-request' };
    }
    const root = await rootOf();
    if (!root) {
      return none;
    }
    const files = await scan(root);
    const picked = body.all ? files : files.filter((f) => f.kind === body.kind);
    return { ok: true, removed: await removeAll(root, picked) };
  };

  const storageLimitsSet = async (body = {}) => {
    if (!validLimits(body)) {
      return { ok: false, error: 'bad request', code: 'bad-request' };
    }
    const root = await rootOf();
    if (!root) {
      return none;
    }
    const limits = limitsFrom(body);
    await fs.writeFile(path.join(root, LIMITS_FILE), JSON.stringify(limits), {
      mode: 0o600,
    });
    const { removed } = await storageEnforce();
    return { ok: true, ...limits, removed };
  };

  if (mediaDir && timer) {
    // At start and every hour; a failure is only a missed round.
    storageEnforce().catch(() => {});
    setInterval(() => storageEnforce().catch(() => {}), HOUR_MS).unref();
  }

  return {
    storageUsage,
    storageClear,
    storageLimits,
    storageLimitsSet,
    storageEnforce,
  };
};

/**
 * Viewing Telegram stories, as Telegram Desktop does (R-Y140; learned,
 * never copied). Read only — posting a story is not here:
 * - `stories({ state })` — the strip above the chat list
 *   (stories.getAllStories, not hidden; `hidden: true` the hidden ones,
 *   R-Y148): the first call has no `state`;
 *   a call with the `state` an answer gave asks for the next page
 *   (`next`). → `{ ok, peers: [{ peer, name, self, count, lastId,
 *   maxReadId, unread }], state, more }` (`notModified` when Telegram
 *   says nothing changed); each answer also has `stealth: { activeUntil,
 *   cooldownUntil }` (stories stealth mode, R-Y199);
 * - `storiesPeer({ chat })` — one peer's stories to show
 *   (stories.getPeerStories; the skipped and `min` ones read again with
 *   stories.getStoriesByID) → `{ ok, peer, stories: [{ id, date, expire,
 *   caption, entities, media: { kind, duration, w, h }, mine, views,
 *   reactions, reaction }] }`;
 * - `storiesRead({ chat, maxId })` — they were seen up to `maxId`
 *   (stories.readStories);
 * - `storyMedia({ chat, id })` — a story's picture (the largest size) or
 *   video, for GET /api/telegram/story: found by stories.getStoriesByID,
 *   downloaded once into `<media>/stories/<chat>/<id>` and served from
 *   there afterwards. Media areas, reactions and replies are not here.
 * Telegram's errors become codes the page shows as text.
 */

import { promises as fs } from 'node:fs';
import path from 'node:path';
import { bigSize, locationOf, pickSize, readCache } from './telegram-media.js';
import { connected, failureOf, runIn } from './telegram-stickers.js';

const CODES = {
  PEER_ID_INVALID: 'no-access',
  CHANNEL_PRIVATE: 'no-access',
  USER_ID_INVALID: 'no-access',
  STORY_ID_INVALID: 'gone',
  STORIES_NEVER_CREATED: 'gone',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);

const CHAT = /^-?\d{1,20}$/;
const STATE = /^[A-Za-z0-9+/=_-]{1,256}$/;
// A story video larger than this is not downloaded.
const MAX_VIDEO = 64 * 1024 * 1024;

const textOf = (value) => String(value?.value ?? value);

export const peerId = (peer) => {
  if (peer?.userId !== undefined) {
    return textOf(peer.userId);
  }
  if (peer?.channelId !== undefined) {
    return `-100${textOf(peer.channelId)}`;
  }
  return peer?.chatId === undefined ? '' : `-${textOf(peer.chatId)}`;
};

export const nameOf = (entity) =>
  entity?.title ||
  [entity?.firstName, entity?.lastName].filter(Boolean).join(' ') ||
  entity?.username ||
  '';

// The user or chat a peer is, among an answer's `users` and `chats`.
export const entityOf = (answer, peer) => {
  const list = peer?.userId === undefined ? answer.chats : answer.users;
  const want =
    peer?.userId === undefined
      ? textOf(peer?.channelId ?? peer?.chatId)
      : textOf(peer.userId);
  return (list ?? []).find((e) => textOf(e.id) === want);
};

const attributeOf = (doc, name) =>
  (doc?.attributes ?? []).find((a) => a?.className === name) ?? null;

const numberOr = (value) => Number(value ?? 0) || null;

// A document story: a video with its length and size, a picture, or none.
const documentMedia = (doc) => {
  const video = attributeOf(doc, 'DocumentAttributeVideo');
  if (video || /^video\//.test(doc.mimeType ?? '')) {
    return {
      kind: 'video',
      duration: numberOr(video?.duration),
      w: numberOr(video?.w),
      h: numberOr(video?.h),
    };
  }
  return { kind: /^image\//.test(doc.mimeType ?? '') ? 'photo' : 'none' };
};

/** What a story shows: `{ kind: 'photo' | 'video' | 'none', … }`. */
export const mediaOf = (media) => {
  if (media?.className === 'MessageMediaPhoto' && media.photo?.sizes) {
    return { kind: 'photo' };
  }
  const doc =
    media?.className === 'MessageMediaDocument' ? media.document : null;
  return doc?.id ? documentMedia(doc) : { kind: 'none' };
};

const shapeEntity = (e) => ({
  className: String(e?.className ?? ''),
  offset: Number(e?.offset ?? 0),
  length: Number(e?.length ?? 0),
  ...(e?.url ? { url: String(e.url) } : {}),
  ...(e?.language ? { language: String(e.language) } : {}),
  ...(e?.documentId === undefined ? {} : { documentId: textOf(e.documentId) }),
});

// Whom a story is for, as the posting dialog names it (R-Y210).
const privacyOf = (item) => {
  if (item.selectedContacts) {
    return 'selected';
  }
  if (item.closeFriends) {
    return 'close-friends';
  }
  return item.contacts ? 'contacts' : 'everyone';
};

/**
 * A story the page can show, null when it is deleted, `{ id, partial }`
 * when Telegram skipped it or sent only part (read again by its id).
 */
export const shapeStory = (item) => {
  if (!item || item.className === 'StoryItemDeleted') {
    return null;
  }
  if (item.className === 'StoryItemSkipped' || item.min) {
    return { id: Number(item.id), partial: true };
  }
  return {
    id: Number(item.id),
    date: Number(item.date ?? 0),
    expire: Number(item.expireDate ?? 0),
    caption: String(item.caption ?? ''),
    entities: (item.entities ?? []).map(shapeEntity),
    media: mediaOf(item.media),
    mine: Boolean(item.out),
    pinned: Boolean(item.pinned),
    public: Boolean(item.public),
    privacy: privacyOf(item),
    views: Number(item.views?.viewsCount ?? 0),
    reactions: Number(item.views?.reactionsCount ?? 0),
    reaction:
      item.sentReaction?.className === 'ReactionEmoji'
        ? String(item.sentReaction.emoticon)
        : '',
  };
};

// A peer's row in the strip.
const peerHead = (answer, stories) => {
  const entity = entityOf(answer, stories.peer);
  const ids = (stories.stories ?? [])
    .filter((s) => s?.className !== 'StoryItemDeleted')
    .map((s) => Number(s.id));
  const lastId = ids.length > 0 ? Math.max(...ids) : 0;
  const maxReadId = Number(stories.maxReadId ?? 0);
  return {
    peer: peerId(stories.peer),
    name: nameOf(entity),
    self: Boolean(entity?.self),
    count: ids.length,
    lastId,
    maxReadId,
    unread: !entity?.self && maxReadId < lastId,
  };
};

const badRequest = { ok: false, error: 'bad request', code: 'failed' };

/**
 * Stealth mode as the page keeps it (R-Y199): `{ activeUntil, cooldownUntil }`
 * in unix seconds, 0 when not set (StoriesStealthMode).
 */
export const shapeStealth = (mode) => ({
  activeUntil: Number(mode?.activeUntilDate ?? 0),
  cooldownUntil: Number(mode?.cooldownUntilDate ?? 0),
});

const allStories = (env, userClient) => async (request) => {
  const state = request?.state;
  if (
    state !== undefined &&
    !(typeof state === 'string' && STATE.test(state))
  ) {
    return badRequest;
  }
  const hidden = request?.hidden === true;
  return connected(env, userClient, failure, async (c) => {
    const answer = await runIn(env, 'stories', () =>
      c.client.invoke(
        new c.Api.stories.GetAllStories({
          hidden,
          ...(state ? { next: true, state } : {}),
        })
      )
    );
    if (answer?.className === 'stories.AllStoriesNotModified') {
      return {
        ok: true,
        notModified: true,
        peers: [],
        state: answer.state,
        stealth: shapeStealth(answer.stealthMode),
      };
    }
    return {
      ok: true,
      peers: (answer?.peerStories ?? [])
        .map((p) => peerHead(answer, p))
        .filter((p) => p.peer && p.count > 0),
      state: String(answer?.state ?? ''),
      more: Boolean(answer?.hasMore),
      stealth: shapeStealth(answer?.stealthMode),
    };
  });
};

// The stories the first answer left partial, read again by id.
const completed = async (c, peer, items) => {
  const wanted = items.filter((s) => s?.partial).map((s) => s.id);
  if (wanted.length === 0) {
    return items;
  }
  const again = await c.client
    .invoke(new c.Api.stories.GetStoriesByID({ peer, id: wanted }))
    .then((answer) => (answer?.stories ?? []).map(shapeStory))
    .catch(() => []);
  const whole = again.filter((s) => s && !s.partial);
  const byId = new Map(whole.map((s) => [s.id, s]));
  return items.map((s) => (s?.partial ? (byId.get(s.id) ?? null) : s));
};

const peerStories = (env, userClient) => async (request) => {
  const chat = String(request?.chat ?? '');
  if (!CHAT.test(chat)) {
    return badRequest;
  }
  return connected(env, userClient, failure, async (c) =>
    runIn(env, `stories-peer:${chat}`, () =>
      env.connection.withPeer(c.client, chat, async (peer) => {
        const answer = await c.client.invoke(
          new c.Api.stories.GetPeerStories({ peer })
        );
        const shaped = (answer.stories.stories ?? []).map(shapeStory);
        const stories = (await completed(c, peer, shaped))
          .filter(Boolean)
          .sort((a, b) => a.id - b.id);
        return {
          ok: true,
          peer: peerHead(answer, answer.stories),
          stories,
        };
      })
    )
  );
};

const readStories = (env, userClient) => async (request) => {
  const chat = String(request?.chat ?? '');
  const maxId = request?.maxId;
  if (!CHAT.test(chat) || !Number.isInteger(maxId) || maxId <= 0) {
    return badRequest;
  }
  return connected(env, userClient, failure, async (c) =>
    runIn(env, `stories-read:${chat}`, () =>
      env.connection.withPeer(c.client, chat, async (peer) => {
        await c.client.invoke(new c.Api.stories.ReadStories({ peer, maxId }));
        return { ok: true };
      })
    )
  );
};

/**
 * What to download for a story item: `{ kind, file, thumb, mimeType }`
 * as locationOf reads it (a photo's largest size, or the video), or null.
 */
export const storyFile = (item) => {
  const media = item?.media;
  if (media?.className === 'MessageMediaPhoto' && media.photo?.sizes) {
    const thumb = pickSize(media.photo.sizes, 'w');
    return thumb
      ? { kind: 'photo', file: media.photo, thumb, mimeType: 'image/jpeg' }
      : null;
  }
  const doc =
    media?.className === 'MessageMediaDocument' ? media.document : null;
  if (!doc?.id || Number(doc.size ?? 0) > MAX_VIDEO) {
    return null;
  }
  return { kind: 'document', file: doc, thumb: '', mimeType: doc.mimeType };
};

const SERVED = /^(image|video)\//;

const createStoryMedia = (env, userClient, dir) => {
  const flights = new Map();

  const fetchStory = async (c, chat, id) => {
    const answer = await env.connection.withPeer(c.client, chat, (peer) =>
      c.client.invoke(new c.Api.stories.GetStoriesByID({ peer, id: [id] }))
    );
    return (answer?.stories ?? []).find(
      (s) => s?.className === 'StoryItem' && Number(s.id) === id
    );
  };

  const download = async (c, chat, id) => {
    const picture = storyFile(await fetchStory(c, chat, id));
    if (!picture) {
      return null;
    }
    const size = Number(picture.file.size ?? 0);
    const buffer = await c.client.downloadFile(
      locationOf(c.Api, c.helpers, picture),
      {
        dcId: Number(picture.file.dcId),
        fileSize: bigSize(c.helpers, size || MAX_VIDEO),
      }
    );
    return buffer?.length
      ? { buffer: Buffer.from(buffer), mimeType: picture.mimeType }
      : null;
  };

  const load = async (chat, id, file) => {
    const got = await connected(
      env,
      userClient,
      () => null,
      (c) => runIn(env, `story:${chat}:${id}`, () => download(c, chat, id))
    );
    if (!got?.buffer || !SERVED.test(got.mimeType ?? '')) {
      return null;
    }
    await fs.mkdir(path.dirname(file), { recursive: true });
    await fs.writeFile(file, got.buffer);
    await fs.writeFile(`${file}.type`, got.mimeType);
    return got;
  };

  return async (request) => {
    const chat = String(request?.chat ?? '');
    const id = Number(request?.id);
    if (!dir || !CHAT.test(chat) || !Number.isInteger(id) || id <= 0) {
      return null;
    }
    const file = path.join(dir, 'stories', chat, String(id));
    const cached = await readCache(file);
    if (cached) {
      const type = await readCache(`${file}.type`);
      return { buffer: cached, mimeType: type?.toString() || 'image/jpeg' };
    }
    // A player asks for a video in ranges: one download serves them all.
    const key = `${chat}:${id}`;
    if (!flights.has(key)) {
      flights.set(
        key,
        load(chat, id, file)
          .catch(() => null)
          .finally(() => flights.delete(key))
      );
    }
    return flights.get(key);
  };
};

export const createStories = (env, { userClient, mediaDir }) => ({
  stories: allStories(env, userClient),
  storiesPeer: peerStories(env, userClient),
  storiesRead: readStories(env, userClient),
  storyMedia: createStoryMedia(env, userClient, mediaDir),
});

/**
 * What Telegram Desktop lets one do with a story besides watching it
 * (R-Y148; learned, never copied):
 * - `storyReply({ chat, id, text })` — "Reply privately…": a message to
 *   the story's owner that answers the story (messages.sendMessage with
 *   InputReplyToStory); it shows in the chat through the live handler;
 * - `storyReact({ chat, id, reaction })` — a reaction to the story
 *   (stories.sendReaction): an emoji, or `''` to take the reaction back
 *   (ReactionEmpty);
 * - `storyViews({ chat, id, offset })` — the viewers of one's own story,
 *   50 at a time (stories.getStoryViewsList) → `{ ok, count, viewsCount,
 *   reactionsCount, views: [{ kind, user, name, date, reaction }], next }`;
 *   `next` is the offset of the following page, '' at the end; `q`,
 *   `justContacts`, `reactionsFirst`, `forwardsFirst` filter and order the
 *   list, and a forward or repost of the story is an entry of its own
 *   (`kind` 'forward' | 'repost', R-Y199);
 * - `storyDelete({ chat, id })` — one's own story deleted
 *   (stories.deleteStories);
 * - `storiesHide({ chat, hidden })` — a peer's stories moved to or from
 *   the hidden list (stories.togglePeerStoriesHidden).
 * Telegram's errors become codes the page shows as text.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';
import { randomIdOf } from './telegram-send.js';
import { entityOf, nameOf as entityName, peerId } from './telegram-stories.js';

const CODES = {
  PEER_ID_INVALID: 'no-access',
  CHANNEL_PRIVATE: 'no-access',
  USER_ID_INVALID: 'no-access',
  USER_IS_BLOCKED: 'no-access',
  PRIVACY_PREMIUM_REQUIRED: 'no-access',
  STORY_ID_INVALID: 'gone',
  STORIES_NEVER_CREATED: 'gone',
  REACTION_INVALID: 'bad-reaction',
  MESSAGE_TOO_LONG: 'too-long',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);

const CHAT = /^-?\d{1,20}$/;
const OFFSET = /^[A-Za-z0-9+/=_.-]{0,256}$/;
const REACTION = /^\S{1,24}$/u;
/** Telegram's page of a story's viewers. */
export const VIEWS_LIMIT = 50;
const MAX_TEXT = 4096;

export const badRequest = { ok: false, error: 'bad request', code: 'failed' };

const textOf = (value) => String(value?.value ?? value);

export const storyOk = (request) =>
  CHAT.test(String(request?.chat ?? '')) &&
  Number.isInteger(request?.id) &&
  request.id > 0;

// A reaction as the page keeps it: an emoji, or '' for none.
export const reactionOf = (reaction) =>
  reaction?.className === 'ReactionEmoji' ? String(reaction.emoticon) : '';

const nameOf = (user) =>
  [user?.firstName, user?.lastName].filter(Boolean).join(' ') ||
  user?.username ||
  '';

// The viewer's peer and date: a person, or — for a public forward or
// repost of the story (R-Y199) — the chat that shared it.
const sharedBy = (view) =>
  view.className === 'StoryViewPublicForward'
    ? { peer: view.message?.peerId, date: view.message?.date, kind: 'forward' }
    : {
        peer: view.peerId,
        date: view.story?.date,
        kind: 'repost',
      };

/** One viewer of a story, as the page shows it. */
export const shapeView = (view, users, chats = []) => {
  if (view.userId === undefined) {
    const { peer, date, kind } = sharedBy(view);
    return {
      kind,
      user: peerId(peer),
      name: entityName(entityOf({ users, chats }, peer)),
      date: Number(date ?? 0),
      reaction: '',
    };
  }
  const id = textOf(view.userId);
  const user = (users ?? []).find((u) => textOf(u.id) === id);
  return {
    kind: 'view',
    user: id,
    name: nameOf(user),
    date: Number(view.date ?? 0),
    reaction: reactionOf(view.reaction),
  };
};

const withStory = (env, userClient, request, key, use) =>
  connected(env, userClient, failure, (c) =>
    runIn(env, `${key}:${request.chat}`, () =>
      env.connection.withPeer(c.client, String(request.chat), (peer) =>
        use(c, peer)
      )
    )
  );

const reply = (env, userClient) => async (request) => {
  const text = String(request?.text ?? '').trim();
  if (!storyOk(request) || !text || text.length > MAX_TEXT) {
    return badRequest;
  }
  return withStory(env, userClient, request, 'story-reply', async (c, peer) => {
    await c.client.invoke(
      new c.Api.messages.SendMessage({
        peer,
        message: text,
        randomId: randomIdOf(null, 0, c.helpers),
        replyTo: new c.Api.InputReplyToStory({ peer, storyId: request.id }),
      })
    );
    return { ok: true };
  });
};

const react = (env, userClient) => async (request) => {
  const reaction = request?.reaction;
  if (
    !storyOk(request) ||
    typeof reaction !== 'string' ||
    (reaction !== '' && !REACTION.test(reaction))
  ) {
    return badRequest;
  }
  return withStory(env, userClient, request, 'story-react', async (c, peer) => {
    await c.client.invoke(
      new c.Api.stories.SendReaction({
        peer,
        storyId: request.id,
        reaction: reaction
          ? new c.Api.ReactionEmoji({ emoticon: reaction })
          : new c.Api.ReactionEmpty(),
        ...(reaction ? { addToRecent: true } : {}),
      })
    );
    return { ok: true, reaction };
  });
};

const FLAGS = ['justContacts', 'reactionsFirst', 'forwardsFirst'];

// The optional filters of the viewers list (R-Y199), or null when wrong.
const filtersOf = (request) => {
  const q = request?.q;
  const flags = FLAGS.filter((f) => request?.[f] !== undefined);
  if (
    (q !== undefined && !(typeof q === 'string' && q.length <= 128)) ||
    flags.some((f) => typeof request[f] !== 'boolean')
  ) {
    return null;
  }
  return {
    ...(q ? { q } : {}),
    ...Object.fromEntries(
      flags.filter((f) => request[f]).map((f) => [f, true])
    ),
  };
};

const views = (env, userClient) => async (request) => {
  const offset = request?.offset ?? '';
  const filters = filtersOf(request);
  if (
    !storyOk(request) ||
    typeof offset !== 'string' ||
    !OFFSET.test(offset) ||
    !filters
  ) {
    return badRequest;
  }
  return withStory(env, userClient, request, 'story-views', async (c, peer) => {
    const answer = await c.client.invoke(
      new c.Api.stories.GetStoryViewsList({
        peer,
        id: request.id,
        offset,
        limit: VIEWS_LIMIT,
        ...filters,
      })
    );
    return {
      ok: true,
      count: Number(answer?.count ?? 0),
      viewsCount: Number(answer?.viewsCount ?? 0),
      reactionsCount: Number(answer?.reactionsCount ?? 0),
      forwardsCount: Number(answer?.forwardsCount ?? 0),
      views: (answer?.views ?? [])
        .map((v) => shapeView(v, answer.users, answer.chats))
        .filter((v) => v.user),
      next: String(answer?.nextOffset ?? ''),
    };
  });
};

const remove = (env, userClient) => async (request) => {
  if (!storyOk(request)) {
    return badRequest;
  }
  return withStory(
    env,
    userClient,
    request,
    'story-delete',
    async (c, peer) => {
      await c.client.invoke(
        new c.Api.stories.DeleteStories({ peer, id: [request.id] })
      );
      return { ok: true };
    }
  );
};

const hide = (env, userClient) => async (request) => {
  if (
    !CHAT.test(String(request?.chat ?? '')) ||
    typeof request?.hidden !== 'boolean'
  ) {
    return badRequest;
  }
  return withStory(
    env,
    userClient,
    request,
    'stories-hide',
    async (c, peer) => {
      await c.client.invoke(
        new c.Api.stories.TogglePeerStoriesHidden({
          peer,
          hidden: request.hidden,
        })
      );
      return { ok: true, hidden: request.hidden };
    }
  );
};

export const createStoryActions = (env, { userClient }) => ({
  storyReply: reply(env, userClient),
  storyReact: react(env, userClient),
  storyViews: views(env, userClient),
  storyDelete: remove(env, userClient),
  storiesHide: hide(env, userClient),
});

/**
 * The rest of Telegram Desktop's story features (R-Y199; learned, never
 * copied):
 * - `storyStealth({ past, future })` — "Stealth mode"
 *   (stories.activateStealthMode: hide the views of the past five minutes
 *   and/or of the next twenty-five) → `{ ok, stealth: { activeUntil,
 *   cooldownUntil } }` (unix seconds, from the UpdateStoriesStealthMode
 *   the answer carries; null when it carries none). A free account gets
 *   code `premium`, a cooldown still running `cooldown`;
 * - `storyReactions({ chat, id, reaction, forwardsFirst, offset })` — the
 *   viewers' "Reactions" list of one's own story
 *   (stories.getStoryReactionsList) → `{ ok, count, views: [{ kind, user,
 *   name, date, reaction }], next }`, a reaction, a public forward or a
 *   public repost each an entry (`kind` 'view' | 'forward' | 'repost');
 * - `storyReport({ chat, id, option, message })` — "Report" on someone
 *   else's story (stories.report), the same walk of reasons as
 *   peerReport's (ReportResult shaped by the same function);
 * - `storiesViews({ chat, ids })` — fresh counters of one's own stories
 *   (stories.getStoriesViews) → `{ ok, stories: [{ id, views, reactions,
 *   forwards }] }`.
 * Telegram's errors become codes the page shows as text.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';
import { bytesOf, shapeReport } from './telegram-peer-actions.js';
import {
  VIEWS_LIMIT,
  badRequest,
  reactionOf,
  shapeView,
  storyOk,
} from './telegram-story-actions.js';
import { entityOf, nameOf, peerId, shapeStealth } from './telegram-stories.js';

const CODES = {
  PREMIUM_ACCOUNT_REQUIRED: 'premium',
  PREMIUM_REQUIRED: 'premium',
  STORIES_STEALTH: 'cooldown',
  STEALTH_MODE: 'cooldown',
  PEER_ID_INVALID: 'no-access',
  CHANNEL_PRIVATE: 'no-access',
  STORY_ID_INVALID: 'gone',
  STORIES_NEVER_CREATED: 'gone',
  OPTION_INVALID: 'bad-option',
  MESSAGE_TOO_LONG: 'too-long',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);

// Resolves the story's chat and runs `use` on it through the queue.
const withStory = (env, userClient, request, key, use) =>
  connected(env, userClient, failure, (c) =>
    runIn(env, `${key}:${request.chat}`, () =>
      env.connection.withPeer(c.client, String(request.chat), (peer) =>
        use(c, peer)
      )
    )
  );

const OFFSET = /^[A-Za-z0-9+/=_.-]{0,256}$/;
const BASE64 = /^[A-Za-z0-9+/]*={0,2}$/;
const REACTION = /^\S{1,24}$/u;
const CHAT = /^-?\d{1,20}$/;
const MAX_IDS = 100;

// The stealth state an activation's answer carries, or null.
const stealthIn = (answer) => {
  const found = [answer, ...(answer?.updates ?? []), answer?.update]
    .filter(Boolean)
    .find((u) => u.className === 'UpdateStoriesStealthMode');
  return found ? shapeStealth(found.stealthMode) : null;
};

const stealth = (env, userClient) => async (request) => {
  const { past, future } = request ?? {};
  if (
    typeof past !== 'boolean' ||
    typeof future !== 'boolean' ||
    !(past || future)
  ) {
    return badRequest;
  }
  return connected(env, userClient, failure, async (c) => {
    const answer = await runIn(env, 'stories-stealth', () =>
      c.client.invoke(
        new c.Api.stories.ActivateStealthMode({
          ...(past ? { past: true } : {}),
          ...(future ? { future: true } : {}),
        })
      )
    );
    return { ok: true, stealth: stealthIn(answer) };
  });
};

// One entry of the reactions list (R-Y199).
const shapeReaction = (item, answer) => {
  const shared = {
    StoryReactionPublicForward: () => ({
      className: 'StoryViewPublicForward',
      message: item.message,
    }),
    StoryReactionPublicRepost: () => ({
      className: 'StoryViewPublicRepost',
      peerId: item.peerId,
      story: item.story,
    }),
  }[item.className];
  if (shared) {
    return shapeView(shared(), answer.users, answer.chats);
  }
  return {
    kind: 'view',
    user: peerId(item.peerId),
    name: nameOf(entityOf(answer, item.peerId)),
    date: Number(item.date ?? 0),
    reaction: reactionOf(item.reaction),
  };
};

const validReactions = (r) =>
  storyOk(r) &&
  (r.offset === undefined ||
    (typeof r.offset === 'string' && OFFSET.test(r.offset))) &&
  (r.reaction === undefined ||
    (typeof r.reaction === 'string' && REACTION.test(r.reaction))) &&
  (r.forwardsFirst === undefined || typeof r.forwardsFirst === 'boolean');

const reactions = (env, userClient) => async (request) => {
  if (!validReactions(request ?? {})) {
    return badRequest;
  }
  return withStory(
    env,
    userClient,
    request,
    'story-reactions',
    async (c, peer) => {
      const answer = await c.client.invoke(
        new c.Api.stories.GetStoryReactionsList({
          peer,
          id: request.id,
          offset: request.offset ?? '',
          limit: VIEWS_LIMIT,
          ...(request.forwardsFirst ? { forwardsFirst: true } : {}),
          ...(request.reaction
            ? {
                reaction: new c.Api.ReactionEmoji({
                  emoticon: request.reaction,
                }),
              }
            : {}),
        })
      );
      return {
        ok: true,
        count: Number(answer?.count ?? 0),
        views: (answer?.reactions ?? []).map((r) => shapeReaction(r, answer)),
        next: String(answer?.nextOffset ?? ''),
      };
    }
  );
};

const validReport = (r) =>
  storyOk(r) &&
  (r.option === undefined ||
    (typeof r.option === 'string' &&
      r.option.length <= 2048 &&
      BASE64.test(r.option))) &&
  (r.message === undefined ||
    (typeof r.message === 'string' && r.message.length <= 512));

const report = (env, userClient) => async (request) => {
  if (!validReport(request ?? {})) {
    return badRequest;
  }
  return withStory(env, userClient, request, 'story-report', async (c, peer) =>
    shapeReport(
      await c.client.invoke(
        new c.Api.stories.Report({
          peer,
          id: [request.id],
          option: bytesOf(request.option),
          message: request.message ?? '',
        })
      )
    )
  );
};

const validIds = (r) =>
  CHAT.test(String(r?.chat ?? '')) &&
  Array.isArray(r?.ids) &&
  r.ids.length > 0 &&
  r.ids.length <= MAX_IDS &&
  r.ids.every((id) => Number.isInteger(id) && id > 0);

const storiesViews = (env, userClient) => async (request) => {
  if (!validIds(request)) {
    return badRequest;
  }
  return withStory(
    env,
    userClient,
    request,
    'stories-views',
    async (c, peer) => {
      const answer = await c.client.invoke(
        new c.Api.stories.GetStoriesViews({ peer, id: request.ids })
      );
      return {
        ok: true,
        stories: request.ids.map((id, i) => ({
          id,
          views: Number(answer?.views?.[i]?.viewsCount ?? 0),
          reactions: Number(answer?.views?.[i]?.reactionsCount ?? 0),
          forwards: Number(answer?.views?.[i]?.forwardsCount ?? 0),
        })),
      };
    }
  );
};

export const createStoryExtras = (env, { userClient }) => ({
  storyStealth: stealth(env, userClient),
  storyReactions: reactions(env, userClient),
  storyReport: report(env, userClient),
  storiesViews: storiesViews(env, userClient),
});

/**
 * Managing one's own stories, as Telegram Desktop does (R-Y210; learned,
 * never copied). Deleting, the viewers, pinning and the archive are in
 * ./telegram-story-actions.js and ./telegram-profile-stories.js; here:
 * - `storyEdit({ chat, id, caption?, privacy?, users? })` — a story's
 *   caption and/or whom it is for (stories.editStory with `caption` +
 *   `entities`, or `privacyRules`; `privacy` is `everyone`, `contacts`,
 *   `close-friends` or `selected` with `users` ids of contacts) →
 *   `{ ok, caption?, entities?, privacy? }`. A caption is markdown, as
 *   the composer's (./telegram-format.js), sent as text and entities;
 * - `storyLink({ chat, id })` — the t.me link of a story
 *   (stories.exportStoryLink) → `{ ok, link }`.
 * Telegram's errors become codes the page shows as text.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';
import { apiEntities, parseFormatted, rawEntities } from './telegram-format.js';
import {
  CAPTION_MAX_PREMIUM,
  PRIVACIES,
  MAX_SELECTED,
  inputUsersOf,
  privacyRules,
} from './telegram-story-post.js';
import { badRequest, storyOk } from './telegram-story-actions.js';

const CODES = {
  PEER_ID_INVALID: 'no-access',
  CHANNEL_PRIVATE: 'no-access',
  CHAT_ADMIN_REQUIRED: 'no-access',
  STORY_ID_INVALID: 'gone',
  STORY_NOT_MODIFIED: 'unchanged',
  MEDIA_CAPTION_TOO_LONG: 'caption-too-long',
  USER_ID_INVALID: 'users-invalid',
  PRIVACY_PARTICIPANT_INVALID: 'users-invalid',
  FLOOD_WAIT: 'flood',
};
const failure = failureOf(CODES);
const USER_ID = /^\d{1,20}$/;
const bad = (code) => ({ ok: false, error: code, code });

// What is wrong with an edit request, as a code, or null.
export const editProblem = (r) => {
  if (!storyOk(r)) {
    return 'failed';
  }
  const hasCaption = r.caption !== undefined;
  if (!hasCaption && r.privacy === undefined) {
    return 'failed';
  }
  if (
    hasCaption &&
    !(
      typeof r.caption === 'string' &&
      [...r.caption].length <= CAPTION_MAX_PREMIUM
    )
  ) {
    return 'caption-too-long';
  }
  if (r.privacy === undefined) {
    return null;
  }
  if (!PRIVACIES.includes(r.privacy)) {
    return 'failed';
  }
  const ids = r.users;
  return r.privacy !== 'selected' ||
    (Array.isArray(ids) &&
      ids.length > 0 &&
      ids.length <= MAX_SELECTED &&
      ids.every((id) => USER_ID.test(String(id))))
    ? null
    : 'users-invalid';
};

const withStory = (env, userClient, request, key, use) =>
  connected(env, userClient, failure, (c) =>
    runIn(env, `${key}:${request.chat}`, () =>
      env.connection.withPeer(c.client, String(request.chat), (peer) =>
        use(c, peer)
      )
    )
  );

const edit = (env, userClient) => async (request) => {
  const problem = editProblem(request ?? {});
  if (problem) {
    return bad(problem);
  }
  return withStory(env, userClient, request, 'story-edit', async (c, peer) => {
    const users =
      request.privacy === 'selected'
        ? await inputUsersOf(env, c, request.users)
        : [];
    if (!users) {
      return bad('users-invalid');
    }
    const formatted =
      request.caption === undefined ? null : parseFormatted(request.caption);
    await c.client.invoke(
      new c.Api.stories.EditStory({
        peer,
        id: request.id,
        ...(formatted
          ? {
              caption: formatted.text,
              entities: apiEntities(c.Api, formatted.entities),
            }
          : {}),
        ...(request.privacy === undefined
          ? {}
          : { privacyRules: privacyRules(c.Api, request.privacy, users) }),
      })
    );
    return {
      ok: true,
      ...(formatted
        ? {
            caption: formatted.text,
            entities: rawEntities(formatted.entities),
          }
        : {}),
      ...(request.privacy === undefined ? {} : { privacy: request.privacy }),
    };
  });
};

const link = (env, userClient) => async (request) => {
  if (!storyOk(request)) {
    return badRequest;
  }
  return withStory(env, userClient, request, 'story-link', async (c, peer) => {
    const answer = await c.client.invoke(
      new c.Api.stories.ExportStoryLink({ peer, id: request.id })
    );
    return answer?.link
      ? { ok: true, link: String(answer.link) }
      : bad('failed');
  });
};

export const createStoryManage = (env, { userClient }) => ({
  storyEdit: edit(env, userClient),
  storyLink: link(env, userClient),
});

/**
 * Posting a story, as Telegram Desktop does (R-Y156; learned, never
 * copied):
 * - `storyCanPost()` — stories.canSendStory for the user (InputPeerSelf)
 *   → `{ ok: true, remains, premium, me: { id, name }, captionMax }`; when the limit is
 *   reached Telegram's answer becomes `{ ok: false, code: 'too-many' }`
 *   (`'premium'` when only Premium may post);
 * - `storyPost({ token, kind, caption, privacy, users, screenshots,
 *   pinned, period, duration, width, height })` — the page's upload
 *   (./telegram-upload.js) sent with stories.sendStory as the user's own
 *   story: a photo as InputMediaUploadedPhoto, a video as
 *   InputMediaUploadedDocument with DocumentAttributeVideo (streaming,
 *   length, size). `privacy` is `everyone`, `contacts`, `close-friends`
 *   or `selected` (then `users` are ids of contacts); `screenshots`
 *   false means `noforwards`; `pinned` keeps it on the profile; `period`
 *   (Premium) is 6, 12, 24 or 48 hours in seconds.
 * Telegram's errors become codes the page shows as words.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';
import { uploadedFile } from './telegram-chat-edit.js';
import { randomIdOf } from './telegram-send.js';

const CODES = {
  STORIES_TOO_MUCH: 'too-many',
  STORIES_SEND_LIMIT: 'too-many',
  STORY_SEND_FLOOD: 'too-many',
  PREMIUM_ACCOUNT_REQUIRED: 'premium',
  MEDIA_INVALID: 'media-invalid',
  MEDIA_EMPTY: 'media-invalid',
  PHOTO_INVALID_DIMENSIONS: 'media-invalid',
  IMAGE_PROCESS_FAILED: 'media-invalid',
  VIDEO_CONTENT_TYPE_INVALID: 'media-invalid',
  MEDIA_VIDEO_STORY_TOO_LONG: 'video-too-long',
  STORY_VIDEO_TOO_LONG: 'video-too-long',
  USER_ID_INVALID: 'users-invalid',
  PRIVACY_PARTICIPANT_INVALID: 'users-invalid',
  MEDIA_CAPTION_TOO_LONG: 'caption-too-long',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);

/** Telegram allows a story video of a minute at most. */
export const MAX_STORY_SECONDS = 60;
/** The caption: 200 characters, 2048 with Premium. */
export const CAPTION_MAX = 200;
export const CAPTION_MAX_PREMIUM = 2048;
/** The hours a story may last (Premium chooses), in seconds. */
export const PERIODS = [21_600, 43_200, 86_400, 172_800];
export const PRIVACIES = ['everyone', 'contacts', 'close-friends', 'selected'];
export const MAX_SELECTED = 1000;

const TOKEN = /^[0-9a-f]{32}$/;
const USER_ID = /^\d{1,20}$/;
const VIDEO_MIME = {
  mp4: 'video/mp4',
  m4v: 'video/mp4',
  mov: 'video/quicktime',
  webm: 'video/webm',
};

const bad = (code) => ({ ok: false, error: code, code });
const textOf = (value) => String(value?.value ?? value);
const whole = (value) => Math.max(1, Math.round(Number(value) || 0));

/** The mime type a video's name says (MP4 when unknown). */
export const videoMime = (name) =>
  VIDEO_MIME[/\.([a-z0-9]+)$/i.exec(String(name ?? ''))?.[1]?.toLowerCase()] ??
  'video/mp4';

/**
 * Whom a story is for, as Telegram's rules: everyone, contacts, close
 * friends, or the chosen contacts (`inputUsers`, built by the caller).
 */
export const privacyRules = (Api, privacy, inputUsers = []) => {
  if (privacy === 'contacts') {
    return [new Api.InputPrivacyValueAllowContacts()];
  }
  if (privacy === 'close-friends') {
    return [new Api.InputPrivacyValueAllowCloseFriends()];
  }
  if (privacy === 'selected') {
    return [new Api.InputPrivacyValueAllowUsers({ users: inputUsers })];
  }
  return [new Api.InputPrivacyValueAllowAll()];
};

// The media: a photo, or a video with its attribute.
const mediaOf = (c, file, request, name) => {
  if (request.kind !== 'video') {
    return new c.Api.InputMediaUploadedPhoto({ file });
  }
  return new c.Api.InputMediaUploadedDocument({
    file,
    mimeType: videoMime(name),
    attributes: [
      new c.Api.DocumentAttributeVideo({
        supportsStreaming: true,
        duration: Number(request.duration) || 0,
        w: whole(request.width),
        h: whole(request.height),
      }),
    ],
  });
};

const selectedProblem = (r) => {
  if (r.privacy !== 'selected') {
    return null;
  }
  const ids = r.users;
  const ok =
    Array.isArray(ids) &&
    ids.length > 0 &&
    ids.length <= MAX_SELECTED &&
    ids.every((id) => USER_ID.test(String(id)));
  return ok ? null : 'users-invalid';
};

const videoProblem = (r) => {
  if (r.kind !== 'video') {
    return null;
  }
  if (!(Number(r.duration) > 0)) {
    return 'failed';
  }
  return Number(r.duration) > MAX_STORY_SECONDS + 0.5 ? 'video-too-long' : null;
};

// What is wrong with the request, as a code, or null.
const problemOf = (request) => {
  const r = request ?? {};
  if (
    !TOKEN.test(String(r.token ?? '')) ||
    (r.kind !== 'photo' && r.kind !== 'video') ||
    !PRIVACIES.includes(r.privacy) ||
    (r.period !== undefined && !PERIODS.includes(r.period))
  ) {
    return 'failed';
  }
  if (
    typeof r.caption !== 'string' ||
    [...r.caption].length > CAPTION_MAX_PREMIUM
  ) {
    return 'caption-too-long';
  }
  return videoProblem(r) ?? selectedProblem(r);
};

// The chosen contacts as InputUsers (their access hashes come from the
// contacts list); null when one is not a contact.
export const inputUsersOf = async (env, c, ids) => {
  const answer = await runIn(env, 'contacts:list', () =>
    c.client.invoke(new c.Api.contacts.GetContacts({ hash: c.zero }))
  );
  const byId = new Map((answer?.users ?? []).map((u) => [textOf(u.id), u]));
  const chosen = [...new Set(ids.map(String))].map((id) => byId.get(id));
  return chosen.every(Boolean)
    ? chosen.map(
        (u) =>
          new c.Api.InputUser({
            userId: u.id,
            accessHash: u.accessHash ?? c.zero,
          })
      )
    : null;
};

const canPost = (env, userClient) => async () =>
  connected(env, userClient, failure, async (c) => {
    const answer = await runIn(env, 'story-can-post', () =>
      c.client.invoke(
        new c.Api.stories.CanSendStory({ peer: new c.Api.InputPeerSelf() })
      )
    );
    const me = await c.client.getMe?.().catch(() => null);
    const premium = Boolean(me?.premium);
    return {
      ok: true,
      remains: Number(answer?.countRemains ?? 0),
      premium,
      me: me
        ? {
            id: textOf(me.id),
            name:
              [me.firstName, me.lastName].filter(Boolean).join(' ') ||
              me.username ||
              '',
          }
        : null,
      captionMax: premium ? CAPTION_MAX_PREMIUM : CAPTION_MAX,
    };
  });

const send = async (c, uploads, request) => {
  const entry = uploads?.uploadOf?.(request.token);
  const users =
    request.privacy === 'selected'
      ? await inputUsersOf(c.env, c, request.users)
      : [];
  if (!users) {
    return bad('users-invalid');
  }
  const file = await uploadedFile(c, uploads, request.token);
  if (!file) {
    return bad('media-invalid');
  }
  await runIn(c.env, 'story-post', () =>
    c.client.invoke(
      new c.Api.stories.SendStory({
        peer: new c.Api.InputPeerSelf(),
        media: mediaOf(c, file, request, entry?.name),
        privacyRules: privacyRules(c.Api, request.privacy, users),
        caption: request.caption,
        randomId: randomIdOf(null, 0, c.helpers),
        ...(request.screenshots === false ? { noforwards: true } : {}),
        ...(request.pinned === true ? { pinned: true } : {}),
        ...(request.period ? { period: request.period } : {}),
      })
    )
  );
  return { ok: true };
};

const post =
  (env, { userClient, uploads }) =>
  async (request) => {
    const problem = problemOf(request);
    const token = String(request?.token ?? '');
    try {
      if (problem) {
        return bad(problem);
      }
      return await connected(env, userClient, failure, (c) =>
        send({ ...c, env }, uploads, request)
      );
    } finally {
      if (TOKEN.test(token)) {
        await uploads?.dropUpload?.(token);
      }
    }
  };

/** `context.uploads` has the page's uploads (`uploadOf`, `dropUpload`). */
export const createStoryPost = (env, context) => ({
  storyCanPost: canPost(env, context.userClient),
  storyPost: post(env, context),
});

/**
 * Frequent contacts, as Telegram Desktop's search shows them when the
 * query is empty (R-Y207; learned, never copied):
 * - `topPeers()` — contacts.getTopPeers (correspondents) → `{ ok, enabled,
 *   peers: [{ chat, name, username, kind }] }`; `enabled` false when the
 *   user turned the list off.
 * - `removeTopPeer({ chat })` — contacts.resetTopPeerRating (correspondents).
 * - `setTopPeers({ enabled })` — contacts.toggleTopPeers.
 */

import {
  entitiesOf,
  kindOf,
  nameOf,
  peerIdOf,
  usernameOf,
} from './telegram-global.js';
import { connected, failureOf, runIn } from './telegram-stickers.js';

const failure = failureOf({ FLOOD_WAIT: 'flood' });
export const TOP_LIMIT = 10;
const CHAT = /^-?\d{1,20}$/;

const bad = { ok: false, error: 'bad-request', code: 'bad-request' };

// The correspondents category of an answer.
const correspondents = (answer) =>
  (answer?.categories ?? []).find((c) =>
    String(c?.category?.className ?? '').endsWith(
      'TopPeerCategoryCorrespondents'
    )
  );

/** The people of an answer, in Telegram's order: `[{ chat, entity }]`. */
export const peopleOf = (answer, utils) => {
  const entities = entitiesOf(answer, utils);
  const found = [];
  for (const top of correspondents(answer)?.peers ?? []) {
    const chat = peerIdOf(utils, top.peer);
    const entity = entities.get(chat);
    if (entity && !entity.self && !entity.deleted) {
      found.push({ chat, entity });
    }
  }
  return found;
};

const createTop = (env, userClient) => async () =>
  connected(env, userClient, failure, async (c) => {
    const { utils } = await env.importer();
    const answer = await runIn(env, 'top-peers', () =>
      c.client.invoke(
        new c.Api.contacts.GetTopPeers({
          correspondents: true,
          offset: 0,
          limit: TOP_LIMIT,
          hash: c.zero,
        })
      )
    );
    if (String(answer?.className ?? '').endsWith('TopPeersDisabled')) {
      return { ok: true, enabled: false, peers: [] };
    }
    const peers = [];
    for (const { chat, entity } of peopleOf(answer, utils)) {
      await env.peers?.remember?.(chat, entity);
      peers.push({
        chat,
        name: nameOf(entity),
        username: usernameOf(entity),
        kind: kindOf(entity),
      });
    }
    return { ok: true, enabled: true, peers };
  });

const createRemove =
  (env, userClient) =>
  async ({ chat } = {}) => {
    if (!CHAT.test(String(chat ?? ''))) {
      return bad;
    }
    return connected(env, userClient, failure, async (c) => {
      await env.connection.withPeer(c.client, String(chat), (peer) =>
        c.client.invoke(
          new c.Api.contacts.ResetTopPeerRating({
            category: new c.Api.TopPeerCategoryCorrespondents(),
            peer,
          })
        )
      );
      return { ok: true };
    });
  };

const createToggle =
  (env, userClient) =>
  async ({ enabled } = {}) => {
    if (typeof enabled !== 'boolean') {
      return bad;
    }
    return connected(env, userClient, failure, async (c) => {
      await c.client.invoke(new c.Api.contacts.ToggleTopPeers({ enabled }));
      return { ok: true, enabled };
    });
  };

export const createTopPeers = (env, { userClient }) => ({
  topPeers: createTop(env, userClient),
  removeTopPeer: createRemove(env, userClient),
  setTopPeers: createToggle(env, userClient),
});

/**
 * Managing a forum group's topics, as Telegram Desktop does (R-Y153;
 * learned, never copied):
 * - `topicIcons()` — the emoji a topic may carry (the default topic icon
 *   stickers, messages.getStickerSet) → `{ ok, icons: [{ id, emoji }] }`;
 * - `createTopic({ chat, title, iconColor, iconEmojiId? })` — a new topic
 *   (messages.createForumTopic);
 * - `editTopic({ chat, topic, title?, iconEmojiId?, closed?, hidden? })` —
 *   rename, change the icon (`'0'` takes it off), close or reopen, hide or
 *   show General (messages.editForumTopic);
 * - `pinTopic({ chat, topic, pinned })` — messages.updatePinnedForumTopic;
 * - `deleteTopic({ chat, topic })` — the topic and its messages
 *   (messages.deleteTopicHistory, until Telegram has nothing left);
 * - `reorderTopics({ chat, order })` — the pinned topics in a new order
 *   (messages.reorderPinnedForumTopics with force, R-Y211);
 * - `toggleForum({ chat, enabled })` — a supergroup's Topics on or off
 *   (channels.toggleForum).
 * Telegram's errors become codes the page shows as text.
 */

import { TOPIC_COLORS } from '../web/forum-topics.js';
import { randomIdOf } from './telegram-send.js';
import { connected, failureOf, runIn } from './telegram-stickers.js';

const CODES = {
  CHAT_ADMIN_REQUIRED: 'not-admin',
  CHAT_NOT_MODIFIED: 'not-modified',
  TOPIC_TITLE_EMPTY: 'title-empty',
  TOPIC_NOT_MODIFIED: 'not-modified',
  TOPIC_ID_INVALID: 'no-topic',
  TOPIC_CLOSED: 'closed',
  CHANNEL_FORUM_MISSING: 'no-forum',
  CHANNEL_PRIVATE: 'no-access',
  CHANNEL_INVALID: 'no-access',
  PEER_ID_INVALID: 'no-access',
};

const asFailure = failureOf(CODES);
// Nothing to change is no failure.
const failure = (error) => {
  const out = asFailure(error);
  return out.code === 'not-modified' ? { ok: true } : out;
};
const bad = () => ({ ok: false, error: 'bad-request', code: 'bad-request' });

const CHANNEL = /^-100\d{1,20}$/;
const ID = /^\d{1,20}$/;
export const TITLE_MAX = 128;
export const GENERAL = 1;
export { TOPIC_COLORS };
const MAX_ROUNDS = 50;

const textOf = (value) => String(value?.value ?? value);
const topicId = (value) =>
  Number.isInteger(value) && value > 0 ? value : null;
const titleOf = (value) => {
  const title = typeof value === 'string' ? value.trim() : '';
  return title && Array.from(title).length <= TITLE_MAX ? title : null;
};
const emojiIdOf = (value) =>
  ID.test(String(value ?? '')) ? String(value) : null;

const createIcons = (env, userClient) => async () =>
  connected(env, userClient, failure, async (c) => {
    const answer = await runIn(env, 'topic:icons', () =>
      c.client.invoke(
        new c.Api.messages.GetStickerSet({
          stickerset: new c.Api.InputStickerSetEmojiDefaultTopicIcons(),
          hash: 0,
        })
      )
    );
    const icons = (answer?.documents ?? []).flatMap((doc) => {
      const mark = (doc.attributes ?? []).find((a) => a.alt !== undefined);
      return mark?.alt ? [{ id: textOf(doc.id), emoji: String(mark.alt) }] : [];
    });
    return { ok: true, icons };
  });

const createCreate =
  (env, userClient) =>
  async (body = {}) => {
    const chat = String(body.chat ?? '');
    const title = titleOf(body.title);
    const emoji =
      body.iconEmojiId === undefined ? null : emojiIdOf(body.iconEmojiId);
    if (
      !CHANNEL.test(chat) ||
      !title ||
      !TOPIC_COLORS.includes(body.iconColor) ||
      (body.iconEmojiId !== undefined && !emoji)
    ) {
      return bad();
    }
    return connected(env, userClient, failure, async (c) => {
      await runIn(env, `topic:create:${chat}`, () =>
        env.connection.withPeer(c.client, chat, (peer) =>
          c.client.invoke(
            new c.Api.messages.CreateForumTopic({
              peer,
              title,
              iconColor: body.iconColor,
              ...(emoji ? { iconEmojiId: c.helpers.returnBigInt(emoji) } : {}),
              randomId: randomIdOf(null, 0, c.helpers),
            })
          )
        )
      );
      return { ok: true };
    });
  };

// The fields an edit may carry, each checked; null when one is wrong or
// none is given.
const editFields = (body) => {
  const out = {};
  if (body.title !== undefined) {
    out.title = titleOf(body.title);
  }
  if (body.iconEmojiId !== undefined) {
    out.iconEmojiId = emojiIdOf(body.iconEmojiId);
  }
  for (const key of ['closed', 'hidden']) {
    if (body[key] !== undefined) {
      out[key] = typeof body[key] === 'boolean' ? body[key] : null;
    }
  }
  const values = Object.values(out);
  return values.length > 0 && values.every((v) => v !== null) ? out : null;
};

const createEdit =
  (env, userClient) =>
  async (body = {}) => {
    const chat = String(body.chat ?? '');
    const topic = topicId(body.topic);
    const fields = editFields(body);
    if (!CHANNEL.test(chat) || !topic || !fields) {
      return bad();
    }
    return connected(env, userClient, failure, async (c) => {
      const { iconEmojiId, ...rest } = fields;
      await runIn(env, `topic:edit:${chat}:${topic}`, () =>
        env.connection.withPeer(c.client, chat, (peer) =>
          c.client.invoke(
            new c.Api.messages.EditForumTopic({
              peer,
              topicId: topic,
              ...rest,
              ...(iconEmojiId === undefined
                ? {}
                : { iconEmojiId: c.helpers.returnBigInt(iconEmojiId) }),
            })
          )
        )
      );
      return { ok: true };
    });
  };

const createPin =
  (env, userClient) =>
  async (body = {}) => {
    const chat = String(body.chat ?? '');
    const topic = topicId(body.topic);
    if (!CHANNEL.test(chat) || !topic || typeof body.pinned !== 'boolean') {
      return bad();
    }
    return connected(env, userClient, failure, async (c) => {
      await runIn(env, `topic:pin:${chat}:${topic}`, () =>
        env.connection.withPeer(c.client, chat, (peer) =>
          c.client.invoke(
            new c.Api.messages.UpdatePinnedForumTopic({
              peer,
              topicId: topic,
              pinned: body.pinned,
            })
          )
        )
      );
      return { ok: true };
    });
  };

/** The pinned topics' new order: distinct topic ids, 1 to 100, else null. */
export const pinOrderOf = (order) =>
  Array.isArray(order) &&
  order.length > 0 &&
  order.length <= 100 &&
  order.every((id) => topicId(id) && id !== GENERAL) &&
  new Set(order).size === order.length
    ? order
    : null;

const createReorder =
  (env, userClient) =>
  async (body = {}) => {
    const chat = String(body.chat ?? '');
    const order = pinOrderOf(body.order);
    if (!CHANNEL.test(chat) || !order) {
      return bad();
    }
    return connected(env, userClient, failure, async (c) => {
      await runIn(env, `topic:reorder:${chat}`, () =>
        env.connection.withPeer(c.client, chat, (peer) =>
          c.client.invoke(
            new c.Api.messages.ReorderPinnedForumTopics({
              peer,
              order,
              force: true,
            })
          )
        )
      );
      return { ok: true };
    });
  };

const createDelete =
  (env, userClient) =>
  async (body = {}) => {
    const chat = String(body.chat ?? '');
    const topic = topicId(body.topic);
    // General cannot be deleted.
    if (!CHANNEL.test(chat) || !topic || topic === GENERAL) {
      return bad();
    }
    return connected(env, userClient, failure, async (c) => {
      // Telegram deletes in steps: asked again while it says more is left.
      for (let round = 0; round < MAX_ROUNDS; round += 1) {
        const answer = await runIn(env, `topic:delete:${chat}:${topic}`, () =>
          env.connection.withPeer(c.client, chat, (peer) =>
            c.client.invoke(
              new c.Api.messages.DeleteTopicHistory({ peer, topMsgId: topic })
            )
          )
        );
        if (!Number(answer?.offset)) {
          break;
        }
      }
      return { ok: true };
    });
  };

const createToggle =
  (env, userClient) =>
  async (body = {}) => {
    const chat = String(body.chat ?? '');
    if (!CHANNEL.test(chat) || typeof body.enabled !== 'boolean') {
      return bad();
    }
    return connected(env, userClient, failure, async (c) => {
      await runIn(env, `topic:forum:${chat}`, () =>
        env.connection.withPeer(c.client, chat, (peer) =>
          c.client.invoke(
            new c.Api.channels.ToggleForum({
              channel: peer,
              enabled: body.enabled,
              tabs: false,
            })
          )
        )
      );
      return { ok: true };
    });
  };

export const createTopicAdmin = (env, { userClient }) => ({
  topicIcons: createIcons(env, userClient),
  createTopic: createCreate(env, userClient),
  editTopic: createEdit(env, userClient),
  pinTopic: createPin(env, userClient),
  reorderTopics: createReorder(env, userClient),
  deleteTopic: createDelete(env, userClient),
  toggleForum: createToggle(env, userClient),
});

/**
 * Voice and video note transcription, as Telegram Desktop's "→A" button
 * has it (R-Y175; learned, never copied):
 * - `transcribeAudio({ chat, id })` — messages.transcribeAudio on the
 *   message → `{ ok, transcriptionId, text, pending, trialRemains?,
 *   trialUntil? }`. While `pending` the text is what is known so far and
 *   the final one comes as updateTranscribedAudio (`transcriptWriter`
 *   below keeps it as a `transcript:telegram:<chat>:<id>` link the page
 *   follows) or by asking again. Non-Premium accounts get a trial: how
 *   many free ones remain and, when none, the date the next is free;
 * - `rateTranscription({ chat, id, transcriptionId, good })` —
 *   messages.rateTranscribedAudio.
 * Telegram's refusals (Premium needed, the transcription failed, a flood
 * wait) become codes the page shows as text.
 */

import { connected, runIn, failureOf } from './telegram-stickers.js';

const SOURCE = 'telegram';

const CODES = {
  PREMIUM_ACCOUNT_REQUIRED: 'premium',
  TRANSCRIPTION_FAILED: 'transcription-failed',
  MSG_ID_INVALID: 'not-found',
  PEER_ID_INVALID: 'no-access',
  CHANNEL_PRIVATE: 'no-access',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);

const CHAT = /^-?\d{1,20}$/;
const NUMBER = /^\d{1,20}$/;
const MAX_KEPT = 500;

/** The link that keeps one message's transcription. */
export const transcriptLinkId = (chat, id) =>
  `transcript:${SOURCE}:${chat}:${id}`;

// Telegram's answer, as the page reads it.
const shapeOf = (answer) => ({
  transcriptionId: String(answer.transcriptionId),
  text: String(answer.text ?? ''),
  pending: Boolean(answer.pending),
  ...(answer.trialRemainsNum === undefined
    ? {}
    : {
        trialRemains: Number(answer.trialRemainsNum),
        trialUntil: Number(answer.trialRemainsUntilDate) || null,
      }),
});

const linkOf = (chat, id, shape, now) => ({
  id: transcriptLinkId(chat, id),
  tokens: ['transcript', SOURCE, String(chat), String(id)],
  kind: 'transcript',
  source: SOURCE,
  chat: String(chat),
  msgId: Number(id),
  ...shape,
  at: new Date(now()).toISOString(),
});

/**
 * An updateTranscribedAudio kept: the message's transcript link takes the
 * text. True when it changed.
 */
export const transcriptWriter = async (store, effect, now = Date.now) => {
  if (!effect.id || !effect.chat) {
    return false;
  }
  const before = await store.get(transcriptLinkId(effect.chat, effect.id));
  const shape = {
    transcriptionId: String(effect.transcriptionId),
    text: String(effect.text ?? ''),
    pending: Boolean(effect.pending),
    // The trial counts stay from the call that asked.
    ...(before?.trialRemains === undefined
      ? {}
      : { trialRemains: before.trialRemains, trialUntil: before.trialUntil }),
  };
  if (
    before &&
    before.transcriptionId === shape.transcriptionId &&
    before.text === shape.text &&
    before.pending === shape.pending
  ) {
    return false;
  }
  await store.put(linkOf(effect.chat, effect.id, shape, now));
  return true;
};

const validAsk = ({ chat, id } = {}) =>
  CHAT.test(String(chat ?? '')) && Number.isInteger(id) && id > 0;

const validRate = (body = {}) =>
  validAsk(body) &&
  NUMBER.test(String(body.transcriptionId ?? '')) &&
  typeof body.good === 'boolean';

export const createTranscribe = (env, { userClient, now = Date.now }) => {
  const kept = new Map(); // chat:id -> shape
  const keep = (key, shape) => {
    kept.delete(key);
    kept.set(key, shape);
    if (kept.size > MAX_KEPT) {
      kept.delete(kept.keys().next().value);
    }
  };

  const transcribeAudio = async (body = {}) => {
    if (!validAsk(body)) {
      return { ok: false, error: 'bad request', code: 'failed' };
    }
    const { chat, id } = body;
    const key = `${chat}:${id}`;
    const done = kept.get(key);
    if (done && !done.pending) {
      return { ok: true, ...done };
    }
    return connected(env, userClient, failure, async (c) => {
      const answer = await runIn(env, `transcribe:${key}`, () =>
        env.connection.withPeer(c.client, String(chat), (peer) =>
          c.client.invoke(
            new c.Api.messages.TranscribeAudio({ peer, msgId: id })
          )
        )
      );
      const shape = shapeOf(answer);
      keep(key, shape);
      await env.store?.put?.(linkOf(chat, id, shape, now));
      return { ok: true, ...shape };
    });
  };

  const rateTranscription = async (body = {}) => {
    if (!validRate(body)) {
      return { ok: false, error: 'bad request', code: 'failed' };
    }
    return connected(env, userClient, failure, async (c) => {
      await runIn(env, `transcribe-rate:${body.chat}:${body.id}`, () =>
        env.connection.withPeer(c.client, String(body.chat), (peer) =>
          c.client.invoke(
            new c.Api.messages.RateTranscribedAudio({
              peer,
              msgId: body.id,
              transcriptionId: c.helpers.returnBigInt(
                String(body.transcriptionId)
              ),
              good: body.good,
            })
          )
        )
      );
      return { ok: true };
    });
  };

  return { transcribeAudio, rateTranscription };
};

/**
 * The translate bar's and the summary's server side (R-Y213; learned,
 * never copied). Translating a chat's messages is `translateMessages`
 * (./telegram-translate.js); here are:
 * - `translateAccount()` — `{ ok, premium }`: whether the account has
 *   Premium, which the bar needs to offer translating whole chats.
 * - `summarizeMessage({ chat, id, to? })` — messages.summarizeText of a
 *   long message → `{ ok, text, entities }` (entities as a stored
 *   message's). Telegram's refusals become codes the page shows in words.
 */

import { connected, runIn } from './telegram-stickers.js';
import { CHAT, LANG, failure, plainEntity } from './telegram-translate.js';

const validSummary = ({ chat, id, to } = {}) =>
  CHAT.test(String(chat ?? '')) &&
  Number.isInteger(id) &&
  id > 0 &&
  (to === undefined || LANG.test(String(to)));

export const createTranslateChat = (env, context) => {
  const translateAccount = () =>
    connected(env, context.userClient, failure, async (c) => ({
      ok: true,
      premium: Boolean((await c.client.getMe?.())?.premium),
    }));

  const summarizeMessage = async (body = {}) => {
    if (!validSummary(body)) {
      return { ok: false, error: 'invalid request', code: 'bad-request' };
    }
    const { chat, id, to } = body;
    return connected(env, context.userClient, failure, async (c) => {
      const answer = await runIn(
        env,
        `summarize:${chat}:${id}:${to ?? ''}`,
        () =>
          env.connection.withPeer(c.client, chat, (peer) =>
            c.client.invoke(
              new c.Api.messages.SummarizeText({
                peer,
                id,
                ...(to ? { toLang: to } : {}),
              })
            )
          )
      );
      return {
        ok: true,
        text: String(answer?.text ?? ''),
        entities: (answer?.entities ?? []).map(plainEntity),
      };
    });
  };

  return { translateAccount, summarizeMessage };
};

/**
 * Translating messages, as Telegram Desktop's "Translate" does (R-Y132;
 * learned, never copied):
 * - `translateMessages({ chat, ids, to })` — the messages' texts in the
 *   language `to` (messages.translateText with the peer and the ids) →
 *   `{ ok, items: [{ id, text, entities }] }`, the entities by className
 *   as a stored message's. Answers are kept in memory by chat, id and
 *   language, so asking again costs nothing.
 * Telegram's refusals (translations off in the chat, the quota used up,
 * a language it has not, Premium needed) become codes the page shows as
 * text.
 */

import { connected, runIn, failureOf } from './telegram-stickers.js';

export const CODES = {
  TRANSLATIONS_DISABLED: 'disabled',
  TRANSLATE_REQ_QUOTA_EXCEEDED: 'quota',
  FLOOD_WAIT: 'quota',
  MSG_ID_INVALID: 'not-found',
  TO_LANG_INVALID: 'bad-language',
  PREMIUM_ACCOUNT_REQUIRED: 'premium',
};

export const failure = failureOf(CODES);

export const CHAT = /^-?\d{1,20}$/;
export const LANG = /^[a-z]{2,3}(-[A-Za-z]{2,4})?$/;
const MAX_IDS = 20;
const MAX_KEPT = 500;

// An entity as the page draws it: plain fields, ids as strings.
export const plainEntity = (one) => ({
  className: one.className,
  offset: Number(one.offset),
  length: Number(one.length),
  ...(one.url ? { url: String(one.url) } : {}),
  ...(one.language ? { language: String(one.language) } : {}),
  ...(one.documentId === undefined
    ? {}
    : { documentId: String(one.documentId) }),
});

const valid = ({ chat, ids, to } = {}) =>
  CHAT.test(String(chat ?? '')) &&
  LANG.test(String(to ?? '')) &&
  Array.isArray(ids) &&
  ids.length > 0 &&
  ids.length <= MAX_IDS &&
  ids.every((id) => Number.isInteger(id) && id > 0);

export const createTranslate = (env, context) => {
  const kept = new Map(); // chat:id:to -> { id, text, entities }
  const keep = (key, item) => {
    kept.delete(key);
    kept.set(key, item);
    if (kept.size > MAX_KEPT) {
      kept.delete(kept.keys().next().value);
    }
  };

  const ask = (c, { chat, ids, to }) =>
    runIn(env, `translate:${chat}:${ids.join(',')}:${to}`, () =>
      env.connection.withPeer(c.client, chat, (peer) =>
        c.client.invoke(
          new c.Api.messages.TranslateText({ peer, id: ids, toLang: to })
        )
      )
    );

  const translateMessages = async (body = {}) => {
    if (!valid(body)) {
      return { ok: false, supported: false };
    }
    const { chat, ids, to } = body;
    const keyOf = (id) => `${chat}:${id}:${to}`;
    const have = () => ids.map((id) => kept.get(keyOf(id))).filter(Boolean);
    const missing = ids.filter((id) => !kept.has(keyOf(id)));
    if (missing.length === 0) {
      return { ok: true, items: have() };
    }
    return connected(env, context.userClient, failure, async (c) => {
      const answer = await ask(c, { chat, ids: missing, to });
      const results = answer?.result ?? [];
      missing.forEach((id, i) => {
        if (results[i]) {
          keep(keyOf(id), {
            id,
            text: String(results[i].text ?? ''),
            entities: (results[i].entities ?? []).map(plainEntity),
          });
        }
      });
      return { ok: true, items: have() };
    });
  };

  return { translateMessages };
};

/**
 * A chat's auto-delete timer, and Saved Messages grouped by the chat they
 * came from, as Telegram Desktop has them (R-Y143; learned, never copied):
 *
 * - `setHistoryTtl({ chat, period })` — the chat's timer
 *   (messages.setHistoryTTL); `period` is 0 (off) or one of TTL_PERIODS
 *   in seconds; → `{ ok, period }`;
 * - `savedDialogs({ offsetDate, offsetId, offsetPeer, limit })` — the
 *   Saved Messages "as chats" list (messages.getSavedDialogs), newest
 *   first; → `{ ok, dialogs: [{ peer, name, kind, id, date, preview,
 *   media, pinned }], next, complete }` where `next` is the cursor for
 *   the following page (`{ offsetDate, offsetId, offsetPeer }`);
 * - `savedHistory({ chat, peer, before, limit })` — the messages saved
 *   from one chat (messages.getSavedHistory), oldest first, as the
 *   page's message links of the Saved Messages chat `chat`;
 * - `savedDelete({ peer })` — all of them deleted
 *   (messages.deleteSavedHistory, repeated while Telegram says more).
 * Telegram's errors become codes the page shows as text.
 */

import { runIn, connected, failureOf } from './telegram-stickers.js';

// Seconds Telegram takes for an auto-delete timer: off, a day, a week, a
// month (Desktop's list), and the longer ones its "Other" offers.
export const TTL_PERIODS = Object.freeze([
  0, 86_400, 604_800, 2_678_400, 7_776_000, 15_552_000, 31_536_000,
]);

const CODES = {
  TTL_PERIOD_INVALID: 'bad-period',
  CHAT_ADMIN_REQUIRED: 'not-admin',
  CHAT_NOT_MODIFIED: 'unchanged',
  PEER_ID_INVALID: 'no-access',
  CHAT_ID_INVALID: 'no-access',
  CHANNEL_PRIVATE: 'no-access',
  USER_BANNED_IN_CHANNEL: 'no-access',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);

export const SAVED_PAGE = 30;
const MAX_REPEATS = 20;
const CHAT = /^-?\d{1,20}$/;
const USER = /^\d{1,20}$/;
const BAD = { ok: false, error: 'bad request', code: 'failed' };
const text = (value) => String(value?.value ?? value ?? '');

// A peer's marked id: a person's, -group's, -100channel's.
const markedOf = (peer = {}) => {
  if (peer.userId !== undefined) {
    return text(peer.userId);
  }
  if (peer.chatId !== undefined) {
    return `-${text(peer.chatId)}`;
  }
  return peer.channelId === undefined ? '' : `-100${text(peer.channelId)}`;
};

const nameOf = (entity = {}) =>
  entity.title ||
  [entity.firstName, entity.lastName].filter(Boolean).join(' ') ||
  entity.username ||
  '';

const kindOf = (id) => {
  if (id.startsWith('-100')) {
    return 'channel';
  }
  return id.startsWith('-') ? 'group' : 'user';
};

const MEDIA = {
  MessageMediaPhoto: 'photo',
  MessageMediaDocument: 'file',
  MessageMediaGeo: 'location',
  MessageMediaGeoLive: 'location',
  MessageMediaContact: 'contact',
  MessageMediaPoll: 'poll',
};

const entityOf = (answer, id) => {
  const bare = id.replace(/^-100|^-/, '');
  const list = id.startsWith('-') ? answer.chats : answer.users;
  return (list ?? []).find((e) => text(e.id) === bare) ?? {};
};

// One saved dialog as the page reads it.
const shapeDialog = (answer, dialog) => {
  const peer = markedOf(dialog.peer);
  const top = (answer.messages ?? []).find(
    (m) => Number(m.id) === Number(dialog.topMessage)
  );
  return {
    peer,
    kind: kindOf(peer),
    name: nameOf(entityOf(answer, peer)),
    id: Number(dialog.topMessage) || 0,
    date: top?.date ? Number(top.date) * 1000 : 0,
    preview: String(top?.message ?? '').slice(0, 200),
    media: MEDIA[top?.media?.className] ?? (top?.media ? 'other' : null),
    pinned: Boolean(dialog.pinned),
  };
};

const int = (value) =>
  Number.isInteger(value) && value >= 0 && value <= 2 ** 31 - 1;

const validLimit = (limit) =>
  limit === undefined ||
  (Number.isInteger(limit) && limit >= 1 && limit <= 100);

const validDialogs = (r) =>
  (r.offsetDate === undefined || int(r.offsetDate)) &&
  (r.offsetId === undefined || int(r.offsetId)) &&
  (r.offsetPeer === undefined ||
    r.offsetPeer === '' ||
    CHAT.test(String(r.offsetPeer))) &&
  validLimit(r.limit);

const validHistory = (r) =>
  USER.test(String(r.chat ?? '')) &&
  CHAT.test(String(r.peer ?? '')) &&
  (r.before === undefined || (int(r.before) && r.before > 0)) &&
  validLimit(r.limit);

const usable = (m) => m && m.id !== undefined && m.className !== 'MessageEmpty';

// The cursor after a page: the last dialog, or null at the end.
const cursorOf = (dialogs, limit) => {
  const last = dialogs.at(-1);
  return dialogs.length < limit || !last
    ? null
    : {
        offsetDate: Math.floor(last.date / 1000),
        offsetId: last.id,
        offsetPeer: last.peer,
      };
};

/**
 * `env` is the account's; `userClient()` the user client or null; `tools`
 * brings `toLinks`; `apply(client, result)` runs Telegram's updates.
 */
export const createTtl = (env, { userClient, tools, apply }) => {
  const peerRun = (c, chat, use) =>
    env.connection.withPeer(c.client, String(chat), use);
  const doing = (key, use) =>
    connected(env, userClient, failure, (c) => runIn(env, key, () => use(c)));

  const setHistoryTtl = async ({ chat, period } = {}) =>
    !CHAT.test(String(chat ?? '')) || !TTL_PERIODS.includes(period)
      ? BAD
      : doing(`history-ttl:${chat}`, (c) =>
          peerRun(c, chat, async (peer) => {
            const result = await c.client.invoke(
              new c.Api.messages.SetHistoryTTL({ peer, period })
            );
            await apply?.(c.client, result);
            return { ok: true, period };
          })
        );

  const savedDialogs = async (request = {}) => {
    if (!validDialogs(request)) {
      return BAD;
    }
    const limit = request.limit ?? SAVED_PAGE;
    const offsetPeer = String(request.offsetPeer ?? '');
    return doing('saved-dialogs', async (c) => {
      const ask = (peer) =>
        c.client.invoke(
          new c.Api.messages.GetSavedDialogs({
            ...(offsetPeer ? { excludePinned: true } : {}),
            offsetDate: request.offsetDate ?? 0,
            offsetId: request.offsetId ?? 0,
            offsetPeer: peer,
            limit,
            hash: c.zero,
          })
        );
      const answer = offsetPeer
        ? await peerRun(c, offsetPeer, ask)
        : await ask(new c.Api.InputPeerEmpty());
      const dialogs = (answer?.dialogs ?? []).map((d) =>
        shapeDialog(answer, d)
      );
      return {
        ok: true,
        dialogs,
        complete: dialogs.length < limit,
        next: cursorOf(dialogs, limit),
      };
    });
  };

  const savedHistory = async (request = {}) => {
    if (!validHistory(request)) {
      return BAD;
    }
    const size = request.limit ?? SAVED_PAGE;
    return doing(`saved-history:${request.peer}`, (c) =>
      peerRun(c, request.peer, async (input) => {
        const answer = await c.client.invoke(
          new c.Api.messages.GetSavedHistory({
            peer: input,
            offsetId: request.before ?? 0,
            offsetDate: 0,
            addOffset: 0,
            limit: size,
            maxId: 0,
            minId: 0,
            hash: c.zero,
          })
        );
        const messages = [...(answer?.messages ?? [])]
          .filter(usable)
          .sort((a, b) => Number(a.id) - Number(b.id));
        return {
          ok: true,
          messages: tools.toLinks(
            { id: String(request.chat), isUser: true },
            messages
          ),
          complete: messages.length < size,
        };
      })
    );
  };

  const savedDelete = async ({ peer } = {}) =>
    !CHAT.test(String(peer ?? ''))
      ? BAD
      : doing(`saved-delete:${peer}`, (c) =>
          peerRun(c, peer, async (input) => {
            // Telegram deletes in parts: `offset` says how many are left.
            for (let n = 0; n < MAX_REPEATS; n += 1) {
              const part = await c.client.invoke(
                new c.Api.messages.DeleteSavedHistory({ peer: input, maxId: 0 })
              );
              if (!(Number(part?.offset) > 0)) {
                break;
              }
            }
            return { ok: true };
          })
        );

  return { setHistoryTtl, savedDialogs, savedHistory, savedDelete };
};

/**
 * Unread mentions (@) and reactions (♥) of a chat, as Telegram's apps
 * lead to them (R-Y55): the counts come with the chat list
 * (`unreadMentionsCount`, `unreadReactionsCount`, kept on the chat's
 * `read:` link); the buttons above "down" ask which messages they are
 * and go to the oldest, one per click.
 *
 *   marks({ chat, kind })        → { ids } oldest first, the messages
 *                                  written to the store so the chat can
 *                                  show them (messages.getUnreadMentions /
 *                                  getUnreadReactions);
 *   readMarks({ chat, kind, ids, last })
 *                                → the shown ones are read (their
 *                                  contents: messages.readMessageContents),
 *                                  and on the last one the chat's whole
 *                                  list (readMentions / readReactions).
 *
 * Asked through the account's queue at `view` priority: the user is
 * waiting. Only counts are logged.
 */

import { readLinkId } from './telegram-account-live.js';

export const MARK_KINDS = Object.freeze(['mentions', 'reactions']);
const MARK_PAGE = 100;
const FIELD = { mentions: 'unreadMentions', reactions: 'unreadReactions' };

const isChannel = (chat) => String(chat).startsWith('-100');

const cleanIds = (ids) =>
  [...new Set((ids ?? []).map(Number))]
    .filter((id) => Number.isInteger(id) && id > 0)
    .slice(0, MARK_PAGE);

/**
 * `env`: the account's (store, connection, queue, importer, catchUp,
 * log); `userClient()` the connected user client or null; `write(chat,
 * messages)` stores GramJS messages as links.
 */
export const createUnreadMarks = (env, { userClient, write }) => {
  const { store } = env;

  // The chat's count, lowered by what was read (the next chat list
  // brings Telegram's own count again).
  const lower = async (chat, kind, by, last) => {
    const link = await store.get(readLinkId(chat));
    if (!link) {
      return;
    }
    const field = FIELD[kind];
    const left = last ? 0 : Math.max(0, Number(link[field] ?? 0) - by);
    if (left !== Number(link[field] ?? 0)) {
      await store.put({ ...link, [field]: left });
    }
  };

  const marks = async ({ chat, kind } = {}) => {
    const client = chat && FIELD[kind] ? await userClient() : null;
    if (!client) {
      return { ok: false, supported: false, ids: [] };
    }
    const { Api } = await env.importer();
    const target = String(chat);
    const Request =
      kind === 'mentions'
        ? Api.messages.GetUnreadMentions
        : Api.messages.GetUnreadReactions;
    const started = Date.now();
    const result = await env.queue.run(`marks:${kind}:${target}`, 'view', () =>
      env.connection.withPeer(client, target, (peer) =>
        client.invoke(
          new Request({
            peer,
            offsetId: 0,
            addOffset: 0,
            limit: MARK_PAGE,
            maxId: 0,
            minId: 0,
          })
        )
      )
    );
    const messages = (result?.messages ?? []).filter(
      (m) => m && m.id !== undefined && m.className !== 'MessageEmpty'
    );
    await write(target, messages);
    const ids = messages.map((m) => Number(m.id)).sort((a, b) => a - b);
    env.log?.({
      event: 'telegram_unread_marks',
      kind,
      ids: ids.length,
      count: Number(result?.count ?? ids.length),
      duration_ms: Date.now() - started,
    });
    return { ok: true, ids, count: Number(result?.count ?? ids.length) };
  };

  const readContents = async (client, Api, target, ids) => {
    if (isChannel(target)) {
      await env.connection.withPeer(client, target, (channel) =>
        client.invoke(
          new Api.channels.ReadMessageContents({ channel, id: ids })
        )
      );
      return;
    }
    const affected = await client.invoke(
      new Api.messages.ReadMessageContents({ id: ids })
    );
    env.catchUp?.observeResult({
      className: 'UpdateReadMessagesContents',
      messages: ids,
      pts: affected?.pts,
      ptsCount: affected?.ptsCount,
    });
  };

  const readAll = (client, Api, target, kind) =>
    env.connection.withPeer(client, target, (peer) =>
      client.invoke(
        kind === 'mentions'
          ? new Api.messages.ReadMentions({ peer })
          : new Api.messages.ReadReactions({ peer })
      )
    );

  const readMarks = async ({ chat, kind, ids, last = false } = {}) => {
    const wanted = cleanIds(ids);
    const client =
      chat && FIELD[kind] && (wanted.length > 0 || last)
        ? await userClient()
        : null;
    if (!client) {
      return { ok: false, supported: false };
    }
    const { Api } = await env.importer();
    const target = String(chat);
    await env.queue.run(`marks-read:${kind}:${target}`, 'view', async () => {
      if (wanted.length > 0) {
        await readContents(client, Api, target, wanted);
      }
      if (last) {
        await readAll(client, Api, target, kind);
      }
    });
    await lower(target, kind, wanted.length, last);
    return { ok: true, read: wanted.length, last: Boolean(last) };
  };

  return { marks, readMarks };
};

/**
 * Live Telegram updates (MTProto), as plain effects.
 *
 * GramJS hands a raw-update handler one update at a time (containers are
 * already unpacked, each update carrying `_entities`: the users and chats
 * it mentions, keyed by their marked peer id). This module turns one
 * update into what the app should do about it, without touching the
 * store, so it is tested with plain objects:
 *
 *   { kind: 'message', chat, message, entities }  a new message
 *   { kind: 'edit', chat, message, entities }     an edited message
 *   { kind: 'delete', chat, ids }                 deleted (chat null: a
 *                                                 user/basic-group delete,
 *                                                 whose ids are account-wide)
 *   { kind: 'read', chat, maxId }                 the other side read our
 *                                                 messages up to maxId
 *   { kind: 'read-inbox', chat, maxId, stillUnread } we read theirs up to
 *                                                 maxId (on any device)
 *   { kind: 'draft', chat, text, date }           the chat's cloud draft
 *                                                 changed (another device)
 *   { kind: 'typing', chat, user, typing }        someone types (or stops)
 *   { kind: 'poll', chat, id, pollId, poll, results }
 *                                                 a poll's results moved
 *   { kind: 'transcript', chat, id, transcriptionId, text, pending }
 *                                                 a voice or video note's
 *                                                 transcription moved
 *                                                 (R-Y175)
 *   { kind: 'requests', chat, pending, recent, entities }
 *                                                 people waiting to join the
 *                                                 chat, how many and the
 *                                                 latest ids (R-Y161)
 *
 *   { kind: 'ephemeral', chat, message, entities }
 *                                                 a bot's message for this
 *                                                 user only, new or edited
 *                                                 (layer 232, R-Y223)
 *   { kind: 'ephemeral-delete', chat, ids }       such messages deleted
 *
 *   { kind: 'group-call', chat, id, call }        a voice chat / live stream
 *                                                 started, changed or ended
 *                                                 (call null; chat may be
 *                                                 null: found by id, R-Y188)
 *   { kind: 'group-call-people', id }             its participants changed
 *   { kind: 'phone-call', phoneCall, entities }   a private call moved: the
 *                                                 raw PhoneCall for the call
 *                                                 machine (R-Y196)
 *
 * Chat ids are GramJS "marked" peer ids, the same ones dialogs use: a
 * user's id, `-<id>` for a basic group, `-100<id>` for a channel or
 * supergroup.
 */

import { rawMessage } from './telegram-history.js';
import { shapeCall } from './telegram-voice-chat.js';

const text = (value) =>
  value === null || value === undefined ? null : String(value.value ?? value);

/** The marked chat id of a Peer (PeerUser / PeerChat / PeerChannel). */
export const peerChatId = (peer) => {
  if (!peer) {
    return null;
  }
  if (peer.userId !== undefined) {
    return text(peer.userId);
  }
  if (peer.chatId !== undefined) {
    return `-${text(peer.chatId)}`;
  }
  if (peer.channelId !== undefined) {
    return `-100${text(peer.channelId)}`;
  }
  return null;
};

/**
 * Who wrote a message. GramJS fills `senderId` only for the messages it
 * builds itself (`getMessages`); a raw one — from an update or a
 * channel's difference — names its author in `fromId` only: a person,
 * or a channel posting. Neither: the private chat's other side (null).
 */
export const messageSenderId = (message) =>
  text(message?.senderId) ?? peerChatId(message?.fromId);

const NEW_MESSAGE = new Set(['UpdateNewMessage', 'UpdateNewChannelMessage']);
const EDIT_MESSAGE = new Set(['UpdateEditMessage', 'UpdateEditChannelMessage']);
const TYPING = new Set([
  'UpdateUserTyping',
  'UpdateChatUserTyping',
  'UpdateChannelUserTyping',
]);

// A chat's message, service messages (joins, pins, calls) included:
// they are stored with their action and shown as a line of their own.
const isChatMessage = (message) =>
  Boolean(message) && message.className !== 'MessageEmpty';

// The short forms Telegram uses for a private / basic-group message
// carry the fields of a message without the Message object around them.
const shortMessage = (update) => {
  const isUser = update.className === 'UpdateShortMessage';
  const chat = isUser ? text(update.userId) : `-${text(update.chatId)}`;
  const message = {
    id: update.id,
    message: update.message,
    date: update.date,
    out: Boolean(update.out),
    senderId: isUser
      ? update.out
        ? null
        : update.userId
      : (update.fromId ?? null),
    replyTo: update.replyTo,
    media: update.media,
    editDate: null,
  };
  return { kind: 'message', chat, message, entities: update._entities };
};

const typingEffect = (update) => {
  const typing = update.action?.className !== 'SendMessageCancelAction';
  if (update.className === 'UpdateUserTyping') {
    const user = text(update.userId);
    return { kind: 'typing', chat: user, user, typing };
  }
  const chat =
    update.className === 'UpdateChatUserTyping'
      ? `-${text(update.chatId)}`
      : `-100${text(update.channelId)}`;
  const user = peerChatId(update.fromId) ?? text(update.userId);
  return { kind: 'typing', chat, user, typing };
};

/**
 * GramJS's connection state, which it hands to update handlers as an
 * `UpdateConnectionState` (no TL `className`): 1 connected, 0 broken,
 * -1 disconnected; null for anything else.
 */
export const connectionStateOf = (update) =>
  update && !update.className && [-1, 0, 1].includes(update.state)
    ? update.state
    : null;

const ids = (update) => (update.messages ?? []).map(Number);
const channelOf = (update) => `-100${text(update.channelId)}`;

// Deletions and read receipts: one line each.
// How many Telegram says are still unread after a read, when it says.
const stillUnreadOf = (u) =>
  Number.isFinite(u.stillUnreadCount)
    ? { stillUnread: u.stillUnreadCount }
    : {};

// An ephemeral message's chat: its peer, else (a bot's private chat) the
// bot that wrote it.
const ephemeralEffect = (u) => ({
  kind: 'ephemeral',
  chat: peerChatId(u.message?.peerId) ?? peerChatId(u.message?.fromId),
  message: u.message,
  entities: u._entities,
});

const SIMPLE_EFFECTS = {
  // Ephemeral messages (R-Y223): shown to one user, never in the history.
  UpdateNewEphemeralMessage: ephemeralEffect,
  UpdateEditEphemeralMessage: ephemeralEffect,
  UpdateDeleteEphemeralMessages: (u) => ({
    kind: 'ephemeral-delete',
    chat: peerChatId(u.peer),
    ids: ids({ messages: u.ids }),
  }),
  // A poll's results moved (anyone's vote, ours too), R-Y74: which poll
  // (by message when Telegram says, else by poll id), its new results
  // and, when it changed (closed), the poll.
  UpdateMessagePoll: (u) => ({
    kind: 'poll',
    chat: u.peer ? peerChatId(u.peer) : null,
    id: Number(u.msgId) || null,
    pollId: u.pollId === undefined ? null : String(u.pollId),
    poll: u.poll ? rawMessage(u.poll) : null,
    results: rawMessage(u.results ?? null),
  }),
  // A voice or video note's transcription, partial or final (R-Y175).
  UpdateTranscribedAudio: (u) => ({
    kind: 'transcript',
    chat: peerChatId(u.peer),
    id: Number(u.msgId) || null,
    transcriptionId: String(u.transcriptionId),
    text: String(u.text ?? ''),
    pending: Boolean(u.pending),
  }),
  UpdateDeleteMessages: (u) => ({ kind: 'delete', chat: null, ids: ids(u) }),
  UpdateDeleteChannelMessages: (u) => ({
    kind: 'delete',
    chat: channelOf(u),
    ids: ids(u),
  }),
  UpdateReadHistoryOutbox: (u) => ({
    kind: 'read',
    chat: peerChatId(u.peer),
    maxId: Number(u.maxId),
  }),
  UpdateReadChannelOutbox: (u) => ({
    kind: 'read',
    chat: channelOf(u),
    maxId: Number(u.maxId),
  }),
  UpdateReadHistoryInbox: (u) => ({
    kind: 'read-inbox',
    chat: peerChatId(u.peer),
    maxId: Number(u.maxId),
    ...stillUnreadOf(u),
  }),
  UpdateReadChannelInbox: (u) => ({
    kind: 'read-inbox',
    chat: channelOf(u),
    maxId: Number(u.maxId),
    ...stillUnreadOf(u),
  }),
  // Pinned or unpinned: the chat's pinned bar follows.
  UpdatePinnedMessages: (u) => ({
    kind: 'pin',
    chat: peerChatId(u.peer),
    ids: ids(u),
    pinned: Boolean(u.pinned),
  }),
  UpdatePinnedChannelMessages: (u) => ({
    kind: 'pin',
    chat: channelOf(u),
    ids: ids(u),
    pinned: Boolean(u.pinned),
  }),
  // A voice chat or live stream began, changed or ended (R-Y188).
  UpdateGroupCall: (u) => ({
    kind: 'group-call',
    chat: peerChatId(u.peer),
    id: text(u.call?.id),
    call: shapeCall(u.call),
  }),
  // A private call's state moved (R-Y196); the machine reads the raw
  // PhoneCall. Its signalling data is not used (no media in a browser).
  UpdatePhoneCall: (u) =>
    u.phoneCall
      ? { kind: 'phone-call', phoneCall: u.phoneCall, entities: u._entities }
      : null,
  UpdateGroupCallParticipants: (u) => ({
    kind: 'group-call-people',
    id: text(u.call?.id),
  }),
  // The join requests waiting changed (R-Y161): their count and the
  // latest requesters (the "N requested to join" bar follows).
  UpdatePendingJoinRequests: (u) => ({
    kind: 'requests',
    chat: peerChatId(u.peer),
    pending: Math.max(0, Number(u.requestsPending) || 0),
    recent: (u.recentRequesters ?? []).map((id) => text(id)),
    entities: u._entities,
  }),
  // How the chat is listed: muted, pinned, archived (R-Y68).
  UpdateNotifySettings: (u) =>
    u.peer?.className === 'NotifyPeer'
      ? {
          kind: 'listing',
          chat: peerChatId(u.peer.peer),
          muteUntil: Number(u.notifySettings?.muteUntil ?? 0) || 0,
        }
      : null,
  UpdateDialogPinned: (u) =>
    u.peer?.className === 'DialogPeer'
      ? {
          kind: 'listing',
          chat: peerChatId(u.peer.peer),
          pinned: Boolean(u.pinned),
          folder: Number(u.folderId ?? 0) === 1 ? 1 : 0,
        }
      : null,
  UpdatePinnedDialogs: (u) =>
    Array.isArray(u.order)
      ? {
          kind: 'pinned-order',
          folder: Number(u.folderId ?? 0) === 1 ? 1 : 0,
          chats: u.order
            .filter((p) => p?.className === 'DialogPeer')
            .map((p) => peerChatId(p.peer))
            .filter(Boolean),
        }
      : null,
  UpdateFolderPeers: (u) => ({
    kind: 'folders',
    peers: (u.folderPeers ?? [])
      .map((f) => ({
        chat: peerChatId(f.peer),
        folder: Number(f.folderId) === 1 ? 1 : 0,
      }))
      .filter((f) => f.chat),
  }),
  // The folders changed on another device (R-Y172): one folder, all of
  // them, or their order. The page asks Telegram for the list again.
  UpdateDialogFilter: (u) => ({
    kind: 'folders-live',
    change: 'filter',
    id: Number(u.id) || 0,
  }),
  UpdateDialogFilters: () => ({ kind: 'folders-live', change: 'all', id: 0 }),
  UpdateDialogFilterOrder: (u) => ({
    kind: 'folders-live',
    change: 'order',
    id: 0,
    order: (u.order ?? []).map(Number),
  }),
  // Marked unread, or the mark taken off, on any device (R-Y97).
  UpdateDialogUnreadMark: (u) =>
    u.peer?.className === 'DialogPeer'
      ? {
          kind: 'listing',
          chat: peerChatId(u.peer.peer),
          unreadMark: Boolean(u.unread),
        }
      : null,
  // A forum topic's draft (topMsgId) is not the chat's own.
  UpdateDraftMessage: (u) =>
    u.topMsgId
      ? null
      : {
          kind: 'draft',
          chat: peerChatId(u.peer),
          text: u.draft?.message ?? '',
          date: Number(u.draft?.date) || null,
        },
};

/** What one raw update means for the app, or null when nothing. */
export const updateEffect = (update) => {
  const name = update?.className;
  if (!name) {
    return null;
  }
  if (NEW_MESSAGE.has(name) || EDIT_MESSAGE.has(name)) {
    const message = update.message;
    if (!isChatMessage(message)) {
      return null;
    }
    return {
      kind: NEW_MESSAGE.has(name) ? 'message' : 'edit',
      chat: peerChatId(message.peerId),
      message,
      entities: update._entities,
    };
  }
  if (name === 'UpdateShortMessage' || name === 'UpdateShortChatMessage') {
    return shortMessage(update);
  }
  const simple = SIMPLE_EFFECTS[name];
  if (simple) {
    return simple(update);
  }
  if (TYPING.has(name)) {
    return typingEffect(update);
  }
  return null;
};

/** The kind of chat a marked id names, for chat links. */
export const chatKindOf = (chat) => {
  const id = String(chat ?? '');
  if (id.startsWith('-100')) {
    return 'channel';
  }
  return id.startsWith('-') ? 'group' : 'user';
};

/**
 * Sending files and photos, as Telegram's apps do it (R-Y99; Telegram
 * Desktop's "Send as photo / as files", learned, never copied).
 *
 * Two steps, so a group of photos can go as one album:
 *
 * - `receiveUpload(stream, { name })` keeps one file the page uploads
 *   in a temporary folder of its own and answers `{ token, name, size }`;
 *   a file larger than Telegram takes is refused while it streams.
 * - `sendFiles({ chat, tokens, caption, asPhoto, group, replyTo })`
 *   sends them: pictures as photos (compressed, shown in the chat) when
 *   `asPhoto`, else everything as files; with `group`, photos together go
 *   as albums of up to ten, files together likewise — as Desktop groups
 *   them; the caption goes with the first. A picture Telegram will not
 *   take as a photo (too big, too long) goes as a file instead, as
 *   Desktop does. What Telegram answers is stored at once; the files are
 *   removed after.
 *
 * "Send without sound" and "Schedule message" go with every batch
 * (R-Y102); scheduled ones are not stored — Telegram holds them. A
 * message `effect` (R-Y161, a decimal string) goes with the first batch
 * only (messages.sendMedia / sendMultiMedia carry it).
 *
 * Captions are formatted as messages are (R-Y101,
 * ./telegram-format.js): GramJS is handed the parsed text and entities
 * as its parse mode, so an album's caption keeps them too.
 *
 * A voice message (R-Y108): `sendVoice({ chat, token, duration, waveform,
 * replyTo })` sends one upload — Ogg Opus, as the page recorded it — as
 * Telegram's voice note: its length in seconds and its waveform (100
 * values 0..31, packed five bits each, as Telegram keeps it).
 *
 * A round video (R-Y150): `sendRound({ chat, token, duration, size,
 * replyTo })` sends one upload (WebM or MP4) as a video note
 * (./telegram-round.js).
 */

import { randomBytes } from 'node:crypto';
import { createWriteStream } from 'node:fs';
import { mkdtemp, rm } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { Transform } from 'node:stream';
import { pipeline } from 'node:stream/promises';

import { apiEntities, parseFormatted } from './telegram-format.js';
import { longOf, sendError, withEffect } from './telegram-send.js';
import { withSendAs } from './telegram-send-as-client.js';
import { roundFileOf, roundOptions } from './telegram-round.js';

// Telegram takes files up to 2 GB from an account (4 GB with Premium).
export const MAX_UPLOAD = 2000 * 1024 * 1024;
export const MAX_FILES = 100;
export const ALBUM_SIZE = 10;
export const MAX_CAPTION = 4096;
// A voice message: an hour at most, a waveform of up to 100 values 0..31.
export const MAX_VOICE_SECONDS = 3600;
export const WAVEFORM_SIZE = 100;
const KEEP_MS = 60 * 60 * 1000;

const IMAGE = /\.(jpe?g|png|gif|webp|bmp|heic|heif)$/i;
// GIFs and WebP go as animations and stickers' kin, not as photos.
const PHOTO = /\.(jpe?g|png|bmp|heic|heif)$/i;
const NOT_A_PHOTO =
  /PHOTO_INVALID_DIMENSIONS|PHOTO_SAVE_FILE_INVALID|IMAGE_PROCESS_FAILED|PHOTO_EXT_INVALID|PHOTO_CROP_SIZE_SMALL/;

export const isImageName = (name) => IMAGE.test(String(name ?? ''));

/** A file's name as given, made safe: no folders, no control characters. */
export const safeName = (name) => {
  const base = path.basename(String(name ?? '').replace(/\\/g, '/'));
  // eslint-disable-next-line no-control-regex
  const clean = base.replace(/[\u0000-\u001f\u007f]/g, '').trim();
  return clean && clean !== '.' && clean !== '..'
    ? clean.slice(0, 200)
    : 'file';
};

const tooLarge = () =>
  Object.assign(new Error('file too large'), { code: 'too-large' });

// Counts what passes and stops past `max`.
const limiter = (max) => {
  let seen = 0;
  return new Transform({
    transform(chunk, _encoding, done) {
      seen += chunk.length;
      done(seen > max ? tooLarge() : null, chunk);
    },
  });
};

/**
 * Batches as Desktop sends them: with `group`, consecutive photos (or
 * consecutive files) together, ten at most; else one by one.
 */
export const batchesOf = (files, { asPhoto, group }) => {
  const batches = [];
  for (const file of files) {
    const photo = Boolean(asPhoto) && PHOTO.test(file.name);
    const last = batches.at(-1);
    if (
      group &&
      last &&
      last.photo === photo &&
      last.files.length < ALBUM_SIZE
    ) {
      last.files.push(file);
    } else {
      batches.push({ photo, files: [file] });
    }
  }
  return batches;
};

// GramJS's parse mode for a caption: ours (the markdown made entities),
// or none when it has no formatting — sent as typed.
const captionMode = (caption, Api) => {
  const formatted = parseFormatted(caption);
  if (!caption || formatted.entities.length === 0) {
    return false;
  }
  return {
    parse: () => [formatted.text, apiEntities(Api, formatted.entities)],
    unparse: (text) => text,
  };
};

/**
 * A waveform as Telegram keeps it: each value 0..31 in five bits, the
 * first in the lowest bits of the first byte (as the apps read it back:
 * ../web/message-parts.js `decodeWaveform`).
 */
export const packWaveform = (values) => {
  const list = (Array.isArray(values) ? values : []).slice(0, WAVEFORM_SIZE);
  const bytes = new Uint8Array(Math.ceil((list.length * 5) / 8));
  list.forEach((value, i) => {
    const v = Math.max(0, Math.min(31, Math.round(Number(value) || 0)));
    const bit = i * 5;
    const at = bit >> 3;
    const pair = v << (bit & 7);
    bytes[at] |= pair & 0xff;
    if (pair > 0xff) {
      bytes[at + 1] |= pair >> 8;
    }
  });
  return Buffer.from(bytes);
};

// A voice's length (whole seconds, one at least), waveform and when.
const voiceOptions = ({
  duration = 0,
  waveform = [],
  replyTo = null,
  silent = false,
  scheduleDate = null,
}) => ({
  seconds: Math.max(
    1,
    Math.min(MAX_VOICE_SECONDS, Math.round(Number(duration) || 0))
  ),
  waveform: packWaveform(waveform),
  extra: {
    ...(replyTo ? { replyTo } : {}),
    ...(silent ? { silent: true } : {}),
    ...(scheduleDate ? { scheduleDate } : {}),
  },
});

// GramJS's sendFile options for a voice note: Ogg Opus, its length and
// waveform as Telegram's audio attribute says them.
const voiceFileOf = (upload, options) => (telegram) => {
  const CustomFile =
    telegram.client?.uploads?.CustomFile ?? telegram.CustomFile;
  return {
    file: new CustomFile('voice.ogg', upload.size, upload.path),
    voiceNote: true,
    forceDocument: false,
    mimeType: 'audio/ogg',
    attributes: [
      new telegram.Api.DocumentAttributeAudio({
        voice: true,
        duration: options.seconds,
        waveform: options.waveform,
      }),
    ],
    clearDraft: true,
    ...options.extra,
  };
};

const messagesOf = (sent) =>
  (Array.isArray(sent) ? sent : [sent]).filter((m) => m && m.id !== undefined);

// The voice sent; what Telegram answers stored (a scheduled one is
// Telegram's to hold, R-Y102).
const voiceSent = async ({ env, client, dialogOf, tools }, target, fileOf) => {
  const telegram = await env.importer();
  const options = fileOf(telegram);
  const sent = await env.connection.withPeer(client, target, (peer) =>
    client.sendFile(peer, options)
  );
  const messages = messagesOf(sent);
  if (options.scheduleDate) {
    env.actions?.scheduledChanged?.(target);
    return { ok: true, chat: target, ids: [], scheduled: true };
  }
  await tools.writeChanged(
    env.store,
    tools.toLinks(await dialogOf(target), messages)
  );
  return { ok: true, chat: target, ids: messages.map((m) => Number(m.id)) };
};

// One batch through GramJS's sendFile; a photo Telegram does not take
// as one goes as a file.
const sendBatch = async ({ client, Api, CustomFile, peer, batch, options }) => {
  const files = batch.files.map((f) => new CustomFile(f.name, f.size, f.path));
  const send = (photo) =>
    client.sendFile(peer, {
      file: files.length === 1 ? files[0] : files,
      caption: options.caption,
      forceDocument: !photo,
      parseMode: captionMode(options.caption, Api),
      clearDraft: true,
      ...(options.replyTo ? { replyTo: options.replyTo } : {}),
      ...(options.silent ? { silent: true } : {}),
      ...(options.scheduleDate ? { scheduleDate: options.scheduleDate } : {}),
      workers: 4,
    });
  try {
    return await send(batch.photo);
  } catch (error) {
    if (
      batch.photo &&
      NOT_A_PHOTO.test(String(error?.errorMessage ?? error?.message))
    ) {
      return send(false);
    }
    throw error;
  }
};

// One recorded upload sent as a single message: a voice note (R-Y108)
// or a round video (R-Y150).
const singleSender =
  ({ env, userClient, dialogOf, tools, uploads, drop }, fileOf, optionsOf) =>
  async (args = {}) => {
    const { chat, token, sendAs = null, allowPaidStars, ...rest } = args;
    const upload = uploads.get(token);
    const client = chat && upload?.path ? await userClient() : null;
    if (!client) {
      await drop(token);
      return { ok: false, supported: Boolean(chat && upload) };
    }
    try {
      const sender = await withSendAs(env, client, sendAs, allowPaidStars);
      return await voiceSent(
        { env, client: sender, dialogOf, tools },
        String(chat),
        fileOf(upload, optionsOf(rest))
      );
    } catch (error) {
      throw sendError(error);
    } finally {
      await drop(token);
    }
  };

// Scheduled ones: the chat's list is asked afresh (R-Y102).
const scheduledNote = (env, scheduleDate, chat) => {
  if (!scheduleDate) {
    return {};
  }
  env.actions?.scheduledChanged?.(chat);
  return { scheduled: true };
};

/**
 * `env` is the account's; `userClient()` the user client or null;
 * `dialogOf(chat)` the chat as listed; `tools` its `toLinks` and
 * `writeChanged`. `importer()` gives GramJS (its uploads' `CustomFile`).
 */
export const createFileSender = (
  env,
  { userClient, dialogOf, tools },
  { tmp = os.tmpdir(), now = () => Date.now() } = {}
) => {
  const uploads = new Map();

  const drop = async (token) => {
    const entry = uploads.get(token);
    uploads.delete(token);
    if (entry) {
      await rm(entry.dir, { recursive: true, force: true }).catch(() => {});
    }
  };

  // Uploads never sent (the page closed) go after an hour.
  const sweep = () =>
    Promise.all(
      [...uploads]
        .filter(([, entry]) => now() - entry.at > KEEP_MS)
        .map(([token]) => drop(token))
    );

  const receiveUpload = async (stream, { name, max = MAX_UPLOAD } = {}) => {
    await sweep();
    const dir = await mkdtemp(path.join(tmp, 'ms-upload-'));
    const file = path.join(dir, 'data');
    let size = 0;
    const counter = new Transform({
      transform(chunk, _encoding, done) {
        size += chunk.length;
        done(null, chunk);
      },
    });
    try {
      await pipeline(stream, limiter(max), counter, createWriteStream(file));
    } catch (error) {
      await rm(dir, { recursive: true, force: true }).catch(() => {});
      throw error;
    }
    const token = randomBytes(16).toString('hex');
    uploads.set(token, {
      dir,
      path: file,
      name: safeName(name),
      size,
      at: now(),
    });
    return { ok: true, token, name: safeName(name), size };
  };

  // Batch by batch, each stored as Telegram answers it; the caption and
  // the reply go with the first.
  const sendAll = async ({
    client,
    target,
    batches,
    caption,
    replyTo,
    when,
  }) => {
    const telegram = await env.importer();
    const CustomFile =
      telegram.client?.uploads?.CustomFile ?? telegram.CustomFile;
    const ids = [];
    const effect = longOf(telegram.helpers, when.effect);
    for (const [index, batch] of batches.entries()) {
      const first = index === 0;
      const sent = await env.connection.withPeer(client, target, (peer) =>
        sendBatch({
          client: first ? withEffect(client, effect) : client,
          Api: telegram.Api,
          CustomFile,
          peer,
          batch,
          options: {
            caption: first ? caption : '',
            replyTo: first ? replyTo : null,
            silent: when.silent,
            scheduleDate: when.scheduleDate,
          },
        })
      );
      const messages = messagesOf(sent);
      // Scheduled ones are Telegram's to hold, not the chat's (R-Y102).
      if (!when.scheduleDate) {
        await tools.writeChanged(
          env.store,
          tools.toLinks(await dialogOf(target), messages)
        );
      }
      ids.push(...messages.map((m) => Number(m.id)));
    }
    return ids;
  };

  const clientFor = async (chat, files) =>
    chat && files.length > 0 && files.every((f) => f.path)
      ? userClient()
      : null;

  const sendFiles = async ({
    chat,
    tokens = [],
    caption = '',
    asPhoto = true,
    group = true,
    replyTo = null,
    silent = false,
    scheduleDate = null,
    sendAs = null,
    allowPaidStars,
    effect = null,
  } = {}) => {
    const files = tokens.map((token) => ({ token, ...uploads.get(token) }));
    const client = await clientFor(chat, files);
    if (!client) {
      await Promise.all(tokens.map(drop));
      return { ok: false, supported: Boolean(chat && files.length > 0) };
    }
    const target = String(chat);
    try {
      const ids = await sendAll({
        client: await withSendAs(env, client, sendAs, allowPaidStars),
        target,
        batches: batchesOf(files, { asPhoto, group }),
        caption: String(caption ?? '').slice(0, MAX_CAPTION),
        replyTo,
        when: { silent, scheduleDate, effect },
      });
      return {
        ok: true,
        chat: target,
        ids,
        ...scheduledNote(env, scheduleDate, target),
      };
    } catch (error) {
      throw sendError(error);
    } finally {
      await Promise.all(tokens.map(drop));
    }
  };

  const sender = { env, userClient, dialogOf, tools, uploads, drop };
  const sendVoice = singleSender(sender, voiceFileOf, voiceOptions);
  const sendRound = singleSender(sender, roundFileOf, roundOptions);

  // `held`: the uploads, for an action that sends one itself (R-Y129).
  return {
    receiveUpload,
    sendFiles,
    sendVoice,
    sendRound,
    held: { uploads, drop },
  };
};

/**
 * Several usernames, as Telegram Desktop's profile and channel settings
 * show them (R-Y170; learned, never copied). A user or a channel may hold
 * collectible usernames besides the one edited by hand; each is a Username
 * (`editable`, `active`). `usernamesOf(list)` is that list as the page
 * keeps it. The two writes, both only on a click:
 * - `toggleUsername({ username, active, chat? })` — activate or deactivate
 *   one (account.toggleUsername; for a channel the user owns,
 *   channels.toggleUsername);
 * - `reorderUsernames({ order, chat? })` — the active usernames in a new
 *   order (account.reorderUsernames / channels.reorderUsernames).
 * The editable username is changed by the profile and chat editors.
 */

import { connected, failureOf, runIn } from './telegram-stickers.js';

const CODES = {
  USERNAME_INVALID: 'username-invalid',
  USERNAMES_ACTIVE_TOO_MUCH: 'too-many',
  USERNAME_PURCHASE_AVAILABLE: 'username-invalid',
  CHAT_ADMIN_REQUIRED: 'no-access',
  CHANNEL_INVALID: 'no-access',
  CHANNEL_PRIVATE: 'no-access',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);

export const NAME = /^[A-Za-z0-9_]{1,32}$/;
export const CHANNEL = /^-100\d{1,20}$/;
export const MAX_NAMES = 100;

/** A Username list as `[{ username, editable, active }]`. */
export const usernamesOf = (list) =>
  (Array.isArray(list) ? list : [])
    .filter((u) => u && typeof u.username === 'string' && u.username)
    .map((u) => ({
      username: u.username,
      editable: Boolean(u.editable),
      active: Boolean(u.active),
    }));

/**
 * The usernames and phone number of a user or channel that Fragment sells
 * (R-Y194): the active usernames that are not the editable one, and a
 * phone number from the anonymous "+888" range. `{ collectible }` for the
 * chat info, or nothing when the profile has none.
 */
export const collectibleOf = (entity) => {
  const usernames = usernamesOf(entity?.usernames)
    .filter((u) => u.active && !u.editable)
    .map((u) => u.username);
  const digits = String(entity?.phone ?? '').replace(/\D/g, '');
  const phone = /^888\d{4,}$/.test(digits) ? `+${digits}` : null;
  return usernames.length > 0 || phone
    ? { collectible: { usernames, ...(phone ? { phone } : {}) } }
    : {};
};

const bad = (code) => ({ ok: false, error: code, code });

// Telegram saying nothing changed is no failure.
const forgiving = (error) =>
  String(error?.errorMessage ?? error?.message ?? '').includes('_NOT_MODIFIED')
    ? { ok: true }
    : failure(error);

/** Whether `chat` is absent or a channel's id. */
const targetOk = (chat) =>
  chat === undefined || chat === null || CHANNEL.test(String(chat));

/** Whether `order` is 1 to 100 distinct usernames. */
export const validOrder = (order) =>
  Array.isArray(order) &&
  order.length >= 1 &&
  order.length <= MAX_NAMES &&
  order.every((n) => typeof n === 'string' && NAME.test(n)) &&
  new Set(order).size === order.length;

export const createUsernames = (env, { userClient }) => {
  // account.* for the user, channels.* for the channel given.
  const send = (c, chat, key, mine, theirs) =>
    runIn(env, key, () =>
      chat
        ? env.connection.withPeer(c.client, String(chat), (channel) =>
            c.client.invoke(theirs(channel))
          )
        : c.client.invoke(mine())
    );

  const toggleUsername = async ({ username, active, chat } = {}) => {
    if (
      !NAME.test(String(username ?? '')) ||
      typeof active !== 'boolean' ||
      !targetOk(chat)
    ) {
      return bad('username-invalid');
    }
    return connected(env, userClient, forgiving, async (c) => {
      await send(
        c,
        chat,
        `usernames:toggle:${chat ?? 'me'}`,
        () => new c.Api.account.ToggleUsername({ username, active }),
        (channel) =>
          new c.Api.channels.ToggleUsername({ channel, username, active })
      );
      return { ok: true };
    });
  };

  const reorderUsernames = async ({ order, chat } = {}) => {
    if (!validOrder(order) || !targetOk(chat)) {
      return bad('username-invalid');
    }
    return connected(env, userClient, forgiving, async (c) => {
      await send(
        c,
        chat,
        `usernames:reorder:${chat ?? 'me'}`,
        () => new c.Api.account.ReorderUsernames({ order }),
        (channel) => new c.Api.channels.ReorderUsernames({ channel, order })
      );
      return { ok: true };
    });
  };

  return { toggleUsername, reorderUsernames };
};

/**
 * Live counters under channel posts, as Telegram Desktop keeps them
 * (R-Y182; learned, never copied): a post that is on screen is marked
 * viewed (the count goes up once), and the counters of the posts shown
 * are asked again from time to time.
 * - `messageViews({ chat, ids, increment })` — messages.getMessagesViews
 *   for up to 100 posts → `{ ok, items: [{ id, views, forwards, replies }] }`
 *   (a counter Telegram does not send is left out of the item). With
 *   `increment: true` the posts count as seen by the user; the page does
 *   that once per post and session.
 * Errors become codes.
 */

import { connected, runIn, failureOf } from './telegram-stickers.js';

const failure = failureOf({
  FLOOD_WAIT: 'flood',
  CHANNEL_PRIVATE: 'no-access',
  CHAT_ID_INVALID: 'no-access',
  MSG_ID_INVALID: 'not-found',
});
const CHAT = /^-?\d{1,20}$/;
export const MAX_VIEW_IDS = 100;

/** Whether a request body is one the fetch answers. */
export const validViewsRequest = ({ chat, ids, increment } = {}) =>
  CHAT.test(String(chat ?? '')) &&
  Array.isArray(ids) &&
  ids.length > 0 &&
  ids.length <= MAX_VIEW_IDS &&
  ids.every((id) => Number.isInteger(id) && id > 0) &&
  new Set(ids).size === ids.length &&
  (increment === undefined || typeof increment === 'boolean');

const count = (value) =>
  Number.isInteger(Number(value)) && Number(value) >= 0 ? Number(value) : null;

/** One post's counters as the page takes them (`id` is the post's). */
export const viewsOf = (id, raw) => {
  const item = { id };
  const views = count(raw?.views);
  const forwards = count(raw?.forwards);
  const replies = count(raw?.replies?.replies);
  if (views !== null) {
    item.views = views;
  }
  if (forwards !== null) {
    item.forwards = forwards;
  }
  if (replies !== null) {
    item.replies = replies;
  }
  return item;
};

export const createViews = (env, { userClient }) => {
  const messageViews = async (body = {}) => {
    if (!validViewsRequest(body)) {
      return { ok: false, error: 'bad request', code: 'failed' };
    }
    const { chat, ids, increment = false } = body;
    return connected(env, userClient, failure, async (c) => {
      const answer = await runIn(
        env,
        `views:${chat}:${increment ? 'seen' : 'peek'}:${ids.join(',')}`,
        () =>
          env.connection.withPeer(c.client, chat, (peer) =>
            c.client.invoke(
              new c.Api.messages.GetMessagesViews({ peer, id: ids, increment })
            )
          )
      );
      // Telegram answers in the order the ids were given.
      const list = answer?.views ?? [];
      return {
        ok: true,
        items: ids.map((id, i) => viewsOf(id, list[i])),
      };
    });
  };
  return { messageViews };
};

// A chat's voice chat or live stream, kept live (R-Y188; learned, never
// copied): one link per chat, `groupcall:telegram:<chat>`, written from
// updateGroupCall (the call began, changed or ended) and bumped by
// updateGroupCallParticipants (`rev` grows, so the open panel asks for
// the participants again). An update that names no chat is matched to
// the link that holds the call's id.

const SOURCE = 'telegram';

export const groupCallLinkId = (chat) => `groupcall:${SOURCE}:${chat}`;

const holder = async (store, effect) => {
  if (effect.chat) {
    return store.get(groupCallLinkId(effect.chat));
  }
  const found = await store.query(
    (l) => l?.kind === 'group-call' && l.callId === effect.id
  );
  return found[0] ?? null;
};

export const groupCallWriter = async (store, now, effect) => {
  const before = await holder(store, effect);
  const chat = effect.chat ?? before?.chat;
  const people = effect.kind === 'group-call-people';
  if (!chat || (people && !before)) {
    return false;
  }
  const call = people ? (before.call ?? null) : effect.call;
  await store.put({
    id: groupCallLinkId(chat),
    tokens: ['groupcall', SOURCE, String(chat)],
    kind: 'group-call',
    source: SOURCE,
    chat: String(chat),
    callId: call?.id ?? effect.id,
    call,
    rev: (Number(before?.rev) || 0) + (people ? 1 : 0),
    at: new Date(now()).toISOString(),
  });
  return false;
};

/**
 * Voice chats, video chats and live streams of groups and channels, as
 * Telegram Desktop and the web clients have them (R-Y188; learned, never
 * copied). The page never joins or unmutes by itself: every write below
 * answers one click.
 * - `callInfo({ chat })` — the chat's active call, if any (the full chat's
 *   `call`, then phone.getGroupCall) → `{ ok, call }`, `call` null or
 *   `{ id, accessHash, title, count, recent (up to three { id, name }), live (a live stream), scheduleDate
 *   (seconds), subscribed, joinMuted, canStartVideo, canChangeJoinMuted,
 *   defaultJoinAs }`;
 * - `callOpen({ id, accessHash })` — the call and its first participants
 *   (phone.getGroupCall) → `{ ok, call, participants, next, count }`;
 * - `callParticipants({ id, accessHash, offset })` — a further page
 *   (phone.getGroupParticipants);
 * - `callNotify({ id, accessHash, subscribed })` — "Notify me" for a
 *   scheduled call (phone.toggleGroupCallStartSubscription);
 * - `callJoinAs({ chat })` — who may join as (phone.getGroupCallJoinAs);
 * - `callJoin({ id, accessHash, params, joinAs? })` — joins muted
 *   (phone.joinGroupCall) with the browser's join params JSON; answers
 *   `{ ok, connection (Telegram's answer JSON), source }`;
 * - `callLeave({ id, accessHash, source })` — phone.leaveGroupCall;
 * - `callSelf({ id, accessHash, muted, raiseHand?, joinAs? })` — our own
 *   mute or raised hand (phone.editGroupCallParticipant, self only).
 * Telegram's errors become codes the page shows as text.
 */

import { connected, runIn, failureOf } from './telegram-stickers.js';
import { inputOf } from './telegram-send-as-client.js';

const CODES = {
  GROUPCALL_INVALID: 'gone',
  GROUPCALL_FORBIDDEN: 'forbidden',
  GROUPCALL_JOIN_MISSING: 'not-joined',
  PARTICIPANT_JOIN_MISSING: 'not-joined',
  JOIN_AS_PEER_INVALID: 'bad-join-as',
  CHANNEL_PRIVATE: 'no-access',
  CHAT_ID_INVALID: 'no-access',
  PEER_ID_INVALID: 'no-access',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);
const bad = () => ({ ok: false, error: 'bad request', code: 'failed' });

const DIGITS = /^\d{1,20}$/;
const CHAT = /^-\d{1,20}$/;
const JOIN_AS = /^-?\d{1,20}$/;
const PAGE = 30;
const text = (value) => String(value ?? '');

/** Whether the body names a call: its id and access hash as digits. */
export const validCall = (body) =>
  DIGITS.test(text(body?.id)) && /^-?\d{1,20}$/.test(text(body?.accessHash));

export const validChat = (body) => CHAT.test(text(body?.chat));

export const validJoinAs = (value) =>
  value === undefined || (typeof value === 'string' && JOIN_AS.test(value));

/** The join params JSON the page built: an object with a numeric ssrc. */
export const validParams = (value) => {
  if (typeof value !== 'string' || value.length > 20_000) {
    return false;
  }
  try {
    const parsed = JSON.parse(value);
    return (
      Boolean(parsed) &&
      typeof parsed === 'object' &&
      !Array.isArray(parsed) &&
      Number.isFinite(parsed.ssrc) &&
      typeof parsed.ufrag === 'string' &&
      typeof parsed.pwd === 'string' &&
      Array.isArray(parsed.fingerprints)
    );
  } catch {
    return false;
  }
};

/** The marked chat id of a Peer. */
export const peerKey = (peer) => {
  switch (peer?.className) {
    case 'PeerUser':
      return text(peer.userId);
    case 'PeerChat':
      return `-${text(peer.chatId)}`;
    case 'PeerChannel':
      return `-100${text(peer.channelId)}`;
    default:
      return null;
  }
};

const nameOf = (entity) =>
  entity?.title ??
  ([entity?.firstName, entity?.lastName].filter(Boolean).join(' ') ||
    entity?.username ||
    '');

/** A GroupCall as the page reads it; null when it is over. */
export const shapeCall = (call) => {
  if (!call || call.className !== 'GroupCall') {
    return null;
  }
  const schedule = Number(call.scheduleDate) || 0;
  const joinAs = call.defaultSendAs ? peerKey(call.defaultSendAs) : null;
  return {
    id: text(call.id),
    accessHash: text(call.accessHash),
    title: text(call.title),
    count: Number(call.participantsCount) || 0,
    live: Boolean(call.rtmpStream),
    ...(schedule > 0 ? { scheduleDate: schedule } : {}),
    subscribed: Boolean(call.scheduleStartSubscribed),
    joinMuted: Boolean(call.joinMuted),
    canChangeJoinMuted: Boolean(call.canChangeJoinMuted),
    canStartVideo: Boolean(call.canStartVideo),
    creator: Boolean(call.creator),
    ...(joinAs ? { defaultJoinAs: joinAs } : {}),
  };
};

const entityOf = (answer, peer) => {
  const key = peer?.userId ?? peer?.channelId ?? peer?.chatId;
  const list = peer?.userId ? answer.users : answer.chats;
  return (list ?? []).find((e) => text(e.id) === text(key));
};

/**
 * A GroupCallParticipant as the page reads it: who, the marks (muted,
 * raised hand, video, presentation, self), when they last spoke
 * (`activeDate`, seconds: the page decides who is speaking now) and their
 * about line.
 */
export const shapeParticipant = (answer, p) => ({
  id: peerKey(p.peer),
  name: nameOf(entityOf(answer, p.peer)),
  source: Number(p.source) || 0,
  muted: Boolean(p.muted),
  mutedByYou: Boolean(p.mutedByYou),
  canSelfUnmute: Boolean(p.canSelfUnmute),
  activeDate: Number(p.activeDate) || 0,
  raisedHand: p.raiseHandRating !== undefined && p.raiseHandRating !== null,
  video: Boolean(p.video),
  presentation: Boolean(p.presentation),
  self: Boolean(p.self),
  left: Boolean(p.left),
  about: text(p.about),
  date: Number(p.date) || 0,
});

const shapeAll = (answer) =>
  (answer.participants ?? [])
    .map((p) => shapeParticipant(answer, p))
    .filter((p) => p.id && !p.left);

// The connection answer rides in an updateGroupCallConnection.
const connectionOf = (updates) => {
  const found = (updates?.updates ?? []).find(
    (u) => u.className === 'UpdateGroupCallConnection'
  );
  try {
    return found ? JSON.parse(found.params.data) : null;
  } catch {
    return null;
  }
};

const inputCall = (c, { id, accessHash }) =>
  new c.Api.InputGroupCall({
    id: c.helpers.returnBigInt(text(id)),
    accessHash: c.helpers.returnBigInt(text(accessHash)),
  });

// Who we act as: the account itself, or a peer the call allows.
const asPeer = (env, c, joinAs) =>
  joinAs
    ? inputOf(env, c.client, joinAs)
    : Promise.resolve(new c.Api.InputPeerSelf());

// What is asked about a call (nothing is changed).
const createCallReads = (env, { userClient }) => {
  const run = (use) => connected(env, userClient, failure, use);

  const fullChat = async (c, chat, peer) => {
    if (chat.startsWith('-100')) {
      const answer = await c.client.invoke(
        new c.Api.channels.GetFullChannel({ channel: peer })
      );
      return answer?.fullChat;
    }
    const answer = await c.client.invoke(
      new c.Api.messages.GetFullChat({
        chatId: c.helpers.returnBigInt(chat.slice(1)),
      })
    );
    return answer?.fullChat;
  };

  const callInfo = async ({ chat } = {}) => {
    if (!CHAT.test(text(chat))) {
      return { ok: false, supported: false };
    }
    return run((c) =>
      runIn(env, `voice-chat:${chat}`, () =>
        env.connection.withPeer(c.client, chat, async (peer) => {
          const full = await fullChat(c, chat, peer);
          if (!full?.call) {
            return { ok: true, call: null };
          }
          const answer = await c.client.invoke(
            new c.Api.phone.GetGroupCall({ call: full.call, limit: 3 })
          );
          const shaped = shapeCall(answer?.call);
          const joinAs = peerKey(full.groupcallDefaultJoinAs);
          return {
            ok: true,
            call: shaped
              ? {
                  ...(joinAs ? { defaultJoinAs: joinAs } : {}),
                  ...shaped,
                  recent: shapeAll(answer)
                    .slice(0, 3)
                    .map(({ id, name }) => ({ id, name })),
                }
              : null,
          };
        })
      )
    );
  };

  const pageOf = (answer, next) => ({
    participants: shapeAll(answer),
    next: text(next) || null,
  });

  const callOpen = async (request = {}) =>
    validCall(request)
      ? run(async (c) => {
          const answer = await c.client.invoke(
            new c.Api.phone.GetGroupCall({
              call: inputCall(c, request),
              limit: PAGE,
            })
          );
          const call = shapeCall(answer?.call);
          return call
            ? {
                ok: true,
                call,
                ...pageOf(answer, answer.participantsNextOffset),
                count: call.count,
              }
            : { ok: false, error: 'GROUPCALL_INVALID', code: 'gone' };
        })
      : bad();

  const callParticipants = async (request = {}) =>
    validCall(request) && /^[\w-]{0,200}$/.test(text(request.offset))
      ? run(async (c) => {
          const answer = await c.client.invoke(
            new c.Api.phone.GetGroupParticipants({
              call: inputCall(c, request),
              ids: [],
              sources: [],
              offset: text(request.offset),
              limit: PAGE,
            })
          );
          return {
            ok: true,
            ...pageOf(answer, answer.nextOffset),
            count: Number(answer.count) || 0,
          };
        })
      : bad();

  const callJoinAs = async ({ chat } = {}) =>
    CHAT.test(text(chat))
      ? run((c) =>
          env.connection.withPeer(c.client, chat, async (peer) => {
            const answer = await c.client.invoke(
              new c.Api.phone.GetGroupCallJoinAs({ peer })
            );
            const peers = (answer?.peers ?? [])
              .map((one) => ({
                id: peerKey(one),
                name: nameOf(entityOf(answer, one)),
                kind: one.userId ? 'user' : 'channel',
              }))
              .filter((one) => one.id);
            return { ok: true, peers };
          })
        )
      : { ok: false, supported: false };

  return { callInfo, callOpen, callParticipants, callJoinAs };
};

// What follows a click: Notify me, Join, Leave, our own mute and hand.
const createCallWrites = (env, { userClient }) => {
  const run = (use) => connected(env, userClient, failure, use);

  const callNotify = async (request = {}) =>
    validCall(request) && typeof request.subscribed === 'boolean'
      ? run(async (c) => {
          await c.client.invoke(
            new c.Api.phone.ToggleGroupCallStartSubscription({
              call: inputCall(c, request),
              subscribed: request.subscribed,
            })
          );
          return { ok: true, subscribed: request.subscribed };
        })
      : bad();

  const callJoin = async (request = {}) =>
    validCall(request) &&
    validParams(request.params) &&
    validJoinAs(request.joinAs)
      ? run(async (c) => {
          const updates = await c.client.invoke(
            new c.Api.phone.JoinGroupCall({
              muted: true,
              videoStopped: true,
              call: inputCall(c, request),
              joinAs: await asPeer(env, c, request.joinAs),
              params: new c.Api.DataJSON({ data: request.params }),
            })
          );
          const connection = connectionOf(updates);
          return connection
            ? {
                ok: true,
                connection,
                source: JSON.parse(request.params).ssrc | 0,
              }
            : { ok: false, error: 'no connection', code: 'failed' };
        })
      : bad();

  const callLeave = async (request = {}) =>
    validCall(request) && Number.isInteger(request.source)
      ? run(async (c) => {
          await c.client.invoke(
            new c.Api.phone.LeaveGroupCall({
              call: inputCall(c, request),
              source: request.source | 0,
            })
          );
          return { ok: true };
        })
      : bad();

  const callSelf = async (request = {}) =>
    validCall(request) &&
    typeof request.muted === 'boolean' &&
    validJoinAs(request.joinAs) &&
    (request.raiseHand === undefined || typeof request.raiseHand === 'boolean')
      ? run(async (c) => {
          await c.client.invoke(
            new c.Api.phone.EditGroupCallParticipant({
              call: inputCall(c, request),
              participant: await asPeer(env, c, request.joinAs),
              muted: request.muted,
              ...(request.raiseHand === undefined
                ? {}
                : { raiseHand: request.raiseHand }),
            })
          );
          return { ok: true };
        })
      : bad();

  return { callNotify, callJoin, callLeave, callSelf };
};

export const createVoiceChat = (env, context) => ({
  ...createCallReads(env, context),
  ...createCallWrites(env, context),
});

/**
 * Chat backgrounds, as Telegram Desktop's "Chat background" has them
 * (R-Y155; learned, never copied):
 * - `wallpapers({ fresh })` — the wallpapers Telegram offers
 *   (account.getWallPapers, hash 0) as `{ ok, wallpapers: [page] }`, kept
 *   ten minutes; each is an image, a pattern over colours, or colours only;
 * - `wallpaperFile({ id, slug, size })` — a wallpaper's thumbnail or full
 *   image, downloaded once through Telegram into the app folder. A pattern
 *   is a gzipped SVG: unzipped and sanitized here, served as image/svg+xml;
 * - `setChatWallpaper({ chat, id })` — a wallpaper of the list set for one
 *   chat (messages.setChatWallPaper, for the user only), the one write.
 * The choice of the app's own background is the page's, kept on its side.
 * The documents the page may name are those listed (by id) or, for a
 * chat's own wallpaper, the one Telegram answers for its slug.
 */

import { promises as fs } from 'node:fs';
import path from 'node:path';
import zlib from 'node:zlib';
import { bigSize, locationOf, pickSize, readCache } from './telegram-media.js';
import { connected, failureOf, runIn } from './telegram-stickers.js';

const CODES = {
  WALLPAPER_INVALID: 'invalid',
  WALLPAPER_NOT_FOUND: 'invalid',
  PEER_ID_INVALID: 'no-access',
  CHAT_ADMIN_REQUIRED: 'no-access',
  CHAT_WRITE_FORBIDDEN: 'no-access',
  USER_PRIVACY_RESTRICTED: 'no-access',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);

export const ID = /^-?\d{1,20}$/;
export const SLUG = /^[A-Za-z0-9_-]{1,64}$/;
const LIST_MS = 10 * 60_000;
const MAX_IMAGE = 12 * 1024 * 1024;
const MAX_SVG = 2 * 1024 * 1024;
const IMAGE_TYPE = /^image\/(jpeg|png|webp)$/;

const text = (value) =>
  value === null || value === undefined ? '' : String(value.value ?? value);

/** A colour int (0xRRGGBB, maybe signed) as `#rrggbb`. */
export const hexOf = (value) =>
  `#${(Number(value) & 0xffffff).toString(16).padStart(6, '0')}`;

const COLOUR_KEYS = [
  'backgroundColor',
  'secondBackgroundColor',
  'thirdBackgroundColor',
  'fourthBackgroundColor',
];

/** The colours of a wallpaper's settings, in order, as `#rrggbb`. */
export const coloursOf = (settings) =>
  COLOUR_KEYS.map((key) => settings?.[key])
    .filter((v) => v !== undefined && v !== null)
    .map(hexOf);

const kindOf = (wp, withFile) => {
  if (!withFile) {
    return 'colors';
  }
  return wp.pattern ? 'pattern' : 'image';
};

const settingsPage = (settings) => ({
  colors: coloursOf(settings),
  rotation: Number(settings?.rotation ?? 0) || 0,
  intensity: Number(settings?.intensity ?? 0) || 0,
  blur: Boolean(settings?.blur),
  motion: Boolean(settings?.motion),
});

/**
 * A WallPaper or WallPaperNoFile as the page keeps it:
 * `{ id, slug, kind: image|pattern|colors, dark, colors, rotation,
 * intensity, blur, motion, file }`, or null.
 */
export const wallpaperPage = (wp) => {
  if (!wp || !['WallPaper', 'WallPaperNoFile'].includes(wp.className)) {
    return null;
  }
  const withFile = wp.className === 'WallPaper' && Boolean(wp.document?.id);
  return {
    id: text(wp.id),
    slug: withFile && SLUG.test(String(wp.slug ?? '')) ? wp.slug : '',
    kind: kindOf(wp, withFile),
    dark: Boolean(wp.dark),
    ...settingsPage(wp.settings),
    file: withFile,
  };
};

// Elements dropped with everything inside them.
const DROPPED =
  'script|foreignObject|style|iframe|object|embed|animate|animateMotion|animateTransform|set|image|audio|video|canvas|handler|listener';

const ATTRIBUTE = String.raw`("[^"]*"|'[^']*'|[^\s>]+)`;

// An href that is not a `#id` of the file itself is dropped.
const keepLocalHref = (all, name, raw) => {
  const value = String(raw)
    .replace(/^["']|["']$/g, '')
    .trim();
  return value.startsWith('#') ? all : '';
};

/**
 * A pattern wallpaper's SVG made safe to show: no scripts, foreign
 * objects, styles, animations, images or links; no event attributes;
 * no reference but to the file itself (`#id`); no doctype or entities.
 */
export const sanitizeSvg = (source) => {
  let svg = String(source)
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/<\?[\s\S]*?\?>/g, '')
    .replace(/<!\[CDATA\[[\s\S]*?\]\]>/g, '')
    .replace(/<!(DOCTYPE|ENTITY|ELEMENT|ATTLIST)[^>]*>/gi, '');
  const pair = new RegExp(
    `<(${DROPPED})\\b[^>]*?(?:/>|>[\\s\\S]*?</\\1\\s*>)`,
    'gi'
  );
  let before;
  do {
    before = svg;
    svg = svg.replace(pair, '');
  } while (svg !== before);
  // An opening tag left without its end is dropped too.
  svg = svg.replace(new RegExp(`<(${DROPPED})\\b[^>]*>`, 'gi'), '');
  // A link keeps what it holds (the drawing) but is no link.
  svg = svg.replace(/<\/?a\b[^>]*>/gi, '');
  svg = svg
    .replace(
      new RegExp(`\\s(on[a-z]+|formaction|srcdoc)\\s*=\\s*${ATTRIBUTE}`, 'gi'),
      ''
    )
    .replace(
      new RegExp(`\\s((?:xlink:)?href|src)\\s*=\\s*${ATTRIBUTE}`, 'gi'),
      keepLocalHref
    )
    .replace(/\sstyle\s*=\s*("[^"]*"|'[^']*')/gi, (all, value) =>
      /url\(|expression|javascript|@import/i.test(value) ? '' : all
    )
    .replace(/(javascript|vbscript|data)\s*:/gi, '');
  const start = svg.search(/<svg\b/i);
  return start < 0 ? '' : svg.slice(start).trim();
};

/** A pattern document's bytes (gzip or plain SVG) as safe SVG bytes. */
export const patternSvg = (buffer) => {
  try {
    const gzipped = buffer[0] === 0x1f && buffer[1] === 0x8b;
    const raw = gzipped
      ? zlib.gunzipSync(buffer, { maxOutputLength: MAX_SVG })
      : buffer;
    const svg = sanitizeSvg(raw.toString('utf8'));
    return svg ? Buffer.from(svg, 'utf8') : null;
  } catch {
    return null;
  }
};

// The settings Telegram is told with a chat's wallpaper.
const settingsOf = (c, page) => {
  const fields = {};
  page.colors.forEach((colour, i) => {
    fields[COLOUR_KEYS[i]] = parseInt(colour.slice(1), 16);
  });
  if (page.colors.length > 1) {
    fields.rotation = page.rotation;
  }
  if (page.intensity) {
    fields.intensity = page.intensity;
  }
  return new c.Api.WallPaperSettings(fields);
};

const download = async (c, doc, thumb) => {
  const size = Number(doc.size ?? 0);
  if (!thumb && size > MAX_IMAGE) {
    return null;
  }
  const buffer = await c.client.downloadFile(
    locationOf(c.Api, c.helpers, { kind: 'document', file: doc, thumb }),
    { dcId: Number(doc.dcId), fileSize: bigSize(c.helpers, thumb ? 0 : size) }
  );
  return buffer?.length ? Buffer.from(buffer) : null;
};

// A wallpaper's thumbnail or full picture; a pattern as safe SVG.
const fetchPicture = async (c, wp, size) => {
  const doc = wp.document;
  if (wp.pattern) {
    const raw = await download(c, doc, '');
    const svg = raw ? patternSvg(raw) : null;
    return svg ? { buffer: svg, mimeType: 'image/svg+xml' } : null;
  }
  const thumb = size === 'thumb' ? pickSize(doc.thumbs ?? [], 'm') : '';
  if (size === 'thumb' && !thumb) {
    return null;
  }
  const buffer = await download(c, doc, thumb);
  const mimeType = thumb ? 'image/jpeg' : String(doc.mimeType ?? '');
  return buffer && IMAGE_TYPE.test(mimeType) ? { buffer, mimeType } : null;
};

export const createWallpapers = (env, { userClient, mediaDir }) => {
  const known = new Map(); // id -> WallPaper
  const flights = new Map();
  let kept = null; // { at, answer }

  const remember = (list) => {
    const pages = [];
    for (const wp of list ?? []) {
      const page = wallpaperPage(wp);
      if (page) {
        known.set(page.id, wp);
        pages.push(page);
      }
    }
    return pages;
  };

  const wallpapers = async ({ fresh = false } = {}) => {
    if (!fresh && kept && Date.now() - kept.at < LIST_MS) {
      return kept.answer;
    }
    return connected(env, userClient, failure, async (c) => {
      const got = await runIn(env, 'wallpapers:list', () =>
        c.client.invoke(new c.Api.account.GetWallPapers({ hash: c.zero }))
      );
      if (got?.className === 'account.WallPapersNotModified' && kept) {
        return kept.answer;
      }
      const answer = { ok: true, wallpapers: remember(got?.wallpapers) };
      kept = { at: Date.now(), answer };
      return answer;
    });
  };

  // A wallpaper not on the list (a chat's own): by its slug.
  const bySlug = async (id, slug) => {
    if (!SLUG.test(slug)) {
      return null;
    }
    return connected(
      env,
      userClient,
      () => null,
      async (c) => {
        const wp = await runIn(env, `wallpaper:${slug}`, () =>
          c.client.invoke(
            new c.Api.account.GetWallPaper({
              wallpaper: new c.Api.InputWallPaperSlug({ slug }),
            })
          )
        );
        if (text(wp?.id) !== id || wp?.className !== 'WallPaper') {
          return null;
        }
        known.set(id, wp);
        return wp;
      }
    );
  };

  const fetchFile = (wp, size) =>
    connected(
      env,
      userClient,
      () => null,
      (c) =>
        runIn(env, `wallpaper-file:${text(wp.id)}:${size}`, () =>
          fetchPicture(c, wp, size)
        )
    );

  const load = async (key, slug, size, file) => {
    const wp = known.get(key) ?? (await bySlug(key, slug));
    if (wp?.className !== 'WallPaper' || !wp.document?.id) {
      return null;
    }
    const got = await fetchFile(wp, size);
    if (!got?.buffer) {
      return null;
    }
    await fs.mkdir(path.dirname(file), { recursive: true });
    await fs.writeFile(file, got.buffer);
    await fs.writeFile(`${file}.type`, got.mimeType);
    return got;
  };

  const wallpaperFile = async ({ id, slug = '', size = 'full' } = {}) => {
    const key = String(id ?? '');
    if (!ID.test(key) || !mediaDir || !['thumb', 'full'].includes(size)) {
      return null;
    }
    const name = `${key.replace('-', 'n')}-${size}`;
    const file = path.join(mediaDir, 'wallpapers', name);
    const cached = await readCache(file);
    const type = cached ? String(await readCache(`${file}.type`)) : '';
    if (cached && /^image\//.test(type)) {
      return { buffer: cached, mimeType: type };
    }
    if (!flights.has(name)) {
      flights.set(
        name,
        load(key, String(slug), size, file)
          .catch(() => null)
          .finally(() => flights.delete(name))
      );
    }
    return flights.get(name);
  };

  const inputOf = (c, wp) =>
    wp.className === 'WallPaper'
      ? new c.Api.InputWallPaper({ id: wp.id, accessHash: wp.accessHash })
      : new c.Api.InputWallPaperNoFile({ id: wp.id });

  // The one write: a wallpaper of the list for this chat, for the user
  // only (forBoth off).
  const setChatWallpaper = async ({ chat, id } = {}) => {
    const wp = known.get(String(id ?? ''));
    if (!ID.test(String(chat ?? '')) || !wp) {
      return { ok: false, error: 'unknown wallpaper', code: 'unknown' };
    }
    return connected(env, userClient, failure, async (c) => {
      await runIn(env, `wallpaper-set:${chat}`, () =>
        env.connection.withPeer(c.client, String(chat), (peer) =>
          c.client.invoke(
            new c.Api.messages.SetChatWallPaper({
              peer,
              wallpaper: inputOf(c, wp),
              ...(wp.settings
                ? { settings: settingsOf(c, wallpaperPage(wp)) }
                : {}),
            })
          )
        )
      );
      return { ok: true };
    });
  };

  return { wallpapers, wallpaperFile, setChatWallpaper };
};

/**
 * A bot's mini apps (Web Apps), as Telegram Desktop opens them (R-Y168;
 * learned from Telegram's public Mini Apps documentation, never copied):
 * - `webAppOpen({ kind, ... })` asks Telegram for the address the app is
 *   shown from → `{ ok, url, queryId, fullsize, bot? }`:
 *     'menu'    the bot's menu button (messages.requestWebView, from the
 *               bot menu): `chat`, `bot`, `url?`;
 *     'inline'  an inline keyboard button (messages.requestWebView):
 *               `chat`, `bot`, `url`;
 *     'simple'  a reply keyboard button (messages.requestSimpleWebView):
 *               `bot`, `url`;
 *     'app'     a t.me/bot/app link (messages.getBotApp, then
 *               messages.requestAppWebView): `username`, `shortName`,
 *               `startParam?`, `chat?`;
 *     'main'    a t.me/bot?startapp link (messages.requestMainWebView):
 *               `username`, `startParam?`, `chat?`.
 *   `theme` is the app's colours (theme_params); the platform is 'weba',
 *   the name Telegram's own web client gives, as this is a web client.
 * - `webAppProlong({ chat, bot, queryId })` keeps a query alive while the
 *   app is open (messages.prolongWebView, silent) — the page asks every 60
 *   seconds;
 * - `webAppSendData({ bot, text, data })` is a reply-keyboard app's
 *   `web_app_data_send` (messages.sendWebViewData).
 * The address Telegram answers must be https without credentials, else
 * nothing is opened. 'attach' (R-Y201): an attachment-menu bot's app, from
 * the chat, with no address (messages.requestWebView, not from the bot menu).
 */

import { runIn, connected, failureOf } from './telegram-stickers.js';
import { inputUserOf } from './telegram-peer-actions.js';
import { inputBot, resolveBotUser } from './telegram-inline-bots.js';
import { randomIdOf } from './telegram-send.js';

const CODES = {
  BOT_INVALID: 'no-bot',
  BOT_APP_INVALID: 'no-app',
  BOT_APP_SHORTNAME_INVALID: 'no-app',
  USERNAME_NOT_OCCUPIED: 'no-bot',
  USERNAME_INVALID: 'no-bot',
  URL_INVALID: 'bad-url',
  PEER_ID_INVALID: 'no-access',
  CHANNEL_PRIVATE: 'no-access',
  BOT_DOMAIN_INVALID: 'bad-url',
  DATA_INVALID: 'bad-data',
  FLOOD_WAIT: 'flood',
};

const failure = failureOf(CODES);

export const PLATFORM = 'weba';
// 'attach': an attachment-menu bot's app (R-Y201), no address asked.
export const KINDS = ['menu', 'inline', 'simple', 'app', 'main', 'attach'];
export const MAX_URL = 2048;
export const MAX_DATA = 4096;
export const MAX_TEXT = 64;

const ID = /^\d{1,20}$/;
const CHAT = /^-?\d{1,20}$/;
const NAME = /^[A-Za-z][A-Za-z0-9_]{3,31}$/;
const SHORT = /^[A-Za-z][A-Za-z0-9_]{2,31}$/;
const START = /^[A-Za-z0-9_-]{0,512}$/;
const COLOR = /^#[0-9a-fA-F]{6}$/;
const BAD = { ok: false, error: 'bad request', code: 'bad-request' };

const text = (value) =>
  value === null || value === undefined ? '' : String(value.value ?? value);

/** An https address without credentials, within bounds; else null. */
export const httpsUrl = (value) => {
  const raw = String(value ?? '').trim();
  if (!raw || raw.length > MAX_URL) {
    return null;
  }
  try {
    const url = new URL(raw);
    return url.protocol === 'https:' && !url.username && !url.password
      ? url.href
      : null;
  } catch {
    return null;
  }
};

/** The theme as sent: `key: #rrggbb` pairs only, or null. */
export const themeOf = (theme) => {
  if (!theme || typeof theme !== 'object' || Array.isArray(theme)) {
    return null;
  }
  const entries = Object.entries(theme);
  return entries.length <= 32 &&
    entries.every(([k, v]) => /^[a-z_]{1,40}$/.test(k) && COLOR.test(String(v)))
    ? Object.fromEntries(entries)
    : null;
};

/** Whether `value` may be a start parameter (absent is fine). */
export const startParamOk = (value) =>
  value === undefined || (typeof value === 'string' && START.test(value));

const botOut = (user) => ({
  id: text(user?.id),
  name:
    [user?.firstName, user?.lastName].filter(Boolean).join(' ') ||
    String(user?.username ?? ''),
  username: String(user?.username ?? ''),
});

// Theme and platform ride along on every request.
const common = (c, theme) => {
  const ok = themeOf(theme);
  return {
    ...(ok
      ? { themeParams: new c.Api.DataJSON({ data: JSON.stringify(ok) }) }
      : {}),
    platform: PLATFORM,
  };
};

const resultOf = (answer, bot) => {
  const url = httpsUrl(answer?.url);
  if (!url) {
    return { ok: false, error: 'bad address', code: 'bad-url' };
  }
  return {
    ok: true,
    url,
    queryId:
      answer.queryId === undefined || answer.queryId === null
        ? null
        : text(answer.queryId),
    fullsize: Boolean(answer.fullsize),
    ...(bot ? { bot } : {}),
  };
};

// A user as the input a request names, from the chat id alone.
const userIn = (c, env, id) =>
  env.connection.withPeer(c.client, String(id), (peer) => inputUserOf(c, peer));

const peerIn = (c, env, chat) =>
  env.connection.withPeer(c.client, String(chat), (peer) => peer);

const MENUS = ['menu', 'attach'];
const NO_BOT = { ok: false, error: 'not a bot', code: 'no-bot' };

const openMenu = async (c, env, o) => {
  const [peer, bot] = await Promise.all([
    peerIn(c, env, o.chat),
    userIn(c, env, o.bot),
  ]);
  const answer = await runIn(env, `web-app:${o.bot}`, () =>
    c.client.invoke(
      new c.Api.messages.RequestWebView({
        peer,
        bot,
        ...(o.kind === 'menu' ? { fromBotMenu: true } : {}),
        ...(o.url ? { url: o.url } : {}),
        ...(o.startParam ? { startParam: o.startParam } : {}),
        ...common(c, o.theme),
      })
    )
  );
  return resultOf(answer);
};

const openSimple = async (c, env, o) => {
  const bot = await userIn(c, env, o.bot);
  const answer = await runIn(env, `web-app:${o.bot}`, () =>
    c.client.invoke(
      new c.Api.messages.RequestSimpleWebView({
        bot,
        url: o.url,
        ...common(c, o.theme),
      })
    )
  );
  return resultOf(answer);
};

const openApp = async (c, env, o) => {
  const user = await runIn(env, `web-app:resolve:${o.username}`, () =>
    resolveBotUser(c, o.username)
  );
  if (!user) {
    return NO_BOT;
  }
  const found = await runIn(env, `web-app:app:${o.username}`, () =>
    c.client.invoke(
      new c.Api.messages.GetBotApp({
        app: new c.Api.InputBotAppShortName({
          botId: inputBot(c, user),
          shortName: o.shortName,
        }),
        hash: c.zero,
      })
    )
  );
  const app = found?.app;
  if (app?.className !== 'BotApp') {
    return { ok: false, error: 'no such app', code: 'no-app' };
  }
  const peer = await peerIn(c, env, o.chat ?? text(user.id));
  const answer = await runIn(env, `web-app:app:${o.username}`, () =>
    c.client.invoke(
      new c.Api.messages.RequestAppWebView({
        peer,
        app: new c.Api.InputBotAppID({
          id: app.id,
          accessHash: app.accessHash,
        }),
        ...(o.startParam ? { startParam: o.startParam } : {}),
        ...common(c, o.theme),
      })
    )
  );
  return resultOf(answer, { ...botOut(user), title: String(app.title ?? '') });
};

const openMain = async (c, env, o) => {
  const user = await runIn(env, `web-app:resolve:${o.username}`, () =>
    resolveBotUser(c, o.username)
  );
  if (!user) {
    return NO_BOT;
  }
  const peer = await peerIn(c, env, o.chat ?? text(user.id));
  const answer = await runIn(env, `web-app:main:${o.username}`, () =>
    c.client.invoke(
      new c.Api.messages.RequestMainWebView({
        peer,
        bot: inputBot(c, user),
        ...(o.startParam ? { startParam: o.startParam } : {}),
        ...common(c, o.theme),
      })
    )
  );
  return resultOf(answer, botOut(user));
};

const OPENERS = {
  menu: openMenu,
  inline: openMenu,
  attach: openMenu,
  simple: openSimple,
  app: openApp,
  main: openMain,
};

// A link's app: the bot's username, the app's short name (not for the
// main app) and, when given, the chat it opens from.
const linkReady = (o) =>
  NAME.test(o.username ?? '') &&
  (o.kind === 'main' || SHORT.test(o.shortName ?? '')) &&
  (o.chat === undefined || CHAT.test(String(o.chat)));

// A button's app: the bot, the chat (not for a simple one) and the
// https address (the menu button may leave it to Telegram).
const buttonReady = (o) =>
  ID.test(String(o.bot ?? '')) &&
  (o.kind === 'simple' || CHAT.test(String(o.chat ?? ''))) &&
  (o.url ? true : MENUS.includes(o.kind) && o.url === undefined);

// What each kind must carry, checked before the account is asked.
const complete = (o) =>
  KINDS.includes(o.kind) &&
  startParamOk(o.startParam) &&
  (o.kind === 'app' || o.kind === 'main' ? linkReady(o) : buttonReady(o));

export const createWebApps = (env, { userClient, apply }) => ({
  webAppOpen: async (options = {}) => {
    // An address that is not https is nulled, which fails `complete`.
    const o = {
      ...options,
      ...(options.url === undefined ? {} : { url: httpsUrl(options.url) }),
    };
    if (!complete(o)) {
      return BAD;
    }
    return connected(env, userClient, failure, (c) =>
      OPENERS[o.kind](c, env, o)
    );
  },
  webAppProlong: async ({ chat, bot, queryId } = {}) => {
    if (
      !CHAT.test(String(chat)) ||
      !ID.test(String(bot)) ||
      !ID.test(String(queryId))
    ) {
      return BAD;
    }
    return connected(env, userClient, failure, async (c) => {
      const [peer, user] = await Promise.all([
        peerIn(c, env, chat),
        userIn(c, env, bot),
      ]);
      await runIn(env, `web-app:prolong:${queryId}`, () =>
        c.client.invoke(
          new c.Api.messages.ProlongWebView({
            silent: true,
            peer,
            bot: user,
            queryId: c.helpers.returnBigInt(String(queryId)),
          })
        )
      );
      return { ok: true };
    });
  },
  webAppSendData: async ({ bot, text: label, data } = {}) => {
    const words = typeof label === 'string' ? label.trim() : '';
    const body = typeof data === 'string' ? data : '';
    if (
      !ID.test(String(bot)) ||
      !words ||
      words.length > MAX_TEXT ||
      !body ||
      Buffer.byteLength(body) > MAX_DATA
    ) {
      return BAD;
    }
    return connected(env, userClient, failure, async (c) => {
      const user = await userIn(c, env, bot);
      const result = await runIn(env, `web-app:data:${bot}`, () =>
        c.client.invoke(
          new c.Api.messages.SendWebViewData({
            bot: user,
            randomId: randomIdOf(null, 0, c.helpers),
            buttonText: words,
            data: body,
          })
        )
      );
      if (result && typeof result === 'object' && apply) {
        await apply(c.client, result);
      }
      return { ok: true };
    });
  },
});

// Honest outcomes for account writes (R-Y218; R-Z4 rule): when a Telegram
// call that CHANGES something fails without an answer from Telegram (a
// dropped connection, a timeout), the change may have been made. The answer
// is then `send-unknown` (never "failed", never retried or tried another
// way), and the page tells the user to look before doing it again. Errors
// Telegram itself answers (an RPC error: wrong code, flood wait, ...) are
// clear failures and keep their own codes. Nothing of the error's text, which
// may hold a code or an address, is passed on.

import { failureOf } from './telegram-stickers.js';
import { markSendOutcome } from './http.js';

/** The answer for a write whose outcome is not known. */
export const UNKNOWN_WRITE = Object.freeze({
  ok: false,
  error: 'send-unknown',
  code: 'send-unknown',
  outcome: 'unknown',
  fallback: false,
});

const answered = (error, codes) => {
  const name = String(error?.errorMessage ?? '');
  return (
    name !== '' ||
    Object.keys(codes).some((k) => String(error?.message ?? '').includes(k))
  );
};

/** `failureOf(codes)` for writes: no answer from Telegram means unknown. */
export const writeFailureOf = (codes) => {
  const failure = failureOf(codes);
  return (error) => {
    if (answered(error, codes)) {
      return failure(error);
    }
    markSendOutcome(error, { ambiguous: true });
    return { ...UNKNOWN_WRITE };
  };
};

/**
 * Telegram source adapter.
 *
 * `parseArchive` accepts the JSON shape produced by Telegram Desktop's
 * "Export chat history" feature, both per-chat and all-chats exports.
 * The live side uses Telegram's Bot API (`getUpdates`, `sendMessage`,
 * `setMyName`, `setMyDescription`) so a user-provided bot token can
 * pull incoming bot-visible messages and send queued replies.
 * Greeting stickers (issue #35) go out through `sendSticker`; packs are
 * enumerated with `getStickerSet`, and their thumbnails are fetched by
 * the local server (`fetchFile`) because Bot API file links embed the
 * bot token and must never reach the browser.
 *
 * Issue #31 / PR #34: `setTyping` shows the bot's typing status via
 * `sendChatAction`, and `chatMembers` lists what the Bot API exposes
 * about a chat's members (see the limitation note on the method).
 */

import { buildMessageLink } from './link.js';
import { contentSticker } from './sticker.js';
import { greetingEmoji } from '../greetings/detect.js';
import { DEFAULT_TIMEOUT_MS, timedRequest } from './http.js';

// Bot API methods that only read: a timeout there is retried (R-Z1).
const BOT_READS = /^get[A-Z]/;

const SOURCE = 'telegram';

const fromTextEntity = (text) => {
  if (typeof text === 'string') {
    return text;
  }
  if (Array.isArray(text)) {
    return text.map(fromTextEntity).join('');
  }
  if (text && typeof text === 'object' && 'text' in text) {
    return text.text;
  }
  return '';
};

const parseArchiveObject = (archive) =>
  typeof archive === 'string' ? JSON.parse(archive) : archive;

const archiveChats = (obj) => {
  if (Array.isArray(obj)) {
    return [{ id: 'telegram', name: 'telegram', messages: obj }];
  }
  if (obj.chats?.list) {
    return obj.chats.list;
  }
  if (obj.messages) {
    return [obj];
  }
  return [];
};

const messageText = (msg) => {
  const direct = fromTextEntity(msg.text);
  if (direct) {
    return direct;
  }
  return fromTextEntity(msg.text_entities);
};

const messageTimestamp = (msg) => {
  if (msg.date) {
    return msg.date;
  }
  if (msg.date_unixtime) {
    return new Date(Number(msg.date_unixtime) * 1000).toISOString();
  }
  return undefined;
};

const senderId = (msg) =>
  String(msg.from_id ?? msg.actor_id ?? msg.from ?? msg.sender_id ?? 'unknown');

const liveToken = () => globalThis.process?.env?.TELEGRAM_BOT_TOKEN ?? null;

const botMessage = (update) =>
  update.message ??
  update.edited_message ??
  update.channel_post ??
  update.edited_channel_post ??
  update.business_message ??
  update.edited_business_message ??
  null;

const botSender = (message) =>
  String(
    message.from?.id ??
      message.sender_chat?.id ??
      message.author_signature ??
      'unknown'
  );

const botSticker = (message) =>
  message.sticker
    ? {
        id: String(message.sticker.file_unique_id ?? message.sticker.file_id),
        fileId: message.sticker.file_id ?? null,
        pack: message.sticker.set_name ?? null,
        emoji: message.sticker.emoji ?? null,
      }
    : null;

const archiveSticker = (msg) =>
  msg.media_type === 'sticker'
    ? { id: msg.file ?? null, pack: null, emoji: msg.sticker_emoji ?? null }
    : null;

const isGreetingEmoji = (emoji) =>
  Boolean(emoji) && greetingEmoji.some((wave) => emoji.includes(wave));

const stickerFormat = (sticker) => {
  if (sticker.is_animated) {
    return 'tgs';
  }
  return sticker.is_video ? 'webm' : 'webp';
};

/** One `getStickerSet` result reduced to its greeting stickers. */
const greetingStickersOfSet = (set, entry) => {
  const name = set.name ?? entry.name;
  return (set.stickers ?? [])
    .filter((sticker) => entry.all || isGreetingEmoji(sticker.emoji))
    .map((sticker) => ({
      network: SOURCE,
      id: sticker.file_id,
      uniqueId: sticker.file_unique_id ?? null,
      pack: name,
      packTitle: set.title ?? name,
      emoji: sticker.emoji ?? null,
      format: stickerFormat(sticker),
      thumbnailFileId:
        sticker.thumbnail?.file_id ?? sticker.thumb?.file_id ?? null,
      addUrl: `https://t.me/addstickers/${name}`,
    }));
};

/** `sendSticker` for sticker content, `sendMessage` otherwise. */
const botSendFields = (content) =>
  compact({
    reply_parameters: content?.replyTo
      ? {
          message_id: content.replyTo,
          ...(content.replyQuote ? { quote: content.replyQuote } : {}),
        }
      : undefined,
    message_thread_id: content?.topic > 1 ? content.topic : undefined,
    disable_notification: content?.silent === true ? true : undefined,
  });
const sendRequest = (content, chat) => {
  const sticker = contentSticker(content);
  const business = content?.businessConnectionId;
  const fields = botSendFields(content);
  if (sticker) {
    return [
      'sendSticker',
      {
        chat_id: chat,
        sticker: sticker.id ?? sticker.url,
        business_connection_id: business,
        ...fields,
      },
    ];
  }
  const text =
    typeof content === 'string' ? content : (content?.text ?? content?.body);
  return [
    'sendMessage',
    {
      chat_id: chat,
      text,
      business_connection_id: business,
      ...fields,
      ...(content?.noWebpage
        ? { link_preview_options: { is_disabled: true } }
        : {}),
    },
  ];
};

const botChat = (message) =>
  String(message.chat?.id ?? message.business_connection_id ?? 'unknown');

const compact = (obj) =>
  Object.fromEntries(
    Object.entries(obj).filter(
      (entry) => entry[1] !== null && entry[1] !== undefined
    )
  );

const botForwardedFrom = (message) => {
  const origin = message.forward_origin;
  if (origin) {
    if (origin.type === 'user') {
      return {
        id: String(origin.sender_user?.id),
        name:
          [origin.sender_user?.first_name, origin.sender_user?.last_name]
            .filter(Boolean)
            .join(' ') || null,
      };
    }
    if (origin.type === 'channel') {
      return { id: String(origin.chat?.id), name: origin.chat?.title || null };
    }
    if (origin.type === 'hidden_user') {
      return { name: origin.sender_user_name || null };
    }
  }
  if (message.forward_from) {
    return {
      id: String(message.forward_from.id),
      name:
        [message.forward_from.first_name, message.forward_from.last_name]
          .filter(Boolean)
          .join(' ') || null,
    };
  }
  return null;
};

const photoAtt = (message) => {
  if (!message.photo) {
    return null;
  }
  const largest = message.photo.reduce(
    (best, p) => ((p.file_size ?? 0) > (best.file_size ?? 0) ? p : best),
    message.photo[0]
  );
  return compact({
    kind: 'photo',
    width: largest?.width,
    height: largest?.height,
  });
};

const documentAtt = (doc) =>
  compact({
    kind: 'file',
    name: doc.file_name ?? null,
    mime: doc.mime_type ?? null,
    size: doc.file_size ?? null,
  });

const voiceAtt = (v) =>
  compact({
    kind: 'voice',
    duration: v.duration ?? null,
    mime: v.mime_type ?? null,
  });

const videoAtt = (v) =>
  compact({
    kind: 'video',
    duration: v.duration ?? null,
    width: v.width ?? null,
    height: v.height ?? null,
  });

const audioAtt = (a) =>
  compact({
    kind: 'audio',
    duration: a.duration ?? null,
    mime: a.mime_type ?? null,
    name: a.file_name ?? null,
    title: a.title ?? null,
  });

const mediaAtt = (message) => {
  if (message.document) {
    return documentAtt(message.document);
  }
  if (message.voice) {
    return voiceAtt(message.voice);
  }
  if (message.video) {
    return videoAtt(message.video);
  }
  if (message.audio) {
    return audioAtt(message.audio);
  }
  return null;
};

const miscAtt = (message) => {
  if (message.location) {
    return {
      kind: 'location',
      lat: message.location.latitude,
      lon: message.location.longitude,
    };
  }
  if (message.contact) {
    return compact({
      kind: 'contact',
      name:
        [message.contact.first_name, message.contact.last_name]
          .filter(Boolean)
          .join(' ') || null,
    });
  }
  if (message.poll) {
    return compact({ kind: 'poll', title: message.poll.question ?? null });
  }
  return null;
};

/** Non-sticker attachments extracted from a Bot API message. */
const botAttachment = (message) => {
  const att = photoAtt(message) ?? mediaAtt(message) ?? miscAtt(message);
  return att ? [att] : null;
};

const botSenderName = (message) =>
  [message.from?.first_name, message.from?.last_name]
    .filter(Boolean)
    .join(' ') ||
  message.sender_chat?.title ||
  message.author_signature ||
  null;

const botChatName = (message) =>
  message.chat?.title ||
  (message.chat?.first_name
    ? [message.chat.first_name, message.chat.last_name]
        .filter(Boolean)
        .join(' ')
    : null) ||
  null;

const botLinkFields = (update, message) => {
  const isEdited = !!(
    update.edited_message ||
    update.edited_channel_post ||
    update.edited_business_message
  );
  return {
    source: SOURCE,
    externalId: String(message.message_id ?? update.update_id),
    sender: botSender(message),
    chat: botChat(message),
    body: message.text ?? message.caption ?? '',
    timestamp: message.date
      ? new Date(Number(message.date) * 1000).toISOString()
      : undefined,
    replyTo: message.reply_to_message?.message_id
      ? String(message.reply_to_message.message_id)
      : null,
    chatType: message.chat?.type ?? null,
    sticker: botSticker(message),
    senderName: botSenderName(message),
    chatName: botChatName(message),
    edited: isEdited
      ? new Date(Number(message.edit_date) * 1000).toISOString()
      : null,
    forwardedFrom: botForwardedFrom(message),
    attachments: botAttachment(message),
    raw: message,
  };
};

export const telegramReactionsFromUpdate = (update) => {
  if (!update?.message_reaction) {
    return null;
  }
  const mr = update.message_reaction;
  return {
    messageId: String(mr.message_id),
    chat: String(mr.chat?.id),
    reactions: (mr.new_reaction ?? []).map((r) => ({
      emoji: r.emoji ?? r.custom_emoji_id ?? String(r.type),
      count: 1,
    })),
  };
};

export const telegramUpdatesToLinks = (updates) => {
  const out = [];
  for (const update of updates ?? []) {
    if (update.message_reaction) {
      continue;
    }
    const message = botMessage(update);
    if (!message) {
      continue;
    }
    out.push(buildMessageLink(botLinkFields(update, message)));
  }
  return out;
};

/** Membership calls (issue #31 audiences) over the Bot API `call`. */
const membershipMethods = (call) => ({
  async friends() {
    throw new Error(
      'telegram Bot API has no friends/contacts list; use chatMembers'
    );
  },
  /**
   * The Bot API cannot enumerate every member of a group: only the
   * administrators (`getChatAdministrators`) and the total head count
   * (`getChatMemberCount`) are available. Regular members only become
   * known as they post (see `pullMessages`). Returns the admins plus
   * the reported total so callers can tell the list is partial.
   */
  async chatMembers(chatId, options = {}) {
    if (!chatId) {
      throw new Error('telegram chatMembers requires a chat id');
    }
    const admins = await call(
      'getChatAdministrators',
      { chat_id: chatId },
      options.token
    );
    const count = await call(
      'getChatMemberCount',
      { chat_id: chatId },
      options.token
    );
    const members = (admins ?? []).map(({ user = {} }) => ({
      user: String(user.id),
      name: [user.first_name, user.last_name].filter(Boolean).join(' ') || null,
      handle: user.username ?? null,
    }));
    return { members, count: Number(count), partial: true };
  },
});

/** Profile update methods. */
const profileMethods = (call) => ({
  async syncProfile(profile) {
    const results = [];
    if (profile.name) {
      results.push({
        method: 'setMyName',
        result: await call('setMyName', { name: profile.name }),
      });
    }
    if (profile.bio) {
      results.push({
        method: 'setMyDescription',
        result: await call('setMyDescription', { description: profile.bio }),
      });
    }
    return results;
  },
});

/** Bot API mutation methods (edit, delete, react, forward). */
const actionMethods = (call) => {
  const setMessageReaction = async (
    { chat, id, emoji, link } = {},
    options = {}
  ) => {
    const chatId = chat ?? link?.chat;
    const messageId = Number(id ?? link?.id?.split(':').pop());
    const reaction = emoji ? [{ type: 'emoji', emoji }] : [];
    return call(
      'setMessageReaction',
      { chat_id: chatId, message_id: messageId, reaction },
      options.token
    );
  };
  return {
    async editMessage({ chat, id, text, link } = {}, options = {}) {
      const chatId = chat ?? link?.chat;
      const messageId = Number(id ?? link?.id?.split(':').pop());
      return call(
        'editMessageText',
        { chat_id: chatId, message_id: messageId, text },
        options.token
      );
    },
    async deleteMessages({ chat, ids, links } = {}, options = {}) {
      const chatId = chat ?? links?.[0]?.chat;
      const rawIds = ids ?? links?.map((l) => Number(l.id?.split(':').pop()));
      const messageIds = (rawIds ?? []).filter(Boolean);
      return call(
        'deleteMessages',
        { chat_id: chatId, message_ids: messageIds },
        options.token
      );
    },
    setMessageReaction,
    react: setMessageReaction,
    async forwardMessages({ fromChat, ids, toChat, links } = {}, options = {}) {
      const from = fromChat ?? links?.[0]?.chat;
      const rawIds = ids ?? links?.map((l) => Number(l.id?.split(':').pop()));
      const messageIds = (rawIds ?? []).filter(Boolean);
      return call(
        'forwardMessages',
        { from_chat_id: from, chat_id: toChat, message_ids: messageIds },
        options.token
      );
    },
  };
};

export const createTelegramBotLive = ({
  token = null,
  fetchImpl = globalThis.fetch,
  baseUrl = 'https://api.telegram.org',
  // `{ timeoutMs?, retries?, sleep? }` for the outbound time budget.
  timing = null,
} = {}) => {
  const root = baseUrl.replace(/\/+$/, '');
  const call = async (method, body = {}, tokenOverride = null) => {
    const authToken = tokenOverride ?? token ?? liveToken();
    if (!authToken) {
      throw new Error(
        'telegram live API requires TELEGRAM_BOT_TOKEN or an explicit token'
      );
    }
    if (!fetchImpl) {
      throw new Error('telegram live API requires fetch');
    }
    // A long poll waits `timeout` seconds on purpose (R-Z1).
    const wait = Number(body.timeout) > 0 ? body.timeout * 1000 : 0;
    return timedRequest(
      fetchImpl,
      `${root}/bot${authToken}/${method}`,
      {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify(body),
      },
      {
        timeoutMs: DEFAULT_TIMEOUT_MS + wait,
        write: !BOT_READS.test(method),
        ...(timing ?? {}),
      },
      async (res) => {
        const payload = await res.json();
        if (!res.ok || payload.ok === false) {
          throw new Error(
            `telegram ${method}: ${payload.description ?? `HTTP ${res.status}`}`
          );
        }
        return payload.result;
      }
    );
  };

  return {
    async pullMessages({
      offset = undefined,
      limit = 100,
      timeout = 0,
      allowedUpdates = [
        'message',
        'edited_message',
        'channel_post',
        'message_reaction',
      ],
      token: tokenOverride = null,
    } = {}) {
      const result = await call(
        'getUpdates',
        {
          offset,
          limit,
          timeout,
          allowed_updates: allowedUpdates,
        },
        tokenOverride
      );
      const nextOffset =
        result.length > 0
          ? Math.max(...result.map((u) => Number(u.update_id))) + 1
          : (offset ?? null);
      return {
        links: telegramUpdatesToLinks(result),
        nextOffset,
        rawCount: result.length,
      };
    },
    async setTyping({ chat, chatId } = {}, options = {}) {
      const target = chat ?? chatId;
      if (!target) {
        throw new Error('telegram setTyping requires a chat/chatId target');
      }
      return call(
        'sendChatAction',
        { chat_id: target, action: 'typing' },
        options.token
      );
    },
    ...membershipMethods(call),
    async listChats(options = {}) {
      const pulled = await this.pullMessages(options);
      const chats = new Map();
      for (const link of pulled.links) {
        chats.set(link.chat, {
          id: link.chat,
          source: SOURCE,
          lastMessage: link.id,
        });
      }
      return [...chats.values()];
    },
    async post(content, { token: tokenOverride = null } = {}) {
      const chat = content?.chat ?? content?.chatId ?? content?.to;
      if (!chat) {
        throw new Error('telegram live.post requires a chat/chatId target');
      }
      const result = await call(...sendRequest(content, chat), tokenOverride);
      return {
        ok: true,
        messageId: String(result.message_id),
        chat: String(result.chat?.id ?? chat),
      };
    },
    /**
     * Greeting stickers from the named sets. A sticker qualifies when
     * its emoji is a greeting gesture, or when the set is listed with
     * `{all: true}` because the whole pack is greetings. `file_id`s are
     * only valid for the bot that listed them, so they are fetched live
     * rather than stored in the catalogue.
     */
    async listGreetingStickers({
      sets = [],
      token: tokenOverride = null,
    } = {}) {
      const stickers = [];
      const failures = [];
      for (const raw of sets) {
        const entry = typeof raw === 'string' ? { name: raw } : raw;
        try {
          const set = await call(
            'getStickerSet',
            { name: entry.name },
            tokenOverride
          );
          stickers.push(...greetingStickersOfSet(set, entry));
        } catch (err) {
          failures.push({ pack: entry.name, error: err.message });
        }
      }
      return { stickers, failures };
    },
    /**
     * Downloads a file (e.g. a sticker thumbnail) through `getFile`.
     * Server-side only: the download URL contains the bot token.
     */
    async fetchFile(fileId, { token: tokenOverride = null } = {}) {
      const file = await call('getFile', { file_id: fileId }, tokenOverride);
      const authToken = tokenOverride ?? token ?? liveToken();
      const res = await fetchImpl(
        `${root}/file/bot${authToken}/${file.file_path}`
      );
      if (!res.ok) {
        throw new Error(`telegram getFile: HTTP ${res.status}`);
      }
      return {
        bytes: new Uint8Array(await res.arrayBuffer()),
        path: file.file_path,
      };
    },
    ...profileMethods(call),
    ...actionMethods(call),
  };
};

export const telegramSource = {
  name: SOURCE,
  async parseArchive(archive) {
    const chats = archiveChats(parseArchiveObject(archive));
    const out = [];
    const seen = new Set();
    for (const chat of chats) {
      const chatId = String(chat.id ?? chat.name ?? 'unknown');
      for (const msg of chat.messages ?? []) {
        if (msg.type !== 'message') {
          continue;
        }
        const id = String(msg.id);
        const externalId = seen.has(id) ? `${chatId}:${id}` : id;
        seen.add(id);
        out.push(
          buildMessageLink({
            source: SOURCE,
            externalId,
            sender: senderId(msg),
            chat: chatId,
            body: messageText(msg),
            timestamp: messageTimestamp(msg),
            replyTo: msg.reply_to_message_id
              ? String(msg.reply_to_message_id)
              : null,
            chatType: chat.type ?? null,
            chatName: chat.type === 'personal_chat' ? chat.name : null,
            senderName: typeof msg.from === 'string' ? msg.from : null,
            sticker: archiveSticker(msg),
          })
        );
      }
    }
    return out;
  },
  live: createTelegramBotLive(),
};

// The QR code part of the Telegram sign-in (R-Y203): like Telegram Desktop's
// "Log in to Telegram by QR code". The code is drawn in the page as an SVG
// (../qr-code.js) from the `tg://login?token=…` URL the server holds; the
// server renews it when it expires and the page polls for the outcome.

import React, { useEffect, useRef } from 'react';
import { api } from '../dom.js';
import { useT } from '../i18n.js';
import { encodeQr, qrPath } from '../qr-code.js';

const el = React.createElement;

export const QR_POLL_MS = 1500;
const QUIET = 2;

/** The QR code of `text` as an inline SVG (dark modules on white). */
export const QrCode = ({ text }) => {
  const t = useT();
  const { modules, size } = React.useMemo(() => encodeQr(text), [text]);
  const full = size + QUIET * 2;
  return el(
    'svg',
    {
      className: 'tg-qr-code',
      role: 'img',
      'aria-label': t('telegramLogin.qrAlt'),
      'data-qr-version': size,
      viewBox: `0 0 ${full} ${full}`,
      shapeRendering: 'crispEdges',
    },
    [
      el('rect', { key: 'bg', width: full, height: full, fill: '#fff' }),
      el('path', {
        key: 'm',
        d: qrPath(modules, QUIET),
        fill: '#000',
      }),
    ]
  );
};

/** The code with Telegram Desktop's three steps beside it. */
export const QrPanel = ({ url }) => {
  const t = useT();
  return el('div', { className: 'tg-qr', 'data-tg-qr': 'true' }, [
    el('div', { key: 'c', className: 'tg-qr-box' }, el(QrCode, { text: url })),
    el('div', { key: 's', className: 'tg-qr-steps' }, [
      el('h4', { key: 'h' }, t('telegramLogin.qrTitle')),
      el('ol', { key: 'o' }, [
        el('li', { key: '1' }, t('telegramLogin.qrStep1')),
        el('li', { key: '2' }, t('telegramLogin.qrStep2')),
        el('li', { key: '3' }, t('telegramLogin.qrStep3')),
      ]),
      el('p', { key: 'w', className: 'meta' }, t('telegramLogin.qrWaiting')),
    ]),
  ]);
};

/**
 * While `id` is a QR sign-in being waited for, ask the server for its
 * state now and then and hand each answer to `onResult` (which decides
 * whether polling goes on, by changing `id`). Cancels a sign-in left
 * behind when the form goes away.
 */
export const useQrPolling = (id, onResult) => {
  const handler = useRef(onResult);
  handler.current = onResult;
  const live = useRef(null);
  live.current = id;
  useEffect(() => {
    if (!id) {
      return undefined;
    }
    let stopped = false;
    let timer = null;
    const tick = async () => {
      const result = await api.telegramLogin('qr-status', { id });
      if (stopped) {
        return;
      }
      handler.current(result);
      timer = globalThis.setTimeout(tick, QR_POLL_MS);
    };
    timer = globalThis.setTimeout(tick, QR_POLL_MS);
    return () => {
      stopped = true;
      globalThis.clearTimeout(timer);
    };
  }, [id]);
  useEffect(
    () => () => {
      if (live.current) {
        api.telegramLogin('qr-cancel', { id: live.current });
      }
    },
    []
  );
};

// "Find Telegram sessions on this computer" (Telegram -> Enter manually).
//
// People who experiment with Telegram leave their own credentials in many
// repositories: a bot token in one project's `.env`, a GramJS user string
// session saved beside another, an api_id/api_hash trio in a third. This
// panel asks the local server to find them (read-only), groups them by the
// account they belong to, and connects the one the user picks. The browser
// only ever sees kinds, paths and masked hints — never a token or session.

import React, { useRef, useState } from 'react';
import { api } from '../dom.js';
import { useT } from '../i18n.js';
import { Icon } from '../icons.js';
import { RecommendedHeader } from './recommended.js';
import { QrPanel, useQrPolling } from './telegram-qr-login.js';

const el = React.createElement;

// Tell the tutorial (and anyone else listening) that a service just
// connected, so the tour can advance past its "connect a service" step
// no matter how the user connected — a saved session, a phone login, a
// bot token or API keys all fire the same event.
export const announceConnected = () =>
  globalThis.dispatchEvent?.(new CustomEvent('meta-sovereign:connected'));

// A small check mark that means "this credential was confirmed with
// Telegram". It replaces the old text badge; the words live in a tooltip
// (a styled CSS tooltip, with `aria-label` for screen readers) so the row
// stays compact. Shared so every confirmed credential uses the same mark.
export const VerifiedMark = ({ labelKey = 'telegramSessions.verified' }) => {
  const t = useT();
  const label = t(labelKey);
  // `data-tooltip` drives a CSS tooltip (reliable and styled, unlike the
  // native `title`, which is slow to appear and easy to miss); `aria-label`
  // keeps the words available to screen readers. `tabIndex` lets keyboard
  // users surface the tooltip with focus too.
  return el(
    'span',
    {
      className: 'verified-mark',
      role: 'img',
      tabIndex: 0,
      'aria-label': label,
      'data-tooltip': label,
    },
    el(Icon, { name: 'check', size: 14 })
  );
};

// Each entry is one distinct credential (the same token found in ten repos
// is one row). Its TYPE says how connecting works: a bot token, a login by
// saved session, or a login by phone & password.
const TYPE_LABEL = {
  bot: 'telegramSessions.typeBot',
  session: 'telegramSessions.typeSession',
  'user-password': 'telegramSessions.typePassword',
};

// Where the credential was found. The shortest path leads (the finder sorts
// `wheres` by length); the rest hide behind a "+N more" toggle so a widely
// copied token does not flood the row, and expand to the full list on click.
const WhereLine = ({ entry }) => {
  const t = useT();
  const [open, setOpen] = useState(false);
  const wheres = entry.wheres ?? [entry.where];
  const extra = wheres.length - 1;
  const toggle =
    extra > 0
      ? el(
          'button',
          {
            key: 'more',
            type: 'button',
            className: 'meta tg-session-more',
            'aria-expanded': open ? 'true' : 'false',
            onClick: () => setOpen((v) => !v),
          },
          open
            ? t('telegramSessions.less')
            : t('telegramSessions.more').replace('{n}', String(extra))
        )
      : null;
  if (open) {
    return el('span', { className: 'tg-session-where' }, [
      el(
        'ul',
        { key: 'list', className: 'tg-session-where-list' },
        wheres.map((where, index) =>
          el('li', { key: index, className: 'tg-session-where-item' }, where)
        )
      ),
      toggle,
    ]);
  }
  return el('span', { className: 'tg-session-where' }, [
    el('span', { key: 'first' }, wheres[0]),
    toggle ? el('span', { key: 'sp' }, ' ') : null,
    toggle,
  ]);
};

// One labelled `telegramLogin.*` input, shared by the manual login form and
// the finder's inline phone-login so the markup lives in a single place.
const CredentialField = ({
  id,
  type,
  value,
  placeholder,
  dataField,
  onChange,
}) => {
  const t = useT();
  return el('label', { key: id, className: 'col provider-credential-row' }, [
    el('span', { key: 'l' }, t(`telegramLogin.${id}`)),
    el('input', {
      key: 'i',
      type: type ?? 'text',
      value: value ?? '',
      placeholder,
      autoComplete: 'off',
      'data-field': dataField ?? id,
      onChange: (e) => onChange(e.target.value),
    }),
  ]);
};

// The inline sign-in a phone & password login needs: Connect starts it on
// the server (which already holds the api_id/api_hash/phone), then the user
// types the code Telegram sent and, if set, their 2FA password — right here,
// without leaving the list.
const EntryLogin = ({ login, onField, onSubmit, busy }) => {
  const t = useT();
  const field = (id, type) =>
    el(CredentialField, {
      key: id,
      id,
      type,
      value: login[id],
      dataField: `entry-${id}`,
      onChange: (value) => onField(id, value),
    });
  return el('div', { className: 'tg-session-login' }, [
    el(
      'p',
      { key: 'sent', className: 'meta' },
      t(
        login.needs === 'password'
          ? 'telegramLogin.twoFactor'
          : 'telegramLogin.codeSent'
      )
    ),
    login.needs === 'code' ? field('code') : null,
    login.needs === 'password' ? field('password', 'password') : null,
    el(
      'button',
      {
        key: 'go',
        type: 'button',
        className: 'primary',
        'data-action': 'telegram-session-login',
        disabled: Boolean(busy),
        'aria-busy': busy ? 'true' : undefined,
        onClick: onSubmit,
      },
      t(busy ? 'telegramLogin.working' : 'telegramLogin.signIn')
    ),
    login.error
