// The scan dedupes every discovered credential, checks each one is still
// live, resolves user sessions to their phone/@username, and groups them by
// account — so the list shows one connectable entry per real sign-in.
const useFinder = (onConnected) => {
  const [groups, setGroups] = useState(null);
  const [busy, setBusy] = useState('');
  const [error, setError] = useState('');
  const [scanned, setScanned] = useState(false);
  // Phone-logins that have started an inline sign-in: id -> { needs, code,
  // password, error }.
  const [logins, setLogins] = useState({});
  // Entries whose credential is now stored (bot/session): id -> result. Shown
  // as a "Connected" badge so the click is not silent.
  const [connected, setConnected] = useState({});
  const patch = (id, next) =>
    setLogins((all) => ({ ...all, [id]: { ...all[id], ...next } }));

  const find = async () => {
    setBusy('scan');
    setError('');
    setLogins({});
    setConnected({});
    const scan = await api.telegramSessions('scan');
    setBusy('');
    setScanned(true);
    if (scan?.error) {
      setError(scan.error);
      return;
    }
    setGroups(scan.groups ?? []);
  };

  const use = async (id) => {
    setBusy(id);
    setError('');
    const result = await api.telegramSessions('use', { id });
    setBusy('');
    if (result?.error) {
      setError(result.error);
      return;
    }
    // A phone & password login: reveal the inline code/2FA step, keeping
    // the server-side login id to submit the code against.
    if (result.needsLogin) {
      patch(id, {
        needs: result.needs ?? 'code',
        loginId: result.id,
        error: '',
      });
      return;
    }
    // A bot token or saved session: it is now stored. Mark it so the row
    // shows "Connected" instead of leaving the click without any feedback.
    setConnected((all) => ({ ...all, [id]: result }));
    announceConnected();
    await onConnected?.();
  };

  const field = (id, key, value) => patch(id, { [key]: value });

  const submit = async (id) => {
    const login = logins[id] ?? {};
    setBusy(id);
    const action = login.needs === 'password' ? 'password' : 'code';
    const result = await api.telegramLogin(action, {
      id: login.loginId ?? id,
      code: login.code,
      password: login.password,
    });
    setBusy('');
    if (result?.error) {
      patch(id, { error: result.error });
      return;
    }
    if (result.done) {
      setLogins((all) => {
        const next = { ...all };
        delete next[id];
        return next;
      });
      setConnected((all) => ({ ...all, [id]: result }));
      announceConnected();
      await onConnected?.();
      return;
    }
    patch(id, { needs: result.needs ?? 'code', error: '' });
  };

  return {
    groups,
    busy,
    error,
    scanned,
    logins,
    connected,
    find,
    use,
    field,
    submit,
  };
};

// Sign in to a Telegram USER account over MTProto, like konard/telegram-bot:
// api_id + api_hash + phone -> a login code -> an optional 2FA password ->
// a reusable session stored under secret:telegram:*. As in Telegram Desktop
// there is a second way in, by QR code (R-Y203; ./telegram-qr-login.js).
const LoginField = ({ id, type, value, onChange, placeholder }) =>
  el(CredentialField, { id, type, value, placeholder, onChange });

const useTelegramLogin = (onConnected, slot = 1) => {
  const [form, setForm] = useState({
    apiId: '',
    apiHash: '',
    phone: '',
    code: '',
    password: '',
  });
  // start | code | password | qr | done. `mode` is the way in the user
  // chose, like Telegram Desktop's two (R-Y203): phone number or QR code.
  const [needs, setNeeds] = useState('start');
  const [mode, setMode] = useState('phone');
  const [qr, setQr] = useState(null); // { url, expires } while showing a QR
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [account, setAccount] = useState(null);
  const idRef = useRef(null); // the login id returned by `start`
  const set = (key) => (value) => setForm((f) => ({ ...f, [key]: value }));

  const apply = (result) => {
    if (result?.error) {
      setError(result.error);
      return;
    }
    if (result.id) {
      idRef.current = result.id;
    }
    if (result.done) {
      setNeeds('done');
      setAccount(result.account);
      announceConnected();
      onConnected?.();
      return;
    }
    if (result.url) {
      setQr({ url: result.url, expires: result.expires });
      setNeeds('qr');
      return;
    }
    setNeeds(result.needs ?? 'code');
  };

  const run = async (action, body) => {
    setBusy(true);
    setError('');
    const result = await api.telegramLogin(action, body);
    setBusy(false);
    apply(result);
  };

  // The QR code is renewed by the server; a failure ends the wait.
  useQrPolling(needs === 'qr' ? idRef.current : null, (result) => {
    if (result?.error) {
      setError(result.error);
      setNeeds('start');
      setQr(null);
      return;
    }
    apply(result);
  });

  const chooseMode = (next) => {
    if (needs === 'qr' && idRef.current) {
      api.telegramLogin('qr-cancel', { id: idRef.current });
    }
    setMode(next);
    setNeeds('start');
    setQr(null);
    setError('');
  };

  return {
    form,
    set,
    needs,
    mode,
    qr,
    busy,
    error,
    account,
    chooseMode,
    start: () =>
      run('start', {
        apiId: form.apiId,
        apiHash: form.apiHash,
        phone: form.phone,
        // An extra account signs in to its own slot (R-Y198).
        ...(slot > 1 ? { account: slot } : {}),
      }),
    startQr: () =>
      run('qr-start', {
        apiId: form.apiId,
        apiHash: form.apiHash,
        ...(slot > 1 ? { account: slot } : {}),
      }),
    submitCode: () => run('code', { id: idRef.current, code: form.code }),
    submitPassword: () =>
      run('password', { id: idRef.current, password: form.password }),
  };
};

// The fields of the current step: api id/hash always; the phone number and
// code for the phone way in; the 2FA password when asked (either way).
const loginFields = (l) => {
  const field = (id, extra = {}) =>
    el(LoginField, {
      key: id,
      id,
      value: l.form[id],
      onChange: l.set(id),
      ...extra,
    });
  const phone = l.mode === 'phone';
  const waiting = l.needs === 'qr';
  return [
    waiting ? null : field('apiId', { placeholder: '2040' }),
    waiting
      ? null
      : field('apiHash', {
          type: 'password',
          placeholder: '0123456789abcdef…',
        }),
    phone ? field('phone', { placeholder: '+1 555 123 4567' }) : null,
    phone && (l.needs === 'code' || l.needs === 'password')
      ? field('code', { placeholder: '12345' })
      : null,
    l.needs === 'password'
      ? field('password', { type: 'password', placeholder: '••••••••' })
      : null,
  ];
};

const loginAction = (l) => {
  if (l.needs === 'password') {
    return { key: 'telegramLogin.signIn', on: l.submitPassword };
  }
  if (l.mode === 'qr') {
    return l.needs === 'qr'
      ? null
      : { key: 'telegramLogin.qrStart', on: l.startQr };
  }
  return l.needs === 'code'
    ? { key: 'telegramLogin.signIn', on: l.submitCode }
    : { key: 'telegramLogin.sendCode', on: l.start };
};

