// Which Telegram account the page is using, and which requests belong to
// it (R-Y202; learned, never copied: Telegram Desktop switches its whole
// window to the account chosen in the main menu).
//
// The choice is kept per tab in sessionStorage (a new tab starts on
// account 1, as ever). A request for an extra account (2..5) names it in
// `telegramAccount=N` of its query; the server then answers from that
// account's own store and connection. Only the paths in `scopedForExtra`
// belong to an account; the server refuses an extra account on any other
// path, and the page never adds one to them. This module is shared by the
// page and the server, so both agree on that list.

export const ACCOUNT_PARAM = 'telegramAccount';
export const ACCOUNT_HEADER = 'x-telegram-account';
export const ACCOUNT_KEY = 'metaSovereignTelegramAccount';

const MAX_SLOT = 5;

// The account-global Telegram routes: they name an account in their body
// (or list all of them), so an account in the query is refused there.
const GLOBAL_TELEGRAM = /^\/api\/telegram\/accounts(-|$)/;
const ALWAYS_GET = [
  /^\/links(\/[^/]+)?$/,
  /^\/api\/chat\//,
  /^\/api\/media\/history\//,
  /^\/api\/events$/,
  /^\/api\/status$/,
  /^\/api\/contacts$/,
  /^\/api\/typing$/,
  /^\/api\/message\/supports$/,
];
const POSTS = [/^\/api\/send$/, /^\/api\/typing$/, /^\/api\/message\//];

/** Whether a request of this path and method may be for an extra account. */
export const scopedForExtra = (path, method = 'GET') => {
  const verb = String(method).toUpperCase();
  if (path.startsWith('/api/telegram/')) {
    return !GLOBAL_TELEGRAM.test(path);
  }
  if (verb === 'GET') {
    return ALWAYS_GET.some((re) => re.test(path));
  }
  return verb === 'POST' && POSTS.some((re) => re.test(path));
};

const slotOf = (value) => {
  const slot = Number(value);
  return Number.isInteger(slot) && slot >= 1 && slot <= MAX_SLOT ? slot : 1;
};

/** The account this tab uses: 1 unless another was chosen. */
export const activeAccount = (storage = globalThis.sessionStorage) => {
  try {
    return slotOf(storage?.getItem(ACCOUNT_KEY));
  } catch {
    return 1;
  }
};

/** Remember the tab's account (the page then reloads its data). */
export const setActiveAccount = (slot, storage = globalThis.sessionStorage) => {
  try {
    if (slotOf(slot) === 1) {
      storage?.removeItem(ACCOUNT_KEY);
    } else {
      storage?.setItem(ACCOUNT_KEY, String(slotOf(slot)));
    }
  } catch {
    // Storage blocked: the page stays on the account it has.
  }
};

/**
 * `url` (a path or an absolute URL) with the account named in its query,
 * when the tab uses an extra account and the path belongs to one.
 */
export const scopedUrl = (url, method = 'GET', slot = activeAccount()) => {
  if (slot < 2 || typeof url !== 'string') {
    return url;
  }
  let parsed;
  try {
    parsed = new URL(url, 'http://local.invalid');
  } catch {
    return url;
  }
  if (!scopedForExtra(parsed.pathname, method)) {
    return url;
  }
  parsed.searchParams.set(ACCOUNT_PARAM, String(slot));
  const tail = `${parsed.pathname}${parsed.search}${parsed.hash}`;
  return /^[a-z][a-z0-9+.-]*:/i.test(url) ? parsed.toString() : tail;
};

// One header badge reports Online, Reconnecting (yellow), or Offline.
// Local transport and Telegram reconnects share it across every section;
// conversations retain only their actual history/media loading indicators.

import React, { useEffect, useRef, useState } from 'react';
import { api as defaultApi } from './dom.js';
import { useT } from './i18n.js';
import { useBrowserOnline, useServerReconnecting } from './server-transport.js';
import {
  rememberTelegramConnection,
  useConnectionHistory,
} from './connection-prefs.js';

const el = React.createElement;

const EVERY_MS = 10_000;

/** Reachability and sign-in state of the connected Telegram account. */
export const useTelegramReach = (
  api,
  { enabled = true, everyMs = EVERY_MS } = {}
) => {
  const [reach, setReach] = useState({ offline: false, needsLogin: false });
  useEffect(() => {
    if (!enabled || typeof api?.telegramStatus !== 'function') {
      return undefined;
    }
    let cancelled = false;
    const load = () =>
      Promise.resolve(api.telegramStatus())
        .then((status) => {
          if (cancelled) {
            return;
          }
          const connected = Boolean(status?.connected);
          if (connected) {
            rememberTelegramConnection();
          }
          const next = {
            offline: connected && Boolean(status.offline),
            needsLogin: connected && Boolean(status.needsLogin),
            reconnecting:
              connected &&
              Boolean(status.connection) &&
              status.connection !== 'connected',
          };
          setReach((before) =>
            before.offline === next.offline &&
            before.reconnecting === next.reconnecting &&
            before.needsLogin === next.needsLogin
              ? before
              : next
          );
        })
        .catch(() => {});
    load();
    const timer = globalThis.setInterval(load, everyMs);
    return () => {
      cancelled = true;
      globalThis.clearInterval(timer);
    };
  }, [api, enabled, everyMs]);
  return reach;
};

/** What the header badge shows: online, and the reason when it is not. */
export const badgeOf = (online, reach, connection = {}) => {
  if (connection.browserOnline === false) {
    return { online: false, reason: null };
  }
  if (!online) {
    return connection.hadServer
      ? { online: false, reconnecting: true, reason: 'chat.banner.server' }
      : { online: false, reason: null };
  }
  if (reach.needsLogin) {
    return { online: false, reason: 'header.telegramSignIn' };
  }
  if (connection.reconnecting) {
    return {
      online: false,
      reconnecting: true,
      reason: 'chat.banner.server',
    };
  }
  if (reach.offline) {
    return { online: false, reason: 'header.telegramOffline' };
  }
  if (reach.reconnecting) {
    return {
      online: false,
      reconnecting: true,
      reason: 'chat.banner.telegram',
    };
  }
  return { online: true, reason: null };
};

const openTelegramConnection = () =>
  globalThis.dispatchEvent(
    new globalThis.CustomEvent('meta-sovereign:navigate', {
      detail: { view: 'connections', anchor: '#conn-telegram' },
    })
  );

/** Global status; a Telegram sign-in failure links to its connection. */
export const ModeBadge = ({ online, api = defaultApi }) => {
  const t = useT();
  const connectedBefore = useConnectionHistory();
  const hadServer = useRef(false);
  if (online) {
    hadServer.current = true;
  }
  const connection = {
    hadServer: hadServer.current || connectedBefore,
    reconnecting: useServerReconnecting(),
    browserOnline: useBrowserOnline(),
  };
  const badge = badgeOf(
    online,
    useTelegramReach(api, { enabled: Boolean(online) }),
    connection
  );
  if (!badge.reason || badge.reconnecting) {
    return el(
      'span',
      {
        className: `mode-badge ${badge.reconnecting ? 'reconnecting' : badge.online ? 'online' : 'offline'}`,
        role: 'status',
        'aria-live': 'polite',
        title: badge.reason ? t(badge.reason) : undefined,
      },
      badge.reconnecting
        ? t('header.reconnecting')
        : badge.online
          ? t('header.online')
          : t('header.offline')
    );
  }
  return el(
    'button',
    {
      type: 'button',
      className: 'mode-badge offline',
      'data-action': 'telegram-offline',
      title: t(badge.reason),
      'aria-label': `${t('header.offline')}: ${t(badge.reason)}`,
      onClick: openTelegramConnection,
    },
    t('header.offline')
  );
};

import { activeAccount } from './telegram-account-scope.js';

const accounts = new WeakMap();
/** A transport failure cannot log out an account; views reuse its known status. */
export const telegramStatusFor = (api, slot = activeAccount()) => {
  let slots = accounts.get(api);
  if (!slots) {
    slots = new Map();
    accounts.set(api, slots);
  }
  if (!slots.has(slot)) {
    let status = null;
    let pending = null;
    slots.set(slot, {
      snapshot: () => status,
      read: () => {
        pending ??= Promise.resolve()
          .then(() => api.telegramStatus())
          .then(
            (next) => {
              if (next && !next.offline && !next.error) {
                status = next;
              }
              return status;
            },
            () => status
          )
          .finally(() => {
            pending = null;
          });
        return pending;
      },
    });
  }
  return slots.get(slot);
};

// What the Telegram tests of a source and its route share: a fake GramJS
// class by name, and a POST through handleTelegramRoutes → its status.

import { Readable } from 'node:stream';
import { handleTelegramRoutes } from '../../src/server/routes-telegram.js';

export const named = (className) =>
  class {
    constructor(fields = {}) {
      Object.assign(this, fields);
      this.className = className;
    }
  };

export const postRoute = async (route, body, account) => {
  const path = `/api/telegram/${route}`;
  const req = Readable.from([Buffer.from(JSON.stringify(body))]);
  Object.assign(req, {
    method: 'POST',
    url: path,
    headers: { 'content-type': 'application/json', host: '127.0.0.1:8787' },
  });
  const res = {
    setHeader() {},
    writeHead(status) {
      this.status = status;
    },
    end() {},
  };
  await handleTelegramRoutes(req, res, path, {
    telegramAccount: account,
    allowOrigins: [],
  });
  return res.status;
};

