// A stuck request drops the connection and several readers then ask for
// a new one at once: one client must serve them all, and a dropped one
// must really end (GramJS's disconnect() leaves its update loop running,
// which reconnects it). Leftover clients took the server's memory.
test('one Telegram client at a time, and a dropped one is destroyed', async () => {
  const made = [];
  let failNext = false;
  const clientFactory = async () => {
    let release;
    const ready = new Promise((resolve) => (release = resolve));
    const client = {
      destroyed: false,
      release,
      setLogLevel() {},
      async connect() {
        await ready;
        if (failNext) {
          failNext = false;
          throw new Error('network down');
        }
      },
      async getMe() {
        return ME;
      },
      async destroy() {
        client.destroyed = true;
      },
    };
    made.push(client);
    return client;
  };
  const opened = [];
  const connection = createUserConnection({
    clientFactory,
    dialogLimit: 10,
    now: () => 0,
    onOpen: (client) => opened.push(client),
  });
  const creds = { apiId: '1', apiHash: 'h', session: 's' };
  const settle = () =>
    new Promise((resolve) => globalThis.setTimeout(resolve, 0));

  const three = [1, 2, 3].map(() => connection.open(creds));
  await settle();
  assert.equal(made.length, 1, 'callers share the open');
  made[0].release();
  const [a, b, c] = await Promise.all(three);
  assert.equal(a, b);
  assert.equal(b, c);
  assert.deepEqual(opened, [made[0]]);

  await connection.disconnect();
  assert.equal(made[0].destroyed, true, 'the dropped client is destroyed');

  // Dropped while opening: that client ends too, the next open is fresh.
  const late = connection.open(creds);
  await settle();
  await connection.disconnect();
  made[1].release();
  await assert.rejects(late, { code: 'telegram-reconnect' });
  assert.equal(made[1].destroyed, true);

  // A client that cannot connect is not left behind either.
  failNext = true;
  const failing = connection.open(creds);
  await settle();
  made[2].release();
  await assert.rejects(failing, /network down/);
  assert.equal(made[2].destroyed, true);

  const again = connection.open(creds);
  await settle();
  made[3].release();
  assert.equal((await again).client, made[3]);
  assert.equal(made.length, 4);
  assert.deepEqual(opened, [made[0], made[3]]);
});

test('Telegram asking to wait is not an error; out of reach for long is Offline (R-Y96)', async () => {
  const store = createMemoryStore();
  await seed(store);
  const client = fakeClient();
  let clock = Date.parse('2026-10-22T00:00:00Z');
  const events = [];
  const account = accountWith(store, client, {
    now: () => clock,
    log: (e) => events.push(e),
  });
  const getDialogs = client.getDialogs.bind(client);
  // As the queue turns a request down while Telegram asks to wait.
  let failure = Object.assign(new Error('Telegram asked to wait'), {
    code: 'flood-wait',
    retryAfter: 21,
  });
  client.getDialogs = async () => {
    throw failure;
  };
  await account.sync({ full: true });
  let status = await account.status();
  assert.equal(status.error, null, 'a wait is not shown');
  assert.equal(status.offline, false);
  assert.ok(events.some((e) => e.event === 'telegram_sync_waits'));
  assert.equal(client.calls.disconnect ?? 0, 0, 'the connection is kept');

  // The network is gone: still Online for a minute, then Offline.
  failure = new Error('connect ECONNREFUSED 149.154.167.50:443');
  await account.sync({ full: true });
  status = await account.status();
  assert.equal(status.offline, false, 'not yet');
  clock += 30_000;
  await account.sync({ full: true });
  assert.equal((await account.status()).offline, false, 'still not');
  clock += 31_000;
  status = await account.status();
  assert.equal(status.offline, true, 'a minute out of reach');
  assert.equal(status.needsLogin, false);

  // Back: Online again at once.
  client.getDialogs = getDialogs;
  await account.sync({ full: true });
  status = await account.status();
  assert.equal(status.offline, false);
  assert.equal(status.unreachableSince, null);

  // A session Telegram ended asks to sign in again.
  failure = Object.assign(new Error('AUTH_KEY_UNREGISTERED'), {
    errorMessage: 'AUTH_KEY_UNREGISTERED',
  });
  client.getDialogs = async () => {
    throw failure;
  };
  await account.sync({ full: true });
  assert.equal((await account.status()).needsLogin, true);
});

// More than one Telegram account (R-Y198): the single account keeps its
// keys and is never written to; an extra account lives under `@N` keys,
// is isolated from account 1, logs out without touching anything else, and
// is picked by the route's `account` field. Memory stores and fake
// clients only; nothing reaches a network.

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { Readable } from 'node:stream';
import os from 'node:os';
import path from 'node:path';
