test("GramJS gets each download's size as it reads it", async (t) => {
  // GramJS picks the part size by `fileSize.lesser(…)`: a plain number
  // throws, and no photo, sticker or file downloads. We replicate the
  // bigint-like interface locally so the test runs in Deno (which rejects
  // bare `import('teleproto')` in dynamic position) without weakening the
  // check: .lesser() still throws when fileSize is a plain number.
  const bigInt = (n) => {
    const v = BigInt(String(n));
    return { lesser: (o) => v < BigInt(String(o)) };
  };
  const helpers = {
    returnBigInt: bigInt,
    readBigIntFromBuffer: () => bigInt(1),
  };
  // Exact copy of GramJS's getAppropriatedPartSize (Utils.js).
  const getAppropriatedPartSize = (fileSize) =>
    fileSize.lesser(104857600) ? 128 : fileSize.lesser(786432000) ? 256 : 512;
  const dir = await mkdtemp(path.join(os.tmpdir(), 'ms-media-'));
  t.after(() => rm(dir, { recursive: true, force: true }));
  const store = createMemoryStore();
  const sticker = {
    className: 'MessageMediaDocument',
    document: {
      id: '7',
      accessHash: '8',
      dcId: 2,
      mimeType: 'image/webp',
      size: 30_000,
      attributes: [{ className: 'DocumentAttributeSticker', alt: '🙂' }],
    },
  };
  await store.put(message('-1007', 5, { raw: { id: 5, media: sticker } }));
  const sizes = [];
  const client = async () => ({
    async downloadFile(_location, params) {
      sizes.push(getAppropriatedPartSize(params.fileSize));
      return Buffer.from('webp');
    },
  });
  const fake = await importer();
  const options = {
    store,
    dir,
    queue: { run: (_key, _priority, task) => task() },
    client,
    importer: async () => ({ ...fake, helpers }),
  };
  const picture = await createMediaReader(options).read({
    chat: '-1007',
    id: 5,
  });
  assert.equal(picture.buffer.toString(), 'webp');
  assert.equal(picture.mimeType, 'image/webp');
  const file = await createFileReader({
    ...options,
    dir: path.join(dir, 'files'),
  }).read({ chat: '-1007', id: 5 });
  assert.equal(file.buffer.toString(), 'webp');
  assert.deepEqual(sizes, [128, 128]);
});

test('an expired file reference reads the message again, once', async (t) => {
  const dir = await mkdtemp(path.join(os.tmpdir(), 'ms-media-'));
  t.after(() => rm(dir, { recursive: true, force: true }));
  const store = createMemoryStore();
  await store.put(message('42', 4, { raw: { id: 4, media: PHOTO } }));
  let tries = 0;
  const refreshed = [];
  const reader = createMediaReader({
    store,
    dir,
    importer,
    queue: { run: (_key, _priority, task) => task() },
    refresh: async (request) => refreshed.push(request),
    client: async () => ({
      async downloadFile() {
        tries += 1;
        if (tries === 1) {
          throw Object.assign(new Error('FILE_REFERENCE_EXPIRED'), {
            errorMessage: 'FILE_REFERENCE_EXPIRED',
          });
        }
        return Buffer.from('ok');
      },
    }),
  });
