    current: { id: '99', until: 1_700_050_000 },
    defaults: [{ id: '11' }, { id: '12', until: 1_700_100_000 }],
    recent: [],
  });
  assert.deepEqual(
    log.map((r) => [r.className, r.hash]),
    [
      ['account.GetDefaultEmojiStatuses', 0n],
      ['account.GetRecentEmojiStatuses', 0n],
    ]
  );
});

