const getRoute = async (query, account) => {
  const path = '/api/telegram/ephemeral';
  const req = Readable.from([]);
  Object.assign(req, {
    method: 'GET',
    url: `${path}${query}`,
    headers: { host: '127.0.0.1:8787' },
  });
  const res = {
    headers: {},
    setHeader() {},
    writeHead(status) {
      this.status = status;
    },
    end(text) {
      this.text = text;
    },
  };
