    (await checkFolder(path.join(link, 'sub'), opts)).code,
    'inside-store'
  );
  assert.deepEqual(await checkFolder(path.join(home, 'out'), opts), {
    ok: true,
    folder: path.join(home, 'out'),
  });
  assert.equal(
    (await checkFolder('~/exports', opts)).folder,
    path.join(home, 'exports')
  );
});

