      ['2', 1],
    ]
  );
  assert.equal(unreadChats(chatsInFolder(all, folder, people)), 1);
  const fallback = [{ key: 'all' }];
  assert.equal(folderTabs([], { all, people, fallback }), fallback);
  assert.equal(
    folderTabs([{ id: 0, all: true }], { all, people, fallback }),
