    parseFormatted('<u>**x**</u>')
      .entities.map((e) => e.type)
      .sort(),
    ['bold', 'underline']
  );
  for (const typed of ['<u> x</u>', '<u></u>', '<u>open', 'a <b>b</b>']) {
    assert.equal(parseFormatted(typed).text, typed, typed);
  }
});

