test('the queue runs the most urgent request first, one at a time', async () => {
  const queue = createFetchQueue({ pace: NO_PACE });
  const order = [];
  let release;
  const gate = new Promise((resolve) => {
    release = resolve;
  });
  const first = queue.run('a', 'background', async () => {
    await gate;
    order.push('a');
  });
  const later = [
    queue.run('b', 'background', async () => order.push('b')),
    queue.run('c', 'prefetch', async () => order.push('c')),
    queue.run('d', 'view', async () => order.push('d')),
  ];
  // The same key asked again is one request, at the higher priority.
  const same = queue.run('b', 'list', async () => order.push('b2'));
  assert.equal(queue.pending('prefetch'), 3);
  release();
  await Promise.all([first, ...later, same]);
  assert.deepEqual(order, ['a', 'd', 'b', 'c']);
});

// A clock and timers the test moves by hand.
const fakeTime = () => {
  let clock = 0;
  const timers = [];
  return {
    now: () => clock,
    setTimer: (fn, ms) => {
      const timer = { at: clock + ms, fn };
      timers.push(timer);
      return timer;
    },
    clearTimer: (timer) => {
      const at = timers.indexOf(timer);
      if (at >= 0) {
        timers.splice(at, 1);
      }
    },
    // Move the clock on, firing what falls due.
    async advance(ms) {
      clock += ms;
      for (const timer of [...timers].filter((t) => t.at <= clock)) {
        timers.splice(timers.indexOf(timer), 1);
        timer.fn();
      }
      await new Promise((resolve) => setTimeout(resolve, 0));
    },
  };
};

test('the queue paces requests and gives background work only a quiet minute (R-Y34)', async () => {
  const time = fakeTime();
  const queue = createFetchQueue({
    now: time.now,
    setTimer: time.setTimer,
    clearTimer: time.clearTimer,
    pace: {
      view: { gapMs: 100, perMinute: 60 },
      list: { gapMs: 100, perMinute: 60 },
      prefetch: { gapMs: 1000, perMinute: 3 },
      background: { gapMs: 3000, perMinute: 2 },
    },
  });
  const done = [];
  const ask = (key, priority) =>
    queue.run(key, priority, async () => done.push(key));
  ask('b1', 'background');
  ask('b2', 'background');
  ask('b3', 'background');
  await time.advance(0);
  assert.deepEqual(done, ['b1'], 'the first goes at once');
  await time.advance(2999);
  assert.deepEqual(done, ['b1'], 'the next waits for its gap');
  await time.advance(1);
  assert.deepEqual(done, ['b1', 'b2']);
  // Two background requests this minute: the third waits for the minute.
  await time.advance(3000);
  assert.deepEqual(done, ['b1', 'b2']);
  // What the user looks at goes first, after a short gap.
  ask('v1', 'view');
  await time.advance(0);
  assert.deepEqual(done, ['b1', 'b2', 'v1']);
  await time.advance(60_000);
  assert.deepEqual(done, ['b1', 'b2', 'v1', 'b3']);
  assert.equal(queue.state().waiting, 0);
});

test('a request asked by one in flight runs as part of it, not after it', async () => {
  const time = fakeTime();
  const stuckJobs = [];
  const queue = createFetchQueue({
    now: time.now,
    setTimer: time.setTimer,
    clearTimer: time.clearTimer,
    pace: NO_PACE,
    onStuck: (job) => stuckJobs.push(job.method),
  });
  const order = [];
  // A refresh whose peer must be looked up first (the dialogs).
  const refresh = queue.run('refresh:42:5', 'prefetch', async () => {
    order.push('refresh');
    const dialogs = await queue.run('dialogs:lookup', 'list', async () => {
      order.push('lookup');
      return ['42'];
    });
    return dialogs.length;
  });
  await time.advance(0);
  assert.equal(await refresh, 1);
  assert.deepEqual(order, ['refresh', 'lookup']);
  assert.deepEqual(stuckJobs, []);
  // Once it is answered, a request is queued as ever.
  const later = queue.run('dialogs:lookup', 'list', async () => 'queued');
  await time.advance(0);
  assert.equal(await later, 'queued');
});

test('a request made while the connection is down waits for it (R-Y75)', async () => {
  const time = fakeTime();
  const queue = createFetchQueue({
    now: time.now,
    setTimer: time.setTimer,
    clearTimer: time.clearTimer,
    pace: NO_PACE,
  });
  let tries = 0;
  const history = queue.run('history:42', 'view', async () => {
    tries += 1;
    if (tries < 3) {
      throw new Error(
        'Cannot send requests while disconnected. Please reconnect.'
      );
    }
    return 'messages';
  });
  await time.advance(0);
  assert.equal(tries, 1);
  await time.advance(1000);
  assert.equal(tries, 2);
  await time.advance(2000);
  assert.equal(await history, 'messages');
  // Down for good: said after the last wait, not forever.
  const gone = queue.run('history:43', 'view', async () => {
    throw new Error(
      'Cannot send requests while disconnected. Please reconnect.'
    );
  });
  gone.catch(() => {});
  for (const ms of [0, 1000, 2000, 4000, 8000]) {
    await time.advance(ms);
  }
  await assert.rejects(gone, /while disconnected/);
});

test('a request Telegram never answers is given up and the queue moves on', async () => {
  const time = fakeTime();
  const stuck = [];
  const logged = [];
  const queue = createFetchQueue({
    now: time.now,
    setTimer: time.setTimer,
    clearTimer: time.clearTimer,
    pace: NO_PACE,
    stuck: { file: 5000, other: 1000 },
    onStuck: (job) => stuck.push(job.key),
    log: (entry) => logged.push(entry.event),
  });
  const never = () => new Promise(() => {});
  const lost = queue.run('chat-info:42', 'view', never);
  const file = queue.run('file:7', 'list', never);
  const next = queue.run('avatar:42:small', 'list', async () => 'picture');
  const failed = [];
  lost.catch((error) => failed.push(error.code));
  file.catch((error) => failed.push(error.code));
  await time.advance(999);
  assert.deepEqual(stuck, []);
  await time.advance(1);
  assert.deepEqual(failed, ['telegram-stuck']);
  assert.deepEqual(stuck, ['chat-info:42']);
  assert.deepEqual(logged, ['telegram_request_stuck']);
  // A file is given longer; then what waited behind it goes.
  await time.advance(4999);
  assert.equal(queue.state().waiting, 1);
  await time.advance(1);
  assert.equal(await next, 'picture');
  assert.deepEqual(stuck, ['chat-info:42', 'file:7']);
  assert.equal(queue.state().waiting, 0);
});

test("Telegram's wait holds its method, briefly everything, then slows down (R-Y34)", async () => {
  const time = fakeTime();
  const holds = [];
  const queue = createFetchQueue({
    now: time.now,
    setTimer: time.setTimer,
    clearTimer: time.clearTimer,
    pace: NO_PACE,
    onHold: (saved) => holds.push(saved),
  });
  await assert.rejects(
    queue.run('messages:42', 'view', async () => {
      throw Object.assign(new Error('FLOOD_WAIT_120'), {
        errorMessage: 'FLOOD_WAIT_120',
      });
    })
  );
  assert.equal(queue.heldFor('messages'), 120_000);
  assert.equal(queue.heldFor(), 30_000, 'everything pauses for 30 s');
  // Waiting work is turned down at once, with how long to wait.
  await assert.rejects(
    queue.run('dialogs:x', 'background', async () => 'no'),
    (error) => error.code === 'flood-wait' && error.retryAfter === 30
  );
  await time.advance(31_000);
  assert.equal(await queue.run('dialogs:x', 'list', async () => 'ok'), 'ok');
  await assert.rejects(
    queue.run('messages:42', 'view', async () => 'no'),
    (error) => error.code === 'flood-wait' && error.retryAfter === 89
  );
  // Saved, so a restart keeps waiting; an hour of slower pace after.
  const saved = holds.at(-1);
  assert.equal(saved.methods.messages, 120_000);
  assert.ok(saved.slowUntil >= 120_000 + 3_600_000);
  const restarted = createFetchQueue({ now: time.now, pace: NO_PACE });
  restarted.hold(saved);
  assert.equal(restarted.heldFor('messages'), 89_000);
  // A wait seen anywhere else (a send, GramJS's own lookups) counts too.
  assert.equal(
    restarted.note(new Error('A wait of 7 seconds is required (caused by X)')),
    7
  );
  assert.equal(floodSeconds({ seconds: 3 }), 3);
});

