describe('telegram bot live connector', () => {
  it('pulls updates, sends messages, and syncs bot profile fields', async () => {
    const calls = [];
    const fetchImpl = async (url, init) => {
      const body = JSON.parse(init.body);
      calls.push({ url, body });
      if (url.endsWith('/getUpdates')) {
        return jsonResponse({
          ok: true,
          result: [
            {
              update_id: 41,
              message: {
                message_id: 7,
                from: { id: 9, username: 'alice' },
                chat: { id: 44, title: 'Room' },
                date: 1777629600,
                text: 'hello from telegram',
              },
            },
          ],
        });
      }
      if (url.endsWith('/sendMessage')) {
        return jsonResponse({
          ok: true,
          result: {
            message_id: 8,
            chat: { id: body.chat_id },
            date: 1777629601,
            text: body.text,
          },
        });
      }
      return jsonResponse({ ok: true, result: true });
    };

    const live = createTelegramBotLive({
      token: '123:test',
      fetchImpl,
      baseUrl: 'https://telegram.test',
    });

    const pulled = await live.pullMessages({ offset: 40, limit: 10 });
    expect(pulled.nextOffset).toBe(42);
    expect(pulled.links[0].id).toBe('msg:telegram:7');
    expect(pulled.links[0].sender).toBe('9');
    expect(pulled.links[0].body).toBe('hello from telegram');

    const sent = await live.post({ chat: 44, text: 'queued reply' });
    expect(sent.messageId).toBe('8');
    expect(calls[1].body.chat_id).toBe(44);

    const profile = await live.syncProfile({
      name: 'Meta Sovereign',
      bio: 'Local-first personal CRM',
    });
    expect(profile.length).toBe(2);
    expect(calls[2].url.endsWith('/setMyName')).toBe(true);
    expect(calls[3].url.endsWith('/setMyDescription')).toBe(true);
  });

  it('imports pulled updates into the store with connector handled stamps', async () => {
    const store = createMemoryStore();
    await store.put({
      id: 'secret:telegram:bot-token',
      tokens: ['secret', 'telegram'],
      value: 'stored-token',
    });
    let seenToken = null;
    const live = {
      async pullMessages(options) {
        seenToken = options.token;
        return {
          nextOffset: 12,
          links: [
            {
              id: 'msg:telegram:11',
              tokens: ['message', 'telegram', '11'],
              source: 'telegram',
              sender: 'alice',
              chat: 'direct:alice',
              body: 'live hello',
            },
          ],
        };
      },
    };

    const result = await pullLiveInto(store, 'telegram', { live });
    const imported = await store.get('msg:telegram:11');

    expect(seenToken).toBe('stored-token');
    expect(result.imported).toBe(1);
    expect(result.nextOffset).toBe(12);
    expect(imported.handled.by).toBe('source:telegram:live');
    expect(Boolean(imported.handledBy['source:telegram:live'])).toBe(true);
  });
});

describe('source-pull handler', () => {
  it('runs live imports from a datastore command link once', async () => {
    const store = createMemoryStore();
    const bus = createHandlerBus(store);
    let pulls = 0;
    const pullLive = async (targetStore, source) => {
      pulls += 1;
      await targetStore.put(
        stampSourceLink(
          {
            id: `msg:${source}:live-1`,
            tokens: ['message', source, 'live-1'],
            source,
            sender: 'alice',
            chat: 'direct:alice',
            body: 'from handler',
          },
          source
        )
      );
      return { source, imported: 1, nextOffset: 2 };
    };
    const { selector, run } = sourcePullHandler({ pullLive });
    bus.register('source-pull', selector, run);

    await store.put({
      id: 'source-pull:telegram:test',
      tokens: ['source-pull', 'telegram'],
      source: 'telegram',
      offset: 1,
    });
    for (let i = 0; i < 6; i += 1) {
      await flush();
    }

    expect(pulls).toBe(1);
    const command = await store.get('source-pull:telegram:test');
    expect(command.status).toBe('done');
    expect(command.imported).toBe(1);
    expect(Boolean(command.handledBy['source-pull'])).toBe(true);

    await store.put(command);
    for (let i = 0; i < 4; i += 1) {
      await flush();
    }
    expect(pulls).toBe(1);
  });
});

// The Telegram user-login HTTP flow: start (send code) -> code -> optional
// 2FA password -> the session saved under secret:telegram:*. A fake MTProto
// stands in for GramJS, so no network or real dependency is touched. The
// routes are POST-only from the app, like the other auto-import routes.

import assert from 'node:assert/strict';
import { test } from 'node:test';
import path from 'node:path';
import os from 'node:os';
import { promises as fs } from 'node:fs';

import { startServer } from '../src/server/index.js';
import { createTelegramMtproto } from '../src/web/../sources/telegram-mtproto.js';
import { createTelegramCreds } from '../src/web/../sources/auto-import/telegram-creds.js';
import { readStoreText } from './util-store-text.js';
import { post, postJson } from './util-http.js';

const tmpDir = () => fs.mkdtemp(path.join(os.tmpdir(), 'ms-tg-login-'));

// A fake GramJS client that needs a 2FA password.
const fakeClient = () => ({
  async connect() {},
  async disconnect() {},
  async start({ phoneNumber, phoneCode, password }) {
    await phoneNumber();
    await phoneCode();
    await password();
  },
  session: { save: () => 'SESSION_FROM_LOGIN' },
  getMe: async () => ({ id: 99, username: 'konard' }),
});

// Start a server with the fake MTProto wired in, plus any extra options.
const startTgServer = async (storeDir, extra = {}) => {
  const handle = await startServer({
    port: 0,
    storeDir,
    enableSync: false,
    autoImportLauncher: async () => ({ close: async () => {} }),
    telegramMtproto: createTelegramMtproto({
      clientFactory: async () => fakeClient(),
    }),
    ...extra,
  });
  return { handle, storeDir, base: `http://127.0.0.1:${handle.port}` };
};

const serve = async () => startTgServer(await tmpDir());

// Submit the code Telegram "sent", then the 2FA password — the shared tail
// of every finished sign-in — and return the final reply.
const finishLogin = async (base, id) => {
  const afterCode = await postJson(
    base,
    '/api/auto-import/telegram/login/code',
    {
      id,
      code: '12345',
    }
  );
  assert.equal(afterCode.needs, 'password');
  return postJson(base, '/api/auto-import/telegram/login/password', {
    id,
    password: 's3cret',
  });
};

test('telegram login: start -> code -> 2FA password -> saved session', async () => {
  const { handle, base, storeDir } = await serve();
  try {
    // Foreign origins are rejected, like the other auto-import routes.
    const foreign = await post(
      base,
      '/api/auto-import/telegram/login/start',
      { apiId: 1, apiHash: 'h', phone: '+1555' },
      { origin: 'https://evil.example' }
    );
    assert.equal(foreign.status, 403);

    const started = await postJson(
      base,
      '/api/auto-import/telegram/login/start',
      { apiId: 2040, apiHash: 'abcdef', phone: '+15551234567' }
    );
