    }
  };

const Api = {
  contacts: {
    Block: named('Block'),
    Unblock: named('Unblock'),
    AddContact: named('AddContact'),
    DeleteContacts: named('DeleteContacts'),
    AcceptContact: named('AcceptContact'),
  },
  messages: {
    Report: named('Report'),
    ReportSpam: named('ReportSpam'),
    GetPeerSettings: named('GetPeerSettings'),
    HidePeerSettingsBar: named('HidePeerSettingsBar'),
  },
  InputUser: named('InputUser'),
};

const make = (answer) => {
  const log = [];
  const client = {
    invoke: async (request) => {
      log.push(request);
      const next = answer(request);
      if (next instanceof Error) {
        throw next;
      }
      return next;
    },
  };
  const actions = createPeerActions(
    {
      importer: async () => ({
        Api,
        helpers: { returnBigInt: (v) => BigInt(v) },
      }),
      connection: {
        withPeer: async (_c, chat, use) =>
          use({ chat, userId: BigInt(chat), accessHash: 77n }),
      },
    },
    { userClient: async () => client }
  );
  return { actions, log };
};

