  assert.equal(applied.length, 1);
  const back = await actions.votePoll({ chat: '-1001234', id: 7, options: [] });
  assert.equal(back.retracted, true);
  assert.deepEqual(asked[1].options, []);
  // No client (a bot, not connected): nothing is asked.
