test('Accept sends g_b; Decline discards as a hangup with the duration', async () => {
  const { actions, env, log } = await make({
    other: (r) =>
      r.className === 'AcceptCall'
        ? { phoneCall: { className: 'PhoneCallWaiting', id: 88n } }
