  });
  await env.phoneCalls.handle(
    { invoke: async () => true },
    updateEffect({
      className: 'UpdatePhoneCall',
      phoneCall: {
        className: 'PhoneCallRequested',
        id: 88n,
        accessHash: 99n,
        date: Math.floor(NOW / 1000),
