  }
  await stickers.stickerPanel();
  await stickers.savedGifs();
  assert.equal(count(log, 'GetFavedStickers'), 2, 'the panel asked again');
  assert.equal(count(log, 'GetSavedGifs'), 2, 'the GIFs asked again');
