  assert.equal(got.ok, true);
  assert.deepEqual(got.items, [
    {
      id: 3,
      text: 't3',
      entities: [{ className: 'MessageEntityBold', offset: 0, length: 2 }],
    },
    {
      id: 4,
      text: 't4',
      entities: [{ className: 'MessageEntityBold', offset: 0, length: 2 }],
    },
  ]);
  assert.deepEqual(
    [log[0].peer, log[0].id, log[0].toLang],
    [{ chat: '-5' }, [3, 4], 'de']
  );
});

